window.LAW_CATALOG.records.push(...[{"articles":[],"attachment_required":false,"attachments":[{"name":"宜蘭縣建築物造價估算標準修正條文對照表.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4028&id=FL051000&type=LAW"},{"name":"宜蘭縣建築物造價估算標準修正總說明.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4027&id=FL051000&type=LAW"},{"name":"修正前附表.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4029&id=FL051000&type=LAW"},{"name":"修正後附表.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4030&id=FL051000&type=LAW"},{"name":"宜蘭縣建築物造價估算標準條文.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4031&id=FL051000&type=LAW"},{"name":"附表.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4033&id=FL051000&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"第一條\n宜蘭縣政府(以下簡稱本府)為統一建築物造價估算基準，依宜蘭縣建築管理自治條例第二十三條規定訂定本標準。\n第二條\n宜蘭縣各種構造建築物之造價估算基準如附表。\n前項附表，由本府依行政院主計總處公告之「臺灣地區消費者物價總指數」變動情形，每二年檢討一次並公告之。\n第三條\n依本標準所公告之各種構造建築物之造價，係作為本府收取建築執照規費及罰鍰之核算依據。\n第四條\n依本標準所公告之各種構造建築物之造價，不包含水電及其設備部分；未公告之雜項工作物造價，由建築師覈實估算之。\n第五條\n本標準自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:FL051000","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"修正日期":"民國 112 年 06 月 07 日","全文檔案":"宜蘭縣建築物造價估算標準條文.odt","公發布日":"民國 98 年 11 月 04 日","圖表附件":"附表.odt","法規名稱":"宜蘭縣建築物造價估算標準","法規體系":"建設","發文字號":"府秘法字第1120103110B號令","立法理由":"宜蘭縣建築物造價估算標準修正條文對照表.odt 宜蘭縣建築物造價估算標準修正總說明.odt 修正前附表.odt 修正後附表.odt"},"promulgation_date":"2009-11-04","revision_date":"2023-06-07","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=FL051000","status":"unknown","title":"宜蘭縣建築物造價估算標準","last_checked_at":"2026-10-06T17:31:11+08:00","last_success_at":"2026-10-06T17:31:11+08:00","verification_status":"fetched","content_hash":"598a0be5513f3d55981b3eb2a2984334c7b5aeb223cff89ee37192e23875606c","history":[{"observed_at":"2026-10-06T17:31:11+08:00","content_hash":"598a0be5513f3d55981b3eb2a2984334c7b5aeb223cff89ee37192e23875606c","change_kind":"initial","revision_date":"2023-06-07"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4028&id=FL051000&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4027&id=FL051000&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4029&id=FL051000&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4030&id=FL051000&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4031&id=FL051000&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4033&id=FL051000&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"宜蘭縣政府","category":"建築管理相關","content":"第 1 條\n本辦法依建築法第一百零二條之一第二項規定訂定之。\n第 2 條\n建築物依規定應附建防空避難設備，符合下列各款情形之一者，起造人得\n申請繳納代金，免予附建：\n一、防空避難設備面積未達一百平方公尺者。\n二、建築基地地面以下為流砂、湧泉、溫泉或岩石層，開挖地下室確有困\n難者。\n三、建築物辦理增建或變更使用，需增設防空避難設備者。\n四、其他因特殊情形施工困難者。\n第 3 條\n建築物依規定應附設停車空間，而建築基地位於都市計畫停車場公共設施\n用地周圍八百公尺半徑範圍內，符合下列各款情形之一者，起造人得申請\n繳納代金，免予附建：\n一、建築基地面積在三百五十平方公尺以下，且寬度或深度任一邊未達十\n五公尺者；基地應留設騎樓者，其寬度、深度及面積以扣除騎樓深度\n、寬度及面積為準。\n二、依都市計畫法令或建築技術規則規定應附設之停車空間在六輛以下者\n。\n三、建築物因增建、改建或變更用途需增設停車空間者。\n四、建築基地因都市計畫相關規定，車輛無法通行者。\n五、建築基地臨接之道路坡度超過一比六者。\n六、其他經認定不宜設置者。\n第 4 條\n原有建築物於實施容積管制後申請建築，符合第二條第三款或第三條第三\n款規定情形之一者，申請繳納代金之防空避難設備或停車空間所占樓地板\n面積，應計入容積樓地板面積並依現行土地使用分區管制要點相關規定檢\n討。\n第 5 條\n依第二條或第三條規定申請繳納代金之計算公式如下：\n一、防空避難設備：\n代金總額＝【法定工程造價（新臺幣元／平方公尺）＋建築執照掛號\n日之建築基地當期公告現值（新臺幣元／平方公尺）ｘ建築基地面積\n（平方公尺）÷建築物總樓地板面積（平方公尺）】ｘ防空避難設備\n面積（平方公尺）。\n二、停車空間：\n代金總額＝【法定工程造價（新臺幣元／平方公尺）＋建築執照掛號\n日之建築基地當期公告現值（新臺幣元／平方公尺）ｘ建築基地面積\n（平方公尺）÷建築物總樓地板面積（平方公尺）】ｘ二十五ｘ車位\n數。\n三、防空避難設備兼停車空間：\n代金總額＝防空避難設備代金總額＋停車空間代金總額；防空避難設\n備及停車空間代金總額比照前二款規定核算。\n第 6 條\n申請繳納代金，應於領取使用執照或變更使用執照時，向宜蘭縣政府（以\n下簡稱本府）繳納。\n第 7 條\n申請人繳交之代金，應納入本府停車場作業基金統籌應用於集中興建或購\n置防空避難設備或停車空間等相關用途。但基金未成立前暫納入本府公務\n預算，並專款專用。\n第 8 條\n依前條興建完成或購置之停車空間，其所有權登記為宜蘭縣所有，並由本\n府核定管理機關負責或委託管理維護。\n第 9 條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:FL034154","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"修正日期":"民國 97 年 03 月 10 日","公發布日":"民國 92 年 05 月 27 日","法規名稱":"宜蘭縣建築物附建防空避難設備或停車空間繳納代金及管理使用辦法","法規體系":"建設","發文字號":"府秘法字第0970031953B號"},"promulgation_date":"2003-05-27","revision_date":"2008-03-10","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=FL034154","status":"unknown","title":"宜蘭縣建築物附建防空避難設備或停車空間繳納代金及管理使用辦法","last_checked_at":"2026-10-06T17:31:20+08:00","last_success_at":"2026-10-06T17:31:20+08:00","verification_status":"fetched","content_hash":"352fbf4b94484823a4476c2b5207bc5f0378ee7ee6902193aa5b399a2e93412c","history":[{"observed_at":"2026-10-06T17:31:20+08:00","content_hash":"352fbf4b94484823a4476c2b5207bc5f0378ee7ee6902193aa5b399a2e93412c","change_kind":"initial","revision_date":"2008-03-10"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"(1140806)宜蘭縣建築管理自治條例部分條文修正總說明及修正對照表.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=5191&id=FL023420&type=LAW"},{"name":"(1140806)宜蘭縣建築管理自治條例.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=5192&id=FL023420&type=LAW"},{"name":"附表.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3886&id=FL023420&type=LAW"},{"name":"附表.DOC","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=7&id=FL023420&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"第 一 章 總則\n第 一 條\n本自治條例依建築法（以下簡稱本法）第一百零一條規定制定之。\n第 二 條\n本法第七十條所稱建築物主要設備，係指下列各款：\n一、消防設備。\n二、避雷設備。\n三、污物、污水或其他廢棄物處理設備。\n四、昇降設備。\n五、防空避難設備。\n六、機械式停車設備。\n七、機械通風設備。\n第 三 條\n本自治條例所稱道路，係指依都市計畫法或其他法律公布之道路或合於本\n自治條例規定之現有巷道。\n第 二 章 建築基地及界線\n第 四 條\n建築基地面臨道路或廣場者，得申請指示（定）建築線。但建築基地鄰接\n高速公路及其交流道、快速道路、高架道路、橋梁等及其引道經相關主管\n機關認定公告後，得不予指定建築線，以維護公共交通安全。\n道路或廣場開闢完成，其境界線經宜蘭縣政府（以下簡稱本府）公告為建\n築線者，得免申請指示（定）建築線。建築線變更時應即公告修正。\n第 五 條\n本自治條例所稱現有巷道，指符合下列情形之一者：\n一、經道路管理機關認定具公用地役關係之既成道路。\n二、經農地重劃所闢(留)設供通行使用，並由政府機關管理維護之農路。\n三、政府機關開闢及維護，或接管之通路，其現況寬度於山坡地達三公尺\n以上，山坡地以外達四公尺以上，由道路管理機關出具開闢及維護，\n或接管之證明。但因年代久遠無法出具開闢證明者，得以下列文件代\n之:\n(一)公有土地:管理機關同意土地作為道路使用函。\n(二)私有土地:全體土地所有權人同意供公眾通行之土地使用同意書。\n四、私設通路或私有通路符合下列各目規定：\n(一)經土地所有權人捐贈土地為道路使用，並完成土地所有權移轉登\n記為當地鄉(鎮、市)所有。\n(二)未計入法定空地。\n(三)上方無建築物。\n(四)連接至經指定建築線之道路。\n(五)寬度達六公尺以上。\n五、本法中華民國七十三年十一月七日修正公布前，曾指定建築線之現有\n巷道，經本府認定無礙公共安全、公共衛生、公共交通及市容觀瞻。\n六、經政府機關接管並公告供一般道路通行使用之水防道路。\n七、曾依本自治條例指定建築線之現有巷道，並符合下列各目規定：\n(一)巷道之認定未經撤銷或廢止。\n(二)道路現況與原建築線指定圖之道路寬度、位置無顯著差異。\n(三)政府機關出具管理維護中之證明。\n八、巷道最小寬度達二公尺以上，經政府機關出具管理維護證明，並符合\n下列情形之一：\n(一)省道、縣道或鄉道解編後之巷道。\n(二)曾依廢止前之臺灣省建築管理規則第四條第一項第二款規定，經\n土地所有權人出具供公眾通行同意書，並由本府完成公告程序之\n私設通路。\n九、供公眾通行使用之巷道。\n前項第四款私設通路範圍，不包括道路截角之退讓部分。\n第一項第四款所定私設通路，於申請建造執照時已設置之迴車道，視為私\n設通路之一部。\n第一項第一款、第七款及第九款規定現有巷道認定方式，由本府另以辦法\n定之。\n現有巷道及建築線之認定有疑義時，由本府現有巷道及建築線指示爭議案\n件審議小組審議之。\n第一項位於都市計畫內之公共設施用地或位於非都市土地之特定目的事業\n用地，屬公共設施性質者，不得認定為現有巷道。但經本府現有巷道及建\n築線指示爭議案件審議小組認定不影響該用地使用目的者，不在此限。\n第 六 條\n面臨現有巷道之基地，其建築線之指定，應依下列規定辦理：\n一、下列情形之現有巷道，以該巷道中心線為準，兩旁均等退讓，依下列\n規定指定建築線:\n(一)單向出口長度四十公尺以下，雙向出口長度八十公尺以下，寬度\n未達四公尺:以合計達四公尺寬度之邊界線作為建築線。\n(二)長度超過前款規定:以合計達六公尺寬度之邊界線作為建築線。\n(三)坐落都市計畫工業區、非都市土地之丁種建築用地及依法報編之\n工業區內之基地:以合計達八公尺寬度之邊界線作為建築線。\n二、地形特殊而不能通行車輛，符合前款第一目、第二目規定者，得分別\n以合計達三公尺、四公尺寬度之邊界線作為建築線。\n三、現有巷道之一側屬特殊地形或公共設施用地者，以其對側退縮達第一\n款規定寬度之邊界線作為建築線。\n四、現有巷道之寬度大於第一款規定之寬度者，依其邊界線指定建築線。\n五、建築基地正面臨接計畫道路或現有巷道，側面或背面臨接現有巷道者\n，一併指定該現有巷道之建築線；其側面或背面現有巷道因指定建築\n線退讓之部分，得計入法定空地。\n六、建築基地與都市計畫道路間之現有巷道，得以該現有巷道之邊界線指\n定建築線。\n七、第一款規定之現有巷道，寬度邊界線未達公有交通用地邊界線時，得\n以交通用地邊界線指定建築線。\n依前項規定退讓之土地，應供公眾通行使用。\n依第一項第一款規定退讓之土地，不得計入該基地之法定空地。\n第一項第一款所定單向出口，為現有巷道僅一端接通六公尺以上之計畫道\n路；所定現有巷道之長度，自其連接計畫道路之出口起算。\n建築物坐落非農業用地之基地，因第一項規定退讓土地者，於申請使用執\n照前，應完成地籍分割。\n第 七 條\n申請指示（定）建築線，應填具申請書及繳納規費，並檢附下列文件：\n一、地籍描繪圖：\n（一）應描繪一個街廓以上。\n（二）應標明建築基地之地段、地號、方位及基地範圍。\n（三）地籍經完成數值測量地區，應檢具申請基地地界座標值。\n二、基地位置圖：應標明基地位置、附近道路、機關學校或其他明顯建築\n物之相關位置。\n三、經建築師或專業技師簽證之現況實測圖：\n（一）應標明基地四周地界線外各十五公尺範圍內公共設施位置、現有建\n築物、道路（位置及寬度）、溝渠（位置及寬度）、地形（屬山坡\n地範圍之基地應測繪等高線）。\n（二）繪圖範圍及其比例尺同地籍描繪圖。\n（三）基地臨接現有道路者，應標示地界線與道路之關係。\n四、建築基地及鄰近土地之地籍圖及土地登記謄本。\n五、臨接或坐落於申請土地之現況相片（包含通路）。\n指示（定）建築線收費及作業辦法由本府定之。\n第 八 條\n指示（定）建築線成果圖有效期限為一年。但都市計畫、道路或廣場變更\n時，本府得指示重新申請。\n第 九 條\n現有巷道之改道或廢止，應向本府申請之，本府應將改道或廢止之路段公\n告三十日，徵求異議。公告期滿，無異議或認定異議無理由者，應准其申\n請。\n依前項申請改道者，除應檢附新設巷道位置圖外，並應檢附新設巷道土地\n所有權人出具捐贈土地為道路使用之同意書。\n經核准改道後，原巷道於新巷道開闢完成及供公眾通行，且新巷道土地辦\n畢所有權移轉登記手續予當地鄉（鎮、市）所有之日起廢止。現有巷道改\n道後之寬度應合於第六條規定。\n第一項現有巷道之改道或廢止之申請文件、辦理程序等作業規定，由本府\n定之。\n第 十 條\n建築基地連接建築線或以私設通路連接建築線，其連接寬度不得小於二公\n尺。\n申請興建農舍及一定規模之農業產銷設施者免受前項規定，但仍需向本府\n申請指示（定）建築線。\n前項一定規模之農業產銷設施，由本府定之。\n第十一條\n本府為改善環境，增進市容觀瞻，調整建築物之位置，得指定牆面線或退\n縮建築。\n前項所稱牆面線係指建築物外牆或以高度三點五公尺以上且無礙市容觀瞻\n及通行之圍牆、牌樓、牌坊、裝飾塔、光廊、迴廊、光柱、列柱、植栽綠\n籬或其他經本府認定之構造形式所形塑之界線。\n第十二條\n沿道路交叉口申請建築者，應依附表規定退讓。\n圖表附件：\n附表.DOC\n第十三條\n面臨計畫道路之建築基地，其騎樓、庇廊或無遮簷人行道之設置，除都市\n計畫說明書另有規定外，得由本府依據地方實際情形訂定設置標準。\n第十四條\n指示（定）建築線之文件上應註明下列事項：\n一、都市計畫內應註明道路樁位及分區界樁。都市計畫外應指定道路中心\n線及道路寬度。\n二、都市計畫土地使用分區。\n三、主要計畫及細部計畫名稱、發布實施日期及文號。\n四、建蔽率、容積率。\n五、道路寬度、截角長度、牆面線、退縮建築、第十二條規定之退讓界線\n及未開闢計畫道路之高程。\n六、其它必要事項。\n第十五條\n建築基地之排水設施及出水方向應配合該地區之排水及下水道系統設計，\n必要時得由本府規定其構造規格及型式。\n第十六條\n為推動環境綠化增進市容觀瞻，建築基地內之法定空地應加以綠化，實施\n辦法由本府定之。\n第 三 章 建築許可\n第十七條\n建築基地面臨道路、廣場申請建築，免附該道路、廣場之土地權利證明文\n件。\n第十八條\n建築基地以私設通路連接建築線者，應檢附該私設通路之土地權利證明文\n件。但已依法申請建築所留設之私設通路，其原面臨該通路建造之建築物\n或空地申請新建、增建、改建或修建者，不在此限。\n第十九條\n申請建造執照除依本法規定外，應檢附下列文件：\n一、土地登記謄本、地籍圖謄本。\n二、下列以建築為目的之土地權利證明文件（土地自有者免附）：\n（一）租賃權之租約書。\n（二）借用權之借約證書。\n（三）土地所有權人出具之土地使用權同意書。\n（四）其他依法取得之文件。\n三、工程圖樣。\n四、結構計算書。\n五、地基調查報告書。\n六、建築線指示（定）圖（公告免指定者免附）。\n七、其他有關文件：\n（一）使用共同壁者，應檢附協定書。\n（二）起造人委託建築師申請建築執照者，應檢附委託書。\n（三）申請興建自用農舍，應檢附鄉、鎮、市公所核發之無自用農舍證明\n、農業用地作農業使用證明文件。\n（四）增建者應檢附合法房屋證明文件。但供公眾使用建築物應檢附使用\n執照。\n（五）地籍套繪透明圖（內容與地盤圖相同）。\n（六）建築基地現況照片。\n（七）起造人為建築開發業者，應檢附建築開發商業同業公會之會員證書\n影本。\n（八）依有關法令之規定應檢附者。\n八、本府統一規定格式之數位化資料。\n下列圖說應於開工前送本府備查：\n一、結構詳圖。\n二、主要設備圖。\n三、公共建築物供行動不便者使用設施設置計畫書圖。\n第二十條\n申請雜項執照，除依本法規定外，並應檢附下列文件：\n一、土地登記謄本、地籍圖謄本。\n二、下列以建築為目的之土地權利證明文件（土地自有者免附）：\n（一）租賃權之租約書。\n（二）借用權之借約證書。\n（三）土地所有權人出具之土地使用權同意書（土地自有者免附）。\n（四）其他依法取得之文件。\n三、工程圖樣。\n四、建築線指示（定）圖（公告免指定者免附）。\n五、其他有關文件：\n（一）使用共同壁者應檢附協定書。\n（二）起造人委託建築師設計及請領建築執照者，應檢附委託書。\n（三）建築基地現況照片。\n（四）依有關法令之規定應檢附者。\n六、本府統一規定格式之數位化資料。\n山坡地範圍內之土地申請雜項執照者，除應依前項規定辦理外，並應依山\n坡地建築管理辦法之規定辦理。\n第二十一條\n本法第十六條規定得免由建築師設計、監造及營造業承造之建築物或雜項\n工作物規模如下：\n一、每幢樓地板面積在七十五平方公尺以下，高度在三點五公尺以下之建\n築物。\n二、高度在六公尺以下之瞭望台、廣播塔、獨立水塔、煙囪等或高度在二\n公尺以下之圍牆、駁崁。\n三、經農業主管機關核准非供人居住使用，每幢樓地板面積在五百平方公\n尺以下，建築物高度在三點五公尺以下用途為農業、畜牧、養殖或林\n業等設施之建築物。但休閒農業設施除外。\n第二十二條\n經農業主管機關核准非供人居住使用之農業、畜牧、養殖或林業設施，申\n請建築時，建築物應依下列規定退縮建築：\n一、建築物高度三點五公尺以下者，除面臨建築線外，自地界線退縮三公\n尺。但面臨道路交叉口應依本自治條例第十二條規定辦理。\n二、建築物高度逾三點五公尺者，依前款退縮外，並依逾越高度二分之一\n累計退縮建築距離。\n在一定規模以下之非供人居住使用之農作、畜牧、養殖或林業設施者，不\n受前項規定之限制。\n前項一定規模，由本府另定之。\n第二十三條\n本自治條例建築物之造價估算標準，由本府定之。\n本府依行政院主計處公告之「臺灣區消費者物價總指數」變化情形，每二\n年檢討前項估算標準。其變化情形逾前次調整後年指數累計達百分之二點\n五時，依該指數累計比例調整。造價估算標準調整時以百元為最小計算單\n位，未滿一百元部分以四捨五入計算。\n第 四 章 施工管理\n第二十四條\n建築工程及拆除工程使用道路者，應依下列規定辦理：\n一、使用道路寬度：\n（一）道路寬度未達四公尺者，不得使用。\n（二）道路寬度在四公尺以上未達六公尺者，使用寬度不得超過一公尺。\n（三）道路寬度在六公尺以上未達十二公尺者，使用寬度不得超過一點五\n公尺。\n（四）道路寬度在十二公尺以上者，使用寬度不得超過二公尺。\n二、申請使用道路，應於開工前填具申請書，檢附使用範圍圖，向道路主\n管機關申請核定後，報本府備查。\n三、使用道路應依核准使用之範圍設置安全圍籬；使用人行道者，應在安\n全圍籬外設置有頂蓋之行人安全走廊。\n四、經核准使用道路之範圍，仍應依本法第六十四條規定辦理。\n第二十五條\n依本法第五十九條第一項規定經本府令其停工者，應於六個月內辦理變更\n設計。\n依下列規定完成之樓層，得按其核准範圍申領使用執照：\n一、已完成基礎工程者，准其完成至一層樓為止。\n二、超出一層樓並已完成外牆一公尺以上或柱高達二公尺半以上者，准其\n完成至各該樓層為止。\n第二十六條\n本府依本法第五十三條核定建築期限時，以六個月為基數，並依下列規定\n增加日數：\n一、地下層每層四個月。\n二、地面各樓層每層三個月。\n三、雜項工程三個月。\n前項建築期限，因特殊構造、施工困難、工程鉅大或情形特殊，顯有增\n加日數必要者，得敘明原因，檢附施工計畫書向本府提出申請，本府得依\n其施工計畫審查結果酌予增加工期。\n施工中建築物因本法及其相關法令或都市計畫變更，需勒令停工者，並經\n查明不應歸責於起造人、承造人時，本府得就勒令停工日數不計施工期限\n，於通知復工或核准變更設計時一併延長其建築期限。\n第一項建築期限，以開工之日起算。\n第二十七條\n依本法第五十三條、第五十四條作廢之建造執照或雜項執照，本府應於執\n照作廢後三十日內，派員實地勘查，其擅自建築者，應依本法第八十六條\n規定處理。\n第二十八條\n(刪除)\n第二十九條\n建築物施工計畫書之內容，應包括下列事項：\n一、承造人之專任工程人員、監工人、工地負責人與勞工安全衛生管理人\n員之姓名、地址及聯絡電話。\n二、工程概要。\n三、施工程序及預定進度。\n四、施工方法、作業時間及勘驗申報方式。\n五、施工場所各項安全措施布置、工寮、材料堆置、加工場之圖說及配置。\n六、營造安全衛生設施、勞工安全衛生設施、工地環境之維護、 賸餘土石\n方、建築廢棄物之處理及防災緊急應變措施。\n起造人應依本府備查之施工計畫書施工；建築物施工管制辦法， 由本府另\n定之。\n第三十條\n工程施工期間，應於基地明顯處懸掛施工告示牌，載明核准執照文號、起\n造人姓名、設計人、監造人、承造人、專任工程人員資料及連絡電話、建\n築期限、開工及竣工日期、工程管制編號、環保檢舉電話、工地負責人姓\n名、工地電話。告示牌之規格、材質、顏色設置規則，由本府定之。\n第三十一條\n建築工程必須申報勘驗部分，除因特殊構造或工法按本府核定之施工計畫\n書辦理外，依下列施工階段辦理：\n一、放樣勘驗：建築物放樣後，挖掘基礎土方前。\n二、基礎勘驗：基礎土方挖掘後、澆置混凝土前，其為鋼筋混凝土構造者\n，配筋完畢，如有基樁者，基樁施工完成。\n三、各層勘驗：\n（一）鋼骨鋼筋混凝土造、鋼筋混凝土造及加強磚造各層樓板或屋頂配筋\n完畢，澆置混凝土前。\n（二）鋼骨構造之鋼骨結構組立完成，作防火被覆前，並得多層勘驗。\n四、屋架勘驗：屋架豎立後蓋屋面之前。\n前項勘驗應包括建築物位置相關事項、防火避難設備、場鑄污水處理設備\n、配筋、騎樓及其高程、公共交通、衛生及安全措施。\n申報勘驗前，應由承造人及其專任工程人員、監工人、工地負責人先行勘\n驗合格，再報請監造人查核合格後，檢具申報文件於該階段工程施工前送\n達本府後方得繼續施工。但有緊急施工之必要者，監造人或承造人得監督\n先行施工，並於三日內報請備查。依第二十一條規定免由營造業承造及建\n築師監造之建築物由起造人自行依核定圖樣施工，免予施工勘驗。有關建\n築物之位置，臨接建築線部分，以本府所定建築線為準，土地界址由土地\n所有權人申請主管地政機關鑑定之，地界未經鑑定致越界建築者，由起造\n人負責。\n勘驗紀錄應與建築執照申請書件及工程圖說一併保存，至該建築物拆除或\n損毀為止。\n必須申報勘驗部分之勘驗方式、項目、所需文件，起造人、承造人、監造\n人應配合事項及未報勘驗先行施工之處理辦法，由本府定之。\n第三十二條\n工程進行中變更設計者，應依本法第三十九條前段規定提出申請。但因防\n範緊急危險，得於施工後七日內補辦手續。\n第 五 章 使用管理\n第三十三條\n建築物竣工後，有下列情形者，視為符合建築執照許可內容：\n一、建築物高度誤差在百分之一以下，未逾三十公分；各樓層\n高度誤差在\n百分之三以下，未逾十公分。\n二、各層樓地板面積誤差在百分之三以下，未逾三平方公尺，\n且任一向長\n度誤差合計在百分之一以下，未逾十公分。\n三、臨接騎樓線或指定牆面線部分誤差，未逾五公分。\n四、前三款以外之其它部分之尺寸誤差在百分之二以下，未逾\n十公分。\n建築物竣工後，應由起造人會同承造人及監造人申請使用執照；建築物使\n用執照核發辦法，由本府另定之。\n第三十四條\n建築物竣工時，起造人或承造人應將損壞之道路、溝渠、路燈、都市計畫\n樁等公共設施修復，並將損毀之行道樹補植，私設通路路面舖設適當；搭\n蓋之圍籬、遮板、鷹架、工棚、樣品屋及須拆除之舊有建築物拆除完竣、\n清理一切廢棄物及疏通水溝後，始得申請核發使用執照。\n第 六 章 拆除管理\n第三十五條\n申請拆除執照，除依本法規定外，並應檢附下列文件：\n一、申請書。\n二、建築物權利證明文件或其他合法證明。\n三、建築物面積計算圖。\n四、現況照片。\n五、使用道路範圍圖（限使用道路者）。\n六、建築物部分拆除者，檢附建築師出具之安全鑑定書。\n拆除執照得併同建造執照申請之，未併同建造執照申請者，其有效期限以\n領得拆除執照之日起九個月為限，逾期失其效力。\n第三十六條\n建築物拆除工程，除符合第二十一條規定規模之建築物外，應由營造業承\n攬，並由建築師或營造業之專任工程人員負責監督。\n拆除工程進行前，申請人應檢具申報書、施工計畫書、工程賸餘土石方處\n理計畫書、廢棄物處理計畫書及空氣污染防制費繳納證明，報本府備查。\n第三十七條\n拆除執照未併同建築執照申請者，申請人應於建築物拆除完成後，在拆除\n執照有效期限內，填具申請書並檢附下列文件、資料，向本府申請拆除竣\n工證明：\n一、部分拆除者，檢附拆除後之建築物平面圖、立面圖。\n二、現況照片。\n三、建築工程賸餘土石方及建築廢棄物處理完成之證明文件。\n四、空氣污染防制費繳納結清證明。\n因進行拆除工程致生損壞鄰房爭議者，申請人應依宜蘭縣建築物施工中損\n壞鄰房爭議事件處理自治條例規定程序處理；經本府解除列管後，始得申\n請拆除竣工證明。\n第 七 章 罰則\n第三十八條\n違反第三十條、第三十六條第三項應遵守辦理事項者，經限期改善，屆期\n仍未改善或改善未完竣者，處新臺幣三千元以上二萬元以下罰鍰，並得連\n續處罰。\n第三十八條之一\n有下列情形之一者，處申請人、承造人或起造人新臺幣九千元以下罰鍰，\n並令其限期補辦手續；屆期仍未補辦手續者，令其停工至改善為止：\n一、違反第二十九條第二項前段規定，未依本府備查之施工計畫書施工。\n二、未依本法第五十四條及本自治條例第三十六條第二項規定向本府申報\n備查，即進行拆除工程。\n三、領得拆除執照後，未依第三十七條規定之期限，申請拆除竣工證明。\n四、逾臨時性建築物許可使用期限，始申請延長使用。\n違反前項規定者，依其申請案件之數量，分別處罰之。\n第 八 章 附則\n第三十九條\n下列建築物或雜項工作物之起造人，應敘明不適用本法之條款及其理由，\n向本府申請許可：\n一、紀念性之建築物或古蹟，照原有形貌保存，有修復必要，且其修復之\n工程計畫，經古蹟主管機關許可者。\n二、海港、碼頭、鐵路車站、航空站等範圍內之雜項工作物，其工程計畫\n經各該主管機關許可者。\n三、臨時性之建築物。\n興辦公共設施，在拆除合法建築基地內改建或增建建築物之管理辦法，由\n本府定之。\n第一項經許可不適用本法一部或全部規定之建築物，申請人仍應將工程圖\n樣說明書及建築期限報本府備查。\n第一項第三款臨時性建築物之許可、施工及使用管理辦法，由本府定之。\n臨時性建築物使用期滿後，申請人應自行拆除；逾期未拆除者，依違章建\n築處理辦法辦理。\n第四十條\n中華民國六十年十二月二十二日本法修正公布前、實施都市計畫以外地區\n建築物管理辦法施行前，已建築完成或經鄉（鎮、市）公所發給合法房屋\n證明文件者，起造人得填具使用執照申請書，檢附下列文件，申請補發使\n用執照，並免由建築師及營造業簽章：\n一、申請基地連接建築線指示成果圖。\n二、土地權利或同意使用土地權利證明文件。\n三、房屋權利證明文件；未辦理房屋所有權登記者，應檢附切結其房屋權\n利之文件。\n四、基地位置圖、地盤圖與建築物之平面圖及立面圖。\n五、建築師簽證之安全鑑定書。\n六、房屋完成日期證明文件。\n七、其他有關文件。\n第四十一條\n中華民國六十年十二月二十二日本法修正公布前已領有建造執照之建築物\n，得檢附下列文件，申請補發使用執照，並免由建築師及營造業簽章：\n一、使用執照申請書。\n二、原領建造執照及核准之設計圖。\n三、施工中有辦理勘驗者，檢附勘驗紀錄，未辦理者，檢附建築師安全鑑\n定書。\n四、同時變更起造人名義者，應附土地及房屋權利證明文件。\n五、房屋完成日期證明文件。\n六、其他有關文件。\n前項第三款無勘驗紀錄者，應依本法第八十七條規定予以處罰。\n第四十二條\n供公眾使用之建築物，依前二條規定申請補發使用執照者，其出入口、走\n廊、樓梯、室內裝修及消防設備應符合建築技術規則及消防法規之規定。\n增設之安全梯免計入建築面積。\n第四十三條\n依第四十條、第四十一條規定申請補發使用執照之建築物，其建蔽率、高\n度應符合都市計畫法及相關法令規定。但建築物在適用本法前或實施都市\n計畫以外地區建築物管理辦法施行前，已建築完成或符合原核准建造執照\n、合法房屋認定者，不在此限。\n前項建築物之用途，應符合都市計畫法及相關法令規定。但在都市計畫發\n布前已取得營利事業許可者，不在此限。\n第四十四條\n本府得委託專業公會或團體協助審查以下事項：\n一、建築線指示(定)。\n二、建築執照。\n三、施工勘驗。\n四、變更使用執照。\n五、其他本自治條例規定之事項。\n前項審查費用由申請人負擔。\n第一項受託之專業公會或團體執行審查業務，應擬訂作業事項並載明工作\n內容、收費基準與應負之責任及義務，報本府核定。\n第四十五條\n起造人、建築物所有權人得申請發給建築執照核准執照圖說影本。\n建築物所有權人得申請發給使用執照謄本及竣工圖影本。\n發給前二項文件，本府得收取規費。\n第四十五條之一\n為避免老舊建築物因地震發生災害，以維護公共安全，中華民國八十八年\n十二月三十一日以前取得建造執照之四層以上集合住宅及六層以上建築物\n，經本府篩檢有安全疑慮者，其所有權人或使用人應於本府通知之日起三\n個月內委由專業機構辦理建築物耐震能力初步評估。\n前項評估結果應於評估完成之日起三個月內申報本府備查，評估所需費用\n由本府補助。\n第四十六條\n本自治條例自公布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:FL023420","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"修正日期":"民國 114 年 08 月 06 日","全文檔案":"(1140806)宜蘭縣建築管理自治條例.odt","公發布日":"民國 91 年 12 月 25 日","圖表附件":"附表.odt","法規名稱":"宜蘭縣建築管理自治條例","法規體系":"建設","發文字號":"府秘法字第1140133631B號令","立法理由":"(1140806)宜蘭縣建築管理自治條例部分條文修正總說明及修正對照表.odt"},"promulgation_date":"2002-12-25","revision_date":"2025-08-06","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=FL023420","status":"unknown","title":"宜蘭縣建築管理自治條例","last_checked_at":"2026-10-06T17:31:09+08:00","last_success_at":"2026-10-06T17:31:09+08:00","verification_status":"fetched","content_hash":"f96fb4cfa7112f8c08db976831c6fb554f97695004fefe5b41cf02f300c9e062","history":[{"observed_at":"2026-10-06T17:31:09+08:00","content_hash":"f96fb4cfa7112f8c08db976831c6fb554f97695004fefe5b41cf02f300c9e062","change_kind":"initial","revision_date":"2025-08-06"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=5191&id=FL023420&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=5192&id=FL023420&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3886&id=FL023420&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=7&id=FL023420&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"宜蘭縣建造執照及雜項執照簽證案件抽查檢查表.doc","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=948&id=GL000257&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、宜蘭縣政府（以下簡稱本府）為辦理建造執照、雜項執照及其變更設計建築師簽證項目抽查，依據建造執照及雜項執照規定項目審查及簽證項目抽查作業要點訂定本處理原則。\n二、本處理原則所稱簽證項目，係指建造執照及雜項執照建築師簽證表所定建築師簽證項目。\n三、本府辦理建造執照、雜項執照及其變更設計建築師簽證項目抽查，應設抽查小組。抽查小組由本府代表一人及宜蘭縣建築師公會（以下簡稱建築師公會）代表三人組成。抽查案件包含本府委託專業團體協助審查之建造執照及雜項執照核准案件。\n建築師公會代表如為簽證案件設計人，應予迴避。\n四、抽查時間定於每星期二下午二時起進行，於當日抽查完畢；遇國定假日順延。\n五、抽查方式如下：\n㈠五層以下非供公眾使用之建築物每十件至少抽查一件。\n㈡五層以下供公眾使用之建築物每十件至少抽查二件。\n㈢六層以上至十四層之建築物每十件至少抽查二件。\n㈣十五層以上建築物每十件至少抽查五件。\n前項各款未達抽查數量者，至少應抽查一件。\n六、抽查結果應作成書面紀錄，有不符規定者，由本府通知起造人及設計人改正，或辦理變更設計。\n本府委託建築師公會協審之建築執照申請案件，其抽查及通知一併委由建築師公會辦理。\n七、建造執照及雜項執照抽查項目如附表。每一案件簽證項目經抽查有附表五項以上不符規定者，視為不合格案件。一年內不合格案件累積超過三件者，設計建築師或專業工業技師應依建築師法或技師法有關規定移送懲戒。\n前項附表有關結構計算書與綠建築設計等項目，本府得另委託專業團體辦理。其他事項經抽查人員認定不合格者，仍應依前項規定辦理。\n八、起造人、設計建築師申請建造執照或雜項執照案件，經抽查不符規定，於收到抽查小組通知改正或辦理變更設計，如有異議者，應於通知改正期限內申請復核。\n抽查小組應於十日內將復核結果通知起造人、設計建築師。\n抽查或復核時如有法令適用疑義，得提請本府建築法令研討小組研議解決。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:GL000257","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"公發布日":"民國 103 年 02 月 10 日","圖表附件":"宜蘭縣建造執照及雜項執照簽證案件抽查檢查表.doc","法規名稱":"宜蘭縣建造執照及雜項執照簽證案件抽查處理原則","法規體系":"建設","發文字號":"府建管字第1030020075號 函"},"promulgation_date":"2014-02-10","revision_date":"2014-02-10","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=GL000257","status":"unknown","title":"宜蘭縣建造執照及雜項執照簽證案件抽查處理原則","last_checked_at":"2026-10-06T17:31:30+08:00","last_success_at":"2026-10-06T17:31:30+08:00","verification_status":"fetched","content_hash":"c81323510de33032cc333fcc8eccbe0097a1a67a1e2a9e6484d2bb80b8f9e282","history":[{"observed_at":"2026-10-06T17:31:30+08:00","content_hash":"c81323510de33032cc333fcc8eccbe0097a1a67a1e2a9e6484d2bb80b8f9e282","change_kind":"initial","revision_date":"2014-02-10"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=948&id=GL000257&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、宜蘭縣政府建設局 (以下簡稱本局) 為辦理建築法第三十四條第一項規定之特殊結構\n建築物委託審查業務，特訂定本要點。\n二、建築物有下列各款情形之一者，應將其結構設計委託審查。\n(一)建築物高度超過五十公尺以上者。\n(二)鋼筋混凝土構造且設計跨距在十八公尺以上者。\n(三)建築物地下層開挖之總深度 (含基礎) 在十二公尺以上或地下層開挖超過三層者\n。\n(四)其他情況特殊經本局認為有必要者。\n三、受理委託審查之機關或團體 (以下簡稱審查機關或團體) 如下：\n(一)設有土木、營建或建築等科系之國內公私立大學院校。\n(二)土木、結構技師或建築師公會。\n(三)其他經本局核備之機關或團體。\n前項審查機關或團體每一案件之審查人員應在五人以上，審查人員應具備土木、結構\n技師、建築師或大專院校副教授以上教授結構相關科目等資格之一者，並應函報本府\n核備，異動時亦同。案件之設計人不得擔任該案件之審查人。\n四、審查機關或團體於受理特殊結構委託審查案件，應依下列方式辦理：\n(一)審查機關或團體應明定審查費用、檢附文件及審查時限。\n(二)應舉行公開會議審查，並得自由旁聽。\n(三)本局認為有必要時，得邀請審查機關或團體於審查完成後准予備查前提出說明。\n五、符合本要點第二條建築物之起造人於領得建造執照後，應選定審查機關或團體，並自\n行繳納審查費申請特殊結構委託審查。\n審查完成後應檢具合格證文件，於法定開工期限內，申報開工。\n結構變更之案件，應委由原審查機關或團體辦理審查，經審查合格後，始得准予變更\n設計。\n六、本要點奉縣長核定後實施，修正時亦同。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:FL034343","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"公發布日":"民國 91 年 10 月 14 日","法規名稱":"宜蘭縣建造執照申請有關特殊結構委託審查作業要點","法規體系":"建設","發文字號":"府建管字第0910118485號"},"promulgation_date":"2002-10-14","revision_date":"2002-10-14","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=FL034343","status":"unknown","title":"宜蘭縣建造執照申請有關特殊結構委託審查作業要點","last_checked_at":"2026-10-06T17:31:34+08:00","last_success_at":"2026-10-06T17:31:34+08:00","verification_status":"fetched","content_hash":"fe1dc213aeef97cb84385dc87ab66a5a17aaedfa844e8d27903da1450a9c6eff","history":[{"observed_at":"2026-10-06T17:31:34+08:00","content_hash":"fe1dc213aeef97cb84385dc87ab66a5a17aaedfa844e8d27903da1450a9c6eff","change_kind":"initial","revision_date":"2002-10-14"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"宜蘭縣政府","category":"建築管理相關","content":"第 1 條\n本辦法依宜蘭縣建築管理自治條例 (以下簡稱本自治條例) 第三十九條第\n二項訂定之。\n第 2 條\n本辦法所稱合法建築物係指依法領有使用執照、完工證明或合法房屋證明\n之建築物。\n第 3 條\n有下列情形之一者，不適用本辦法：\n一　農舍及農業、畜牧、養殖或林業生產必要設施。\n二　供公眾使用之建築物。\n三　已領有補償費須全棟拆除之建築物。\n未領得補償費之剩餘建築物，依本辦法申請就地整建時，得一併辦理拆除\n重建。\n第 4 條\n剩餘建築物就地整建應依下列規定辦理：\n一、建築基地臨接建築線長度應為二公尺以上。\n二、建築基地自建築線起算之深度不得小於三‧五公尺。\n三、就地整建建築物之簷高不得超過十‧五公尺，屋頂如為斜屋頂，其最\n高高度得自簷高加屋架跨度四分之一高度，如拆除後之賸餘基地屬公\n共設施保留地者，其整建高度應符合都市計畫公共設施保留地臨時建\n築使用辦法有關規定。\n四、就地整建後之總樓地板面積，不得超過拆除前原有合法建築物總樓地\n板面積之一‧二倍，且不得大於二百六十平方公尺。\n五、就地整建時，得不受建蔽率、容積率、都市計畫有關留設騎樓或退縮\n建築、宜蘭縣畸零地使用規則及宜蘭縣都市計畫地區法定騎樓或無遮\n簷人行道設置辦法規定之限制。惟應依建築技術規則建築設計施工編\n規定留設防火間隔，但其基地深度小於十公尺者，不在此限。\n第 5 條\n建築物剩餘部分修復門面得免申請就地整建，由修復人自行沿拆除面，按\n拆除剩餘之建築物高度修復。\n第 6 條\n申請就地整建者，應於受領補償費並自確定公共設施邊界線至公共工程完\n工後六個月內，向宜蘭縣政府 (以下簡稱本府) 提出申請。\n第 7 條\n申請就地整建時應檢附下列文件：\n一　合法房屋之證明文件。\n二　土地權利證明文件。\n三　共同壁協定書。\n四　地盤圖。\n五　建築線指定 (示) 成果圖。\n六　剩餘建築物之各層平面圖及各向立面圖，比例尺不得小於百分之一。\n七　就地整建建築物之各層平面圖、各向立面圖、基礎平面圖、屋架構造\n平面圖及主要剖面圖，比例尺不得小於百分之一。\n八　整建建築物在二層樓以上，應檢附建築師或專業技師簽證之安全證明\n及結構計算書。\n九　其他相關文件。\n第 8 條\n就地整建應依核准圖樣興建完成。興建完成後應檢附竣工平面圖、立面圖\n、各向立面照片及相關文件向主管機關申請核發完工證明。\n第 9 條\n未經核准擅自整建或未依照核准圖樣施工者，依建築法第八十六條第一款\n規定處理。\n第 10 條\n依本辦法規定申請就地整建，本府得依建築法第二十七條規定委由鄉、鎮\n公所辦理。\n第 11 條\n就地整建申請書及證明書之格式由本府另定之。\n第 12 條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:FL030365","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"修正日期":"民國 104 年 06 月 08 日","公發布日":"民國 92 年 04 月 03 日","法規名稱":"宜蘭縣拆除合法建築物剩餘部分就地整建辦法","法規體系":"建設","發文字號":"中華民國104年6月8日府秘法字第1040094785號 令"},"promulgation_date":"2003-04-03","revision_date":"2015-06-08","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=FL030365","status":"unknown","title":"宜蘭縣拆除合法建築物剩餘部分就地整建辦法","last_checked_at":"2026-10-06T17:31:19+08:00","last_success_at":"2026-10-06T17:31:19+08:00","verification_status":"fetched","content_hash":"7f0f9dbc77ce0eab782c143b1fdfb9a9b7534ef1ce274fd3122d9cbf6e0ec32c","history":[{"observed_at":"2026-10-06T17:31:19+08:00","content_hash":"7f0f9dbc77ce0eab782c143b1fdfb9a9b7534ef1ce274fd3122d9cbf6e0ec32c","change_kind":"initial","revision_date":"2015-06-08"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"宜蘭縣指定建築線收費辦法.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3145&id=FL034157&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"第一條\n本辦法依宜蘭縣建築管理自治條例第七條第二項規定訂定之。\n第二條\n指定建築線申請案件，申請人應於宜蘭縣政府（以下簡稱本府）\n審查通過後，繳交新臺幣二千元並領取建築線指定成果圖一份。\n同一申請案件申請發給成果圖多於一份時，每增加一份應再繳交\n新臺幣五百元。\n第三條\n申請人收到領取建築線指定成果圖及繳交費用之通知後，逾六個\n月未向本府領取建築線指定成果圖及繳交費用者，本府得廢止指\n定之建築線成果，並駁回申請案件。\n申請人未繳清應繳之費用者，本府不受理該申請人其他指定建築\n線申請案件。\n第四條\n申請人依本辦法規定繳納費用後，除有溢繳或誤繳情形外，不得\n要求退費。\n申請人有前項溢繳或誤繳情事者，得於繳費之日起一個月內提出\n相關文件，向本府申請退還溢繳或誤繳之費用。\n第五條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:FL034157","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"修正日期":"民國 109 年 05 月 07 日","公發布日":"民國 92 年 12 月 23 日","圖表附件":"宜蘭縣指定建築線收費辦法.odt","法規名稱":"宜蘭縣指定建築線收費辦法","法規體系":"建設","發文字號":"府秘法字第1090073154B號"},"promulgation_date":"2003-12-23","revision_date":"2020-05-07","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=FL034157","status":"unknown","title":"宜蘭縣指定建築線收費辦法","last_checked_at":"2026-10-06T17:31:17+08:00","last_success_at":"2026-10-06T17:31:17+08:00","verification_status":"fetched","content_hash":"4b758bbec5f4db124212bec070b8d09b1b15979b4ab8e849b692192513994e6f","history":[{"observed_at":"2026-10-06T17:31:17+08:00","content_hash":"4b758bbec5f4db124212bec070b8d09b1b15979b4ab8e849b692192513994e6f","change_kind":"initial","revision_date":"2020-05-07"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3145&id=FL034157&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"(1150122)宜蘭縣政府公共建築物無障礙設施改善諮詢及審查小組設置及作業要點.pdf","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=5440&id=FL039663&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、宜蘭縣政府(以下簡稱本府)為推動宜蘭縣公共建築物無障礙設施改善\n計畫，依內政部訂頒既有公共建築物無障礙設施替代改善計畫作業程\n序及認定原則第六點規定，設公共建築物無障礙設施改善諮詢及審查\n小組(以下簡稱本小組)，並訂定本要點。\n二、本要點所稱公共建築物，指建築技術規則建築設計施工編第一百七十\n條所定之公共建築物。\n三、本小組任務如下：\n(一)分類、分期、分區改善執行計畫及期限之擬定。\n(二)各類建築物無障礙設施項目優先改善次序之擬定。\n(三)公共建築物替代改善計畫之諮詢及指導。\n(四)公共建築物無障礙設施改善計畫書、無障礙設施改善報告書之審\n核。\n(五)公共建築物改善完竣報請備查之勘驗。\n四、本小組置召集人一人，由本府建設處處長兼任；副召集人二人，由本\n府社會處、教育處相關業務主管各一人兼任；其餘委員由本府就下列\n人員聘(派)兼之：\n(一)相關目的事業主管機關代表。\n(二)建築師公會代表。\n(三)相關專業領域之學者、專家。\n(四)身心障礙團體代表。\n本小組委員任一性別比例，不得少於總數三分之一。\n五、本小組每季定期召開一次會議，必要時得召開臨時會議，由召集人召\n集並擔任主席。召集人因故未能出席時，得由召集人指定一人代理之\n。\n六、本小組置幹事數人，由本府下列單位人員兼任，負責相關資料整理及\n聯繫協調等事項：\n(一)建設處。\n(二)社會處。\n(三)教育處。\n七、本小組委員、幹事均為無給職。但外聘委員得依規定支領交通費及出\n席費。本小組所需業務經費，由本府編列預算支應。\n八、本小組審查無障礙設施改善計畫書、無障礙設施改善報告書時，得邀\n請設計人列席說明。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:FL039663","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"修正日期":"民國 115 年 01 月 22 日","全文檔案":"(1150122)宜蘭縣政府公共建築物無障礙設施改善諮詢及審查小組設置及作業要點.pdf","公發布日":"民國 90 年 05 月 14 日","法規名稱":"宜蘭縣政府公共建築物無障礙設施改善諮詢及審查小組設置及作業要點","法規體系":"建設","發文字號":"府建使字第1150007214號函"},"promulgation_date":"2001-05-14","revision_date":"2026-01-22","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=FL039663","status":"unknown","title":"宜蘭縣政府公共建築物無障礙設施改善諮詢及審查小組設置及作業要點","last_checked_at":"2026-10-06T17:31:23+08:00","last_success_at":"2026-10-06T17:31:23+08:00","verification_status":"fetched","content_hash":"9525847a263ca77752cbf171d030b1af7815d596c87c438f606afc00f29f202b","history":[{"observed_at":"2026-10-06T17:31:23+08:00","content_hash":"9525847a263ca77752cbf171d030b1af7815d596c87c438f606afc00f29f202b","change_kind":"initial","revision_date":"2026-01-22"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=5440&id=FL039663&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"附件.DOC","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=544&id=FL034336&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"第 1 條\n本要點依本府執行違章建築取締辦法第六條暨建築法第九十六條之一第一\n項規定訂定之。\n第 2 條\n執行範圍：依本府執行違章建築取締辦法第三條規定之執行順序，依限處\n理，由本府訂定每月應拆除之件數基準，列管追蹤處理。\n第 3 條\n執行方式:\n(一) 八十六年十二月三十一日以前之違章建築，由本府每年編列預算，\n逐年進行拆除。\n(二) 八十七年一月一日以後之新違章建築，應依違章建築處理辦法規定\n即報即拆，拆除費用，依本要點第四條規定之標準計算，由義務人\n負擔。\n第 4 條\n拆除費用，依附表規定按違章建築構造類別及拆除面積計算之。\n第 5 條\n本要點公佈後，本府應定期召開全縣各鄉鎮市公所違建取締承辦人協調作\n業會報，提出成果報告並作檢討。\n第 6 條\n違建拆除結案後，由本府列冊交由各鄉鎮市公所按月呈報追蹤績效，本府\n得隨時抽查。\n第 7 條\n有關違建督導考核及獎懲要點由本府另訂之。\n第 8 條\n要點奉縣長核定後公行，修正時亦同。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:FL034336","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"公發布日":"民國 87 年 05 月 21 日","圖表附件":"附件.DOC","法規名稱":"宜蘭縣政府取締違章建築執行要點","法規體系":"建設","發文字號":"八七府祕法字第47123號"},"promulgation_date":"1998-05-21","revision_date":"1998-05-21","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=FL034336","status":"unknown","title":"宜蘭縣政府取締違章建築執行要點","last_checked_at":"2026-10-06T17:31:35+08:00","last_success_at":"2026-10-06T17:31:35+08:00","verification_status":"fetched","content_hash":"073aff003b34caf40ead492cfdcbe0f9a77379ef23c54c1cb29f989c7be2f19c","history":[{"observed_at":"2026-10-06T17:31:35+08:00","content_hash":"073aff003b34caf40ead492cfdcbe0f9a77379ef23c54c1cb29f989c7be2f19c","change_kind":"initial","revision_date":"1998-05-21"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=544&id=FL034336&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"宜蘭縣政府執行建築基地開放空間管理維護要點.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3460&id=GL000618&type=LAW"},{"name":"附表.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3461&id=GL000618&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、宜蘭縣政府(以下簡稱本府)為使建築基地之開放空間確實開放提\n供公眾自由通行或休憩，及增進公眾使用權益，特訂定本要點。\n二、本要點之主管機關為本府，管理單位為本府建設處。\n三、本要點所稱開放空間，係指符合下列情形之一者：\n(一)依八十五年六月二十六日廢止前之未實施容積管制地區綜合\n設計鼓勵辦法第三條及九十二年三月二十日廢止前之實施都\n市計畫地區建築基地綜合設計鼓勵辦法第四條規定，所納管\n之開放空間。\n(二)依建築技術規則建築設計施工編第二百八十三條第一項規定\n，或經本縣都市設計審議委員會(以下簡稱都審會)審議通過\n，得提高建築物高度，所留設之空間。\n四、建築基地開放空間經都審會通過後，本府應將起造人申請使用執\n照時應履行事項列為附款，通知起造人並副知管理單位。\n五、起造人申請建造執照時，應檢附都審會通過之核准函及報告書。\n前項核准文件及本府核發之建照執照均應記載核准文號及基地所\n留設開放空間，日後應確實供公眾使用等文字。\n六、起造人應製作與開放空間告示牌內容相同之開放空間圖說，送本\n府、開放空間所在地之鄉（鎮、市）公所、村（里）長辦公處備\n查，俾利後續管理及公告事宜。\n七、建築工程申報開工時，起造人應在施工圍籬上設置與施工告示牌\n相同大小之開放空間預告圖照片，材質應具防水性。\n八、建築工程施工期間，本府得不定期派員至現場勘驗是否按圖施工\n；經發現與原核准內容不符者，依建築法第五十八條規定辦理。\n九、建築工程申請使用執照時，起造人應檢附開放空間管理維護執行\n計畫書（以下簡稱執行計畫書），內容應載明開放空間設施及其\n管理維護事項及方式，並納入公寓大廈規約草約內。本要點實施\n前，已申請或領得建造執照案件，亦同。\n前項執行計畫書應載明下列事項：\n(一)建築物所有權人、公寓大廈管理委員會或管理負責人之姓名\n、住址、身分證號碼及連絡電話。\n(二)開放空間設施及其管理維護事項。\n(三)管理維護方式。\n(四)其他管理維護執行有關事項。\n十、建築工程核發使用執照前，由本府通知工程所在地之鄉（鎮、市\n）公所、民意代表及村里長到場，並請起造人、承造人或監造人\n當場說明開放空間竣工範圍及設施內容。\n十一、使用執照及其核准函，應記載核准文號、開放空間面積、都審\n會決議要求事項及基地所留設開放空間，日後應確實供公眾使\n用等文字，並副知管理單位、開放空間所在地之鄉（鎮、市）\n公所、民意代表、村（里）長，協助辦理公告事宜。\n十二、公寓大廈於成立管理委員會或推選管理負責人，並向各鄉（鎮\n、市）公所完成報備後，本府應發文通知起造人將執行計畫書\n列入建築物點交其他項目，並確實辦理移交。起造人依公寓大\n廈管理條例第五十七條規定辦理公寓大廈共用部分、約定共用\n部分與其附屬設施設備（以下簡稱共用設施）點交前，本府應\n派員至現場確認有無違規情事，以釐清違規行為人，賡續為裁\n罰之依據。\n前項共用設施點交時，起造人除應會同本府、公寓大廈管理委\n員會或管理負責人外，應同時通知開放空間所在地之鄉（鎮、\n市）公所及其村里長到場，說明開放空間點交事項。\n十三、已領得使用執照及完成共用設施點交之開放空間建案，本府應\n予造冊列管，並將相關資訊公布於管理單位之網站，每年實施\n抽查；發現有違規情形者，依建築法及其他相關法令規定辦理\n(如附表)。\n圖表附件：\n附表.odt\n十四、開放空間應供公眾通行或休憩使用，不得限制開放時間。但一\n百零一年七月一日建築技術規則建築設計施工編第十五章實施\n都市計畫區建築基地綜合設計專章修正施行前已領得使用執照\n之建築物，其開放空間應至少於每日上午八時至下午八時開放\n供公眾使用，其餘時段得依既有設施設備予以限制。\n符合前項規定者，應於適當位置設置寬度一點五公尺以上之進\n出開口，並於明顯處張貼公告，其內容應載明開放時段及供民\n眾自由進出使用等。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:GL000618","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"修正日期":"民國 110 年 06 月 29 日","全文檔案":"宜蘭縣政府執行建築基地開放空間管理維護要點.odt","公發布日":"民國 108 年 10 月 01 日","法規名稱":"宜蘭縣政府執行建築基地開放空間管理維護要點","法規體系":"建設","發文字號":"府建使字第1100104375號函"},"promulgation_date":"2019-10-01","revision_date":"2021-06-29","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=GL000618","status":"unknown","title":"宜蘭縣政府執行建築基地開放空間管理維護要點","last_checked_at":"2026-10-06T17:31:37+08:00","last_success_at":"2026-10-06T17:31:37+08:00","verification_status":"fetched","content_hash":"33864e78c058e36728a2a234704f025356f603b519af3d2d134e58db2a606a7b","history":[{"observed_at":"2026-10-06T17:31:37+08:00","content_hash":"33864e78c058e36728a2a234704f025356f603b519af3d2d134e58db2a606a7b","change_kind":"initial","revision_date":"2021-06-29"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3460&id=GL000618&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3461&id=GL000618&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"宜蘭縣政府執行違章建築取締辦法修正條文對照表.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3910&id=FL023438&type=LAW"},{"name":"宜蘭縣政府執行違章建築取締辦法修正總說明.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3909&id=FL023438&type=LAW"},{"name":"宜蘭縣政府執行違章建築取締辦法.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3911&id=FL023438&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"第一條\n宜蘭縣政府(以下簡稱本府)為落實執行違章建築處理辦法第三條第一項規定\n，特訂定本辦法。\n第二條\n本縣違章建築之劃分日期及處理規定如下:\n一、舊違章建築:八十六年十二月三十一日以前建造者，依違章建築處理辦法\n第十一條第一項規定。\n二、既存違章建築：八十七年一月一日至一百零一年四月二日間建造者，依\n違章建築處理辦法第十一條之一第一項及第二項規定。\n三、新違章建築：一百零一年四月三日以後建造者，依本辦法規定。\n第三條\n本府執行本縣違章建築拆除作業之順序如下：\n一、第一順位:\n(一)施工中之違章建築。\n(二)縣政中心地區之違章建築。\n(三)應申請而未申請雜項執照之樹立廣告及招牌廣告。\n(四)山坡地住宅社區之違章建築。\n(五)危害公共安全、占用公地及妨礙公共交通、公共衛生或市容觀瞻之\n違章建築。\n(六)配合中央政策性方案及本府專案性計畫，應拆除之違章建築。\n二、第二順位：\n面積在三百平方公尺以上之違章建築。\n三、第三順位：\n面積在一百五十平方公尺以上未達三百平方公尺之違章建築。\n四、第四順位：\n面積在三十平方公尺以上未達一百五十平方公尺之違章建築。\n五、第五順位：\n面積未達三十平方公尺之違章建築。\n第四條\n凡涉及私權爭執之違章建築，應由利害關係人循民、刑事訴訟程序辦理。\n第五條\n國軍眷區違章建築之處理，依國軍眷區違章建築處理作業要點之相關處理規\n定。\n第六條\n施工中或拆除重建之違章建築，依本辦法規定強制拆除者，本府得委託民間\n業者辦理；其拆除費用，由本府支付後，向違建人求償之。\n前項拆除費用，本府以書面通知違建人於三十日內繳納，屆期未繳納者，得\n依法移送強制執行。\n第七條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:FL023438","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"修正日期":"民國 112 年 02 月 10 日","全文檔案":"宜蘭縣政府執行違章建築取締辦法.odt","公發布日":"民國 87 年 05 月 21 日","法規名稱":"宜蘭縣政府執行違章建築取締辦法","法規體系":"建設","發文字號":"府秘法字第1120030427B號令","立法理由":"宜蘭縣政府執行違章建築取締辦法修正條文對照表.odt 宜蘭縣政府執行違章建築取締辦法修正總說明.odt"},"promulgation_date":"1998-05-21","revision_date":"2023-02-10","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=FL023438","status":"unknown","title":"宜蘭縣政府執行違章建築取締辦法","last_checked_at":"2026-10-06T17:31:14+08:00","last_success_at":"2026-10-06T17:31:14+08:00","verification_status":"fetched","content_hash":"d82f8019d5710182e4369914a5a34a653e289324c4ea457b2dd0ad63a1f63219","history":[{"observed_at":"2026-10-06T17:31:14+08:00","content_hash":"d82f8019d5710182e4369914a5a34a653e289324c4ea457b2dd0ad63a1f63219","change_kind":"initial","revision_date":"2023-02-10"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3910&id=FL023438&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3909&id=FL023438&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3911&id=FL023438&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"(1140602)宜蘭縣政府執行違章建築強制拆除達不堪使用認定要點.pdf","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=5099&id=GL000786&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、宜蘭縣政府（以下簡稱本府）為執行違章建築處理辦法第三條第一項規定，\n認定違章建築之強制拆除事項，特訂定本要點。\n二、本府執行違章建築強制拆除達不堪使用之認定，其基準如下：\n(一)構造種類以鋼骨造、鋼骨鋼筋混凝土造或鋼筋混凝土造之屋頂、樓板、\n牆壁及樓梯：除保留必要之拆除作業空間外，其餘拆除須達二分之一以\n上；梁柱，得予免拆。\n(二)其餘材料以鐵皮、鋼架、石棉瓦、竹木等構造之屋頂、樓板、牆壁及樓\n梯：全部拆除。\n(三)圍牆、廣告物及其支架：全部拆除。\n(四)騎樓鐵捲門及其他違建：全部拆除，並回復騎樓功能。\n三、主要構造拆除後，雖未達前點基準範圍，但符合下列情形之一，且經本府派\n員勘查認定確實已達不堪使用者，得免予繼續執行拆除：\n(一)基於拆除技術或拆除安全考量，無法完成拆除。\n(二)拆除行為有損及鄰房、合法共同壁之虞。\n四、違章建築經認定拆除達不堪使用後，如有危害公共安全、占用公有地及妨礙\n公共通行、公共衛生或市容觀瞻者，仍應全部拆除。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:GL000786","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"全文檔案":"(1140602)宜蘭縣政府執行違章建築強制拆除達不堪使用認定要點.pdf","公發布日":"民國 114 年 06 月 02 日","法規名稱":"宜蘭縣政府執行違章建築強制拆除達不堪使用認定要點","法規體系":"建設","發文字號":"府建使字第1140082137A號令"},"promulgation_date":"2025-06-02","revision_date":"2025-06-02","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=GL000786","status":"unknown","title":"宜蘭縣政府執行違章建築強制拆除達不堪使用認定要點","last_checked_at":"2026-10-06T17:31:35+08:00","last_success_at":"2026-10-06T17:31:35+08:00","verification_status":"fetched","content_hash":"0b2ba15fe02dda5a2b6d86f4c00f6d9e4c0649359c4b384629268525accffc41","history":[{"observed_at":"2026-10-06T17:31:35+08:00","content_hash":"0b2ba15fe02dda5a2b6d86f4c00f6d9e4c0649359c4b384629268525accffc41","change_kind":"initial","revision_date":"2025-06-02"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=5099&id=GL000786&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"(1130627)宜蘭縣政府執行違章建築查報作業原則.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4695&id=FL046532&type=LAW"},{"name":"附件.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3751&id=FL046532&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、宜蘭縣政府(以下簡稱本府)為劃定本府、各鄉鎮市公所等機關對於違章建\n築查報之權責，並考量違章建築存在期間之長短，對公共安全危害之程度\n等因素，將查報作業區分為免予查報、暫免查報及應予查報等三種處理情\n形，爰訂定本作業原則。\n二、本作業原則所稱之違章建築，為建築法適用地區內，未依法申請本府主管\n建築機關之審查許可並發給執照，而擅自興建之建築物。\n三、違建查報權責:\n(一)依違章建築處理辦法第三條規定由各鄉(鎮、市）公所(以下簡稱公所\n)指定人員辦理。\n(二)國軍眷區八十五年二月五日以後新增之違章建築，依國軍眷區違章建\n築處理作業要點由眷區主管機關(單位）舉報，並會同本府勘查、認定\n及拆除。\n(三)公有土地遭占用違建者，土地管理機關(單位）應循民法處理侵占行為\n或提供占用人資料通知公所查報。被占用土地如屬國有公用者，其違建\n之處理應依各機關經管國有公用被占用不動產處理原則規定辦理。\n(四)國道五號高速公路路權範圍內之違章建築，經內政部指定交通部高速公\n路局為主管建築機關，免由公所查報辦理。\n(五)施工中違建之查報應依宜蘭縣政府處理施工中違建查報及拆除作業要點\n規定辦理。\n四、 查報作業原則:\n(一)免予查報：\n1.民國八十一年一月十日以前興建完成之建築物符合台灣省違章建築拆\n除認定基準之規定者。\n2.原有合法房屋之屋架未有過半更換或修理，其餘椼條、椽子、屋面板\n及屋面瓦全部翻修、雖翻修範圍過半，仍不視為修建行為。\n3.陽台欄杆及女兒牆等修建，其高度在一點五公尺以下者。\n4.設於建築基地內之假山水等景觀設施，未構成建築物者。\n5.領有使用執照之合法建築物，其四周原無壁體 (不含開放空間、停車\n空間)，已計入建築面積之空間，加設門窗或外牆者。\n6.建築物外牆加裝伸縮式帆布棚架及附於建築物之固定雨棚，且無立柱\n者。\n7.圍牆如以鐵絲網或竹籬建造、不鏽鋼條漏空構築等，設置高度未達一\n點五公尺者。\n8.經農業主管機關認定之農業用地上與農業經營不可分離之農漁業產銷\n必要設施，其構造僅為一層，且面積在四十五平方公尺以下者。\n9.可得隨時移動，非定著於土地上或地面下，不足以構成建築物之攤架\n或守望相助崗亭等類似物。\n10.屋頂設置電信無線電接收天線架，其高度未超過九公尺或地面上以\n鋼管電桿式設置者，其高度未超過三十五公尺等，非屬雜項工作物\n者。\n11.砂石場、石化廠內架設之輸送帶及其鐵架生產設備，非屬雜項工作\n物者。\n12.建築物屋頂搭蓋活動式鴿舍，高度未超出一點五公尺或面積未超出\n六平方公尺者。\n13.設置地磅，非屬建築法第七條雜項工作物範圍者。\n(二)暫免查報：\n1.民國八十六年十二月三十一日以前之舊違章建築，如無妨礙公共安全\n、公共交通、公共衛生、都市景觀及都市計畫，拍照列管。\n2.領有使用執照之合法建築物，僅在陽台加裝窗戶，而未將原有外牆拆\n除者。\n3.建築物前方之空地或退縮地，自建築線退縮三十公分或私設通路邊線\n，以竹、木、金屬等構材搭建無壁體之透光遮雨棚。但市地重劃、區\n段徵收或整體開發地區，依法應維持供公眾通行使用之範圍不適用之\n。\n4.房屋因防水需要，須於原屋頂上以防水構材搭建，屋脊高度在二點一\n公尺以下之無壁體構造物或屋脊高度在一點五公尺以下之有壁體構造\n物。\n5.在不影響公共通行，非屬前款第七目構造形式之圍牆，其高度一點二\n公尺以下者。\n(三)應予查報：違章建築非屬免予查報或暫免查報之情形者。\n五、查報單格式如附件。\n圖表附件：\n附件.odt","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:FL046532","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"修正日期":"民國 113 年 06 月 27 日","全文檔案":"(1130627)宜蘭縣政府執行違章建築查報作業原則.odt","公發布日":"民國 94 年 06 月 03 日","法規名稱":"宜蘭縣政府執行違章建築查報作業原則","法規體系":"建設","發文字號":"府建使字第1130100825號函"},"promulgation_date":"2005-06-03","revision_date":"2024-06-27","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=FL046532","status":"unknown","title":"宜蘭縣政府執行違章建築查報作業原則","last_checked_at":"2026-10-06T17:31:24+08:00","last_success_at":"2026-10-06T17:31:24+08:00","verification_status":"fetched","content_hash":"8e68d4a332b3712ba81016abf45999ed44d3e5a509becbcf3d6d71e1733b85a1","history":[{"observed_at":"2026-10-06T17:31:24+08:00","content_hash":"8e68d4a332b3712ba81016abf45999ed44d3e5a509becbcf3d6d71e1733b85a1","change_kind":"initial","revision_date":"2024-06-27"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4695&id=FL046532&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3751&id=FL046532&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"(1130311)宜蘭縣政府審查營建賸餘土石方資源堆置處理場申請案件收費標準.pdf","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4640&id=GL000746&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"第一條\n本標準依規費法第十條第一項規定訂定之\n。\n第二條\n宜蘭縣政府依宜蘭縣營建賸餘土石方管理自治條例受理土石方資源堆置\n處理場（以下稱土資場）申請案件時，應向申請人收取審查費或登記費\n，其收費數額如下：\n一、審查費：\n(一)申請設置許可、變更興辦事業計畫許可或廢止營運許可，每件\n新臺幣一萬元。\n(\n二\n)\n申請營運許可及營運期限展延許可，每件新臺幣三千元。\n二、登記費：申請土資場負責人變更或其住居所變更，每件新臺幣三千\n元。\n第三條\n依前條規定繳納規費後，除有溢繳或誤繳情形，得依規費法相關規定辦\n理外，不得申請退費。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:GL000746","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"全文檔案":"(1130311)宜蘭縣政府審查營建賸餘土石方資源堆置處理場申請案件收費標準.pdf","公發布日":"民國 113 年 03 月 11 日","法規名稱":"宜蘭縣政府審查營建賸餘土石方資源堆置處理場申請案件收費標準","法規體系":"建設","發文字號":"府秘法字第1130039356B號令"},"promulgation_date":"2024-03-11","revision_date":"2024-03-11","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=GL000746","status":"unknown","title":"宜蘭縣政府審查營建賸餘土石方資源堆置處理場申請案件收費標準","last_checked_at":"2026-10-06T17:31:11+08:00","last_success_at":"2026-10-06T17:31:11+08:00","verification_status":"fetched","content_hash":"b579967c5ee9e87dc6ba9cd5b2bbea966849312dc05dacae72ff424c92510da1","history":[{"observed_at":"2026-10-06T17:31:11+08:00","content_hash":"b579967c5ee9e87dc6ba9cd5b2bbea966849312dc05dacae72ff424c92510da1","change_kind":"initial","revision_date":"2024-03-11"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4640&id=GL000746&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"(1150717)宜蘭縣政府建築法令研討小組設置要點.pdf","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=5719&id=GL000048&type=LAW"},{"name":"附表.doc","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=669&id=GL000048&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、宜蘭縣政府\n（\n以下簡稱本府\n）\n為研訂本府建築自治法規及處理建\n築法規適用疑義事項，特設置「宜蘭縣政府建築法令研討小組」\n（\n以下簡稱本小組\n）\n，並訂定本要點。\n二、本小組置委員十三人，其中一人為召集人，由本府建設處處長兼\n任，一人為副召集人，由本府建築管理科科長兼任；其餘委員由\n本府就下列機關\n（\n單位\n）\n、團體人員聘\n（\n派\n）\n兼之：\n(一)資深之建築、法律相關專家或學者二人。\n(二)宜蘭縣建築師公會會員代表二人。\n(三)宜蘭縣地政士公會會員代表一人。\n(四)臺灣區綜合營造業同業公會宜蘭縣辦事處會員代表一人。\n(五)宜蘭縣不動產開發商業同業公會會員代表一人。\n(六)本府秘書處法制科長。\n(七)本府建設處技正、都市計畫科科長及使用管理科科長。\n本小組委員任一性別比例，不得少於委員總數三分之一。\n三、本小組委員任期二年，任滿得續聘\n（\n派\n）\n兼之；代表機關\n（\n單位\n）\n或團體兼任者，隨其本職進退。\n委員出缺時，本府得予補聘；補聘委員之任期至原委員任期屆滿\n之日止。\n四、法令研討之提案應依附表內容詳列並附相關說明文件；本小組之\n幕僚作業，由本府建設處建築管理科辦理，負責提送本小組討論\n議案之研擬等事宜。\n圖表附件：\n附表.doc\n五、本小組會議由召集人視實際需要召開，並擔任主席；召集人因故\n不能出席時，由副召集人代理；其餘委員應親自出席會議，不得\n委託他人代理。\n六、本小組會議應有全體委員二分之一以上出席始得開會，並經出席\n委員二分之一以上之同意方得決議。\n七、委員對於討論議案有利害關係者，準用行政程序法第三十二條及\n第三十三條之規定自行或申請迴避。\n八、本小組開會時得邀請與議案有關單位人員列席。\n九、本小組委員為無給職。\n十、本小組對外行文，以本府名義為之。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:GL000048","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"修正日期":"民國 115 年 07 月 17 日","全文檔案":"(1150717)宜蘭縣政府建築法令研討小組設置要點.pdf","公發布日":"民國 99 年 07 月 09 日","法規名稱":"宜蘭縣政府建築法令研討小組設置要點","法規體系":"建設","發文字號":"府建管字第1150118696號函"},"promulgation_date":"2010-07-09","revision_date":"2026-07-17","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=GL000048","status":"unknown","title":"宜蘭縣政府建築法令研討小組設置要點","last_checked_at":"2026-10-06T17:31:22+08:00","last_success_at":"2026-10-06T17:31:22+08:00","verification_status":"fetched","content_hash":"43b128679fc9931c29e7b5a69d75a4575a4745974afe46d2d6d5e999d0f6b008","history":[{"observed_at":"2026-10-06T17:31:22+08:00","content_hash":"43b128679fc9931c29e7b5a69d75a4575a4745974afe46d2d6d5e999d0f6b008","change_kind":"initial","revision_date":"2026-07-17"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=5719&id=GL000048&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=669&id=GL000048&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、依據：行政院八十九年六月十六日八十九內一七六一○號函核定「建\n築物實施耐震能力評估及補強方案」第六條第三項規定訂定。\n二、諮詢小組任務：\n（一）協助政府推動「建築物實施耐震能力評估及補強方案」之規劃與執\n行。\n（二）協助政府提供建築物所有權人或使用人技術諮詢。\n（三）協助政府辦理「建築物實施耐震能力評估及補強方案」之訓練及講\n習。\n（四）協助政府審查建築物之耐震能力評估報告書。\n（五）協助政府實地複查建築物之耐震能力評估。\n（六）協助政府抽查建築物之耐震能力評估。\n（七）協助政府建立辦理「建築物實施耐震能力評估及補強方案」之人才\n資料庫。\n三、諮詢小組成員：召集人、副召集人、執行長各一人、組員八至二十一\n人。\n（一）召集人：建設處處長兼任之。\n（二）執行長：建設處使用管理科科長兼任之。\n（三）組員：（由本府就下列人員聘兼之）\n1.建築師公會會員經專案輔導團講習並持有講習證明文件者。\n2.土木技師公會會員經專案輔導團講習並持有講習證明文件者。\n3.結構工程技師公會會員經專案輔導團講習並持有講習證明文件者\n。\n4.專案輔導團研究員以上之成員。專案輔導團中本府之諮詢委員得\n優先聘兼之。\n四、組員任期為二年，期滿得續聘之，組員因故出缺時本府應予補聘。\n五、諮詢小組受理案件原則以各公會認為有疑義之案件或由縣政府排定抽\n查之案件為主。諮詢小組之組員均為無給職。但非由縣政府人員兼任\n者，得依規定支給兼職酬勞。\n六、諮詢小組決議事項，得由本府名義行之。\n七、本要點奉縣長核定後實施，修正時亦同。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:FL039048","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"修正日期":"民國 97 年 04 月 14 日","公發布日":"民國 95 年 04 月 26 日","法規名稱":"宜蘭縣政府建築物實施耐震能力評估及補強方案諮詢小組設置要點","法規體系":"建設","發文字號":"府建使字第0970048796號"},"promulgation_date":"2006-04-26","revision_date":"2008-04-14","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=FL039048","status":"unknown","title":"宜蘭縣政府建築物實施耐震能力評估及補強方案諮詢小組設置要點","last_checked_at":"2026-10-06T17:31:33+08:00","last_success_at":"2026-10-06T17:31:33+08:00","verification_status":"fetched","content_hash":"bad90b75a0fe98f1095492a8a84d8887c4dfb0f1d675f2bd63404748b8637984","history":[{"observed_at":"2026-10-06T17:31:33+08:00","content_hash":"bad90b75a0fe98f1095492a8a84d8887c4dfb0f1d675f2bd63404748b8637984","change_kind":"initial","revision_date":"2008-04-14"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"宜蘭縣政府建造執照預審小組設置要點.pdf","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3464&id=FL041758&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、宜蘭縣政府（以下簡稱本府）為審理建造執照申請預審案件，依建造\n執照預審辦法第三條之規定，設宜蘭縣政府建造執照預審小組（以下\n簡稱本小組），並訂定本要點。\n二、本小組受理之建造執照申請預審案件，不含建築物特殊結構及加強山\n坡地雜項執照審查之申請。\n三、本小組置委員十一人，其中一人為召集人，由本府建設處處長兼任；\n一人為副召集人，由本府建設處建築管理科科長兼任；其餘委員由本\n府就下列人員聘（派）兼之：\n（一）具有都市計畫、環境規劃、建築、交通、結構等有關學術專長\n或實務經驗之學者專家代表共四人。\n（二）本縣建築師公會代表二人。\n（三）本府建設處技正、國土計畫科科長及使用管理科科長。\n四、本小組委員任期二年，期滿得續聘（派）兼之。府外委員於任期內辭\n任且任期餘六個月以上者，隨時改聘，並續任至原任期屆滿。府內委\n員因故無法出席會議時，得由職務代理人代表出席。\n五、本小組依受理案件情況，由召集人召開審查會議，於每月底開會一次\n，審理該月二十日前申請預審案件。召集人因故不能出席，得指定職\n務代理人或委員一人為主席。\n六、本小組會議之決議，以委員過半數之出席，出席委員過半數之同意行\n之。出席委員之同意與不同意意見人數相同時，取決於主席。\n七、設計建築師應親自或指派代表列席說明，並得由專業人員陪同列席說\n明。\n八、委員對於預審案件有利害關係者，準用行政程序法第三十二條及第三\n十三條之規定自行或申請迴避。\n九、本小組委員為無給職。但非由本府人員兼任者，得支給出席費及交通\n費。\n十、本小組所需經費，由相關科目項下支應。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:FL041758","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"修正日期":"民國 110 年 07 月 01 日","全文檔案":"宜蘭縣政府建造執照預審小組設置要點.pdf","公發布日":"民國 96 年 01 月 12 日","法規名稱":"宜蘭縣政府建造執照預審小組設置要點","法規體系":"建設","發文字號":"府建管字第1100106009號函"},"promulgation_date":"2007-01-12","revision_date":"2021-07-01","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=FL041758","status":"unknown","title":"宜蘭縣政府建造執照預審小組設置要點","last_checked_at":"2026-10-06T17:31:26+08:00","last_success_at":"2026-10-06T17:31:26+08:00","verification_status":"fetched","content_hash":"c463170a9fff410904c434c5060d1ccaa502ec959e84cc4a0bfc1a0a30b0ef03","history":[{"observed_at":"2026-10-06T17:31:26+08:00","content_hash":"c463170a9fff410904c434c5060d1ccaa502ec959e84cc4a0bfc1a0a30b0ef03","change_kind":"initial","revision_date":"2021-07-01"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3464&id=FL041758&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"宜蘭縣政府所屬機關學校工程委託代辦作業要點.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3287&id=GL000656&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、宜蘭縣政府(以下簡稱本府)為規範所屬各機關學校(以下簡稱洽辦\n機關)委託本府建設處(以下簡稱代辦單位)代辦公共工程(以下簡\n稱工程)，特訂定本要點。\n二、代辦單位代辦之工程範圍如下：\n(一)採購金額達政府採購法查核金額以上者。\n(二)其他特殊原因報經本府核定者。\n三、洽辦機關就工程之設計至施工階段，以全程委託代辦單位代辦為\n原則。\n四、洽辦機關委託代辦工程，應與代辦單位簽訂代辦協議書；本府各\n單位委託應簽辦代辦協議文件。\n前項代辦協議書及協議文件格式由本府定之。\n五、代辦工程工程管理費之預算全額，由代辦單位動支使用為原則。\n本府秘書處代辦採購代辦費由代辦單位自工程管理費支應。\n六、工程移交接管及保固作業階段，依下列規定辦理：\n(一)代辦單位應於正式驗收合格移交接管後，將建築執照或建築\n許可文件、驗收合格文件副本、工程維護使用手冊及竣工圖\n說等相關資料，送洽辦機關收存續辦。\n(二)工程於正式接管後之保固期限內，如發現有屬工程契約保固\n範圍之瑕疵，由接管單位主動辦理會勘，並通知代辦單位，\n後續由代辦單位督導該廠商依契約檢修完成，並副知洽辦機\n關；如因使用、管理或保養不當而發生不屬廠商保固責任之\n瑕疵損害，則由洽辦機關自行處理。代辦單位於退還保固保\n證金前，應先徵得洽辦機關之同意。\n(三)代辦工程完工驗收後，洽辦機關如有原委託代辦協議文件約\n定以外之其他需求，應由洽辦機關自行辦理或另案委託代辦\n。\n七、本府各單位經首長核可由代辦單位代辦工程者，準用本要點之規\n定。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:GL000656","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"公發布日":"民國 109 年 11 月 17 日","法規名稱":"宜蘭縣政府所屬機關學校工程委託代辦作業要點","法規體系":"建設","發文字號":"府建工字第1090190747號函","立法理由":"宜蘭縣政府所屬機關學校工程委託代辦作業要點.odt"},"promulgation_date":"2020-11-17","revision_date":"2020-11-17","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=GL000656","status":"unknown","title":"宜蘭縣政府所屬機關學校工程委託代辦作業要點","last_checked_at":"2026-10-06T17:31:26+08:00","last_success_at":"2026-10-06T17:31:26+08:00","verification_status":"fetched","content_hash":"69537ca92a92ec482d9decc945667a3aee1608fb2988154fb8a5cc2752b5b31d","history":[{"observed_at":"2026-10-06T17:31:26+08:00","content_hash":"69537ca92a92ec482d9decc945667a3aee1608fb2988154fb8a5cc2752b5b31d","change_kind":"initial","revision_date":"2020-11-17"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3287&id=GL000656&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、宜蘭縣政府（以下簡稱本府）為執行營造業法(以下簡稱\n本法)第十七條及第三十四條第一項規定之營造業及其專\n任工程人員受聘情形抽查作業，特訂定本要點。\n二、本要點適用之範圍為於本縣辦理營造業登記或於本縣承攬\n工程之營造業。\n三、營造業有下列情形之一，列為優先抽查：\n(一)經各機關、團體及人民移送、函告、檢舉等有違法情\n事者。\n(二)至本府辦理營造業各項變更登記業務，有違反本法規\n定者。\n(三)曾有未配合抽查或未依規定提供專任工程人員（含逐\n案簽證之建築師或技師）相關文件者。\n四、抽查作業由本府派員不定期至營造業營業登記地址、承攬\n工程現場、申報開工現場或於本府指定之地點辦理。\n五、本府執行抽查時，營造業應檢具公司負責人及其專任工程\n人員（含逐案簽章之建築師或技師）之身分證影本、承攬\n工程手冊、營造業登記證書、專任工程人員資格證明書及\n受聘同意書、公司登記或商業登記證明文件、營利事業所\n得結算申報書、營業稅銷售額及稅額申報書、勞健保投保\n資料及薪資所得資料，以供抽查人員核對。\n六、本府於工程現場抽查時，營造業應提出所承攬興建中工程\n之施工計畫書、開工報告或竣工報告、工程查驗文件或申\n報勘驗文件以供查核，該營造業專任工程人員應到場協助\n說明。\n七、營造業未依第五點規定辦理者，本府得函請財政部、勞工\n保險局、中央健保局提供薪資所得稅籍資料、勞保及健保\n投保登記資料，逕予查核。\n營造業之專任工程人員有違反本法第三十四條規定者\n，依本法第六十一條規定辦理。\n八、營造業拒絕、妨礙或規避本府抽查者，依本法第五十五條\n第一項第三款規定辦理。\n九、營造業經抽查後，如不合規定時，由本府列舉事由通知限\n期補正，逾期未補正者，依本法第五十六條第一項規定辦\n理。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:GL000362","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"公發布日":"民國 103 年 12 月 09 日","法規名稱":"宜蘭縣政府抽查營造業作業要點","法規體系":"建設","發文字號":"府建管字第1030201130B號 函"},"promulgation_date":"2014-12-09","revision_date":"2014-12-09","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=GL000362","status":"unknown","title":"宜蘭縣政府抽查營造業作業要點","last_checked_at":"2026-10-06T17:31:29+08:00","last_success_at":"2026-10-06T17:31:29+08:00","verification_status":"fetched","content_hash":"e208314b830e13f9b2e79df24731c5805dd302e70141136d5b7412eadcd59f6d","history":[{"observed_at":"2026-10-06T17:31:29+08:00","content_hash":"e208314b830e13f9b2e79df24731c5805dd302e70141136d5b7412eadcd59f6d","change_kind":"initial","revision_date":"2014-12-09"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"(1130319)宜蘭縣政府施工中建築工程災害緊急應變標準作業要點.pdf","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4638&id=GL000748&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、為處理施工中建築工程災害防救事宜並配合宜蘭縣災害應變中心執行災害\n應變措施，特訂定本標準作業要點。\n二、本要點依災害防救法第十二條及第二十四條規定訂定之。\n三、任務：\n(一)工地重大災害發生，經通報後，立即依照本作業要點進行編組救災。\n(二)執行施工中建築工程災害之應變事項及災害應變有關措施。\n(三)執行災情調查評估、通報、緊急救災人力、物資之調度及支援策略之\n擬訂事項。\n(四)執行其他有關災害緊急應變事宜及臨時交付任務。\n四、本編組係臨時性任務編組，依本要點成立宜蘭縣政府（以下簡稱本府）施\n工中建築工程災害緊急應變專案小組（以下簡稱本小組）成員五人至十人\n，小組成員及編組成員由各級開設任務編組機關（單位）派員擔任，除執\n行本機關（單位）與該災害有關事項外，並與其他關係局、處單位保持密\n切聯繫，策劃應變對策，採取必要措施：\n(一)召集人一人：由縣長兼任，進行總指揮調度。\n(二)副召集人二人：由副縣長、秘書長兼任。\n(三)執行秘書一人：由本府建設處處長兼任，進行現場指揮調度處理及對\n外說明。\n(四)小組成員：宜蘭縣政府消防局、宜蘭縣政府警察局、本府建設處、本\n府秘書處。\n(五)編組成員：宜蘭縣政府衛生局、宜蘭縣政府環境保護局、本府消保官\n、本府社會處、本府民政處、本府交通處、本府計畫處、本府勞工處\n、本府水利資源處、本府工商旅遊處、宜蘭縣各鄉(鎮、市)公所。\n五、開設時機︰施工中建築工程發生倒塌、損壞等重大災害造成下列情形之一\n者：\n(一)造成估計有十五人以上傷亡、失蹤、亟待救助者。\n(二)災害有擴大之虞者。\n(三)須本府應變處置時或經通報本府研判有開設必要者。\n六、開設方式：建築工程災害發生或有發生之虞時，本府建設處處長應視災害\n之規模、性質、災情、影響層面及緊急應變措施等狀況，報告縣長決定本\n小組之開設。\n七、本小組相關進駐機關（單位）之權責及應執行任務內容分別如列：\n小組成員：\n(一)宜蘭縣政府消防局：\n1.執行調度災害搶救、傷患救護及人命救助。\n2.依指令執行人員緊急避難疏散撤離作業。\n(二)宜蘭縣政府警察局：\n1.辦理有關災區替代道路規劃、交通狀況調查、管制、疏導等交通管\n制事項。\n2.辦理災區警戒、治安維護、人員緊急疏散等事項。\n3.依指令執行人員緊急避難疏散撤離作業。\n4.其他有關警政工作事項\n(三)本府建設處：\n1.災情彙整事項。\n2.災情通報事項。\n3.接獲重大災害通報立即聯繫專業公會調派相關技術人員進駐並進行\n相關災害評估以供召集人決策：\n(1)確認災變原因及協助擬定解決方案。\n(2)確認災害範圍。\n(3)確認災民撤離範圍。\n(4)於現場建立災民諮詢窗口及建立諮詢專線。\n4.控管並要求開發單位進行：\n(1)災害後勤事項。\n(2)災情評估事項。\n(3)災害緊急應變措施擬定及執行事項。\n(4)搶災搶險人員、機具調度事項。\n(5)成立災害專責辦公室。\n(6)辦理災害庶務工作。\n(7)辦理後續委託鑑定工作。\n(8)其他有關災情處理事項。\n5.確認災害緊急應變措施內容，必要時聯繫本府相關開口契約廠商配\n合搶災作業。\n6.辦理相關說明會。\n(四)本府秘書處：\n1.彙整各單位信息，並擬定發布訊息。\n2.發布新聞稿並運用不同管道，說明災情、提醒民眾配合事宜及各項\n因應作為。\n3.協助媒體進行採訪及各項與媒體溝通事宜。\n4.監測輿情並利用相關管道，適時澄清有關災情之不實報導與謠言。\n5.受理損害賠償、合約爭議等相關法律、求償管道諮詢事宜。\n編組成員：\n(一)宜蘭縣政府衛生局：\n1.於災害現場成立醫療站、負責傷患現場救護及後送就醫調度事宜。\n2.辦理急救用醫療器材儲備、運用、供給事項。\n3.辦理災後家戶消毒、衛生改善輔導、災區傳染病預防及災區食品衛\n生管理事項。\n4.辦理災後心理衛生服務及諮詢管道。\n5.其他有關衛生業務權責事項。\n(二)宜蘭縣政府環境保護局：\n1.督導各鄉(鎮、市)公所辦理災區公共環境清理。\n2.災區有關消毒清潔事項。\n3.其他有關環保等災害應變之協調及業務權責事項。\n(三)本府消保官：協助事件發生後產生預售建案之合約爭議事件。\n(四)本府社會處：\n1.會同當地鄉鎮市公所開設災民收容處所，辦理協助災民進駐收容處\n所相關事項。\n2.辦理災民民生物資調查、募集與發放工作，以及接受社會大眾捐贈\n民生物資與轉發作業事項。\n3.開設災民關懷站，會同民間團體志工進行關懷慰問災民及罹難者家\n屬，並協助連結社會資源。\n4.協助災民申請災害救助金及相關補助。\n5.其他有關災民救濟事項。\n(五)本府民政處：\n1.督導各鄉(鎮、市)公所辦理災情查報。\n2.辦理罹難者屍體處理及家屬服務有關事項。\n3.國軍支援救災聯繫事宜。\n4.依指令執行人員緊急避難疏散撤離作業。\n5.其他有關民政權責事項。\n(六)本府交通處︰\n1.辦理交通運輸工具之徵用，協助災民及相關人員交通接駁等調度事\n項。\n2.其他有關交通應變措施事項。\n(七)本府計畫處：\n1.建立並統一災民現場及線上陳情窗口。\n2.彙整災民陳情事項通知各權責單位協助處理。\n3.提供各單位資訊設備簡易維修，協助收集災區各項資料整合建置資\n訊網站。\n(八)本府勞工處：\n1.辦理職業災害應變小組幕僚作業事項。\n2.辦理災區有關勞工職業災害權益維護。\n3.其他有關勞工業務權責事項。\n(九)本府水利資源處：\n1.水利及防洪設施之搶修、搶險及災情查報事項。\n2.災害時動員各類專家技術人員及營繕機構協助水利及防洪設施救災\n有關事項。\n(十)本府工商旅遊處：\n1.電力、電訊、油槽設施、工業管線、瓦斯、自來水等維生系統緊急\n搶修聯繫事項。\n2.協助接洽旅館商業同業公會及彙整可做災民臨時收容、住宿等場所\n調度事項。\n(十一)宜蘭縣各鄉(鎮、市)公所：\n1.配合開設災害應變中心運作以提供相關協助。\n2.災民之登記、接待及管理事項。\n3.災民統計、查報及其他有關事故之處理事項。\n4.緊急安置所之指定，分配佈置事項。\n5.災民救濟資源之發放事項。\n6.受災損害之救濟事項。\n7.各界捐贈救災物資之接受與轉發事項。\n8.其他有關業務權責事項。\n八、作業程序：\n(一)經本府建設處會同專業公會研判及進駐。\n(二)本小組開設地點擇就近地點開設進駐運作。\n(三)搶災作業以災害搶救、傷患救護及人命救助為首要執行任務，依消防\n局調度，並由建設處及專業公會輔助評估搶災必要措施之作業內容。\n(四)本小組成立及撤除以書面或口頭報請召集人決定後，通知相關機關（\n單位）據以處理。\n(五)災害發生或有發生之虞時，各進駐機關（單位）之人員應立即瞭解相\n關災情，並掌握各該編組機關（單位）應變處置情形，隨時向召集人\n報告處置狀況。\n(六)縮小編組時機：災害狀況已不再繼續擴大或災情已趨緩和時，召集人\n得縮小編組規模，對已無執行應變任務需要者予以歸建。\n(七)撤除時機：災害緊急應變處置已完成，後續復原重建可由各相關機關\n（單位）自行辦理時，執行秘書得以口頭或書面報告召集人撤除本小\n組。\n九、本小組撤除後，各單位應持續依權責協助民眾相關補助、諮詢事宜，本府\n建設處應督導建築工程起造人、監造人及承造人接續辦理災後復原重建工\n作。\n十、有關因搶災衍生之相關費用由開發單位全額負擔。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:GL000748","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"全文檔案":"(1130319)宜蘭縣政府施工中建築工程災害緊急應變標準作業要點.pdf","公發布日":"民國 113 年 03 月 19 日","法規名稱":"宜蘭縣政府施工中建築工程災害緊急應變標準作業要點","法規體系":"建設","發文字號":"府建管字第1130037050號函"},"promulgation_date":"2024-03-19","revision_date":"2024-03-19","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=GL000748","status":"unknown","title":"宜蘭縣政府施工中建築工程災害緊急應變標準作業要點","last_checked_at":"2026-10-06T17:31:25+08:00","last_success_at":"2026-10-06T17:31:25+08:00","verification_status":"fetched","content_hash":"5cfae1346507684e05691af702a60b644f5fb7693a4e210a6a54fb916bea488d","history":[{"observed_at":"2026-10-06T17:31:25+08:00","content_hash":"5cfae1346507684e05691af702a60b644f5fb7693a4e210a6a54fb916bea488d","change_kind":"initial","revision_date":"2024-03-19"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4638&id=GL000748&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"(1150402)宜蘭縣政府營建產出物推動小組設置要點.pdf","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=5599&id=GL000814&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、本府為督導及推動宜蘭縣營建產出物管理政策，協調主導營建產出物相關業\n務，設宜蘭縣政府營建產出物推動小組\n（\n以下簡稱本小組\n）\n，特訂定本要點\n。\n二、本要點所稱營建產出物，包含營建賸餘土石方、營建廢棄物及其他經本小組\n認定之物料。\n三、本小組任務如下：\n（\n一\n）\n推動轄內工程營建產出物減量及平衡。\n（\n二\n）\n擴增營建產出物去化管道。\n（\n三\n）\n落實營建產出物全流向追蹤機制。\n（\n四\n）\n其他本府主導營建產出物管理協調有關事項。\n四、本小組設置委員十一人至十三人，其中一人為召集人，由本府秘書長兼任；\n一人為副召集人，由本府建設處\n（\n以下簡稱建設處\n）\n處長兼任；其餘委員由\n本府就下列機關（單位）、團體人員聘（派）兼之：\n（一）本府地政處。\n（二）本府農業處。\n（三）本府水利資源處。\n（四）本府工商旅遊處。\n（五）本府民政處。\n（六）本府環境保護局。\n（七）本府建設處。\n（八）營造及不動產開發公會代表及學者專家二人至四人。\n本小組置執行秘書一人，由建設處科長以上人員兼任，承召集人之命，綜理\n本小組幕僚業務。另置工作人員若干，由地政處、農業處、水利資源處、工\n商旅遊處、民政處及環境保護局各派一員兼任。\n本小組委員任一性別比例，不得少於委員總數三分之一。\n五、本小組委員任期二年，任滿得續聘（派）兼之；代表機關（單位）或團體兼\n任者，隨其本職進退。\n委員出缺時，本府得予補聘；補聘委員之任期至原委員任期屆滿之日止。\n六、本小組會議每年召開二次，但因應業務需要，得隨時召開。\n七、本小組會議，由召集人召集並為主席；召集人因故不能出席時，由副召集人\n代理；召集人及副召集人均不能出席時，得由委員互推一人代理之。機關代\n表之委員未能親自出席時，得由機關指派代表代理之。\n八、本小組會議應有委員過半數之出席，決議事項應有出席委員過半數之同意，\n正反意見同數時，由主席裁決之。\n本小組委員對於審議之案件依行政程序法第三十二條或第三十三條規定，有\n應迴避事由時，應依法迴避。\n九、本小組開會時，得視個案性質及實際需要，邀請中央或地方有關機關人員、\n專家或學者列席提供意見，必要時並得由主席選派委員若干人組成專案小組\n調查。\n十、本小組對外行文，以本府名義行之。\n十一、本小組委員及兼任人員均為無給職。但參與開會之專家、學者及相關公會\n代表得依規定支給出席費及交通費。\n十二、本小組所需經費由建設處編列預算支應。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:GL000814","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"全文檔案":"(1150402)宜蘭縣政府營建產出物推動小組設置要點.pdf","公發布日":"民國 115 年 04 月 02 日","法規名稱":"宜蘭縣政府營建產出物推動小組設置要點","法規體系":"建設","發文字號":"府建管字第1150037275號函"},"promulgation_date":"2026-04-02","revision_date":"2026-04-02","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=GL000814","status":"unknown","title":"宜蘭縣政府營建產出物推動小組設置要點","last_checked_at":"2026-10-06T17:31:23+08:00","last_success_at":"2026-10-06T17:31:23+08:00","verification_status":"fetched","content_hash":"52a7c1ea19971b4bc537b6b709586867d6cde3a2a56384476e0282643eefdafe","history":[{"observed_at":"2026-10-06T17:31:23+08:00","content_hash":"52a7c1ea19971b4bc537b6b709586867d6cde3a2a56384476e0282643eefdafe","change_kind":"initial","revision_date":"2026-04-02"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=5599&id=GL000814&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"(1130430)宜蘭縣政府石城稽查站管理要點.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4635&id=GL000705&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、 宜蘭縣政府(以下簡稱本府)為執行檢查載運入境土石方之\n車輛及稽查人員之管理，訂定本要點。\n二、本府設石城稽查站及北宜公路稽查站，置稽查人員十名；\n其值勤時間及每日薪資依下列規定:\n(一)石城稽查站:\n1.早班:\n(1)值勤時間:凌晨零時至上午八時。\n(2)薪資:以中班薪資加新臺幣一百五十元。\n2.中班:\n(1)值勤時間:上午八時至下午四時。\n(2)薪資:依勞動部最新每小時基本工資乘以八小時\n計算。\n3.晚班:\n(1)值勤時間:下午四時至晚上十二時。\n(2)薪資:以中班薪資加新臺幣一百五十元。\n(二)北宜公路稽查站:\n1. 執勤時間：下午十時至上午六時\n2. 薪資：以石城稽查站晚班薪資計算。\n三、稽查人員具勞工身分者，其特別休假依勞動基準法第三十八\n條規定辦理。\n前項稽查人員排定特別休假，應於十五日前向本府提出申請\n；本府依法發給代為值班人員加班費。\n第一項稽查人員之特別休假，因每年年度終結或終止契約而\n未休之日數，本府應發給之工資，依第二點第一款規定三班\n薪資平均值計算之。\n四、接班之稽查人員應提早十分鐘到站進行交班作業(簽到、交辦\n事項)，未能於規定時間內到站時，應先電話通知在班之稽查\n人員。接班之稽查人員未到站前，在班之稽查人員不得擅自\n離開，並應回報本府建設處(以下簡稱主管單位)。\n五、接班之稽查人員逾第二點規定時間二十分鐘以上者，應依規\n定請假，未請假者，該班視同曠職。\n六、因故須請假或調班者，應事先填寫假單或調班單送達或傳真\n至主管單位，非本府上班時間請假，應同時以電話通知主管\n單位承辦人，凡未填寫假單及調班單者，一律以曠職論。\n七、事病假均依勞工請假規則辦理。\n八、除天災或經主管人員通知特殊狀況外，稽查人員應按排班表\n出勤，並應於差勤紀錄表確實簽到及簽退。\n九、稽查人員於執勤時應穿著規定之制服並配戴識別證，夜間應\n增穿反光背心。稽查人員於執勤時不可喝酒、嚼檳榔、口香\n糖、賭博及觀看電視。\n十、稽查人員應於站外值勤負責攔車，並辦理稽查業務，避免載\n運入境土石方車輛闖關。\n十一、稽查人員應負責清理稽查站四周及站內之環境衛生，並應\n將前一日之差勤紀錄表傳真至主管單位。\n十二、稽查人員應對持有流向證明文件(四聯單)及入境三聯單之\n車輛查核載運內容是否與申請內容相符，相符者，簽收三\n聯單後放行；對未持有三聯單之車輛，應查核載運內容，\n如屬生產原料者，應將通行時間、車號、駕駛人姓名、載\n運內容及載運之目的地，登記於未持三聯單載運非土石方\n入境車輛紀錄表後放行。\n稽查人員得代收環境保護主管機關同意核准最終處理事業\n廢棄物之網路申報之委託共同處理管制遞送三聯單及確認\n單後放行，其聯單送本府環境保護局備查。\n非屬前二項情形者，稽查人員應勸阻車輛折返。\n十三、車輛未依規定停車受檢者，稽查人員應通知梗枋攔檢站勸\n阻折返；車輛未依勸阻折返者，梗枋攔檢站駐警人員應記\n錄駕駛人姓名及車牌號碼，並回報稽查人員記錄於差勤紀\n錄表後，由駐警人員護送違規車輛離境。\n十四、本府警察局、環境保護局、農業處、地政處、水利資源處\n、工商旅遊處、民政處及建設處等機關(單位)應派員擔任\n督導官，依排定之日期不定時督導稽查人員執勤情形。\n督導官應依稽查站督導查核紀錄表督導項目進行督導，將\n紀錄表第一聯存於石城稽查站專用資料夾內，第二聯攜回\n本府，並將入境三聯單(第一聯)及相關資料攜回本府轉交\n各目的事業主管機關(單位)收執。\n十五、違反本要點之相關規定累計達三次者，立即解僱。\n十六、稽查人員如有違法之情事，除依法辦理外，並予解僱。\n十七、有關員額管制、僱用及待遇福利部分，比照宜蘭縣政府及\n所屬機關約用人員僱用及管理要點辦理。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:GL000705","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"修正日期":"民國 113 年 04 月 30 日","全文檔案":"(1130430)宜蘭縣政府石城稽查站管理要點.odt","公發布日":"民國 97 年 02 月 14 日","法規名稱":"宜蘭縣政府石城稽查站管理要點","法規體系":"建設","發文字號":"府建管字第1130057883號函"},"promulgation_date":"2008-02-14","revision_date":"2024-04-30","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=GL000705","status":"unknown","title":"宜蘭縣政府石城稽查站管理要點","last_checked_at":"2026-10-06T17:31:24+08:00","last_success_at":"2026-10-06T17:31:24+08:00","verification_status":"fetched","content_hash":"e37c5b4d1f04a6fec9929244e09efae116886a09ad544a09875d987def7f4573","history":[{"observed_at":"2026-10-06T17:31:24+08:00","content_hash":"e37c5b4d1f04a6fec9929244e09efae116886a09ad544a09875d987def7f4573","change_kind":"initial","revision_date":"2024-04-30"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4635&id=GL000705&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"宜蘭縣政府處理建築物擅自建造裁罰基準.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3486&id=GL000405&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、宜蘭縣政府(以下簡稱本府)為處理建築物違反建築法第二十五條\n未經申請許可擅自建造事件之裁罰，特訂定本基準。\n二、違反建築法第二十五條擅自建造，依建築法第八十六條第一款裁\n罰之基準如下：\n(一)已建造建築物造價在新台幣一百萬元以下，處以建築物造價\n千分之三十罰鍰。\n(二)已建造建築物造價逾新台幣一百萬元至新台幣五百萬元者，\n超過新台幣一百萬元部分處以建築物造價千分之四十罰鍰。\n(三)已建造建築物造價逾新台幣五百萬元者，超過新台幣五百萬\n元部分處以建築物造價千分之五十罰鍰。\n三、本府於九十四年七月二十日前列入專案輔導之休閒農場，且已興\n建完成之農場內建築物，處以建築物造價千分之一罰鍰。\n四、民國八十九年八月二十五日前已興建完成且已寺廟登記在案之建\n築物，處以建築物造價千分之五罰鍰。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:GL000405","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"全文檔案":"宜蘭縣政府處理建築物擅自建造裁罰基準.odt","公發布日":"民國 104 年 08 月 21 日","法規名稱":"宜蘭縣政府處理建築物擅自建造裁罰基準","法規體系":"建設","發文字號":"府建管字第1040141000號令"},"promulgation_date":"2015-08-21","revision_date":"2015-08-21","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=GL000405","status":"unknown","title":"宜蘭縣政府處理建築物擅自建造裁罰基準","last_checked_at":"2026-10-06T17:31:40+08:00","last_success_at":"2026-10-06T17:31:40+08:00","verification_status":"fetched","content_hash":"8c7ab3b3d8471edf1e2de0441303310974ac63fda406a3e9a6887fe09af1c23a","history":[{"observed_at":"2026-10-06T17:31:40+08:00","content_hash":"8c7ab3b3d8471edf1e2de0441303310974ac63fda406a3e9a6887fe09af1c23a","change_kind":"initial","revision_date":"2015-08-21"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3486&id=GL000405&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、宜蘭縣政府（以下簡稱本府）為即時有效拆除施工中之違建及執行違\n章建築處理辦法之規定，特訂定本作業要點。\n二、本作業要點應即時拆除之違建，係指未依法申請審查許可而擅自建築\n之施工中違建。\n三、各鄉鎮市公所之查報員（以下簡稱查報員）平日應主動就其轄區進行\n巡查，發現施工中違建時，應依本作業要點第四點規定之程序辦理。\n四、施工中違建之查報及拆除應依下列程序辦理：\n（一）查報員發現屬本作業要點第二點之施工中違建，應於現場張貼勒令\n停工通知單（如附表一）拍照存證，併同查報單（如附表二）函報\n本府。\n（二）施工中之違建經現場張貼勒令停工單後，如有繼續施工情形，查報\n員應立即填發二次勒令停工單張貼並陳報本府依建築法第九十三條\n規定辦理。\n五、本府建設處應就現有人力排定各鄉鎮市責任區之巡查人員（以下簡稱\n巡查員），進行施工中違建查報業務之督導，若發現未被查報之施工\n中違建，應立即責成公所之查報員依本作業要點第四點進行查報工作\n。\n六、查報員應負施工中違建查報之責，如有漏查漏報案件，應提報「宜蘭\n縣政府處理違章建築督導協調會報」（以下簡稱協調會報）依「處理\n違章建築有關人員獎懲辦法」﹙以下簡稱獎懲辦法﹚規定辦理相關人\n員之懲處；對於查報績效良好者，亦提報協調會報依獎懲辦法規定辦\n理相關人員之敘獎。\n七、巡查員應負督導及主動就其責任區進行巡查之責，發現施工中違建時\n，應立即以電話通知所屬之鄉鎮市公所查報人員依本作業要點規定程\n序辦理，巡查人員執行成效應提協調會報依獎懲辦法規定辦理獎懲，\n並列入年度考核。\n八、依本作業要點查報屬應拆除之案件，得由違建人限期自行拆除。\n九、拆除完成之案件，應由巡查員檢附拆除前後之照片，填寫結案單辦理\n結案。\n十、本府於核發使用執照時應同時副本抄送各鄉鎮市公所備查。\n十一、本要點奉縣長核定後實施，修正時亦同。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:FL046082","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"修正日期":"民國 97 年 05 月 15 日","公發布日":"民國 94 年 05 月 05 日","法規名稱":"宜蘭縣政府處理施工中違建查報及拆除作業要點","法規體系":"建設","發文字號":"府建使字第0970064518號"},"promulgation_date":"2005-05-05","revision_date":"2008-05-15","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=FL046082","status":"unknown","title":"宜蘭縣政府處理施工中違建查報及拆除作業要點","last_checked_at":"2026-10-06T17:31:33+08:00","last_success_at":"2026-10-06T17:31:33+08:00","verification_status":"fetched","content_hash":"c3b0b23e38634de6fc19621dc73db3e52fc69d645c5e694c49921100c07d6a72","history":[{"observed_at":"2026-10-06T17:31:33+08:00","content_hash":"c3b0b23e38634de6fc19621dc73db3e52fc69d645c5e694c49921100c07d6a72","change_kind":"initial","revision_date":"2008-05-15"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"665003_108D077134_1080134922-1.pdf","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=2737&id=GL000614&type=LAW"},{"name":"違反營造業法第34條裁罰基準附表.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=2738&id=GL000614&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、宜蘭縣政府(以下簡稱本府)為處理違反營造業法第三十四條第一項所定專任工程人員兼\n任其他綜合營造業、專業營造業之業務或職務事件，特訂定本基準。\n二、營造業專任工程人員違法兼職事件，依營造業法第六十一條第一項規定，裁罰基準如附\n表。\n圖表附件：\n違反營造業法第34條裁罰基準附表.odt\n三、依本基準裁罰之案件，符合行政罰法規定裁處加重或減輕情形者，得敘明理由，加重或\n減輕裁罰之。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:GL000614","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"公發布日":"民國 108 年 08 月 13 日","法規名稱":"宜蘭縣政府處理營造業專任工程人員違法兼職事件統一裁罰基準","法規體系":"建設","發文字號":"府建管字第1080134922B號令","立法理由":"665003_108D077134_1080134922-1.pdf"},"promulgation_date":"2019-08-13","revision_date":"2019-08-13","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=GL000614","status":"unknown","title":"宜蘭縣政府處理營造業專任工程人員違法兼職事件統一裁罰基準","last_checked_at":"2026-10-06T17:31:38+08:00","last_success_at":"2026-10-06T17:31:38+08:00","verification_status":"fetched","content_hash":"193070eb28afb7979a26d8062ce041fb2cb21a44e088eb3f331b43e7af81e30b","history":[{"observed_at":"2026-10-06T17:31:38+08:00","content_hash":"193070eb28afb7979a26d8062ce041fb2cb21a44e088eb3f331b43e7af81e30b","change_kind":"initial","revision_date":"2019-08-13"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=2737&id=GL000614&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=2738&id=GL000614&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、宜蘭縣政府(以下簡稱本府)為處理建築工程逾規定期限始\n申請開工或竣工展期之行政處分，擬審酌違反情節之輕重\n，建立執行之公平性，特訂定本裁量基準。\n二、本府處理逾規定期限申請開、竣工展期之裁罰原則如下：\n(一)逾規定開工期限未達三十日申報開工展期者，處新台\n幣三千元罰鍰。\n(二)逾規定開工期限三十日以上未達六十日申報開工展期\n者，處新台幣六千元罰鍰。\n(三)逾規定開工期限六十日以上申報開工展期者，處新台\n幣九千元罰鍰。\n(四)逾規定竣工期限未達一二○日申報竣工展期者，處新\n台幣三千元罰鍰。\n(五)逾規定竣工期限一二○日以上未達二四○日申報竣工\n展期者，處新台幣六千元罰鍰。\n(六)逾規定竣工期限二四○日以上申報竣工展期者，處新\n台幣九千元罰鍰。\n三、本基準自發布日實施。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:GL000779","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"公發布日":"民國 97 年 12 月 31 日","法規名稱":"宜蘭縣政府處理逾規定期限申請開、竣工展期之裁量基準","法規體系":"建設","發文字號":"府建管字第0970174534A號令"},"promulgation_date":"2008-12-31","revision_date":"2008-12-31","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=GL000779","status":"unknown","title":"宜蘭縣政府處理逾規定期限申請開、竣工展期之裁量基準","last_checked_at":"2026-10-06T17:31:41+08:00","last_success_at":"2026-10-06T17:31:41+08:00","verification_status":"fetched","content_hash":"e8bd6b823feafa73b57b677e158f6d6db05b167f93d8b1f7cd802c6d2c862051","history":[{"observed_at":"2026-10-06T17:31:41+08:00","content_hash":"e8bd6b823feafa73b57b677e158f6d6db05b167f93d8b1f7cd802c6d2c862051","change_kind":"initial","revision_date":"2008-12-31"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"附表.pdf","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=2617&id=GL000594&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、宜蘭縣政府（以下簡稱本府）為處理違反公寓大廈管理條例事件，建\n立執法之公平性，減少爭議，提升本府之公信力，特訂定本基準。\n二、違反公寓大廈管理條例事件統一裁罰基準如附表。\n圖表附件：\n附表.pdf\n三、違規案件依前點基準裁罰，有關連續處罰之基準，第二次罰鍰金額\n以第一次罰鍰金額二倍計算，第三次以上罰鍰金額則以法定罰鍰金\n額上限計算。情節重大或特殊案件，經依行政罰法第十八條規定審\n酌得減輕或加重。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:GL000594","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"公發布日":"民國 108 年 03 月 22 日","法規名稱":"宜蘭縣政府處理違反公寓大廈管理條例事件統一裁罰基準","法規體系":"建設","發文字號":"府建使字第1080046683B號 令"},"promulgation_date":"2019-03-22","revision_date":"2019-03-22","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=GL000594","status":"unknown","title":"宜蘭縣政府處理違反公寓大廈管理條例事件統一裁罰基準","last_checked_at":"2026-10-06T17:31:38+08:00","last_success_at":"2026-10-06T17:31:38+08:00","verification_status":"fetched","content_hash":"df8d7187709cfe2d5a3e3dce4ffc0a198a706f5cc1a38ef979a3fcf00b4e4528","history":[{"observed_at":"2026-10-06T17:31:38+08:00","content_hash":"df8d7187709cfe2d5a3e3dce4ffc0a198a706f5cc1a38ef979a3fcf00b4e4528","change_kind":"initial","revision_date":"2019-03-22"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=2617&id=GL000594&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"(附表)宜蘭縣政府處理違反建築法使用管理規定事件裁罰基準表.pdf","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4102&id=GL000735&type=LAW"},{"name":"(附表)宜蘭縣政府處理違反建築法使用管理規定事件裁罰基準表.pdf","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4100&id=GL000735&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"1\n一、宜蘭縣政府為處理違反建築法（以下簡稱本法）使用管理規定\n事件，建立執法公平性，減少爭議並提升公信力，特訂定本基\n準。\n2\n二、違反本法使用管理規定事件，統一裁罰基準如附表。\n同一行為人就同一建築物，同時違反本法第七十三條第二項、\n第七十七條第一項及第七十七條之二第一項規定二項以上者，\n按下列順序裁罰，並於行政處分書中，一併通知改善其他違規\n事項：\n(\n一)本法第七十三條第二項。\n(\n二)本法第七十七條第一項。\n(\n三)本法第七十七條之二第一項。\n第一項附表次數之累計，以同一行為人最近三年內於同一建築\n物之罰鍰次數論計。\n圖表附件：\n(附表)宜蘭縣政府處理違反建築法使用管理規定事件裁罰基準表.pdf\n3\n三、違規事件依附表裁罰外，其情節重大或為特殊情事，符合行政\n罰法加重或減輕裁罰規定之情形者，得酌予加重或減輕裁罰之\n。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:GL000735","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"公發布日":"民國 112 年 07 月 17 日","圖表附件":"(附表)宜蘭縣政府處理違反建築法使用管理規定事件裁罰基準表.pdf","法規名稱":"宜蘭縣政府處理違反建築法使用管理規定事件統一裁罰基準","法規體系":"建設","發文字號":"府建使字第1120119154B號令"},"promulgation_date":"2023-07-17","revision_date":"2023-07-17","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=GL000735","status":"unknown","title":"宜蘭縣政府處理違反建築法使用管理規定事件統一裁罰基準","last_checked_at":"2026-10-06T17:31:36+08:00","last_success_at":"2026-10-06T17:31:36+08:00","verification_status":"fetched","content_hash":"eb68a0d5386619d11cdbe396076bd5f95ab59dd091a6debbae2cb08fd0d7e312","history":[{"observed_at":"2026-10-06T17:31:36+08:00","content_hash":"eb68a0d5386619d11cdbe396076bd5f95ab59dd091a6debbae2cb08fd0d7e312","change_kind":"initial","revision_date":"2023-07-17"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4102&id=GL000735&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4100&id=GL000735&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、宜蘭縣政府（以下簡稱本府）為維持本縣國土計畫審議會、都市計畫委員會等合議制委\n員會(小組)開會時之會場秩序，使會議順利進行，特訂定本要點。\n二、審議會、委員會及各專案小組召開會議（以下簡稱各會議）時，除出席委員、列席機關\n代表、會議工作人員、受通知列席說明者及各級民意代表外，未經許可，不得擅自進入\n會場。\n申請登記發言或旁聽之居民、居民代表或相關團體等，應於會議召開前向本府提出申請\n進入會場或旁聽席。\n每一案件申請旁聽之居民、居民代表或相關團體等，各團體或各村（里）居民以不超過\n三人為原則。申請至旁聽席之總人數上限，視會議室空間狀態，以十五人為原則，超過\n十五人者，得由會議工作人員安排至其他適當地點等候。\n三、各會議應於會場門口設置簽到處，以備與會人員持開會通知或身分證明文件辦理簽到，\n並由會議工作人員引導進入會場或旁聽席。\n四、各會議召開前以書面、電子信件、口頭或現場報名等方式向本府申請登記發言之各級民\n意代表、團體或個人，始得於會議進行中表示意見；申請發言以一次為原則，已於該次\n會議申請發言者，得經會議主席徵詢全體出席委員同意後，再次發言。\n前項團體或多數有共同利益之人，應選定其中一人至三人代表發言。會議主席得視會議\n進行狀況及個案情形，於徵詢全體出席委員同意後，調整發言人數，並以與該案件具有\n利害關係之人優先。\n五、各會議與會人員應遵守下列規定：\n(一)除會議工作人員因製作會議紀錄需要者外，其他人員不得於會議進行中攝影、錄影\n或錄音。\n(二)每一案件得發言之時間，總計以不超過三十分鐘為原則，發言者表達意見應簡明扼\n要，每人以三分鐘為原則。但主席得視會議進行狀況及個案情形，經徵詢全體出席\n委員同意後，調整發言時間。\n(三)於會議進行委員討論時，除出席委員、會議工作人員與參與會議人員中之列席機關\n及列席說明者外，其餘人員均應離開會場及旁聽席區。\n(四)不得攜帶無線麥克風等各式擴音設備、標語、海報、各式布條、旗幟、棍棒、武器\n、危險及易燃物品等，進入會場、旁聽席及會議所在辦公廳舍區域。\n(五)不得於會場內、旁聽席及會議所在辦公廳舍區域大聲喧嘩或鼓譟，亦不得無故前往\n其他非指定活動區域。\n(六)等候審查案件之相關列席人員，應於會場外或本府安排之會議準備區等候會議工作\n人員通知。\n(七)會議工作人員為製作會議紀錄之需要，得請發言者提供發言書面內容。\n六、各會議與會人員違反前點規定或有妨礙會場議事運作順暢、干擾辦公或其他危害會議安\n全之不當行為，經勸阻仍不改善者，會議主席或工作人員得制止或要求其離開會場、旁\n聽席或會議所在辦公廳舍區域，必要時，得取消其再申請出席會議、發言或旁聽之權利\n；情節重大者，得依刑法、社會秩序維護法及其他相關法規，移送法辦。\n七、會議主席或工作人員得視實際需要，洽請警察機關派員管制會場進出秩序。\n八、本縣非都市土地使用分區及使用地變更專責審議小組及都市設計審議委員會召開之相關\n審議會議，得視實際需要參照本要點規定辦理。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:GL000600","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"公發布日":"民國 108 年 05 月 08 日","法規名稱":"宜蘭縣政府辦理國土計畫及都市計畫審議會議會場管理要點","法規體系":"建設","發文字號":"府建國字第1080074026號函"},"promulgation_date":"2019-05-08","revision_date":"2019-05-08","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=GL000600","status":"unknown","title":"宜蘭縣政府辦理國土計畫及都市計畫審議會議會場管理要點","last_checked_at":"2026-10-06T17:31:27+08:00","last_success_at":"2026-10-06T17:31:27+08:00","verification_status":"fetched","content_hash":"695afbb13297760c24143139ce97d1fb2994fe5ae50bbd016148b2e9f2bf69de","history":[{"observed_at":"2026-10-06T17:31:27+08:00","content_hash":"695afbb13297760c24143139ce97d1fb2994fe5ae50bbd016148b2e9f2bf69de","change_kind":"initial","revision_date":"2019-05-08"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"條文全文.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=2652&id=GL000341&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、宜蘭縣政府為審核縣內山坡地興建農舍建築執照，以確保山坡地永續利用，維護自然景\n觀及降低開挖邊坡風險，特訂定本原則。\n二、山坡地申請興建農舍，除依都市計畫法、建築法及實施區域計畫地區建築管理辦法等規\n定辦理外，並依本原則辦理。\n三、建築基地除建築面積範圍外，不得有其他開挖整地行為。\n四、為降低開發過程中土方產生運棄或堆置對坡地環境造成影響，建築物之基礎型式以獨立\n基礎、連續基礎或樁基礎為設計原則，不得設置地下室。\n五、建築物斜屋頂覆蓋面積不得小於二分之一建築面積，屋頂斜率應介於二分之一至四分之一。\n六、建築物層數以二層樓為限；建築物高度（含屋頂突出物及裝飾物）以十點五公尺為限。\n但原始地形標高未滿一百公尺者，依第二點相關法令規定辦理。\n七、建築物外觀應採低明度與山坡地環境景觀相融之色彩及材質。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:GL000341","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"修正日期":"民國 108 年 05 月 13 日","公發布日":"民國 103 年 01 月 29 日","圖表附件":"條文全文.odt","法規名稱":"宜蘭縣政府辦理山坡地興建農舍管理及設計審查原則","法規體系":"建設","發文字號":"府建管字第1080077318號函"},"promulgation_date":"2014-01-29","revision_date":"2019-05-13","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=GL000341","status":"unknown","title":"宜蘭縣政府辦理山坡地興建農舍管理及設計審查原則","last_checked_at":"2026-10-06T17:31:27+08:00","last_success_at":"2026-10-06T17:31:27+08:00","verification_status":"fetched","content_hash":"4e70a5222e15eb1885b4f812a54fb4463a839deff9c164378fe0dda7cd69ac3d","history":[{"observed_at":"2026-10-06T17:31:27+08:00","content_hash":"4e70a5222e15eb1885b4f812a54fb4463a839deff9c164378fe0dda7cd69ac3d","change_kind":"initial","revision_date":"2019-05-13"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=2652&id=GL000341&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"(1140331)宜蘭縣建築物施工計畫書備查作業原則總說明及逐條說明.pdf","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=5034&id=GL000782&type=LAW"},{"name":"(1140331)宜蘭縣建築物施工計畫書備查作業原則.pdf","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=5035&id=GL000782&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"1\n一、宜蘭縣政府（以下簡稱本府）為強化宜蘭縣建築管理自治條例第二十九條\n有關施工計畫書內容，以加強本縣建築施工管理，提升建築物施工品質、\n安全及衛生，特訂定本原則。\n2\n二、建築物施工（拆除）計畫書，分為以下二類：\n(一)特殊性案件：\n1.建築高度五十公尺以上，或樓層十六層以上之建築物。\n2.地下層開挖總深度（含基礎）九公尺以上，或地下層開挖達三層以\n上之建築物。\n3.山坡地基地面積達三千平方公尺以上，且涉及開挖整地之建築物或\n雜項工作物。\n4.拆除高度達二十公尺以上或地下層達二層以上之建築物或雜項工作\n物，或連棟式有設置地下層之建築物任一棟拆除者。\n5.基地地質條件不佳（如位於本縣土壤液化中、高潛勢區範圍內，且\n涉及地下室開挖達三層以上之建築物；或開挖深度三倍水平距離之\n區域曾經發生施工災害者）。\n6.鄰接大眾運輸設施(高速公路、鐵路)且有開挖地下層之建築物。\n7.地下室開挖範圍境界線起算水平距離六公尺內之毗鄰土地同時有地\n下層施工者。\n8.其他經主管建築機關認定情況特殊並有安全顧慮者。\n(二)一般性案件：前款以外之建築物或雜項工作物。\n3\n三、前點第二款所定一般性案件之施工（拆除）計畫書，載明事項如下：\n(一)工程概要：\n1.工程名稱。\n2.工程地點。\n3.建築執照字號。\n4.工程規模。\n5.工程造價。\n6.工程承攬金額。\n(二)工程相關人員組織基本資料：\n1.起造人。\n2.監造人。\n3.承造人。\n4.專任工程人員。\n5.職業安全衛生人員。\n6.工地主任 (含執業證及會員證)。\n7.工地負責人。\n8.營造業技術士資訊(包含專業工程項目、特定施工項目、特定施工項\n目金額規模、技術士種類、技術士證號、派駐施工期間)。\n(三)施工方法及施工程序。\n(四)預定進度及作業時間。\n(五)勘驗預定申報流程及範圍。\n(六)自主品質管制措施。\n(七)建築基地周邊調查(含公共設施)。\n(八)施工場所配置及圖說：\n1.各項安全衛生維護設施。\n2.預防火災之適當設備。\n3.工務所設置位置。\n4.機具材料堆置位置。\n5.加工場位置。\n6.施工圍籬綠美化之相關設計圖說及設置位置標示。\n(九)工地環境維護：\n1.噪音及振動防制措施。\n2.相關營建污染及灰塵散播防制措施。\n3.公共設施維護措施。\n4.營建廢棄物處理措施。\n(十)營建賸餘土石方處理：\n1.開挖土石方計算及處理方式。\n2.營建工程賸餘土石方處理計畫申報表。\n3.賸餘土石方清除機具內容及應裝置即時追蹤系統等說明。\n(十一)塔式起重機具設備使用計畫：\n1.使用塔式起重機具設備者，應檢附施工計畫、勞工安全衛生及交通\n維持之主管機關同意核備文件。\n2.無需使用塔式起重機具者，應檢附切結書。\n(十二)交通安全維護計畫(含大型工程車車輛進出工地及營建材料吊掛作業\n管制措施)。\n(十三)地下室施工作業：\n1.地下層開挖擋土措施。\n2.挖土工程施工及流程安排。\n3.地下層開挖之止水及排水措施分析評估。\n4.安全觀測系統(儀器、數量、安裝位置圖、觀測頻率及管理值表)。\n(十四)鄰房安全維護措施：\n1.現況鄰房調查及距離。\n2.開挖深度及影響評估。\n3.擋土設施及支撐安全維護設施。\n4.事故發生之處理及緊急應變措施。\n(十五)施工風險評估報告。\n(十六)防災及緊急應變措施：\n1.鷹架系統施工及安全維護措施。\n2.模板支撐系統施工及安全維護措施。\n3.墜落物防護及安全維護措施。\n4.開口安全防護措施。\n5.地下室通風及毒氣安全維護監測措施。\n6.火災預防措施。\n7.天然災害(颱風、豪雨、地震)防救措施及檢查(核)表：\n(1)宜蘭縣建築工程防颱作業工地自主檢查表。\n(2)宜蘭縣建築工程地震災害後工程設施檢核表。\n8.人為災害(火災、坍塌、墜落)防救措施。\n(十七)施工災害緊急應變及通報計畫。\n(十八)建築工地紅火蟻防治工作計畫：\n1.紅火蟻清查及防治措施。\n2.建築基地入侵紅火蟻現場清查紀錄表。\n(十九)建築工地登革熱防治工作計畫。\n(二十)建築工程落實污染防制(治)輔導紀錄單、公共工程建築工程環境維\n護輔導紀錄單。\n4\n四、第二點第一款所定特殊性案件之施工（拆除）計畫書，除載明前點所定事\n項外，並須載明下列事項：\n(一)工程概要：結構與施工法概要、地下室擋土工法概要（擋土措施之種\n類、規格、開挖剖面圖）。\n(二)基地環境概況：基地現況與四周基地地下管線及構造物現況調查、基\n地土層分布特性、地下水位。\n(三)地下室施工作業：地下層開挖擋土措施及挖土工程施工及流程之安排\n、地下層開挖之止水及排水措施分析評估、地下層開挖之安全觀測系\n統（儀器、數量、安裝位置圖觀測頻率及管理值表），支撐系統之應\n力分析及檢討（各階段開挖壁體變形量、水平支撐設定壓力及地面沉\n陷分析）、開挖面之上舉、隆起及砂湧、管湧及整體穩定分析、地質\n改良工法之施工方式及藥液成分管制及地下水污染防治（改良範圍）\n。\n(四)鄰房安全維護措施：開挖可能導致鄰近一定範圍地盤沉陷分析評估、\n開挖深度一定範圍鄰房及公共設施現況調查（含鄰房樓層數、構造、\n基礎型式初判及周邊道路探測（如透地雷達等方式）、鄰房保護措施\n。\n(五)工法說明：如施工程序及管制要點說明、逆打柱承載重核算、高空作\n業人員安全防護措施、地下室照明、通訊設備、鋼骨樓層、樓板進度\n配合、地下室緊急逃生措施、地下室各層樓板混凝土養護、地下室運\n土計畫、垂直墜落物防範措施、地錨設計、施工拉拔力檢測。\n(六)其他視案件規模或類型，應載明事項：\n1.土壤鑽探試驗結果報告。\n2.抽水及停止抽水計畫計算。\n3.構台應力分析及設計。\n4.緊急搶修及救災應變方式。\n5.依相關環境保護法令設置之環境保護措施（噪音、振動、空氣污染\n、廢土、廢棄物防制）。\n6.特殊模板應力分析及設計。\n7.地下連續壁或反循環基樁等施工方法之污染防治措施。\n8.其他經主管建築機關認有必要載明之事項。\n5\n五、施工計畫書應於開工報請備查作業：\n(一)特殊性案件：起造人或承造人委託建築師公會、土木技師公會、結構\n技師公會或大地技師公會辦理計畫書技術性諮詢作業且無修正意見後\n，將諮詢結果文件送本府備查。\n(二)一般性案件：由主管建築機關自行辦理備查。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:GL000782","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"全文檔案":"(1140331)宜蘭縣建築物施工計畫書備查作業原則.pdf","公發布日":"民國 114 年 03 月 31 日","法規名稱":"宜蘭縣政府辦理建築物施工計畫書備查作業原則","法規體系":"建設","發文字號":"府建管字第1140050576號函","立法理由":"(1140331)宜蘭縣建築物施工計畫書備查作業原則總說明及逐條說明.pdf"},"promulgation_date":"2025-03-31","revision_date":"2025-03-31","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=GL000782","status":"unknown","title":"宜蘭縣政府辦理建築物施工計畫書備查作業原則","last_checked_at":"2026-10-06T17:31:24+08:00","last_success_at":"2026-10-06T17:31:24+08:00","verification_status":"fetched","content_hash":"663ab172780409d392bfed585ea7a9a48f3d2a4498020357db49d04eb6b8a049","history":[{"observed_at":"2026-10-06T17:31:24+08:00","content_hash":"663ab172780409d392bfed585ea7a9a48f3d2a4498020357db49d04eb6b8a049","change_kind":"initial","revision_date":"2025-03-31"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=5034&id=GL000782&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=5035&id=GL000782&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"(1130117)宜蘭縣政府辦理建造執照及雜項執照展延復審期限處理原則總說明及逐點說明.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4645&id=GL000744&type=LAW"},{"name":"(1130117)宜蘭縣政府辦理建造執照及雜項執照展延復審期限處理原則.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4646&id=GL000744&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、宜蘭縣政府（下稱本府）為辦理建築法（下稱本法）第三十六條規定\n建造執照及雜項執照復審期限之展延事項，特訂定本原則。\n二、起造人申請展延建造執照及雜項執照復審期限者，應於本法第三十六\n條規定第一次通知改正之期限屆滿前三十日內，檢附申請書敘明展延\n理由、辦理進度及相關證明資料，向本府提出。\n前項展延申請，不得超過六個月，並以一次為限。\n起造人逾第一項所定期限始申請展延者，不予受理。\n三、起造人申請展延事由及相關辦理進度說明經查為不實者，駁回展延案\n件之申請。\n四、起造人已依宜蘭縣建築物擅自建造補辦建築執照申請辦法申請補辦執\n照之案件，不得再依本原則申請展延復審期限。\n五、起造人未依第二點規定申請展延復審期限者，駁回該建造執照或雜項\n執照申請。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:GL000744","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"全文檔案":"(1130117)宜蘭縣政府辦理建造執照及雜項執照展延復審期限處理原則.odt","公發布日":"民國 113 年 01 月 17 日","法規名稱":"宜蘭縣政府辦理建造執照及雜項執照展延復審期限處理原則","法規體系":"建設","發文字號":"府建管字第1130006879號","立法理由":"(1130117)宜蘭縣政府辦理建造執照及雜項執照展延復審期限處理原則總說明及逐點說明.odt"},"promulgation_date":"2024-01-17","revision_date":"2024-01-17","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=GL000744","status":"unknown","title":"宜蘭縣政府辦理建造執照及雜項執照展延復審期限處理原則","last_checked_at":"2026-10-06T17:31:25+08:00","last_success_at":"2026-10-06T17:31:25+08:00","verification_status":"fetched","content_hash":"d0af09a1245c13750ff31a394b8f25e4252f9b15fa397900f67ce46f5e62b275","history":[{"observed_at":"2026-10-06T17:31:25+08:00","content_hash":"d0af09a1245c13750ff31a394b8f25e4252f9b15fa397900f67ce46f5e62b275","change_kind":"initial","revision_date":"2024-01-17"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4645&id=GL000744&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4646&id=GL000744&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"宜蘭縣政府辦理都市危險及老舊建築物申請重建原合法建築物建築基地認定原則.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3829&id=GL000713&type=LAW"},{"name":"附表.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3830&id=GL000713&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、宜蘭縣政府為執行都市危險及老舊建築物加速重建條例（以下\n簡稱本條例）核准重建計畫作業，對原合法建築物基地面積之\n認定，特訂定本原則。\n二、未領有使用執照之合法建築物，原建築基地認定方式如下：\n(一)建物登記第一類謄本之登記日期為本條例一百零六年五月\n十日公布施\n行以前者，以謄本所載之建物坐落地號，為原\n合法建築物建築基地。\n(二)建物登記第一類謄本之登記日期為本條例一百零六年五月\n十日公布施\n行以後者，以本條例公布施行以前之建物、土\n地登記資料認定，並以\n該資料所載之建物坐落地號，為原\n合法建築物建築基地。\n三、領有使用執照之合法建築物，原建築基地認定方式如下:\n(一)依建築物於本條例一百零六年五月十日公布施行以前核\n發之建築執照\n所載建築基地範圍與面積，為原合法建築\n物基地。\n(二)原合法建築物為農舍、農業設施，後因都市計畫變更為\n住宅區、商業\n區者，其建築基地面積以原合法建築物建\n築面積，除以所屬都市計畫\n土地使用分區管制規定之建\n蔽率計算。\n四、依第二點、第三點認定有疑義者，得提宜蘭縣都市更新及爭\n議處理審議會審議。\n五、\n宜蘭\n縣都市危險及老舊建築物申請重\n建，原合法建築物建築\n基地面積認定檢核項目如附表。\n圖表附件：\n附表.odt","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:GL000713","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"全文檔案":"宜蘭縣政府辦理都市危險及老舊建築物申請重建原合法建築物建築基地認定原則.odt","公發布日":"民國 111 年 11 月 09 日","法規名稱":"宜蘭縣政府辦理都市危險及老舊建築物申請重建原合法建築物建築基地認定原則","法規體系":"建設","發文字號":"府建都字第1110174641B號令"},"promulgation_date":"2022-11-09","revision_date":"2022-11-09","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=GL000713","status":"unknown","title":"宜蘭縣政府辦理都市危險及老舊建築物申請重建原合法建築物建築基地認定原則","last_checked_at":"2026-10-06T17:31:36+08:00","last_success_at":"2026-10-06T17:31:36+08:00","verification_status":"fetched","content_hash":"130ceb28aa14386278ed31cc29654996aa82df146162a0698f1513e8cececcaf","history":[{"observed_at":"2026-10-06T17:31:36+08:00","content_hash":"130ceb28aa14386278ed31cc29654996aa82df146162a0698f1513e8cececcaf","change_kind":"initial","revision_date":"2022-11-09"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3829&id=GL000713&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3830&id=GL000713&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、宜蘭縣政府\n(\n以下簡稱本府\n)\n為辦理都市計畫法台灣省施行細則（以下稱本細則）第二十九條之二規定之事項，特訂定本要點。\n二、已申請興建農舍之該宗農地及九十二年十月二十三日前作為興建農舍之配合耕地者，均不得作為私設通路之使用。\n三、作為連接建築線之私設通路應符合下列規定：\n（一）以可連接建築線之最短路徑為原則。\n（二）不得影響鄰近灌溉排水設施。如經過農田水利會灌溉溝渠者，應取得使用同意證明文件。\n（三）應設置雨水、污水分流排水系統。\n以私設通路為進出道路之建築物總樓地板面積與通路\n寬度應符\n合建築技術規則設計施工篇第一百六十三條之\n規定。但\n工業區或丁種建築用地以私設通路為進出道路\n者，通路\n寬度應為。\n四、私設通路位於下列地區者，應依下列規定辦理：\n（一）屬山坡地者，應依法提出相關水土保持計畫。\n（二）屬風景特定區者，應徵詢管理機關（單位）之同意。\n（三）屬原住民保留地者，應徵詢主管機關（單位）之同意。\n五、申請私設通路，應檢附下列文件：\n（一）申請書（格式不拘）需載明：申請人姓名、地址，申請土地詳細地號及座落位置等。\n（二）土地登記謄本及使用權同意書。\n（三）地籍圖謄本及套繪現況測量圖。\n（四）建築線指示（定）成果圖。\n（五）建築基地及私設通路套繪地籍配置圖。\n（六）私設通路剖面圖。\n（七）建築基地排水系統圖。\n六、私設通路之申請未經本府核准，已先行設置完成者，應依都市計畫法第七十九條規定處分後，始得核准。\n七、私設通路之申請經核准者，申請人應依農業用地變更回饋金撥繳及分配利用辦法第三條前段規定，於本府核發私設通路證明文件前，繳交回饋金。\n八、經核准設置之私設通路，申請人應於申請使用執照前向地政事務所申請辦理分割完竣；本府核發使用執照時，應註記該地號土地供私設通路使用。\n九、本要點核定後實施，修正時亦同。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:FL040798","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"修正日期":"民國 100 年 05 月 27 日","公發布日":"民國 95 年 10 月 18 日","法規名稱":"宜蘭縣政府辦理都市計畫農業區土地作為連接建築線之私設通路使用審查要點","法規體系":"建設","發文字號":"府建城字第1000079404號 函"},"promulgation_date":"2006-10-18","revision_date":"2011-05-27","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=FL040798","status":"unknown","title":"宜蘭縣政府辦理都市計畫農業區土地作為連接建築線之私設通路使用審查要點","last_checked_at":"2026-10-06T17:31:40+08:00","last_success_at":"2026-10-06T17:31:40+08:00","verification_status":"fetched","content_hash":"952d55a7b1d73e8b8faaaaed657e44bb8c97b71ae5aae109c372237af725ec34","history":[{"observed_at":"2026-10-06T17:31:40+08:00","content_hash":"952d55a7b1d73e8b8faaaaed657e44bb8c97b71ae5aae109c372237af725ec34","change_kind":"initial","revision_date":"2011-05-27"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"宜蘭縣政府都市計畫保護區及農業區土地使用審查要點.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3419&id=GL000289&type=LAW"},{"name":"附表.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3608&id=GL000289&type=LAW"},{"name":"附圖.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3421&id=GL000289&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、宜蘭縣政府（以下簡稱本府）為審查本縣都市計畫保護區及農業區內核\n准使用之各項設施案件，依都市計畫法臺灣省施行細則第二十七條第二\n項及第二十九條之一第五項規定訂定本要點。\n二、各目的事業主管單位(機關)於核准籌設(或設立)許可前，應依本要點審\n核。但都市計畫說明書或其他法令另有規定者，從其規定。\n三、申請基地面臨之道路應以已開闢都市計畫道路或現有巷道為限。\n前項申請基地未直接臨接可通行道路者，應依下列規定辦理，並自行開\n闢完成可通行之通路後，始得申請使用：\n(一)面臨未全部開闢之計畫道路:取得該未開闢道路用地之土地使用權\n利證明文件。\n(二)受現有溝渠區隔:取得該目的事業主管單位(機關)同意使用或架設\n橋涵之權利證明文件。\n前項「已開闢完成都市計畫道路或現有巷道」係指:\n(一)已開闢：指政府機關開闢完竣，或由私人依道路主管機關設計標\n準開闢完成，並取得道路主管機關同意管理維護之證明文件。\n(二)都市計畫道路:於都市計畫範圍內，經都市計畫擬定機關依都市計\n畫法定程序於都市計畫書、圖劃定並公告之道路。\n(三)現有巷道:依建築法第四十八條第二項規定及宜蘭縣建築管理自治\n條例第五條所列情形者。\n第一項自行開闢完成可通行之通路，寬度不得小於該項設施應臨接之\n道路寬度，並應符合相關建築管理法令規定。申請人送件時應檢附相\n關文件，併同建照執照申請審查。\n申請基地各項設施應鄰接已開闢完成都市計畫道路或現有巷道寬度，\n詳如附要項表；已開闢道路寬度之認定，以及如有經溝渠、橋涵或路\n邊駁崁等，應依附圖及附表各類使用類別規範寬度辦理。\n圖表附件：\n附表.odt\n附圖.odt\n四、依本要點申請之各項設施，不得設置在下列地區：\n(一)農地重劃區。但經本府農業處、地政處認定不影響該地區農田、\n農路、農業生產環境，及農田水利管理機關認定不影響水路、\n水利設施等功能者，不在此限。\n(二)保安林地。但經林業主管機關同意者，不在此限。\n(三)軍事禁建區、都市計畫禁建區及其他依法令公告之禁建區。\n(四)自然地景、野生動物保護區或野生動物重要棲息環境。\n(五)景觀保護區、資源保護區、地質保護區及其他依特殊目的劃設\n之保護區。\n(六)自來水水質水量保護區、飲用水水源水質保護區及飲用水取水\n口一定距離內之地區。但下列情形不在此限:\n1.自來水水質水量保護區:經轄區水利主管機關同意。\n2.飲用水水源水質保護區及飲用水取水口一定距離內之地區:\n經本府環境保護局同意。\n(七)經濟部中央地質調查所公告斷層帶或環境地質上有崩塌滑動\n危險之地區。\n(八)河川主管機關公告水道治理計畫範圍內之地區。\n(九)其他法令規定禁止或經本府認定不適宜使用之地區。\n五、申請基地範圍原始地形平均坡度超過百分之三十部分不得建築且\n不得計入法定空地。\n前項平均坡度應依建築技術規則建築設計編第十三章之平均坡度\n定義計算。\n六、申請時除應檢附各目的事業主管單位(機關)規定之文件外，並應\n檢具下列文件、資料：\n(一)第四點第一款至第八款地區主管機關之查詢結果公文。\n(二)土地相關證明文件：受理目的事業申請日起算三個月內核發\n之地籍圖謄本、土地登記謄本、土地使用分區證明。\n(三)標示基地位置及其周圍一百公尺範圍之都市計畫圖(比例尺\n不得小於一千二百分之一)。\n(四)申請基地位於山坡地者，應標示地形、地物之等高線(等高\n線間隔一百公分)，其比例尺不得小於六百分之一，並需經\n相關專業技師簽證。\n(五)建築線指示成果圖(應含基地及其鄰近地區之現況測量）。\n(六)(簡易)用排水計畫書。\n七、農業區及保護區之建蔽率，除於農業區核准使用之社會福利事業\n設施、幼兒園、兒童課後照顧服務中心、加油(氣)站及運動訓練\n設施，依都市計畫法臺灣省施行細則第二十九條之一規定不得超\n過百分之四十外，餘仍依都市計畫法臺灣省施行細則第三十二條\n規定辦理。\n八、各項設施申請核准使用時，除依第一點至第七點規定辦理外，並\n應符合都市計畫保護區及農業區土地使用審查要項表(如附表)之\n規定。\n九、依第八點規定設置之隔離綠帶範圍內，除目的事業主管單位(機\n關)另有規定，不得設置圍牆。\n隔離綠帶面積每十平方公尺(餘數不計)應種植一株米高徑不\n得小於五公分之喬木，且樹距不得小於三公尺。\n十、原核准設置之興辦事業或設施，於不增加基地面積下，倘依本要\n點申請變更者，有關隔離綠帶之規定得依原核准計畫辦理，不受\n第八點及第九點規定限制。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:GL000289","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"修正日期":"民國 110 年 05 月 10 日","全文檔案":"宜蘭縣政府都市計畫保護區及農業區土地使用審查要點.odt","公發布日":"民國 91 年 08 月 16 日","法規名稱":"宜蘭縣政府都市計畫保護區及農業區土地使用審查要點","法規體系":"建設","發文字號":"府建都字第1100077430號令"},"promulgation_date":"2002-08-16","revision_date":"2021-05-10","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=GL000289","status":"unknown","title":"宜蘭縣政府都市計畫保護區及農業區土地使用審查要點","last_checked_at":"2026-10-06T17:31:26+08:00","last_success_at":"2026-10-06T17:31:26+08:00","verification_status":"fetched","content_hash":"04be686b75ee396dbfd10db59ece93e385735114a2fa0f8cbef99c96ae8724d8","history":[{"observed_at":"2026-10-06T17:31:26+08:00","content_hash":"04be686b75ee396dbfd10db59ece93e385735114a2fa0f8cbef99c96ae8724d8","change_kind":"initial","revision_date":"2021-05-10"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3419&id=GL000289&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3608&id=GL000289&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3421&id=GL000289&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、\n依據法源\n:\n依據內政部一○一年四月二日修正發布違章建築處理辦法第十一條之一制定本計畫。\n二、\n目的\n:\n為執行違章建築處理辦法第十一條之一，針對本縣既存違章建築影響公共安全者\n,\n訂定拆除計畫限期拆除，以維護縣民生命財產安全。\n三、\n適用範圍：\n前既存違章建築影響公共安全，依下列優先順序辦理執行強制拆除作業。\n第一類\n（一）\n有傾頹、朽壞或結構安全顧慮之違章建築，或經本府委請專業機構或團體鑑定確有影響公共安全、公共交通情形者。\n（二）\n經消防主管機關認定為狹窄巷道，確有妨礙消防救災之違章建築。\n（三）\n現有巷道（含既成道路）、私設通路等擅自違章建築，確有妨礙通行情形者。\n（四）\n營業場所未委請專業檢查人辦理建築物公共安全檢查簽證及申報，經本府裁罰二次以上並執行強制斷電後，仍持續營業，且屬違章建築之以下場所：\n1.\nB1\n類\n-\n視聽歌唱場所、理容（理髮）場所\n(\n將場所加以區隔或包廂式之場所\n)\n及電子遊戲場等場所。\n2.\nB4\n類\n-\n觀光旅館、旅社及旅館等場所。\n3.\nD1\n類\n-\n資訊休閒服務等場所。\n4.\nD5\n類\n-\n補習班、課後照顧中心、安親班等場所。\n5.\nF3\n類\n-\n幼兒園、托嬰中心等場所。\n6.\n本府社會處及衛生局列管場所。\n7.\n經本府認定有危害公共安全之使用類組。\n（五）\n法定騎樓或無遮掩人行道之轉角處，擅自以木板或其他材料構成之圍牆，或設置鐵捲門等違章建築，涉有影響公共交通安全者。\n（六）\n依公路兩側公私有建築物與廣告物禁建限建辦法第三條規定，其擅自建築或設置廣告物，經交通部臺灣區國道高速公路局北區工程處查報函送本府有案者。\n（七）\n縣轄內主要道路及重要路口兩側，擅自設置廣告物影響公共安全及行車視線之路段。\n第二類：\n（一）\n供營業使用之整幢違章建築，屬供公眾使用建築物且未委請專業檢查人辦理建築物公共安全檢查簽證及申報場所。\n（二）\n合法建築物垂直增建違章建築，有下列情形之一者：\n1.\n建築技術規則設計施工編第九十九條規定之屋頂避難平臺。\n2.\n違章建築樓層達二層以上。\n第三類：\n（一）\n合法建築物水平增建違章建築，有下列情形之一者：\n1.\n占用防火間隔。\n2.\n占用防火巷。\n3.\n占用騎樓。\n4.\n占用法定空地供營業使用。\n5.\n占用開放空間。\n（二）\n違反各目的事業主管機關主管法規之違建，經列入專案處理簽報核定後，配合優先執行強制拆除之違章建築。\n四、\n實施方式\n:\n經各鄉鎮市公所查報或配合府內單位簽核完成之案件，經開立拆除處分書後，依實質影響公共安全程度排定拆除作業後執行拆除。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:GL000346","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"公發布日":"民國 103 年 09 月 15 日","法規名稱":"宜蘭縣既存違章建築影響公共安全執行計畫","法規體系":"建設","發文字號":"中華民國103年9月15日府建使字第1030148291號 函"},"promulgation_date":"2014-09-15","revision_date":"2014-09-15","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=GL000346","status":"unknown","title":"宜蘭縣既存違章建築影響公共安全執行計畫","last_checked_at":"2026-10-06T17:31:30+08:00","last_success_at":"2026-10-06T17:31:30+08:00","verification_status":"fetched","content_hash":"af7b5607beb9856dc85042cf03fa882d2c0f6d3df06bbf6f4fa0d982dfaecd32","history":[{"observed_at":"2026-10-06T17:31:30+08:00","content_hash":"af7b5607beb9856dc85042cf03fa882d2c0f6d3df06bbf6f4fa0d982dfaecd32","change_kind":"initial","revision_date":"2014-09-15"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"宜蘭縣未領得使用執照之建築物申請接水接電辦法第三條修正總說明及對照表.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3568&id=FL030367&type=LAW"},{"name":"宜蘭縣未領得使用執照之建築物申請接水接電辦法.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3569&id=FL030367&type=LAW"},{"name":"第六條第一款-申請書.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3567&id=FL030367&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"第一條\n本辦法依建築法第七十三條第一項規定訂定之。\n第二條\n本辦法適用未領有使用執照、完工證明或合法房屋證明之建築物。\n建築物領有使用執照、完工證明或合法房屋證明，其增建部分於一百\n零二年一月一日前已完成戶籍遷入登記者，適用本辦法。\n第三條\n建築物符合下列情形之一者，得申請接水接電：\n一、大同鄉或南澳鄉非屬都市計畫地區之建築物。\n二、因興辦公共設施而拆遷具整建需要之建築物。但位於都市計畫\n地區者，以無礙都市計畫發展為限。\n三、因天然災害受損，須安置及修復之建築物。\n四、本辦法發布前領得建造執照之建築物，於原核准範圍內，因故\n未能領得使用執照。\n五、有迫切民生需要之建築物。\n六、候車亭、涼亭、守望相助亭、公廁、寺廟或其他使用建築物，並\n取得各目的事業主管機關(單位)同意。\n第四條\n依前條第一款至第三款、第五款申請接水接電之建築物用途限居住使\n用，其高度不得超過三層樓，最大基層面積不得超過一百六十五平方\n公尺，且座落位置無占用公有土地情形。\n前項有二個以上住宅使用單元，分別申請接水接電者，應分別具備住\n宅生活機能，室內範圍樓地板面積分別須達三十平方公尺以上，並應\n以整層為之。\n第五條\n依本辦法申請接水接電之建築物，不視為合法房屋；有關違章建築之\n處理，仍適用建築法、違章建築處理辦法之規定。\n第六條\n申請人應為房屋使用人，並檢附下列文件向宜蘭縣政府(以下簡稱本\n府)申請核發接水接電證明：\n一、申請書。\n二、土地為公有者，應檢附建築基地租賃契約書。\n三、房屋稅籍證明書。\n四、建築物現況照片(一式三份)。\n五、簡易各層平面圖(含面積計算表)。\n六、其他相關證明文件。\n圖表附件：\n第六條第一款-申請書.odt\n第七條\n依本辦法規定申請核發接水接電證明，本府得委託鄉(鎮、市)公所\n辦理。\n第八條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:FL030367","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"修正日期":"民國 110 年 10 月 26 日","全文檔案":"宜蘭縣未領得使用執照之建築物申請接水接電辦法.odt","公發布日":"民國 93 年 01 月 02 日","法規名稱":"宜蘭縣未領得使用執照之建築物申請接水接電辦法","法規體系":"建設","發文字號":"府秘法字第1100175497B號令","立法理由":"宜蘭縣未領得使用執照之建築物申請接水接電辦法第三條修正總說明及對照表.odt"},"promulgation_date":"2004-01-02","revision_date":"2021-10-26","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=FL030367","status":"unknown","title":"宜蘭縣未領得使用執照之建築物申請接水接電辦法","last_checked_at":"2026-10-06T17:31:16+08:00","last_success_at":"2026-10-06T17:31:16+08:00","verification_status":"fetched","content_hash":"5ebb834dc072b20c8e7f987c8260fc077b0661bf7e2f2f7ed9c0d41f7b43da24","history":[{"observed_at":"2026-10-06T17:31:16+08:00","content_hash":"5ebb834dc072b20c8e7f987c8260fc077b0661bf7e2f2f7ed9c0d41f7b43da24","change_kind":"initial","revision_date":"2021-10-26"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3568&id=FL030367&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3569&id=FL030367&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3567&id=FL030367&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"(1120529)宜蘭縣營建賸餘土石方管理自治條例修正條文對照表.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4082&id=FL039802&type=LAW"},{"name":"(1120529)宜蘭縣營建賸餘土石方管理自治條例修正總說明.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4015&id=FL039802&type=LAW"},{"name":"(1120529)宜蘭縣營建賸餘土石方管理自治條例條文.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4017&id=FL039802&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"第一章 總則\n第一條\n宜蘭縣政府(以下簡稱本府)為有效管理宜蘭縣(以下簡稱本縣)轄內營建工程賸餘土石方(\n以下簡稱餘土)及入境土石方，以維護環境衛生及公共安全，特制定本自治條例。\n第二條\n本自治條例適用範圍如下：\n一、本府及所屬機關、本縣各鄉(鎮、市)公所、其他公務機關及公用事業機構發包之公共\n工程，所產生之餘土。\n二、本縣境內領有建築執照之建築工程及拆除工程，所產生之餘土。\n三、其他民間工程所產生之餘土。\n四、入境土石方。\n第三條\n本自治條例用詞，定義如下：\n一、餘土：指前條所定工程施工所產生之營建泥漿、賸餘泥土、砂、石、磚、瓦或混凝土\n塊等。\n二、入境土石方：指由本縣境外，以車輛運入或運經本縣之土石方。\n三、營建混合物：指公共工程、建築工程及建築物拆除工程施工所產生之餘土、廢木板(\n屑)、廢玻璃屑、廢鐵、廢金屬、廢塑膠、廢橡膠或廢瀝青混凝土等混雜未經分離者\n。\n四、土石方資源堆置處理場(以下簡稱土資場)：指提供下列功能之場所：\n(一)餘土填埋、暫屯或轉運再利用功能。\n(二)餘土破碎、洗選、篩選、分類、拌合或煆燒等加工再利用功能。\n五、再利用機構：指符合內政部公告之營建事業廢棄物再利用種類及管理方式應備資格者\n。\n六、餘土處理計畫：指載明下列事項之書面文件：\n(一)工程及承造人姓名或承包廠商名稱。\n(二)餘土數量、內容、產出時間及處理方式。\n(三)合法收容處理場所之名稱、地點、運送時間、路線及作業方式。\n(四)污染防治(制)說明。\n第四條\n餘土依其產生源、土質及再利用方式，應申請許可後，於下列場所處理：\n一、依法設立之土資場。\n二、依法登記營運中之碎解洗選場或水泥廠。\n三、依法登記營運中之磚瓦窯廠或礦石加工廠。\n四、依法核准之土地改良地點。\n五、經各目的事業主管機關核准之需土工程。\n前項餘土產生源為公共工程者，由承包廠商向工程主辦機關申請；為建築工程或拆除工程\n者，由起造人(申請人)、承造人及監造人共同向建築主管機關申請；為其他民間工程者，\n由承包廠商向工程核准機關申請。\n第一項場所營運期間內，本府各目的事業主管機關得隨時派員檢查，場所負責人或現場管\n理人，不得規避、妨礙或拒絕。\n場所負責人應在場所出入口處裝置遠端監控系統，按月彙整影像檔案並保存三年。本府有\n調閱即時影像之需求時，場所負責人應配合辦理。\n第一項申請辦法由本府另定之。\n第五條\n公共工程、建築工程及拆除工程挖填土石，應力求平衡；有餘土者，承包廠商、承造人應\n有餘土處理計畫，並應納入工程施工管理。監造廠商、監造人，應依工程主辦機關、建築\n主管機關之要求，負責督導承包廠商、承造人對於餘土之處理。\n前項工程餘土之出(需)土數量達一定規模及入境土石方運送期間內，運輸業者應加裝車輛\n定位系統，並開放供工程主辦機關、建築主管機關查詢。\n前項餘土達一定規模之數量標準，由本府公告之。\n第六條\n工程主辦機關為加強公共工程餘土去化處理，得進行餘土交換作業。\n民間工程之餘土交換，於開工時一併申報；經本府或鄉(鎮、市)公所審核其工期、土質及\n數量符合相關規定者，發給流向證明文件，進行餘土交換作業。\n前二項餘土交換之數量、土質類別及期程，應經承包廠商或承造人之專任工程人員簽證。\n第七條\n住宅及營業場所裝修工程產生之餘土，數量在十五立方公尺以下者，其申報處理作業依下\n列規定辦理：\n一、承包廠商填具申請書，經本府審核許可後，發給流向證明文件。\n二、餘土清運完成後，至本府指定網站，填報餘土處理紀錄月報表。\n第二章 公共工程餘土之處理及管理\n第八條\n承包廠商應於工程開工前，將餘土處理計畫陳報工程主辦機關審核同意後，依核定計畫辦\n理；餘土處理計畫變更時，亦同。\n第九條\n承包廠商應於餘土產出前，檢具工程餘土流向管制編號、合法收容處理場所流向管制編號\n等資料，向工程主辦機關申請發給流向證明文件。\n第十條\n承包廠商應於每月五日前，至本府指定網站填報上月份餘土處理紀錄月報表，並陳報工程\n主辦機關備查。\n第十一條\n工程主辦機關應於承包廠商請領工程估驗款計價時，上網勾稽查核餘土處理資料，並查核\n承包廠商是否已載運餘土至指定合法收容處理場所。\n第三章 建築工程及拆除工程餘土之處理與管理\n第十二條\n承造人應於工程開工前，將餘土處理計畫陳報本府或鄉(鎮、市)公所審核同意後，依核定\n計畫辦理；餘土處理計畫變更時，亦同。\n第十三條\n承造人應於餘土產出前，檢具工程餘土流向管制編號、合法收容處理場所流向管制編號等\n資料，向本府或鄉(鎮、市)公所申請發給流向證明文件。\n起造人或承造人應於每月五日前，至本府指定網站填報上月份餘土處理紀錄月報表，本府\n或鄉(鎮、市)公所得隨時查核之。\n第十四條\n前條第一項流向證明文件計四聯，第一聯由承造人收執，第二聯由承運業者收執，第三聯\n由合法收容處理場所負責人收執，第四聯由起造人或監造人收執。\n流向證明文件收執人應將文件留存三年，本府或鄉(鎮、市)公所得隨時抽查之。\n承運業者應於運送餘土時，隨車攜帶流向證明文件，以備檢查。\n第十五條\n餘土處理完成，且餘土處理紀錄月報表經本府或鄉(鎮、市)公所上網勾稽查核完成後，起\n造人或承造人始得申報基礎勘驗。\n第十六條\n本府得於餘土處理期間內，視實際需要，查核餘土處理作業情形，核對其流向證明文件及\n處理紀錄表。\n第四章 土資場之設置及管理\n第十七條\n下列地區不得設置土資場：\n一、水庫集水區域或河川行水區域內。\n二、特定水土保持區或土石流潛勢溪流影響範圍內。\n三、飲用水水源水質保護區、自來水水源水質水量保護區或飲用水取水口之一定距離內。\n四、國家公園、保安林、自然保留區、國有林自然保護區、野生動物重要棲息環境或野生\n動物保護區內。\n五、軍事禁建或限建地區。\n六、政府機關核定之養殖漁業生產區範圍內之農業用地。\n七、特定農業區之農業用地。\n八、其他各目的事業主管機關依法劃定應保護、管制或禁止之地區。\n第十八條\n土資場之設置，應符合下列條件：\n一、設置於平地者，其面積不得少於一公頃，容量不得少於一萬立方公尺。\n二、設置於低窪地區者，以未曾因違反都市計畫法或區域計畫法，受裁罰處分者為限。\n三、地界線以外一百公尺範圍內，無供人居住使用之建築物。但已取得建築物所有權人之\n同意者，不在此限。\n四、聯外道路已開闢完成，且連接土資場之道路，其寬度達八公尺以上。\n五、使用鄉(鎮、市)公所開闢養護之道路、現有巷道或由政府機關所興建並專供其運輸之\n專用道路者，經道路主管機關或管理機關同意使用。\n六、設置於都市計畫甲、乙種工業區者，符合宜蘭縣都市計畫甲、乙種工業區設置工業發\n展有關設施、公共服務設施、公用事業設施審查相關規定。\n七、設置於保護區、農業區者，符合宜蘭縣都市計畫保護區及農業區土地使用審查有關規\n定。\n第十九條\n申請設置土資場者，應填具申請書，並檢附興辦事業計畫書一式二十份，向本府提出。\n前項興辦事業計畫書，應包括下列內容：\n一、設場區位說明摘要表。\n二、自然人身分證明文件或法人證明文件影本。\n三、土地權利證明文件：包括土地使用範圍之土地清冊、土地登記簿謄本、地籍圖謄本及\n土地複丈成果圖；非申請人之土地者，應檢附土地使用權同意書。\n四、土地使用分區證明文件；非都市土地，免附。\n五、設置計畫說明書圖如下：\n(一)計畫內容說明：設場目的、服務範圍、處理設備功能、營運項目、收容餘土及營\n建混合物來源、餘土與營建混合物種類及場區各項必要設施配置情形。\n(二)場地位置及範圍說明：場地位置、方位、鄰近之聚落、水體及交通路線；場地範\n圍、地形、標高、土地使用現況、地物及鄰近地區地質狀況；場地界線外一百公\n尺範圍內地上物及土地使用現況。\n(三)位置圖：以比例尺二萬五千分之一基本圖標示基地與其相鄰及附近地區之關係位\n置及相關事項。\n(四)範圍圖：以比例尺不小於五千分之一之基本圖表示。\n(五)基地周圍一百公尺範圍內之實測地形圖：比例尺不小於一千二百分之一，且應由\n建築師或測量技師簽證。\n(六)配置圖：以大比例尺設計地形圖標示場地標示牌、堆置區、通路、導水、排水設\n施、綠帶、植栽圍籬、圍牆或隔離設施、管理室、機具作業空間、洗車設備、沉\n澱池及污水處理設備等配置。\n六、現況各向度照片：以地形圖標示拍攝位置。\n七、最大堆置容量及日處理量計算書圖；其應記載內容如下：\n(一)設計地形圖、斷面圖及最大容量計算式。\n(二)處理設備圖說及最大日處理量計算式。\n八、再利用機構收容處理能力證件及其承諾收容量之相關文件；未處理營建混合物者，免\n附。\n九、交通運輸計畫書圖；其應記載內容如下：\n(一)場內及場外運輸路線圖、聯外公路系統名稱、已開闢寬度；使用村(里)道路或專\n用道路者，另檢附該村(里)道路主管機關或專用道路管理機關同意使用證明文件\n；基地面臨現有巷道者，另檢附建築線指定成果圖。\n(二)運輸車輛種類、車輛出入行車安全管制措施、堆置場至聯外道路、交岔路口之安\n全設施及每日最大運輸車次。\n十、污染防治(制)措施計畫；其應記載內容如下：\n(一)空氣污染、水質污染、道路污染、噪音及震動防治(制)措施。\n(二)廢棄物貯存、清除及處理措施。\n十一、出流管制計畫書。\n十二、營運管理計畫；其應記載內容如下：\n(一)餘土之進場、暫屯、加工及轉運再利用作業。\n(二)營建混合物之進場、暫屯及分類再利用作業。\n(三)營建混合物於分類後之營建廢棄物與可回收資源之貯存、清除及處理計畫。\n(四)各項設備操作及維護計畫。\n(五)營運管理組織、管理要點及財務計畫。\n十三、含使用期限之分區、分段及分期計畫書圖。\n十四、再利用計畫概述。\n十五、使用農業用地者，依使用審查作業相關規定辦理。\n十六、軍事禁建或限建管制會勘紀錄；不須辦理者，免附。\n十七、環境影響評估報告；不須辦理者，免附。\n十八、水土保持計畫書；非山坡地，免附。\n十九、都市設計審議許可函；非都市設計審議地區，免附。\n二十、其他本府規定之必要文件、資料。\n第二十條\n土資場設置申請案件之審查程序如下：\n一、由本府邀集相關目的事業主管機關會勘審查；有不合規定者，一次通知申請人改正。\n二、申請人應於接獲通知之日起六個月內依照通知事項改正完竣，申請復審；屆期未完成\n改正或經復審仍不合規定者，本府得駁回申請案件。\n第二十一條\n土資場設置申請案件，經本府許可者，得為下列使用：\n一、填埋餘土。\n二、暫屯、轉運再利用餘土。\n三、加工再利用餘土。\n四、依廢棄物清理法及營建事業廢棄物再利用管理辦法相關規定，分類再利用營建混合物\n。\n第二十二條\n土資場設置申請案件經本府許可者，發給許可函。\n前項許可，有效期間為一年，期滿得申請展延，每次不得超過六個月，並以二次為限；逾\n期未設置完成者，廢止其設置許可。\n第二十三條\n土資場設置完成後，負責人應填具申請書，並檢附原興辦事業計畫書及下列文件一式二十\n份，向本府申請營運許可；經許可後，始得營運：\n一、設置許可函影本。\n二、建築物之使用執照或臨時使用許可影本；無建築物者，免附。\n三、完成後之現況全景照片。\n四、空氣污染防制費等相關規費繳費證明。\n五、前條第一項許可函所載應辦理事項，辦理完成之證明文件。\n第二十四條\n土資場營運期間以五年為限；期限屆滿時，應停止營運並向本府陳報場址整復計畫書。\n土資場場地填埋容量未飽和或仍具有轉運、加工再利用功能者，負責人得於前項所定期限\n屆滿前三個月，檢具原興辦事業計畫書、營運許可函及第十九條規定之興辦事業計畫書，\n向本府申請展延，每次展延期間不得超過五年；經許可後，始得繼續營運。\n第二十五條\n土資場於設置或營運期間內，有變更興辦事業計畫之情形者，應依第十九條規定，向本府\n申請；經許可後，始得依變更後之興辦事業計畫營運。\n第二十六條\n第四條第一項場所，依本府許可之營運項目，應辦理下列事項：\n一、簽發承諾餘土收容處理文件。\n二、簽收流向證明文件。\n三、簽發轉運再利用文件。\n四、申請核發運送證明文件。\n第二十七條\n第四條第一項場所，應於每月五日前，至本府指定網站填報上月份月報表，登錄再利用產\n品數量及去處，並填具下列報表，陳報本府備查：\n一、承諾餘土收容處理文件月報表。\n二、流向證明文件簽收月報表。\n三、轉運再利用文件月報表。\n四、營運月報總表。\n第二十八條\n土資場因許可使用期間屆滿或填埋容量飽和等因素終止營運時，負責人應填具申請書，並\n檢附原興辦事業計畫書及下列文件、資料一式二十份，向本府申請廢止營運許可；未申請\n者，本府得逕予廢止營運許可：\n一、營運許可函影本。\n二、當月土資場已處理紀錄之月報表。\n三、比例尺不小於一千二百分之一，且經建築師或測量技師簽證之現況地形圖。\n四、現況全景照片。\n五、場址整復計畫書。\n第五章 入境土石方管理\n第二十九條\n申請載運入境土石方者，經本府許可後，按月(次)領取本府發給之運土憑證(三聯單)。\n申請人已領取之運土憑證(三聯單)有破損或賸餘者，應全數繳回本府；有遺失者，應登報\n作廢。\n第三十條\n本府得在適當地點設稽查站，檢查載運入境土石方之車輛。\n第三十一條\n載運入境土石方之車輛，應隨車攜帶本府發給之運土憑證(三聯單)。\n前項車輛行經稽查站時，應緩慢靠站停車，配合稽查人員檢查載運之土石方及簽收三聯單\n第一聯；合格者放行，不合格者由稽查人員勸導離境。\n第三十二條\n申請人於載運完成時，應檢附下列文件、資料，向本府陳報：\n一、運土憑證(三聯單)使用順序紀錄。\n二、申報表。\n三、運土憑證(三聯單)第二聯。\n申請人應保存運土憑證(三聯單)第三聯至少三年，本府得隨時查核之。\n第六章 罰則\n第三十三條\n第四條第一項場所有下列情形之一者，處負責人新臺幣六萬元以上十萬元以下罰鍰，並得\n令其停止營運一個月以上三個月以下：\n一、違反第四條第三項規定，規避、妨礙或拒絕配合檢查。\n二、未依第二十六條規定，簽收(發)文件、申請核發運送證明文件或簽收(發)文件不實。\n第三十四條\n有下列情形之一者，處新臺幣三萬元以上十萬元以下罰鍰，並令其限期改善，屆期仍未改\n善者，按次處罰：\n一、第四條第一項場所負責人違反同條第四項規定，未在場所入口處裝置遠端監控系統、\n保存影像檔案或拒絕本府調閱即時影像。\n二、運輸業者違反第五條第二項規定，未加裝車輛定位系統，或未開放供工程主辦機關、\n建築主管機關查詢。\n三、申請載運入境土石方者違反第二十九條第二項規定，未繳回破損或賸餘之運土憑證(\n三聯單)或遺失未登報作廢。\n四、申請載運入境土石方者違反第三十二條規定，未於載運完成時向本府陳報。\n第三十五條\n有下列情形之一者，處新臺幣三萬元以上十萬元以下罰鍰，並得按次處罰；必要時，得勒\n令停工至改善為止：\n一、承包廠商違反第八條規定，未將餘土處理計畫陳報工程主辦機關審核，或未依核定計\n畫辦理。\n二、承造人違反第十二條規定，未將餘土處理計畫陳報本府或鄉(鎮、市)公所審核，或未\n依核定計畫辦理。\n三、監造廠商或監造人違反第五條第一項規定，未負責督導承包廠商、承造人對於餘土之\n處理。\n第三十六條\n土資場有下列情形之一者，處負責人新臺幣三萬元以上十萬元以下罰鍰，並令其限期改善\n或補辦手續；屆期仍未改善或補辦手續者，得按次處罰，並得令其停止營運至改善為止：\n一、違反第二十四條第二項規定，於許可期限屆滿前未申請展\n延而繼續營運。\n二、違反第二十五條規定，有變更興辦事業計畫之情形時，未\n依第十九條規定，向本府申\n請；或未依本府許可變更後之\n興辦事業計畫書營運。\n三、違反第二十八條規定，終止營運時，未向本府申請廢止營\n運許可。\n第三十七條\n土資場有下列情形之一者，處負責人新臺幣二萬元以上十萬元以下罰鍰，並令其限期改善\n；屆期未改善者，得按次處罰，並得令其停止營運至改善為止：\n一、違反第二十三條規定，未經本府許可營運，即擅自營運；\n或未依本府許可之營運項目\n營運。\n二、違反第二十四條第一項規定，未陳報場址整復計畫書或未\n依場址整復計畫書辦理。\n第三十八條\n有下列情形之一者，處新臺幣一萬元以上五萬元以下罰鍰，並令其限期改善；屆期仍未改\n善者，得按次處罰，並得令其停工至改善為止：\n一、承包廠商未依第七條規定，辦理餘土申報處理作業。\n二、承包廠商違反第十條規定，未至本府指定網站，填報餘土\n處理紀錄月報表，或未陳報\n工程主辦機關備查。\n三、起造人或承造人違反第十三條第二項規定，未至本府指定\n網站，填報餘土處理紀錄月\n報表。\n第三十九條\n第四條第一項場所，違反第二十七條規定，未按月至本府指定網站填報月報表，登錄再利\n用產品數量及去處，或未填具同條第一款至第四款報表者，處負責人新臺幣一萬元以上五\n萬元以下罰鍰，並得令其限期改善；屆期仍未改善者，得按次處罰，並得令其停止營運至\n改善為止。\n第四十條\n載運入境土石方車輛之駕駛人違反第三十一條第二項規定，不依稽查人員之勸導離境者，\n處新臺幣一萬元以上五萬元以下罰鍰\n。\n第七章 附則\n第四十一條\n承包廠商、承造人應在工地現場將營建混合物分離處理；其屬餘土者，應載運至收容處理\n場所；其屬廢棄物或無法在工地現場分離處理之營建混合物，應依環保相關法規處理之。\n第四十二條\n本自治條例自公布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:FL039802","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"修正日期":"民國 112 年 05 月 29 日","全文檔案":"(1120529)宜蘭縣營建賸餘土石方管理自治條例條文.odt","公發布日":"民國 95 年 07 月 07 日","法規名稱":"宜蘭縣營建賸餘土石方管理自治條例","法規體系":"建設","發文字號":"府秘法字第1120091798B號","立法理由":"(1120529)宜蘭縣營建賸餘土石方管理自治條例修正條文對照表.odt (1120529)宜蘭縣營建賸餘土石方管理自治條例修正總說明.odt"},"promulgation_date":"2006-07-07","revision_date":"2023-05-29","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=FL039802","status":"unknown","title":"宜蘭縣營建賸餘土石方管理自治條例","last_checked_at":"2026-10-06T17:31:09+08:00","last_success_at":"2026-10-06T17:31:09+08:00","verification_status":"fetched","content_hash":"f984bbd8a120673f45b867da2747e39091ca213e79229cd166d0286496985d7b","history":[{"observed_at":"2026-10-06T17:31:09+08:00","content_hash":"f984bbd8a120673f45b867da2747e39091ca213e79229cd166d0286496985d7b","change_kind":"initial","revision_date":"2023-05-29"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4082&id=FL039802&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4015&id=FL039802&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4017&id=FL039802&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、宜蘭縣政府（以下簡稱本府）為解決本縣現有巷道認定及建築線指示等相關爭議案件，依據宜蘭縣建築管理自治條例\n(\n以下簡稱本自治條例\n)\n第五條第三項規定，設置「現有巷道及建築線指示爭議案件審議小組」（以下簡稱本小組），並訂定本要點。\n二、本小組任務如下：\n（一）有關現有巷道公用地役關係爭議、疑義事件之處理，協調配合審議事項。\n（二）現有巷道之改道或廢止異議處理審議事項。\n（三）經本府建設處報請核准列入議程之都市計畫區內現有巷道及建築線指定爭議案件。\n（四）其他有關現有巷道及建築線指定爭議案件之交議及研究建議等事項。\n三、本小組置主任委員一人，由本府建設處長兼任，副主任委員由本府建設處副處長或技正兼任，其餘委員由下列人員派\n(\n聘\n)\n兼之：\n（一）台灣省建築師公會宜蘭縣辦事處建築師代表一人。\n（二）本府秘書處法制科長。\n（三）本府工務處土木科長。\n（四）本府地政處地權科長。\n（五）本府建設處城鄉計畫科長。\n（六）本府建設處建築管理科長。\n(\n七\n)\n本府建設處交通科長\n(\n八\n)\n本府消防局災害預防科長\n四、本小組會議由主任委員召集並為會議主席，主任委員因故不能召集或出席時，由副主任委員代理之，主任委員及副主任委員均不能出席時由出席委員共推選一名委員擔任主席。\n五、本小組會議應有半數以上委員出席方得開會，並經出席委員過半數同意始得決議，本府委員因故無法參加會議，得指派相關業務承辦人員代理，並得計入出席委員人數。\n六、本小組為審議案件需要得請當事人或利害關係人到會陳述意見及請有關機關派員列席，必要時並得請當地村里長列席說明。土地所在之鄉鎮公所，應指派專人列席說明。\n七、本小組決議事項應做成紀錄，由有關業務單位以本府名義執行之，其執行情形應提會報告。\n八、本小組委員均為無給職。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:GL000002","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"公發布日":"民國 99 年 01 月 14 日","法規名稱":"宜蘭縣現有巷道及建築線指示爭議案件審議小組設置要點","法規體系":"建設","發文字號":"府建城字第0990007387號"},"promulgation_date":"2010-01-14","revision_date":"2010-01-14","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=GL000002","status":"unknown","title":"宜蘭縣現有巷道及建築線指示爭議案件審議小組設置要點","last_checked_at":"2026-10-06T17:31:32+08:00","last_success_at":"2026-10-06T17:31:32+08:00","verification_status":"fetched","content_hash":"5eeca7ca7ab64c2291d2635511c76018e26d7fbdc6d0eeb4bcd29d585271f6e7","history":[{"observed_at":"2026-10-06T17:31:32+08:00","content_hash":"5eeca7ca7ab64c2291d2635511c76018e26d7fbdc6d0eeb4bcd29d585271f6e7","change_kind":"initial","revision_date":"2010-01-14"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、宜蘭縣政府 (以下簡稱本府) 為辦理本縣內現有巷道之廢止或改道申\n請作業，特依據「宜蘭縣建築管理自治條例」 (以下簡稱本自治條例\n) 第六條第四項之規定，訂定本執行要點。\n二、本縣內現有巷道廢止或改道之申請，依本要點規定辦理，本要點未規\n定者，適用其他相關法令規定。\n三、本府受理申請單位為建設局。\n四、申請現有巷道廢止或改道應檢附下列文件：\n(一) 申請書：格式不拘，應載明申請人姓名、地址、申請土地詳細地號\n及位置。\n(二) 說明書：格式不拘，應載明案由、申請單位或申請人、事實原因及\n使用計畫。\n(三) 計畫圖，包括下列圖件：\n1.位置圖：應標明巷道位置、附近道路、機關學校或其他明顯建築\n物之相關位置。\n2.地籍描繪圖：應描繪一個街廓以上，並標明方位及申請範圍內之\n地段、地號。\n3.現況圖：應依本自治條例第三條第一項第三款規定繪製圖件 (位\n於都市計畫區內者應加繪都市計畫線) ，並分別著色標明廢止或\n改道土地位置及巷道寬度。\n(四) 現況照片。\n(五) 土地權利證明，包括下列文件：\n1.地籍圖謄本及土地登記謄本：最近三個月地政機關核發之正本。\n2.現有巷道廢止同意書：公有土地應徵詢管理機關意見，但申請人\n為土地所有權人者，得免檢附。\n3.新設巷道捐獻土地同意書：新設巷道土地所有權人捐獻土地為道\n路使用之同意書，但僅申請現有巷道廢止時，得免檢附。\n(六) 辦理公告所需計畫圖說，其份數由本府另行通知。\n五、本府受理申請案件後，應於十五天內完成書面審查及通知會勘。經審\n查如檢送之申請書件與規定不合者，應限期通知申請人補正，逾期不\n補正者，不予受理。如廢止或改道計畫不當或有礙公共利益時，應提\n具體意見限期通知申請人修改。逾期不為修改或無法修改者，駁回其\n申請。\n六、依第五點完成初審後，應將擬廢止或改道之說明書圖張貼於本府公告\n欄、申請案所在地之鄉 (鎮、市) 公所，公告徵求異議三十天及舉辦\n說明會，並應將公告及說明會之日期及地點登報周知。\n申請人應於申請廢止或改道巷口明顯處豎立公告牌張貼公告，並拍照\n存證送本府備查。\n七、公告期間之異議案件由本府就實際情況依權責處理，必要時得提本縣\n都市計畫委員會 (以下簡稱縣都委會) 審議。\n經本府或縣都委會審議應修正之案件，應再依第五點規定辦理補正，\n並免再辦理徵求異議公告及舉辦說明會。\n八、經核准廢道案件，應通知申請人辦理廢道，並於本府公告欄、申請案\n所在地之鄉 (鎮、市) 公所公告同意廢道。\n九、經核准廢止及改道案件，應先行通知申請人辦理改道。於新設巷道開\n闢完成，且土地完成捐獻移轉登記為申請案所在地之鄉 (鎮、市) 公\n所有後，本府始通知申請人辦理廢道，並於本府公告欄、該鄉 (鎮、\n市) 公所公告同意廢止及改道。\n十、前點新設巷道之開闢，其相關圖說應經申請案所在地之鄉 (鎮、市)\n公所同意；新設巷道開闢及捐獻之完成，應經該鄉 (鎮、市) 公所辦\n理驗收同意。\n十一、下列地區內之現有巷道，除政府機關為興辦公共工程外，不得申請\n廢止或改道。\n(一) 辦理市地重劃地區。\n(二) 辦理區段徵收地區。\n(三) 辦理都市更新地區。\n(四) 都市計畫禁建區。\n(五) 都市計畫擬變更地區。\n(六) 現有巷道有排水設施經認定無法廢止或改道者。\n十二、受理案件提報縣都委會審議時，應邀請當地村里鄰長列席。\n十三、本要點奉縣長核定後實施，修正時亦同。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:FL034345","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"公發布日":"民國 92 年 06 月 30 日","法規名稱":"宜蘭縣現有巷道廢止或改道執行要點","法規體系":"建設","發文字號":"府建城字第0920078479號"},"promulgation_date":"2003-06-30","revision_date":"2003-06-30","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=FL034345","status":"repealed","title":"宜蘭縣現有巷道廢止或改道執行要點","last_checked_at":"2026-10-06T17:31:34+08:00","last_success_at":"2026-10-06T17:31:34+08:00","verification_status":"fetched","content_hash":"92f9324ab2065cd91e39016382fc46363840aeaf4f928dbea08080e29fa16980","history":[{"observed_at":"2026-10-06T17:31:34+08:00","content_hash":"92f9324ab2065cd91e39016382fc46363840aeaf4f928dbea08080e29fa16980","change_kind":"initial","revision_date":"2003-06-30"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"宜蘭縣申請土地改良費用證明作業要點.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3676&id=GL000696&type=LAW"},{"name":"(附件一)土地改良費用證明申請書.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3674&id=GL000696&type=LAW"},{"name":"(附件四)竣工申報書.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3673&id=GL000696&type=LAW"},{"name":"申辦流程圖.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3672&id=GL000696&type=LAW"},{"name":"抽驗紀錄表.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3671&id=GL000696&type=LAW"},{"name":"會勘審查表.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3670&id=GL000696&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、本要點依平均地權條例施行細則第十二條訂定之。\n二、土地改良項目指建築基地改良、農地改良及其他用地開發行為\n之土地改良。\n土地改良應符合土地使用管制規定。\n三、本要點執行單位為本府建設處。\n四、申請土地改良，應檢附下列文件：\n(一)申請書(附件一)－載明申請人姓名、住址、電話、身分證\n字號、土地資料及土地改良內容與申請目的。\n(二)申請人身分證明影本。\n(三)土地現況照片。\n(四)土地改良計畫書，內容包括：\n1.位置圖、現況圖（以地籍為底圖，載明改良地點、鄰地、面臨\n道路及排水溝高程差及地上物）、剖面圖。\n2.目的事業或主管機關核准文件（不須目的事業主管機關許可者\n免附）。\n3.挖填土方量、土質、填方土石來源或挖方再利用方式、施工法\n、施工機具及工程概算。\n4.土地改良設計圖（如有駁坎、給、排水溝等設施者一併附詳細\n圖）。\n5.預定開、竣工日期。\n6.需土或棄土運輸路線圖及流向管理計畫、汙染防治計畫。\n7.土地改良面積超過三百三十平方公尺、挖填方量超過一千立方\n公尺或改良費用總計超過十萬元整者，土地改良計畫書應由執\n業技師簽證負責。\n圖表附件：\n(附件一)土地改良費用證明申請書.odt\n五、申請文件審查合格後，由相關單位（本府農業處、水利資源處、\n農田水利會及環保局等）現場勘查，符合規定者，核定土地改良\n計畫書及施工期限。未符規定者，通知申請人限期補正，屆期未\n補正，駁回申請案。\n六、土地改良工程因故未能於核定期限內完工時，應於期限屆滿前敘\n明理由申請展期。展期每次不得超過六個月，並以二次為限。但\n因天災或其他不可歸責申請人之事由，致無法施工者，得扣除實\n際無法施工之天數。\n七、土地改良填方材質須符合改良後之使用目的，其來源以縣內土方\n為原則。挖方再利用方式應符合再利用目的，並附再利用場所同\n意收容證明。\n八、本府於土地改良工程施工中得隨時抽驗；發現與核准計畫不符者\n，應通知限期改善。屆期未改善者，廢止土地改良計畫。\n九、申請人應於土地改良工程完工翌日起十日內檢附下列文件申請本\n證明：\n(一)竣工申報書（附件四）載明申請人姓名、國民身份證號、住\n居所、設計監造技師基本資料（無則免填）、開工、竣工日\n期、各筆土地資料及土地改良費用。\n(二)竣工圖，如與核准土地改良設計圖相符者免附。\n(三)現況照片。\n本府於收到竣工申報書圖後由相關單位（本府農業處、水利資源\n處、農田水利會及環保局）現勘。經查驗符合規定者，核發本證\n明；不符規定者，通知限期改正申請複審，屆期未改正，廢止土\n地改良計畫書。\n圖表附件：\n(附件四)竣工申報書.odt\n十、附件：\n(一)土地改良費用證明申請書。\n(二)土地改良費用證明申請案件會勘審查表。\n(三)土地改良費用證明抽驗記錄表。\n(四)土地改良費用證明竣工申報書。\n(五)土地改良費用證明申辦流程圖。\n圖表附件：\n申辦流程圖.odt\n抽驗紀錄表.odt\n會勘審查表.odt","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:GL000696","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"修正日期":"民國 107 年 12 月 21 日","全文檔案":"宜蘭縣申請土地改良費用證明作業要點.odt","公發布日":"民國 88 年 12 月 09 日","法規名稱":"宜蘭縣申請土地改良費用證明作業要點","法規體系":"建設","發文字號":"府建國字第1070214476號函"},"promulgation_date":"1999-12-09","revision_date":"2018-12-21","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=GL000696","status":"unknown","title":"宜蘭縣申請土地改良費用證明作業要點","last_checked_at":"2026-10-06T17:31:28+08:00","last_success_at":"2026-10-06T17:31:28+08:00","verification_status":"fetched","content_hash":"9e70f1958da8bf5a131dd2b805f59821ce85f931a4673d6d3e581e4567a25a34","history":[{"observed_at":"2026-10-06T17:31:28+08:00","content_hash":"9e70f1958da8bf5a131dd2b805f59821ce85f931a4673d6d3e581e4567a25a34","change_kind":"initial","revision_date":"2018-12-21"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3676&id=GL000696&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3674&id=GL000696&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3673&id=GL000696&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3672&id=GL000696&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3671&id=GL000696&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3670&id=GL000696&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"宜蘭縣畸零地使用規則.doc","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=2868&id=FL023434&type=LAW"},{"name":"附表一~四.pdf","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=2867&id=FL023434&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"第 1 條\n本規則依建築法第四十六條 (以下簡稱本法) 規定訂定之。\n第 2 條\n畸零地及其相鄰土地之使用管理，依本規則之規定。\n前項所稱畸零地係指本法第三條規定地區內面積狹小或地界曲折之基地。\n第 3 條\n本規則所稱面積狹小基地，係指建築基地深度或寬度任一未達下列規定者\n。\n一、一般建築用地 (表一)\n二、側面應留設騎樓之建築基地 (表二)\n前項其他使用區，不包括農業區及保護區。\n依獎勵投資條例或促進產業升級條例開發之工業住宅社區，按第一項表一\n之甲、乙種建築用地及住宅區之規定辦理。\n第 4 條\n本規則所稱道路、正面路寬、最小寬度及最小深度，其定義如下：\n一、道路係指依建築技術規則設計施工編第一條第三十二款規定之道路或\n私設通路或基地內通路。\n二、正面路寬係指基地面前道路之寬度。\n三、最小寬度係指最小深度範圍內基地二側境界線間與道路境界線平行距\n離之最小值。但道路境界線為曲線者，以該曲線與基地兩側境界線交\n點之連線視為道路境界線。\n四、最小深度係指臨接之道路境界線至該基地後側境界線垂直距離之最小\n值。\n建築基地如屬角地應截角時，其寬度及深度係指截角前之寬度及深度。\n第 5 條\n建築基地臨接二條以上道路，起造人得選擇任一道路為面前道路。\n建築基地位於道路末端，其寬度、深度及方位由起造人選定之。\n前二項情形分別以任一道路為面前道路或以任一方位量距，其寬度及深度\n達到本規則所定最小寬度及深度之標準以上者，得不與相鄰土地合併使用\n。\n道路境界線以外另定建築線之建築基地，其寬度及深度應自建築線起算。\n臨接綠帶退縮建築之基地，其寬度應自退縮線起算，深度應自綠帶境界線\n起算。\n第 6 條\n依第三條規定之基地寬度，每增加十公分，其深度得減少二十公分，減少\n後之深度不得小於八公尺。\n應留設前後院地區，其基地深度減前後院深度之差不得小於六公尺。\n應留設側院地區，其基地寬度減側院寬度之差不得小於四公尺。\n應留設騎樓或指定退縮建築之土地，其基地深度減騎樓或退縮地深度之差\n不得小於八公尺。\n第 7 條\n面積狹小之基地非經補足所缺寬度或深度者均不得建築。但符合下列情形\n之一者，不在此限：\n一、需補足深度部份無法補足，但扣除騎樓或指定退縮地後，其基地最小\n深度未小於五公尺且最小面積未小於二十平方公尺者。\n二、需補足寬度部份無法補足，但扣除騎樓或指定退縮地後，其基地最小\n寬度未小於二公尺且最小面積未小於二十平方公尺者。\n三、深度及寬度均無法補足者。\n前項所稱無法補足係指鄰接地為道路、水溝、軍事設施、公共設施用地或\n鄰接地業已建築完成無法合併建築使用者。\n前項所稱業已建築完成，係指於實施建築管理前已興建完成或領有建築執\n照之建築物。\n第 8 條\n地界曲折之基地如可配置符合本規則第三條或第六條規定之最小寬度及深\n度者不視為畸零地。\n第 9 條\n實施區域計畫地區非都市土地在編定使用前或實施都市計畫地區在中華民\n國六十二年七月十二日臺灣省畸零地使用規則發布施行前業經地政機關辦\n理分割完竣，或因都市計畫公共設施用地之劃定逕為分割完竣，面積狹小\n之基地符合於(表三)規定之最小寬度、深度及面積者，准予建築。\n前項基地騎樓部分應計入最小深度，但不列入最小寬度及最小面積。\n應留設側院地區，其基地寬度減側院寬度之差，不得小於三公尺。\n臨接綠帶應退縮建築之基地，其退縮部分不計入最小面積，基地深度減退\n縮地深度之差，不得小於五公尺。\n第 10 條\n實施區域計畫地區非都市土地編定為丁種建築用地及實施都市計畫地區劃\n定為工業區之土地，在中華民國七十五年十一月二日前，業經地政機關辦\n理分割完竣之建築基地，符合(表四)規定之最小寬度、深度者，准予建築，\n不受第三條規定之限制。\n第 11 條\n畸零地所有權人與鄰地所有權人無法達成協議時，欲申請調處者應填具申\n請書並檢附下列書件正本一份、副本十份向本府申請調處：\n一  合併使用土地之土地登記謄本、地籍圖謄本。\n二  相關土地地盤圖，註明需合併使用土地最小面積之寬度及深度。\n三  相關土地所有權人、承租人及他項權利人之姓名、住址。\n四  公告現值及市價概估。\n第 12 條\n本府受理調處畸零地合併時，應於收到申請書之日起一個月內，通知有關\n土地所有權人、承租人及他項權利人進行調處，調處之程序如下：\n一  審查合併土地之位置、形狀及申請人所規劃合併土地最小面積、寬度\n及深度，必要時並酌予調整。\n二  查估合併土地附近之買賣市價，徵詢參與調處人之意見，並由各土地\n所有權人協商或公開議價，互為買賣或合併建築。\n三  調處時，雙方意見不一致或一方缺席經再次通知不到者，視為調處一\n次不成立。\n第 13 條\n畸零地於調處二次不成立時，基地所有權人及鄰接土地所有權人得依本法\n第四十五條之規定預繳承買價款，申請徵收。\n第 14 條\n本府設畸零地調處委員會，以下列人員為委員，由建設局局長為召集人：\n一、建設局局長。\n二、秘書室法規課課長。\n三、地政局代表一人。\n四、財政局代表一人。\n五、建築管理課課長\n六、城鄉計畫課課長。\n七、臺灣省建築師公會宜蘭縣辦事處代表一人。\n八、宜蘭縣建築投資商業同業公會代表一人。\n第 15 條\n申請承購公有畸零地，應檢附本府核發之公有畸零地合併使用證明書。\n前項證明書核發基準由本府另定之。\n第 16 條\n本規則自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:FL023434","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"修正日期":"民國 94 年 01 月 03 日","公發布日":"民國 91 年 03 月 06 日","圖表附件":"宜蘭縣畸零地使用規則.doc 附表一~四.pdf","法規名稱":"宜蘭縣畸零地使用規則","法規體系":"建設","發文字號":"府秘法字第0940000191-B號"},"promulgation_date":"2002-03-06","revision_date":"2005-01-03","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=FL023434","status":"unknown","title":"宜蘭縣畸零地使用規則","last_checked_at":"2026-10-06T17:31:21+08:00","last_success_at":"2026-10-06T17:31:21+08:00","verification_status":"fetched","content_hash":"40a6cdd1293f853e07acd5e183ee1ca05f092ba6e2fcc90a98644f90a3a4dce4","history":[{"observed_at":"2026-10-06T17:31:21+08:00","content_hash":"40a6cdd1293f853e07acd5e183ee1ca05f092ba6e2fcc90a98644f90a3a4dce4","change_kind":"initial","revision_date":"2005-01-03"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=2868&id=FL023434&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=2867&id=FL023434&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"(1130624)宜蘭縣簡化實施都市計畫以外地區建築管理辦法修正總說明及條文對照表.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4692&id=GL000132&type=LAW"},{"name":"(1130624)宜蘭縣簡化實施都市計畫以外地區建築管理辦法.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4693&id=GL000132&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"第一條\n本辦法依建築法第九十九條之一規定訂定之。\n第二條\n本辦法適用於宜蘭縣實施都市計畫以外地區。\n第三條\n宜蘭縣政府（以下簡稱本府）及各鄉、鎮公所審查非供公眾使用建築物及雜項工\n作物之建築執照申請案件，得以高中（職）以上建築、土木相關科系畢業，具有\n三年以上工程經驗，並經依法任用者為審查人員，不受建築法第三十四條第二項\n所定學歷、考試資格及工程經驗之限制。\n第四條\n起造人申請下列建築物建造執照、雜項工作物雜項執照，於配置圖說載明聯外道\n路關係者，其建築基地得免臨接道路，且得免檢附建築線指示（定）圖：\n一、依交通部訂頒露營場管理相關規定，准予設置之露營設施。\n二、公有之廁所、涼亭、賞鳥亭、眺望臺、收費站等建築物。\n前項建築物或雜項工作物建築基地臨接省道、縣道或鄉道之公路者，起造人申請\n建造或雜項執照時，應檢附建築線指示(定)圖。\n第一項建築基地之聯外道路及排水設施，由起造人與該土地所有權人自行協調，\n並依建築法第二十六條第二項規定負其責任。\n第五條\n前條第一項所定建築物，本府及各鄉、鎮公所得免依宜蘭縣建築工程施工勘驗\n執行辦法第三條規定，辦理現場勘驗。\n第六條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:GL000132","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"修正日期":"民國 113 年 06 月 26 日","全文檔案":"(1130624)宜蘭縣簡化實施都市計畫以外地區建築管理辦法.odt","公發布日":"民國 100 年 06 月 03 日","法規名稱":"宜蘭縣簡化實施都市計畫以外地區建築管理辦法","法規體系":"建設","發文字號":"府秘法字第1130105343B號令","立法理由":"(1130624)宜蘭縣簡化實施都市計畫以外地區建築管理辦法修正總說明及條文對照表.odt"},"promulgation_date":"2011-06-03","revision_date":"2024-06-26","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=GL000132","status":"unknown","title":"宜蘭縣簡化實施都市計畫以外地區建築管理辦法","last_checked_at":"2026-10-06T17:31:10+08:00","last_success_at":"2026-10-06T17:31:10+08:00","verification_status":"fetched","content_hash":"e97b886051c679fc56b2b8d0daf98b55f332d690684b2a54d932f9eff58c6847","history":[{"observed_at":"2026-10-06T17:31:10+08:00","content_hash":"e97b886051c679fc56b2b8d0daf98b55f332d690684b2a54d932f9eff58c6847","change_kind":"initial","revision_date":"2024-06-26"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4692&id=GL000132&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4693&id=GL000132&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"(1081031)宜蘭縣臨時性建築物管理辦法第五條及第八條修正總說明及對照表.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3150&id=GL000109&type=LAW"},{"name":"(1120818)宜蘭縣臨時性建築物管理辦法部分條文修正總說明及對照表.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4112&id=GL000109&type=LAW"},{"name":"(1120818)全文--宜蘭縣臨時性建築物管理辦法.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4113&id=GL000109&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"第一條\n宜蘭縣政府(以下簡稱本府)為辦理臨時性建築物管理，依宜蘭縣建築\n管理自治條例第三十九條第四項規定，訂定本辦法。\n第二條\n本辦法所稱臨時性建築物，指符合建築法第四條規定，經目的事業主\n管機關許可，供下列用途使用之臨時構造物或雜項工作物：\n一、辦理文教藝術、體育競技、育樂休閒、慈善公益、生活新知、民\n俗節慶、商品販賣或競選集會等活動之建築物。\n二、房屋銷售展示屋或接待所。\n三、工程施工所需之工務所。\n第三條\n申請人所申請搭建之臨時性建築物，應符合區域計畫法或都市計畫法\n等有關土地容許使用及使用強度之規定。\n第四條\n有搭建及使用臨時性建築物之需求者，應填具申請書，並檢附下列書\n圖文件，向本府申請；經本府許可後，始得搭建：\n一、目的事業主管機關許可文件。\n二、土地使用權利證明文件：\n（一）土地登記謄本。\n（二）地籍圖謄本。\n（三）土地使用權同意書；申請人為土地所有權人者，免附。\n三、建築師及專業技師簽證負責表。\n四、基地現況照片。\n五、自動拆除切結書。\n六、工程圖樣三份：\n（一）基地位置圖：標明基地位置、方位、都市計畫土地使用分區\n或區域計畫土地使用編定。\n（二）地盤圖：於地籍圖描繪圖上標示基地方位、地號、境界線、\n臨接道路名稱、寬度及建築物之建築面積投影圖。\n（三）配置圖：標明基地方位、地形、四周道路、附近建築物層數\n與構造等、申請建築物之地面層平面圖、基地標高、水系統\n及排水方向。\n（四）面積計算表。\n（五）建築物各層平面圖及屋頂平面圖：標明各部分之用途及尺寸\n，其比例尺不得小於二百分之一。\n（六）建築物各向立面圖，其比例尺不得小於二百分之一。\n（七）各層結構平面圖，並標明結構材料強度。\n七、結構計算書。\n八、其他必要設備圖說。\n前項申請書，應載明臨時性建築物依建築物使用類組及變更使用辦法\n第二條附表二規定使用項目之用途。\n第一項工程圖樣、結構計算書及設備圖說，應由建築師及專業技師簽\n證負責。\n申請人應自本府許可搭建臨時性建築物之日起三個月內搭建完成並申\n請臨時使用許可；屆期未申請者，原搭建許可失其效力，建築物依違\n章建築處理辦法辦理。\n第五條\n臨時性建築物之用途為房屋銷售展示屋、接待所或工程施工所需工務\n所者，應於領得建造執照或經公共工程主辦機關核定者後，始得依本\n辦法申請搭建。\n前項臨時性建築物，應符合下列規定：\n一、總樓地板面積不得大於六百六十平方公尺，開挖深度不得超過一\n點五公尺，且不得建造地下室。\n二、屋簷高度不得超過十二公尺。\n三、採非防火構造者，應由基地境界線退縮三公尺以上建築；基地內\n二幢建築物間距淨寬應達六公尺以上。\n四、建築工程施工所需之工務所，得於申報建築執照開工時併同施工\n計畫書辦理。\n第六條\n臨時性建築物使用期間在三日以內，舞台或高度在六公尺以下無壁體\n之臨時攤棚，經目的事業主管機關許可後即可搭建，不適用本辦法之\n規定。\n第七條\n申請人應於臨時性建築物竣工後，檢附下列書圖文件向本府申請核發\n臨時使用許可：\n一、申請書。\n二、原領許可文件。\n三、建築物各向立面竣工相片。\n四、消防設備查驗合格證明。\n五、建築物竣工平面圖及立面圖(現況與原許可圖說相符者，免附)。\n六、建築師勘驗建築物與申請圖說相符之證明。\n臨時性建築物變更設計得併竣工審查辦理，除應檢附前項規定之文件\n外，另應檢附第四條第一項第四、七、八款規定之文件。\n第八條\n本府應視臨時性建築物使用之目的，許可其使用期限，最長不得逾三\n年。\n有延長使用期限之需求者，原申請人應於原許可使用期限內，檢附設\n計建築師及專業技師出具之建築物結構安全勘檢證明書，向本府提出\n申請。延長使用許可，以二次為限，每次不得逾一年。\n原使用期限屆滿後始申請延長使用許可者，於本府許可前，不得使用\n該臨時性建築物；本府許可後，其使用期限自前次期限屆滿日之翌日\n起算。\n前項臨時性建築物有繼續使用之需求者，申請人得於許可使用期限屆\n滿前，重行申請臨時搭建許可或申請建築執照。\n第九條\n臨時性建築物許可使用期限屆滿後，申請人應自屆滿日起十日內，自\n行拆除完畢；因故不能完成拆除時，得申請展期一次，以三十日為限\n，屆期未拆除者，依違章建築處理辦法辦理。\n第十條\n臨時性建築物施工中或使用期間本府得隨時派員檢查，申請人不得拒\n絕，並應依指示通知設計監造建築師及專業技師會同檢查。\n第十一條\n符合本辦法規定之臨時性建築物，申請人得依本府所核發之臨時使用\n許可，申請臨時水電。\n第十二條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:GL000109","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"修正日期":"民國 112 年 08 月 18 日","全文檔案":"(1120818)全文--宜蘭縣臨時性建築物管理辦法.odt","公發布日":"民國 99 年 02 月 09 日","法規名稱":"宜蘭縣臨時性建築物管理辦法","法規體系":"建設","發文字號":"府秘法字第1120147045B號","立法理由":"(1081031)宜蘭縣臨時性建築物管理辦法第五條及第八條修正總說明及對照表.odt (1120818)宜蘭縣臨時性建築物管理辦法部分條文修正總說明及對照表.odt"},"promulgation_date":"2010-02-09","revision_date":"2023-08-18","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=GL000109","status":"unknown","title":"宜蘭縣臨時性建築物管理辦法","last_checked_at":"2026-10-06T17:31:11+08:00","last_success_at":"2026-10-06T17:31:11+08:00","verification_status":"fetched","content_hash":"39dee68aedd5259e92cc31c71948ea7e7ce8a645b6791de194aa1c74b86a856e","history":[{"observed_at":"2026-10-06T17:31:11+08:00","content_hash":"39dee68aedd5259e92cc31c71948ea7e7ce8a645b6791de194aa1c74b86a856e","change_kind":"initial","revision_date":"2023-08-18"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3150&id=GL000109&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4112&id=GL000109&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4113&id=GL000109&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"宜蘭縣舊違章建築修繕辦法.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3320&id=FL023446&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"第1條\n本辦法依違章建築處理辦法第十二條規定訂定之。\n第2條\n舊違章建築之修繕，除法令另有規定外，悉依本辦法之規定。\n第3條\n本辦法用詞，定義如下:\n一、舊違章建築:指中華民國八十六年十二月三十一日以前建\n造完成之違章建築。\n二、修繕:指建築物之基礎、樑柱、承重牆壁、樓地板、屋架\n或屋頂，其中任何一種未過半之修理或變更。但屋架上之\n桁條、椽子、屋面板及屋面瓦之修理或變更，不在此限。\n第4條\n舊違章建築修繕之申請人，應為該建築物之所有人。\n第5條\n申請舊違章建築修繕者，應填具申請書一份，並檢附下列文件\n、資料向宜蘭縣政府(以下簡稱本府)提出：\n一、切結書一份。\n二、修繕前房屋現況照片正面、側面、背面各二張及擬修繕部\n分，註明尺寸、高度及材質之平(立)面簡圖二份。\n三、下列證明文件之一：\n(一)建物謄本或建物登記證明。\n(二)戶口遷入證明。\n(三)完納稅捐證明。\n(四)繳納自來水費或電費證明。\n第6條\n本府受理前條申請案件，經審查無誤後，發給許可函。\n申請人收到許可函後，始得動工，並於收到許可函之次日起三\n個月內修繕完竣；屆期未修繕完竣者，得申請延期三個月，並\n以一次為限。\n未於前項期限內修繕完竣者，許可函失其效力。\n第7條\n申請人應依本府許可圖樣、地點施工；未經許可，不得擅自變\n更原有形狀、構造或增加面積、高度。\n第8條\n舊違章建築有下列情形之一者，不得申請修繕：\n一、本府以書面通知或公告，限期拆除(遷)或整理。\n二、已全部倒塌或毀損。\n第9條\n本府發給之許可函，為許可修繕舊違章建築之文件，不得為任\n何其他用途使用。\n修繕完成之舊違章建築經本府或其他機關依法強制拆除者，申\n請人不得以本府曾發給許可函為由，要求補償或賠償。\n第10條\n舊違章建築修繕有下列各款情形之一者，視為新發生之違章建\n築，本府應依違章建築處理辦法之規定處理：\n一、未經許可，擅自修繕。\n二、未經許可，擅自變更原有形狀、構造或增加面積、高度。\n三、未依許可圖樣施工或修繕之地點與許可地點不符。\n四、許可函已失其效力。\n五、申請人出具之切結書內容有虛偽不實之情形。\n六、修繕行為違反建築法或相關法令規定。\n第11條\n因舊違章建築修繕涉及土地、建築物權利爭執者，申請人應自\n行負法律上之一切責任。\n第12條\n本辦法所需書表文件格式，由本府另定之。\n第13條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:FL023446","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"修正日期":"民國 109 年 12 月 25 日","公發布日":"民國 61 年 01 月 29 日","法規名稱":"宜蘭縣舊違章建築修繕辦法","法規體系":"建設","發文字號":"府秘法字第1090214479B號令","立法理由":"宜蘭縣舊違章建築修繕辦法.odt"},"promulgation_date":"1972-01-29","revision_date":"2020-12-25","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=FL023446","status":"unknown","title":"宜蘭縣舊違章建築修繕辦法","last_checked_at":"2026-10-06T17:31:16+08:00","last_success_at":"2026-10-06T17:31:16+08:00","verification_status":"fetched","content_hash":"d269bfa1f2326cc9790856471d762aae29957ebd6be8284514decceb53573542","history":[{"observed_at":"2026-10-06T17:31:16+08:00","content_hash":"d269bfa1f2326cc9790856471d762aae29957ebd6be8284514decceb53573542","change_kind":"initial","revision_date":"2020-12-25"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3320&id=FL023446&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"宜蘭縣辦理指定建築線作業辦法修正總說明及對照表.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3891&id=GL000621&type=LAW"},{"name":"宜蘭縣辦理現有巷道認定及指定建築線作業辦法.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3892&id=GL000621&type=LAW"},{"name":"附件1-申請書.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3893&id=GL000621&type=LAW"},{"name":"附件2-建築線作業辦法附圖.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3894&id=GL000621&type=LAW"},{"name":"附件3-宜蘭縣巷道管理維護證明書).odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3895&id=GL000621&type=LAW"},{"name":"附件4.pdf","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3896&id=GL000621&type=LAW"},{"name":"附件1-申請書.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3887&id=GL000621&type=LAW"},{"name":"附件2-建築線作業辦法附圖.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3888&id=GL000621&type=LAW"},{"name":"附件3-宜蘭縣巷道管理維護證明書).odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3889&id=GL000621&type=LAW"},{"name":"附件4.pdf","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3890&id=GL000621&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"第一條\n宜蘭縣政府(以下簡稱本府)為辦理現有巷道認定及指定建築線作業，依宜蘭縣建築管\n理自治條例(以下簡稱本自治條例)第五條第四項及第七條第二項規定，訂定本辦法。\n第二條\n本自治條例第五條第一項所定現有巷道，認定權責機關(單位)如下：\n一、經農地重劃所闢(留)設供通行使用，並由政府機關管理維護之農路，為本府地政\n處。\n二、政府機關開闢維護，或接管之通路，為開闢及管理維護或接管之機關。\n三、私設通路或私有通路經土地所有權人捐贈土地為道路使用，為受贈之鄉(鎮、市)\n公所。\n四、中華民國七十三年十一月七日建築法修正公布前，曾指定建築線之現有巷道，為\n本府建設處。\n五、經政府機關接管並公告供一般道路通行使用之水防道路，為接管機關。\n六、巷道最小寬度達二公尺以上，經政府機關出具管理維護證明者，為本府交通處、\n建設處。\n第三條\n依本自治條例第五條第一項第一款規定申請既成道路證明者，應填具申請書(如附件\n一)，並檢附下列文件、資料，向道路管理機關提出：\n一、身分證明文件影本。\n二、位置及實測現況套繪地籍圖：含一個街廓以上，並標明地段、地號、方位、申請\n土地範圍、各種公共設施及道路之寬度；其比例尺不得小於地籍圖。\n三、實地現況照片。\n四、其他證明文件。\n圖表附件：\n附件1-申請書.odt\n第四條\n道路管理機關認定之既成道路，應符合下列要件：\n一、為不特定之公眾通行所必要，而非僅為通行之便利或省時。\n二、於公眾通行之初，土地所有權人並無阻止之情事。\n三、經歷之年代久遠而未曾中斷。\n第五條\n本自治條例第五條第一項第七款之現有巷道，依現有資料無法認定其範圍者，得依下\n列方式認定之(圖例如附件二)：\n一、單向巷道臨接可指定建築線道路者：以編有相同名稱巷道行經範圍至路口為認定\n範圍(如圖例一）。\n二、雙向巷道臨接可指定建築線道路者：以編有相同名稱巷道行經範圍至兩側路口為\n認定範圍(如圖例二）。\n前項巷道未臨接可指定建築線之道路者，其巷道範圍，應由第二條權責機關(單位)將\n該巷道毗鄰之通路認定為本自治條例第五條所定現有巷道後，再依前項規定認定之(如\n圖例三)。\n第一項巷道無名稱或所行經範圍有爭議者，以巷道維護機關認定之主要出入巷道為準\n，巷道維護機關無法認定主要出入巷道者，以曾指定建築線之基地所臨巷道至得指定\n建築線道路路口之最短距離為準(如圖例四、五）。\n第一項巷道位屬山坡地者，得以曾指定建築線之基地至可指定建築線道路路口為認定\n範圍。\n圖表附件：\n附件2-建築線作業辦法附圖.odt\n第六條\n依本自治條例第五條第一項第九款規定申請認定現有巷道者，應填具申請書，並檢附\n下列文件、資料，向本府交通處提出：\n一、鄉(鎮、市)公所或道路管理機關出具供公眾通行且管理維護二十年以上之證明(如\n附件三)。\n二、包括下列圖說之文件七份：\n(一)地籍描繪圖：標示基地位置、申請認定之巷道範圍及連接其他可指定建築線\n之道路。\n(二)基地位置圖：標示基地位置、附近道路、機關、學校及其他明顯建築物之相\n關位置。\n(三)經建築師或專業技師簽證之現況實測圖：繪圖範圍及其比例尺同地籍描繪圖\n，並標示申請認定巷道下列位置之寬度：\n1.起始處、中點及終止處。\n2.轉折處。\n3.寬度標示位置間距逾一百公尺，於適當處增加寬度標示。\n三、臺灣地區像片基本圖第三版或二十年以上之空照像片，並標示申請路段全線範圍\n、基地位置及其他可指定建築線之道路。\n前項文件、資料有欠缺或不符合規定，經本府通知限期補正，屆期未補正或補正不完\n全者，駁回其申請。\n本府就第一項第二款、第三款文件、資料內容有疑義者，得會同有關機關並通知申請\n人至現場勘查，必要時得通知申請人向地政機關申請鑑界。\n圖表附件：\n附件3-宜蘭縣巷道管理維護證明書).odt\n第七條\n申請認定之巷道經審查符合本自治條例第五條第一項第九款規定者，由本府及申請基\n地所在地之鄉（鎮、市）公所公告三十日。\n申請認定巷道之法律上利害關係人，在前項公告期間內有異議者，得以書面載明理由\n並檢附相關證明文件、資料，向本府提出。\n第一項公告期滿無人提出異議或異議無理由者，本府應許可現有巷道認定之申請；公\n告期間內有提出異議且異議有理由者，本府得許可申請人部分之申請或駁回其申請。\n第八條\n申辦指定建築線者，應填具申請書，並檢附下列文件、資料，向本府提出：\n一、代理人之代理委託書；無代理人者，免附。\n二、標示拍攝日期之最近三個月基地及所鄰巷道現況照片；近照及遠照各二張以上。\n三、法院或權責機關(單位)認定現有巷道之證明文件。\n四、最近三個月之地籍圖謄本，其比例尺須與建築線指定圖相同。\n五、最近三個月之土地登記謄本。\n六、經測量技師或建築師測繪簽證之建築線指定圖，套繪地籍及樁位，並於其上著色\n標示；建築基地著紅色、道路著黃褐色、水溝著水藍色。\n依本自治條例第五條第一項第七款規定申辦者，應另檢附第六條第一項第二款規定之\n圖說文件一份。\n第一項第六款建築線指定圖，其分區界線不明確，或顯與現況不符者，駁回其申請。\n第一項及第二項文件、資料有欠缺或不符規定，經本府通知限期補正，屆期未補正或\n補正不完全者，駁回其申請。\n第九條\n申請之巷道有下列情形之一者，不予指定建築線：\n一、最小寬度未達二公尺。\n二、申請基地坐落於禁限建範圍內。但經該主管機關同意者，不在此限。\n三、其他經道路主管機關或相關權責機關查明，對公益有不利影響。\n第十條\n本自治條例第五條及第六條所定之寬度，以現況鋪設柏油或水泥路面範圍為限；其邊\n界如附件四所示，認定標準如下：\n一、未臨排水溝者：以巷道邊緣為界。\n二、臨排水溝者：以排水溝內緣為界。但經道路管理機關認定排水溝為道路附屬設施\n者，以排水溝外緣為界。\n三、臨加蓋排水溝者：以排水溝外緣為界。\n四、臨建築物者：以建築物或圍牆邊緣為界。\n五、臨設有陽臺之建築物者：以陽臺邊緣投影為界。\n六、臨駁崁者：以駁崁頂部邊緣為界。\n圖表附件：\n附件4.pdf\n第十一條\n建築基地毗鄰尚未依計畫寬度開闢完成之縣、鄉道者，其建築線之指定以現況道路中心\n線，兩旁均等退讓至計畫寬度為原則。\n前項縣、鄉道位於彎道處且既有建築物密集處或周邊有水利構造物時，應經道路主管機\n關確認計畫道路邊界線後，再據以指定建築線。\n​​​​​​​第十二條\n本府核發建築線指定成果圖後，發現該成果圖內經建築師或專業技師簽證之現況實測圖\n與實際現況不符時，本府得廢止核發該建築線指定成果圖之處分，並追究簽證建築師或\n專業技師之責任。\n第十三條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:GL000621","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"修正日期":"民國 112 年 01 月 31 日","全文檔案":"宜蘭縣辦理現有巷道認定及指定建築線作業辦法.odt","公發布日":"民國 108 年 10 月 24 日","圖表附件":"附件1-申請書.odt 附件2-建築線作業辦法附圖.odt 附件3-宜蘭縣巷道管理維護證明書).odt 附件4.pdf","法規名稱":"宜蘭縣辦理現有巷道認定及指定建築線作業辦法","法規體系":"建設","發文字號":"府秘法字第1120022475B號令","立法理由":"宜蘭縣辦理指定建築線作業辦法修正總說明及對照表.odt"},"promulgation_date":"2019-10-24","revision_date":"2023-01-31","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=GL000621","status":"unknown","title":"宜蘭縣辦理現有巷道認定及指定建築線作業辦法","last_checked_at":"2026-10-06T17:31:15+08:00","last_success_at":"2026-10-06T17:31:15+08:00","verification_status":"fetched","content_hash":"3c7764dd7e075280fa5a8c917e2aa9659db60a5a89ef540c061c2693b3a9b9fc","history":[{"observed_at":"2026-10-06T17:31:15+08:00","content_hash":"3c7764dd7e075280fa5a8c917e2aa9659db60a5a89ef540c061c2693b3a9b9fc","change_kind":"initial","revision_date":"2023-01-31"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3891&id=GL000621&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3892&id=GL000621&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3893&id=GL000621&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3894&id=GL000621&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3895&id=GL000621&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3896&id=GL000621&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3887&id=GL000621&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3888&id=GL000621&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3889&id=GL000621&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3890&id=GL000621&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"農業設施建築物之使用類〈組〉別.doc","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=783&id=GL000094&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、宜蘭縣政府（以下簡稱本府）為將本縣內各類農、林、畜牧、養殖業暨休閒農業設施（以下簡稱農業設施）建築物，依建築物使用類組及變更使用辦法第二條規定之使用類別、組別辦理分類\n(\n組\n)\n，特訂定本原則。\n二、農業設施建築物之使用類\n(\n組\n)\n別如附表；附表未規定者由本府建設處會同農業處認定之。\n圖表附件：\n農業設施建築物之使用類〈組〉別.doc\n三、本原則奉 縣長核定後實施，修正時亦同。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:GL000094","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"公發布日":"民國 99 年 12 月 07 日","法規名稱":"宜蘭縣農、林、畜牧、養殖業暨休閒農業設施建築物使用類組認定原則","法規體系":"建設","發文字號":"府建管字第0990176980號"},"promulgation_date":"2010-12-07","revision_date":"2010-12-07","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=GL000094","status":"unknown","title":"宜蘭縣農、林、畜牧、養殖業暨休閒農業設施建築物使用類組認定原則","last_checked_at":"2026-10-06T17:31:32+08:00","last_success_at":"2026-10-06T17:31:32+08:00","verification_status":"fetched","content_hash":"965df4d3ce48740b2900e3933837bba2ffa6ed2d34a9db8b84fe48e2bd6c3e4b","history":[{"observed_at":"2026-10-06T17:31:32+08:00","content_hash":"965df4d3ce48740b2900e3933837bba2ffa6ed2d34a9db8b84fe48e2bd6c3e4b","change_kind":"initial","revision_date":"2010-12-07"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=783&id=GL000094&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"規範內容.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=2534&id=GL000581&type=LAW"},{"name":"img-Y15092654 (1).pdf","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3780&id=GL000581&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、宜蘭縣政府（下稱本府）為執行都市計畫法（下稱本法）第\n七十九條規定，裁處土地及建築物使用行為違反本法或依本\n法所發布之命令案件，視違規情節，建立裁處額度，特訂定\n本基準。\n二、違反本法或依本法所發布之命令案件裁罰基準如附表。\n圖表附件：\nimg-Y15092654 (1).pdf\n三、本法八十九年一月二十六日修正公布施行前，違規行為已終\n了但違規狀態繼續者，得視違規使用情節審酌減輕處罰。\n四、違規情節有下列情形之一者，得加重處罰：\n（一）違反使用案件涉及危害公共安全。\n（二）農地違法施工中。\n（三）無法興建農舍之農地，而以農業設施擴大違法興建，\n並從事營業行為。\n（四）農地供工廠使用，但依工廠管理輔導辦法申請臨時登\n記者，不在此限。\n（五）農地供餐廳、賣場、便利商店營業使用。\n（六）農地違法興建建築物面積投影面積超過一百平方公尺\n以上。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:GL000581","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"公發布日":"民國 107 年 11 月 16 日","圖表附件":"規範內容.odt","法規名稱":"宜蘭縣違反都市計畫法案件裁罰基準","法規體系":"建設","發文字號":"1070191683B號 令"},"promulgation_date":"2018-11-16","revision_date":"2018-11-16","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=GL000581","status":"unknown","title":"宜蘭縣違反都市計畫法案件裁罰基準","last_checked_at":"2026-10-06T17:31:39+08:00","last_success_at":"2026-10-06T17:31:39+08:00","verification_status":"fetched","content_hash":"fbc35b24fa70ca21dc5ea4d4e497a2daa1558d3dc3f77effa9ff6eaed0effba3","history":[{"observed_at":"2026-10-06T17:31:39+08:00","content_hash":"fbc35b24fa70ca21dc5ea4d4e497a2daa1558d3dc3f77effa9ff6eaed0effba3","change_kind":"initial","revision_date":"2018-11-16"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=2534&id=GL000581&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3780&id=GL000581&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"宜蘭縣違規廣告物取締業務權責劃分規定附表.pdf","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=2501&id=FL038621&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、宜蘭縣政府（以下簡稱本府）為有效管理、執行違規廣告物取締，使\n取締業務分工明確，以維護公共安全、交通秩序、市容觀瞻及環境衛\n生，並提昇執行效率，特訂定本規定。\n二、各類廣告物之分類及主管機關取締執行權責劃分如附表：\n圖表附件：\n宜蘭縣違規廣告物取締業務權責劃分規定附表.pdf\n三、本規定奉　縣長核定後實施，修正時亦同。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:FL038621","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"修正日期":"民國 107 年 10 月 05 日","公發布日":"民國 92 年 01 月 06 日","法規名稱":"宜蘭縣違規廣告物取締業務權責劃分規定","法規體系":"建設","發文字號":"府建使字第1070167276號"},"promulgation_date":"2003-01-06","revision_date":"2018-10-05","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=FL038621","status":"unknown","title":"宜蘭縣違規廣告物取締業務權責劃分規定","last_checked_at":"2026-10-06T17:31:28+08:00","last_success_at":"2026-10-06T17:31:28+08:00","verification_status":"fetched","content_hash":"48cded77a4ff07f8d272c1914bb859f4c3554f0aa5ef3f9db034e818c3b47231","history":[{"observed_at":"2026-10-06T17:31:28+08:00","content_hash":"48cded77a4ff07f8d272c1914bb859f4c3554f0aa5ef3f9db034e818c3b47231","change_kind":"initial","revision_date":"2018-10-05"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=2501&id=FL038621&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"宜蘭縣都市土地開發許可與都市設計及交通影響評估審查收費標準.pdf","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=1998&id=FL043187&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"第 1 條\n本標準依規費法第七條及第十條規定訂定之。\n第 2 條\n宜蘭縣政府（以下簡稱本府）受理下列申請案件，應依本標準收取審查費\n：\n一、都市土地開發許可、都市設計案件須經都市計畫委員會或都市設計審\n議委員會審查同意者。\n二、依建築技術規則建築設計施工編第二百九十條、停車場法第二十條、\n開發行為環境影響評估作業準則第十六條、第四十二條、第四十三條\n、第四十七條辦理交通影響評估審查之案件。\n三、依都市計畫土地使用分區管制要點規定，申請放寬退縮建築或免\n留設騎樓案件，須經都市計畫委員會或都市設計審議委員會審查\n同意者。\n前項案件，應於收件時繳納審查費，經通知繳納，仍未繳納者，駁回其申請。\n第 3 條\n申請都市土地開發許可或都市設計審議之案件，申請基地面積在一公頃以\n下者，每件收取新台幣三萬元，每增加一公頃（含零數），加收取新台幣\n一萬元。\n交通影響評估審查案件，申請樓地板面積在一萬平方公尺以下者，每件收\n取新台幣三萬元，每增加五千平方公尺（含零數），加收取新台幣一萬元\n。\n申請放寬退縮建築或免留設騎樓案件，每件收取新台幣一萬元。\n第 4 條\n申請人應以現金或即期支票繳納審查費，未經繳納者，不予受理審查。\n第 5 條\n本標準所規定之審查費經繳納後，除有溢繳或誤繳情形，依規費法相關規\n定辦理外，不得要求退費。\n第 6 條\n本標準應考量辦理費用、成本變動趨勢或消費者物價指數變動等因素，至\n少每三年定期檢討一次。\n第 7 條\n本標準自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:FL043187","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"修正日期":"民國 106 年 07 月 20 日","公發布日":"民國 96 年 05 月 21 日","圖表附件":"宜蘭縣都市土地開發許可與都市設計及交通影響評估審查收費標準.pdf","法規名稱":"宜蘭縣都市土地開發許可與都市設計及交通影響評估審查收費標準","法規體系":"建設","發文字號":"府秘法字第1060117096-B號 令"},"promulgation_date":"2007-05-21","revision_date":"2017-07-20","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=FL043187","status":"unknown","title":"宜蘭縣都市土地開發許可與都市設計及交通影響評估審查收費標準","last_checked_at":"2026-10-06T17:31:19+08:00","last_success_at":"2026-10-06T17:31:19+08:00","verification_status":"fetched","content_hash":"efa3c92a6424e9f55e132d51e98f3a9bc7ab09c110f7300ef32fc06c65bcf802","history":[{"observed_at":"2026-10-06T17:31:19+08:00","content_hash":"efa3c92a6424e9f55e132d51e98f3a9bc7ab09c110f7300ef32fc06c65bcf802","change_kind":"initial","revision_date":"2017-07-20"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=1998&id=FL043187&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、宜蘭縣政府（以下簡稱本府）為辦理都市更新條例第十六條及第三十\n二條有關審議都市更新事業計畫、權利變換計畫及處理有關爭議，特\n設都市更新及爭議處理審議會（以下簡稱審議會），並訂定本要點。\n二、本會職掌並辦理下列事項：\n（一）關於都市更新地區公告招商評選、都市更新事業計畫擬定及變更審\n議事項。\n（二）關於權利變換計畫擬定、變更之審議事項。\n（三）關於權利變換有關爭議之處理事項。\n（四）其他有關都市更新之交議及研究建議事項。\n三、審議會置委員十三人至十七人，其中一人為主任委員，由縣長或其指\n派人員兼任之；一人為副主任委員，由縣長指派本府人員兼任之；其\n餘委員，由縣長分別就下列人員聘（派）之：\n（一）主管業務及有關機關之代表。\n（二）具有都市計畫、建築、景觀、社會、法律、交通、財經、土地開發\n、估價或地政等專門學識經驗之專家、學者。\n（三）熱心公益人士。\n委員任期一年，期滿得續聘（派）之；任期內出缺時，得補聘（派）\n之，其任期至原委員任期屆滿之日為止；代表機關出任者，應隨其本\n職進退。\n依第一項第二款聘任之委員，不得少於審議會委員總數二分之一。\n四、審議會會議由主任委員召集之，並為會議主席；主任委員不克出席會\n議時，由副主任委員代理之，副主任委員亦不克出席時，由出席委員\n互推一人代理之。\n五、審議會應於開會前三日將議事日程及有關資料送達各委員。但緊急性\n之臨時會議，不在此限。\n六、審議會非有過半數以上委員之出席不得開會，並有出席委員過半數之\n同意始得決議，可否同數時，由主席裁決。委員應親自出席前項會議\n。但由機關代表兼任之委員，如未能親自出席時，得指派代表出席，\n並通知審議會。\n七、審議會開會時，得邀請土地及建築物所有權人、權利關係人、管理機\n關、實施者或其委託之代表及陳情人列席說明。\n八、審議會開會時，委員有行政程序法第三十二條各款情形之一者，應自\n行迴避。\n九、審議會為審議案件或處理有關爭議之需要，得推派委員或調派業務有\n關人員組成專案小組赴實地調查，並研擬意見，提供會議參考。前項\n專案小組，並得邀請其他專家或委員提供諮商。\n十、審議會委員為無給職，但得依規定支給兼職費等相關費用。\n十一、審議會所需經費，由本府年度預算編列支應。\n十二、審議會決議事項，以本府名義行之。\n十三、本要點自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:FL051244","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"公發布日":"民國 98 年 11 月 24 日","法規名稱":"宜蘭縣都市更新及爭議處理審議會設置要點","法規體系":"建設","發文字號":"府建城字第0980167823號"},"promulgation_date":"2009-11-24","revision_date":"2009-11-24","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=FL051244","status":"unknown","title":"宜蘭縣都市更新及爭議處理審議會設置要點","last_checked_at":"2026-10-06T17:31:32+08:00","last_success_at":"2026-10-06T17:31:32+08:00","verification_status":"fetched","content_hash":"1b8b55469abc85164d3e99ad5087b570598680777d7e3868b6a5c413bf0382d3","history":[{"observed_at":"2026-10-06T17:31:32+08:00","content_hash":"1b8b55469abc85164d3e99ad5087b570598680777d7e3868b6a5c413bf0382d3","change_kind":"initial","revision_date":"2009-11-24"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、宜蘭縣政府為強化愛臺十二建設政府為主都市更新案之執行及招商機\n制，設各都市更新地區專案推動小組（以下簡稱專案推動小組），特\n訂定本要點。\n二、專案推動小組之任務：\n（一）議定推動策略、分工、步驟及期程。\n（二）協調推動都市更新工作。\n（三）協商招商投資有關文件。\n（四）協商投資廠商所提投資計畫，並提供諮詢服務。\n（五）控管推動情形與進度。\n（六）其他有關都市更新事項。\n三、專案推動小組協調都市更新計畫實施事宜，遇無法處理需中央協助事\n項，應提報內政部予以協調；涉及跨部會事項則由內政部提報行政院\n都市更新推動小組協助解決。\n四、專案推動小組設置委員十七至二十人，其中一人為召集人，由縣長兼\n任（或指派適當人員兼任）；副召集人一人由副縣長兼任（或指派適\n當人員兼任），其餘委員由行政院經濟建設委員會、內政部營建署、\n其他相關機關（構）或團體指派代表各一人兼任。\n五、專案推動小組設置執行祕書一人，由縣政府都市更新地區專案承辦機\n關（單位）首長（主管）兼任，承召集人之命，綜理本小組幕僚業務\n。另置工作人員若干人，由承辦機關（單位）派員兼任。\n六、專案推動小組會議以每二個月召開一次為原則，必要時得隨時召開會\n議。會議由召集人召集，並擔任主席；召集人因故不克出席時，由副\n召集人代理出席；副召集人亦不克出席時，由委員互推一人代理主席\n。其餘委員未能親自出席時，得指派代表出席。\n七、專案推動小組召開會議時，得邀請中央及地方各有關機關人員或專家\n、學者列席。\n八、專案推動小組委員、執行秘書及工作人員均為無給職。\n九、本要點奉  縣長核定後實施。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:FL049445","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"公發布日":"民國 98 年 04 月 22 日","法規名稱":"宜蘭縣都市更新地區專案推動小組設置要點","法規體系":"建設","發文字號":"府建城字第0980057707號"},"promulgation_date":"2009-04-22","revision_date":"2009-04-22","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=FL049445","status":"unknown","title":"宜蘭縣都市更新地區專案推動小組設置要點","last_checked_at":"2026-10-06T17:31:33+08:00","last_success_at":"2026-10-06T17:31:33+08:00","verification_status":"fetched","content_hash":"d06cc7b5e88b6133bb08cb004447ced443c31e0e1e624201baef880855bac097","history":[{"observed_at":"2026-10-06T17:31:33+08:00","content_hash":"d06cc7b5e88b6133bb08cb004447ced443c31e0e1e624201baef880855bac097","change_kind":"initial","revision_date":"2009-04-22"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"附表.DOC","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=135&id=FL023541&type=LAW"},{"name":"附表.DOC","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=136&id=FL023541&type=LAW"},{"name":"附表.DOC","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=137&id=FL023541&type=LAW"},{"name":"附圖：「毗連」土地使用分區檢討範圍說明圖.DOC","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=138&id=FL023541&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"第 1 條\n本規則依都市計畫公共設施保留地（以下簡稱公共設施保留地）臨時建築\n使用辦法第四條第二項訂定之。\n第 2 條\n公共設施保留地申請臨時建築使用，應依毗連土地使用分區及容許臨時建\n築使用細目使用。\n毗連之土地使用分區有二種以上者，應同時依據附表，並不得違反毗連各\n土地使用分區之容許臨時建築使用細目規定。毗連土地使用分區、容許使\n用細目及附帶條件規定如附表。\n圖表附件：\n附表.DOC\n第 3 條\n毗連之土地使用分區未於附表規定者，應由本府都市計畫\n主管單位，依該毗連土地使用分區之規定，參照附表類似之毗連土地使用\n分區，於不影響周邊環境之發展下，逕予認定其毗連之土地使用分區種類\n，並依前條規定辦理。\n圖表附件：\n附表.DOC\n第 4 條\n申請臨時建築使用細目為臨時攤販集中場者，應先徵得該公共設施保留地\n所在地鄉鎮市公所同意，並檢附該公共設施保留地周邊停車空間改善計畫\n，向本府提出申請。\n第 5 條\n申請臨時建築作自用住宅使用，如毗連保護區、一般保護區、景觀保護區\n、海岸發展區者，應自道路境界線起退縮五公尺建築。\n第 6 條\n申請臨時建築使用細目為簡易汽車駕駛訓練場者，其毗連土地使用分區種\n類為住宅區暨其他種住宅區、別墅區者，應先申請目的事業主管機關審查\n核准後，始得申請臨時建築使用。\n第 7 條\n毗連土地使用分區為河川區、行水區者，如堤防已依治理計畫設置完成，\n或依現況設置之堤防經檢討符合防洪標準，並經水利主管機關同意辦理解\n編劃出河川區、行水區者，得依附表容許臨時建築使用。\n圖表附件：\n附表.DOC\n第 8 條\n本規則所稱毗連土地使用分區，係指距離申請土地最近之非公共設施用地\n之土地使用分區，其距離以在申請基地中心距離二百公尺內者為限。超過\n二百公尺距離者，免再檢討。（檢討範圍說明圖如附圖）\n圖表附件：\n附圖：「毗連」土地使用分區檢討範圍說明圖.DOC\n第 9 條\n公共設施保留地之臨時建築使用，建蔽率不得超過百分之三十。\n第 10 條\n本規則自八十八年七月一日起施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:FL023541","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"修正日期":"民國 95 年 07 月 21 日","公發布日":"民國 89 年 10 月 31 日","法規名稱":"宜蘭縣都市計畫公共設施保留地臨時建築使用規則","法規體系":"建設","發文字號":"府秘法字第0950090240B號"},"promulgation_date":"2000-10-31","revision_date":"2006-07-21","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=FL023541","status":"unknown","title":"宜蘭縣都市計畫公共設施保留地臨時建築使用規則","last_checked_at":"2026-10-06T17:31:21+08:00","last_success_at":"2026-10-06T17:31:21+08:00","verification_status":"fetched","content_hash":"f386a86cb89ece2126659aac9bb079a380194bc95048f5832f50f4b3d78206d5","history":[{"observed_at":"2026-10-06T17:31:21+08:00","content_hash":"f386a86cb89ece2126659aac9bb079a380194bc95048f5832f50f4b3d78206d5","change_kind":"initial","revision_date":"2006-07-21"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=135&id=FL023541&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=136&id=FL023541&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=137&id=FL023541&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=138&id=FL023541&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"宜蘭縣都市計畫地區建築基地法定空地綠化實施辦法.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3072&id=FL029898&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"第 1 條\n宜蘭縣政府 (以下簡稱本府) 為執行都市計畫地區土地使用分區管制要點\n規定建築基地法定空地應實施綠化之工作，特訂定本辦法。除都市計畫或\n相關法令另有規定外，應依本辦法規定辦理。\n第 2 條\n建築基地內之空地有下列各款情形者，得扣除其面積後作為檢討綠化面積\n之基準：\n一、指定建築線之現有巷道退縮地面積。\n二、退縮騎樓地供公眾通行深度二˙五公尺範圍內面積。\n第 3 條\n用詞定義：\n一、綠化：指建築基地內之空地種植花草樹木之行為。\n二、綠化面積：指植物枝葉於建築基地內空地之水平投影面積。\n第 4 條\n綠化面積計算基準如下：\n一、喬木、棕櫚樹及特大樹依下表計算。 (如附表一)\n二、灌木以實際密植栽植平面面積加百分之二十計算。\n三、草皮、草花、地被以均布被覆面積計算。\n四、使用植草磚舖築者，依舖設植草磚面積三分之一計算。\n前項各款規定之水平投影面積若有重疊時，以最大水平投影範圍計算。\n第 5 條\n綠化配置規定如下：\n一、以栽植草花、草皮、地被等植生為綠化面積之比例不得大於百分之六\n十。\n二、退縮騎樓地之綠化植生應以臨接建築線垂直深度一百一十四公分範圍\n內為之，且每五公尺範圍內，應留設一處淨寬度一˙二公尺以上出入\n口，若不足五公尺應至少留設一處出入口，該出入口不得植生及舖築\n植草磚。\n第 6 條\n植生覆土置於人工地盤上方時，應同時設置排水、防水及栽植穴等設施，\n植物生長之最小覆土厚度規定如下：\n一、喬木：一百公分。\n二、灌木：六十公分。\n三、草皮、草花：三十公分。\n前項喬木之栽植穴口面積不得小於一平方公尺。\n第 7 條\n設計圖說應包括下列圖表：\n一、綠化配置圖。\n二、剖面圖 (設置有人工地盤者) 。\n三、綠化面積計算表 (應載明植物種類規格、數量、單位綠化面積及總綠\n化面積) 。\n第 8 條\n建築物於領得使用執照後，其綠化部分若有改變，而依本辦法規定計算之\n綠化面積違反都市計畫地區土地使用分區管制要點之規定者，本府得依都\n市計畫法第七十九條規定處罰之。\n第 9 條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:FL029898","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"公發布日":"民國 93 年 04 月 29 日","圖表附件":"宜蘭縣都市計畫地區建築基地法定空地綠化實施辦法.odt","法規名稱":"宜蘭縣都市計畫地區建築基地法定空地綠化實施辦法","法規體系":"建設","發文字號":"府秘法字第0930052617-B號 令"},"promulgation_date":"2004-04-29","revision_date":"2004-04-29","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=FL029898","status":"unknown","title":"宜蘭縣都市計畫地區建築基地法定空地綠化實施辦法","last_checked_at":"2026-10-06T17:31:22+08:00","last_success_at":"2026-10-06T17:31:22+08:00","verification_status":"fetched","content_hash":"6924fcb8f4532d188c003e288b439671f44845bc3960771fa8dabb97f6ccc205","history":[{"observed_at":"2026-10-06T17:31:22+08:00","content_hash":"6924fcb8f4532d188c003e288b439671f44845bc3960771fa8dabb97f6ccc205","change_kind":"initial","revision_date":"2004-04-29"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3072&id=FL029898&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"宜蘭縣政府","category":"建築管理相關","content":"第 1 條\n本辦法依宜蘭縣建築管理自治條例第十二條規定訂定。\n第 2 條\n本縣實施都市計畫地區，除該都市計畫另有規定或屬農業區、保護區外，\n面臨都市計畫道路寬度八公尺以上之建築基地，應設置法定騎樓或無遮簷\n人行道。\n第 3 條\n法定騎樓或無遮簷人行道留設寬度，自建築線至法定騎樓內緣線，應為三\n點六四公尺，留設寬度超過法定騎樓寬度部分，視為私設騎樓。私設騎樓\n之構造不受本辦法第四條及第五條之限制。\n第 4 條\n法定騎樓或無遮簷人行道地面，應依下列規定留設：\n一  地面應與人行道、已開闢道路、建築線交接面及未開闢道路路邊計畫\n高程齊平，並以道路邊界線向內至七十五公分處為 A  段，地面坡度\n為五分之一，七十五公分外至三百六十四公分處為 B  段，地面坡度\n為四十分之一。\n二  地面舖裝應平整，不得裝置任何台階及阻礙物，並應與鄰地法定騎樓\n或無遮簷人行道齊平。\n第 5 條\n法定騎樓構造應合於下列規定：\n一  法定騎樓牆柱應自建築線退縮十五公分以上。法定騎樓之淨寬應達二\n點五公尺以上，淨高應達三公尺以上。\n二  法定騎樓正面開口應達臨接道路長度二分之一以上；淨高自路肩起算\n，應達三點三三公尺以上。開口以外可供通行部分之淨高，自路肩起\n算，應達二點二五公尺以上。\n第 6 條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:FL041248","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"公發布日":"民國 95 年 11 月 14 日","法規名稱":"宜蘭縣都市計畫地區法定騎樓或無遮簷人行道設置辦法","法規體系":"建設","發文字號":"府秘法字第0950141744B號"},"promulgation_date":"2006-11-14","revision_date":"2006-11-14","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=FL041248","status":"unknown","title":"宜蘭縣都市計畫地區法定騎樓或無遮簷人行道設置辦法","last_checked_at":"2026-10-06T17:31:20+08:00","last_success_at":"2026-10-06T17:31:20+08:00","verification_status":"fetched","content_hash":"e89acb383afcb003d0b0544b44564589045f369c3c1f2f38022344358ed793ab","history":[{"observed_at":"2026-10-06T17:31:20+08:00","content_hash":"e89acb383afcb003d0b0544b44564589045f369c3c1f2f38022344358ed793ab","change_kind":"initial","revision_date":"2006-11-14"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"宜蘭縣都市計畫容積移轉許可審查條件.pdf","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3787&id=GL000571&type=LAW"},{"name":"附表一附圖二.pdf","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=2751&id=GL000571&type=LAW"},{"name":"第六條附圖.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=2546&id=GL000571&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、宜蘭縣政府為執行都市計畫容積移轉實施辦法（以下簡稱本辦法）第四條第一項之規定\n，特訂定本審查條件。\n二、容積移轉之許可審查，都市計畫書及其他法令另有規定者從其規定，都市計畫書及其他\n法令未有規定者依本審查條件辦理。\n已依都市計畫規定、古蹟土地容積移轉辦法或其他法令申請容積移轉之土地，不得同時\n適用本審查條件。\n三、本辦法第六條第一項第一款所稱有保存價值之建築，係指下列各款：\n(一)經主管機關登錄之歷史建築。\n(二)都市計畫劃定之保存區。\n四、送出基地依本辦法第六條第一項各款所訂內容為限，且不得有下列情形：\n(一)已申請或已核准依「都市計畫公共設施用地多目標使用辦法」辦理公共設施多目標\n使用之土地。\n(二)屬山坡地範圍且平均坡度超過百分之四十之土地。\n五、送出基地應依該筆地號所有權全部辦理容積移轉；接受基地應以一宗建築基地為限，並\n於申請建造執照時一併提出申請。\n送出基地、接受基地分別超過一筆時，按申請容積移轉當期各接受基地、送出基地各筆\n公告土地現值，以面積加權平均計算之。\n六、接受基地面積不得小於五百平方公尺，且應屬住宅區、商業區或都市計畫書明定準用都\n市計畫法臺灣省施行細則有關住宅區或商業區規定之分區，基地面前臨接已開闢供通行\n寬度達八公尺以上之計畫道路。並不得位於以下範圍：\n(一)實施容積管制前已取得建造執照之土地。\n(二)位於山坡地範圍之土地。\n(三)依都市計畫規定，禁止容積移轉之地區。\n(四)依其他相關法令規定，列為禁限建區之土地。\n前項已開闢道路係指政府機關開闢完竣，或由私人依道路主管機關之設計標準開闢完成\n，並取得道路管理機關管理維護之證明文件。\n接受基地周遭五十公尺範圍內有古蹟、歷史建築、紀念建築或聚落建築群者，其移入容\n積後建築絕對高度應依附圖一辦理，惟都市計畫書另有規定者應從其規定。\n接受基地毗鄰前項列舉之文化資產者，該文化資產座落土地境界線起五公尺範圍內不得\n建築，其建築量體應經都市設計審議委員會審議通過始得發照建築。\n圖表附件：\n第六條附圖.odt\n七、接受基地可移入容積比率上限依下列規定辦理(詳附表一)：\n(一)基地面前臨接已開闢供通行寬度達八公尺以上，未達十公尺之計畫道路，且臨接道\n路長度不得小於道路寬度：\n1.基地面積達五百平方公尺以上，可移入容積不得超過基準容積百分之十。\n(二)基地面前臨接已開闢供通行寬度達十公尺以上，未達十二公尺之計畫道路，且臨接\n道路長度不得小於道路寬度：\n1.基地面積達五百平方公尺以上，未達二千平方公尺者，可移入容積不得超過基準容\n積百分之十五。\n2.基地面積達二千平方公尺以上，可移入容積不得超過基準容積百分之二十。\n(三)基地面前臨接已開闢供通行寬度達十二公尺以上，未達三十公尺之計畫道路，且臨\n接道路長度不得小於道路寬度：\n1.基地面積達五百平方公尺以上，未達二千平方公尺者，可移入容積不得超過基準容\n積百分之二十。\n2.基地面積達二千平方公尺以上，未達五千平方公尺者，可移入容積不得超過基準容\n積百分之二十五。\n3.基地面積達五千平方公尺以上者，可移入容積不得超過基準容積百分之三十。\n(四)基地面前臨接已開闢供通行寬度達三十公尺以上之計畫道路，且臨接道路長度不得\n小於道路寬度，可移入容積不得超過基準容積百分之三十。\n(五)接受基地倘屬雙面臨路之角地，其臨接已開闢計畫道路長度以截角前長度認定（詳\n附圖二）\n八、接受基地位於已完成整體開發地區，或已實施都市更新地區，或都市計畫指定移入地\n區，可移入容積上限依下列規定辦理(詳附表一)：\n(一)基地面前臨接已開闢供通行寬度達八公尺以上，未達十公尺之計畫道路且臨接道\n路長度不得小於道路寬度：\n1.基地面積達五百平方公尺以上，可移入容積不得超過基準容積百分之二十。\n(二)基地面前臨接已開闢供通行寬度達十公尺以上，未達十二公尺之計畫道路且臨接\n道路長度不得小於道路寬度：\n1.基地面積達五百平方公尺以上，未達二千平方公尺者，可移入容積不得超過基準\n容積百分之二十五。\n2.基地面積達二千平方公尺以上，可移入容積不得超過基準容積百分之三十。\n(三)基地面前臨接已開闢供通行寬度達十二公尺以上，未達三十公尺之計畫道路且臨\n接道路長度不得小於道路寬度：\n1.基地面積達五百平方公尺以上，未達二千平方公尺者，可移入容積不得超過基準\n容積百分之三十。\n2.基地面積達二千平方公尺以上，未達五千平方公尺者，可移入容積不得超過基準\n容積百分之三十五。\n3.基地面積達五千平方公尺以上者，可移入容積不得超過基準容積百分之四十。\n(四)基地面前臨接已開闢供通行寬度達三十公尺以上之計畫道路且臨接道路長度不得\n小於道路寬度，可移入容積不得超過基準容積百分之四十。\n(五)接受基地倘屬雙面臨路之角地，其臨接已開闢計畫道路長度以截角前長度認定(詳\n附圖二)\n九、接受基地依本辦法、都市更新條例、都市計畫法或其他法規規定給予之增加容積總量合\n計若達基準容積百分之三十以上申請者，應提送本縣都市計畫委員會審查通過始得辦理\n移轉。\n前項審查原則依都市計畫定期通盤檢討實施辦法第九條第二項規定都市設計內容應表明\n之事項辦理。\n接受基地非屬審查條件第六點第一項所定分區者，得經本縣都市計畫委員會考量都市發\n展密度、發展總量、公共設施劃設水準及發展優先次序等，審查通過後，申請容積移轉\n。\n十、接受基地移入之容積量，應有百分之五十以上依本辦法第九條之一規定，以折繳代金方\n式辦理。\n折繳代金規定施行日期，由宜蘭縣政府另行公告。\n十一、本審查條件核定後實施，修正時亦同。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:GL000571","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"修正日期":"民國 111 年 08 月 24 日","全文檔案":"宜蘭縣都市計畫容積移轉許可審查條件.pdf","公發布日":"民國 100 年 01 月 03 日","圖表附件":"附表一附圖二.pdf","法規名稱":"宜蘭縣都市計畫容積移轉許可審查條件","法規體系":"建設","發文字號":"府建都字第1110132296B號令"},"promulgation_date":"2011-01-03","revision_date":"2022-08-24","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=GL000571","status":"unknown","title":"宜蘭縣都市計畫容積移轉許可審查條件","last_checked_at":"2026-10-06T17:31:37+08:00","last_success_at":"2026-10-06T17:31:37+08:00","verification_status":"fetched","content_hash":"d70226970b3dae380e8fd51281d72633cd711797c3f50d721134ca192dc65511","history":[{"observed_at":"2026-10-06T17:31:37+08:00","content_hash":"d70226970b3dae380e8fd51281d72633cd711797c3f50d721134ca192dc65511","change_kind":"initial","revision_date":"2022-08-24"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3787&id=GL000571&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=2751&id=GL000571&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=2546&id=GL000571&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"108.5.20_附圖一及附表一至附表八.ODT.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3423&id=GL000416&type=LAW"},{"name":"108.5.20_附圖一及附表一至附表八-全.pdf","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3424&id=GL000416&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、宜蘭縣政府（以下簡稱本府）為辦理都市計畫容積移轉許可審查，特訂定本要點。\n二、本要點之主管單位為本府建設處。\n三、容積移轉申請案件之申請人，以接受基地之所有權人或都市更新事業實施者為限。\n四、申請人提出容積移轉許可之申請，送出基地屬都市計畫容積移轉實施辦法（以下簡稱本辦法）第\n六條第一項第一款規定之土地者，應檢附主管機關審查通過，並經本府核定之文件；屬本辦法第\n六條第一項第二、三款規定之土地者，應檢附中央主管機關、本府或本縣鄉鎮市公所或需地機關\n同意受贈之公文。有本辦法第六條第三項但書規定之情形者，應檢送本府認定公文及本府或鄉鎮\n市公所同意受贈公文。\n五、申請人於領得容積移入量初步認定函後，應於一年內提出建造執照之申請。送出基地如屬本辦法\n第六條第一項第二、三款者，申請人應於本府通知領取建造執照日起六個月內辦竣送出基地權利\n清理，並將所有權贈與登記為國有、縣有或鄉、鎮、市有；未於上述期限內完成土地登記移轉者\n，該建造執照申請案予以駁回。\n六、容積移轉許可審查流程如附圖一，申請人應檢附之文件如下:\n(一)宜蘭縣都市計畫容積移轉許可審查申請書(附表一)。\n(二)宜蘭縣都市計畫容積移轉許可審查審查表(附表二)。\n(三)宜蘭縣、都市計畫容積移轉許可審查計算表(附表三)。\n(四)送出基地土地及建物所有權人及關條人清冊及同意書(附表四)。\n(五)接受基地土地及建物所有權人清冊及同意書(附表五)。\n(六)送出基地與接受基地所有權人委託書(附表六)。\n(七)送出基地與接受基地所有權人身份證明文件影本。\n(九)送出基地及接受基地之地籍圖謄本、土地登記謄本、建物登記謄本、建築線指示(定)成果圖、土\n地使用分區證明、位置圖、送出基地現況照片。\n(十)送出基地屬山坡地範圍者，經專業技師簽證之測量圖、坡度分析圖、坡度分析面積分配表等。\n(十一)本要點第四點規定之文件或公文。\n圖表附件：\n108.5.20_附圖一及附表一至附表八.ODT.odt\n108.5.20_附圖一及附表一至附表八-全.pdf\n七、本要點核定後實施，修正時亦同。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:GL000416","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"修正日期":"民國 108 年 07 月 02 日","公發布日":"民國 100 年 07 月 01 日","法規名稱":"宜蘭縣都市計畫容積移轉許可審查要點","法規體系":"建設","發文字號":"府建管字第1080108772號函"},"promulgation_date":"2011-07-01","revision_date":"2019-07-02","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=GL000416","status":"unknown","title":"宜蘭縣都市計畫容積移轉許可審查要點","last_checked_at":"2026-10-06T17:31:38+08:00","last_success_at":"2026-10-06T17:31:38+08:00","verification_status":"fetched","content_hash":"94f1abd3efd9307f842b7720fb8da16a837f864b548d6e7254704d18ea2207ea","history":[{"observed_at":"2026-10-06T17:31:38+08:00","content_hash":"94f1abd3efd9307f842b7720fb8da16a837f864b548d6e7254704d18ea2207ea","change_kind":"initial","revision_date":"2019-07-02"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3423&id=GL000416&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3424&id=GL000416&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"(1130205)宜蘭縣都市計畫甲、乙種工業區設置工業發展有關設施、公共服務設施、公用事業設施審查要點.pdf","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4642&id=FL042321&type=LAW"},{"name":"附表一.pdf","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4333&id=FL042321&type=LAW"},{"name":"附表二--各使用項目目的事業主管機關（單位）.pdf","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4334&id=FL042321&type=LAW"},{"name":"附圖.pdf","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4335&id=FL042321&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一．宜蘭縣政府（以下簡稱本府）為執行都市計畫法臺灣省施行細則（\n以下簡稱本細則）第十八條及第十九條規定，辦理宜蘭縣（以下簡\n稱本縣）都市計畫甲種、乙種工業區申請設置工業發展有關設施、\n公共服務設施、公用事業設施之土地使用審查事宜，特訂定本要點。\n二、甲種或乙種工業區總面積之計算，應以同一都市計畫區範圍內所有\n甲種或乙種工業區，視其集中分布情形分別計算之。\n三、申請設置工業發展有關設施、公共服務設施、公用事業設施者，應\n依附表一所列使用條件規定辦理，填具申請書，並檢附下列文件、\n資料向附表二所列之目的事業主管機關（單位）申請，並同時申請\n建造執照：\n(\n一)最近三個月內核發之地籍圖謄本及土地登記簿謄本；如有建物\n者，應檢附建物登記謄本。\n(\n二)最近三個月內之土地使用分區證明。\n(\n三)最近三個月內之基地周圍現況圖：標示基地境界線鄰近三百公\n尺以內之地形、地物及附表一所列使用條件規定之檢討，其比\n例尺不得小於一千分之一。\n(\n四)基地位置圖：依都市計畫圖標示。\n(\n五)臨接道路已開闢寬度之證明文件。\n(\n六)面積計算及配置圖說：依該都市計畫土地使用分區管制要點及\n附表一所列使用條件規定標示基地及設施面積。\n(\n七)各目的事業主管機關指定之文件。\n(\n八)土地使用同意書；申請人為土地所有權人者，免附。\n(\n九)建物使用同意書；申請人為建物所有權人者，免附。\n前項文件涉及測量、計算、配置圖或平面圖者，應由建築師或專業\n技師簽證負責。\n圖表附件：\n附表一.pdf\n附表二--各使用項目目的事業主管機關（單位）.pdf\n四、申請基地臨接之道路，其寬度依附表一規定辦理，並以「已開闢完\n成都市計畫道路或現有巷道」為限。\n基地未直接臨接已開闢完成都市計畫道路或現有巷道者，申請人得\n依下列規定之一辦理，並自行開闢完成可通行之通路後，始得據以\n申請使用：\n(一)臨接未足寬開闢之計畫道路：取得該未開闢道路用地之土地使\n用權利證明文件。\n(二)受現有溝渠區隔：取得該目的事業主管機關同意使用或架設橋\n涵之權利證明文件。\n前項所稱已開闢完成都市計畫道路，指政府機關開闢完竣，或由私\n人依該道路主管機關之規定開闢完成，並取得該道路管理機關同意\n管理維護之證明文件。\n前項證明文件倘因道路開關年代久遠無法考證，經道路管理機關認\n定確屬年代久遠無法考證、現況已開闢完成，並由其管理維護者，\n不在此限。\n已開闢道路之寬度涉及溝渠、橋涵或路邊駁崁等，應依附圖辦理。\n第二項自行開闢完成可通行之通路，其寬度不得小於該項設施應臨\n接之道路寬度，並應符合相關建築管理法令規定。\n圖表附件：\n附圖.pdf\n五、申請基地範圍原始地形平均坡度超過百分之三十部分不得建築，且\n不得計入法定空地。\n前項平均坡度應依建築技術規則建築設計編第十三章之平均坡度定\n義計算。\n六、申請使用項目，依附表一使用條件規定應檢附開發計畫書者，應經\n本縣都市設計審議委員會審議通過。\n前項開發計畫書，應包括下列事項:\n(一)開發計畫圖:比例不小於五百分之一。\n(二)基地環境分析。\n(三)土地使用計畫。\n(四)交通運輸計畫。\n(五)空間配置計畫。\n(六)建築造型計畫:高度、樣式、結構、色彩、材質等。\n(七)防災避難計畫。\n(八)水土保持計畫。\n(九)污染防治計畫:空氣污染防治、水污染防治、廢棄物清理等環\n境保護對策等。\n(十)景觀美化(植栽綠化、夜間照明等)計畫。\n(十一)事業經營及財務管理計畫。\n七、建築物於本次修正要點公告發布實施日前（含發布實施日）領有使\n用執照符合建築物使用類組及變更使用辦法第六條及宜蘭縣建築物\n免辦理變更使用執照辦法者，得免適用附表一之「使用條件」、第\n四點及第六點規定。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:FL042321","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"修正日期":"民國 113 年 02 月 05 日","全文檔案":"(1130205)宜蘭縣都市計畫甲、乙種工業區設置工業發展有關設施、公共服務設施、公用事業設施審查要點.pdf","公發布日":"民國 91 年 12 月 27 日","法規名稱":"宜蘭縣都市計畫甲、乙種工業區設置工業發展有關設施、公共服務設施、公用事業設施審查要點","法規體系":"建設","發文字號":"府建都字第1120228278B號令"},"promulgation_date":"2002-12-27","revision_date":"2024-02-05","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=FL042321","status":"unknown","title":"宜蘭縣都市計畫甲、乙種工業區設置工業發展有關設施、公共服務設施、公用事業設施審查要點","last_checked_at":"2026-10-06T17:31:36+08:00","last_success_at":"2026-10-06T17:31:36+08:00","verification_status":"fetched","content_hash":"21075fadb7a6fcab5ca7f2b339c61caadacdf304b973f597c019aca758a8abe7","history":[{"observed_at":"2026-10-06T17:31:36+08:00","content_hash":"21075fadb7a6fcab5ca7f2b339c61caadacdf304b973f597c019aca758a8abe7","change_kind":"initial","revision_date":"2024-02-05"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4642&id=FL042321&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4333&id=FL042321&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4334&id=FL042321&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=4335&id=FL042321&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"01宜蘭縣都市計畫開發回饋比例及代金審議作業要點(全文).odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3029&id=GL000647&type=LAW"},{"name":"宜蘭縣都市計畫開發回饋比例及代金審議作業要點逐點說明(0320).odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3030&id=GL000647&type=LAW"},{"name":"附表一各土地使用分區及公共設施用地變更回饋比例表.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3031&id=GL000647&type=LAW"},{"name":"附表二-申請書.pdf","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3032&id=GL000647&type=LAW"},{"name":"附表一各土地使用分區及公共設施用地變更回饋比例表.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3033&id=GL000647&type=LAW"},{"name":"附表二-申請書.pdf","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3034&id=GL000647&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、為使宜蘭縣(以下簡稱本縣)各都市計畫回饋比例原則一致性及市價查估公平合\n理性，依各級都市計畫委員會組織規程第十三條規定，訂定本要點。\n二、本縣都市計畫區內土地變更之回饋條件，其他法令已有規定者，從其規定。\n三、本縣各土地使用分區及公共設施用地變更回饋比例詳附表一。\n前項回饋比例以回饋公共設施用地方式為原則，其回饋位置及各變更回饋比例\n應經各級都市計畫委員會審議通過。\n第一項回饋比例各級都市計畫委員會得參酌各都市計畫區之都市機能、人口\n成長、公共設施劃設、開闢情形、都市計畫發布實施時間點，以及個案合法\n建築等情事，依第一項附表一之標準酌予調整。\n第一項未規定之土地使用分區或用地之變更回饋比例，依各該都市計畫或各\n目的事業中央主管機關訂定之該設置管理辦法、審核要點或審議規範等相關\n規定辦理；無相關規定可依循者，由本縣都市計畫委員會視實際情況審決。\n圖表附件：\n附表一各土地使用分區及公共設施用地變更回饋比例表.odt\n四、申請人申請折繳代金，應檢具下列文件：\n（一）申請書（詳附表二）。\n（二）近三個月內申請之土地登記簿謄本及地籍圖謄本。\n（三）近三個月內申請之土地使用分區證明。\n（四）三家估價報告書。\n（五）其他應檢具文件。\n圖表附件：\n附表二-申請書.pdf\n五、估價方式應以申請折繳代金之整筆地號土地為單元。\n前項估價應以變更後分區之市價為準。\n六、申請人所附估價報告書價格日期介於前年九月二日至當年三月一日之間者，應\n於當年十二月三十一日前完成繳納代金；估價報告書價格日期介於當年三月二\n日至當年九月一日之間者，應於翌年六月三十日前完成繳納代金。\n三家估價報告書價格日期應一致。\n申請人未於第一項規定期間內完成繳納代金者，其所附估價報告書失其效\n力。\n七、本縣都市計畫委員會設回饋代金審查專案小組（以下簡稱本小組），評定都市\n計畫土地變更回饋代金之市價金額及其合理性。\n八、本小組置委員七人至九人，其中一人為召集人，一人為副召集人，由縣長就宜\n蘭縣政府(以下簡稱本府)建設處處長、地政處處長、財政稅務局局長三人中指\n派二人兼任，其餘委員就下列人員聘（派）兼之：\n(一)不動產估價師三至五人。\n(二)地政專家學者一人。\n(三)未兼任召集人、副召集人之建設處處長、地政處處長或財政稅務局局長。\n本小組委員任期二年，期滿得續聘（派）之。委員於任期內因故出缺時，得補\n聘(派)之，其任期至原任期屆滿為止。但本府派兼之委員，應隨其本職進退。\n九、本小組會議由召集人召集，並為會議主席；召集人因故不能出席時，由副召集\n人代理之；副召集人因故不能出席時，由出席委員互推一人擔任主席。\n委員應親自出席會議。但本府派兼之委員未能親自出席時，得指派代表代理出\n席，並列入出席人數，參與會議發言及表決。\n本小組會議應有過半數以上委員出席，始得開會。\n十、本小組開會時，得通知估價報告書之簽證不動產估價師及有關機關派員列席，\n並得邀請申請人於會議中陳述意見。不動產估價師及申請人應於說明後離席。\n本小組開會時，依宜蘭縣政府辦理國土計畫及都市計畫審議會議會場管理要點\n之規定，維護會場秩序。\n十一、本小組作成估價報告書應予修正之決議者，申請人應於會議結束後一個月內\n完成修正；修正後估價報告書送達本府之日，逾第六點第一項繳納期限者\n，應予退回，重新辦理查估。\n十二、本小組委員對具有利害關係之議案，應自行迴避，並對會議內容有保守秘密\n之義務。\n十三、本小組委員及工作人員均為無給職。但外聘委員及列席之專家、學者得依中\n央政府各機關學校出席費及稿費支給要點之規定，支領出席費、審查費及交\n通費。\n十四、申請案件受理及審議之流程詳附圖。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:GL000647","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"公發布日":"民國 109 年 04 月 14 日","圖表附件":"附表一各土地使用分區及公共設施用地變更回饋比例表.odt 附表二-申請書.pdf","法規名稱":"宜蘭縣都市計畫開發回饋及代金審議組織作業要點","法規體系":"建設","發文字號":"府建都字第1090059530號令","立法理由":"01宜蘭縣都市計畫開發回饋比例及代金審議作業要點(全文).odt 宜蘭縣都市計畫開發回饋比例及代金審議作業要點逐點說明(0320).odt"},"promulgation_date":"2020-04-14","revision_date":"2020-04-14","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=GL000647","status":"unknown","title":"宜蘭縣都市計畫開發回饋及代金審議組織作業要點","last_checked_at":"2026-10-06T17:31:37+08:00","last_success_at":"2026-10-06T17:31:37+08:00","verification_status":"fetched","content_hash":"a96ed906a40e07a51c7cccaff244ef1088aad12c9882ba5f96f355ec3724ead5","history":[{"observed_at":"2026-10-06T17:31:37+08:00","content_hash":"a96ed906a40e07a51c7cccaff244ef1088aad12c9882ba5f96f355ec3724ead5","change_kind":"initial","revision_date":"2020-04-14"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3029&id=GL000647&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3030&id=GL000647&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3031&id=GL000647&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3032&id=GL000647&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3033&id=GL000647&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3034&id=GL000647&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"(1150513)宜蘭縣都市設計審議作業要點.pdf","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=5652&id=GL000665&type=LAW"},{"name":"附表一.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3358&id=GL000665&type=LAW"},{"name":"附表二.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3359&id=GL000665&type=LAW"},{"name":"附圖一.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3360&id=GL000665&type=LAW"},{"name":"附圖二.odt","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3361&id=GL000665&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、宜蘭縣政府(以下簡稱本府)為辦理宜蘭縣\n（\n以下簡稱本縣\n）\n都市設計審議作\n業，增進審議效能，特訂定本要點。\n二、都市設計審議作業，除都市計畫書或法令另有規定外，依本要點規定辦理。\n三、都市設計審議範圍如下：\n(一)都市計畫書規定應經都市設計審議者。\n(二)都市計畫指定應辦理整體開發地區之土地使用開發者。\n(三)實施都市計畫地區建築基地綜合設計者。\n(四)依都市計畫書規定基地情形特殊，申請放寬退縮建築者。\n(五)其他依法令規定須經都市設計審議者。\n四、都市設計審議申請案件應檢具之書圖文件及電子檔如附表一；申請放寬退縮\n建築案件者，應檢具書圖文件及電子檔如附表二。\n圖表附件：\n附表一.odt\n附表二.odt\n五、本府應自收受申請案件之次日起十四日內完成書面查核，申請文件不符合前\n點規定者，應以書面通知申請人補正。\n六、申請案件符合下列各款之一者，由本府建設處審查，但案件內容複雜、具時\n效性或對環境可能有重大影響之情形者，經本縣都市設計審議委員會\n（\n以下\n簡稱本委員會\n）\n主任委員同意後，得逕提送本委員會審議：\n(一)都市計畫土地使用管制要點規定授權範圍。\n(二)本縣都市計畫規定應全區提送都市設計審議地區，其建築基地面積未達\n五百平方公尺，且建築物高度未達十五公尺。\n(三)本委員會授權審查案件。\n前項本府建設處審查案件之審查紀錄，應送本委員會備查。\n第一項申請案件經本府建設處審查須修正者，本府應將審查意見函送申請人\n修正之，並自收受申請人依審查意見修正書圖之日起三十日內核定之。\n第一項各款所定案件以外之申請案件，由本委員會審議。\n七、前點第一項但書、第四項申請案件，本府應自收受申請人依查核意見補正書\n圖之日起三十日內提送本委員會審議。\n審議作業依下列規定辦理：\n(一)審議會議開會時，設計人應親自到場說明；委任代理人出席者，應出具\n委任書。\n(二)審議會議開會時，得邀請民意代表列席。\n(三)經審議通過之都市設計案件部分內容有變更者，除符合宜蘭縣都市設計\n案部分變更內容免再提送都市設計審議通案原則外，應再提送本委員會\n審議。\n八、申請案件經查核、審查或審議後須補正者，申請人應於本府通知補正之公文\n書送達日起六個月內補正相關資料，必要時得以書面敘明理由，申請展延三\n個月，並以一次為限；屆期未補正或補正未完全者，本府得駁回申請案件。\n前項須補正事項係本委員會決議要求辦理者，補正期間最長為一年。\n申請案件應實施環境影響評估及交通影響評估等審查者，由本委員會視辦理\n情形酌予展延補正期限。\n九、申請案件經本委員會審議通過後，本府應將會議紀錄函送\n申請人；申請人應自會議紀錄送達之日起六個月內，檢具\n修正完竣之報告書圖五份及電子檔向本府申請核定；屆期\n未申請者，應重新申請審議。\n十、申請人應自本府通知之日起十五日內，檢具定稿本報告書十二份及電子檔陳\n報本府核定；屆期未陳報者，應重新申請審議。\n十一、申請人應自本府核定函送達之日起六個月內，申請建造執照；屆期未申請\n者，應重新申請審議。申請人因故無法辦理者，得於期限屆滿前敘明理由\n，申請展延六個月，並以一次為限。\n十二、本委員會審議作業流程如附圖一；屬本府建設處審查案件，作業流程如附\n圖二。\n圖表附件：\n附圖一.odt\n附圖二.odt","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:GL000665","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"修正日期":"民國 115 年 05 月 13 日","全文檔案":"(1150513)宜蘭縣都市設計審議作業要點.pdf","公發布日":"民國 110 年 03 月 15 日","法規名稱":"宜蘭縣都市設計審議作業要點","法規體系":"建設","發文字號":"府建國字第1150076119B號令"},"promulgation_date":"2021-03-15","revision_date":"2026-05-13","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=GL000665","status":"unknown","title":"宜蘭縣都市設計審議作業要點","last_checked_at":"2026-10-06T17:31:35+08:00","last_success_at":"2026-10-06T17:31:35+08:00","verification_status":"fetched","content_hash":"dedcc495e11ff206184e40c9f46dd43eab036df311cb85c72e20b66123053c03","history":[{"observed_at":"2026-10-06T17:31:35+08:00","content_hash":"dedcc495e11ff206184e40c9f46dd43eab036df311cb85c72e20b66123053c03","change_kind":"initial","revision_date":"2026-05-13"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=5652&id=GL000665&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3358&id=GL000665&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3359&id=GL000665&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3360&id=GL000665&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=3361&id=GL000665&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"(1141231)宜蘭縣都市設計審議委員會設置要點第四點修正總說明及修正對照表.pdf","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=5378&id=GL000148&type=LAW"},{"name":"(1141231)宜蘭縣都市設計審議委員會設置要點.pdf","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=5379&id=GL000148&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、宜蘭縣政府（以下簡稱本府）為辦理都市設計暨開放空間審議事\n項，依都市計畫定期通盤檢討實施辦法及建造執照預審辦法第三\n條規定，設宜蘭縣都市設計審議委員會（以下簡稱本會）並訂定\n本要點。\n二、本會任務如下：\n（一）都市計畫指定須辦理都市設計地區之都市設計審議。\n（二）都市計畫指定須辦理整體開發地區之土地使用開發許可審\n議。\n（三）實施都市計畫地區建築基地綜合設計之審議。\n（四）其他法令規定須辦理都市設計或土地使用開發許可案件之\n審議。\n三、第二點規定之審議事項，都市計畫說明書或相關法令已規定者應\n從其規定，未規定者依案件實際需求選擇下列重點項目進行審查：\n（一）建築量體配置、高度、天際線、造型、色彩、樓層高度。\n（二）建築容積之總量與限制。\n（三）交通動線、停車空間。\n（四）開放空間及公共服務空間之配置。\n（五）景觀計畫（包含綠化、照明、廣告物及標示系統）。\n（六）消防救災空間配置。\n（七）其他必要事項。\n四、本會置委員七至十一人，主任委員由本府建設處處長兼任，副主\n任委員一人，由本府建設處副處長兼任，其餘委員由本府就下列\n人員聘兼：\n（一）都市設計專家學者。\n（二）建築設計專家學者。\n（三）景觀設計專家學者。\n（四）交通設計專家學者。\n（五）本縣都市計畫委員會委員。\n本會委員任一性別比例不得少於委員總數三分之一。\n五、本會委員任期一年，期滿得續聘（派）兼之。主任委員及副主任\n委員出任應隨其職務進退。\n委員出缺時應予補聘，其任期至原委員任期屆滿之日止。\n六、本會會議視業務需要不定期召開，由主任委員擔任主席。主任委\n員因故不能出席時，由副主任委員擔任主席。兩者皆不克出席時\n，由出席委員互推一人為主席。\n七、本會委員關於案件審議、決議之迴避，準用行政程序法第三十二\n條及第三十三條之規定。\n八、本會委員出席人數過半數者，始得開會；決議應經出席委員過半\n數同意，可否同數時，由主席裁決。\n本會決議事項經主任委員核定後，以本府名義行之。\n九、本會委員均為無給職。但外聘委員得依規定支給出席費及交通費。\n十、本會所需經費由本府建設處編列預算支應。\n十一、本要點核定後實施，修正時亦同。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:GL000148","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"修正日期":"民國 114 年 12 月 31 日","全文檔案":"(1141231)宜蘭縣都市設計審議委員會設置要點.pdf","公發布日":"民國 100 年 09 月 29 日","法規名稱":"宜蘭縣都市設計審議委員會設置要點","法規體系":"建設","發文字號":"府建國字第1140213894號函","立法理由":"(1141231)宜蘭縣都市設計審議委員會設置要點第四點修正總說明及修正對照表.pdf"},"promulgation_date":"2011-09-29","revision_date":"2025-12-31","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=GL000148","status":"unknown","title":"宜蘭縣都市設計審議委員會設置要點","last_checked_at":"2026-10-06T17:31:23+08:00","last_success_at":"2026-10-06T17:31:23+08:00","verification_status":"fetched","content_hash":"15543a3cb07f64912a1281c63e7b64a8e6e3c1ad0dc123ff9c60761fbf46689e","history":[{"observed_at":"2026-10-06T17:31:23+08:00","content_hash":"15543a3cb07f64912a1281c63e7b64a8e6e3c1ad0dc123ff9c60761fbf46689e","change_kind":"initial","revision_date":"2025-12-31"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=5378&id=GL000148&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=5379&id=GL000148&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"宜蘭縣政府","category":"建築管理相關","content":"第 1 條\n本準則依據建築技術規則總則編第三條之二第一項第五款規定訂定之。\n第 2 條\n本準則適用範圍為下列用途建築物：\n一、商業類：B-1娛樂場所、B-2商場百貨、B-3餐飲場所、B-4旅館。\n二、休閒、文教類：D-1健身休閒、D-5補教托育。\n三、衛生、福利、更生類：F-1醫療照顧、F-2社會福利、F-3兒童福利、F-4戒護場所。\n四、辦公、服務類：G-1金融證券、G-2辦公場所、G-3店舖診所。\n五、住宿類：H-1宿舍安養。\n六、停車空間。\n七、其他經認定之建築物。\n第 3 條\n建築物除為單一使用單元（同一戶）且總樓地板面積達一千平方公尺以上者外，適用本準則之樓層高度規定如下：\n一、B-1娛樂場所、B-2商場百貨或B-3餐飲場所地面一層不得超過六公尺，地面二層以上各樓層不得超過四點五公尺。\n其餘各類用途建築物，除非屬專有使用單元之公共空間外，地面一層不得超過四點五公尺，地面二層以上各樓層不得超過四點二公尺。\n二、除B-4旅館用途外，本準則各類用途建築物，各戶或各單元使用樓地板面積在一百五十平方公尺以下者（不含共同使用部分），依建築技術規則建築設計施工編第一百六十四條之一規定辦理。\n三、地面以上附設停車空間者，平面式停車空間樓層高度不得超過三點六公尺，雙層以上機械式停車空間以每層二點一公尺計算（梁下淨高），核計樓層高度。\n第 4 條\n建築物因構造或用途特殊，或既有建築物辦理變更使用時，經本府都市設計審議委員會或建造執照預審小組審核通過者，得不受第三條限制。\n第 5 條\n本準則自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:GL000247","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"公發布日":"民國 103 年 01 月 21 日","法規名稱":"宜蘭縣非住宅建築物樓層高度設計審查準則","法規體系":"建設","發文字號":"府秘法字第1030012434B號 令"},"promulgation_date":"2014-01-21","revision_date":"2014-01-21","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=GL000247","status":"unknown","title":"宜蘭縣非住宅建築物樓層高度設計審查準則","last_checked_at":"2026-10-06T17:31:19+08:00","last_success_at":"2026-10-06T17:31:19+08:00","verification_status":"fetched","content_hash":"5564958efd95ceb4bff017efd17669e05c158a8c5f715065691232971d820543","history":[{"observed_at":"2026-10-06T17:31:19+08:00","content_hash":"5564958efd95ceb4bff017efd17669e05c158a8c5f715065691232971d820543","change_kind":"initial","revision_date":"2014-01-21"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、宜蘭縣政府為防範建築開發業者將非都市土地丁種建築用地以平面類似住宅之設計，出售民眾為住宅使用，造成購屋糾紛及違規使用，並影響合法建築開發業者之權益，特訂定本原則。\n二、依本原則申請之工廠建造執照除應符合建築技術規則工廠類建築物專章規定，並應依下列規定辦理：\n（一）基地內有二使用單元（戶）以上之開發，每一使用單元總樓地面積不得小於\n一、○○○平方公尺。但情況特殊，經本縣建造執照預審小組審議通過者，不受限制。基地已分割多筆並申請整體開發，其每一使用單元（戶）並應符合前開最小總樓地板面積規定。\n（二）室內除必要之廠房附屬空間及浴廁空間外，不得設置隔間。\n（三）於建造執照注意事項附表加註：起造人應依原核定用途使用，並將建築物用途詳細告知各承買戶，除於公寓大廈管理規約草約中明確記載外，產權移轉時應列入交代且須轉載於公寓大廈管理規約中。施工中應加強樣品屋及預售中心之管理，樣品屋、實品屋及圖說應符合發照圖說及用途，並於現場張貼公告說明。現場如作核准用途以外之使用，均視為違規使用，將依相關規定處理。\n（四）起造人須切結：確實作工廠使用，如誤導民眾為住宅或其他用途，或有不實廣告惡意欺瞞等行為，經行政院公平交易委員會認定而受處罰，或受敗訴判決確定時，廢止建造執照。\n三、依第二點申請之工廠類建築，應依下列規定繳納保證金：\n（一）繳納之保證金按戶收取，並於該建案領得使用執照前繳納，繳納後由本府存入代收代付專戶保管。\n（二）保證金之計算依建築基地當期公告現值乘零點四五乘每戶樓地板面積（單位：平方公尺）。\n（三）使用執照核發或變更使用竣工查驗三年內均未作為住宅或其他違反土地容許使用用途者，保證金無息退還。\n四、相關後續執行方式：\n（一）使用執照核發時於附表內註記：起造人應依原核定用途使用，並將建築物用途詳細告知各承買戶，且應於公寓大廈管理規約草約中載明，應依原核定用途使用，不得供作其他用途之使用，並應列入產權移轉交代，轉載於公寓大廈管理規約中。且起造人須另行切結：如作為住宅或其他違反土地容許使用用途，繳納之保證金同意主管機關沒入。\n（二）於使用執照核發時於附表內註記：本案承買戶應依原核定用途使用，不得作為住宅或其他違反土地容許使用用途，買賣時應列入產權移轉交代，不得隱瞞。如未交代致發生糾紛賣方應自負法律責任，並轉載於公寓大廈管理規約中。\n（三）使用執照核發或變更使用竣工勘驗後三年內，持續加強巡查及不定期檢查，如發現未依原核定用途使用，將依法查處並沒入保證金。\n（四）已領得使用執照之建築物辦理變更使用執照或分戶時後續執行方式\n如下：\n1\n、依第二、三點規定辦理。\n2\n、變更使用執照之保證金於該案竣工勘驗前繳納；戶數變更申請案於核准函發文前繳納。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:GL000319","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"公發布日":"民國 103 年 05 月 21 日","法規名稱":"宜蘭縣非都市土地丁種建築用地平面設計類似住宅處理原則","法規體系":"建設","發文字號":"中華民國103年5月21日府建管字第1030080587號 函"},"promulgation_date":"2014-05-21","revision_date":"2014-05-21","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=GL000319","status":"unknown","title":"宜蘭縣非都市土地丁種建築用地平面設計類似住宅處理原則","last_checked_at":"2026-10-06T17:31:30+08:00","last_success_at":"2026-10-06T17:31:30+08:00","verification_status":"fetched","content_hash":"f4dbc7ef4b6f6c652952306f5c6b7f379f731e59a773b6b530d305e4b6c6c3a3","history":[{"observed_at":"2026-10-06T17:31:30+08:00","content_hash":"f4dbc7ef4b6f6c652952306f5c6b7f379f731e59a773b6b530d305e4b6c6c3a3","change_kind":"initial","revision_date":"2014-05-21"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"宜蘭縣非都市建築用地既有建築物重建排放水審查準則.pdf","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=2100&id=GL000532&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"第一條\n宜蘭縣政府為保障民眾居住基本生活需求，解決本縣部分建築用地因周邊地區無完善公共排水溝，致重建之建築物污水處理設施處理之生活雜排水，無法依建築技術規則排至有出口之溝渠，特訂定本準則。\n第二條\n本準則適用於非都市甲種建築用地，申請重建戶數未達四戶，且未逾重建前戶數，\n其建築物非屬四戶以上之集居社區型態，符合下列各款情形之ㄧ者：\n一、未經農地重劃，無公共排水溝。\n二、農地重劃時，其建築用地未比照耕地繳納農水路工程費，\n致未面臨排水系統。\n以集居社區開發型態申請建築者，污水處理應依建築法及建築技術規則等規定辦理。\n依第一項許可之建築物，於該地區未完成建置公共排水系統且其污水排放未銜接排水溝前，限作住宅使用。\n第三條\n重建前條地區內之建築物，應依下列原則辦理：\n一、建築物雨、污水管線應分流，污水處理設施應依建築技術規則設計，\n並加倍設置，以提高淨化效果，並設置放流水日後可銜接公共排水\n溝之裝置。\n二、生活雜排水經污水處理設施處理後之放流水應排放至基地既有排水\n溝或空地周邊土溝、野溪或私有水體等放流。\n無既有水溝時，應於基地內設置放流水淨化池，該池體大小應依基\n地土壤入滲率檢討設計。放流水淨化池應由起造人定期維護及設置防墜\n蓋板，並提送管理維護計畫。\n第四條\n本準則自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:GL000532","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"公發布日":"民國 106 年 12 月 08 日","圖表附件":"宜蘭縣非都市建築用地既有建築物重建排放水審查準則.pdf","法規名稱":"宜蘭縣非都市建築用地既有建築物重建排放水審查準則","法規體系":"建設","發文字號":"府秘法字第1060202658-B號 令"},"promulgation_date":"2017-12-08","revision_date":"2017-12-08","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=GL000532","status":"unknown","title":"宜蘭縣非都市建築用地既有建築物重建排放水審查準則","last_checked_at":"2026-10-06T17:31:18+08:00","last_success_at":"2026-10-06T17:31:18+08:00","verification_status":"fetched","content_hash":"7c5cd081865ab96c213b529fa67877b6406c1c13ca5302db0eae5ce55a5fd0de","history":[{"observed_at":"2026-10-06T17:31:18+08:00","content_hash":"7c5cd081865ab96c213b529fa67877b6406c1c13ca5302db0eae5ce55a5fd0de","change_kind":"initial","revision_date":"2017-12-08"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=2100&id=GL000532&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"(1150601)宜蘭縣餘土處理申請辦法修正總說明及修正對照表.pdf","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=5673&id=FL042853&type=LAW"},{"name":"(1150601)宜蘭縣餘土處理申請辦法.pdf","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=5674&id=FL042853&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"第1條\n本辦法依據宜蘭縣營建賸餘土石方管理自治條例第四條第五項規定訂\n定之。\n第2條\n本辦法餘土分類及其定義如下：\n一、B1類：岩塊、礫石、碎石或沙。\n二、B2-1類：土壤與礫石及沙混合物（土壤體積比例少於百分之三十\n）。\n三、B2-2類：土壤與礫石及沙混合物（土壤體積比例介於百分三十至\n百分之五十）。\n四、B2-3類：土壤與礫石及沙混合物（土壤體積比例大於百分之五十\n）。\n五、B3類：粉土質土壤（沉泥）。\n六、B4類：黏土質土壤。\n七、B5類：磚塊或混凝土塊。\n八、B6類：淤泥或含水量大於百分三十之土壤。\n九、B7類：連續壁產出之皂土\n第3條\n餘土依其分類，得於下列場所處理後再利用之：\n一、土資場：收容核准之營運計畫所載各類餘土。\n二、依法登記營運中之廠（場）所收容之餘土：\n（一）碎解洗選場：B1、B2-1、B2-2、B5類。\n（二）水泥廠：B3、B4類。\n（三）磚瓦窯廠：B4類。\n（四）礦石加工廠：B1類。\n（五）輕質骨材場：B4類。\n（六）預拌混凝土廠：B1至B5類。\n三、依法核准之土地改良場地：核准改良計畫所載之需土種類。\n四、經目的事業主管機關核准之需土工程：核准工程計畫所載需土種\n類。\n第4條\n申請於前條各類場所處理餘土，應填具申請書，並檢附下列文件向本\n府建設處提出：\n一、開工之餘土處理計畫書。\n二、土壤試驗報告。\n三、各類餘土數量計算表。\n四、收容場所管理單位出具之承諾收容文件。\n前項場所為碎解洗選場、水泥廠、磚瓦窯廠、礦石加工廠、輕質骨材\n場、預拌混凝土廠者，於每年第一次申請時應另檢附工廠登記證；其\n為土地改良場地、需土工程者，應另檢附主管機關核准文件。\n第一項第一款餘土處理計畫書，應載明下列事項：\n一、餘土產生地點。\n二、承運業者名稱。\n三、運送之路線、車次及起訖期間。\n四、收容處理地點。\n第一項第二款土壤試驗報告，應載明下列事項：\n一、建築基地範圍內，各開挖深度分布之土壤粒徑分析及分類。\n二、印有依標準法授權之中華民國實驗室認證體系CNLA、財團法人全\n國認證基金會TAF或其他實驗室認證機構之認可標章。\n第一項第三款各類餘土數量計算表，應由承造人之專任工程人員依據\n土壤試驗報告有關資料覈實計算，並簽章；承造人無置專任工程人員\n者，應由承造人負責辦理。\n第5條\n本辦法未規定事項，依據宜蘭縣營建賸餘土石方管理自治條例及其他\n有關規定辦理。\n第6條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:FL042853","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"修正日期":"民國 115 年 06 月 01 日","全文檔案":"(1150601)宜蘭縣餘土處理申請辦法.pdf","公發布日":"民國 96 年 04 月 10 日","法規名稱":"宜蘭縣餘土處理申請辦法","法規體系":"建設","發文字號":"府秘法字第1150094373B號令","立法理由":"(1150601)宜蘭縣餘土處理申請辦法修正總說明及修正對照表.pdf"},"promulgation_date":"2007-04-10","revision_date":"2026-06-01","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=FL042853","status":"unknown","title":"宜蘭縣餘土處理申請辦法","last_checked_at":"2026-10-06T17:31:10+08:00","last_success_at":"2026-10-06T17:31:10+08:00","verification_status":"fetched","content_hash":"c944f3721079952556ae5c3d43141c27e8807599801ed2769d89442619af2246","history":[{"observed_at":"2026-10-06T17:31:10+08:00","content_hash":"c944f3721079952556ae5c3d43141c27e8807599801ed2769d89442619af2246","change_kind":"initial","revision_date":"2026-06-01"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=5673&id=FL042853&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=5674&id=FL042853&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、宜蘭縣政府\n(\n以下簡稱本府\n)\n為辦理縣內有關高氯離子鋼筋混凝土建築物善\n後處理事項，特訂定本要點。\n二、本要點所稱之高氯離子鋼筋混凝土建築物，係指建築物之混凝土，經本府\n認可之專業鑑定機構、學校或團體辦理鑑定，其氯離子含量超過設計環境\n下之國家標準值，認定必須補強、防蝕處理或拆除重建者。\n前項專業鑑定機構、學校或團體，須檢具相關鑑定資格文件，向本府主管\n建築機關申請認可。\n三、本要點適用之建築物為民國八十四年六月三十日前，已依建築法規定領有\n使用執照之私有建築物。\n四、建築物所有權人，在發現建築物有白華、析晶、鋼筋銹蝕、混凝土剝落等\n現象時，應自行委託本府認可之鑑定機構、學校或團體實施鑑定，經鑑定\n屬高氯離子鋼筋混凝土建築物者，鑑定單位應在完成鑑定報告後，三十天\n內檢附相關鑑定報告副知本府主管建築機關。\n五、專業鑑定機構、學校或團體接受鑑定業務，其鑑定報告內容應包括建築物\n結構安全、氯離子含量情形、損壞程度，並提具體處理措施。\n六、高氯離子鋼筋混凝土建築物經本府認可之專業鑑定機構、學校或團體鑑定\n並報經本府認定須拆除重建者，應依建築法第八十一條規定，通知所有權\n人或使用人停止使用，並限期拆除，逾期未拆除，得強制拆除。\n七、經鑑定須補強或防蝕處理者，由本府通知建築物所有權人或使用人，在一\n定期限內，依鑑定報告處理措施完成補強或防蝕工作。\n八、高氯離子鋼筋混疑土建築物須補強、防蝕或拆除重建時，房屋所有權人得\n向本府申請房屋損壞程度證明，並於十五日內向稅捐稽徵單位辦理房屋稅\n減免手續。\n九、本要點奉縣長核定後實施，修正時亦同。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:FL034340","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"修正日期":"民國 99 年 12 月 08 日","公發布日":"民國 89 年 07 月 19 日","法規名稱":"宜蘭縣高氯離子鋼筋混凝土建築物善後處理要點","法規體系":"建設","發文字號":"府建使字第0990177694號"},"promulgation_date":"2000-07-19","revision_date":"2010-12-08","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=FL034340","status":"unknown","title":"宜蘭縣高氯離子鋼筋混凝土建築物善後處理要點","last_checked_at":"2026-10-06T17:31:31+08:00","last_success_at":"2026-10-06T17:31:31+08:00","verification_status":"fetched","content_hash":"9ea0885624b634a010f193155ca140b556b8272d90796a471119a0044fd50e79","history":[{"observed_at":"2026-10-06T17:31:31+08:00","content_hash":"9ea0885624b634a010f193155ca140b556b8272d90796a471119a0044fd50e79","change_kind":"initial","revision_date":"2010-12-08"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"附表一.DOC","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=123&id=FL034155&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"第 1 條\n宜蘭縣政府 (以下簡稱本府) 為管理入境土方，依規費法第七條第五款訂\n定本辦法。\n第 2 條\n本辦法所稱入境土方，係指天然土方或經本府指定範圍之土石，但不包括\n營建工程拆除剩餘之混凝土、磚、瓦及廢棄物。\n第 3 條\n載運入境土方前，申請人應依土方用途別，檢具本府各目的事業主管機關\n(單位) 規定之申請文件，向各該目的事業主管機關 (單位)  (如附表一\n) 申請核發運土憑證。\n圖表附件：\n附表一.DOC\n第 4 條\n申請人申請運土憑證，本府應徵收行政規費，每份新台幣一百二十元整。\n由申請人向本府出納單位繳費後，憑繳費收據至各目的事業主管機關 (單\n位) 領取。\n運土憑證由本府統一印制，每份為一式三聯，第一聯存稽查站，第二聯存\n目的事業主管機關 (單位) ，第三聯由申請人收執。\n第 5 條\n載運入境土方車輛應隨車攜帶運土憑證，行經本府設置之稽查站時應停車\n受檢，經稽查人員檢查通過並簽收運土憑證後，始得入境。\n第 6 條\n申請人應依各目的事業主管機關 (單位) 核准之運土憑證數量按月 (次)\n領取依序使用，並應按每星期辦理核銷，核銷總數達申領當次九成以上者\n，始得再次申領。運土憑證如有作廢，應一式三聯繳回核銷，倘有遺失應\n登報作廢。\n前項作廢繳回及遺失之運土憑證，本府不予退費。\n第 7 條\n本辦法未規定事項，依規費法及其他相關規定辦理。\n第 8 條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:FL034155","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"公發布日":"民國 92 年 10 月 09 日","廢止日期":"民國 95 年 10 月 30 日","法規名稱":"廢 宜蘭縣入境土方運土憑證申請辦法","法規體系":"建設","發文字號":"字第號"},"promulgation_date":"2003-10-09","revision_date":"2003-10-09","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=FL034155","status":"repealed","title":"廢 宜蘭縣入境土方運土憑證申請辦法","last_checked_at":"2026-10-06T17:31:12+08:00","last_success_at":"2026-10-06T17:31:12+08:00","verification_status":"fetched","content_hash":"404054b97b1c31fc41fc35447bcab82ea8d87aea2643500c56a5c4a20b56aed2","history":[{"observed_at":"2026-10-06T17:31:12+08:00","content_hash":"404054b97b1c31fc41fc35447bcab82ea8d87aea2643500c56a5c4a20b56aed2","change_kind":"initial","revision_date":"2003-10-09"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=123&id=FL034155&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"宜蘭縣政府","category":"建築管理相關","content":"第 1 條\n宜蘭縣政府（以下簡稱本府）為提昇宜蘭縣公共建築物供行動不便者使用\n設施之使用品質，並執行身心障礙者保護法及建築技術規則建築設計施工\n編第十章之規定，特訂定本辦法。\n第 2 條\n本辦法所稱之公共建築物係指建築技術規則建築設計施工編第一百七十條\n規定之公共建築物。\n第 3 條\n公共建築物於申請建造執照時，應檢附供行動不便者使用設施設置計畫書\n，經本府審查，合於「宜蘭縣公共建築物供行動不便者使用設施申請建造\n執照、變更設計、變更用途作業手冊」\n之規定，始得核發建造執照。\n第 4 條\n本辦法公布施行前，已申請建造執照之公共建築物，起造人得依「宜蘭縣\n公共建築物供行動不便者使用設施申請建造執照、變更設計、變更用途作\n業手冊」規定\n辦理變更設計，\n或完工後依本辦法第六條規定辦理。\n第 5 條\n建築物申請辦理變更用途屬「建築物使用類組及變更使用辦法」規定應設\n置無障礙設施之類組者，應依「宜蘭縣公共建築物供行動不便者使用設施\n申請建造執照、變更設計、變更用途作業手冊」\n提送供行動不便者使用設施設置\n報告書，併同變更使用執照審查。\n第 6 條\n本辦法公布施行前，已取得使用執照之公共建築物，經本府認定供行動不\n便者使用設施有不符規定者，依「宜蘭縣公共建築物無障礙環境分類、分\n期、分區改善執行計畫」，公共建築物之所有權人或管理機關負責人應依\n「宜蘭縣公共建築物供行動不便者使用設施改善計畫作業手冊」\n提送改善計畫書。\n第 7 條\n申請人無法依前三條規定設置各項供行動不便者使用設施，於不違反建築\n技術規則建築設計施工編第十章之範圍內，得提送計畫書，經「宜蘭縣公\n共建築物行動不便者使用設施改善諮詢及審查小組」同意後，採用其他設\n置方案。\n第 8 條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:FL041246","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"公發布日":"民國 95 年 11 月 14 日","廢止日期":"民國 102 年 12 月 05 日","法規名稱":"廢 宜蘭縣公共建築物供行動不便者使用設施設置辦法","法規體系":"建設","發文字號":"府秘法字第1020197043-B 令"},"promulgation_date":"2006-11-14","revision_date":"2006-11-14","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=FL041246","status":"repealed","title":"廢 宜蘭縣公共建築物供行動不便者使用設施設置辦法","last_checked_at":"2026-10-06T17:31:12+08:00","last_success_at":"2026-10-06T17:31:12+08:00","verification_status":"fetched","content_hash":"8a7fdb0a85a021b352e0fa216562f04533f38cb0bc3f8a7e025a3df5b93fb39d","history":[{"observed_at":"2026-10-06T17:31:12+08:00","content_hash":"8a7fdb0a85a021b352e0fa216562f04533f38cb0bc3f8a7e025a3df5b93fb39d","change_kind":"initial","revision_date":"2006-11-14"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"宜蘭縣政府","category":"建築管理相關","content":"第 1 條\n本辦法依據建築技術規則建築設計施工編第五十九條之二第一項規定訂定\n之。\n第 2 條\n本辦法所稱增設停車空間，係指建築物依都市計畫法及其他法令規定應設\n置之法定停車空間、核准之自設停車空間以外，再增設之營業使用停車空\n間。\n前項增設停車空間應依停車場法或相關法令規定對外開放供公眾停車使用。\n第 3 條\n本辦法之適用地區，應依都市計畫法或都市更新條例相關法令規定辦理。\n其相關法令未規定者，應為下列地區以外之都市計畫住宅區、商業區、工\n業區、旅舘區、市場用地、醫療專用區：\n一、依獎勵投資條例及促進產業升級條例所劃定之工業區。\n二、中華民國七十八年九月十九日以後實施區段徵收或市地重劃之地區。\n三、建築基地地籍邊線以外二百公尺範圍內，已開闢之公有路外公共停車\n場供汽車停車位合計總數達二百個以上者。但位於醫療專用區者，不\n在此限。\n非前項使用分區，其都市計畫書已載明比照前項分區土地使用管制規定且\n未排除適用本辦法者，得適用本辦法之規定。\n都市更新案其都市更新事業計畫於民國一百零一年十二月三十一日前已報\n核，並依都市更新條例第六十一條之一規定，申請建造執照其法規之適用\n以擬定都市更新事業計畫報核日為準者，不受第一項各款之限制。\n第 4 條\n依本辦法增設停車空間之建築物，得增加建築物樓地板面積△FA，並依下\n列公式計算：\n△FA=25×N×M×L≦FA×P\nN：增設之停車空間數量。總停車數（含法定停車及自設停車數量）小於\n申請戶數時，或每層增設停車位數量小於十五個者（採用機械停車設\n備者，應為全自動設備始得計入，如為立體停車塔應以整座車位計算\n之），或以機械停車設備設置者，N值以零計算；設全自動機械停車設\n備或停車塔者，每一停車空間N值應乘以零點六計算。\nM：道路寬度鼓勵係數，詳表一。\nL：規劃設計鼓勵係數，詳表二。\nFA：建築物基準總樓地板面積，依都市計畫法規及其相關法令規定該基地\n之容積率與基地面積之乘積。\nP：鼓勵上限係數。依建築技術規則建築設計施工編第十五章實施都市計畫\n地區建築基地綜合設計或山坡地建築之申請案P=0.1，其他一般地區之\n申請案P=0.2。\n前項得增加之樓地板面積，應計入核算法定停車空間之樓地板面積。\n供增設停車空間使用之樓地板免計入容積總樓地板面積核算。但每個停車\n空間免計額最大不得超過四十平方公尺。\n第 5 條\n建築物允建高度、高度比、深度比之檢討，得將基地地面提高△H值起算\n，△H值等於增設停車空間之樓層高度總和。但地下層每層增設之停車空\n間數量在二十個以上及地面以上每層增設之停車空間數量在十五個以上\n者，其樓層高度始得計算在內。\n增加之樓層高度及樓層數最大值如表三。但每層停車空間超過者，\n以計算，且△H值超過者，以計算。\n建築物應依建築技術規則建築設計施工編第二十三條第二項及第一百六十\n四條檢討日照及陰影，並應以提高前之基地地面檢討。\n建築基地位於山坡地者，其建築物高度不適用本辦法增加之樓層高度規定\n。\n第 6 條\n防空避難設備不得兼作增設停車空間使用。增設停車空間與其他使用空間\n位於同一樓層者，應以無開口之防火牆區隔；與法定停車空間位於一樓層\n者，應集中留設於近車道出入口處，除車道外，應以分間牆予以區劃。\n第 7 條\n於地面上增設停車空間者，應自地面層向上（含地面層）連續樓層設置；\n於地下層增設停車空間者，應自地下層向下連續樓層設置。\n第 8 條\n地面層以上供增設停車空間使用之樓層，其面向道路之外牆，每一立面應\n透空二分之一以上（樓梯間、電梯間及排煙室除外），並不得設置窗戶。\n但設置符合國家標準全自動昇降之機械停車空間者（停車塔），不在此限\n。\n臨地界線應設置外牆，不得透空，且每一立面開設門窗之面積不得大於三\n分之一。\n第 9 條\n依本辦法審核建築物增設停車空間時，得就停車空間需求、停車場出入口\n動線及其他交通相關事項，徵詢交通主管機關意見；停車位總數（含法定\n及自設停車空間）達建築物交通影響評估準則第二條規定者，應先進行交\n通影響評估審核。\n第 10 條\n建築物增設停車空間之建造執照、使用執照及詳細平面圖上應加註或標示\n於X層增設Y個營業用停車空間，為公寓大廈之專有部分，所有權人以單獨\n編列建號辦理登記，並依停車場法或其他法令規定對外開放供公眾停車使\n用。\n起造人或所有權人除得於適當位置設置管理員室外，應設置下列設施及設\n備，並負責其管理維護：\n一、警示燈。\n二、反射鏡。\n三、於建築物進出口明顯位置設置動態剩餘車位顯示裝置及標示牌。（標\n示牌規格如表四）\n四、供行動不便者使用停車空間至少一處。\n第 11 條\n起造人申請使用執照時，應檢附經宜蘭縣政府（以下簡稱本府）審核同意\n之增設停車空間營業管理規範；領得使用執照後六個月內應依停車場法相\n關規定申領停車場登記證，對外開放供公眾停車收費使用。\n前項營業管理規範應納為公寓大廈管理規約草約之附件。\n第 12 條\n本府對於已核發使用執照之增設停車空間，應列管並不定期抽查。未依第\n十條規定加註或標示者，除通知所有權人或管理單位改善外，並應依建築\n法及停車場法相關規定處理。\n第 13 條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:FL034803","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"公發布日":"民國 94 年 03 月 25 日","廢止日期":"民國 108 年 05 月 08 日","法規名稱":"廢 宜蘭縣建築物增設停車空間鼓勵辦法","法規體系":"建設","發文字號":"府秘法字第1080074307B號令"},"promulgation_date":"2005-03-25","revision_date":"2005-03-25","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=FL034803","status":"repealed","title":"廢 宜蘭縣建築物增設停車空間鼓勵辦法","last_checked_at":"2026-10-06T17:31:41+08:00","last_success_at":"2026-10-06T17:31:41+08:00","verification_status":"fetched","content_hash":"5f12cdec21ea1799a654bc581359fea4a8dfc4104bcff75ee134e72f5910ba8f","history":[{"observed_at":"2026-10-06T17:31:41+08:00","content_hash":"5f12cdec21ea1799a654bc581359fea4a8dfc4104bcff75ee134e72f5910ba8f","change_kind":"initial","revision_date":"2005-03-25"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、宜蘭縣政府 (以下簡稱本府) 為辦理現有巷道指定建築線案，依據「\n宜蘭縣建築管理自治條例」第四條第三項之規定，訂定本執行要點。\n二、本府受理現有巷道指定建築線之單位為建設局城鄉計畫課。\n三、受理現有巷道指定建築線之原則如下：\n(一) 寬度：寬度須達二公尺以上之巷道。\n(二) 使用性質：下列情形不得認定。\n1.都市計畫地區內，位於公共設施用地內之巷道。\n2.非都市計畫地區內，位於特定目的事業用地內 (屬公共設施性質\n) 之巷道。\n3.依相關法令規定，不得建築或指定建築線地區內之巷道。\n(三) 使用期間及通行情形：\n1.二十年間繼續並表現者。但屬政府機關開闢及維護，其開闢寬度\n達六公尺以上，由主辦工程機關或當地管理維護之鄉 (鎮、市)\n公所出具證明者，不在此限。\n2.足以證明供不特定對象通行使用之事實者。\n四、受理之申請案件，得由本府建設局城鄉計畫課邀集相關單位、人員至\n現場勘查，就下列事項查明並作成紀錄：\n(一) 寬度：\n1.巷道寬度之認定，其兩旁有排水溝或斷崖者，以水溝內緣或斷崖\n為準，無排水溝者，以該巷路兩旁建築物 (或圍牆) 間之最小淨\n距離為準。\n2.前目所稱「巷路兩旁建築物」包括陽台在內，但不包括屋簷及雨\n庇。\n(二) 使用性質：\n1.是否違反土地使用分區或使用編定。\n2.是否有供不特定公眾通行之事實。\n(三) 使用期間及通行情形：\n1.該現有巷道通行之期間及目前通行之戶數。\n2.前目巷道通行時間及戶數之證明文件得為戶籍設籍證明、房屋稅\n籍證明、接水電證明、建物登記簿謄本正本、戶籍謄本及其他可\n供證明之文件。\n3.屬政府機關開闢及維護者，出具主辦工程機關或當地鄉 (鎮、市\n) 公所管理維護之證明文件。\n五、本要點奉縣長核定後實施，修正時亦同。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:FL034346","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"公發布日":"民國 92 年 06 月 30 日","廢止日期":"民國 108 年 11 月 01 日","法規名稱":"廢 宜蘭縣政府辦理現有巷道指定建築線執行要點","法規體系":"建設","發文字號":"府建都字第1080183222B號"},"promulgation_date":"2003-06-30","revision_date":"2003-06-30","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=FL034346","status":"repealed","title":"廢 宜蘭縣政府辦理現有巷道指定建築線執行要點","last_checked_at":"2026-10-06T17:31:14+08:00","last_success_at":"2026-10-06T17:31:14+08:00","verification_status":"fetched","content_hash":"2e7d472a821f9b303ab34006e9c41dda7d9404ffe74901ef4a579f641588cdeb","history":[{"observed_at":"2026-10-06T17:31:14+08:00","content_hash":"2e7d472a821f9b303ab34006e9c41dda7d9404ffe74901ef4a579f641588cdeb","change_kind":"initial","revision_date":"2003-06-30"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、依據：\n（一）身心障礙者權益保障法第五十七條。\n（二）內政部營建署九十二年二月十四日研商九十一年度公共建築物無障\n礙生活環境業務督導工作檢討案第二次會議決議。\n二、清查對象：\n（一）社會福利機構（提供庇護及安置服務兒童、少年、婦女、老人及身\n心障礙者之機構）\n（二）醫院\n（三）政府機關\n（四）鐵路車站、客運車站\n（五）圖書館\n（六）集會場\n（七）殯儀館\n（八）展覽館（場）\n（九）公共廁所（與機關合併者併入機關清查）\n（十）體育館（學校內體育館併入學校專案）\n（十一）電影院、演藝場所\n（十二）國際觀光飯店\n（十三）郵局、電信局（民營電信業者之直營門市除外）、銀行、合作社\n、市場、百貨公司\n（十四）衛生所\n（十五）集合住宅（每幢五○戶以上或六層以上）\n（十六）學校（縣立國中小另有專案，不列入本計畫）\n三、清查單位：由社會處、建設處成員分三組，每組二名。\n組  別    清查區域\n第一組    礁溪、頭城、壯圍、員山、五結\n第二組    宜蘭、大同、冬山、三星\n第三組    羅東、蘇澳、南澳\n四、工作內容：\n（一）彙整列管清冊。\n（二）現場作業：\n1.填具檢查紀錄表。（如附表）\n2.數位照相紀錄。\n（三）檔案整理、報表彙製。\n五、辦理期限：配合公共服務擴大就業方案期程辦理。\n六、經　費：由本項工作執行業務費支應。\n七、本計畫奉縣長核可後實施，修正時亦同。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:FL034350","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"公發布日":"民國 93 年 07 月 08 日","廢止/停止適用日期":"民國 107 年 01 月 25 日","法規名稱":"廢/停 宜蘭縣公共建築物設置供行動不便者使用設施清查工作執行計畫","法規體系":"建設","發文字號":"府建字第1070015879號 函"},"promulgation_date":"2004-07-08","revision_date":"2004-07-08","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=FL034350","status":"unknown","title":"廢/停 宜蘭縣公共建築物設置供行動不便者使用設施清查工作執行計畫","last_checked_at":"2026-10-06T17:31:13+08:00","last_success_at":"2026-10-06T17:31:13+08:00","verification_status":"fetched","content_hash":"ecf3a815d30663b49a9f4bd79b8302cffefed37bd06bbf1fed449573e32605f0","history":[{"observed_at":"2026-10-06T17:31:13+08:00","content_hash":"ecf3a815d30663b49a9f4bd79b8302cffefed37bd06bbf1fed449573e32605f0","change_kind":"initial","revision_date":"2004-07-08"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、宜蘭縣政府基於用電為公共安全、公共衛生及民生所必需暨維護大同\n、南澳山地鄉未領得使用執照住戶用電之基本生存權，特依台灣省政\n府八十五年九月廿日八五府建四字第一六六○一○號函訂定本要點。\n二、本要點適用於大同、南澳山地鄉民國八十六年一月十六日之前既有住\n宅。\n三、申請之住戶須設籍當地六個月以上 (即八十五年七月十六日前) ，並\n由鄉公所出具證明。\n四、工寮及農業設施等用電依其相關規定申請。\n五、臨時接電後之房屋不得作為非住宅用途之使用。\n六、臨時接電申請應依左列事項切結：\n(一) 基於解決日常生活之迫切需要准予臨時接電，但不能視同合法房屋\n。\n(二) 違建處理仍依「建築法」、「違章建築處理辦法」及其他相關規定\n辦理；如因公共建設之所需，建物願無條件配合拆除，並負一切法\n律責任。\n七、符合本要點之申請住戶由鄉公所調查完後，造冊並檢附切結書函送本\n府備後由公所函請臺灣電力公司接電並通知申請住戶辦理。\n八、本要點簽奉縣長核定後實施，至八十六年十二月三十一日失其效力。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:FL034334","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"公發布日":"民國 0 年 00 月 00 日","廢止/停止適用日期":"民國 86 年 06 月 07 日","法規名稱":"廢/停 宜蘭縣大同、南澳山地鄉未領得使用執照住宅臨時接電處理要點","法規體系":"建設","發文字號":"八六府建管字第065507號"},"promulgation_date":null,"revision_date":null,"source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=FL034334","status":"unknown","title":"廢/停 宜蘭縣大同、南澳山地鄉未領得使用執照住宅臨時接電處理要點","last_checked_at":"2026-10-06T17:31:14+08:00","last_success_at":"2026-10-06T17:31:14+08:00","verification_status":"fetched","content_hash":"32fd3495ec3ed39aaebebcb4d03c8e00c149dae88e0c578060036d1a3d38de50","history":[{"observed_at":"2026-10-06T17:31:14+08:00","content_hash":"32fd3495ec3ed39aaebebcb4d03c8e00c149dae88e0c578060036d1a3d38de50","change_kind":"initial","revision_date":null}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"bde2d661a23104462aa2bb10a3eb9755_107D083224_107D2034575.pdf","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=2398&id=FL034330&type=LAW"},{"name":"附表一、宜蘭縣政府獎勵縣內建築物採斜式屋頂獎勵金申請表.DOC","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=558&id=FL034330&type=LAW"},{"name":"附表二、切結書.DOC","url":"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=559&id=FL034330&type=LAW"}],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、為鼓勵縣內居民重視環境景觀特色及建築內涵，維持整體景觀之和諧\n，特訂定本要點。\n二、獎勵對象：\n縣內建築物之起造人或所有權人。\n三、獎勵條件：\n依規定程序申請新建之建築物，採斜式屋頂，斜率不得少於百分之二\n十五，其斜屋頂之水平投影面積應大於建築面積 50 ％，經本府審查\n合格，並經縣內主管建築機關 (含各縣鎮市公所) 核發建造執照者，\n均可申請補助；原有合法建物之增建、改建、修建，除公有建築物外\n，得比照辦理。\n圖表附件：\n附表一、宜蘭縣政府獎勵縣內建築物採斜式屋頂獎勵金申請表.DOC\n附表二、切結書.DOC\n四、房屋建築造型、色彩、材質：\n(一) 屋頂材料：木瓦、陶瓷瓦、柔性瓦、鋼瓦、貼大片磁磚或經本府認\n定核可之材料 (鋁鋅鋼板、鐵皮除外) 等。\n(二) 屋頂顏色：紅色色系、藍綠色、藍灰色、橘黃色、黑灰色。\n(三) 牆材料：石材、紅磚、清水磚、丁掛、面磚、RC (加水泥粉或清水\n模板) 、木材、竹材。\n五、申請獎勵金手續：\n申請人應於領得使用執照一個月內檢具左列文件，提送本府審核，經\n派員實地勘驗合格後，核發獎勵金憑領單 (格式如附表二) 至本府領\n取獎勵金。\n(一) 申請表一式兩份 (格式如附表一) 。\n(二) 建築物完工後各立面照片。\n(三) 新建 (增建、改建、修建) 建築物使用執照影本一份。\n(四) 身份證或公司合法證明文件 (含負責人身份證) 。\n(五) 切結書一式兩份 (格式如附表三) 。\n六、獎勵金核發標準：\n申請獎勵金面積以斜屋頂投影面積計算，每戶申請不得超過一五○平\n方公尺，每平方公尺獎勵新台幣六○○元。\n七、獎勵金發放後，非經申請同意，不得任意改變屋造型，如房屋所有權\n人違反規定，應依切結書收回獎勵金。\n八、獎勵金之發放依申請之優先順序核發。\n九、本要點奉縣長核可後實施，修正時亦同。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:FL034330","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"公發布日":"民國 84 年 07 月 26 日","廢止/停止適用日期":"民國 107 年 08 月 27 日","法規名稱":"廢/停 宜蘭縣政府獎勵縣內建築物採斜式屋頂實施要點","法規體系":"建設","發文字號":"府建管字第1070142557號 函","立法理由":"bde2d661a23104462aa2bb10a3eb9755_107D083224_107D2034575.pdf"},"promulgation_date":"1995-07-26","revision_date":"1995-07-26","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=FL034330","status":"unknown","title":"廢/停 宜蘭縣政府獎勵縣內建築物採斜式屋頂實施要點","last_checked_at":"2026-10-06T17:31:12+08:00","last_success_at":"2026-10-06T17:31:12+08:00","verification_status":"fetched","content_hash":"deaeefe5d5e68c97c102417b5b30af90c466e5650a5c0894d3e3cf3bd1fcc7a8","history":[{"observed_at":"2026-10-06T17:31:12+08:00","content_hash":"deaeefe5d5e68c97c102417b5b30af90c466e5650a5c0894d3e3cf3bd1fcc7a8","change_kind":"initial","revision_date":"1995-07-26"}],"version_count":1,"attachment_hashes":{"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=2398&id=FL034330&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=558&id=FL034330&type=LAW":null,"https://glrslaw.e-land.gov.tw/Download.ashx?FileID=559&id=FL034330&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"宜蘭縣政府","category":"建築管理相關","content":"一、宜蘭縣政府基於水、電為公共安全、公共衛生及民生所必需，特依台\n海省政府八五年九月二十日府達四字第 166010 號函訂定本處理要點\n。\n二、適用對象：民國八十五年九月二十日以前已存在之既有建築物，並符\n合左列條件者：\n(一) 建築物高度在三層以下，且最大基層面積未超過一六五平方公尺者\n。\n(二) 僅供住宅用途使用。\n(三) 無佔用公地或違反都市計畫土地使用分區及非都市土地使用管制規\n則之情事者。\n三、申請接用臨時水、電應切結左列事項：\n(一) 基於解決日常生活之迫切需要申請核准接用臨時水、電，但明瞭建\n物不視同合法建築物。\n(二) 違建處理仍依「建築法」、「違章建築處理辦法」及其他相關規定\n辦理；如因公共建設之所需，建築物願無條件配合拆除，並負一切\n法律責任。\n四、申請人應檢附申請書、切結書(如附件)、照片向所轄之鄉鎮市公所申\n請，經各鄉鎮公所審核合格後，核發臨時接用水、電同意函，由住戶\n逕向臺灣電力公司及自來水公司接用臨時水、電。\n五、依照本本要點申請臨時接用水、電者，如因違反建築法或其他法令遭\n強制斷水、電者，不得再適用之。\n六、各鎮市公所應按月將核可之文件造冊送本府備查。\n七、本點簽奉縣長核定後公佈實施，實施期限一年。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:FL034337","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"公發布日":"民國 0 年 00 月 00 日","廢止/停止適用日期":"民國 87 年 08 月 25 日","法規名稱":"廢/停 宜蘭縣未領得使用執照之既有建築物臨時接用水、電處理要點","法規體系":"建設","發文字號":"八七府建管字第102319號"},"promulgation_date":null,"revision_date":null,"source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=FL034337","status":"unknown","title":"廢/停 宜蘭縣未領得使用執照之既有建築物臨時接用水、電處理要點","last_checked_at":"2026-10-06T17:31:14+08:00","last_success_at":"2026-10-06T17:31:14+08:00","verification_status":"fetched","content_hash":"c821ca0d4e7bd5b8a538578be9225b2f6447abceadf73735c8966e88cf55b109","history":[{"observed_at":"2026-10-06T17:31:14+08:00","content_hash":"c821ca0d4e7bd5b8a538578be9225b2f6447abceadf73735c8966e88cf55b109","change_kind":"initial","revision_date":null}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"宜蘭縣政府","category":"建築管理相關","content":"第 1 條\n為辦理建築法第九十九條第一項及宜蘭縣建築管理規則自治條例第三十六\n條規定之各項活動臨時性建築物管理，特訂定本作業程序。\n第 2 條\n本作業程序所稱之各項活動搭建臨時性建築物，係指由目的事業主管機關\n核定辦理之文教藝術、體育競技、育樂休閒、慈善公益、生活新知、民俗\n節慶、商品販賣及競選集會或類似活動所需，符合建築法第四條所規定之\n構造物或雜項工作物。\n第 3 條\n本作業程序臨時性建築物之管理，應符合區域計劃法及都市計劃法等有關\n土地容許使用及使用強度之規定。\n第 4 條\n申請人應於辦理各項活動十日前委託建築師，檢附下列書圖文件，向宜蘭\n縣政府建設局 (以下簡稱本局) 申請：\n一  申請書。\n二  目的事業主管機關核准文件。\n三  土地使用權利證明文件：\n(一) 土地登記簿謄本。\n(二) 地籍圖謄本。\n(三) 土地使用權同意書。\n四  建築師委託書及專業技師簽證書。\n五  基地現況相片。\n六  拆除切結書。\n七  工程圖樣：\n(一) 基地位置圖：標明基地位置、方位、都市計畫土地使用分區或區域\n計畫土地使用編定。\n(二) 地盤圖：於地籍圖描繪圖上標明基地之方位、地號、境界線、臨接\n道路之名稱、寬度、建築物之建築面積投影圖。\n(三) 配置圖：標明基地之方位、地形、四週道路、附近建築物情況 (含\n層數及構造) 、申請建築物之地面層平面圖、基地標高、水系統及\n排水方向。\n(四) 面積計算表。\n(五) 各層建築平面圖及屋頂平面圖：標明各部份之用途及尺寸，比例尺\n不得小於二百分之一。\n(六) 建築物各項立面圖，比例尺不得小於二百分之一。\n(七) 建築物剖面圖：註明建築各部尺寸及所用材料。\n(八) 各層結構平面圖：標明材料強度。\n八  結構計算書。\n九  其他必要設備圖說。\n第 5 條\n申請人應於竣工後檢附下列書圖文件向本局申請竣工查驗：\n一  申請書。\n二  原領核准文件。\n三  建築物各向立面及建築物內部竣工相片。\n四  建築物竣工平面圖及立面圖。\n五  消防合格證明。\n第 6 條\n本作業程序臨時使用許可之核發及使用期滿逾期未拆除之處理，應依宜蘭\n縣建築管理規則自治條例第三十六條第四項規定辦理。\n第 7 條\n前條核發之臨時使用許可，得憑以接用臨時水電\n第 8 條\n本作業程序奉 縣長核定後實施，修正後亦同。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"yilan:FL023839","jurisdiction":"宜蘭縣","metadata_only":false,"official_fields":{"公發布日":"民國 92 年 02 月 10 日","廢止/停止適用日期":"民國 107 年 05 月 24 日","法規名稱":"廢/停 宜蘭縣辦理各項活動搭建臨時性建築物管理作業程序","法規體系":"建設","發文字號":"府建管字第1070084896號 函"},"promulgation_date":"2003-02-10","revision_date":"2003-02-10","source_id":"yilan","source_updated_at":null,"source_url":"https://glrslaw.e-land.gov.tw/LawContent.aspx?id=FL023839","status":"unknown","title":"廢/停 宜蘭縣辦理各項活動搭建臨時性建築物管理作業程序","last_checked_at":"2026-10-06T17:31:13+08:00","last_success_at":"2026-10-06T17:31:13+08:00","verification_status":"fetched","content_hash":"e50e4b058796afba62d2cb5320190530c44e43baec2d8c0100a4b8518d12519a","history":[{"observed_at":"2026-10-06T17:31:13+08:00","content_hash":"e50e4b058796afba62d2cb5320190530c44e43baec2d8c0100a4b8518d12519a","change_kind":"initial","revision_date":"2003-02-10"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"一、屏東縣政府(以下簡稱本府)為活絡地方經濟，扶植中小企業發展，\n提供融資信用保證，特訂定本要點。\n二、本要點中小企業貸款(以下簡稱本貸款)資金來源，由本府公開徵選\n擇定之金融機構(以下簡稱承貸銀行)提供資金辦理。\n三、符合下列條件者，得申請本貸款，但申請以一次為限：\n設籍本縣四個月以上之中華民國國民，年齡在二十歲以上六十五歲\n以下並於本縣辦理公司或商業登記之中小企業公司或行號。\n本貸款於必要時，得徵提連帶保證人。\n四、本貸款受理期限至本府與承貸銀行所簽合約書到期日止。\n五、本貸款貸放款額度最高為新臺幣三百萬元，視申請人之事業計畫書\n所載需用資金審核。\n六、本貸款用途以購置或租用營業所需之廠房、營業場所、機器、設備\n、裝潢、營運週轉金為限。\n申請用途為購置或租用機器設備者，得免辦理動產抵押設定。但購\n置或租用廠房、營業場所、機器、設備、裝潢者，應於核准貸款後\n三個月內完成購置或租用，於購置或租用事實存在後，憑發票或憑\n證辦理撥貸；申請營運週轉金者應於申請日前實際營業三個月以上\n。\n七、本貸款期限最長為七年，還本付息方式得以本金寬緩二年及按月付\n息，寬緩期滿，按月平均攤還本息。\n八、本貸款利率，按中華郵政股份有限公司二年期定期儲金機動利率加\n年息百分之一點四五機動計息為上限，實際計息以公開徵選銀行提\n供之放款利率為主。\n九、符合申請條件者，年齡未滿四十五歲且須完成本府青年學院所開辦\n創業相關套裝課程並領有結訓證書，貸款期間所生利息，由貸款人\n支付利息之百分之一點二九，其餘由本府負擔。\n十、本貸款利息補貼由承貸金融機構按季向本府申請。承貸金融機構應\n按月將貸款人每月應繳款利息彙送本府，據以核撥利息補貼金額。\n十一、貸款人經營之事業有下列情形之一者，應於事實發生起七日內，\n以書面通知本府，本府應停止利息補貼，並通知貸款人及承貸金\n融機構：\n（一）停業或歇業。\n（二）營業場所遷離本縣。\n（三）變更負責人或法定代表人。\n經本府查核發現有第一項所定應停止利息補貼之事由時，\n應停止利息補貼，並通知貸款人及承貸金融機構，且日後不\n得繼續補貼利息。\n十二、本貸款由本府撥付財團法人中小企業信用保證基金(以下簡稱信保\n基金)新臺幣五百萬元，信保基金提供相對資金新臺幣七百五十萬\n元，合計新臺幣一千二百五十萬元，辦理本貸款履行保證責任所\n需之支出(含攤付因本貸款所衍生之訴訟、執行及其他必要費用)。\n本貸款設定信用保證融資總金額以一億二千五百萬元為限。\n本府及信保基金依前項規定提撥之金額不足履、行保證責任時，雙\n方應分別補足各應負擔之金額。\n十三、本貸款履行保證責任所需之支出，本府及信保基金提供之資金搭配\n比率負擔。\n十四、申請人依信保基金相關規定申請信用保證，其前一年度營業額達五\n百萬元以上者，保證成數為九成；設立未滿一年或前一年度營業額\n未達新臺幣五百萬元者，保證成數為九成五，保證手續費以固定年\n費率百分之零點三七五計算。\n十五、除信用保證費用及必要之徵信查詢規費外，承貸銀行不得向申請人\n收取任何額外費用。\n十六、申請本貸款應檢附申請文件向承貸銀行提出。\n前項申請文件由本府另定之。\n十七、本貸款由本府設置屏東縣中小企業貸款審查小組(以下簡稱審查小組\n)，就申請人之資格、財務結構、營業情況及產業前景等事項進行審\n查，經審查通過者，發給合格通知書。\n申請人應於收受合格通知書之次日起三個月內，向承貸銀行辦理貸款\n，逾期未辦理者，應向本府城鄉發展處重新提出申請。\n申請人未獲合格，得請求復審，惟復審以一次為限。\n十八、審查小組成員九人，其中一人為召集人，由縣長指派之；餘由本府城\n鄉發展處、財政處、主計處、屏東縣工商發展投資策進會、屏東縣商\n業會、屏東縣工業會、信保基金及承貸銀行各一人兼任。\n審查小組成員均為無給職，除承貸銀行外，其他委員須親自出席會議\n，不得代理。\n十九、審查小組會議視受理案件需要，不定期召開，並邀請相關單位派員列\n席。\n二十、審查小組會議之決議，應以審查小組成員三分之二以上出席，出席成\n員二分之一以上同意行之。\n二十一、審查小組成員有下列情形之一者，應予迴避，不得參與審查：\n(一)本人或其配偶擔任申請人之任何職位或解任未滿一年。\n(二)本人或其配偶與申請人之負責人、發起人、董事、監察人、經理\n人或持有百分之十以上股份之股東，有配偶、直系親屬或三親等\n以內之旁系血親關係。\n(三)本人或其配偶與申請人之負責人、發起人、董事、監察人、經理\n人或持有百分之十以上股份之股東有共同經營事業或分享利益之\n關係者。\n審查小組成員對審查過程獲悉之資訊，應予保密。\n二十二、有下列情形之一者，本府得停止受理本貸款之申請：\n(一)本貸款信用保證融資總金額達新臺幣新臺幣一億二千五百萬元。\n(二)本貸款逾期保證餘額加計代償餘額達新臺幣一千二百五十萬元。\n二十三、本府發給合格通知書後，申請人有下列情形之一者，承貸銀行應停止\n貸放：\n(一)經向票據交換所查詢，使用之票據曾受拒絕往來處分，或知悉其\n退票尚未清償註記之張數，已達受拒絕往來處分之標準者。\n(二)經向金融聯合徵信中心查詢，或徵授信過程中，有債務本金逾期\n尚未清償，或尚未依約定分期攤還已超過一個月，或應繳利息尚\n未繳付而延滯期間超過三個月，或有信用卡消費款項或現金卡未\n繳納，遭發卡銀行強制停卡，且未繳清延滯款項者。有前述情形\n之一者，經與貸款銀行前置協商後，正常還款達一年以上，且徵\n得連帶保證人二人者，不在此限。\n二十四、承貸銀行辦理本貸款，應確實依其核貸作業辦法、徵授信規定及本要\n點之規定辦理。\n二十五、承貸銀行應妥為保存本貸款相關資料，以備本府及信保基金派員實地\n前往查核。\n二十六、辦理本貸款之信保基金及承貸銀行經辦人員，非出於故意重大過失或\n舞弊情事所造成的呆帳，依審計法第七十七條第一項第一款之規定得\n免除全部損害賠償責任，並免除予以糾正之處置。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000073","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"修正日期":"民國 111 年 10 月 13 日","公發布日":"民國 100 年 12 月 30 日","法規名稱":"屏東縣中小企業貸款實施要點","法規體系":"城鄉發展處","發文字號":"屏府城工字第11159434500號函"},"promulgation_date":"2011-12-30","revision_date":"2022-10-13","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000073","status":"unknown","title":"屏東縣中小企業貸款實施要點","last_checked_at":"2026-10-06T17:32:00+08:00","last_success_at":"2026-10-06T17:32:00+08:00","verification_status":"fetched","content_hash":"2e7df6d9904beef7ee1738e9f4ab94e0c5df5da2134e6d54e853448d585bd4d8","history":[{"observed_at":"2026-10-06T17:32:00+08:00","content_hash":"2e7df6d9904beef7ee1738e9f4ab94e0c5df5da2134e6d54e853448d585bd4d8","change_kind":"initial","revision_date":"2022-10-13"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"第 一 條　　屏東縣(以下簡稱本縣)為辦理人行道設置斜坡道申請事宜，特訂定本\n辦法。\n第 二 條　　本辦法主管機關為屏東縣政府，管理機關為本縣各鄉（鎮、市）公所。\n第 三 條　　本辦法所稱斜坡道，指為調整人行道與道路間原有高差所興建之內嵌\n式平緩斜坡，高低差與斜坡度應符合市區道路及附屬工程設計規範之規定\n，並分為下列三類：\n一、汽車斜坡道：供汽車進出，其寬度最小為二點七五公尺，最大為八公\n尺。\n二、機車斜坡道：供機車、腳踏車進出，其寬度最小為零點九公尺，最大\n為一點五公尺。\n三、無障礙斜坡道：供輪椅進出，其寬度最小為零點九公尺，最大為一點\n五公尺。\n第 四 條　　有下列情形之一者，得申請設置汽車斜坡道：\n一、作為車庫、停車位或停車場通道之使用且確有停車事實。\n二、經營汽車買賣業、汽車保養業、汽車修理業、汽車裝潢業、汽車美容\n業、汽車清洗業、車輪定位業、輪胎更換業、小客車租賃業或計程車\n營業站、加油站或倉儲物流業，且營業場所內確有停車空間及停車之\n事實。\n第 五 條　  有下列情形之一者，得申請設置機車斜坡道：\n一、經營機車買賣業、機車保養業或機車修理業，且營業場所內確有停車\n空間之事實。\n二、住家有機車出入需要，並符合下列情形之一者：\n(一)設置地點距離最近斜坡道十五公尺以上。\n(二)設置地點至鄰近斜坡道間無平順路面可通行。\n第 六 條　　設置地點有行動不便使用輪椅人士居住或出入者，得申請設置無障礙\n斜坡道。\n第 七 條　　申請設置斜坡道者，應填具申請書並檢附下列文件向管理機關提出：\n一、設置地點現況調查表及現況照片。\n二、地籍圖謄本、圖面繪製，並標示申請地點、斜坡道位置及相關道路名\n稱。\n三、申請日前三個月內之土地登記簿謄本（標示部、他項權利部）。\n四、申請人為自然人，其身分證（正、反面）影本。申請人為法人或行號\n者，公司登記證明文件或商業登記證明文件及其代表人之身分證正、\n反面影本。但政府機關、公營事業機構或公立學校免附。\n五、依第四條第一款規定申請者，並應加附下列文件：\n(一)對外營業之車庫、停車位或停車場，其停車場登記證影本。\n(二)設置於建築物內或已建築土地之車庫、停車位或停車場，其建築物\n使用執照及核准平面圖影本。\n(三)設置於私有未建築土地之停車位或停車場，其土地所有權證明或使\n用同意書。\n六、依第四條第二款或第五條第一款規定申請者，並應加附房屋所有權證\n明或使用同意書，及營利事業登記證。\n七、依第五條第二款規定申請者，並應加附房屋所有權證明或使用同意書。\n八、依前條規定申請者，並應加附下列文件：\n(一)行動不便人士需使用輪椅相關證明（如身心障礙手冊或證明影本、\n醫院診斷書或村（里）辦公處出具之證明書等）。\n(二)申請人或其親屬所有之房屋所有權證明或行動不便者設籍證明文件。\n第 八 條　　申請設置斜坡道者，設置費用應依下列規定辦理：\n一、斜坡道經申請核准者，由申請人於核准之日起三個月內，依管理單位核\n發之圖說自行負擔費用施工完成，並檢附完工後之照片送管理機關備查\n。逾期未施工完成者，管理機關得廢止其核准。\n二、配合人行道更新或改善工程設置者，得由工程主辦機關併人行道工程一\n併施工，其施工期限及費用負擔不適用前款規定。\n第 九 條　　申請人施工時，應依下列規定辦理：\n一、原有人行道應採先切割後打除方式辦理。\n二、設置地點原有之溝蓋、緣石等附屬設施應一併設置。\n三、立體停車場及地下停車場之汽車斜坡道出入口應加設車輛駛出感應裝\n置及警示燈。\n第 十 條　　斜坡道及附屬設施，應由申請人負責維護管理，並不得妨礙人行道上\n行人之通行。\n第十一條　　斜坡道違反原設置目的使用或前條規定者，管理機關應通知申請人限\n期改善，屆期未改善或一年內累計達三次者，管理機關得廢止其核准。經\n管理機關廢止核准之斜坡道，應由申請人於廢止後一個月內，依周邊人行\n道標準恢復原狀，並將恢復原狀後之照片送管理機關備查。\n第十二條　　斜坡道申請核准之原因消滅後，申請人應向管理機關申請廢止斜坡道\n，並於管理機關同意廢止後一個月內，依周邊人行道標準恢復原狀，並將\n恢復原狀後之照片送管理機關備查。\n第十三條　　未依前二條規定恢復原狀者，申請人二年內不得再申請設置斜坡道，\n管理機關並得代為恢復原狀，其費用由申請人負擔。\n第十四條　　本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000421","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 105 年 07 月 28 日","法規名稱":"屏東縣人行道設置斜坡道申請辦法","法規體系":"工務處","發文字號":"屏府行法字第10524898101號 令"},"promulgation_date":"2016-07-28","revision_date":"2016-07-28","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000421","status":"unknown","title":"屏東縣人行道設置斜坡道申請辦法","last_checked_at":"2026-10-06T17:32:10+08:00","last_success_at":"2026-10-06T17:32:10+08:00","verification_status":"fetched","content_hash":"10723153c994d5b5ca65efcd28a3607ec8277c180dfee289db00a08ec18a434a","history":[{"observed_at":"2026-10-06T17:32:10+08:00","content_hash":"10723153c994d5b5ca65efcd28a3607ec8277c180dfee289db00a08ec18a434a","change_kind":"initial","revision_date":"2016-07-28"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"第 1 條\n屏東縣政府（以下簡稱本府）為保障人民生命、身體、財產，確保公共營\n業場所安全，特訂定本辦法。\n第 2 條\n應依本辦法投保公共意外責任險之公共營業場所（以下簡稱公共營業場所\n）規定如下:\n一、公寓大廈管理條例第十七條第一項所規定須投保之場所。\n二、經營舞廳、舞場、酒家、酒吧、特種咖啡茶室、理容業、視聽歌唱業\n、浴室業、旅館業、觀光旅館業、錄影節目帶播映業、電影片映演業\n、遊樂園業、保齡球館、百貨公司、補習班及其他樓地板面積超過五\n百平方公尺或經主管機關指定事業之場所，不論其是否位於公寓大廈\n範內，均列入投保對象。\n第 3 條\n公共營業場所申請設立或非公共營業場所申請變更為公共營業場所之營業\n項目登記時，應檢附其營業場所投保公共意外責任險之保險單，經目的事\n業主管機關及營業登記主管機關審查符合規定，始予許可或登記發證。\n第 4 條\n公共營業場所投保公共意外責任險最低保險金額，不得低於公寓大廈公共\n意外責任保險投保及火災保險費差額補償辦法之規定。\n第 5 條\n公共營業場所應於保險期限屆滿前一個月或保險契約變更五日內，將續保\n或變更保險單送本府備查。\n第 6 條\n本府為稽核公共營業場所投保公共意外責任險情形，得要求保險業者為必\n要之協助，保險業者無正當理由，不得拒絕。\n第 7 條\n公共營業場保險單應置於營業場所，以供本府檢查。\n第 8 條\n公共營業場所應將承保公共意外責任險之保險公司、投保金額及保險期間\n，以顯明文字張貼或懸掛於營業場所內消費者足以辦識之處所。\n第 9 條\n未依第五條、第七條及第八條規定辦理者，除公共營業場所位於公寓大廈\n範圍者，依公寓大廈管理條例有關規定處理外，並送相關單位依有關法令\n規定處理。\n第 10 條\n本辦法施行前，已經許可或登記發證之公共營業場所，應於本辦法施行後\n六個月內，辦妥投保公共意外責任險，並將保險單送本府備查; 期滿仍未\n辦理者，依前條規定辦理。\n第 11 條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:FL041018","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 89 年 08 月 31 日","法規名稱":"屏東縣公共營業場所強制投保公共意外責任險實施辦法","法規體系":"城鄉發展處","發文字號":"屏府秘法字第133046號"},"promulgation_date":"2000-08-31","revision_date":"2000-08-31","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=FL041018","status":"unknown","title":"屏東縣公共營業場所強制投保公共意外責任險實施辦法","last_checked_at":"2026-10-06T17:31:48+08:00","last_success_at":"2026-10-06T17:31:48+08:00","verification_status":"fetched","content_hash":"c0c89ea4c7841783991dc20f71fb8885f323d995c783d0623c6d69c8b63d0196","history":[{"observed_at":"2026-10-06T17:31:48+08:00","content_hash":"c0c89ea4c7841783991dc20f71fb8885f323d995c783d0623c6d69c8b63d0196","change_kind":"initial","revision_date":"2000-08-31"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"一、屏東縣政府（以下簡稱本府）為確保公共設施管線資料之精確性，以\n利道路之維護管理，並使管線   單位之管線施作及圖資更新維護作\n業有所依循，特訂定本要點。\n二、本要點所指用詞定義如下：\n(一) 公共設施管線：電信、電力、自來水、下水道、瓦斯（天然氣）、水\n利、輸油、綜合（寬頻管道）管線等八大類管線。\n(二) 管線單位：指利用各類公共設施管線設施進行業務或營運、維護之事\n業單位。\n(三) 圖資：以測量方式建立公共設施管線資料位相關係，並以紙本或數化\n檔案方式呈現者。\n三、圖資建制規範及屬性依據內政部營建署公告國土資訊系統-公共設施管\n線資料庫標準制度、公共設施管線共同規範資料標準及公共設施管線\n交換資料標準規定為準。\n前項所採用座標系統，平面基準採用內政部公布之TWD97或TWD97（2010）\n二度分帶座標系統，高程基準採用TWVD2001高程系統。\n四、本要點之主管機關為本府，管理機關為各路權單位。\n五、管線單位申請於道路上進行管線設施之新設、更改、遷移、報廢、更\n新及維護等工作時，應調查、測量公共設施管線及其固定設施物，並\n向主管機關申報異動，且依下列規定施作管線異動資料：\n(一) 管線佈設位置應進行測量定位，測量方法可採用全測站（Total Station）\n法，或實施GPS全球衛星定位測量，皆須依「基本測量實施規則」等\n相關作業規定進行施測。\n(二) 管線量測之範圍須涵蓋全部人手孔蓋、固定設施物及管線路徑（包\n括管線起末端、轉折點及分支點）。\n(三) 測量精度：孔蓋中心及固定設施物坐標施測成果容許誤差為正負二十\n公分。管線直線之線形坐標施測成果容許誤差為正負三十公分。管\n線轉折部份之特殊線形測量，其成果容許誤差為正負五十公分。高\n程施測成果容許誤差為正負三十公分。\n(四) 需拍攝施工現場數位相片（以.jpg 檔拍攝，每張相片檔案不得超過\n三百KB），數位相片以能清楚展示施工之範圍、管線佈設完成、回\n填前、測量標記及工程情況為主。拍攝需分為開工前（現況）、施\n工中（含交通維持、道路切割面、挖掘機具、挖掘深度量測、管線\n佈設）及完工後（含回填復原、夯實機具、取樣會簽）等三大類。\n(五) 現場測量完成之資料，需保留原始資料並製作相關表單（如記錄器\n資料、控制點及導線測量成果表、孔蓋及管線測量成果表等），並\n由申請挖掘單位或測量技師簽證保障資料品質。\n六、管線單位施作完成之測量成果資料應進行圖資更新及維護作業，其規\n定如下：\n(一) 將外業測量之成果於內業進行轉換並數化，並以千分之一地形圖進行\n套疊檢核，若施作區無千分之一數值化基本地形圖時，可採用航照\n圖、都市計畫圖或通用版電子地圖，惟參考底圖精度不得低於二千\n五百分之一比例尺，以確認施測成果與地形圖一致。\n(二) 圖資更新數值檔：公共設施管線圖資數值化之電子檔流通格式以ESRI\nArcGIS(shape file)、MapInfo(tab)及GML（Geography Mark-up Language\n，地理標誌語言）為主。以Autodesk AutoCAD dwg檔流通時需另檢\n附屬性對應檔一併提供。\n(三) 圖形檔之每一屬性註記均需能對應在屬性資料庫中之每一屬性資料；\n而屬性資料庫中之每一筆資料也只對應圖形檔中之一個屬性註記。\n(四) 公共設施管線屬性資料檢核作業，可使用程式偵測可能之人為誤差，\n並修正檢核之。\n七、管線單位於施工完成後，需登入屏東縣公路挖掘網-道路挖掘管理系\n統申報完工，依系統之要求填報竣工資料，上傳相關文件資料及照\n片，並由系統提供之圖資更新功能界面上傳管線異動交換資料。上\n傳資料如下：\n(一) 測量成果檔案︰包括記錄器資料、控制點及導線測量成果、孔蓋及\n管線測量成果相關證明資料。\n(二) 施工數位相片檔案。\n(三) 依GML格式製作圖資更新數值檔，須與系統上傳檔案一致。\n(四) 其他本府所規定之相關竣工資料檔。\n八、管線單位須保障圖檔品質，主管機關得予以抽查，如發現資料未上傳\n，或上傳資料有缺漏、空白、錯誤或不符測量精度要求者，得請管線\n單位自行補測或調查後補正圖檔。\n管線單位進行道路挖掘申請作業及圖資更新維護作業時，若違反本要\n點，本府得暫緩管線單位網路申報挖掘申請作業。\n九、軍事或特殊非公眾利益機構設置之管線，得敘明理由函報主管機關同\n意後，免提供圖檔並採自行維護妥處。\n如遇公共危險、天然災害等必要時，前項機關單位得提供特定範圍\n內管線圖檔，以配合救災所需。\n十、公共設施管線資料庫為各管線單位提供圖資數化建立，使用人引用時\n仍應查證，必要時須辦理試挖作業確定。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000159","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 102 年 03 月 13 日","法規名稱":"屏東縣公共設施管線圖資更新及維護作業要點","法規體系":"工務處","發文字號":"屏府工養字第10207361300號函 函"},"promulgation_date":"2013-03-13","revision_date":"2013-03-13","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000159","status":"unknown","title":"屏東縣公共設施管線圖資更新及維護作業要點","last_checked_at":"2026-10-06T17:32:10+08:00","last_success_at":"2026-10-06T17:32:10+08:00","verification_status":"fetched","content_hash":"3b4bdbbee99905bb64977fb6439bc93f8966652c483f96744296119272661b90","history":[{"observed_at":"2026-10-06T17:32:10+08:00","content_hash":"3b4bdbbee99905bb64977fb6439bc93f8966652c483f96744296119272661b90","change_kind":"initial","revision_date":"2013-03-13"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"第一條    屏東縣為加強本縣公園之管理，特制定本自治條例。\n第二條    本自治條例所稱公園，係指設置於都市計畫區內，供公眾遊憩\n之場地而言。\n第三條    本自治條例所稱主管機關在縣為屏東縣政府，在鄉、鎮、縣轄\n市為鄉(鎮、市)公所。\n主管機關於本自治條例之取締違反禁止規定權限，得委任或委\n託其他機關執行。\n第四條    公園應依基地形態及特性分下列各區管理之。但鄰里公園面積\n在二公頃以下及特定性之公園不在此限。\n一、一般區。\n二、遊憩區。\n三、文藝區。\n前項第一款之面積，不得少於公園總面積百分之五十；公園周\n邊適當地點得設置停車場。\n第五條    公園內得視規模性質及環境需要設置下列各項設施。但經主管\n機關核准者，不在此限。\n一、一般區：\n(一)人行道及暢通之排水系統。\n(二)樹木花卉草坪及其必需之花架、花壇、暖室。\n(三)橋樑、假山、池塘、噴水池。\n(四)亭榭、迴廊椅凳、遊艇。\n(五)紀念碑、牌坊。\n(六)垃圾廢棄物收集設備。\n(七)公共廁所及盥洗設備。\n(八)照明設備。\n(九)標準鐘、目晷台。\n(十)公共電話亭、郵筒或視聽設備。\n(十一)必要之附屬設施。\n二、遊憩區：\n(一)一般區所定各目。\n(二)兒童遊戲場設施。\n(三)觀賞性動物籠舍。\n(四)野餐地。\n(五)運動、康樂設備。\n(六)停車設施。\n三、文藝區：\n(一)一般區所定各目。\n(二)博物館。\n(三)美術館。\n(四)音樂廳台。\n(五)集會堂。\n(六)圖書館。\n(七)文物展覽館。\n(八)停車設施。\n公園內有頂蓋之建築物內得設置販賣飲食、照相、書報、畫廊\n、玩具及藝品攤位，使用總面積不得超過建築物總面積三分之一。\n公園內新闢兒童遊戲場設施，得邀請社區兒童行使表意權，並\n由其家長給予適當之協助，以符合實際需求。\n第六條    公園內有頂蓋之建築物其建蔽率之基準如下：\n一、公園面積在五公頃以下者，建蔽率不得超過百分之十五。\n二、公園面積超過五公頃者，其超過部分之建蔽率不得超過百分之\n十二。\n前項所指建蔽率，都市計畫另有規定者，依其規定辦理。\n第七條    公園內各項設施設備得接受私人或機關團體捐獻或依促進民間\n參與公共建設法令規定辦理。但其設計圖樣及裝設位置，應經主管\n機關核准。\n第八條    公園開放供公眾遊憩，以不收費為原則。但為養護、改善或增\n進設施設備，得收取門票，如有不足應由各該主管機關，依據實際\n需要編列預算辦理。\n第九條    凡有下列各款情形之一者，禁止進入：\n一、駕駛各式機動車輛或以任何方式使各式機動車輛進入公園。但\n行動不便者使用電動代步車，不在此限。\n二、酗酒。\n三、攜帶危險物。\n違反前項規定者，處新臺幣五百元以上一萬元以下罰鍰，並命\n其立即離開公園；其經告誡仍有不從者，得按次處罰。\n於公園退縮地上之人行道違規駕駛車輛或停放車輛者，依道路\n交通管理處罰條例處罰。\n第十條    公園內禁止有下列行為：\n一、兜售商品或乞討。\n二、赤身露體或其他不檢行為。\n三、隨地吐痰、便溺或拋棄果皮廢物。\n四、在水池游泳、沐浴或非經許可捕捉魚類。\n五、曝曬衣服。\n六、喧鬧滋事、妨害公共安寧及秩序者。\n七、攀折花木、損壞草坪或損毀公園之設施。\n八、擅自在公園設施上刻劃或張貼。\n九、不依正常方法使用遊樂設施。\n十、逾開放時間仍逗留公園。\n十一、露宿。\n十二、其他經主管機關禁止或限制之事項。\n違反前項規定經制止或命其離開而不聽從者，處新臺幣六百元\n以上六千元以下罰鍰，並得按次處罰。\n第十一條    公園開放時間自主管機關公告，除特殊情形外，星期日及例\n假日不得關閉。\n第十二條    第九條、第十條規定之事項及公園平面圖應於大門口公告之。\n第十三條    於公園內埋 (架) 設地下 (上) 物者，應先向主管機關申請\n核准並繳納修復費，始得施工；其因施工而致各項設施變更現狀\n或損壞時，施工單位應負責修復賠償。\n第十四條    本自治條例自公布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:FL031586","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"修正日期":"民國 108 年 04 月 10 日","公發布日":"民國 93 年 03 月 23 日","法規名稱":"屏東縣公園管理自治條例","法規體系":"工務處","發文字號":"屏府行法字第10812185101號 令"},"promulgation_date":"2004-03-23","revision_date":"2019-04-10","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=FL031586","status":"unknown","title":"屏東縣公園管理自治條例","last_checked_at":"2026-10-06T17:32:09+08:00","last_success_at":"2026-10-06T17:32:09+08:00","verification_status":"fetched","content_hash":"525bcb954b0b4c52eddf1979f5661d32d03608a02d6a1a8b5836f87badf4f95b","history":[{"observed_at":"2026-10-06T17:32:09+08:00","content_hash":"525bcb954b0b4c52eddf1979f5661d32d03608a02d6a1a8b5836f87badf4f95b","change_kind":"initial","revision_date":"2019-04-10"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"一、屏東縣政府為活化各鄉（鎮、市）公所所屬公有零售市場（以下簡稱\n公有市場）、擴大民間參與公有市場經營管理、提升商業水準，特依\n據零售市場管理條例第六條第二項規定，訂定本作業要點。\n二、各鄉（鎮、市）公所所屬公有市場經評估採出租者，以公開標租方式\n辦理；採委託經營者，以公開評選方式辦理。\n公有市場之出租或委託經營，租期以不超過九年為限。\n三、鄉（鎮、市）公所所屬公有市場出租或委託經營之資格與程序：\n（一）以公開標租方式辦理者：符合招標規定之公司或商號均可參加投標\n，其招標程序分資格標、價格標等二階段辦理。\n（二）以公開評選方式辦理者：符合招標規定之公司或商號均可參加投標\n，其招標程序分資格標、技術標、價格標等三階段辦理。其中技術\n標評審部分，由各鄉（鎮、市）公所遴聘相關業務單位人員及府外\n學者、專家五至七人組成，依評審要點辦理。\n四、採公開標租或公開評選方式辦理者，其租金底價參酌各鄉（鎮、市）\n公所攤（鋪）位使用費收費標準，財產出租或市場行情酌定之。\n五、經出租或委託經營之公有市場，經營管理者須於訂約之日起四個月內\n開業經營，開業後無故停業三個月，以違約論。但有特殊理由確實無\n法開業，報經各鄉（鎮、市）公所展延者，不在此限。\n六、公有市場之整修建工程涉及建築執照申請，皆以各鄉（鎮、市）公所\n名義為起造人申請興建，經費由經營管理者負擔，興建完成各鄉（鎮\n、市）公所即無償取得所有權。\n七、公有市場之有關硬體設施及照明、廣播、電器等設備之維修、消防設\n備定期申驗、市場水電費、及使用管理上衍生之相關費用等，皆由經\n營管理者負責。\n八、市場之經營項目依各鄉（鎮、市）公所規定許可之種類設置，經營管\n理者對場內攤商營業應負責管理並約束遵守下列規定：\n（一）不得有妨礙交通、公共安全、社會秩序、居家安寧或有礙環境清潔\n衛生及其他違規之行為。\n（二）不得販賣法令禁止項目、公共危險物品或未經許可之種類。\n（三）應配合本府稽核小組之稽查。\n（四）攤棚架或營業地點四周應保持整潔，不得破壞或污損。\n（五）各鄉（鎮、市）公所通知應配合事項。\n（六）其他經營管理契約規定事項。\n九、經營管理者有下列情形之一，經通知限期改善仍未改善者，得解除或\n終止委託契約：\n（一）逾二個月未繳納權利金或相關費用。\n（二）將市場經營權全部或一部分轉讓。\n（三）違反契約規定事項，情節重大者。\n（四）違反第八點第一項第一款至第三款規定。\n（五）未於營運前就營業場所投保公共意外責任險\n（六）在公有市場外違規設攤營業。\n（七）限制營業消費對象（例如以收取年會費方式，未開放一般大眾消費\n）。\n（八）違反其他法令規定。\n十、履約保證金用途如下，如有不足依法求償：\n（一）抵扣契約所訂之違約金。\n（二）抵繳所積欠之使用費。\n（三）市場欠繳之水、電費或管理上增生之相關費用。\n十一、本作業要點奉核定後施行，修正時亦同。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:FL051929","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 97 年 06 月 04 日","法規名稱":"屏東縣各鄉鎮市公有零售市場出租或委託經營作業要點","法規體系":"城鄉發展處","發文字號":"屏府建工字第0970114251號"},"promulgation_date":"2008-06-04","revision_date":"2008-06-04","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=FL051929","status":"unknown","title":"屏東縣各鄉鎮市公有零售市場出租或委託經營作業要點","last_checked_at":"2026-10-06T17:31:54+08:00","last_success_at":"2026-10-06T17:31:54+08:00","verification_status":"fetched","content_hash":"eec6eb75174326cd3f52e1344c22a85ad7201d2bd4c5f372b6b080b76f7b12d0","history":[{"observed_at":"2026-10-06T17:31:54+08:00","content_hash":"eec6eb75174326cd3f52e1344c22a85ad7201d2bd4c5f372b6b080b76f7b12d0","change_kind":"initial","revision_date":"2008-06-04"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"一、屏東縣政府為活絡各鄉（鎮、市）公所所屬公有零售市場（以下簡稱\n公有市場）營運，依零售市場管理條例第十條第五項規定，訂定本作\n業要點。\n二、公有市場轉讓，除法令另有規定外，悉依本作業要點規定辦理。\n三、本作業要點所指攤（鋪）位係指與鄉鎮市公所訂有契約並有繳納使用\n費之公有市場之店鋪、攤位及臨時攤位。\n四、經鄉（鎮、市）公所列入委外經營之市場，不得辦理轉讓。\n五、受讓人資格如下：\n（一）設籍於本縣。\n（二）須已成年。\n（三）現職非為軍公教人員。\n（四）非經主管機關許可，以一戶一攤（鋪）位為原則。\n六、轉讓應符合下列規定：\n（一）承租使用市場攤（鋪）位二年以上。\n（二）無積欠使用費、清掃費、水、電、管理等費用。\n（三）使用人使用市場攤（鋪）位不得有妨害營業秩序、公共安全、擅自\n增加裝置或設備等違規情形，已改善者不在此限。\n七、使用人應填具轉讓申請書，檢附原核發攤（鋪）位租賃契約書、轉讓\n證明文件、受讓人身分證影本、全戶戶籍謄本、切結書等，經該管市\n場管理員初核，必要時得會同該市場自治會會勘認可後，經所屬鄉（\n鎮、市）公所同意後另行通知訂約。\n八、本作業要點奉核定後施行，修正時亦同。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:FL051930","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"修正日期":"民國 112 年 05 月 23 日","公發布日":"民國 97 年 06 月 04 日","法規名稱":"屏東縣各鄉鎮市公有零售市場攤（鋪）位轉讓作業要點","法規體系":"城鄉發展處","發文字號":"屏府城工字第11220419400號函"},"promulgation_date":"2008-06-04","revision_date":"2023-05-23","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=FL051930","status":"unknown","title":"屏東縣各鄉鎮市公有零售市場攤（鋪）位轉讓作業要點","last_checked_at":"2026-10-06T17:32:01+08:00","last_success_at":"2026-10-06T17:32:01+08:00","verification_status":"fetched","content_hash":"f6a39f3bbf1f0274e415a17dc777707f76754579988d39a81af26ade3fe1b35f","history":[{"observed_at":"2026-10-06T17:32:01+08:00","content_hash":"f6a39f3bbf1f0274e415a17dc777707f76754579988d39a81af26ade3fe1b35f","change_kind":"initial","revision_date":"2023-05-23"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"第 一 章 總則\n一、屏東縣政府為管理監督各鄉（鎮、市）公有零售市場（以下簡稱公有\n市場）自治組織之設置、執行事項、章程、議事程序、設置時間及其\n他應遵行事項，依據零售市場管理條例第十九條第四項規定，訂定本\n要點。\n二、依本要點所組成之自治組織定名為屏東縣各鄉（鎮、市）公有零售市\n場自治組織（以下簡稱本組織）。\n三、本組織為發揮自治功能，溝通使用人與政府間意見，並策勵其自動自\n發，配合政府各項措施，推行政令、消除髒亂、維護秩序、並聯絡使\n用人情感、維護使用人利益為宗旨。\n四、本組織以屏東縣各鄉（鎮、市）公有零市場原有建築物為範圍，組織\n地址暫設屏東縣各鄉（鎮、市）○○路○段○號。\n第 二 章 任務\n五、本組織遵照零售市場管理條例之規定，受主管機關及公有市場管理人\n員之指導監督，執行下列事項：\n（一）市場公共安全之維護。\n（二）市場公共秩序之維持。\n（三）市場環境衛生之管理。\n（四）市場公共設施之維護。\n（五）攤（鋪）位使用人違反市場管理條例規定之舉發及處理。\n（六）市場及其周圍違規攤販之舉發。\n（七）其他主管機關規定及委辦之事項。\n（八）調解使用人與使用人或與使用人客戶之糾紛。\n（九）加強守望相助、謀求使用人福利、及辦理公益等事項。\n（十）辦理市場之營業場所投保公共意外責任險。\n（十一）其他有關市場應興革建議事項。\n本組織執行前項市場管理事項之經費來源如下：\n（一）攤（鋪）位使用人繳交之自治組織管理費。\n（二）接受補助或捐助。\n（三）其他服務收入。\n本組織具當事人能力，應向會員大會負責，並向其報告會務。\n第 三 章 會員\n六、會員入本組織須經幹部會議審查合格，並繳納管理費後方得為本組織\n會員。\n前項管理費數額，由本組織依零售市場管理條例第十二條訂定，並送\n主管機關備查。\n七、會員如經本組織議決應退出組織者，依「零售市場管理條例」相關規\n定，報請向所屬主管機關各鄉（鎮、市）公所終止契約並收回攤（鋪\n）位。\n八、本組織會員為市場內現營業之固定攤（鋪）位使用人。\n九、會員應參加本組織舉行之相關各項會議，並享有發言、表決、選舉及\n被選舉權，更應遵守本組織章程、服從本組織決議。\n十、攤（鋪）位已轉讓他人時，不在市場內經營者，不得為本組織會員。\n十一、會員因故不能參加大會時，得以書面委託代理人出席。但以一人為\n限。\n十二、會員退出組織時，應繳清欠繳之管理費。\n第 四 章 組織及職權\n十三、本組織以會員大會為最高權利機構，會員大會閉會期間，由代表會\n代行職權。\n十四、會員大會之職權如下：\n（一）訂定與變更章程。\n（二）選舉或罷免代表。\n（三）與會員權利義務有關之其它重大事項之議決。\n十五、本組織置理事長、總幹事各一人，理事長、總幹事得由自治組織代\n表於固定攤（舖）位代表中選舉一人擔任，以無記名投票產生。\n十六、本組織得設監察、總務、財務、會務各組，每組置組長、副組長各\n一人，其人選由理事長遴選足堪任者，提經全體代表過半數之同意\n兼任之。\n十七、本組織設幹部會議，由理事長、總幹事、各組之組長、副組長、會\n員代表組成之以執行代表會議決事項。\n十八、本組織設代表會，於會員大會或代表會議，由會員以無記名選舉產\n生之（投票方式地點、日期於會前議決）。\n十九、會員代表會之職權：\n（一）執行會員大會之議決。\n（二）召集會員大會。\n（三）做主管機關與會員溝通的橋樑，並代表轉達。\n（四）選舉罷免理事長、總幹事。\n（五）議決理事長、總幹事之辭職。\n（六）議決理事長及會員代表提議事項。\n（七）議決財務收支事項。\n（八）其它有關自治組織職掌範圍內行使之職權。\n前項各職權之行使以會議行之。\n二十、本組織理事長、總幹事因故不能執行職務時，應指定代表一人代理\n之。\n二十一、本組織理事長因故出缺由總幹事遞補，理事長、總幹事同時出缺\n，會員代表會應於三個月內改選之。\n二十二、本組織理事長、總幹事之任期四年，連選得連任一次。\n二十三、本組織理事長、總幹事、代表及各組組長、副組長均為無給職。\n二十四、本組織得置辦事人員若干人。\n二十五、本組織視實際需要得聘請顧問。\n第 五 章 會議\n二十六、會員大會分定期會議及臨時會議均由理事長召集之。定期會議每\n年召開一次，臨時會議於代表會認為必要或經會員三分之一以上\n之請求，召開之。\n二十七、下列事項之決議應經會員大會出席人數三分之二以上同意行之：\n（一）本組織章程之訂定與修改。\n（二）本組織代表之罷免。\n（三）其它與會員權利義務有關之重大事項。\n二十八、本組織代表任期四年，連選得連任，代表因故出缺達二分之一以\n上，應召開會員臨時大會或代表會議補選之。\n二十九、本組織代表每六個月召開會員代表會議一次，每三個月召開幹部\n會議一次，會議召開應於七日前向所屬主管機關各鄉（鎮、市）\n公所報備，請派員列席指導。\n三十、本組織會議程序如下：\n（一）會議開始：由司儀報告出席人數，並宣佈開會。\n（二）主席報告。\n（三）介紹來賓。\n（四）報告事項：\n1.宣讀上次會議紀錄。（如係第一次會議此項從略）。\n2.報告上次會議決議案執行情形。（無此項報告者從略）。\n3.其他報告。（如有其他各種報告，應將報告之事或報告人，一\n一列舉，無則從略）。\n4.以上各目報告完畢後，得對上次決議之情形，或其他會務進行\n情形，檢討其利弊得失，及其改進之方法。\n（五）討論事項：\n1.前會遺留之事項。（如前會有未完之事項，或指定之事項，須\n於本次會議討論者，應將其一一列舉，如無此種事項者，從略\n）\n2.本次會議預定討論之事項。（應將各預定討論事項一一列舉）\n（六）臨時動議。\n（七）散會。\n三十一、各種會議應由理事長及記錄分別簽署，會議紀錄於會後十五日內\n函報向所屬主管機關各鄉（鎮、市）公所核備，召開各種會議未\n事先報備，其會議紀錄無效。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:FL051931","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 97 年 06 月 04 日","法規名稱":"屏東縣各鄉鎮市公有零售市場自治組織設置作業要點","法規體系":"城鄉發展處","發文字號":"屏府建工字第0970114251號"},"promulgation_date":"2008-06-04","revision_date":"2008-06-04","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=FL051931","status":"unknown","title":"屏東縣各鄉鎮市公有零售市場自治組織設置作業要點","last_checked_at":"2026-10-06T17:31:54+08:00","last_success_at":"2026-10-06T17:31:54+08:00","verification_status":"fetched","content_hash":"8dad8d6bf85c13906f43a55447438dd395bc7de2c71ebca5d01d6211985d3440","history":[{"observed_at":"2026-10-06T17:31:54+08:00","content_hash":"8dad8d6bf85c13906f43a55447438dd395bc7de2c71ebca5d01d6211985d3440","change_kind":"initial","revision_date":"2008-06-04"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"第 一 章 總則\n一、屏東縣政府為管理監督各鄉（鎮、市）民有零售市場（以下簡稱民有\n市場）管理委員會之設置、執行事項、章程、議事程序、設置時間及\n其他應遵行事項，依據零售市場管理條例第二十五條第四項規定，訂\n定本要點。\n二、依本要點組成之管理委員會定名為屏東縣各鄉（鎮、市）民有零售市\n場管理委員會（以下簡稱管理委員會）。\n三、管理委員會為發揮自治功能，溝通使用人與政府間意見，並策勵其自\n動自發，配合政府項措施，推行政令、消除髒亂、維護秩序、並聯絡\n使用人情感、維護使用人利益為宗旨。\n四、管理委員會以屏東縣各鄉（鎮、市）民有零售市場原有建築物為範圍\n，組織地址暫設屏東縣各鄉（鎮、市）○○路○段○號。\n第 二 章 任務\n五、管理委員會應遵照零售市場管理條例之規定，受主管機關及市場管理\n人員之指導監督，執行下列事項：\n（一）市場公共安全之維護。\n（二）市場公共秩序之維持。\n（三）市場環境衛生之管理。\n（四）市場公共設施之維護。\n（五）攤（鋪）位使用人違反市場管理條例規定之舉發及處理。\n（六）市場及其周圍違規攤販之舉發。\n（七）其他主管機關規定及委辦之事項。\n（八）調解使用人與使用人或與使用人客戶之糾紛。\n（九）加強守望相助、謀求使用人福利、及辦理公益等事項。\n（十）辦理市場之營業場所投保公共意外責任險。\n（十一）其他有關市場應興革建議事項。\n管理委員會執行前項市場管理事項之經費來源如下：\n（一）攤（鋪）位使用人繳交之自治組織管理費。\n（二）接受補助或捐助。\n（三）其他服務收入。\n本管理委員會具當事人能力，應向會員大會負責，並向其報告會務。\n第 三 章 會員\n六、會員進入管理委員會須經幹部會議審查合格，並繳納管理費後方得為\n本組織會員。\n七、會員如經管理委員會議決應退出組織者，依「零售市場管理條例」相\n關規定，報請向所屬主管機關各鄉（鎮、市）公所終止契約並收回攤\n（鋪）位。\n八、管理委員會會員為市場內現營業之固定攤（鋪）位使用人。\n九、會員應參加管理委員會舉行之相關各項會議，並享有發言、表決、選\n舉及被選舉權，更應遵守管理委員會組織章程、服從管理委員會決議\n。\n十、攤（鋪）位已轉讓他人時，不在市場內經營者，不得為管理委員會會\n員。\n十一、會員因故不能參加大會時，得以書面委託代理人出席。但以一人為\n限。\n十二、會員退出管理委員會時，應繳清欠繳之管理費。\n第 四 章 組織及職權\n十三、管理委員會以會員大會為最高權利機構，會員大會閉會期間，由代\n表會代行職權。\n十四、會員大會之職權如下：\n（一）訂定與變更章程。\n（二）選舉或罷免代表。\n（三）與會員權利義務有關之其它重大事項之議決。\n十五、管理委員會置理事長、總幹事各一人，理事長、總幹事得由管理委\n員會代表於固定攤（鋪）位代表中選舉一人擔任，以無記名投票產\n生。\n十六、管理委員會得設監察、總務、財務、會務各組，每組置組長、副組\n長各一人，其人選由理事長遴選足堪任者，提經全體代表過半數之\n同意兼任之。\n十七、管理委員會設幹部會議，由理事長、總幹事、各組之組長、副組長\n、會員代表組成之以執行代表會議決事項。\n十八、管理委員會設代表會，於會員大會或代表會議，由會員以無記名選\n舉產生之（投票方式地點、日期於會前議決）。\n十九、會員代表會之職權：\n（一）執行會員大會之議決。\n（二）召集會員大會。\n（三）做主管機關與會員溝通的橋樑，並代表轉達。\n（四）選舉罷免理事長、總幹事。\n（五）議決理事長、總幹事之辭職。\n（六）議決理事長及會員代表提議事項。\n（七）議決財務收支事項。\n（八）其它有關自治組織職掌範圍內行使之職權。\n前項各職權之行使以會議行之。\n二十、管理委員會理事長、總幹事因故不能執行職務時，應指定代表一人\n代理之。\n二十一、管理委員會理事長因故出缺由總幹事遞補，理事長、總幹事同時\n出缺，會員代表會應於三個月內改選之。\n二十二、管理委員會理事長、總幹事之任期四年，連選得連任一次。\n二十三、管理委員會理事長、總幹事、代表及各組組長、副組長均為無給\n職。\n二十四、管理委員會得設辦事人員若干人。\n二十五、管理委員會視實際需要得聘請顧問。\n第 五 章 會議\n二十六、會員大會分定期會議及臨時會議均由理事長召集之。定期會議每\n年召開一次，臨時會議於代表會認為必要或經會員三分之一以上\n之請求，召開之。\n二十七、下列事項之決議應經會員大會出席人數三分之二以上同意行之。\n（一）管理委員會組織章程之訂定與修改。\n（二）管理委員會代表之罷免。\n（三）其它與會員權利義務有關之重大事項。\n二十八、管理委員會代表任期四年，連選得連任，代表因故出缺達二分之\n一以上，應召開會員臨時大會或代表會議補選之。\n二十九、管理委員會代表每六個月召開會員代表會議一次，每三個月召開\n幹部會議一次，會議召開應於七日前向所屬主管機關各鄉（鎮、\n市）公所報備，請派員列席指導。\n三十、管理委員會會議程序如下：\n（一）會議開始：由司儀報告出席人數，並宣佈開會。\n（二）主席報告。\n（三）介紹來賓。\n（四）報告事項：\n1.宣讀上次會議紀錄。（如係第一次會議此項從略）。\n2.報告上次會議決議案執行情形。（無此項報告者從略）。\n3.其他報告。（如有其他各種報告，應將報告之事或報告人，一\n一列舉，無則從略）。\n4.以上各目報告完畢後，得對上次決議之情形，或其他會務進行\n情形，檢討其利弊得失，及其改進之方法。\n（五）討論事項：\n1.前會遺留之事項。（如前會有未完之事項，或指定之事項，須\n於本次會議討論者，應將其一一列舉，如無此種事項者，從略\n）\n2.本次會議預定討論之事項。（應將各預定討論事項一一列舉）\n（六）臨時動議。\n（七）散會。\n三十一、各種會議應由理事長及記錄分別簽署，會議紀錄於會後十五日內\n函報向所屬主管機關各鄉（鎮、市）公所核備，召開各種會議未\n事先報備，其會議紀錄無效。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:FL051932","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"修正日期":"民國 98 年 10 月 29 日","公發布日":"民國 97 年 06 月 04 日","法規名稱":"屏東縣各鄉鎮市民有零售市場管理委員會設置作業要點","法規體系":"城鄉發展處","發文字號":"屏府建工字第0980256765號"},"promulgation_date":"2008-06-04","revision_date":"2009-10-29","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=FL051932","status":"unknown","title":"屏東縣各鄉鎮市民有零售市場管理委員會設置作業要點","last_checked_at":"2026-10-06T17:31:55+08:00","last_success_at":"2026-10-06T17:31:55+08:00","verification_status":"fetched","content_hash":"1683e87ec298a2397b95c5c2daac0c6f6f8ec7b12ef3281fc957da1c10f2d8c9","history":[{"observed_at":"2026-10-06T17:31:55+08:00","content_hash":"1683e87ec298a2397b95c5c2daac0c6f6f8ec7b12ef3281fc957da1c10f2d8c9","change_kind":"initial","revision_date":"2009-10-29"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"一、屏東縣政府為規範各鄉（鎮、市）公所所屬零售市場營業秩序，依據\n零售市場管理條例第五條規定，訂定本要點。\n二、市場零售物品種類如下：\n（一）農產品類：青果、蔬菜、花卉、水產類、禽畜類及其加工品。\n（二）百貨類：服飾、五金製品、玩具、裝飾品、鐘錶、資訊電器、日用\n百貨及貴金屬等用品。\n（三）飲食類：各種冷、熱飲食品及烘焙食品。\n（四）其他類：凡不歸屬以上三類之日常用品，及經各鄉（鎮、市）公所\n核准得進入市場營業之物品或相容營業項目者皆屬此類，如藥品、\n美容美髮、刻印、政府發行之彩券、修改衣服等。\n三、市場界址範圍內面向市街之店鋪，不受分類分區營運之限制。但不得\n經營蔬菜、水產及禽肉、畜肉等生鮮農產品。\n四、市場應按第二點物品分類分區劃定攤（鋪）位，編列號數及裝釘牌號\n。\n五、公有市場攤（鋪）位使用人應利用原有設備營業，不得變更位置、規\n格及營業種類。如需增加裝置或設備時，應事先繪具圖說敘明理由，\n報經各鄉（鎮、市）公所同意後始得添置。\n六、市場之攤位深度與寬度依照市場面積特性訂定，以不超過三點五公尺\n為原則。攤台及供出售之物品應排列整齊，高於地面五十公分以上，\n並不得超越規定界線或佔用通道。\n七、市場各攤位招牌應置於攤台上方，左右不得超過攤台寬度；另有其他\n生財器具或設備高度，以不超過一百八十公分為原則，並不得妨礙市\n場整體觀瞻與通透性。\n八、市場使用人應遵守零售規定，不得從事第二點規定以外之行業。\n九、市場攤（鋪）位因營業需要，得檢附圖說並經申請核准，得聯合經營\n。\n十、本要點奉核定後施行，修正時亦同。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:FL051928","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 97 年 06 月 04 日","法規名稱":"屏東縣各鄉鎮市零售市場攤（鋪）位設置及管理要點","法規體系":"城鄉發展處","發文字號":"屏府建工字第0970114251號"},"promulgation_date":"2008-06-04","revision_date":"2008-06-04","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=FL051928","status":"unknown","title":"屏東縣各鄉鎮市零售市場攤（鋪）位設置及管理要點","last_checked_at":"2026-10-06T17:31:55+08:00","last_success_at":"2026-10-06T17:31:55+08:00","verification_status":"fetched","content_hash":"81ad58ac2e8a64c607b8d028a0f299c2bbfac8af010198d0b431e575c5be1116","history":[{"observed_at":"2026-10-06T17:31:55+08:00","content_hash":"81ad58ac2e8a64c607b8d028a0f299c2bbfac8af010198d0b431e575c5be1116","change_kind":"initial","revision_date":"2008-06-04"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"第 1 條\n屏東縣為落實都市計畫土地使用分區管制，維持民眾生活環境品質，對於\n違反分區管制規定之土地及建築物使用，能依循適當原則予以有效、公平\n之裁處，以提升公信力，並減少裁罰爭議及促成行政目的之達成，特訂定\n本辦法。\n第 2 條\n本辦法用詞定義如下：\n一、違反都市計畫土地使用分區管制之行為：指於都市計畫範圍內土地或\n建築物之使用，或從事建造、採取土石、變更地形，違反都市計畫法\n或內政部、屏東縣政府依都市計畫法所發布之命令者。\n二、裁處機關：指違反都市計畫土地使用分區管制案件所在地之都市計畫\n擬定機關。\n第 3 條\n裁處機關處理違反土地使用分區管制案件，得視違規行為對社會治安、公\n共安全之危害情形，區分如下：\n一、情節重大案件：指警察機關提報並經相關目的事業單位認定情節重大\n之違規場所或其他對社會治安、公共安全有危害之虞，認有立即停止\n違法使用者。\n二、特定行業案件：指視聽歌唱、三溫暖、舞廳、舞場、酒家、酒吧、特\n種咖啡茶室、飲酒店及電子遊戲場。\n三、一般行業案件：指前兩款以外之違規場所。\n第 4 條\n違反都市計畫土地使用分區管制案件之裁處原則如下：\n一、情節重大案件於首次查獲時，處新臺幣十二萬元罰鍰並勒令停止違規\n使用或恢復原狀，按次處罰以每次增額新臺幣六萬元之罰鍰，第三次\n查獲時，依都市計畫法第八十條規定，移送臺灣屏東地方法院檢察署\n偵辦。\n二、特定行業案件於首次查獲時，處新臺幣六萬元罰鍰並勒令停止違規使\n用或恢復原狀，按次處罰以每次增額新臺幣六萬元之罰鍰。\n三、一般行業案件於首次查獲時，處新臺幣六萬元罰鍰並勒令停止違規使\n用或恢復原狀，按次處罰至第三次開始以每次增額新臺幣六萬元之罰\n鍰，持續處罰至停止違規使用或恢復原狀為止。\n前項第一款及第二款，除罰鍰外，於第二次裁處後，並得停止供水、供電\n、封閉、強制拆除或其他恢復原狀之措施。\n裁處對象以處罰行為人為原則並以副本通知所有權人。但執行中如遇有無\n法處罰行為人或處罰行為人已無法達成遏止不法之行政目的時，得敘明理\n由裁處行為人以外之所有權人或管理人。\n前項裁處對象應擇一為之\n第 5 條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000251","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 103 年 04 月 21 日","法規名稱":"屏東縣執行違反都市計畫土地使用分區管制裁處辦法","法規體系":"城鄉發展處","發文字號":"屏府行法字第10311998000號 令"},"promulgation_date":"2014-04-21","revision_date":"2014-04-21","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000251","status":"unknown","title":"屏東縣執行違反都市計畫土地使用分區管制裁處辦法","last_checked_at":"2026-10-06T17:31:50+08:00","last_success_at":"2026-10-06T17:31:50+08:00","verification_status":"fetched","content_hash":"480aececeb4c3b30e1cc4f9d7eae5ef5030f2299d8e7e73036888ed07866d866","history":[{"observed_at":"2026-10-06T17:31:50+08:00","content_hash":"480aececeb4c3b30e1cc4f9d7eae5ef5030f2299d8e7e73036888ed07866d866","change_kind":"initial","revision_date":"2014-04-21"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"第一條    本辦法依建築法(以下簡稱本法)第九十九條之一規定訂定之。\n本辦法未規定事項，適用其他建築法相關法令之規定。\n第二條    本辦法主管機關為屏東縣政府(以下簡稱本府)，執行單位為本府城鄉發\n展處。\n第三條    本辦法實施範圍為屏東縣實施都市計畫以外地區之原住民保留地(以下簡\n稱原住民保留地)。\n適用本辦法建築物或雜項工作物之起造人應具原住民身分。\n第四條    原住民保留地下列建築物或雜項工作物之建築許可，得不適用本法及建築\n技術規則全部或一部之規定：\n一、總樓地板面積不超過四百九十五平方公尺，建築物高度不超過三層樓且不\n超過十點五公尺，僅供一幢一棟一戶具原住民族傳統文化特色、圖騰並供\n住宅使用之建築物。\n二、其他經本府認定具原住民族特色之紀念性且非供公眾使用之建築物或雜項\n工作物，如竹屋、穀倉、瞭望台、涼亭等。\n前項各款之建築物或雜項工作物，由本府原住民處認定之。\n第五條    原住民保留地之建築基地得免受屏東縣畸零地使用規則第三條及第四條規\n定最小寬度及深度之限制。\n第六條    原住民保留地之建築基地申請建造執照或雜項執照，得免臨接建築線。\n前項基地未臨接建築線者，其進出通路及排水應由起造人切結自行處理，\n並依本法第二十六條第二項規定負其責任。\n第七條    第四條第一項規定不適用建築技術規則之事項如下：\n一、私設通路及基地內通路。\n二、有效日照、日照、通風、採光。\n三、建築物停車空間。\n四、綠建築基準規定事項。\n五、建築物無障礙設施。\n六、山坡地建築基地應自建築線或基地內通路邊退縮一點五公尺設置人行步道。\n第八條    第四條第一項各款之建築物或雜項工作物，得免由建築師設計、監造或營造\n業承造。但建築基地位於山坡地範圍內者，於申請建造執照或雜項執照時應檢附\n由建築師依建築技術規則建築設計施工編第十三章規定簽證之檢核表。\n前項建築物或雜項工作物，得免依屏東縣建築管理自治條例第二十九條規定申報勘驗。\n第九條    本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000921","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 115 年 07 月 28 日","法規名稱":"屏東縣實施都市計畫以外地區原住民保留地簡化建築管理辦法","法規體系":"城鄉發展處","發文字號":"屏府民法字第11502051331號令"},"promulgation_date":"2026-07-28","revision_date":"2026-07-28","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000921","status":"unknown","title":"屏東縣實施都市計畫以外地區原住民保留地簡化建築管理辦法","last_checked_at":"2026-10-06T17:31:54+08:00","last_success_at":"2026-10-06T17:31:54+08:00","verification_status":"fetched","content_hash":"4e758ddcf57bd7c8ace50eec90c78b542c894203113bdc01d896b850547c3828","history":[{"observed_at":"2026-10-06T17:31:54+08:00","content_hash":"4e758ddcf57bd7c8ace50eec90c78b542c894203113bdc01d896b850547c3828","change_kind":"initial","revision_date":"2026-07-28"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"第十七條　　本辦法自發布日施行。\n第 1 條\n屏東縣政府（以下簡稱本府）為加速寬頻管道建設、統合市區道路公共設\n施管道配置，有效管理維護寬頻管道，特訂定本辦法。\n第 2 條\n本辦法主管機關為本府，管理機關在鄉（鎮、市）為各鄉（鎮、市）公所\n。\n第 3 條\n本辦法用詞定義如下：\n一、寬頻管道：指用於容納固定通訊網路、有線電視、行動電話、號誌控\n制線或其他經管理機關核准之纜線及其接續設施之構造物。\n二、寬頻管線業者（以下簡稱業者）：係指利用寬頻管道佈設纜線及其\n接續設施者。\n三、子管：可容納業者佈設纜線及其接續設施之直徑為最小之管道設施。\n第 4 條\n業者申請租用寬頻管道佈設纜線及其接續設施，應填具申請書並檢附下列\n文件，向管理機關提出：\n一、行政院新聞局核發之有線電視系統營運許可證、交通部或國家通訊\n傳播委員會核發之行動電話業務特許執照或綜合網路業務建設許可\n證影本三份。\n二、佈設路線圖及使用寬頻管道位置圖，並於圖上標註佈設長度。\n三、施工計畫書，含平面圖、管位配置圖、引上管及設置位置詳圖等之\n施工圖說。\n四、其他本府所規定之相關文件。\n警政署、國防部、本府或本府所屬機關為前項申請、或業者申請案件經本\n府或內政部核定者，免檢附前項第一款文件。\n管理機關受理申請案件，應於三十日內完成審查，經核准使用者，使用人\n應於管理機關規定期限內繳納寬頻管道使用租金（以下簡稱租金）及保證\n金，發給使用許可文件。。\n第 5 條\n申請租用寬頻管道應以子管一管為單位，得獨立或共同租用。\n寬頻管道租賃期間以租賃日起至當年十二月三十一日為一期。業者得於租\n賃期間屆滿二個月前檢附前條第一項文件申請續約。\n第 6 條\n業者年度租賃資料經審查合格者，由管理機關通知限期簽訂契約，並繳納\n租金及保證金；逾期未簽訂契約者，視為棄權。\n申請佈纜案件應於管理機關核定後一個月內開工，並於核定期限內施設完成。\n第 7 條\n使用寬頻管道佈設線路不得影響其他業者管道通訊品質。\n第 8 條\n租用寬頻管道佈設線路，除本府及所屬機關、警政署、國防部或管理機關\n外，應於訂約時一併繳納下列費用：\n一、租金：按月份計算，每一子管每公尺每月以新臺幣一點八元計算。\n二、保證金：依租賃契約租金總額百分之十計算。\n業者應於租賃契約簽訂前將保證金及該期租金一次繳清。\n第 9 條\n道路主管機關因公共工程需要拆遷纜線時，應於一個月前通知租用業者拆\n遷纜線。但因緊急救災需要時，租用業者應於接獲本府通知後立即拆遷纜\n線。\n前項情形管理機關未能提供替代管道供租用致使租用業者無法或不繼續租\n用時，應退還保證金及未到期租金。\n未依第一項規定期限拆遷者，管理機關得逕行拆除。\n第 10 條\n租用業者於開啟人、手孔前，應填具申請書向管理機關申請備查。但有緊\n急災害事故時得先行開啟，並應於災害結束後十二小時內補辦申請。\n前項開啟時間以日間為原則，開啟作業人員應隨身攜帶申請書以備查驗。\n第 11 條\n租用業者有下列情形之一者，為違規使用：\n一、未經申請擅自開啟人、手孔。\n二、於寬頻管道內放置未經核准之物件。\n三、租賃契約租期屆滿未拆除纜線。\n四、鋪設纜線有損管道結構或市容觀瞻。\n五、未於人、乎孔內纜線位置及引上管出處清楚標示租用業者名稱。\n六、將租賃契約之權利全部或一部轉讓或分租於他人。\n違反前項第一款或第五款規定者，管理機關得要求租用業者限期改善，並\n依租賃契約規定辦理。\n違反第一項第二款至第四款規定者，管理機關得通知租用業者限期改善，\n逾期未改善者，得逕行拆除，拆除費用由租用業者負擔，並得由保證金中\n扣抵。\n違反第一項第六款規定者，管理機關得終止租賃契約，保證金不予退還，\n並通知限期拆遷纜線，逾期未拆遷者，得逕行拆除，拆除費用由租用業者\n負擔，並得由未到期租金中扣抵。\n第 12 條\n租用業者其設置於寬頻管道內之纜線及其他設施物，得由管理機關每半年\n或一年邀集租用業者進行檢視，除遇有狀況，應立即向管理機關陳報外，\n應於檢視後七日內將檢查紀錄表報請管理機關備查。其應檢視之項目及相\n關事項，由本府另定之。\n第 13 條\n因使用或施工致寬頻管道設施損害者，應負賠償責任。\n第 14 條\n依本辦法所收取之租金應專款專用，由管理機關作為寬頻管道後續之管理\n維護作業費用及寬頻管道新建增建之工程款，或前述工程之地方配合款。\n第 15 條\n本辦法所需之書表格式，由本府另定之。\n第16條\n已設置寬頻管道設施之區域，應使用該管道佈設纜線，不得於各該路段內\n新增設管道、重複挖掘埋設、於雨水下水道、排水溝側溝內、電桿或其他\n處所附掛。但其他法規另有規定或經主管機關同意者，不在此限。\n先前已附掛纜線者，除前項但書情形外，應於管理機關通知之日起三個月\n內完成遷移；屆期仍未拆遷者，附掛處所之各該目的事業主管機關除禁止\n挖埋管線或佈設纜線外，並得逕為拆除，所造成之損失及相關費用，由業\n者負擔。\n第17條　　本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:FL049606","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"修正日期":"民國 103 年 09 月 11 日","公發布日":"民國 98 年 03 月 16 日","法規名稱":"屏東縣寬頻管道管理辦法","法規體系":"工務處","發文字號":"屏府行法字第10327495701號 令"},"promulgation_date":"2009-03-16","revision_date":"2014-09-11","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=FL049606","status":"unknown","title":"屏東縣寬頻管道管理辦法","last_checked_at":"2026-10-06T17:32:09+08:00","last_success_at":"2026-10-06T17:32:09+08:00","verification_status":"fetched","content_hash":"1211d78b76a915f043363375c4e2eaa8ab6864d1fe888b1a47f16c917a0a077a","history":[{"observed_at":"2026-10-06T17:32:09+08:00","content_hash":"1211d78b76a915f043363375c4e2eaa8ab6864d1fe888b1a47f16c917a0a077a","change_kind":"initial","revision_date":"2014-09-11"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"一、本原則依據建築技術規則建築設計施工編第二百六十三條第二項規定\n訂定之。\n二、建築基地位屬山坡地範圍，符合下列各款情形之一者，得免退縮設置\n人行步道：\n（一）個別興建之農舍。\n（二）建築基地退縮一點五公尺範圍內與周遭地形成上、下邊坡。\n（三）原有合法建築物之增建、改建或修建。\n（四）座落於都市計畫區、重劃區或已核定興辦事業計畫、開發計畫\n、整體開發地區。\n（五）建築基地深度扣除一點五公尺後，未符合屏東縣畸零地使用規\n則第三條所規定之建築基地最小深度。\n（六）建築基地臨接二條以上道路時，得選擇一面退縮一點五公尺設\n置人行步道。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000562","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 107 年 09 月 20 日","法規名稱":"屏東縣山坡地建築基地免退縮設置人行步道認定原則","法規體系":"城鄉發展處","發文字號":"屏府城管字第10774023401號 令"},"promulgation_date":"2018-09-20","revision_date":"2018-09-20","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000562","status":"unknown","title":"屏東縣山坡地建築基地免退縮設置人行步道認定原則","last_checked_at":"2026-10-06T17:32:04+08:00","last_success_at":"2026-10-06T17:32:04+08:00","verification_status":"fetched","content_hash":"0ff61d326ba21a2656c3869ec75646ac98e5d1a3e235c82370179a49e782044a","history":[{"observed_at":"2026-10-06T17:32:04+08:00","content_hash":"0ff61d326ba21a2656c3869ec75646ac98e5d1a3e235c82370179a49e782044a","change_kind":"initial","revision_date":"2018-09-20"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"一、屏東縣政府為防範起造人將本縣都市計畫區內工業區土地或非都市計畫區內丁種\n        建築用地，以類似住宅之設計，出售民眾為住家使用，造成糾紛並影響民眾之權\n        益，特訂定本原則。\n二、類似住宅規劃設計疑慮案件，應提送本縣建造執照預審小組，就興辦事業計畫書\n        圖內容審議，俟審議通過後，始可核發建造執照。\n三、前點興辦事業計畫書圖應載明下列事項：\n（一）興辦事業計畫概要：含申請人資料、基地位址、經營項目、電力、土地使用分\n            區、建蔽率、容積率、層數、建物各層面積、用途、構造、供公眾使用及退縮\n            、綠化等。\n（二）現況照片。\n（三）土地使用分區證明。\n（四）地籍圖及土地登記簿謄本。\n（五）基地位置圖。\n（六）地籍套繪圖。\n（七）建物配置圖。\n（八）各層平面圖。\n（九）各向立面圖。\n（十）其他相關法令事項。\n四、依本原則審議通過之案件，於核發建造執照時，將於建造執照注意事項附表加註\n        下列事項：\n(一)  起造人應依原核定使用類組使用，並將建築物用途詳細告知各承買戶。\n(二)  上開加註事項除應於公寓大廈管理規約草約中明確記載外，於建築物產權移轉\n            時應列入交代及轉載於公寓大廈管理規約。\n(三)  建築物如作核准用途外之使用，即視為違規使用，將依法論處。\n(四)  起造人應依核定用途使用，不得誤導民眾為住宅用途，或有不實廣告、惡意欺\n            瞞等行為；買賣時應列入產權移轉交代，不得隱瞞，如未交代清楚致發生糾紛\n            時，賣方應自負法律責任。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000440","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 106 年 04 月 07 日","法規名稱":"屏東縣工業區類住宅申請建造執照處理原則","法規體系":"城鄉發展處","發文字號":"106年4月7日屏府城管字第10610329100號 函"},"promulgation_date":"2017-04-07","revision_date":"2017-04-07","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000440","status":"unknown","title":"屏東縣工業區類住宅申請建造執照處理原則","last_checked_at":"2026-10-06T17:31:56+08:00","last_success_at":"2026-10-06T17:31:56+08:00","verification_status":"fetched","content_hash":"5eab3a350a98ed8a0e2e08ade58349250cdcfa5c762a293e14839b67ed466402","history":[{"observed_at":"2026-10-06T17:31:56+08:00","content_hash":"5eab3a350a98ed8a0e2e08ade58349250cdcfa5c762a293e14839b67ed466402","change_kind":"initial","revision_date":"2017-04-07"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"屏東縣廣告物管理自治條例部分條文修正草案總說明.doc","url":"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=605&id=FL041014&type=LAW"},{"name":"屏東縣廣告管理自治條例部分條文修正草案條文對照表.doc","url":"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=606&id=FL041014&type=LAW"}],"authority":"屏東縣政府","category":"建築管理相關","content":"第一章 總則\n第 1 條\n屏東縣政府（以下簡稱本府）為維護公共安全、交通秩序、都市景觀並塑\n造地區特色，特制定本自治條例。\n第 2 條\n本縣廣告物管理除法令另有規定外，依本自治條例規定辦理。\n第 3 條\n本自治條例所稱廣告物之種類如下：\n一、招牌廣告：指固著於建築物牆面上之電視牆、電腦顯示版、廣告看板\n、以支架固定之帆布等廣告。\n二、樹立廣告：指樹立或設置於地面或屋頂之廣告牌（塔）、綵坊、牌樓\n等廣告。\n三、張貼廣告：指以張貼、磁吸、彩繪及噴漆等方式固著之各種傳單、海\n報、圖案等廣告。\n四、旗幟廣告：指以插設、懸繫掛等方式固著之各種旗幟、布條等廣告。\n五、遊動廣告：指以遊動宣傳為目的，於車、船、航空器等交通工具設置\n之廣告。但不包跨汽車運輸業所有車輛為於車身附設廣告。\n第 4 條\n廣告物之管理單位如下：\n一、招牌廣告、樹立廣告：本府城鄉發展處。\n二、張貼廣告、旗幟廣告：本府環境保護局。\n三、遊動廣告：本府城鄉發展處。\n第二章 申請須知\n第 5 條\n廣告物除有特別規定外非經許可，不得變更內容、規格、形式、材料或遷\n移地點。但電影廣告內容依電影法經行政院新聞局核准得逕行更換內容。\n第 6 條\n廣告物之設置或內容須先經目的事業主管機關核准者，應依規定先送請該\n管目的事業主管機關核准後，始得申請許可。\n第 7 條\n為強化地區風格，實施都市設計管制地區中廣告物設置應符合該地區都市\n設計規範，並經核准後始得核發許可，並得於區域性都市設計規範中擬定\n地區廣告物設置規範。\n第 8 條\n招牌廣告、樹立廣告之申請，應檢附申請書、許可證費及下列書件向本府\n城鄉發展處申請許可：\n一、設計圖及說明：應載明其內容、規格、材料、形式與建築物或申請基\n地之關係位置。\n二、設置處所所有權證明文件或使用權同意書。\n三、應辦理營利事業登記行業，檢附營利事業登記證正本及影本。\n四、新臺幣一百萬元以上之公共意外責任險保單影本。\n招牌廣告及樹立廣告許可之有效期限為五年，期限屆滿後，原雜項使用執\n照及許可失其效力，應重新申請審查許可或恢復原狀。\n第 9 條\n廣告物有下列情形之一者除依前條應檢附之文件外，另需檢附雜項執照申\n請表及相關文件等申請雜項執照及廣告物許可，並於廣告物依設計圖說裝\n設完成後，請領雜項使用執照及廣告物許可證。\n一、正面式招牌廣告縱長超過一點五公尺者。\n二、側懸式招牌廣告縱長超過六公尺者。\n三、樹立廣告高超過六公尺者。\n四、樹立廣告設置於屋頂高度超過三公尺者。\n第 10 條\n免申請雜項執照之招牌及樹立廣告；其申請許可之審查業務，本府得委託\n民間專業團體協助審查；其相關規定由本府另定之。\n民間專業團體依前項規定受託辦理招牌廣告及樹立廣告協助審查業務，應\n將審查結果送本府核備，合格者發給廣告物許可證。\n第 11 條\n旗幟廣告之申請，應依下列規定向本府環境保護局申請許可：\n一、個人或機關、團體、公司行號等為辦理非營利性活動或公益活動，得\n於一個月前檢附申請表、切結書、廣告物平面圖、內容及活動計畫，\n提出申請，經核准並繳費後依核准內容自行張掛或插設。\n二、旗幟插設或懸繫掛期間以二星期為限，若有特殊需要者得延長之。\n第 12 條\n附加構架或附設廣播設備之專用宣傳車之遊動廣告，應檢附申請書、許可\n證費及下列書件向本府申請。但以張貼、漆繪於交通工具表面之遊動廣告\n，免向本府申請許可：\n一、廣告設計圖：載明其內容、規格、材料、形式及設置位置等相關資料。\n二、申請人身分證明文件影本（身分證影本、公司營利事業登記證影本、\n公司執照影本）。\n三、車輛所有人同意書。\n四、行車執照影本及車身前後照片各一張。\n五、交通工具附加框架做為廣告者，應檢附車輛經檢驗合格變更登記之合\n格證明文件。\n遊動廣告物許可證期限為六個月，申請人應於期限屆滿前一個月，重新申\n請。遊動廣告物內容或設計方式變更時，應於許可證有效期限內申請。\n第 13 條\n招牌廣告、樹立廣告、旗幟廣告、遊動廣告等廣告物應收取廣告物許可證\n規費；其中招牌廣告、樹立廣告每申請案件收取一千元，旗幟廣告、遊動\n廣告每申請案件收取五百元。\n第 14 條\n申請案件應於收到申請書件之日起十日內審查完竣，合於規定者准予設置\n，申請人在三個月內依設計圖說裝設完成後發給許可證否則廢止設置許可\n；不合於規定者，應敘明理由一次通知申請人補正。\n第三章 設置規定\n第 15 條\n廣告物之設置應符合下列規定：\n一、廣告內容不得有妨害公共秩序、善良風俗、違反兒童及少年福利與權\n益或不實之文字圖樣。\n二、不得封閉或堵塞建築技術規則規定設置之各種開口，其構體形狀不得\n妨害公共安全及相關建築法令規定。\n三、不得違反各類場所消防安全設備設置標準有關消防安全設備之規定。\n第 16 條\n下列處所不得設置招牌廣告及樹立廣告：\n一、公路、高岡處所或公園、綠地、名勝、古蹟等處所。但經各目的事業\n主管機關核准者，不在此限。\n二、妨礙公共安全或交通安全處所。\n三、妨礙市容、風景或觀瞻處所。\n四、妨礙都市計畫或建築工程認為不適當之處所。\n五、公路兩側禁建、限建範圍不得設置之處所。\n六、阻礙該建築物各樓層依各類場所消防安全設備標準規定設置之避難器\n具開口部開啟、使用及下降操作之處所。\n七、其他法令禁止設置之處所 。\n第 17 條\n經核准設置之廣告物，應將許可證日期及字號標示於廣告物之左下角、右\n下角或明顯處。\n第 18 條\n招牌廣告及樹立廣告之材質應為堅固不易破碎之耐燃材料或經耐火處理者\n。照明方式採外架照明者，高度在四樓以上廣告物照明燈具及支架突出建\n築牆面以二公尺為限，三樓頂版以下突出建築牆面以一公尺為限。下端距\n地面淨高不得低於四‧六公尺，用電裝置設備應符合屋內線路裝置規則之\n規定。\n第 19 條\n正面式招牌廣告設置應符合下列規定：\n一、五層以下建築物，上端不得高於建築物屋頂女兒牆；六層以上建築物\n，上端以三樓樓版高度為限。\n二、下端不得低於二樓樑底或騎樓正面楣樑底緣。\n三、突出建築物牆面不得逾五十公分。\n四、平房之斜屋頂設置者，高度自屋簷起算一‧五公尺以下。\n五、建築物經合法申請之雨庇、門廊或露台設置者，高度自其底緣起算一\n‧五公尺以下。\n六、建築物之圍牆上端設置者，高度應以同一水平位置為原則不得超過圍\n牆高度二分之一，外緣不得超過圍牆面。\n七、帷幕牆上禁止設置。\n第 20 條\n側懸式招牌廣告之設置應符合下列規定：\n一、上端不得高於建築物露台欄杆或屋頂女兒牆。\n二、突出無遮簷人行道或紅磚人行道部分，下端距地面三公尺以上。\n三、突出車道上方部分，其下端距地面四‧六公尺以上。\n四、厚度五十公分以下。\n五、含固定支撐物、構架及維修設施凸出牆面寬度應在一‧四公尺以下。\n六、帷幕牆上禁止設置。\n七、建築物各層樓分層設置之招牌，應沿柱列中心線單排對齊排列，以符\n合美觀、整齊、安全為原則。\n第 21 條\n騎樓簷下招牌廣告之設置應符合下列規定：\n一、建築物騎樓頂版下不得以懸吊型方式設置招牌廣告，僅得於騎樓內柱\n距地面二．五公尺至二‧八公尺之間設置突出柱面不超過六十公分（\n含構架）之側懸式小招牌。\n二、建築物之挑高騎樓外柱間得設置招牌廣告，其下端距地面三．五公尺\n以上。三、建築物騎樓柱不得設置有廣告性質之材質文字或圖樣。\n第 22 條\n樹立廣告之設置應符合下列規定：\n一、在空地上設置之樹立廣告；其高度不得超過十五公尺，如在騎樓退縮\n地設置應與騎樓線至少保持二‧五公尺淨寬。\n二、突出人行道部分；其下端距地面三公尺以上。\n三、突出車道上方部分；其下端距地面四‧六公尺以上。\n四、在屋頂設置樹立廣告不得影響消防安全或防火避難；其高度應符合建\n築技術規則規定且不得超出屋頂版九公尺。\n五、在屋頂樹立廣告者應依規定設置避雷設備及航空障礙燈。\n六、樹立廣告設置時其最大水平投影面積為二平方公尺以下。\n七、在未開闢完成之公共設施用地上設置時須經目的事業主管機關同意，\n高度以設置地點至地界線之最小距離為限。\n第 23 條\n電視牆、電腦顯示版應符合下列規定：\n一、除住宅區外，臨接道路之外面牆均無窗戶或開口設置者，含固定支撐\n物、構架及維修設施其突出建築物外牆在一公尺以下，且下端距地面\n四‧六公尺以上。\n二、空地或尚未開闢完成之公共設施用地經目的事業主管機關核准者，每\n宗建築基地空地得設置一處，高度以設置地點至地界線之最小距離為\n限，最大水平投影面積十平方公尺以下。\n第 24 條\n氣球臨時廣告應符合下列規定：\n一、飛航管制區內，其高度須經國防部空軍總司令部及交通部民用航空局\n審查通過後始得設置。\n二、高度自地面起算不得高於一百公尺。\n三、球體應標示易於辨認之色彩，並需依據航空障礙物標誌與障礙燈設置\n規範之規定，繫留纜線設置旗狀標記及航空障礙燈。\n第 25 條\n懸掛式之旗幟、布條廣告應符合下列規定：\n一、設置於人行道及安全島路燈桿上之羅馬旗以寬度六十公分高度一百五\n十公分為限，下端應距地面二‧五公尺以上，且道路分隔島寬度大於\n羅馬旗寬度者始得設置，不得逾越至車道上方。\n二、設置地點限以申請單位所在處所或活動地點邊緣起算五十公尺內之範\n圍及核准設置路段自各路口起算十公尺後之分隔島路燈桿上端，且不\n得妨礙公共安全及交通秩序。\n三、旗面材料限用布質，並以燈桿套環固定（如圖一、圖二所示）。\n四、電線桿、號誌桿、標誌桿及設有交通號誌之路燈桿、變電箱、電信箱\n、樹木、牆壁、騎樓、樑柱、橋墩及其他公共設施或法令禁止之處所\n不得設置。\n五、懸掛布條不得橫跨車道及人行道上方。\n六、不得包覆騎樓柱。\n七、十字路口及交通號誌周邊二十公尺內不得設置。\n第 26 條\n插設式之旗幟廣告應符合下列規定：\n一、經核准設置路段且道路分隔島寬度應大於插設旗幟兩倍寬度者。\n二、旗面材料限用布質。\n三、各路口及公車站牌二十公尺範圍內、人行道樹穴、草花花壇內禁止設\n置。\n第 27 條\n遊動廣告應於交通工具表面以張貼、漆繪等方式為之，非經許可，不得附\n加構架或變更交通工具原設計。\n設置遊動廣告之車輛不得停放於主管機關公告禁止停放之路段、時段及時\n間，違者依相關法令查處。\n第四章 廣告物街區更新計畫\n第 28 條\n為形塑特定街區建築與招牌、樹立廣告之整體風格與和諧區域景觀，本府\n得劃定一定街區範圍訂定更新計畫及時程，規範廣告物之形式、材料及設\n置規格、位置等，並編列預算，獎助更新廣告物。\n第 29 條\n地（街）區組織為管理維護其環境景觀，得自行擬定一定街區範圍之建築\n物附設招牌廣告或樹立廣告設置規定，經本府核准後據以施行之。\n第五章 管理維護\n第 30 條\n廣告物申請人、使用人、設置場所所有權人或車輛所有人負有對廣告物維\n護管理之責。廣告物不得有破損、傾頹或朽壞等情形，如有損壞應立即修\n護或拆除，拆除後之廣告物，應自行清理，不得任意棄置。\n前項廣告物申請人、使用人、設置場所所有權人或車輛所有人未善盡廣告\n物維護管理之責，致生危險或傷害他人時，應依法負其責任。\n第 31 條\n樹立招牌廣告申請人依第八條規定申請設置廣告物應投保公共意外責任險\n，其基本保險金額不得低於一百萬元。廣告物申請人依第九條規定申請設\n置廣告物應投保公共意外責任險，其基本保險金額不得低於五百萬元。廣\n告物申請人於申請廣告物許可証時，應檢附公共意外責任險保單影本。\n第 32 條\n已核准之旗幟廣告，若逢颱風警報或強風特報時，申請人應立即自行拆除\n，俟颱風警報解除後再行恢復。但自行拆除期間仍應計入核准期間，不得\n要求延長原核准期限。\n第 33 條\n廣告物因地震、風災、水災、火災等重大事件，而有公共危險之虞，不及\n通知申請人、設置人、使用人或設置場所所有權人清理改善者，得逕予拆\n除。\n第六章 查報、取締及罰則\n第 34 條\n廣告物設置具有下列情形者，應撤銷及廢止其執照、許可證：\n一、許可在案之廣告物，如經依公寓大廈管理條例完成報備之公寓大廈，\n其區分所有權人會議決議不得設置者。\n二、廣告物申請許可提具之相關申請資料，有偽造文書、侵害他人權利等\n情事者。\n三、廣告物非經許可，擅自變更內容、規格、形式、材料或遷移地點，經\n令其限期改善，逾期仍未改善者。\n四、依第二十八條及第二十九條必須配合拆除者。\n第 35 條\n招牌廣告、樹立廣告及遊動廣告違反第五條、第十五條至第二十四條、第\n二十七條及第三十一條者，得處申請人、設置人、使用人或設置場所所有\n權人三千元以上九萬元以下罰鍰，並限期於三十日內依規定改善、補辦手\n續或拆除，逾期仍未依規定遵循者，得按日連續處罰，必要時得代為拆除\n。\n前項招牌廣告、樹立廣告未依法申請核准設立，依建築法規定處罰。\n第 36 條\n張貼廣告、旗幟廣告違反第五條、第十一條、第十五條至第十七條、第二\n十五條及第二十六條者，得逕予拆除或併處申請人、設置人、使用人或設\n置場所所有權人一千二百元以上六千元以下罰鍰。\n第 37 條\n對違規廣告物取締執行遇有阻礙時得洽請有關機關派員到場會同辦理。\n第七章 附則\n第 38 條\n廣告物於本自治條例施行前設置者，應自施行之日起一年內申請許可。\n第 39 條\n本自治條例自公布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:FL041014","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"修正日期":"民國 107 年 05 月 04 日","公發布日":"民國 93 年 08 月 12 日","法規名稱":"屏東縣廣告物管理自治條例","法規體系":"城鄉發展處","發文字號":"屏府行法字第10715829501號 令","立法理由":"屏東縣廣告物管理自治條例部分條文修正草案總說明.doc 屏東縣廣告管理自治條例部分條文修正草案條文對照表.doc"},"promulgation_date":"2004-08-12","revision_date":"2018-05-04","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=FL041014","status":"unknown","title":"屏東縣廣告物管理自治條例","last_checked_at":"2026-10-06T17:31:47+08:00","last_success_at":"2026-10-06T17:31:47+08:00","verification_status":"fetched","content_hash":"0c78a2ad929b6419fe02c807476204b29a6653668d9894079e3f1c5718a9341f","history":[{"observed_at":"2026-10-06T17:31:47+08:00","content_hash":"0c78a2ad929b6419fe02c807476204b29a6653668d9894079e3f1c5718a9341f","change_kind":"initial","revision_date":"2018-05-04"}],"version_count":1,"attachment_hashes":{"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=605&id=FL041014&type=LAW":null,"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=606&id=FL041014&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"一、屏東縣政府(以下簡稱本府)為加強屏東縣建築工程施工管理，以維\n護施工品質，減少施工災害，執行建築法第五十四條、屏東縣建築\n管理自治條例第二十八條規定，特訂定本要點。\n二、本要點適用範圍如下：\n(一)山坡地基地面積達三千平方公尺涉及開挖整地之建築或雜項工\n程。\n(二)建築物高度在五十公尺或樓層在十六樓以上之建築工程。\n(三)地下層開挖之總深度(含基礎)在八公尺以上，或地下二層以上\n之建築物。\n(四)拆除執照工程其拆屋規模達十層以上之建築物。\n(五)經本府認有必要，其他有安全顧慮之建築或雜項工程。\n三、本要點適用範圍之建築或雜項工程領得建造執照或雜項執照後，承\n造人及專任工程人員應於建築工程申報開工前，向符合之審查機關\n或專業團體(以下簡稱審查機構)，申請召開施工計畫書審查會(以\n下簡稱審查會)，並將審查會委員意見及辦理情形，補充於施工計\n畫書內簽證負責。\n四、得辦理之審查機構如下：\n(一)建築師公會。\n(二)土木技師公會。\n(三)結構工程技師公會。\n(四)大地技師公會。\n(五)其他經本府核定之審查機構。\n五、審查機構辦理之規定：\n(一)審查機構受理申請案件後，應於承造人提出施工計畫書等文件\n後十四日內召開施工計畫書審查會，承造人之專任工程人員及\n工地主任應親自與會說明，監造建築師得列席參加。審查機構\n應提供專業意見包括施工技術服務與諮詢、災害預防與應變之\n建議，供承造人、專任工程人員及工地主任參考，並應作成書\n面紀錄。審查機構辦理施工計畫書審查，應遴聘具有相關實際\n工程十年以上經驗之學者專家或專業技師為委員，每次出席審\n查會之委員人數至少三人。\n(二)審查機構應於召開審查會後十日內將審查結果函送申請人。由\n承造人、專任工程人員對審查會委員意見及辦理情形，補充於\n施工計畫書並依第三點規定辦理。\n六、審查完成之案件，應由審查機構將施工計畫書及審查意見表等相關\n資料，並審查機構用印與審查委員簽章後，函送申請人。承造人檢\n附於申報開工文件內，並向本府申報開工備查。監造建築師及專任\n工程人員應監督工程施工時確實依施工計畫書辦理。\n七、建築或雜項工程於施工中辦理變更設計，且變更內容涉及施工計畫\n書變更者，承造人應依第三點規定辦理，並於下次申報勘驗前辦理\n完成。\n八、本要點適用範圍之施工計畫書除應有屏東縣建築管理自治條例第二\n十八條應載明事項外，並應載明下列事項：\n(一)工程概要：結構與施工法概要、地下室擋土工法概要（擋土措\n施之種類、規格、開挖剖面圖）。\n(二)基地環境概況：基地現況及四周基地地下管線及構造物現況調\n查、基地土層分布特性、地下水位。\n(三)地下室施工作業：地下層開挖擋土措施及挖土工程施工及流程\n之安排、地下層開挖之止水及排水措施分析評估、地下層開挖\n之安全觀測系統(儀器、數量、安裝位置圖觀測頻率及管理值\n表)，支撐系統之應力分析及檢討（各階段開挖壁體變形量、\n水平支撐設定壓力及地面沉陷分析）、開挖面之上舉、隆起及\n砂湧、管湧及整體穩定分析、地質改良工法之施工方式及藥液\n成份管制及地下水污染防治（改良範圍）。\n(四)鄰房安全維護措施：開挖深度四倍範圍內之地盤沉陷分析評估\n及鄰房、公共設施現況調查、鄰房保護措施。\n(五)工法說明：施工程序及管制要點說明（如逆打柱承載重核算、\n高空作業人員安全防護措施、地下室照明、通訊設備、地下室\n通風、防火及毒氣體監測防範、鋼骨樓層、樓板進度配合、地\n下室緊急逃生措施、地下室各層樓板混凝土養護、地下室運土\n計畫、垂直墜落物防範措施、鋼結構銲接產生火花防範措施、\n地錨設計、施工拉拔力檢測）。\n(六)審查會意見修正對照表(需標註修改頁碼)。\n(七)施工災變防救措施計畫(含人員組織表)。\n(八)其他應檢附文件：\n1.地基調查報告。\n2.抽水及停止抽水計畫計算。\n3.構台應力分析及設計。\n4.緊急搶修及救災應變方式。\n5.依相關環境保護法令設置之環境保護措施（噪音、振動、空氣\n污染、廢土、廢棄物防制）。\n6.特殊模板應力分析及設計。\n7.地下連續壁或反循環基樁等施工方法之污染防治措施。\n8.施工風險評估報告書。(得參照勞動部職業安全衛生署之「營造\n工程風險評估技術指引」製作之)","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000887","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 114 年 07 月 04 日","法規名稱":"屏東縣建築工程辦理施工計畫書備查作業要點","法規體系":"城鄉發展處","發文字號":"屏府城管字第1140182613號函"},"promulgation_date":"2025-07-04","revision_date":"2025-07-04","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000887","status":"unknown","title":"屏東縣建築工程辦理施工計畫書備查作業要點","last_checked_at":"2026-10-06T17:32:03+08:00","last_success_at":"2026-10-06T17:32:03+08:00","verification_status":"fetched","content_hash":"6436a6fb3392d732a8800ae978aaf098d3ada61e313b47923e46cbc7aeeada0d","history":[{"observed_at":"2026-10-06T17:32:03+08:00","content_hash":"6436a6fb3392d732a8800ae978aaf098d3ada61e313b47923e46cbc7aeeada0d","change_kind":"initial","revision_date":"2025-07-04"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"第一條    本辦法依建築法第七十三條第三項規定訂定之。\n第二條    本辦法之主管機關為屏東縣政府。\n第三條    建築物依本辦法免辦理變更使用執照者；其消防安全事項及室內裝修應\n分別依消防法及其他相關法令辦理，且其使用應符合都市計畫法、區域計畫\n法及其他相關法令規定。\n第四條    建築物依本辦法免辦理變更使用執照者，應依建築物原領使用執照登載\n類組認定。但已辦理變更使用執照者，以最後一次變更使用執照登載類組認\n定。\n第五條    建築物使用類組變更符合下列情形之一者，免辦理變更使用執照：\n一、建築物使用單元位於地面一層、二層，使用類組變更為H-1、H-2、G-2\n、G-3類組，且合計變更使用樓地板面積在三百平方公尺以下。\n二、建築物為地面一層，原使用類組為F-3變更為D-5類組，且合計變更使用\n樓地板面積在二百平方公尺以下。\n三、符合建築物使用類組及變更使用辦法第六條規定具主從用途關係。\n四、建築物使用單元位於地面一層、二層，原使用類組為D-3、D-4變更為\nF-3類組之非營利幼兒園及公立幼兒園，且合計變更使用樓地板面積在\n五百平方公尺以下。\n前項建築物之使用類組應依建築技術規則總則編第三條之三規定認定。\n第六條　　建築物外牆變更符合下列情形之一者，免辦理變更使用執照：\n一、外牆面表面粉刷或裝飾材料變更。\n二、面向六公尺以上道路或永久性空地之外牆變更。\n三、雨遮、屋簷、遮陽板變更。\n前項變更，應符合下列規定：\n一、未變更建築物主要構造。\n二、未計入建築技術規則建築設計施工編第一條第三款、第一百六十二條\n建築面積及樓地板面積。\n三、未影響或妨礙建築技術規則建築設計施工編第三十八條、第四十一條\n、第四十五條、第一百零八條及第一百十條有關欄杆扶手、採光、開\n口及窗台高度、緊急進口、防火間隔。\n四、位於都市設計審議範圍內之外牆變更，應經該委員會審議通過。\n第七條    建築物依本辦法免辦理變更使用執照申請者，除第五條第一項第二款\n外，應以整層或以具一小時以上防火時效之牆壁、樓板、防火門窗等防火\n構造及設備區劃分隔，並有獨立出入口連接走廊、門廳或屋外之使用單元\n。\n第八條    本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000114","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"修正日期":"民國 106 年 09 月 04 日","公發布日":"民國 101 年 06 月 27 日","法規名稱":"屏東縣建築物免變更使用執照辦法","法規體系":"城鄉發展處","發文字號":"屏府行法字第10629768101號 令"},"promulgation_date":"2012-06-27","revision_date":"2017-09-04","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000114","status":"unknown","title":"屏東縣建築物免變更使用執照辦法","last_checked_at":"2026-10-06T17:31:51+08:00","last_success_at":"2026-10-06T17:31:51+08:00","verification_status":"fetched","content_hash":"53cad689c119d3b8f420ecaa3befde9b8693234dafa658cf32bab68a0115463f","history":[{"observed_at":"2026-10-06T17:31:51+08:00","content_hash":"53cad689c119d3b8f420ecaa3befde9b8693234dafa658cf32bab68a0115463f","change_kind":"initial","revision_date":"2017-09-04"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"附表一二.pdf","url":"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=11703&id=GL000874&type=LAW"},{"name":"簡易室裝附表三附表四.pdf","url":"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=11704&id=GL000874&type=LAW"}],"authority":"屏東縣政府","category":"建築管理相關","content":"一、本規範依據建築物室內裝修管理辦法（以下簡稱本辦法）第七條第二項\n規定訂定本規範。\n二、本規範所稱審查機構，係指經內政部指定置有審查人員執行室內裝修審\n核及查驗業務之直轄市建築師公會、縣（市）建築師公會辦事處或專業\n技術團體。\n三、屏東縣政府（以下簡稱本府）將室內裝修之圖說審核及竣工查驗交由審\n查機構辦理，應由雙方訂定契約，明定雙方權利義務。\n四、審查機構執行室內裝修之圖說審核及竣工查驗業務，應依本辦法第七條\n第一項，擬訂作業事項並載明工作内容、收費基準與應負之責任及義務\n，報請本府核備。\n五、審查機構辦理室內裝修圖說查核及竣工查驗業務，應指派具有本辦法規\n定審查人員資格者為之，並應將審查人員按縣（市）別造冊，送本府備\n查。\n六、本府室內裝修圖說審核及竣工查驗作業流程如附表一及附表二，本辦法\n第三十三條（以下簡稱簡易室裝）作業及抽查流程如附表三及附表四。\n七、審查機構圖說查核，應審查下列項目:\n（一）申請書圖文件應齊全，並符合本辦法第二十六條規定。\n（二）室內裝修及使用材料應符合建築技術規則規定。\n（三）防火避難設施、消防設備、防火區劃及主要構造應符合規定，不得\n有破壞或妨害情形。\n八、審查機構竣工查驗，應審核下列項目:\n（一）現場查核應與驗章圖說相符。\n（二）使用之防火材料應檢附檢測合格之證明文件及出廠證明。\n九、審查機構受理室內裝修圖說文件之審查，不合格者，應通知建築物申請人\n於六個月內改正。審查機構受理室內裝修竣工查驗之申請，對於不合格者\n，應通知建築物申請人於三個月內修改，逾期未修改者，審查機構應報請\n本府查明處理。\n十、室內裝修施工期限於圖說審核合格後，由本府通知申請人時一併核定之，\n室內裝修期限以六個月為限。申請人因故未能如期完工時，得申請展期六\n個月，逾期未完工者，許可文件失其效力。\n十一、室內裝修相關書表格式，應遵照內政部訂頒格式。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000874","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"修正日期":"民國 114 年 04 月 01 日","公發布日":"","圖表附件":"附表一二.pdf 簡易室裝附表三附表四.pdf","法規名稱":"屏東縣建築物室內裝修審查作業室項規範","法規體系":"城鄉發展處","發文字號":"屏府城使字第114007568611號 令"},"promulgation_date":null,"revision_date":"2025-04-01","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000874","status":"unknown","title":"屏東縣建築物室內裝修審查作業室項規範","last_checked_at":"2026-10-06T17:32:06+08:00","last_success_at":"2026-10-06T17:32:06+08:00","verification_status":"fetched","content_hash":"aa5ac07a523c825ddc2fba4e8ef9ed10e93250746b8b526752f39982d59642d4","history":[{"observed_at":"2026-10-06T17:32:06+08:00","content_hash":"aa5ac07a523c825ddc2fba4e8ef9ed10e93250746b8b526752f39982d59642d4","change_kind":"initial","revision_date":"2025-04-01"}],"version_count":1,"attachment_hashes":{"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=11703&id=GL000874&type=LAW":null,"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=11704&id=GL000874&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"附表一及附表二.pdf","url":"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=11670&id=FL041016&type=LAW"}],"authority":"屏東縣政府","category":"建築管理相關","content":"第一條    本標準依據屏東縣建築管理自治條例第十八條第二項及第十\n九條規定，訂定之。\n第二條    建築法第二十九條及第八十六條所稱建築物造價，依附表一\n之屏東縣建築物工程造價標準表計算之。\n第三條    前條附表一應依下列方式檢討調整：\n一、至少每二年依行政院主計總處公布當年度營造工程物價指數\n銜接表檢討一次。\n二、前款之檢討，於指數年增率增減幅度累計逾百分之二時，得\n予以調整。\n建築物工程造價調整時，其單價計至百位數，餘數採四捨五\n入方式計算。\n第四條    屏東縣建築物免由建築師設計、監造或營造業承造之一定金\n額工程造價標準表如附表二。\n第五條    本標準自中華民國一百十三年一月一日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:FL041016","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"修正日期":"民國 113 年 08 月 19 日","公發布日":"民國 92 年 05 月 12 日","圖表附件":"附表一及附表二.pdf","法規名稱":"屏東縣建築物工程造價標準","法規體系":"城鄉發展處","發文字號":"屏府民法字第11300941401號令"},"promulgation_date":"2003-05-12","revision_date":"2024-08-19","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=FL041016","status":"unknown","title":"屏東縣建築物工程造價標準","last_checked_at":"2026-10-06T17:31:53+08:00","last_success_at":"2026-10-06T17:31:53+08:00","verification_status":"fetched","content_hash":"cca7dc4449c29b39412234c4981e09ad840aa3420d67df0272d7b63ededec204","history":[{"observed_at":"2026-10-06T17:31:53+08:00","content_hash":"cca7dc4449c29b39412234c4981e09ad840aa3420d67df0272d7b63ededec204","change_kind":"initial","revision_date":"2024-08-19"}],"version_count":1,"attachment_hashes":{"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=11670&id=FL041016&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"附表.DOC","url":"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=7&id=FL041013&type=LAW"}],"authority":"屏東縣政府","category":"建築管理相關","content":"第 1 條\n屏東縣政府（以下簡稱本府）為維護公共安全及處理建築爭議事件，特制\n定本自治條例。\n第 2 條\n本自治條例所稱主管機關為本府。\n第 3 條\n建築工程發生損壞鄰房事件（以下簡稱損鄰事件），依下列方式處理：\n一、主管機關於接獲陳情時應立即通知起造人、承造人、監造人速予查明\n處理。\n二、如有危及公共安全者，應勒令停工並知會起造人、承造人及警察機關\n，並應立即加強保護鄰房安全有效措施。\n三、經勘查結果，因停工致損壞擴大之虞者，應責由起造人、承造人趕工\n於完成礎及地下層工程後停工。並請起造人、承造人即刻採取維護補\n救措施至不影響公共安全為止。\n第 4 條\n監造人於接獲損鄰事件通知即應會同承造人之專任工程人員勘查後，並於\n十日內出具安全鑑定書。\n承造人之專任工程人員於監造人出具安全鑑定書之同時應擬具維護鄰房安\n全措施檢討及執行報告書送主管機關備查。\n如無危及公共安全者，主管機關得依照承造人之專任工程人員所擬具之維\n護鄰房安全措施檢討及執行報告書，准予繼續施工。\n承造人、監造人未依第一項、第二項規定辦理者，主管機關維護公共安全\n得予勒令停工。\n第 5 條\n主管機關得將監造人依前核送之安全資料委託具有公信力之相關團體或學\n術機構鑑定，鑑定費用由起造人、承造人負擔。鑑定機關未提出報告前暫\n依監造人之安全鑑定書辦理。\n第 6 條\n起造人、承造人應就損鄰事件主動與受損戶協調修復賠償事宜，倘雙方協\n調未能達成協議者，受損戶得要求起造人、承造人委託具有公信力之相關\n團體或學術機構做損壞情形及承造人委託具有公信力之相關團體或學術機\n構做損壞情形及協議時，得申請當地鄉（鎮、市）公所調解委員會調解或\n本府建築爭議評審嬡員會評，調解不成，則逕循司法途解決。\n第 7 條\n就前二條之鑑定報告有異議者，應自覓具公信力之鑑定單位鑑定；其費用\n由異議人自行負擔。\n第 8 條\n損鄰事件經協調未達成協議，且受損鄰房經定安全無虞；其鑑估之修復費\n用，經依損壞鄰房補償費用提存法院數額表（如下表）以受損方名義提存\n法院者，起造人、承造人具結後得依法請領使用執照。\n第 9 條\n損壞責任如無法認定係因施工損壞或鄰房房屋邊緣線與工程開挖線間之水\n平距離大於開挖深度四倍以上者，應由異議人自覓鑑定單位鑑定並於二個\n月內具損壞鑑定報告，鑑定費用由異議負擔。\n如因案情複雜、戶數眾多者，得由鑑定單位向建管單位申請延長一個月。\n異議人不依前項辦理者，主管機關視為撤回異議。\n第 10 條\n起造人、承造人委託具有公信力之相關團體或學術機構鑑定或鑑估，如受\n損戶經連續通知三次不接受鑑定、鑑估者，則由受委託之鑑定或鑑估單位\n出具報告書送請主管機關核備，並副知受損戶撤銷列管後，起造人得依法\n申領使用執照；其雙方爭執則另循司法程序解決。\n第 11 條\n逾屋頂樓版申報勘驗日一個月始提出損鄰事件者，不適用本自治條例，由\n爭議雙方循司法途徑解決。\n第 12 條\n主管機關為解決損鄰事件及減少糾紛，得要求起造人、承造人於開工時提\n出鄰房現況鑑定報告書，以界定將來損壞之責任。如現況鑑定時拒絕會同\n者，嗣後如有損事件陳情者應檢具鑑定報告書辦理。\n第 13 條\n本自治條例規定事項得委由鄉（鎮、市）公所辦理。\n第 14 條\n本自治條例自公布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:FL041013","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 91 年 08 月 26 日","圖表附件":"附表.DOC","法規名稱":"屏東縣建築物施工中發生公共安全事件處理自治條例","法規體系":"城鄉發展處","發文字號":"屏府秘法字第0910132287號"},"promulgation_date":"2002-08-26","revision_date":"2002-08-26","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=FL041013","status":"unknown","title":"屏東縣建築物施工中發生公共安全事件處理自治條例","last_checked_at":"2026-10-06T17:31:45+08:00","last_success_at":"2026-10-06T17:31:45+08:00","verification_status":"fetched","content_hash":"7e15ed2cdcb3158c22d64af8c3b025e0fbc1ecd9cb8ca0079ab41812aa8fd2af","history":[{"observed_at":"2026-10-06T17:31:45+08:00","content_hash":"7e15ed2cdcb3158c22d64af8c3b025e0fbc1ecd9cb8ca0079ab41812aa8fd2af","change_kind":"initial","revision_date":"2002-08-26"}],"version_count":1,"attachment_hashes":{"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=7&id=FL041013&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"一、屏東縣政府(以下簡稱本府)為落實建築工程施工管理，以確保本縣\n公共交通、公共安全、公共衛生及促進市容觀瞻，特訂定本要點。\n二、建築物申報開工後，承造人應於施工現場之主要進出口豎立公告牌\n，並於現場備有建造執照、核准圖樣、施工計畫書、申請道路使用\n範圍圖等複印本以便查驗。\n三、承造人使用道路者，應將路旁水溝加蓋，以免砂石流入溝內，其有\n流入者應即加以清理保持暢通。\n四、建築剩餘土石方(如磚塊、沙土、木屑、石頭、竹或木頭等)，不得\n放置路旁或散落水溝內。但不影響環境衛生者，得於建築基地內，\n妥為保存，清除時應運往指定收容處理場所處理，取得簽證，於申\n請核發使用執照時交回本府審查。\n五、二樓頂板完成後一個月內，應維持人行道之暢通，不得繼續堵塞。\n但設有安全走廊者不在此限。\n安全走廊之淨寬至少一點三公尺，淨高至少二點四公尺，其使用材\n料應為鋼鐵料、木料或金屬料，須堅固安全美觀，其頂面應以鋼板\n設置(厚度一點五公厘以上)，頂面側緣應設置二十公分寬以上之封\n板以防止物料墜落，且地面應平整。\n六、建築工程施工場所四周明顯處及主要出入處應設置安全警示燈、警\n告標誌，並應於可能發生事故之處所增設危險標誌，並設置一點一\n公尺以上之安全護柵。其利用垃圾滑槽等清運殘碴者，應以帆布或\n木板加設防護裝置。因連續壁施工所產生之污泥，並應設置足夠容\n納之污泥沈澱處理設施或機械處理設備，於污泥凝結沈澱後，運往\n指定地點傾倒。\n七、易產生噪音、震動或散播灰塵致影響鄰宅住戶之建築施工，應改採\n低噪音及減少震動之施工工法。\n八、建築工程施工中有污損周圍道路之虞者，應以混凝土或瀝青混凝土\n等材料暫時加以舖平並清除泥渣，以維施工環境之清潔。搬運棄渣\n、棄土等車輛之輪胎應清洗後，始得駛離工地。\n九、挖掘地下室應依核准圖說施作地下室支撐。靠近鄰房挖土時，承造\n人應指派專人隨時檢查現場地質狀況及地下水情形，並應適時研判\n，隨時修改擋土方法或擋土設備，以免附近道路與鄰房發生崩塌沉\n陷情形。必要時應先加強安全措施，俟地質穩定後再行繼續開挖。\n十、承造人於工地內搭蓋供工人操作、休息用之臨時工寮，應有適當之\n衛生設備。\n十一、建築物施工場所設置之安全圍籬，應依營建工程空氣污染防制設\n施管理辦法及勞工安全衛生檢查單位之相關規定辦理。\n十二、施工中承造人不得將建築材料及機具堆置於圍籬外之道路或人行\n道上，以免妨害交通及公共安全。\n十三、因建築之必要需使用道路者，應應向道路主管機關提出申請。\n十四、七層以上或高度二十一公尺以上之建築物施工時，鷹架應以鋼管\n或鋼料搭設。但施工場所情況特殊或因未臨接道路而無礙於公共\n安全者，於經主管建築機關核准後，不在此限。\n十五、二層以上建築物施工或拆除時，施工鷹架外緣距離建築線或地界\n線不足二點五公尺，及五層以上建築物施工或拆除時，均應設置\n符合勞工安全衛生相關規定之防止物料向外飛散或墜落措施。\n十六、汛期或颱風來臨前，本府得通知承造人等進行工地相關檢查。\n十七、地震震度達四級以上地區之施工中建築物，於地震前七日內有澆\n置混凝土行為者，起造人、承造人、監造人應針對該樓層結構安\n全檢測，並共同出具之安全證明書或專業公會鑑定報告送本府備\n查。\n十八、施工作業時間，除澆置混凝土、連續壁施工、安全措施及防災、\n救災等必須持續施工者外，避免於每日晚上十點至次日早上七點\n間施工。\n十九、承造人應於施工現場之圍籬或明顯位置設置施工告示牌。\n建築物之工程告示牌基本內容為工程名稱、起造人、設計人、監\n造人、承造人、工程概要、施工起迄時間、工地主任（負責人）\n姓名與電話、建築地址或地號、建造執照、治安通報專線等。\n二十、承造人應維護施工環境之美觀，並得適度加強綠美化，以改善市\n容觀瞻。\n二十一、建築物施工場所之鄰近房屋及周圍道路、現有巷道、排水溝渠\n、下水道與人孔、給水管與止水栓、瓦斯管、消防栓、電力電\n纜、電話線、軍用通訊電纜、交通號誌、公車站牌、電桿、行\n道樹、人行地下道、陸橋、公共護欄、路燈等公共設施應詳加\n調查，並與有關單位協調養護、防護、迂迴施工、臨時移設等\n對策。\n二十二、建築物施工中不得損及道路、溝渠等公共設施，如經通報有損\n壞情事，應立即向公共設施主管機關洽詢損壞修復事宜，並將\n該結果報本府備查。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000288","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"修正日期":"民國 114 年 04 月 18 日","公發布日":"民國 103 年 09 月 01 日","法規名稱":"屏東縣建築物施工中管制要點","法規體系":"城鄉發展處","發文字號":"屏府城管字第1140107979號 函"},"promulgation_date":"2014-09-01","revision_date":"2025-04-18","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000288","status":"unknown","title":"屏東縣建築物施工中管制要點","last_checked_at":"2026-10-06T17:32:03+08:00","last_success_at":"2026-10-06T17:32:03+08:00","verification_status":"fetched","content_hash":"2ef442b739e94cf23a908a4e249307fa8cc332e2f98f92b1d6aa129eb7dab168","history":[{"observed_at":"2026-10-06T17:32:03+08:00","content_hash":"2ef442b739e94cf23a908a4e249307fa8cc332e2f98f92b1d6aa129eb7dab168","change_kind":"initial","revision_date":"2025-04-18"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"第一條    屏東縣為收取建築物設置無障礙設施與設備勘檢費及替代改善計畫審\n查費，並依規費法第十條第一項規定，特訂定本標準。\n第二條    本標準之主管機關為屏東縣政府(以下簡稱本府)。\n第三條    起造人申請新建或增建公共建築物者，應於申請時繳納無障礙設施及\n設備設置之勘檢費新臺幣八千元；現場勘檢後由本府核定退件後，再申請\n者以新件論計。\n第四條    新建或增建公共建築物未符合無障礙設施及設備設置規定而依身心障\n礙者權益保障法提具(替代)改善計畫者，應於本府通知期限內繳納審查費\n新臺幣一萬二千元。\n第五條    非公共建築物自行提出勘檢申請或提具替代改善計畫者，其收費標準\n準用前二條規定。\n第六條    依本標準繳納之勘檢費或審查費，於本府勘檢或審查前自行撤回申請\n者，得申請無息退還。\n第七條    依本標準收取之勘檢費及審查費，應納入屏東縣公共建築物無障礙設\n施與設備改善基金。\n第八條    本標準自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000547","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 105 年 05 月 06 日","法規名稱":"屏東縣建築物設置無障礙設施與設備勘檢費及替代改善計畫審查費收費標準","法規體系":"城鄉發展處","發文字號":"屏府行法字第10515099600號 令"},"promulgation_date":"2016-05-06","revision_date":"2016-05-06","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000547","status":"unknown","title":"屏東縣建築物設置無障礙設施與設備勘檢費及替代改善計畫審查費收費標準","last_checked_at":"2026-10-06T17:31:50+08:00","last_success_at":"2026-10-06T17:31:50+08:00","verification_status":"fetched","content_hash":"1e6e5ab10495efd5f3854133b1a706441dddf23bb81aeb44e86afa3aab508622","history":[{"observed_at":"2026-10-06T17:31:50+08:00","content_hash":"1e6e5ab10495efd5f3854133b1a706441dddf23bb81aeb44e86afa3aab508622","change_kind":"initial","revision_date":"2016-05-06"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"一、屏東縣政府〈以下簡稱本府〉為要求申請案之建築物達到公共安全避難逃生最基本\n需求，特訂定本原則。\n二、本縣建築物申請變更使用執照時，其違建部分應於竣工查驗前按下列規定自行拆除\n或改善完竣後，始得准其變更使用。\n(一)地面層出入口有阻礙或封閉依建築技術規則設計施工編（以下簡稱本編），第九十\n條規定出入口寬度之違建者（不包括遮雨棚架等無礙逃生之設施）。\n(二)屋頂平臺違反本編第九十九條所列舉應設置屋頂避難平臺之違建者，應拆除部分違\n建使其避難面積達建築面積二分之一；如以走道連接避難平臺者，走道有效寬度須\n大於樓梯寬度。\n(三)直通樓梯範圍內有阻礙本編法定樓梯寬度之違建者。\n(四)阻塞緊急進口之違建者。\n(五)申請變更使用部分，屬於申請人所有權範圍內之防火間隔、防火巷之違建者，其外\n牆及外牆之開口應以一小時防火時效材料施作改善或拆除。\n三、變更使用範圍內，合法房屋將原有外牆拆除於法定空地或室內空間違建者，其已拆\n除之外牆應以原材料或混凝土（12公分厚以上）、磚牆（24公分厚以上）或經中央\n主管機關審核認可之具一小時以上防火時效材料復原，復原後並應符合緊急進口相\n關規定。\n四、違建部分案情特殊，經本府勘查認定妨害公共安全者，得視個案情形簽報辦理。\n五、第二點、第四點以外之違建，則依違章建築處理辦法規定續處，免要求併案拆除。\n六、本原則自奉核後施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000100","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 100 年 01 月 21 日","法規名稱":"屏東縣建築物變更使用執照違建部分處理原則","法規體系":"城鄉發展處","發文字號":"屏府城管字第1000023035號"},"promulgation_date":"2011-01-21","revision_date":"2011-01-21","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000100","status":"unknown","title":"屏東縣建築物變更使用執照違建部分處理原則","last_checked_at":"2026-10-06T17:31:55+08:00","last_success_at":"2026-10-06T17:31:55+08:00","verification_status":"fetched","content_hash":"10b6dea9dc83be9f533b8e2c3143ff12c7bc3f3d2c375d03f23bf78cd4606cca","history":[{"observed_at":"2026-10-06T17:31:55+08:00","content_hash":"10b6dea9dc83be9f533b8e2c3143ff12c7bc3f3d2c375d03f23bf78cd4606cca","change_kind":"initial","revision_date":"2011-01-21"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"20180705屏東縣建築物附建防空避難設備或停車空間繳納代金及管理使用辦法造價係數.pdf","url":"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=1163&id=GL000545&type=LAW"}],"authority":"屏東縣政府","category":"建築管理相關","content":"第一條    本辦法依建築法第一百零二條之一第二項規定訂定之。\n第二條    建築物依規定應附建防空避難設備，但有下列各款情形之一者，起造人得\n申請繳納代金，免予附建：\n一、防空避難設備面積未達三十平方公尺。\n二、建築基地地面以下流砂層或岩石層，開挖地下室確有困難。\n三、原有建築物辦理變更使用需增建防空避難設備。\n四、其他因特殊情形施工困難，由起造人或所有權人提具經專業技師公會或建\n築師公會評估證明文件認定之。\n第三條    建築物依規定應附設停車空間，但有下列各款情形之一者，起造人得申請\n繳納代金，免予附設：\n一、建築基地面積在三百平方公尺以下。\n二、深度或寬度任一邊未達十公尺，應留設騎樓地區，其深度或寬度應以扣除\n騎樓地部分後之尺寸為準。\n三、停車空間之車位數在五輛以下。\n四、建築基地因都市計畫限制車輛無法通行進入。\n五、建築基地臨接之道路坡度超過一比六。\n六、建築物因增建、改建或變更用途需增設停車空間。\n七、其他經屏東縣政府(以下簡稱本府)會同有關機關勘查認為不宜設置。\n第四條    本辦法發布施行前，原有建築物所附設停車空間，但有下列各款情形之一\n者，所有權人得申請繳納代金，免予附設：\n一、設置於地面層零星之室內停車空間，每棟在二輛停車位以下。\n二、設置於地下層之停車空間，因建築物增設必要之機電設備致停車位無法使\n用。\n第五條    應繳納之代金，其計算公式如下：\n一、防空避難設備：代金總額＝〔（造價係數×建築物法定工程造價【元／平\n方公尺】）＋（建築基地當期公告現值【元／平方公尺】×建築基地面積\n【平方公尺】）／建築物總樓地板面積【平方公尺】〕×防空避難設備面積\n【平方公尺】\n二、停車空間：代金總額＝〔（造價係數×建築物法定工程造價【元／平方公\n尺】）＋（建築基地當期公告現值【元／平方公尺】×建築基地面積【平\n方公尺】／建築物總樓地板面積【平方公尺】）〕×二十五×車位數。\n前項造價係數由本府訂定之。\n第六條    申請防空避難設備或停車空間繳納代金，應併同建造執照或變更使用執照\n向本府提出，並於領取使用執照或變更使用執照時繳交。\n第七條    依本辦法繳納之代金，由本府統籌集中興建或購置停車空間及防空避難設\n備，並依預算程序辦理。\n第八條    依本辦法興建完成或購置之防空避難設備或停車空間，其所有權登記為屏\n東縣所有，並由本府指定管理機關負責或委託管理維護。\n第九條    本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000545","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 107 年 06 月 06 日","圖表附件":"20180705屏東縣建築物附建防空避難設備或停車空間繳納代金及管理使用辦法造價係數.pdf","法規名稱":"屏東縣建築物附建防空避難設備或停車空間繳納代金及管理使用辦法","法規體系":"城鄉發展處","發文字號":"屏府行法字第10720144601號 令"},"promulgation_date":"2018-06-06","revision_date":"2018-06-06","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000545","status":"unknown","title":"屏東縣建築物附建防空避難設備或停車空間繳納代金及管理使用辦法","last_checked_at":"2026-10-06T17:31:51+08:00","last_success_at":"2026-10-06T17:31:51+08:00","verification_status":"fetched","content_hash":"44e7b87a33f30da38dfdeaad34844ec6896ccf61c5eda3f4e191c7905a70fa83","history":[{"observed_at":"2026-10-06T17:31:51+08:00","content_hash":"44e7b87a33f30da38dfdeaad34844ec6896ccf61c5eda3f4e191c7905a70fa83","change_kind":"initial","revision_date":"2018-06-06"}],"version_count":1,"attachment_hashes":{"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=1163&id=GL000545&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"附表.DOC","url":"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=6&id=FL026602&type=LAW"}],"authority":"屏東縣政府","category":"建築管理相關","content":"第　一　條　　本自治條例依建築法 (以下簡稱本法) 第一百零一條規定制定之。\n第　二　條　　建築基地面臨計畫道路、廣場、市區道路、公路或合於本自治條例\n規定之現有巷道者，得申請指定建築線。\n申請指定建築線者，應繳納規費，視申請基地面臨建築線所應指示\n（定）樁位而定，基本樁數二支應繳新臺幣四百五十元，每增加一支增\n繳新臺幣一百元。\n屏東縣政府（以下簡稱本府）指定建築線應自收件次日起七日內辦\n理完竣，並將指定圖發給申請人。但面臨道（公）路須會同道路主管機\n關辦理者，為十五日。\n道路或廣場開闢完成，其境界線經本府確定為建築線者，得公告免\n申請指定建築線，其有變更時應即公告修正。\n非都市土地之建築線指示（定）業務得授權委由當地鄉（鎮、市）\n公所辦理核發。\n都市計畫區建築線指示（定）業務得授權委由當地鄉（鎮、市）公\n所辦理核發。免申請建築線之建築執照申請時，仍應檢附土地使用分區\n證明，且應標明都市計畫附帶相關事項。\n第　三　條　　申請指定建築線應填具申請書，並檢具下列文件：\n一、地籍套繪圖：應描繪一個街廓以上，並應標明建築基地之地段、地\n號、方位、基地範圍及鄰近之各種公共設施、道路之寬度。\n二、基地位置圖：應標出基地位置、附近道路、機關學校或其他明顯建\n築物之相關位置。\n三、現況圖：應標明地形、鄰近現有建築物、道路及溝渠，其比例尺不\n得小於地籍圖之比例尺。\n四、非都市土地應檢附土地登記簿謄本；都市計畫區之土地，本府應要\n求檢附土地使用分區（或公共設施用地）證明書。\n五、基地位置現況照片。\n六、面臨現有巷道基地應另檢附該巷道現況照片。\n前項第一款一個街廓範圍如經本府同意者，得縮小其範圍。\n第　四　條　　本自治條例所稱現有巷道，指符合下列情形之一者：\n一、供公眾通行，為公有土地或具有公用地役關係之巷道。\n二、未計入法定空地之私設通路符合下列情形之一者：\n（一）經土地所有權人出具經公證人認證之同意供公眾通行之土地使\n用權同意書。\n（二）捐贈供公眾通行，並依法完成土地登記。\n三、本自治條例制定公布施行前，曾指定建築線之現有巷道，經本府\n認定無礙公共安全、公共衛生、公共交通及市容觀瞻者。\n四、現有通路旁已有編釘門牌房屋二戶以上，且其門牌編釘或戶籍登\n記已逾二十年。\n五、土地登記謄本之地目登記為道。\n前項第一款所稱供公眾通行之巷道，應由本府依法就其寬度、使\n用性質、使用期間、通行情形及公益上需要認定之。\n第一項第一款所稱供公眾通行具公用地役關係，申請人應提供相\n關證明文件。\n第　五　條　　面臨現有巷道之基地，其建築線之指定，應依下列規定辦理：\n一、巷道為單向出口長度在四十公尺以下，雙向出口在八十公尺以\n下，寬度不足四公尺者，以該巷道中心線為準，兩旁均等退讓\n，以合計達到四公尺寬度之邊界線作為建築線；巷道長度超過\n上開規定者，兩旁亦應均等退讓，以合計達到六公尺寬度之邊\n界線作為建築線。\n二、地形特殊不能通行車輛者，前款巷道之寬度得分別減為三公尺\n及四公尺。\n三、建築基地正面臨接道路，側面或背面臨接現有巷道者，於申請\n指定建築線時，應一併指定該巷道之邊界線，其因而退讓之土\n地，得以空地計算。\n四、現有巷道之寬度大於四公尺或六公尺者，仍應保持原有之寬度。\n五、工業區內建築基地面臨現有巷道之寬度不足八公尺者，應以該巷\n道中心線為準，兩旁均等退讓，合計達到八公尺寬度之邊界線作\n為建築線。\n六、建築基地與都市計畫道路間夾有具公用地役關係之現有巷道，得\n以現有巷道之邊界線作為建築線，並納入都市計畫道路。\n依前項第一款退讓土地，不得以空地計算。\n都市計畫區內巷道之長度應自與計畫道路連接之出口起算。\n第　六　條　　建築基地未臨接建築線者，不得建築。但有下列情形不在此限：\n一、在都市土地農業區及非都市土地農牧用地、林業用地、養殖用地\n、鹽業用地，申請自用農舍而無臨接道路者。\n二、都市土地農業區及非都市土地農牧用地、林業用地、養殖用地、\n鹽業用地，申請農業設施經政府農業單位認為符合農業生產需要\n者，得免臨接建築線。\n三、在休閒農業區之土地，除住宿設施、餐飲設施、自產農產品加工\n（釀造）廠及農產品與農村文物展示（售）及教育解說中心外，\n其他經農業主管機關核准容許設置之休閒農業設施，得免臨接建\n築線。\n四、依經濟部公告嚴重地層下陷地區之產業轉型計畫專區，經本府核\n准得免臨接建築線。\n前項未臨接建築線者，應出具相關證明文件，其通行問題由申請人\n切結自行負責。\n第一項未臨接建築線者，申請建造執照應檢附相關證明文件。\n第　七　條    現有巷道之改道或廢止，應向本府申請，本府應將廢止或改道之路\n段公告一個月，徵求異議。\n依前項申請改道者，除應檢附新設巷道位置圖外；並應檢附新設巷\n道土地所有權人出具供公眾通行之同意書或捐獻土地為道路使用之同意書。\n現有巷道改道後之新巷道寬度應合於第五條規定。\n新巷道自開闢完成供公眾通行之日起，其土地所有權人不得違反供公\n眾通行之使用，原巷道土地所有權人於新巷道開闢通行並出具經公證人認\n證之同意供公眾通行之土地使用權同意書或將新巷道土地完成捐獻移轉登\n記手續之日起，得申請廢止原巷道。\n第　八　條    現有巷道之認定、改道或廢止發生疑義時，由本府現有巷道認定評議\n小組審議之；其組織由本府另定之。\n第　九　條    建築基地與建築線接連部分之最小寬度，規定如下：\n一、建築基地不得小於屏東縣畸零地使用規則所定基地最小寬度之規定。\n二、畸零地寬度不足，依規定不必補足者，不得小於二公尺。\n三、以私設通路連接建築線者，不得小於建築技術規則所定私設通路之最\n小寬度。\n第　十　條    本府應於測定建築線後，在指定建築線之文件上註明下列事項：\n一、樁位。\n二、基地所屬之使用分區用地。\n三、主要計畫及細部計畫發布實施日期文號。\n四、騎樓寬度。\n五、道路寬度、標高，截角規定及牆面線。\n六、禁、限建規定。\n七、建蔽率、容積率、退縮規定。\n八、都市計畫附帶規定事項。\n九、其他與設計有關之各項資料。\n第 十一 條    建築物之排水溝渠與出水方向應配合該地區之排水系統設計，必\n要時得由本府規定溝渠構造規格與型式。\n第 十二 條    申請建造執照除依本法規定外，並應檢附下列文件：\n一、土地權利證明文件：\n(一)最近三個月內申請之土地登記簿謄本。\n(二)最近三個月內申請之地籍圖謄本。\n(三)土地使用同意書（限土地非自有者）。但已依法申請建築所\n留設之私設通路，其面臨原通路之建築物申請增建、改建、\n修建或拆除重建者，免再出具原私設通路之使用同意書。\n(四)土地登記謄本記載之地上權、查封、典權，應取得地上權人\n、債權人及典權人之同意書。\n二、工程圖樣：\n（一）基地位置與現況圖：載明基地位置、方位、地形、四週道\n路、附近建築物情況（含層數及構造）、都市計畫土地使\n用分區或區域計畫土地使用編定。\n（二）地盤圖：載明基地之方位、地號及境界線、建築線、臨接\n道路名稱及寬度、建築物之配置。\n（三）配置圖：申請建築物之位置、騎樓、防火間隔、空地、基\n地標高、排水系統及排水方向。但一樓平面圖標示明確者\n，得免附。\n（四）各層平面圖及屋頂平面圖：註明各部分之用途及尺寸。\n（五）建築物立面圖：各向立面圖應以座向標示之。\n（六）剖面圖：註明建築物各部尺寸及所用材料。\n（七）總剖面圖：自基地地面至建築物各部高度、層高、建築物總\n高、屋頂突出物高度、各項退縮建築線、相關地形斷面圖、\n基地與鄰地騎樓現況橫向及縱向斷面圖。\n（八）各層結構平面圖。\n（九）結構詳圖：載明部斷面大小及所用材料。\n（十）設備圖：載明建築物主要設備之配置。\n三、結構計算書：\n（一）二層以下跨度超過六公尺者之鋼筋混凝土樑或木構造建築物者。\n（二）跨度超過十二公尺之鋼架（含鋼骨）構造者。\n（三）三層以上建築物。\n四、地質鑽探報告書：建築技術規則建築構造編第六十四條規定之建築\n物或因基地地質異狀者經本府認有必要者，應檢附地質鑽探報告書。\n五、建築線指示（定）圖。\n六、其他有關文件：\n（一）使用共同壁者，應檢附協定書。\n（二）起造人委託建築師辦理申請建築執照者，應檢附委託書。\n（三）依農業用地申請興建自用農舍者，應依農業用地興建農舍\n辦法檢附相關文件。\n（四）增建者應檢附合法房屋證明。\n（五）辦理空地套繪所需之地籍套繪圖。\n（六）基地現況及四周彩色照片。\n（七）依有關法令規定應檢附之文件。\n前項第一款第一、四目之文件，能以電子處理達成，查詢者免提出。\n第 十三 條    申請雜項執照，除依本法規定外，並應檢附下列文件：\n一、土地權利證明文件：\n（一）最近三個月內申請之土地登記謄本。\n（二）最近三個月內申請之地籍圖謄本。\n（三）土地使用同意書（限土地非自有者）。\n二、工程圖樣：位置圖、地盤圖、平面圖、立面圖與剖面詳細圖。\n三、建築線指示（定）圖。\n四、其他有關文件：\n（一）使用共同壁者，應檢附協定書。\n（二）起造人委託建築師設計及請領建築執照者，應檢附委託書。\n（三）現況四周彩色照片。\n（四）依有關法令規定應檢附之文件。\n開發山坡地範圍內之土地申請雜項執照者，除應依前項規定辦理外\n，並應依山坡地建築管理辦法及相關之規定辦理。\n第 十四 條    申請使用執照除依本法規定外，並應檢附下列文件：\n一、建築物竣工彩色照片 (各向立面、屋頂突出物、法定空地、防\n火間隔、天井及停車空間等)。\n二、建築物申請新建者，應檢附門牌證明。\n三、地盤圖、位置圖、面積計算表、竣工平面圖及立面圖。\n四、依有關法令規定應檢附之文件。\n第 十五 條    申請拆除執照除依本法規定外，並應檢附下列文件：\n一、建築物之位置圖及平面圖。\n二、建築物權利證明文件或其他合法證明。\n三、拆除施工計畫書。\n四、部分拆除之剩餘建物平、立面圖說。\n申請拆除圖說經審查合格後，申請人依核定圖說施工，竣工時\n應檢附拆除後照片及原核定圖說副本後，始得發給拆除執照。\n拆除許可期限為一年，並自領取或圖說審查合格之次日起算。\n前項許可因故不能於期限內完工時，應敘明理由申請展期一次\n；展期不得逾六個月，逾期得廢止之。\n第一項拆除許可併同變更使用執照申請之案件，得展延至變更\n使用執照有效期限；併同建造執照申請之案件，經本府核定者，得\n展延至建造執照有效期限。\n第 十六 條    供公眾使用建築物應於建築執照申請書及建築執照上註明之。\n第 十七 條    申請變更使用執照，除依本法第七十四條規定檢附相關文件外\n，並應依下列程序辦理：\n一、變更用途說明書 (圖)經審核符合規定者，核定其圖說及施工\n期限，並通知申請人。\n二、依圖說施工完竣，經檢查合格者，發給變更使用執照。\n前項第一款施工期限為一年，如因工程鉅大或情形特殊者，\n施工期限為二年。\n前項申請人因故不能如期完成，得申請展期。但展期不得超\n過六個月，逾期核准圖說作廢。\n第 十八 條    本法第十六條規定得免由建築師設計、監造或營造業承造之\n建築物或雜項工作物如下：\n一、工程造價在一定金額以下者。\n二、建築物之建築面積在四十五平方公尺以下，簷高在三點五公尺以下者。\n三、依規定准予興建之自用農舍，其總樓地板面積在一百六十五平方\n公尺以下且高度不超過八公尺或二層樓以下者（集村興建之農舍除外）。\n四、經本府核准之農作產銷設施、林業設施、自然保育設施、水\n產養殖設施、畜牧設施及綠能設施，其簷高在七公尺以下，\n樑跨度在六公尺以下或屋架跨度在十二公尺以下。\n五、涼棚、容量二公噸以下之水塔、本身高度在六公尺以下之瞭\n望臺、廣告牌、廣播塔或煙囪、或高度在二公尺以下之圍牆\n、建築所需駁崁或挖填土石方者。\n六、雜項工作物之承載物頂端高度在九公尺以下，其載重量未逾\n二公噸者。\n前項第一款工程造價之一定金額由本府定之。\n第一項各款之建築物分次申請建築時，其金額、面積、高\n度、容量等數額應累計計算。\n第 十九 條    前條建築物之造價估算標準，由本府定之。但雜項工作物\n之造價，應由建築師覈實估算，由本府核定。\n第 二十 條    建築工程使用道 (公) 路者，應依下列規定辦理：\n一、使用道路寬度：\n（一）道(公)路寬度在四公尺以下者，不得使用。\n（二）道(公)路寬度超過四公尺未達六公尺者，使用寬度不得超過一公尺。\n（三）道(公)路寬度六公尺以上未達十二公尺者，使用寬度不得超過一．五公尺。\n（四）道(公)路寬度十二公尺以上者，使用寬度不得超過二公尺。\n二、申請使用道 (公) 路，應於開工前填具申請書，檢附使用範圍\n圖，由本府核定。\n三、使用道 (公) 路應依核准使用之範圍設置安全圍籬。使用人行\n道者，應在安全圍籬外設置有頂蓋之行人安全走廊。\n四、經核准使用道路之範圍，仍應依本法第六十四條規定辦理。\n第二十一條    面臨計畫道路之建築基地，其騎樓、庇廊或無遮簷人行道之設\n置，除都市計畫說明書另有規定外，得由本府依據地方實際情形訂\n定設置標準。\n第二十二條    本府對於面臨河湖、廣場、景觀道路等地帶申請建築，有退讓\n必要者，得會同有關機關劃定退讓之界線。\n沿道 （公） 路交叉口建築者，除都市計畫書圖已明示退讓界\n線外，應依附表規定退讓。\n第二十三條    承造人應於施工現場前顯明位置豎立施工內容告示牌，並將建\n造執照、雜項執照、拆除執照等核准圖樣留置施工地點。\n前項告示牌材料、規格、設置方式及告示內容，由本府另定之。\n建築工程之廣告物應載明建築執照字號。\n第二十四條    已領有建築執照尚未開工或正在施工中之建築物，因都市計畫之\n變更而有妨礙變更後之都市計畫者，本府應通知起造人於六個月內，\n辦理變更設計。但依下列規定完成之樓層，得按其核准範圍申領使用\n執照：\n一、已完成基礎工程者，准其完成至一層樓為止。\n二、超出一層樓並已建成外牆一公尺以上或建柱高達二點五公尺以上\n者，准其完成至各該樓層為止。但僅豎立鋼筋不得視為建柱。\n第二十五條    依本法申報開工核定建築期限時，以三個月為基數，另依下列規定\n增加日數：\n一、地下層每層四個月。\n二、地面各樓層每層三個月。\n三、雜項工作物三個月。\n前項建築期限未達一年者，以一年計。\n第一項建築期限，因構造特殊、施工困難、工程鉅大或情形特殊\n，顯有增加日數之必要者，經本府審查通過後，酌予增加。\n第二十六條    依本法第五十三條、五十四條作廢之建造執照或雜項執照，本府\n應於執照作廢後三十日內，派員實地勘查，其擅自建築者，應依本法\n第八十六條規定處理。\n第二十七條    本法第五十四條所稱之開工，係指起造人會同承造人、監造人依\n本法規定向本府申報開工，並在現地實施拆除原有房屋、整地、挖地\n、打樁或從事安全措施等工程。但搭建工寮或設圍籬而無實際工作者\n不得視為已開工。\n第二十八條    建築物施工計畫書之內容應包括下列事項：\n一、承造人之專任工程人員、工地負責人、勞工安全衛生管理人員\n之姓名、地址、連絡電話。\n二、工程概要。\n三、施工程序及預定進度。\n四、施工方法及作業時間。\n五、施工場所佈置各項安全措施、工寮、材料堆置及加工場之圖\n說及配置。\n六、施工安全衛生措施、施工安全衛生設備、工地環境之維護、\n建築廢棄物處理及剩餘土石方處理。\n前項施工計畫書於實施都市計畫以外地區或偏遠地區內，非\n供公眾使用或四樓以下之建築物，本府得依據當地情形簡化其內容。\n第二十九條    建築工程必須申報勘驗部分，除因特殊工法應依報經核定之施工\n計畫書辦理外，依下列施工階段辦理：\n一、放樣勘驗：建築物放樣後，挖掘基礎土方前。\n二、地坪勘驗：建築物基礎或地坪完成。\n三、各層樓板勘驗：各層樓板完成。\n各項申報勘驗前應由承造人及其專任工程人員先行勘驗，其申報\n文件並應會同監造人查核簽章後，於該階段工程施工完成後送達本府\n，於送達之次日方得繼續施工。但有緊急施工之必要者，監造人或承\n造人得監督先行施工，並於三日內報請備查。依本自治條例第十八條\n規定免由營造業承造及建築師監造之建築物，由起造人自行依核定圖\n樣施工，免予施工勘驗。\n放樣及地坪勘驗，有關建築物之位置，臨接建築線部分，以本府\n所定建築線為準，如有不符，由監造人、承造人負責，土地界址由土\n地所有權人申請主管地政機關鑑定之，地界未經鑑定致越界建築者，\n由起造人負責。\n本府得指定必須申報勘驗部分，應經由本府派員勘驗合格後，方\n得繼續施工。其勘驗方式及勘驗項目由本府另定之。\n勘驗紀錄應與建築執照申請書件及工程圖說一併保存，至該建築\n物拆除或損毀為止。\n第 三十 條    工程進行中變更設計者，應依本法第三十九條前段規定提出申\n請。但地下層部分因防範緊急危險，得於施工後七日內補辦手續。\n第三十一條    建築物之竣工尺寸，高度誤差在百分之一以下，未逾三十公分\n；各樓層高度誤差在百分之三以下，未逾十公分；其他各部分尺寸\n誤差在百分之二以下，未逾十公分者，視為符合核定計畫。但臨接\n騎樓線或指定牆面線部分，其誤差不得超過五公分。\n第三十二條    建築物竣工時，起造人或承造人應將損毀之道路、溝渠、路燈\n、都市計畫樁等公共設施或公有建築物修復，並將損毀之行道樹補\n植，私設通路路面舖設完竣；搭蓋之圍籬、遮板、鷹架、工棚、樣\n品屋及須拆除之舊有建築物拆除完竣、清理一切廢棄物及疏通水溝\n後，始得申請核發使用執照。\n第三十三條    本法第七十條所稱主要設備，係指下列各項：\n一、消防設備。\n二、避雷設備。\n三、污物、污水或其他廢棄物處理設備。\n四、昇降設備。\n五、防空避難設備。\n六、附設之停車空間。\n七、通風設備。\n第三十四條    供公眾使用之建築物之檢查簽證及申報結果，本府得依本法第\n七十七條規定辦理抽 (複) 查。\n第三十五條    本法第九十九條第一項規定之建築物，起造人應依下列規定辦\n理後，敘明不適用本法全部規定或一部份之條款及其理由申請本府備查：\n一、依文化資產保存法指定或登錄之紀念性建築物，應照原有形貌\n保存，有修復必要者，其修復之工程計畫，應先經主管機關許可。\n二、海港、碼頭、鐵路車站、航空站等範圍內雜項工作物之建造，\n並經各該主管機關許可。\n三、臨時性建築物之設置期限由主管機關核定之，並以六個月為限\n。但經目的事業主管機關簽報本府核定或其他法規另有規定者\n，得延長使用期限。使用期限屆滿時，應無條件自行拆除。\n興辦公共設施，在拆除合法建築物基地內改建或增建建築之管\n理辦法，由本府另定之。\n第一項第一款至第二款建築物，經核定不適用本法全部之規定\n者，仍應將工程圖樣說明書及建築期限申報本府備查。\n第三十六條    建築物符合下列各款情形之一者，申請補發使用執照，得免由\n建築師及營造業簽章：\n一、建築物於本法或實施都市計畫以外地區建築管理辦法施行前，\n已建築完成。\n二、臨時性建築物在本自治條例制定公布施行前建築完成，領有臨\n時使用許可文件，且無核定使用期限。\n依前項各款申請補發使用執照者，應檢附下列文件：\n一、使用執照申請書。\n二、建築線指示 (定) 圖。\n三、土地權利證明文件。\n（一）最近三個月內土地登記謄本。\n（二）最近三個月內地籍圖謄本。\n（三）土地使用同意書 (土地自有者免附) 。\n四、房屋權利證明文件。\n五、基地位置圖、地盤圖、建築物之平面圖及立面圖。\n六、建築師或專業技師出具結構安全鑑定書。\n七、房屋完成日期證明文件。\n八、其他有關文件。\n第三十七條    中華民國六十年十二月二十二日本法修正公布生效前已領有建\n造執照之建築物，申請補發使用執照者，應檢附下列文件，並免由\n建築師及營造業簽章：\n一、使用執照申請書。\n二、原領建造執照及核准之設計圖說。\n三、施工中有辦理中間勘驗者，檢附勘驗紀錄，未辦理者，檢附建\n築師安全鑑定書。\n四、同時變更起造人名義者，應附土地及房屋權利證明文件。\n五、房屋完成日期證明文件。\n六、其他有關文件。\n前項第三款無勘驗紀錄者，應依本法第八十七條規定予以處罰。\n第三十八條    供公眾使用之建築物，依前二條規定申請補發使用執照者，\n其出入口、走廊、樓梯及消防設備應符合建築技術規則及消防法\n規之規定。但樓梯及走廊如利用原有樓梯修改構造，得不限制其\n寬度；增設之安全梯免計入建築面積及容積。\n第三十九條    依本自治條例第三十六條及第三十七條規定申請補發使用執\n照之建築物，其建蔽率、高度應符合都市計畫法及有關法令之規\n定。但建築物在適用本法前或實施都市計畫以外地區建築管理辦\n法施行前已建築完成或符合原核准建造執照者，不在此限。\n前項建築物之用途，應符合都市計畫法及有關法令之規定。\n但在都市計畫發布前已取得營利事業許可者，不在此限。\n第 四十 條    未領有使用執照接用水電申請證明業務，得授權委託建築物\n所在地鄉（鎮、市）公所辦理核發。\n第四十一條    本自治條例自公布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:FL026602","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"修正日期":"民國 103 年 08 月 26 日","公發布日":"民國 91 年 04 月 08 日","圖表附件":"附表.DOC","法規名稱":"屏東縣建築管理自治條例","法規體系":"城鄉發展處","發文字號":"屏府行法字第10325815301號 令"},"promulgation_date":"2002-04-08","revision_date":"2014-08-26","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=FL026602","status":"unknown","title":"屏東縣建築管理自治條例","last_checked_at":"2026-10-06T17:31:47+08:00","last_success_at":"2026-10-06T17:31:47+08:00","verification_status":"fetched","content_hash":"8777c66b6d7fbcd1d0c578a6eddd4ddd0d9264d6a1944c406f8dec9d1dca4075","history":[{"observed_at":"2026-10-06T17:31:47+08:00","content_hash":"8777c66b6d7fbcd1d0c578a6eddd4ddd0d9264d6a1944c406f8dec9d1dca4075","change_kind":"initial","revision_date":"2014-08-26"}],"version_count":1,"attachment_hashes":{"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=6&id=FL026602&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"第 1 條\n屏東縣政府（以下簡稱本府）為加強本縣建築開發業之管理，建立建築開\n發生產秩序、提升建築物品質、保護消費者權益並協助建築管理業務之推\n行，特制定本自治條例。\n第 2 條\n本縣建築開發業之管理，依本自治條例之規定，本自治條例未規定者，適\n用其他有關法律之規定。\n第 3 條\n凡於本縣轄區從事建築投資及綜合開發之建築開發業者，應加入本縣建築\n開發商業同業公會（以下簡稱同業公會）。\n第 4 條\n建築開發業者申請建造（雜項）執照暨申報開工時應向同業公會報備登記\n，並檢具該公會年度會員證書影本。\n第 5 條\n同業公會應對業者入會、退會及本縣轄區投資建築及開發案之區位、總樓\n地板面積、工程造價、開工時間、完工期限等，每半年彙報本府。\n第 6 條\n本縣建築開發商業同業公會對於建築開發業涉有海砂屋、輻射屋或施工品\n質重大瑕疵之紀錄者，應主動通知監造人加強監工並負監造責任。\n第 7 條\n同業公會應協助辦理本縣轄區建築開發所發生之糾紛處理、紓困及獎懲等\n事項，應將成果報本府備查。\n第 8 條\n本自治條例自公布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:FL052459","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 98 年 01 月 15 日","法規名稱":"屏東縣建築開發業管理自治條例","法規體系":"城鄉發展處","發文字號":"屏府行法字第0980014030號"},"promulgation_date":"2009-01-15","revision_date":"2009-01-15","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=FL052459","status":"unknown","title":"屏東縣建築開發業管理自治條例","last_checked_at":"2026-10-06T17:31:46+08:00","last_success_at":"2026-10-06T17:31:46+08:00","verification_status":"fetched","content_hash":"9c6457f689c0ffbc3dba33b9f2138577ee461d8e38e2d27e6fcea7ebce8afad7","history":[{"observed_at":"2026-10-06T17:31:46+08:00","content_hash":"9c6457f689c0ffbc3dba33b9f2138577ee461d8e38e2d27e6fcea7ebce8afad7","change_kind":"initial","revision_date":"2009-01-15"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"附圖一屏東縣建築執照協助審查作業流程圖.pdf","url":"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=11667&id=GL000845&type=LAW"}],"authority":"屏東縣政府","category":"建築管理相關","content":"一、屏東縣政府（以下簡稱本府）為推動便民措施，提高建築執照核發效率\n，落實建築師簽證制度，並符合行政與技術分立之精神，特訂定本要點\n。\n二、本府辦理建築執照審查時，除依審查程序辦理外，得預先參與屏東縣建\n築師公會（以下簡稱建築師公會）建築執照協助審查作業。\n三、建築師公會受理申請案件檢視文件齊全後排序初審，俟建築師公會審查\n完成並做成紀錄後，除規定審查項目之書圖文件外，其餘建築師簽證負\n責之書圖文件彌封於圖袋內，轉送本府掛號申請，協助審查流程詳如「\n屏東縣建築執照協助審查作業流程圖」（附圖一）。\n四、建築師公會受理協助審查範圍如下：\n（一）建造執照：非都市土地且屬非供公眾使用。\n（二）雜項執照：非都市土地且屬非供公眾使用。\n（三）拆除執照：非都市土地。\n（四）依建築主管機關授權範圍。\n五、建築師公會協助審查人員資格，應符合下列各款規定：\n（一）登記建築師開業三年以上及受委託擔任建築物設計人或監造人業\n務案件達十件以上。\n（二）未受建築師法申誡二次以上之懲戒處分。\n（三）無建築師法第四條第一項規定不得充任建築師情形。\n六、協助審查地點為本府指定場所，設計建築師須親自或委託代理人到場說\n明核對圖說以利協助審查進行。\n七、建築師公會辦理本要點所需訂定相關作業須知、審查文件、收費標準、\n協助審查人員清冊，由建築師公會訂定後報本府備查，有修正時亦同。\n八、本要點如因執行上有窒礙難行時，本府得修正或廢止本作業要點。\n九、本要點自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000845","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 113 年 07 月 12 日","圖表附件":"附圖一屏東縣建築執照協助審查作業流程圖.pdf","法規名稱":"屏東縣建造執照及雜項執照協助審查作業要點","法規體系":"城鄉發展處","發文字號":"屏府城管字第11300540870號函"},"promulgation_date":"2024-07-12","revision_date":"2024-07-12","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000845","status":"unknown","title":"屏東縣建造執照及雜項執照協助審查作業要點","last_checked_at":"2026-10-06T17:32:03+08:00","last_success_at":"2026-10-06T17:32:03+08:00","verification_status":"fetched","content_hash":"7bad02c64cd100f27b10823b27dee09aa50ffd4fb88fe3dbe866456718d0d463","history":[{"observed_at":"2026-10-06T17:32:03+08:00","content_hash":"7bad02c64cd100f27b10823b27dee09aa50ffd4fb88fe3dbe866456718d0d463","change_kind":"initial","revision_date":"2024-07-12"}],"version_count":1,"attachment_hashes":{"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=11667&id=GL000845&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"一、屏東縣政府(以下簡稱本府)為簡化建築物建造執照經屏東縣建造執\n照預審小組以下簡稱預審小組）審定合格案件，變更設計時之審查\n程序，特訂定本原則。\n二、建築物建造執照經預審小組審定合格之案件，於申請變更設計時，\n經建築師檢討符合下列各款規定者，得免送預審小組審查及認可：\n(一)開放空間部分：\n1.開放空間位置或型態變更幅度未超過百分之十。\n2.開放空間面積增減幅度未超過百分之五或五十平方公尺且符\n合相關法令規定。\n3.綠化面積或喬木數量減少未超過百分之十。\n(二)建築物量體部分：\n1.原核准之最大允建總樓地板面積或容積樓地板面積增減幅度\n未超過百分之三或一百平方公尺。\n2.建築物高度減少，或建築物高度增加未超過原核准高度百分\n之十。\n3.汽車、機車停車位數量增減各十部以內且符合相關法令規定。\n(三)不牴觸該案原審查會議紀錄內容。\n三、變更項目影響重大致生疑慮者，仍應提會審查。\n四、本原則得視實際執行情形修正之。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000599","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 108 年 05 月 15 日","法規名稱":"屏東縣建造執照預審審定合格案件辦理變更設計免送建造執照預審小組審議原則","法規體系":"城鄉發展處","發文字號":"屏府城管字第10817108100號 函"},"promulgation_date":"2019-05-15","revision_date":"2019-05-15","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000599","status":"unknown","title":"屏東縣建造執照預審審定合格案件辦理變更設計免送建造執照預審小組審議原則","last_checked_at":"2026-10-06T17:31:57+08:00","last_success_at":"2026-10-06T17:31:57+08:00","verification_status":"fetched","content_hash":"7cc843137c01f04f9c80bcf807247a72b865a471a12b4d581b10ef834e76a747","history":[{"observed_at":"2026-10-06T17:31:57+08:00","content_hash":"7cc843137c01f04f9c80bcf807247a72b865a471a12b4d581b10ef834e76a747","change_kind":"initial","revision_date":"2019-05-15"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"附表：屏東縣屏東市西區公有零售市場攤鋪位使用費收費標準表.pdf","url":"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=11664&id=GL000833&type=LAW"}],"authority":"屏東縣政府","category":"建築管理相關","content":"第一條    本標準依零售市場管理條例第十二條第二項、規費法第八條\n第一款及第十條第一項規定訂定之。\n第二條    本標準之主管機關為屏東縣政府（以下簡稱本府），執行單\n位為本府城鄉發展處。\n第三條    本標準所稱公有零售市場攤（鋪）位，指本縣屏東市西區公\n有零售市場經本府核准使用之攤（鋪）位（以下簡稱攤（鋪）位\n）。\n第四條    攤（鋪）位使用人應按月繳納使用費，收費標準按面積大小\n、位置及攤（鋪）位鄰近設施訂定，如附表。\n前項使用費，本府得參考市場行情、經營狀況及使用需求之\n因素，必要時在前項附表收費標準百分之二十範圍內增減之。\n第五條    公有零售市場因配合政策、公共工程或其他不可抗力之因素\n，致攤（鋪）位無法使用者，得按停業日數比例，減收或免收使\n用費。\n第六條    攤(鋪)位使用人有下列各款情事之一者，本府得減收攤(鋪)\n位使用費，最高每攤(鋪)位以六個月為上限：\n一、擬具經營計畫宣傳行銷或購置必要設備。\n二、參與本府培訓課程取得一定時數認證。\n三、參加本府或經濟部舉辦評核活動獲獎。前項減收項目、對象\n、數額、上限及其他條件，由本府每年公告之。\n第一項攤(鋪)位使用人未依經營計畫執行，或有詐欺或其他\n不正方法情事，經執行單位查證屬實者，本府應撤銷減收處分，\n並以書面行政處分追繳之。\n第七條    本標準自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000833","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"修正日期":"民國 115 年 07 月 22 日","公發布日":"民國 113 年 04 月 29 日","圖表附件":"附表：屏東縣屏東市西區公有零售市場攤鋪位使用費收費標準表.pdf","法規名稱":"屏東縣所屬公有零售市場攤（鋪）位使用費收費標準","法規體系":"城鄉發展處","發文字號":"屏府民法字第11501976661號令"},"promulgation_date":"2024-04-29","revision_date":"2026-07-22","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000833","status":"unknown","title":"屏東縣所屬公有零售市場攤（鋪）位使用費收費標準","last_checked_at":"2026-10-06T17:31:53+08:00","last_success_at":"2026-10-06T17:31:53+08:00","verification_status":"fetched","content_hash":"e253f7853888a870a039ea468d50672fb3be39ae895fb27d783e4b8a0f6a82d1","history":[{"observed_at":"2026-10-06T17:31:53+08:00","content_hash":"e253f7853888a870a039ea468d50672fb3be39ae895fb27d783e4b8a0f6a82d1","change_kind":"initial","revision_date":"2026-07-22"}],"version_count":1,"attachment_hashes":{"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=11664&id=GL000833&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"第 1 條\n本辦法依屏東縣建築管理自治條例第三十六條第二項規定訂定之。\n第 2 條\n剩餘建築物就地整建依下列規定辦理：\n一、寬度：臨接建築線長度應為二公尺以上。\n二、深度：自建築線起扣除騎樓之深度後最小應為一‧五公尺，最大不得\n超過十六公尺。\n三、高度：整建建築物沿路面之簷高以超過拆除面之高度為準，拆除面與\n建築物成斜面，其高度不同者，以平均高度為準，拆除面之高度低於\n原建築物簷高者，得維持原建築物簷高。拆除面高度低於十三公尺者\n，得以十三公尺為準。屋頂如係木架或鐵架之房屋，其最高高度得自\n簷高加屋架跨度四分之一。\n四、原有空地得合併整建。但其總樓地板面積扣除騎樓面積後，不得超過\n拆除前原有建築物總樓地板面積。\n五、建蔽率、容積率：整建範圍得不受建蔽率及容積率規定之限制。\n前項第四款拆除前原有建築物總樓地板面積未達二百六十平方公尺者，整\n建時得以二百六十平方公尺為準。\n整建建築物與毗連建築物如最高簷高相差三十公分以內者，得由整建人聯\n合申請統一高度及統一正面裝修。\n整建應依建築技術規則建築設計施工編規定留設防火間隔。但整建之基地\n，其深度在十公尺範圍內，不在此限。\n第 3 條\n前條第一項第三款建築物之簷高超過十三公尺者，不適用本辦法規定。\n第 4 條\n騎樓之深度、高度及構造應依建築法及有關法令規定辦理。\n第 5 條\n修復門面得免申請就地整建，由修復人自行沿拆除面，按拆除剩餘之建築\n物高度修復之，依法須設置騎樓者，其拆除剩餘之建築物應依屏東縣都市\n計畫區騎樓設置標準辦理。\n第 6 條\n就地整建之基地如有公共設施保留地，得依下列規定辦理：\n一、剩餘建築物所有權人得向主辦工程機關申請補償，一併拆除之。\n二、剩餘建築物如有部分位於公共設施保留地上者，得檢附公共設施開闢\n時無償自行拆除切結書申請同時整建，整建之建築物以原高度為限，\n其構造材料應依都市計畫公共設施保留地臨時建築使用辦法之規定；\n該公共設施開闢時應由本府通知限期自行無條件拆除，逾期未拆者，\n由本府強制拆除之。\n第 7 條\n剩餘建築物有下列各款情事之一者，其所有權人得向主辦工程機關申請補\n償一併拆除：\n一、不符合本辦法規定無法申請整建者。\n二、具有危險性而不申請整建者。\n三、使用價值偏低，不申請整建者。\n第 8 條\n主辦公共工程機關應於工程開工時將預定完工期限通知拆除戶，其申請就\n地整建者，應於施工中或完工後八年內提出申請，逾期不予受理。\n前項申請應自收到申請書之次日起十日內予以准駁；申請文件不全者，應\n即通知申請人限期補正，逾期未補正或補正仍不齊全者，駁回其申請。\n第 9 條\n剩餘建築物逾期未申請整建而有傾頹或朽壞情事致有危害公共安全者，依\n建築法有關規定處理。\n第 10 條\n申請就地整建應檢附下列文件：\n一、申請書依內政部頒訂建造執照申請書並在備註欄加註依本辦法申請。\n二、土地權利證明文及共同壁協定書。\n三、地盤圖。\n四、舊有合法房屋證明文件。\n五、開闢路段完工證明文件，但施工中免附。\n六、建築線指定圖（含現有巷道）。\n七、比例尺百分之一原建築平面圖及各向立面圖。\n八、比例尺百分之一整建平面圖，各向立面圖、基礎、各層地板、屋架構\n造平面圖及主要剖面圖。\n九、整建高度超過七公尺或二層以上者，應檢附建築師或專業技師安全證\n明並依下列情況檢附結構計算書備查：\n（一）二層以下梁跨距超過六公尺之鋼筋混凝土梁，應檢附該部分應力計\n算書。\n（二）跨距超過十二公尺之鋼架構造，應檢附鋼架應力計算書。\n（三）三層之鋼筋混凝土構造建築物，樑跨距超過五公尺者及四層建築物\n應檢附結構計算書。前項設計圖經核准後，應向本府補具二份備查\n。\n第 11 條\n就地整建應依核准設計圖施工，其開工、建築期限依建築法第五十三條、\n第五十四條及屏東縣自治條例第二十五條規定辦理。\n整建完成後，應檢附申請書、竣工平面圖、立面圖及各向立面圖四寸照片\n二份及有關文件申請核發使用執照。\n第 12 條\n未經核准擅自整建或未依照核准圖樣施工者，依建築法第八十六條第一款\n規定或有關法令規定辦理。\n第 13 條\n本府得依建築法第二十七條規定委由鄉（鎮、市）公所依規定受理就地整\n建，指導施工及核發建築執照等業務。\n第 14 條\n依本辨法申請就地整建者，除供公眾使用之建築物外，得免由建築師設計\n、監造或營造業承造。\n第 15 條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:FL041015","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"修正日期":"民國 96 年 05 月 16 日","公發布日":"民國 92 年 02 月 09 日","法規名稱":"屏東縣拆除合法建築物剩餘部分就地整建管理辦法","法規體系":"城鄉發展處","發文字號":"屏府行法字第0960100451號"},"promulgation_date":"2003-02-09","revision_date":"2007-05-16","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=FL041015","status":"unknown","title":"屏東縣拆除合法建築物剩餘部分就地整建管理辦法","last_checked_at":"2026-10-06T17:31:49+08:00","last_success_at":"2026-10-06T17:31:49+08:00","verification_status":"fetched","content_hash":"6eec031ee618a6c2cb4b8f3d639603e47b79b60e2c4c87c0c70ec88694bbeec4","history":[{"observed_at":"2026-10-06T17:31:49+08:00","content_hash":"6eec031ee618a6c2cb4b8f3d639603e47b79b60e2c4c87c0c70ec88694bbeec4","change_kind":"initial","revision_date":"2007-05-16"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":true,"attachments":[{"name":"屏東縣政府-建築師設計、監造案件-申請使用執照得一併辦理變更設計項目一覽表-函文.pdf","url":"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=1587&id=GL000798&type=LAW"},{"name":"使照併案變更設計申請書.pdf","url":"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=1588&id=GL000798&type=LAW"}],"authority":"屏東縣政府","category":"建築管理相關","content":"如附件","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000798","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 112 年 04 月 18 日","圖表附件":"屏東縣政府-建築師設計、監造案件-申請使用執照得一併辦理變更設計項目一覽表-函文.pdf 使照併案變更設計申請書.pdf","法規名稱":"屏東縣政府-建築師設計、監造案件-申請使用執照得一併辦理變更設計項目一覽表","法規體系":"城鄉發展處","發文字號":"屏府城管字第11215123400號函"},"promulgation_date":"2023-04-18","revision_date":"2023-04-18","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000798","status":"unknown","title":"屏東縣政府-建築師設計、監造案件-申請使用執照得一併辦理變更設計項目一覽表","last_checked_at":"2026-10-06T17:32:00+08:00","last_success_at":"2026-10-06T17:32:00+08:00","verification_status":"attachment_pending","content_hash":"a8bde7f7503696fc0463d2904b33b69a051e057b308e3a89e6c70ef0d2fa76af","history":[{"observed_at":"2026-10-06T17:32:00+08:00","content_hash":"a8bde7f7503696fc0463d2904b33b69a051e057b308e3a89e6c70ef0d2fa76af","change_kind":"initial","revision_date":"2023-04-18"}],"version_count":1,"attachment_hashes":{"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=1587&id=GL000798&type=LAW":null,"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=1588&id=GL000798&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"一、為審定本縣六塊厝產業園區開發建設費用之負擔與土地、建築物及\n設施使用、收益及處分之計價，特設屏東縣政府六塊厝產業園區開\n發建設費用及計價審定小組（以下簡稱本小組）並訂定本要點。\n二、本小組任務如下：\n（一）審定及調整六塊厝產業園區開發建設費用（成本）之負擔及各種\n用地、建築物、設施之預售、出售價格及出租價格。\n（二）審定及調整六塊厝產業園區內原有事業應負擔開發建設費用。\n（三）審定依產業創新條例第四十六條之一及產業園區閒置土地認定與\n輔導使用及強制拍賣辦法第二十六條產業園區閒置土地之合理價\n格。\n（四）審定及調整依產業創新條例第五十四條及用地變更規劃辦法第二\n十九條回饋金之當期土地市價。\n（五）其他有關產業園區土地或建築物租售事項。\n三、本小組置委員十二人，其中一人為召集人由本府城鄉發展處長兼任\n，一人為副召集人由本府城鄉發展處副處長兼任，其餘委員，由本\n府就下列人員聘（派）兼之：\n（一）本府農業處副處長。\n（二）本府地政處副處長。\n（三）本府工務處副處長。\n（四）本府主計處副處長。\n（五）本府財稅局副局長。\n（六）本府環境保護局副局長。\n（七）本府行政處法制科科長。\n（八）屏東縣工商發展投資策進會總幹事。\n（九）專家學者二人。\n本小組委員任期為二年，期滿得續聘（派）兼之。但代表機關（單\n位）出任者，應隨其本職進退。\n本小組委員出缺時，應予補聘（派）；補聘（派）委員之任期至原\n委員任期屆滿之日止。\n本小組於開會時，產業園區受託開發單位、產業園區管理機構、有\n關單位應視需要派員列席。\n四、本小組視業務需要採不定期召開會議，會議由召集人召集，並為會\n議主席；召集人因故或遇有迴避事由而不能出席會議時，由召集人\n指派委員一人代理主席。\n委員應親自出席會議。但由機關（單位）代表兼任之委員，因故不\n能出席時，得指派代表出席。\n本小組應有出席人數過半數之委員出席始得開會；出席委員過半數\n之同意始得決議。可否同數時，由主席裁決之。\n迴避之委員，不計入出席或表決委員之人數。\n五、本小組委員對於議案有利害關係者，應自行迴避，不得參與開會及\n表決。\n本小組委員有前項情形而不自行迴避，或有具體事實，足認其執行\n職務有偏頗之虞者，當事人或利害關係人得申請其迴避。\n前項當事人或利害關係人之申請，應舉其原因及事實，於會議開始\n前向本小組為之，並應為適當之釋明；被申請迴避之委員，對於該\n申請得提出意見書。\n本小組對於第二項迴避之申請，應於會議開始前，作出是否應迴避\n之決定，並通知應迴避之委員。但當事人或利害關係人於會議進行\n中始提出申請者，本小組應立即作出是否迴避之決定，經認定應迴\n避，被申請迴避之委員應即迴避之。\n本小組委員有迴避事由者，應就該議案全程迴避。本小組委員就排\n定於同一會議期日有數議案者，應僅就有迴避事由之單一議案迴避\n之。\n六、本小組置執行秘書一人，綜理本小組幕僚事務，由本府城鄉發展處\n工商科長兼任，承召集人之命，就本小組審議案件需協調、釐清事\n項，得召開行政程序審查或諮詢會議，釐清問題及提出建議，提供\n本小組會議討論及審議之參考。\n本小組所需工作人員，由本府城鄉發展處業務人員兼任。\n七、本小組兼任委員及工作人員均為無給職。\n本小組所需經費，得納入六塊厝產業園區之開發成本或由屏東縣產\n業園區開發管理基金支應。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000742","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 111 年 05 月 03 日","法規名稱":"屏東縣政府六塊厝產業園區開發建設費用及計價審定小組設置要點","法規體系":"城鄉發展處","發文字號":"屏府城工字第11117636000號函"},"promulgation_date":"2022-05-03","revision_date":"2022-05-03","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000742","status":"unknown","title":"屏東縣政府六塊厝產業園區開發建設費用及計價審定小組設置要點","last_checked_at":"2026-10-06T17:31:59+08:00","last_success_at":"2026-10-06T17:31:59+08:00","verification_status":"fetched","content_hash":"e92bd6bbb047a4d4250d351ccba1f77742dd04ddfda1b4556dd22c07f612a1b9","history":[{"observed_at":"2026-10-06T17:31:59+08:00","content_hash":"e92bd6bbb047a4d4250d351ccba1f77742dd04ddfda1b4556dd22c07f612a1b9","change_kind":"initial","revision_date":"2022-05-03"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"屏東縣政府受理提議劃定更新地區建議書.pdf","url":"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=11701&id=GL000872&type=LAW"}],"authority":"屏東縣政府","category":"建築管理相關","content":"第一條    為受理土地及合法建築物所有權人(以下簡稱所有權人)提\n議劃定更新地區，依都市更新條例(以下簡稱本條例)第十條第\n三項規定，特訂定本辦法。\n第二條    本辦法主管機關為屏東縣政府（以下簡稱本府），執行單\n位為本府城鄉發展處。\n第三條    所有權人提議劃定更新地區之範圍應為完整之計畫街廓或\n面積達五千平方公尺以上。\n前項提議劃定更新地區全區屬因戰爭、地震、風災、水災\n、火災、爆炸、重大事變或其他不可抗力而遭受損害之合法建\n築物、高氯離子混凝土建築物、偵檢確定遭受輻射污染建築物\n，經建築主管機關認定有危險之虞，應立即拆除或修繕補強者\n，不受前項規定限制。\n農業區、保護區、河川區、行水區、風景區或其他非屬開\n發建築用地之非都市發展用地，不得提議劃定為更新地區。\n第四條    有本條例第六條規定之情形，並符合下列各款情形之一者\n，所有權人得向本府提議優先劃定更新地區：\n一、建築物屋齡達三十年以上，窳陋且屬非防火構造建築物之\n棟數占總建築物棟數比例達五分之三以上，並經建築師、\n專業技師簽證或經專業機構辦理鑑定。\n二、建築物屋齡達三十年以上，窳陋且建築物鄰棟間隔低於三\n公尺，其棟數占總建築物棟數比例達五分之三以上，並經\n建築師、專業技師簽證或經專業機構辦理鑑定。\n三、合法建築物屋齡達三十年以上，經專業機構依都市危險及\n老舊建築物結構安全性能評估辦法辦理結構安全性能評估\n，其結果為乙級或未達最低等級之棟數占總建築物棟數比\n例達五分之三以上。\n四、現有巷道彎曲狹小，寬度小於四公尺者之長度佔現有巷道\n總長度比例達五分之三以上，並經委託建築師、專業技師\n或專業機構辦理鑑定。\n五、四層樓以上建築物屬於無電梯設備之棟數占總建築物棟數\n比例達五分之三以上，且建築物現有停車位數量未達法定\n停車位之棟數，比例達五分之三以上。\n六、鄰近本府大眾運輸場站三百公尺範圍內。\n七、建築物經文化主管機關確認，具有歷史、文化、藝術、紀\n念價值，亟須依文化資產保存法辦理保存或維護，或其毗\n鄰建築物未能配合保存或維護。\n八、建築物經本府水利處確認未銜接公共污水下水道系統之棟\n數，占建築物總棟數比例達五分之三以上。\n九、建築物經核能安全委員會認可之輻射防護偵測業務機構偵\n檢確定遭受放射性污染。\n十、特種工業設施有妨害公共安全之虞。\n前項第一款至第四款規定之專業機構，指都市危險及老舊\n建築物加速重建條例及都市危險及老舊建築物結構安全性能評\n估辦法（以下簡稱評估辦法）所定經中央主管機關評定之共同\n供應契約機構。\n第五條    有本條例第七條規定之情形，並符合下列各款情形之一者\n，所有權人得向本府提議迅行劃定更新地區：\n一、建築物經建築主管機關公告屬因戰爭、地震、火災、水災\n、風災或其他重大事變遭受損壞，有立即重建必要。\n二、合法建築物經建築主管機關依建築法規、災害防救法規通\n知限期拆除、逕予強制拆除，或評估有危險之虞應限期補\n強或拆除。\n三、合法建築物依評估辦法辦理結構安全性能評估，其初步評\n估結果為未達最低等級。\n前項第二款及第三款之合法建築物，以非經文化資產保存\n法所定主管機關指定具有歷史、文化、藝術及紀念價值者為限。\n第六條    所有權人依前二條規定，向主管機關提議劃定都市更新地\n區六個月前，應就地區之發展狀況、更新地區範圍適宜性、土\n地及合法建築物所有權人與居民意願、社會及經濟關係、人文\n特色及整體景觀，進行全面調查及評估，辦理提議劃定更新地\n區範圍說明會。\n前項說明會，應一併通知提議劃定範圍內及相鄰土地之土\n地及合法建築物所有權人參與。\n屬前條第一項第一款及第二款情形者，得免依前項規定通\n知相鄰土地之土地及合法建築物所有權人參與第一項之說明會。\n第七條    提議劃定更新地區之所有權人（以下簡稱提議人），應填\n具建議書（如附件）並檢附下列文件向本府提出：\n一、提議人之身分證明文件及其位於提議範圍內之土地登記謄\n本、建物登記謄本及地籍圖謄本。\n二、提議人委託他人代為辦理者，應檢附受託人之身分證明文\n件及委託書。\n三、說明會開會通知單、書面會議紀錄、意願調查結果、說明\n會全程錄影檔案、鄰地通知證明及鄰地意願調查結果等辦\n理說明會之相關證明文件。\n四、符合本辦法第三條至第五條規定所列提議事由之證明文件。\n五、都市更新計畫草案。\n前項提議劃定更新地區涉及都市計畫主要計畫或細部計畫\n之擬定或變更者，應一併提出擬定主要計畫或細部計畫草案。\n第一項及前項文件有缺漏或不符規定而能補正者，本府應\n以書面通知限期補正；屆時未完成補正者，不予受理。\n第八條    本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000872","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 114 年 03 月 17 日","圖表附件":"屏東縣政府受理提議劃定更新地區建議書.pdf","法規名稱":"屏東縣政府受理提議劃定更新地區實施辦法","法規體系":"城鄉發展處","發文字號":"屏府民法字第11400711841號 令"},"promulgation_date":"2025-03-17","revision_date":"2025-03-17","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000872","status":"unknown","title":"屏東縣政府受理提議劃定更新地區實施辦法","last_checked_at":"2026-10-06T17:31:53+08:00","last_success_at":"2026-10-06T17:31:53+08:00","verification_status":"fetched","content_hash":"d2b5e00fb826338d66b01fef9fb588d31bc188a401043962905aa7e9544eea8d","history":[{"observed_at":"2026-10-06T17:31:53+08:00","content_hash":"d2b5e00fb826338d66b01fef9fb588d31bc188a401043962905aa7e9544eea8d","change_kind":"initial","revision_date":"2025-03-17"}],"version_count":1,"attachment_hashes":{"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=11701&id=GL000872&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"附件-重建申請書及重建計畫書表格式(屏東).pdf","url":"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=991&id=GL000506&type=LAW"}],"authority":"屏東縣政府","category":"建築管理相關","content":"一、為受理及審核都市危險及老舊建築物加速重建條例（以下稱本條例）\n第五條重建計畫，爰訂定本要點。\n二、新建建築物之起造人申請重建時，應檢具申請書、重建計畫，以及\n下列文件，向本府申請審核：\n（一）經文化主管機關確認原建築物非屬經指定之具有歷史、文化、\n藝術及紀念價值之證明文件。\n（二）經建築主管機關確認合法建築物符合本條例第三條第一項或第\n三項規定之證明文件。\n（三）全體土地及合法建築物所有權人名冊。\n（四）全體土地及合法建築物所有權人委託及同意書。\n（五）地籍圖謄本或其電子謄本。\n（六）土地登記謄本或其電子謄本。\n（七）建物登記謄本或其電子謄本，或合法建物證明。\n（八）土地使用分區證明書。\n（九）申請建築容積獎勵項目及額度核算表。\n前項第一款及第二款證明文件以申請日前三個月內核發者為限；第五\n款至第七款謄本或其電子謄本，以申請日當日核發者為限。\n容積獎勵項目為原建築容積時，應經開業建築師簽證，並檢附其認定\n原建築容積之相關文件，由本府轉送建築主管機關確認計算結果。重\n建申請書及重建計畫書表格式，由本府另公告之。\n三、本府受理重建申請案後，未核准前，前點第一項第四款所有權人以書\n面文件向本府申請撤回委託及同意，並副知起造人者，本府應通知及\n限期起造人撤回重建申請；逾期未撤回者，自撤回期限屆滿之次日起\n，視為撤回。\n重建計畫核准後，起造人未依本條例施行細則第七條規定申請建造執\n照者，原核准失其效力。\n四、起造人依都市危險及老舊建築物建築容積獎勵辦法(以下簡稱容積獎\n勵辦法)第六條至第九條申請容積獎勵者，應與本府簽訂協議書，始\n得核准重建計畫。\n依前項規定申請容積獎勵者，依容積獎勵辦法第十一條規定繳納保證\n金；其金額須經開業建築師簽證計算。\n五、前點保證金得選擇下列任一方式繳納：\n（一）現金、匯款或以金融機構為發票人及付款人，且以「屏東縣政\n府」為受款人之劃平行線即期支票繳納。\n（二）金融機構簽發之本票、支票、保付支票或郵政匯票，應為即期，\n並以「屏東縣政府」為受款人。\n（三）設定質權之金融機構定期存款單（期滿應自動轉期）方式繳納：\n持金融機構簽發以起造人名義之定期存款單，並附設定質權申\n請書，送本府辦理質權設定。\n銀行書面連帶保證書繳納。履約連帶保證金保證書有效期限應自領得\n使用執照核發日起二年之有效期間。\n六、經核准之重建計畫，其範圍內土地不得重複申請。\n如需變更重建範圍或容積獎勵項目與額度者，起造人應提出變更計畫\n，重新申請審核；變更起造人者，應檢附所有權人委託暨同意書提送\n本府辦理變更。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000506","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"修正日期":"民國 111 年 01 月 17 日","公發布日":"民國 107 年 01 月 30 日","圖表附件":"附件-重建申請書及重建計畫書表格式(屏東).pdf","法規名稱":"屏東縣政府受理都市危險及老舊建築物加速重建計畫作業要點","法規體系":"城鄉發展處","發文字號":"屏府城都字第11062388200號函"},"promulgation_date":"2018-01-30","revision_date":"2022-01-17","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000506","status":"unknown","title":"屏東縣政府受理都市危險及老舊建築物加速重建計畫作業要點","last_checked_at":"2026-10-06T17:31:58+08:00","last_success_at":"2026-10-06T17:31:58+08:00","verification_status":"fetched","content_hash":"996406fd48317631a226153d327a57bc8581043c98b4170a54b81b1015a643ed","history":[{"observed_at":"2026-10-06T17:31:58+08:00","content_hash":"996406fd48317631a226153d327a57bc8581043c98b4170a54b81b1015a643ed","change_kind":"initial","revision_date":"2022-01-17"}],"version_count":1,"attachment_hashes":{"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=991&id=GL000506&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"一、屏東縣政府（以下簡稱本府）為落實建築物公共安全檢查簽證及申報\n制度，提昇簽證品質，特訂定本要點。\n二、本要點所稱專業機構或人員，指領有內政部依建築物公共安全檢查專\n業機構與人員認可要點規定核發認可證之專業機構或專業檢查人。\n三、本府為審議申報簽證不實案件設置建築物公共安全專案小組（以下簡\n稱專案小組），由本府、建築師公會及相關專業機構（團體）指派代\n表組成，並得邀請專家學者列席提供諮詢意見。\n前項專案小組主持人由本府指派代表擔任，或由出席成員互推一人主\n持，審議案件如有重大爭議時，得通知專業機構或人員到場說明。\n四、本府辦理申報案件之書面查核或申報場所之複查，如涉有簽證不實案\n件者，專業機構或人員應於接獲本府通知日起十五日內（以郵戳為憑\n）提出陳述意見書，再由本府併同下列文件檢送專案小組審議：\n（一）申報案件書面審查發現簽證不實者，應檢附申報書案卷等資料。\n（二）申報場所複查發現簽證不實者，應檢附申報書案卷、檢（複）查\n紀錄表及申報場所相關佐證資料等。\n專業機構或人員不於前項期間內提出陳述意見書者，視為放棄陳述機\n會。\n五、專業機構或人員受託辦理申報案件，有下列情形之一者，並經專案小\n組審議決議通過後，應依建築法第九十一條之一第一款規定處以罰鍰\n，並通知中央主管建築機關：\n（一）未依建築物公共安全檢查簽證及申報辦法規定之檢查簽證項目\n執行檢查，或引用法令錯誤，情節嚴重。\n（二）未依申報場所實際使用現況或範圍檢查，且未於檢查報告書內\n簡圖附註具體說明，情節嚴重者。\n（三）防火避難設施類如防火區劃、非防火區劃分間牆、內部裝修使\n用材料明顯不符，仍予簽證為合格者，情節嚴重。\n（四）提出不合法令規定之改善計畫，情節嚴重。\n（五）檢查報告書內檢附不實文件，係可歸責於專業機構或人員，情\n節嚴重。\n（六）申報場所複查不符規定，卻簽證為合格，情節嚴重。\n（七）其他違規事項情節嚴重。\n六、專業機構或人員受託辦理申報案件，有下列情形之一者，記缺點一次，\n缺點累計次數以一年為期，每年達五次者，並經專案小組審議決議通過\n後，應依建築法第九十一條之一第一款規定處以罰鍰：\n（一）檢查報告書未依規定之選項勾選或應填寫之內容未詳實填寫者，\n或與檢附書件記載不符。\n（二）申報場所檢查不合格項目屬可立即改善事項，卻仍提具改善計畫。\n（三）檢查紀錄簡圖相關標示圖例、符號繪製不清楚。\n（四）經審議會議決議簽證不實，情節輕微。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000879","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 114 年 04 月 18 日","法規名稱":"屏東縣政府建築物公共安全檢查簽證及申報案件簽證不實認定作業要點","法規體系":"城鄉發展處","發文字號":"屏府城使字第1140098554號函"},"promulgation_date":"2025-04-18","revision_date":"2025-04-18","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000879","status":"unknown","title":"屏東縣政府建築物公共安全檢查簽證及申報案件簽證不實認定作業要點","last_checked_at":"2026-10-06T17:32:06+08:00","last_success_at":"2026-10-06T17:32:06+08:00","verification_status":"fetched","content_hash":"73261d5d992dca7b91f658a400dac1551f2ad9f19961c9e26d2e3dbb735a33ee","history":[{"observed_at":"2026-10-06T17:32:06+08:00","content_hash":"73261d5d992dca7b91f658a400dac1551f2ad9f19961c9e26d2e3dbb735a33ee","change_kind":"initial","revision_date":"2025-04-18"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"一、為處理本府受理建造執照申請案件，因涉及其他法令規定應檢附之書\n類文件不齊全，且非可歸責於起造人事由，經通知未能於六個月內改\n正完竣後送請復審之案件，特訂定本原則。\n二、本原則之適用範圍為建造執照之申請，因涉及開放空間預審、都市設\n計審議、容積移轉審查、增額容積審查、交通影響評估審議、環境影\n響評估審查、水土保持計畫審查及依建築技術規則總則編第三條申請\n建築物防火避難性能評定認可案等其他類似案件，須經本府各目的事\n業主管機關(單位)審議或審查者。\n三、前點申請案件，起造人應於本府第一次通知改正之日起六個月內送請\n復審。\n前項復審因非可歸責於起造人之事由不合規定者，且起造人自建造執\n照掛號日前或掛號日起六個月內已向本府各目的事業主管機關(單位)\n提出申請者，得依下列原則辦理：\n(一)屬都市設計審議、開放空間預審、容積移轉審查、增額容積審查\n、交通影響評估審議等類案件者，增加改正期限六個月，並以一\n次為限。\n(二)屬環境影響評估審查、水土保持計畫審查等類案件，增加改正期\n限九個月，並以一次為限。\n(三)同時涉及前二款之案件，以其中一款規定改正期限較長者為上限\n，但不得重覆計算或累計。\n(四)屬其他類似案件者，由本府依個案事實認定。\n四、起造人未依前點規定期限內送請復審，本府得依建築法第三十六條規\n定將該申請案件予以駁回。但有其他特殊情形，且非可歸責於起造人\n者，得檢具相關事證經本府同意者，不在此限。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000713","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 110 年 06 月 10 日","法規名稱":"屏東縣政府建造執照依據建築法第三十六條規定復審案件處理原則","法規體系":"城鄉發展處","發文字號":"屏府城管字第11023032800號函"},"promulgation_date":"2021-06-10","revision_date":"2021-06-10","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000713","status":"unknown","title":"屏東縣政府建造執照依據建築法第三十六條規定復審案件處理原則","last_checked_at":"2026-10-06T17:31:58+08:00","last_success_at":"2026-10-06T17:31:58+08:00","verification_status":"fetched","content_hash":"0f8594101a9372e986d189e26f08b6631c4cc630b7f891b44837cad5e2a2ef00","history":[{"observed_at":"2026-10-06T17:31:58+08:00","content_hash":"0f8594101a9372e986d189e26f08b6631c4cc630b7f891b44837cad5e2a2ef00","change_kind":"initial","revision_date":"2021-06-10"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"修正對照表.doc","url":"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=731&id=GL000332&type=LAW"}],"authority":"屏東縣政府","category":"建築管理相關","content":"一、計劃緣起：\n為提昇交通服務品質，經常保持縣境內公路系統、市區道路及都市計劃\n區外村里連絡道、巷道之路面平整，並兼顧管線單位因業務上需挖掘道\n路埋設管線，特訂定本作業程序，明確劃分路權管理單位與使用公路用\n地埋設管線單位之權責，藉以提高行政效率而達服務便民之目的。\n二、依據：\n(一)公路法。\n(二)道路交通管理處罰條例。\n(三)市區道路條例。\n(四)公共設施管線工程挖掘道路注意要點。\n(五)公路用地使用規則。\n(六)公共管線工程挖掘道路作業規定。\n(七)申請挖掘道路注意事項。\n(八)公路局挖掘道路作業程序手冊。\n三、適用範圍：\n(一)國道、省道向交通部公路總局第三區養護工程處申請核定。\n(二)鄉道路線範圍，為單一鄉鎮市者，由各該管轄鄉、鎮、市公所核定\n。縣道及跨越兩個（含）以上鄉、鎮、市者由縣政府核定。\n(三)村里連絡道（未編號道路）、巷道及市區道路由各該管轄鄉、鎮、\n市公所核定。\n(四)產業道路、農路、專用道路、私設道路、特定區道路或其他道路，\n由各該管理機關核定。\n(五)各種道路與國道、省道、縣道、鄉道重疊部分，由國道、省道、縣\n道、鄉道主管機關核定。\n(六)鄉道系統路線與都市計劃區內重疊部分，由都市計劃主管鄉、鎮、\n市公所核定。\n(七)主管機關有爭議時，由其上一級機關協商。\n(八)縣道如委託府外機關代養，由代養機關核定。\n四、作業程序：\n(一)申挖單位網路填寫申請書。\n(二)道路管理機關審核：本程序申請資格限公有之公共設施或民營公\n用事業之公共設施埋設物，個（私）人申請不受理。\n1.禁挖限制：\n(1)道路拓寬改善完成未滿三年者。\n(2)路面加封未滿二年者。\n(3)其他臨時規定時間。\n2.暫緩受理申請：\n(1)擅自挖掘道路經依法處罰尚未結案者。\n(2)違規施工未依規定期限改善結案者。\n(3)無法配合本府工程施工單位辦理管（桿）線遷移、人(手)\n孔蓋調整等者。\n(4)因管線單位過失因素，發生國賠案件，管線單位未積極配\n合負擔責任者。\n(5)管線單位未善盡管理責任，致人（手）孔蓋鬆脫或與路面\n不平齊，經發現函請限期改善，逾期仍未改善者。\n(6)其他應暫緩申請者。\n3.特殊案件請准免受禁挖限制：\n(1)經中央單位核准之國家重要建設有關之管線工程，需限期\n完成者。\n(2)禁挖路段已有前項特殊案件管線挖掘路段，其他管線單位\n應（可）配合施工之管線者。\n(3)重大軍事管線工程經核准者。\n(4)人民新接用水、用電等管線工程（附使用執照）。\n(5)道路交通號誌之有關管線工程（有急迫性經警察機關核可\n者）。\n(6)其他經本府核可者。\n4.搶修案件挖掘單位應先電傳道路主管機關報備，並於三日內\n（例假日順延）檢附相關證明資料及搶修施工照片補辦申挖\n手續，逾期視同擅自挖掘道路。\n(三)交通安全維持計畫審核：\n1.挖掘路面施工期限超過三十工作天者，道路管理機關(單位)\n初審後轉報屏東縣道路交通安全聯席會報核定。\n2.橋樑附掛案件各受理單位應要求申請單位檢附結構安全計算\n書、附掛詳細圖等。\n(四)申挖案件會勘：\n按申請書及會勘紀錄表內容辦理。\n(五)依相關規定核算代辦挖掘路面修復費並通知繳費。\n(六)繳費程序完成後，核發挖掘道路許可證。\n(七)申挖工期展延：\n申挖單位無法按核定日期施工時，應於網路辦理工期展延。\n(八)申挖單位施工應依相關規定確實辦理。\n(九)申挖單位網路申報竣工並辦理結案。\n五、挖掘道路有關法令：\n(一)公路法第72條：擅自挖掘、破壞公路用地，或損壞各項設施者\n，處三萬元以上十五萬元以下罰緩。公路主管機關並應責令回\n復原狀、償還修復費用或賠償。公路計劃用地，經公告、立定\n界樁並禁止或限制建築後，仍擅自建築者，由公路主管機關會\n同有關機關拆除之。\n(二)公路法第78條：本法規定之罰鍰，由該管公路主管機關處罰，\n並得於執行無效時，移送法院強制執行。\n(三)公路用地使用規則第10條：因公路興建、改善、拓寬或交通安\n全需要，需將公用或公有設施遷移時，使用人應立即予以配合\n，有關配合管線遷移費用，依下列規定：\n1.辦理國道及省道公路工程時已有管線必須永久遷移者，其所\n需費用，依原設計標準，按新設計經費減去拆除材料折舊價\n值後，應由管線單位負擔三分之二，公路施工單位負擔三分\n之一。\n2.附掛於前款公路橋樑之管線，遇有橋樑拓寬或改建，管線單\n位應負擔全部遷移費用，並配合施工。\n3.辦理第1.項公路以外之公路工程時，既有管線必須永久遷移\n者，管線單位應立即予以配合，並自行負擔全部遷移費用。\n4.遇有管線屬臨時遷移時，或輸配水管不需遷移，其產權屬用\n戶所有之給水管線遷移時，由公路施工單位全額負擔遷移、\n搶修費用。\n5.前項第4.項所稱臨時遷移係指既有管線影響公路工程施工，\n須予遷移，限於工地環境，需辦理一次以上之遷移作業時，\n其最末一次以前之各次遷移由臨時遷移管線單位負責設計、\n施工為原則，並應配合公路工程施工適時辦理；必要時可協\n商委由公路施工單位代辦設計、施工，管線單位如有擴充其\n容量或補強換新者，其擴充及補強換新部分所增費用，由管\n線單位負擔。\n6.第1.項設施之遷移，公路主管機關應於實施年度前，通知使\n用人估計所需費用並編列年度預算辦理，如屬急需工程，不\n及編列預算時，得由公路主管機關先行墊付，再由使用人列\n入下年度預算歸還。\n(四)公共施設管線工程挖掘道路注意要點第11條：三年內不得因管\n線工程挖掘道路之規定，左列情形不受其限制：\n1.與國家重要建設有關之工程。\n2.已有管線之修理工程。\n3.重大軍事管線工程。\n4.沿該道路橫向或直向至人（手）孔之用戶聯接管線工程及其\n附帶直向人行道聯接管線工程。\n5.道路交通號誌之有關管線工程。\n(五)道路交通管理處罰條例第82條：有左列情形者，除責令行為人\n即時停止並消除障礙外，處行為人或雇主一千二百元以上二千\n四百元以下罰緩。\n1.在道路堆積、置放、設置或拋擲足以妨礙交通之物。\n2.在道路兩旁附近燃燒物品，發生濃煙，足以妨礙行車視線者。\n3.利用道路為工作場所者。\n4.利用道路放置拖車、貨櫃或動力機械者。\n5.興修房屋使用道路未經許可超出限制者。\n6.經主管機關許可挖掘道路而不豎立警告標誌，或於事後未將\n障礙物清除者。\n7.擅自設置或變更道路交通標誌、標線、號誌或其他類似之標\n誌者。\n8.未經許可在道路設置石碑、廣告牌、綵坊其他類似物者。\n9.未經許可在道路舉行賽會擺設筵席、演戲、拍攝電影及其他\n類似行為者。\n10.未經許可在道路擺設攤位。\n前項第一款妨礙交通之物、第八款之廣告牌、經勸導行為人不\n即時清除或行為人不在場，視同廢棄物，依廢棄物法令清除之\n。第十款之攤棚、攤架得沒入之。行為人在高速公路或高速公\n路兩旁，有第一項第一款、第二款情事者，處新臺幣三千元以\n上六千元以下罰鍰；致發生交通事故者，加倍處罰。\n(六)四線道以上路面，第一線快車道部分（內側車道）依「公路用\n地使用規則」之精神，原則以不准挖掘埋設管線辦理，以維持\n行車舒適及順暢。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000332","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 104 年 04 月 22 日","法規名稱":"屏東縣政府挖掘道路作業程序","法規體系":"工務處","發文字號":"屏府工養字第10412059900號 函","立法理由":"修正對照表.doc"},"promulgation_date":"2015-04-22","revision_date":"2015-04-22","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000332","status":"unknown","title":"屏東縣政府挖掘道路作業程序","last_checked_at":"2026-10-06T17:32:11+08:00","last_success_at":"2026-10-06T17:32:11+08:00","verification_status":"fetched","content_hash":"d8c679cd8e9d042ef56f67acaefb9358f30c46cd5fe85edfac2ac8b801ced007","history":[{"observed_at":"2026-10-06T17:32:11+08:00","content_hash":"d8c679cd8e9d042ef56f67acaefb9358f30c46cd5fe85edfac2ac8b801ced007","change_kind":"initial","revision_date":"2015-04-22"}],"version_count":1,"attachment_hashes":{"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=731&id=GL000332&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"屏東縣既成道路認定申請書.doc","url":"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=926&id=GL000441&type=LAW"},{"name":"屏東縣既成道路認定標準作業流程說明.doc","url":"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=927&id=GL000441&type=LAW"}],"authority":"屏東縣政府","category":"建築管理相關","content":"一、屏東縣政府(以下簡稱本府) 為提昇縣內道路使用率及道路通行順暢，並減少道路\n使用爭議之發生，特訂定本作業程序。\n本認定標準作業程序未規定者，適用其他法令規定。\n二、本作業程序所稱既成道路，指司法院大法官釋字第四百號解釋之道路。\n三、既成道路成立公用地役關係下列要件：\n(一)不特定之公眾通行所必要，而非僅為通行之便利或省時。\n(二)於公眾通行之初，土地所有權人並無阻止之事實。\n(三)經歷之年代久遠而未曾中斷。所謂年代久遠雖不必限定其期間，但仍應以時日\n長久，一般人無復記憶其確實之起始，僅能知其梗概(例如始於日據時期、八\n七水災等)為必要。\n四、本作業程序申請人為各鄉（鎮、市）公所、相關行政機關。\n五、申請既成道路認定，需檢附之文件如下：\n(一)申請計畫書：載明土地所有權人之姓名、年齡、住址、申請土地地號及巷道名\n稱。（如附件）\n(二)位置及實測現況套繪地籍圖，如無實測圖者，由本府函請地政事務所辦理實測\n鑑界，費用由申請人繳交。\n(三)土地登記簿謄本及地籍圖謄本。\n(四)非屬法定空地證明。\n(五)土地通行二十年以上相關證明文件，如七十年版行政院農委會林務局農林航量\n所之航空測量圖、其他圖像資料，可證明公眾通行經歷年代久遠未曾中斷之文\n件。\n六、本府應於受理申請認定既成道路之日起六十六日內，為准駁之決定；必要時，得\n予延長，延長之期間不得逾二十日。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000441","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 106 年 04 月 13 日","圖表附件":"屏東縣既成道路認定申請書.doc 屏東縣既成道路認定標準作業流程說明.doc","法規名稱":"屏東縣政府既成道路認定標準作業程序","法規體系":"工務處","發文字號":"屏府工土字第10612087300號函"},"promulgation_date":"2017-04-13","revision_date":"2017-04-13","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000441","status":"unknown","title":"屏東縣政府既成道路認定標準作業程序","last_checked_at":"2026-10-06T17:32:12+08:00","last_success_at":"2026-10-06T17:32:12+08:00","verification_status":"fetched","content_hash":"126bc2cd691992d11072f00335804603400e0fd37e569383649db09b8879976d","history":[{"observed_at":"2026-10-06T17:32:12+08:00","content_hash":"126bc2cd691992d11072f00335804603400e0fd37e569383649db09b8879976d","change_kind":"initial","revision_date":"2017-04-13"}],"version_count":1,"attachment_hashes":{"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=926&id=GL000441&type=LAW":null,"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=927&id=GL000441&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"屏東縣政府消費爭議申訴案件權限分工表.pdf","url":"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=1127&id=GL000536&type=LAW"}],"authority":"屏東縣政府","category":"建築管理相關","content":"一、屏東縣政府(以下簡稱本府)為確保消費者權益、迅速合理解決消費爭議申訴案件\n(以下簡稱申訴案件)，以落實消費爭議之處理，特定訂本要點。\n二、本府消費者保護申訴業務窗口(以下簡稱申訴窗口)對於所受理之申訴案件，應予\n編號錄案列管，並依「屏東縣政府消費爭議申訴案件權限分工表」(如附表)移送\n第一次申訴主辦單位處理。\n申訴案件如涉及兩個以上主辦單位或權屬不明時，由本府消費者保護官(以下簡\n稱消保官)指定主辦單位。\n三、受理第一次申訴之主辦單位受理申訴案件後，應依下列方式妥為處理，並將處理\n情形通知申訴人及副知消保官：\n(一)申訴案件如須了解其事實及過程者，得請企業經營者提供有關資料研議或請\n企業經營者查明後逕復申訴人。\n(二)申訴案件如涉及有無違反相關法令或契約情事者，可依法請企業經營者提供\n資料或派員查核或請企業經營者及申訴人前來說明案情。\n(三)申訴案件如屬法令規章之闡釋或適用問題者，依相關法令規定，函復當事人\n，其屬通案性質者，並副知各該企業同業公會轉之所屬會員。\n四、受理第一次申訴之主辦單位應於收案後七日內函文業者於十五日內妥適協商處理\n，並副知申訴窗口。\n第一次申訴協商不成立者，由申訴窗口辦理第二次申訴或消費者爭議調解。\n五、本府各單位及所屬一級機關應指定專人辦理申訴案件。\n消保官對於所受理申訴案件之處理情形，應定期追蹤考核並對執行成效良好人員\n敘獎。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000536","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 107 年 07 月 13 日","圖表附件":"屏東縣政府消費爭議申訴案件權限分工表.pdf","法規名稱":"屏東縣政府消費爭議申訴案件分工處理要點","法規體系":"城鄉發展處","發文字號":"屏府消保字第10725113900號 函"},"promulgation_date":"2018-07-13","revision_date":"2018-07-13","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000536","status":"unknown","title":"屏東縣政府消費爭議申訴案件分工處理要點","last_checked_at":"2026-10-06T17:31:56+08:00","last_success_at":"2026-10-06T17:31:56+08:00","verification_status":"fetched","content_hash":"457c9ba31ceb9fa39d5d7d66c79e79813b41c4b495e380d06b7d439c92b54d3d","history":[{"observed_at":"2026-10-06T17:31:56+08:00","content_hash":"457c9ba31ceb9fa39d5d7d66c79e79813b41c4b495e380d06b7d439c92b54d3d","change_kind":"initial","revision_date":"2018-07-13"}],"version_count":1,"attachment_hashes":{"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=1127&id=GL000536&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"屏東縣政府處理違反公寓大廈管理條例事件裁罰基準附表.pdf","url":"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=11696&id=GL000868&type=LAW"}],"authority":"屏東縣政府","category":"建築管理相關","content":"一、屏東縣政府（以下簡稱本府）為審慎處理違反公寓大廈\n管理條例（以下簡稱本法）使用管理規定事件，並兼顧\n裁罰之明確性、適當性與公平性及符合比例原則，以減\n少裁罰爭議及提升行政效率，特訂定本基準。\n二、違反本法使用管理規定事件裁罰基準如附表。\n三、違反本基準附表所列違規事件，如有特殊情況者，得審\n酌違反行政法上義務行為應受責難程度、所生影響、所\n得利益及受處罰者之資力，依本基準附表酌予加重或減\n輕其處罰及延長或縮短改善期限，並應敘明理由。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000868","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 114 年 01 月 21 日","圖表附件":"屏東縣政府處理違反公寓大廈管理條例事件裁罰基準附表.pdf","法規名稱":"屏東縣政府處理違反公寓大廈管理條例事件裁罰基準","法規體系":"城鄉發展處","發文字號":"屏府城使字第11400036410號"},"promulgation_date":"2025-01-21","revision_date":"2025-01-21","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000868","status":"unknown","title":"屏東縣政府處理違反公寓大廈管理條例事件裁罰基準","last_checked_at":"2026-10-06T17:32:06+08:00","last_success_at":"2026-10-06T17:32:06+08:00","verification_status":"fetched","content_hash":"164e09fdfac0cfccaa3bd5fa762d8d37f071fbf06954203e8d6d8aaf3c91057c","history":[{"observed_at":"2026-10-06T17:32:06+08:00","content_hash":"164e09fdfac0cfccaa3bd5fa762d8d37f071fbf06954203e8d6d8aaf3c91057c","change_kind":"initial","revision_date":"2025-01-21"}],"version_count":1,"attachment_hashes":{"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=11696&id=GL000868&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"屏東縣政府處理違反建築法使用管理規定事件裁罰基準附表.pdf","url":"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=11650&id=GL000834&type=LAW"}],"authority":"屏東縣政府","category":"建築管理相關","content":"一、屏東縣政府（以下簡稱本府）為審慎處理違反建築法（以下簡稱本法\n）使用管理規定事件，並兼顧裁罰之明確性、適當性與公平性及符合\n比例原則，以減少裁罰爭議及提升行政效率，特訂定本基準。\n二、本基準有關建築物之用途分類，依建築物使用類組及變更使用辦法之\n類組定義、使用項目舉例等規定辦理。\n三、違反本法使用管理規定事件裁罰基準如附表。\n四、違反本基準附表所列違規事件，如有特殊情況者，得審酌違反行政法\n上義務行為應受責難程度、所生影響、所得利益及受處罰者之資力，\n依本基準附表酌予加重或減輕其處罰及延長或縮短改善期限，並均應\n敘明理由。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000834","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 113 年 04 月 29 日","圖表附件":"屏東縣政府處理違反建築法使用管理規定事件裁罰基準附表.pdf","法規名稱":"屏東縣政府處理違反建築法使用管理規定事件裁罰基準","法規體系":"城鄉發展處","發文字號":"屏府城使字第11315072301號 令"},"promulgation_date":"2024-04-29","revision_date":"2024-04-29","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000834","status":"unknown","title":"屏東縣政府處理違反建築法使用管理規定事件裁罰基準","last_checked_at":"2026-10-06T17:32:05+08:00","last_success_at":"2026-10-06T17:32:05+08:00","verification_status":"fetched","content_hash":"4abb1594ce46329127d9d87cadc1dfe41621ea052c04d8d7485ef15f04d87ca8","history":[{"observed_at":"2026-10-06T17:32:05+08:00","content_hash":"4abb1594ce46329127d9d87cadc1dfe41621ea052c04d8d7485ef15f04d87ca8","change_kind":"initial","revision_date":"2024-04-29"}],"version_count":1,"attachment_hashes":{"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=11650&id=GL000834&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"一、屏東縣政府（以下簡稱本府）為辦理本縣轄內建築物變更戶數作業，\n以建全建築管理，特訂定本要點。\n二、符合下列情形之建築物所有權人，得向本府提出申請變更戶數：\n(一)領有使用執照之建築物。\n(二)實施建築管理前已建築完成之舊有合法房屋。\n前項變更戶數之申請，以未涉及新增或變更分戶牆為限；如涉及新增\n或變更分戶牆，應以變更使用執照程序辦理。\n三、申請變更戶數之建築物，符合下列各款情形者，得依本要點辦理並免\n辦理變更使用執照。但應符合建築法、建築技術規則及公寓大廈管理\n條例等相關規定：\n(一)未涉及室內裝修、用途變更。\n(二)與原核准使用執照圖說或合法建築物證明文件相符。\n(三)各戶均有獨立出入口。\n四、申請建築物變更戶數作業應檢附之文件如下：\n(一)申請書。\n(二)建築物使用執照影本或合法建築物證明文件。\n(三)申請人身分證明文件影本。\n(四)建築物權利證明文件；未辦理建築物所有權第一次登記者，應檢\n具最近一次完納房屋稅捐之證明文件及切結書。\n(五)最後一次核准使用執照竣工平面圖或現況建築物平面示意圖；原\n有圖說遺失或舊有合法建築物者，應由申請人檢附切結書並委由\n依法登記開業建築師繪製現況建築物平面示意圖替代之。\n(六)戶數變更後建築平面圖一式三份，標示其範圍面積並由申請人簽\n章。\n(七)建築物現場出入口照片一份，以顯示其出入口全景為準。\n(八)其他經本府指定之文件。\n五、依本要點申請變更戶數，經本府發給變更戶數同意備查函後，申請人\n應向建築物所在地之戶政機關申請門牌編釘及核發門牌證明。\n前項本府同意備查後，應一併通知建築物所在地之戶政事務所；戶政\n事務所核准申請人增編或合併門牌時，應通知本府於其使用執照上註\n記。\n第一項建築物產權如涉及私權糾紛，由申請人自行處理。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000688","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 109 年 11 月 05 日","法規名稱":"屏東縣政府辦理建築物變更戶數作業要點","法規體系":"城鄉發展處","發文字號":"屏府城使字第10950927500號函"},"promulgation_date":"2020-11-05","revision_date":"2020-11-05","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000688","status":"unknown","title":"屏東縣政府辦理建築物變更戶數作業要點","last_checked_at":"2026-10-06T17:31:57+08:00","last_success_at":"2026-10-06T17:31:57+08:00","verification_status":"fetched","content_hash":"982a00786d690583376e99a51756f7f78bc7f27be81bf53310d4fcd3039b94d4","history":[{"observed_at":"2026-10-06T17:31:57+08:00","content_hash":"982a00786d690583376e99a51756f7f78bc7f27be81bf53310d4fcd3039b94d4","change_kind":"initial","revision_date":"2020-11-05"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"一、屏東縣政府（以下簡稱本府）為使依都市更新條例規定舉行聽證之作業\n事項有所依循，特訂定本要點。\n二、本要點執行單位為本府城鄉發展處。\n三、本要點用詞定義如下：\n（一）都市更新案件之當事人：更新單元內各土地及合法建築物之所有權\n人、地上權人、永佃權人、耕地三七五租約承租人及實施者。\n（二）利害關係人：更新單元內各土地及合法建築物之他項權利人、囑託\n限制登記機關、預告登記請求權人、舊違章建築戶之對象。\n前項以外之人因都市更新程序之進行致其權利或法律上利益受實質影響\n或不利者，本府得依職權或申請，通知其參加為當事人。\n四、都市更新案件得就下列事項之爭議事由及證據資料舉行聽證：\n（一）都市更新事業計畫書、圖或權利變換計畫書、估價報告書摘要。\n（二）其他經本府認定與都市更新案件審查有關事項。\n五、聽證之主持人，由本府首長或其指定人員擔任。本府得視個案爭議事由\n之情形，邀請相關專家、學者、機構（關）或團體代表出席，必要時得\n由律師、相 關專業人員或其他熟諳法規之人員在場協助之。\n六、本府應於舉行聽證期日之二十日前，於本府、鄉（鎮、市）公所及村（\n里）辦公室張貼公告，以及刊登政府公報或新聞紙三日，並於網站刊登\n公告。\n本府應以書面記載下列事項，通知都市更新案件之當事人及已知之利害\n關係人（以下簡稱受通知人）。但經受通知人同意者，不受二十日之限\n制：\n（一）聽證之事由及依據。\n（二）受通知人之姓名或名稱及其住居所、事務所或營業所。\n（三）聽證之期日及場所。\n（四）聽證之主要程序。\n（五）受通知人得選任代理人。\n（六）受通知人依第十三點得享有之權利。\n（七）擬進行預備程序者，預備聽證之期日及場所。\n（八）缺席聽證之處理。\n（九）聽證之機關。\n（十）都市更新案件內容相關資訊。\n（十一）表示出席聽證意願之期限。\n（十二）提出書面意見及資料之期限。\n前項第十款所稱之都市更新案件內容相關資訊，指依第四點內容為主，\n並得以光碟型式檢附之，當事人或利害關係人並得向實施者索取或依規\n定向本府申請紙本。都市更新案件內容相關資訊應以紙本方式存放於鄉\n（鎮、市）公所及村 （里）辦公處供民眾查閱。\n受通知人或其代理人未能出席聽證者，得於舉行聽證程序前以書面陳述\n意見，該書面意見本府得列入聽證紀錄。\n為聽證進行之順暢及時間之控制，受通知人擬於聽證陳述意見或未能出\n席聽證者，應於聽證期日十日前將書面意見及資料提供本府。逾期提供\n者，該書面意見本府得列入聽證紀錄，並提交本府都市更新及爭議處理\n審議會（以下簡稱審議會）作為審議之參考。\n受通知人對其所提出之書面意見及資料，認有保密必要者，應於提出時\n敘明須保密之理由，並製作可公開之文件摘要，送交本府。\n聽證期日及場所之決定，應預留相當期間，便利受通知人或其代理人參\n與。\n七、本府得依職權或受通知人之申請，變更聽證期日或場所。但以有正當理\n由為限。\n本府為前項之變更者，應依第六點規定通知並公告。\n八、本府為使聽證順利進行，認為必要時，得於聽證期日前，舉行預備聽證\n，預備聽證得為下列事項：\n（一）議定聽證程序之進行。\n（二）釐清都市更新案件之爭議事由。\n（三）提出有關文書及證據。\n（四）其他與都市更新案件審議有關之事項。\n（五）當事人或利害關係人以書面陳述意見事項。\n預備聽證之進行，應作成紀錄。\n九、聽證應按本府通知指定之期日及場所舉行。聽證，應公開以言詞為之，\n並得以錄音、錄影輔助之。但公開顯然有違背公共利益之虞或對當事人\n或已知之利害關係人利益造成重大損害之虞者，本府得依職權，決定全\n部或部分不予公開。\n十、出席聽證會之人員進入會場前，本府應請其出示受通知證明文件或身分\n證明文件或委託書，以確認出席者身分。未能提示身分證件且未適時補\n正者，禁止其出席聽證。\n十一、聽證以主持人說明案由為聽證開始，並由主持人或其指定之人說明事\n件之內容要旨。\n十二、聽證程序依下列方式進行：\n（一）當事人及已知之利害關係人自行提出證據者，應於聽證開始前將\n證據資料提示本府。\n（二）聽證程序開始，先由主持人介紹出席聽證之人員，並說明案由。\n（三）作業單位宣讀會議議程及會場規則。\n（四）實施者簡報說明案件規劃內容。\n（五）出席聽證者陳述意見：\n1.發言順序應由主持人依下列類組安排發言順序：\n（1）當事人。\n（2）利害關係人。\n（3）證人、鑑定人、輔佐人及其他人員（含專家學者、相關機關\n（構）或團體代表）。\n（4）主持人或經其同意之律師、相關專業人員，得向出席聽證之\n當事人或利害關係人進行詢問，詢問內容應與案件相關，並\n請受詢者答復。\n（5）詢問當事人或利害關係人有無最後陳述。\n2.發言時間：\n（1）每一申請發言人員及受詢者答復以五分鐘為原則。主持人得\n依案情繁複衡酌分配發言時間；發言時間不因翻譯而延長。\n（2）每位發言者或每類組所分配時間結束前應有訊號提醒，發言\n時間結束時亦應以訊號提醒，發言者應立即停止發言。\n（3）未事先登記發言者如有意見表達，得透過事先登記發言者，\n於分配時間內代為陳述。\n3.相互詢答應針對發言者之提問，主持人應要求下列受詢者回答：\n（1）當事人。\n（2）利害關係人。\n（3）證人、鑑定人、輔佐人。\n（4）專家學者。\n（5）相關機關（構）及團體代表。\n（6）相關專業人員或其他熟諳法令之人員。\n（六）每回進行相互詢答時，應確認所有擬發問人員後，依上述順序相互\n發問及答復；同一方有數位發問者，應依彼此洽定或主持人排定之\n發問順序進行。\n（七）發問內容應限於與案件有關之問題。\n（八）發言者未充分闡述之意見得再發言。但發言次數應以二輪為限。\n十三、受通知人於聽證時，得陳述意見、提出證據，經主持人同意後得對機\n關指定之人員、證人、鑑定人、其他當事人或其代理人提出詢問，所\n詢問內容應以與案 件相關者為限。\n十四、主持人應本中立公正之立場，於聽證時，得行使下列職權：\n（一）就事實或法律問題，詢問受通知人、其他到場人，或促其提出證\n據。\n（二）依職權或受通知人之申請，委託相關機關為必要之調查。\n（三）通知證人或鑑定人到場。\n（四）依職權或申請，通知或允許其他關係人參加聽證。\n（五）許可受通知人及其他到場人之發問或發言。\n（六）為避免延滯程序之進行，禁止受通知人或其他到場人之發言；有\n妨礙聽證程序而情節重大者，並得命其退場。\n（七）受通知人一部或全部無故缺席者，逕行開始、延期或終結聽證。\n（八）受通知人曾於預備聽證中提出有關文書者，得以其所載內容視為\n陳述。\n（九）認為有必要時，於聽證期日結束前，決定繼續聽證之期日及場所。\n（十）如遇天災或其他事故不能聽證時，得依職權或受通知人之申請，\n中止聽證。\n（十一）採取其他為順利進行聽證所必要之措施。 主持人依前項第九款\n決定繼續聽證之期日及場所者，應通知未到場之受通知人。\n十五、聽證開始後，有下列情事之一者，主持人得依職權或當事人之申請，中\n止聽證程序：\n（一）提出之文書或證據等資料，於聽證中無法確認或證實，且對聽證有\n重大影響。\n（二）個案事實或爭議事由另有應行調查釐清事項。\n（三）參加聽證者有違反第十六點情事，經制止仍不聽從，嚴重影響聽證\n之進行。\n（四）現場秩序混亂，經主持人協調仍無法進行聽證。\n（五）其他須中止聽證之情事。\n主持人作成中止聽證之決定及事由，應記明於聽證紀錄。\n十六、聽證程序進行時，當事人、利害關係人或其代表人、代理人及其他到場\n之人應 遵守下列規定：\n（一）禁止吸煙或飲食，並應關閉行動電話。\n（二）應經主持人同意，始得發言。\n（三）發言應簡明扼要，並於主持人所定發言時間內為之。\n（四）發言時應針對案件相關事項陳述意見，不得為人身攻擊。\n（五）他人發言時不得有喧嚷或鼓譟等干擾行為。\n（六）就主持人已處置或明白告知為同一問題或事項者，不得再為重複發言。\n（七）錄音、錄影或照相應於指定之媒體專區內為之。\n（八）旁聽者不得發言及發問。\n（九）不得有其他妨礙聽證程序秩序、影響聽證場所安全或其他干擾聽證進\n行之行為。\n十七、受通知人認為主持人於聽證程序進行中所為之處置違法或不當者，得即時\n聲明異議。主持人認為異議有理由者，應即撤銷原處置，認為無理由，應\n即駁回異議。\n十八、聽證應作成聽證紀錄，並應載明到場人所為陳述或發問之要旨及其提出之\n文書、證據，並記明當事人於聽證程序中聲明異議之事由及主持人對異議\n之處理。\n紀錄應詳實記載，並記載陳述或發問之要旨為原則，陳述或發問人所提書\n面意見，並得以聽證紀錄之附件方式為之。陳述或發問人書面與言詞不一\n致時，以書面為準。紀錄當場製作完成者，由陳述或發問人簽名或蓋章；\n未當場製作完成者，由主持人指定日期、場所供陳述或發問人閱覽並簽名\n或蓋章，不克前來 者得授權代理人閱覽並簽名或蓋章。\n前項情形，陳述或發問人拒絕簽名、蓋章或未於指定日期、場所閱覽者，\n應記明其事由。\n陳述或發問人對聽證紀錄之記載有異議者，得當場即時提出。主持人認異\n議有理由者，應予更正或補充，如有增刪修改情形時，應於增刪修改處簽\n名或蓋章； 無理由者，應記明其異議。\n十九、聽證紀錄經確認後，應提送審議會，斟酌全部聽證紀錄，說明採納及不採\n納之理由作成決定後，應納入核定之都市更新事業計畫或權利變換計畫。\n二十、聽證終結後，決定作成前，經本府或經審議會認為有必要時，得再為聽證。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000838","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 113 年 07 月 03 日","法規名稱":"屏東縣政府辦理都市更新聽證程序作業要點","法規體系":"城鄉發展處","發文字號":"屏府城都字第1130028470號 函"},"promulgation_date":"2024-07-03","revision_date":"2024-07-03","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000838","status":"unknown","title":"屏東縣政府辦理都市更新聽證程序作業要點","last_checked_at":"2026-10-06T17:32:02+08:00","last_success_at":"2026-10-06T17:32:02+08:00","verification_status":"fetched","content_hash":"938d277c74ff71f708952eb98de0eabe773b414374e72acf4fb5d89f4c2dc3a8","history":[{"observed_at":"2026-10-06T17:32:02+08:00","content_hash":"938d277c74ff71f708952eb98de0eabe773b414374e72acf4fb5d89f4c2dc3a8","change_kind":"initial","revision_date":"2024-07-03"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"附件-非都市土地「交通用地」廢止申請書、附表-屏東縣政府辦理非都市土地交通用地廢止標準作業流程說明.pdf","url":"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=11818&id=GL000911&type=LAW"}],"authority":"屏東縣政府","category":"建築管理相關","content":"一、屏東縣政府（以下簡稱本府）為辦理屏東縣非都市土地編定為交\n通用地(以下簡稱交通用地)申請廢止事項，特訂定本程序。\n二、本程序適用對象為申請之土地登記簿謄本內使用地類別為「交通\n用地」，且現況已非作道路使用須辦理申請廢止之土地。\n三、申請核發交通用地廢止證明文件，應由土地所有權人或管理人檢\n附下列資料向本府提出申請，並得出具委託書委託他人代理：\n(一)申請書（如附件）。\n(二)土地所有權人同意書。但申請人為土地所有權人者，免附。\n(三)概略位置圖及現況照片。\n(四)最近三個月內地政機關核發之土地登記簿謄本及地籍圖。\n經本府審核同意後辦理公告三十日以上徵求異議，利害關係人於\n徵求異議公告期間內；得檢附相關證明文件以書面向該土地所在\n地鄉（鎮、市）公所或本府提出異議。\n四、申請廢止交通用地，經本府或道路管理機關審認，部分範圍為供\n公眾通行道路，須辦理土地分割時，其複丈相關規費由申請人負\n擔。\n五、交通用地因地理環境或人文狀況改變，喪失其原有功能者，本府\n得主動檢討廢止。\n六、本府確認無道路使用需求，並於第三點第二項公告期間經過後，\n無異議或異議無理由者，得核發交通用地廢止證明文件並向本府\n申請變更編定為適當使用地及辦理異動程序。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000911","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 115 年 04 月 08 日","圖表附件":"附件-非都市土地「交通用地」廢止申請書、附表-屏東縣政府辦理非都市土地交通用地廢止標準作業流程說明.pdf","法規名稱":"屏東縣政府辦理非都市土地交通用地廢止作業程序","法規體系":"工務處","發文字號":"屏府工土字第1150053792號 函"},"promulgation_date":"2026-04-08","revision_date":"2026-04-08","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000911","status":"repealed","title":"屏東縣政府辦理非都市土地交通用地廢止作業程序","last_checked_at":"2026-10-06T17:32:12+08:00","last_success_at":"2026-10-06T17:32:12+08:00","verification_status":"fetched","content_hash":"f2439c67c1525160c8a3d5ed38564bba4bebdd74bdb258170e3672ad49ec9449","history":[{"observed_at":"2026-10-06T17:32:12+08:00","content_hash":"f2439c67c1525160c8a3d5ed38564bba4bebdd74bdb258170e3672ad49ec9449","change_kind":"initial","revision_date":"2026-04-08"}],"version_count":1,"attachment_hashes":{"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=11818&id=GL000911&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"屏東縣政府道路管理維護經費補助及考核要點-附件1及附件2.doc","url":"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=646&id=GL000207&type=LAW"}],"authority":"屏東縣政府","category":"建築管理相關","content":"一、屏東縣政府（以下簡稱本府）為補助本縣各鄉（鎮、市）公所辦理轄\n管道路管理及養護工作，以維護用路行人行車安全，依據屏東縣道路\n管理自治條例第四條第一項第二款及第五款規定，訂定本要點。\n二、補助範圍為本縣各鄉（鎮、市）公所維護管理之市區道路、村里聯絡\n道路、農路、重劃區道路等道路之管理及維護。\n三、經費補助分配原則如下：\n(一)各鄉（鎮、市）當年度十二月份人口數（鄉鎮市人口數未滿依萬人\n者，以一萬人計算）占年度預算百分之十。\n(二)都市計畫市區道路面積（滿州鄉及無都市計畫者，依各鄉（鎮、市\n）都市計畫市區道路面積最小者計算）占年度預算百分之二十五。\n(三)各鄉（鎮、市）區域面積（山地鄉及滿州鄉區域面積以平地鄉區域\n面積最小者計算）占年度預算百分之十五。\n(四)各鄉（鎮、市）分級補助（補助比例第一級：第二級：第三級為一\n：三：六）占年度預算百分之三十：第一級鄉（鎮、市）為屏東市\n、恆春鎮、東港鎮、潮州鎮等；第二級鄉（鎮、市）為南州鄉、崁\n頂鄉、九如鄉、里港鄉、高樹鄉、竹田鄉、內埔鄉、麟洛鄉、車城\n鄉、枋寮鄉、佳冬鄉、林邊鄉、新園鄉、萬丹鄉、鹽埔鄉、新埤鄉\n、萬巒鄉、長治鄉、琉球鄉等；第三級鄉（鎮、市）為牡丹鄉、三\n地門鄉、霧台鄉、瑪家鄉、春日鄉、滿州鄉、來義鄉、獅子鄉、泰\n武鄉、枋山鄉等。\n(五)道路管理養護績效（含道路施工品質、執行路平專案及完工付款延\n遲等內容），占年度預算百分之二十：依前一年度實際考核結果核\n配。\n四、各鄉（鎮、市）公所應依本補助經費確實辦理道路管理及養護工作，\n並就下列工作項目經常辦理，以維用路人行車安全：\n(一)道路坑洞巡查、修補工作。\n(二)橋梁巡查及緊急處置工作。\n(三)道路交通標誌標線工作。\n(四)交通安全警戒設備及瀝青包料購置。\n(五)有影響安全之虞道路附屬設施其新設維護工作。\n(六)其他道路管理及維護必要之工作（含路平專案、側溝清淤、道路清\n潔通報及處置等）。\n前揭經費如有不足，由鄉（鎮、市）公所自行籌應，本府不另補助。\n五、各鄉（鎮、市）公所若未依前點第一款至第四款規定辦理者，次年度\n酌予取消部分補助經費。\n六、本補助應專款專用，並以納入預算方式辦理。\n七、各鄉（鎮、市）公所應於年度開始一月底前，依本府核定之預算分配\n數，檢齊納入預算證明、收據等文件向本府請領補助款。\n八、本府於當年度十月底前辦理各鄉（鎮、市）公所道路管養績效考核，\n並於當年度年底前依考核結果及次年度預算召開經費及檢討會議。\n九、本府考核作業共分為書面考核（占考核作業百分之四十）及現地考核\n（占考核作業百分之六十）二部份，書面考核應提供核定預算辦理之\n各項工作經費簽陳、工程契約、施工前中後照片及經費支用統計分析\n表等文件，以供查核；現地考核由考核人員隨機選定現場實地考核（\n考核表格如附件一、二）。\n十、本府考核結果，經評定年度計畫執行績優者，得酌予增加補助款予以\n獎勵；執行不佳者，除不可抗拒因素外，應酌予減列該各鄉（鎮、市\n）公所次年度補助款。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000207","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"修正日期":"民國 103 年 11 月 04 日","公發布日":"民國 102 年 11 月 01 日","圖表附件":"屏東縣政府道路管理維護經費補助及考核要點-附件1及附件2.doc","法規名稱":"屏東縣政府道路管理維護經費補助及考核要點","法規體系":"工務處","發文字號":"屏府工養字第10373438800號 函"},"promulgation_date":"2013-11-01","revision_date":"2014-11-04","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000207","status":"unknown","title":"屏東縣政府道路管理維護經費補助及考核要點","last_checked_at":"2026-10-06T17:32:11+08:00","last_success_at":"2026-10-06T17:32:11+08:00","verification_status":"fetched","content_hash":"c3189caf7efb40363504f940db8090def8a485aabe214e798bf364c7749b2e52","history":[{"observed_at":"2026-10-06T17:32:11+08:00","content_hash":"c3189caf7efb40363504f940db8090def8a485aabe214e798bf364c7749b2e52","change_kind":"initial","revision_date":"2014-11-04"}],"version_count":1,"attachment_hashes":{"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=646&id=GL000207&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"一、屏東縣政府（以下簡稱本府）為審議事業概要、都市更新事業計畫、權利變換計畫與處\n理實施者與相關權利人有關爭議，依都市更新條例第二十九條及各級都市更新及爭議處\n理審議會設置辦法規定，設屏東縣政府都市更新及爭議處理審議會（以下簡稱本會），\n並為規範本會之組成及運作，特訂定本要點。\n二、本會辦理事項如下：\n(一)有關都市更新事業概要之擬訂及變更之審議。\n(二)有關都市更新事業計畫之擬訂及變更之審議。\n(三)有關權利變換計畫之擬訂及變更之審議。\n(四)有關權利變換相關爭議事項之處理。\n(五)處理實施者與相關權利人有關爭議之協調事項。\n(六)針對審議案件內容提出建議事項。\n(七)其他有關都市更新之交議及研究建議事項。\n三、本會置委員十七人至二十七人，其中一人為召集人，由縣長或其指派人員兼任；一人為\n副召集人，由本府城鄉發展處處長兼任；其他委員由本府就下列人員聘（派）兼之：\n(一)本府都市更新業務之主管及相關機關代表。\n(二)具有都市計畫、建築、景觀、社會、法律、交通、財務、土地開發、估價、地政或\n其他相關專門學識經驗之專家學者。\n(三)都市更新事務之民間相關團體代表或社會公正人士。\n前項委員任期一年，期滿得續聘（派）兼之，任期內出缺時，應補聘（派）兼至原任期\n屆滿之日止。但機關代表職務異動時，各機關應依程序改派，其任期至原任期屆滿之日\n止。\n依第一項第二款及第三款規定聘兼之委員，不得少於委員人數二分之一。\n依第一項第二款及第三款規定聘兼之委員，續聘以連續三次為限，且每次改聘不得超過\n該二款委員人數二分之一。\n本會任一性別委員，不得少於委員人數三分之一。\n四、本會視業務需要不定期召開會議，由召集人召集並為主席；召集人因故不能出席時，由\n副召集人代理；召集人及副召集人均不能出席時，得由出席委員互推一人代理之。\n五、本會應於開會前三日將議事日程及有關資料送達各委員。但緊急性之臨時會議，不在此\n限。\n六、本會會議應有過半數委員之出席，出席委員過半數之同意始得作成決議；正反意見同數\n時，由主席裁決。\n本會委員應親自出席本會會議及參與表決，不得代理。但機關代表之委員，因故不能親\n自出席時，得指派代表出席，並參與會議發言及表決。\n七、本會開會時，得邀請土地及建築物所有權人、權利關係人、土地管理機關、實施者或其\n委託之代表列席說明，並於說明完畢後退席。列席人員發言超出議案範圍或涉及個人問\n題時，會議主席得制止或停止其發言，其有破壞議場秩序及無禮辱罵情事者，會議主席\n得制止之，並要求其離開會場。\n八、本會委員之迴避，依行政程序法第三十二條及第三十三條規定辦理。\n迴避之委員，不計入出席及表決委員之人數。\n九、本會為審議案件或處理爭議需要，得推派委員或指派業務有關人員組成專案小組調查並\n研擬意見，提供會議討論或參考。必要時，並得邀請其他專家學者、委託專業團體或機\n構協助提供技術性諮商。\n十、本會委員及工作人員均為無給職。但非本府人員兼任者，得依規定支給交通費及出席費\n。\n十一、本會所需之經費，由本府編列預算支應。\n十二、本會委員名單、會議議程及會議紀錄等相關資訊，應公開於網際網路。\n十三、本會決議事項，以本府名義行之。\n十四、本要點自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000826","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"修正日期":"民國 113 年 01 月 11 日","公發布日":"民國 106 年 09 月 26 日","法規名稱":"屏東縣政府都市更新及爭議處理審議會設置要點","法規體系":"城鄉發展處","發文字號":"屏府城都字第11275289400號 函"},"promulgation_date":"2017-09-26","revision_date":"2024-01-11","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000826","status":"unknown","title":"屏東縣政府都市更新及爭議處理審議會設置要點","last_checked_at":"2026-10-06T17:32:01+08:00","last_success_at":"2026-10-06T17:32:01+08:00","verification_status":"fetched","content_hash":"1da6d89e30b071d908e777ef1cd56a8fbfc36a8d66d3003fab67605a7f37cef1","history":[{"observed_at":"2026-10-06T17:32:01+08:00","content_hash":"1da6d89e30b071d908e777ef1cd56a8fbfc36a8d66d3003fab67605a7f37cef1","change_kind":"initial","revision_date":"2024-01-11"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"一、屏東縣政府(以下簡稱本府)為督導並推動本縣都市更新政策，協調本府\n主導都市更新業務，依都市更新條例第十一條規定，設屏東縣政府都市\n更新推動小組(以下簡稱本小組)，並為規範本小組之組成及運作，特訂\n定本要點。\n二、本小組任務如下：\n（一）議定本府主導都市更新執行策略。\n（二）跨局處協調推動本府主導都市更新事項。\n（三）控管及督導本府主導都市更新案執行進度。\n（四）其他本府主導都市更新協調及推動有關事項。\n三、本小組置委員九至十三人，其中一人為召集人，由縣長兼任；一人為副\n召集人，由秘書長兼任；其他委員由本府就下列人員或其指派代表聘（\n派）兼之：\n（一）本府城鄉發展處代表。\n（二）本府地政處代表。\n（三）本府工務處代表。\n（四）本府交通旅遊處代表。\n（五）本府民政處代表。\n（六）本府財稅局代表。\n（七）具都市計畫、都市更新、建築、不動產估價、法律及金融等相關學\n識經驗專家或學者若干人。\n本小組委員單一性別比例應不低於總人數三分之一。\n四、本小組委員任期四年，期滿得續聘（派）兼之。任期內出缺時，得補聘\n（派）至原任期屆滿之日止。但機關代表職務異動時，各機關應依程序改\n派，其任期至原任期屆滿之日止。\n五、本小組置執行秘書一人，由本府城鄉發展處處長兼任，承召集人之命，\n綜理組務；並設置工作人員若干人，由本府城鄉發展處派員兼任。\n六、本小組因應業務需要，得隨時召開會議，由召集人召集並為主席；召集\n人因故不能出席時，由副召集人代理；召集人及副召集人均不能出席時\n，得由委員互推一人代理之。\n本小組委員應親自出席會議。但機關代表之委員未能親自出席時，得指\n派代表代理之。\n七、本小組開會時，得視個案性質及實際需要，邀請中央及地方有關機關（\n構）人員、專家或學者列席提供意見。\n八、本小組對外行文以本府名義行之。\n九、本小組委員、執行秘書及工作人員均為無給職。但非本府人員兼任者，\n得依規定支領出席費及交通費等相關費用。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000840","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 113 年 07 月 10 日","法規名稱":"屏東縣政府都市更新推動小組設置要點","法規體系":"城鄉發展處","發文字號":"屏府城都字第1130033816號函"},"promulgation_date":"2024-07-10","revision_date":"2024-07-10","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000840","status":"unknown","title":"屏東縣政府都市更新推動小組設置要點","last_checked_at":"2026-10-06T17:32:02+08:00","last_success_at":"2026-10-06T17:32:02+08:00","verification_status":"fetched","content_hash":"e017e75a1f140c92ab122a920ba98e3934f0de33e0f2142653ce336f6e57e5dc","history":[{"observed_at":"2026-10-06T17:32:02+08:00","content_hash":"e017e75a1f140c92ab122a920ba98e3934f0de33e0f2142653ce336f6e57e5dc","change_kind":"initial","revision_date":"2024-07-10"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"一、為落實屏東縣政府（以下簡稱本府）都市計畫容積移轉代金（以下\n簡稱本代金）專款專用，特訂定本要點。\n二、本要點執行單位為本府城鄉發展處。\n三、本要點所稱代金，指依屏東縣政府都市計畫容積移轉審查許可要點\n第七點規定，所折繳之代金。\n四、本代金之用途，應依都市計畫容積移轉實施辦法第九條之一第二項\n規定辦理。\n五、執行單位應於每年三月底前彙編本代金收支統計表，供本府各需地\n機關編列公共設施保留地取得計畫概算。\n六、本府各需地機關使用本代金時，應循年度預算編審程序辦理，並註\n明都市計畫區名稱及金額。\n本府各需地機關應將其上年度實際支用本代金情形，於每年二月底\n前，函送執行單位。\n七、各都市計畫區年度代金收支之決算有餘額者，得繼續使用之。但不\n得逾三個年度。逾前項但書期限仍未使用完畢之代金，由執行單位\n辦理歲入退還；如有使用需求時，再納入預算編審程序辦理。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000837","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 113 年 06 月 26 日","法規名稱":"屏東縣政府都市計畫容積移轉代金收支作業要點","法規體系":"城鄉發展處","發文字號":"屏府城都字第1130012278號函"},"promulgation_date":"2024-06-26","revision_date":"2024-06-26","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000837","status":"unknown","title":"屏東縣政府都市計畫容積移轉代金收支作業要點","last_checked_at":"2026-10-06T17:32:01+08:00","last_success_at":"2026-10-06T17:32:01+08:00","verification_status":"fetched","content_hash":"a919e0833700f05fd23924093ccaf28ec340b3763734815947629d2a39636097","history":[{"observed_at":"2026-10-06T17:32:01+08:00","content_hash":"a919e0833700f05fd23924093ccaf28ec340b3763734815947629d2a39636097","change_kind":"initial","revision_date":"2024-06-26"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"屏東縣都市計畫容積移轉許可審查要點附圖一及附圖二.pdf","url":"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=11657&id=GL000507&type=LAW"},{"name":"02.容移_附件一.pdf","url":"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=1365&id=GL000507&type=LAW"},{"name":"03.容移_書件1.pdf","url":"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=1467&id=GL000507&type=LAW"},{"name":"04.容移_書件2.pdf","url":"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=1466&id=GL000507&type=LAW"},{"name":"05.容移_書件3.pdf","url":"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=1368&id=GL000507&type=LAW"},{"name":"06.容移_書件4.pdf","url":"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=1369&id=GL000507&type=LAW"},{"name":"07.容移_書件5.pdf","url":"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=1370&id=GL000507&type=LAW"}],"authority":"屏東縣政府","category":"建築管理相關","content":"一、屏東縣政府（以下簡稱本府）為辦理都市計畫容積移轉申請案件，\n特依都市計畫容積移轉實施辦法（以下簡稱本辦法）第四條第一項\n規定訂定本要點。\n都市計畫容積移轉審查許可事項，除本辦法、其他中央法令或各該\n都市計畫書另有規定外，應依本要點規定辦理。但已依古蹟土地容\n積移轉辦法或其他法令申請容積移轉之土地，不得同時適用本要點\n。\n二、送出基地以下列各款土地為限：\n（一）依文化資產保存法公告之歷史建築所定著之土地或都市計畫指定\n應予保存之地區。\n（二）為改善都市環境或景觀，提供作為公共開放空間使用之可建築土\n地。\n（三）經都市計畫法劃定之公共設施保留地，包括：\n1.公園用地\n2.兒童遊樂場用地\n3.公園兼兒童遊樂場用地\n4.綠地（帶）\n5.廣場用地\n6.廣場兼停車場用地\n7.停車場用地\n8.道路用地\n9.學校（中小學)用地\n10.溝渠用地\n11.排水道用地\n12.園道用地\n13.人行廣場用地\n前項送出基地不含都市計畫書規定應以區段徵收、市地重劃或其他\n方式整體開發地區共同負擔之公共設施用地。\n送出基地申請範圍內之土地所有權人，除公有土地外須全數同意辦\n理容積移轉。\n三、接受基地應以下列使用分區為限：\n（一）位於住宅區之土地，且符合下列各款情形之一：\n1.基地面積達五百平方公尺以上，臨接寬度達八公尺以上之\n計畫道路，且臨接道路長度達二十五公尺以上或大於基地\n周長之六分之ㄧ。\n2.基地面積達一千平方公尺以上，臨接寬度達十二公尺以上\n之計畫道路，且臨接道路長度達二十五公尺以上或大於基\n地周長之六分之ㄧ。\n（二）位於商業區之土地，且符合下列各款情形之一：\n1.基地面積達一千平方公尺以上，臨接寬度達八公尺以上之\n計畫道路，且臨接道路長度達二十五公尺以上或大於基地\n周長之六分之ㄧ。\n2.基地面積達一千平方公尺以上，臨接寬度達十公尺以上之\n計畫道路，且臨接道路長度達二十五公尺以上或大於基地\n周長之六分之ㄧ。\n（三）經都市計畫指定之地區，並符合該都市計畫之容積移轉相關\n規定。\n前項接受基地不得有下列各款情形之一：\n（一）已領有使用執照之土地辦理增建。\n（二）位於山坡地範圍內土地。\n（三）依本縣各都市計畫規定或原擬定機關公告禁止容積移轉、獎\n勵地區之土地。\n（四）經本縣都市計畫委員會決議，並由本府公告禁止容積移轉地\n區之土地。\n（五）文化資產定著土地所在街廓，或因文化資產因素而須辦理都\n市設計審議之地區(如附件一所示)。\n（六）依其他相關法令規定禁止容積移轉之土地。\n接受基地應以一宗建築基地為限，且接受基地範圍應與都市設計審\n議範圍及申請建造執照範圍一致。\n四、送出基地所有權人依本要點提出移出容積之意願後，應經送出基地\n目的事業主管機關同意受贈。\n五、第三點第一項第一款第一目、第二款第一目接受基地可移入容積，\n以基準容積之百分之二十為限；第三點第一項第一款第二目、第二\n款第二目接受基地可移入容積，以基準容積之百分之三十為限。\n位於整體開發地區、實施都市更新地區或其他都市計畫指定地區範\n圍內接受基地之可移入容積，經屏東縣都市設計審議委員會審議通\n過者，得酌予增加，但最高不得超過基準容積之百分之四十。\n接受基地依本要點移入之容積加計其他依法規規定予以獎勵之容積\n總和，不得超過各該建築基地法定容積之百分之五十。\n前項容積總和不含都市更新獎勵容積。\n六、依水利法第八十二條規定經水利主管機關核定實施計畫之河川區域\n，得依本要點規定辦理容積移轉。其送出基地之土地公告現值，依\n水利法第八十二條第五項規定辦理。\n七、接受基地得以折繳代金方式移入容積，其折繳代金之金額，由本府\n委託三家以上專業估價者查估；必要時，查估工作得由本府辦理。\n其所需費用，由申請人負擔。\n八、接受基地、送出基地之土地達二筆以上者，其土地公告現值應按申\n請容積移轉當期各接受基地、送出基地土地公告現值，以面積加權\n平均計算之。接受基地二筆以上，且位於不同土地使用分區者，其\n容積率以面積加權平均計算之。\n九、容積移轉申請案件應與其他依法規規定予以獎勵之容積併同申請。\n前項增加之容積總和超過其基準容積之百分之三十者，由本府都市\n設計審議委員會審查；其餘者由本府容積移轉業務單位審查許可。\n前項審議過後始得向本府申請核發容積移轉初步認定函。\n十、接受基地經本縣都市設計審議通過後，除第二點第一項第一款之送\n出基地外，申請人應於取得本縣核發容積移轉初步認定函之日起一\n年內完成下列事項，始得向本府申請核發容積移轉許可函：\n（一）取得送出基地所有權。\n（二）清理送出基地上土地改良物、租賃契約、他項權利及限制登記\n等法律關係。\n（三）將送出基地土地產權贈與送出基地土地管理機關並辦理移轉登\n記。\n（四）向本府繳納代金完竣。\n因容積移轉及土地產權移轉登記所需之土地登記規費、印花稅及其\n他稅捐等均由申請人負擔之。\n容積移轉初步確認函於必要時得申請延長有效期限一次，延長時間\n不得超過六個月。逾期之容積移轉初步確認函本府得予撤銷。\n十一、容積移轉許可後，應由本府建築管理單位及地政機關依本辦法第\n十九條規定建檔。\n十二、容積移轉申請案應檢附下列文件，向本府提出之：\n（一）屏東縣政府都市計畫容積移轉許可審查要點申請查核表。\n【書件1】\n（二）屏東縣政府都市計畫容積移轉許可審查申請書。【書件2】\n（三）都市計畫容積移轉許可審查計算表。【書件3】\n（四）送出基地所有權人及權利關係人同意書。【書件4】\n（五）送出基地及接受基地土地所有權狀影本。\n（六）送出基地及接受基地之土地使用分區證明書。\n（七）送出基地及接受基地之土地登記簿謄本、地籍圖謄本、現\n況照片、都市計畫位置圖。\n（八）接受基地之建築線指示（定）圖。\n（九）接受基地鄰近地區公共設施服務品質與交通影響之分析資\n料。\n（十）切結書。【書件5】\n（十一）其他經本府認為必要之文件。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000507","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"修正日期":"民國 113 年 06 月 26 日","公發布日":"民國 107 年 02 月 05 日","圖表附件":"屏東縣都市計畫容積移轉許可審查要點附圖一及附圖二.pdf 02.容移_附件一.pdf 03.容移_書件1.pdf 04.容移_書件2.pdf 05.容移_書件3.pdf 06.容移_書件4.pdf 07.容移_書件5.pdf","法規名稱":"屏東縣政府都市計畫容積移轉審查許可要點","法規體系":"城鄉發展處","發文字號":"屏府城都字第1130011560號函"},"promulgation_date":"2018-02-05","revision_date":"2024-06-26","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000507","status":"unknown","title":"屏東縣政府都市計畫容積移轉審查許可要點","last_checked_at":"2026-10-06T17:32:02+08:00","last_success_at":"2026-10-06T17:32:02+08:00","verification_status":"fetched","content_hash":"a5cc16d327d7ee1b7c7f3de9cf475acc6113fcbeca4a495713b5a93220639f98","history":[{"observed_at":"2026-10-06T17:32:02+08:00","content_hash":"a5cc16d327d7ee1b7c7f3de9cf475acc6113fcbeca4a495713b5a93220639f98","change_kind":"initial","revision_date":"2024-06-26"}],"version_count":1,"attachment_hashes":{"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=11657&id=GL000507&type=LAW":null,"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=1365&id=GL000507&type=LAW":null,"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=1467&id=GL000507&type=LAW":null,"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=1466&id=GL000507&type=LAW":null,"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=1368&id=GL000507&type=LAW":null,"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=1369&id=GL000507&type=LAW":null,"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=1370&id=GL000507&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"旁聽及發言申請書.doc","url":"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=399&id=GL000215&type=LAW"}],"authority":"屏東縣政府","category":"建築管理相關","content":"一、屏東縣政府（以下簡稱本府）為維持本府非都市土地使用分區及使用\n地變更專責審議小組（以下簡稱專責小組）會議之議事品質及會場秩\n序，特訂定本要點。\n二、專責小組召開非都市土地開發案件審查會議時，民眾或團體得於會議\n召開前三日，檢具書面向本府申請旁聽或發言。民眾或團體申請旁聽\n或發言者，應依審查案件之場次，按次申請。\n三、民眾或團體申請發言者，應推派一人為代表。但每一場次發言，合計\n以五人為原則。\n四、本府於會議室門口設置簽到處，以備申請發言或旁聽之民眾或團體等\n持開會通知單及身分證明文件簽到。\n五、除本府業務單位人員為製作會議紀錄之需要，得於會議室中攝影、錄\n影或錄音外，其他人員不得於會議進行中攝影、錄影或錄音。\n六、發言者表達意見應簡明扼要，每人以一至三分鐘為原則，每開發案件\n發言總時間原則不得超過二十分鐘。但主席得視會議情形在徵詢全體\n出席委員同意後，調整發言時間。發言總時間與簡報時間應衡平。\n七、專責小組會議進行案件實質討論前，發言之民眾或相關團體等均應離\n開會場。\n八、出列席會議、發言或旁聽人員，不得有下列行為：\n（一）攜帶標語、海報、各式布條、旗幟、棍棒、無線麥克風等物品，\n進入會場及會場所在辦公廳舍區域。\n（二）大聲喧嘩、鼓譟。\n（三）攜帶危險、易燃物品。\n（四）妨害會場秩序或其他不當行為。\n九、本府業務單位人員為製作會議紀錄之需要，得要求發言者提供發言書\n面內容，或經其同意由作業單位代為摘要彙整發言內容。\n十、違反第五點至第八點規定經勸阻不聽、妨礙會場議事運作順暢或其他\n不當行為者，主席或本府業務單位人員得制止或令其離開會場，必要\n時，得取消其再申請出列席會議、發言或旁聽之權利；情節重大者，\n並得移送法辦。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000215","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 102 年 12 月 03 日","圖表附件":"旁聽及發言申請書.doc","法規名稱":"屏東縣政府非都市土地使用分區及使用地變更專責審議小組會議及會場管理要點","法規體系":"城鄉發展處","發文字號":"屏府城規字第10276079300號 函"},"promulgation_date":"2013-12-03","revision_date":"2013-12-03","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000215","status":"unknown","title":"屏東縣政府非都市土地使用分區及使用地變更專責審議小組會議及會場管理要點","last_checked_at":"2026-10-06T17:31:56+08:00","last_success_at":"2026-10-06T17:31:56+08:00","verification_status":"fetched","content_hash":"ae5eb12f27505b51e35022b574c82849997e4ac526f99da3eab3d51de89010e8","history":[{"observed_at":"2026-10-06T17:31:56+08:00","content_hash":"ae5eb12f27505b51e35022b574c82849997e4ac526f99da3eab3d51de89010e8","change_kind":"initial","revision_date":"2013-12-03"}],"version_count":1,"attachment_hashes":{"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=399&id=GL000215&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"第一條    本辦法依都市更新條例(以下簡稱本條例)第四十六條第四\n項規定訂定之。\n第二條    本辦法主管機關為屏東縣政府（以下簡稱本府），執行單\n位為本府城鄉發展處。\n第三條    本條例第四十六條第四項所定一定規模，指實施者擬訂報\n核之都市更新事業計畫，其範圍內之公有土地面積占更新單元\n土地總面積比率達百分之五十以上。\n前項公有土地面積及比率之計算，不包含公共設施用地面\n積。\n第四條    本條例第四十六條第四項所定特殊原因，指都市更新事業\n計畫範圍內有下列情形之一者：\n一、更新單元範圍內公有土地已出租或遭占用之面積合計達公\n有土地總面積百分之五十以上。\n二、更新單元範圍內公私共有土地占更新單元土地總面積比率\n達百分之二十五以上。\n三、其他經本府自行評估或委託都市更新專責法人、機構評估\n，不適宜依本條例第十二條第一項規定辦理。\n第五條    本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000871","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 114 年 03 月 18 日","法規名稱":"屏東縣更新實施者擬訂報核事業計畫範圍內認定公有土地一定規模及特殊原因辦法","法規體系":"城鄉發展處","發文字號":"屏府民法字第11400714021號 令"},"promulgation_date":"2025-03-18","revision_date":"2025-03-18","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000871","status":"unknown","title":"屏東縣更新實施者擬訂報核事業計畫範圍內認定公有土地一定規模及特殊原因辦法","last_checked_at":"2026-10-06T17:31:53+08:00","last_success_at":"2026-10-06T17:31:53+08:00","verification_status":"fetched","content_hash":"e43f33b8bc8d67f6317bd3c288deb6c235c45c641c5d6d3801ff315fae4310fc","history":[{"observed_at":"2026-10-06T17:31:53+08:00","content_hash":"e43f33b8bc8d67f6317bd3c288deb6c235c45c641c5d6d3801ff315fae4310fc","change_kind":"initial","revision_date":"2025-03-18"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"附表一.pdf","url":"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=1445&id=GL000252&type=LAW"},{"name":"附表二.pdf","url":"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=1449&id=GL000252&type=LAW"}],"authority":"屏東縣政府","category":"建築管理相關","content":"第 1 條\n本辦法依據建築法第七十三條第一項但書及規費法第七條規定訂定之。\n第 2 條\n本辦法之主管機關為屏東縣政府，並得委託鄉(鎮、市)公所辦理本辦法\n所定受理申請、核發及撤銷接用水、電許可證等事項。\n第 3 條\n未領得使用執照之建築物，有下列情形之一者，得申請接用水、電之許可\n：\n一、偏遠地區且非屬都市計畫地區之建築物。\n二、因興辦公共設施所需而拆遷，具整建需要且無礙都市計畫發展之建築\n物。\n三、天然災害損壞需安置及修復之建築物。\n四、有迫切民生需要之建築物。\n前項第四款所稱有迫切民生需要之建築物，以非位於河川區、水利用地，\n且供住宅使用(住家稅率)者為限。\n第 4 條\n依本辦法申請接用水、電者，需檢附下列文件向主管機關提出:\n一、申請書一份(如附表一)。\n二、切結書(如附表二)。\n三、土地登記謄本一份。\n四、門牌證明。\n五、建築物位置圖。\n六、建築物照片。\n第 5 條\n主管機關受理前條申請案，得邀集相關權責單位至現場勘查，經審查合\n格且繳納許可證書費新臺幣一千元後，由主管機關發給許可證，並副知\n自來水及電力相關單位。\n前項許可後，申請人應於八個月內向自來水及電力相關單位申請接用水\n、電，屆期未辦理者，應重新申請許可。\n第 6 條\n依前條核發之許可證，僅供作建築物申請接用水、電之證明，不得作為\n合法建築物之依據，且不得作為營利事業場所使用。\n第 7 條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000252","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"修正日期":"民國 110 年 08 月 16 日","公發布日":"民國 103 年 04 月 21 日","圖表附件":"附表一.pdf 附表二.pdf","法規名稱":"屏東縣未領得使用執照建築物申請接用水電辦法","法規體系":"城鄉發展處","發文字號":"屏府行法字第11041443201號令"},"promulgation_date":"2014-04-21","revision_date":"2021-08-16","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000252","status":"unknown","title":"屏東縣未領得使用執照建築物申請接用水電辦法","last_checked_at":"2026-10-06T17:31:52+08:00","last_success_at":"2026-10-06T17:31:52+08:00","verification_status":"fetched","content_hash":"3beb44c560268d2f4d926ed6f502fd963d1f9d1a3b3dee5fbcaa9ac7159f16ad","history":[{"observed_at":"2026-10-06T17:31:52+08:00","content_hash":"3beb44c560268d2f4d926ed6f502fd963d1f9d1a3b3dee5fbcaa9ac7159f16ad","change_kind":"initial","revision_date":"2021-08-16"}],"version_count":1,"attachment_hashes":{"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=1445&id=GL000252&type=LAW":null,"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=1449&id=GL000252&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"第 一 章 總則\n第 1 條\n屏東縣政府（以下簡稱本府）為保護消費者權益，促進消費生活安全，提\n昇消費生活品質，特制定本自治條例。\n本縣消費者保護事項，除消費者保護法（以下簡稱本法）或中央其他法規\n另有規定者外，依本自治條例之規定。\n第 2 條\n本自治條例之主管機關為本府，並由本府各單位及所屬一級機關執行之。\n第 二 章 消費者權利之保護\n第 3 條\n企業經營者對於其提供之商品或服務，應提供消費者充分及正確之資訊，\n不得有誤導、隱瞞或欺罔之行為。\n企業經營者違反前項規定，本府應命其限期改正。\n第 4 條\n企業經營者應對所提供達一定規模之消費場所投保公共意外責任險。\n前項所稱消費場所，係指提供消費關係之場所。\n執行機關或單位對第一項之消費場所辦理建築物公共安全檢查或相關業務\n檢查時，一併查核有無投保公共意外責任險。\n第一項應投保公共意外責任險之消費場所種類、範圍及其最低投保金額等\n事項之辦法，由本府另定之。但依其他法令如有對消費者保護較有利之規\n定者，從其規定。\n第 5 條\n企業經營者提供之消費場所、商品或服務於本縣發生重大災害，致消費者\n生命、身體、健康或財產遭受重大損害者，如企業經營者依法有應賠償責\n任之可能時，本府得經受害消費者或罹難者之父母、子女、配偶或法定代\n理人同意，協助其依法聲請假扣押或協助處理和解賠償事宜或提供其他必\n要之法律服務援助。\n前項重大災害之認定及協助範圍等事項，由本府核定。\n第 6 條\n企業經營者使用定型化契約，應符合誠實信用及平等互惠原則，並不得違\n反中央目的事業主管機關公告定型化契約應記載、不得記載之事項或審閱\n期間。\n企業經營者使用定型化契約，本府得隨時派員查核；其有違反前項規定者\n，應命其限期改正。\n定型化契約未記載中央主管機關公告應記載事項者，視為已記載。\n定型化契約記載中央主管機關公告不得記載事項者，視為未記載。\n定型化契約中之一般條款牴觸中央主管機關公告應記載事項者，其效力依\n應記載事項定之。\n第 7 條\n企業經營者於訂立郵購買賣或訪問買賣契約時，應告知消費者下列事項，\n並取得消費者聲明已受告知之證明文件：\n一、買賣之條件、出賣人之姓名、名稱、負責人、事務所或住居所及連絡\n電話。\n二、消費者得於收受商品或服務後七日內退回商品，或以書面通知企業經\n營者解除契約，無須說明理由及負擔任何費用或價款。\n企業經營者違反前項規定，本府應命其限期改正。\n第 三 章 消費者保護團體\n第 8 條\n本府於必要時，得委託消費者保護團體辦理下列事項：\n一、為商品或服務價格、品質及標示之調查、比較、檢驗、研究。\n二、消費者意見之調查、分析、歸納。\n三、消費者教育宣導工作。\n四、其他有關消費者保護業務事項。\n第 9 條\n對於協助本縣推展消費者保護工作著有成效者，得由本府頒發獎狀、獎牌\n或給予經費之補助。\n第 四 章 消費者保護組織與行政\n第 10 條\n本府為統籌、協調及規劃本縣消費者保護業務之推動，應設消費者保護委\n員會；其設置要點，由本府另定之。\n第 11 條\n本府為保護消費者權益與推動消費者保護業務，應置消保官及承辦相關業\n務人員。\n第 12 條\n本府應設消費者服務中心，辦理消費者諮詢服務、申訴、教育宣導及其他\n有關消費者保護綜合行政業務等事項，並得設消費者服務分中心。\n第 13 條\n本府應設消費爭議調解委員會，置委員七人至十五人，辦理本縣消費爭議\n之調解，任期二年，連聘得連任，除消保官為當然委員並為主席外，其餘\n委員由本府遴聘本府代表、消費者保護團體推派代表、企業經營者所屬或\n相關職業團體推派代表共同組成。\n前項消費者保護團體與企業經營者所屬或相關職業團體之代表人數應相同\n。\n第 14 條\n消費者服務中心應於年度開始前，彙整各執行機關或單位所提消費者保護\n執行事項，擬訂本縣年度消費者保護方案，提請本府消費者保護委員會通\n過，並陳報行政院消費者保護委員會核定後據以執行。\n前項年度消費者保護方案之執行，應由各執行機關或單位予以列管，並於\n每年一月底前，就其上一年度辦理情形，報本府備查。\n第 15 條\n本府應辦理下列消費者教育、宣導事項：\n一、將消費警訊適時於媒體或網路上公布並廣為宣導。\n二、舉辦消費者權利教育、宣導。\n三、編印消費者教育手冊。\n四、辦理充實本府及所屬機關人員消費者保護知能訓練與講習。\n五、辦理本縣各級學校教師消費者保護知能訓練，俾其向學生宣導消費者\n保護知識。\n六、對企業經營者宣導消費者保護法令及理念。\n七、將各項與消費者有關資訊，適時主動於網路或媒體公布。\n第 五 章 消費者保護行政監督\n第 16 條\n企業經營者提供之商品或服務有損害消費者生命、身體、健康、財產之虞\n者，應即依本法第三十三條第二項進行調查，於調查完成後，得公開其經\n過及結果。但在公開其經過及結果前，應給予企業經營者說明之機會。\n經前項調查結果，如認為確有損害消費者生命、身體、健康、財產或確有\n損害之虞者，應依本法第三十六條命企業經營者限期改善、回收或銷燬，\n必要時並得命其立即停止該商品之設計、生產、製造、加工、輸入、經銷\n或服務之提供，或採取其他必要措施。\n第 17 條\n企業經營者提供之商品、服務或消費場所對消費者已發生重大損害，或有\n發生重大損害之虞而情況危急時，除為前條第二項之處置外，應即在網路\n或媒體公告企業經營者之名稱、地址、商品、服務或為其他必要之處置。\n第 18 條\n處理消費爭議案件，發現企業經營者有下列不當銷售行為之一，得移請行\n政院公平交易委員會處理：\n一、為訪問買賣時，以提供無償服務、檢查、贈品為名，行銷售商品或服\n務之實者。\n二、所為行為、言詞或廣告，使消費者誤信為政府機關、公益團體或其他\n企業經營者之人員而與其為交易行為者。\n三、所為行為、言詞或廣告，使消費者誤信有購入、設置、利用商品或服\n務之法令上義務，或其已取得政府機關、公益團體或其他企業經營者\n之許可、認可、授權、推薦而與其為交易行為者。\n四、刊登不實廣告、引人錯誤之表示或其他涉嫌有足以影響交易秩序之欺\n罔或顯失公平之行為者。\n第 19 條\n處理消費爭議案件，發現企業經營者有下列情形之一，得將其名稱、地址\n、爭議商品或服務及所為行為於網路或媒體公告之：\n一、經通知前來說明消費爭議案情、商議解決方法或進行調解，無正當理\n由不派員出席者。\n二、參加前款消費爭議案件協商獲致協議或調解成立，無正當理由不履行\n者。\n三、拒絕接受消費者依本法第十九條第一項規定退還商品或解除契約者。\n第 20 條\n執行人員在本縣轄區外對企業經營者進行調查時，應會同該管直轄市、縣\n（市）政府或消保官辦理。依調查結果，認為有依本法第五十七條至第五\n十九條規定處罰時，應將全案移請該管直轄市、縣（市）政府處理。\n第 21 條\n執行人員於進行調查時，得請警察機關派員協同辦理。\n第 六 章 消費爭議之處理\n第 22 條\n消費者與企業經營者間因商品或服務發生消費爭議，符合下列情形之一，\n消費者得向本府消費者服務中心申訴：\n一、企業經營者之營業所或事務所所在地在本縣者。\n二、契約訂立地或履行地在本縣者。\n三、侵權行為之行為地或結果地在本縣者。\n第 23 條\n消費者服務中心受理申訴案件，應依其性質移送各執行機關或單位處理。\n執行機關或單位處理消費爭議申訴案件，應依下列程序辦理，並將處理情\n形副知本府消費者服務中心：\n一、涉及有無違反主管業務法規或其解釋、適用問題者，應依相關法規查\n處，函復申訴人；其屬通案性質者，並副知相關同業公會轉知所屬會\n員。\n二、前款情形以外之案件，應函請企業經營者於文到之日起十五日內妥適\n處理逕復申訴人，並副知本府；如須瞭解其事實和過程者，得請企業\n經營者查復。\n三、企業經營者未予妥適處理而認申訴人有理由時，得擇期請企業經營者\n及申訴人前來說明案情，商議解決方法。\n四、經前二款方式仍未妥適處理者，應將處理結果函復申訴人及企業經營\n者，並告知申訴人得向消保官申訴或向消費爭議調解委員會申請調解\n或逕向法院提起消費訴訟。\n第 24 條\n消保官處理消費爭議申訴案件，應依下列程序辦理：\n一、未依本法第四十三條第一項規定，先行向企業經營者、消費者保護團\n體、消費者服務中心或其分中心提出申訴者，應移送消費者服務中心\n處理。\n二、非屬消費爭議或非屬本縣轄區內案件者，應移送各該管轄機關並副知\n申訴人。\n三、前二款情形以外之案件，應即函請企業經營者於文到之日起十五日內\n妥適處理逕復申訴人，並副知本府消保官；如須瞭解其事實和過程者\n，得請企業經營者、消費者服務中心、消費者保護團體或有關機關提\n供相關資料以供研議或請企業經營者查復。\n四、涉及法令規定疑義者，得送請有關機關解釋或請其提供相關資料以供\n研議。\n五、必要時得請企業經營者及申訴人前來說明案情，商議解決方法。經協\n商達成協議者，應製作協商紀錄，必要時得將紀錄函送雙方當事人；\n協商無結果時，應製作處理書函送申訴人及企業經營者，並告知申訴\n人，得向本府消費爭議調解委員會申請調解或逕向法院提起消費訴訟\n。\n第 25 條\n處理申訴或調解案件，得請有關機關或團體派員列席。\n第 26 條\n消費者依本法第四十三條規定向消費者服務中心或消保官申訴未獲妥適處\n理時，符合下列情形之一，得向本府消費爭議調解委員會申請調解：\n一、消費者或企業經營者任一方之住居所、營業所、事務所在本縣者。\n二、消費關係發生地在本縣者。\n三、消費者及企業經營者之住居所、營業所、事務所均不在本縣，且不屬\n同一直轄市、縣（市），而雙方合意向本府消費爭議調解委員會申請\n調解者。\n第 27 條\n相關人員對於處理消費爭議案件所知悉依法應予保密之資料，不得予以洩\n漏、不當利用或提供他人使用；發現有涉及刑事責任者，應移送司法機關\n處理。\n第 七 章 罰則\n第 28 條\n企業經營者違反第四條規定未投保公共意外責任險或未達最低投保金額者\n，處新臺幣二萬元以上十萬元以下罰鍰，並通知限期改正，逾期仍不改正\n者，得按月連續處罰。經連續處罰三次仍拒不改正者，應予勒令停業；如\n拒不停業者，依行政執行法規定執行斷水斷電。\n第 29 條\n企業經營者有下列情事之一，經通知限期改正而逾期不改正者，處新臺幣\n二萬元以上十萬元以下罰鍰，並得連續處罰：\n一、違反第三條第一項規定未提供消費者充分及正確資訊者。\n二、違反第六條第一項規定者。\n三、違反第七條第一項規定未告知消費者相關事項或未取得消費者聲明已\n受告知之說明文件者。\n第 八 章 附則\n第 30 條\n第四條第四項規定有關公共意外責任險投保辦法發布前已取得營利事業登\n記證明文件或其他許可證照，未投保公共意外責任險之企業經營者，應自\n該辦法發布之日起六個月內辦理補正。逾期不補正者，依第二十八條規定\n處罰。\n第 31 條\n本自治條例自公布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:FL052446","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 94 年 10 月 20 日","法規名稱":"屏東縣消費者保護自治條例","法規體系":"城鄉發展處","發文字號":"屏府行法字第0940203256號"},"promulgation_date":"2005-10-20","revision_date":"2005-10-20","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=FL052446","status":"unknown","title":"屏東縣消費者保護自治條例","last_checked_at":"2026-10-06T17:31:46+08:00","last_success_at":"2026-10-06T17:31:46+08:00","verification_status":"fetched","content_hash":"f0e596531a87909e6b2383082f8bad4d6d361e9f98fb7e6ae6279cbd28804a30","history":[{"observed_at":"2026-10-06T17:31:46+08:00","content_hash":"f0e596531a87909e6b2383082f8bad4d6d361e9f98fb7e6ae6279cbd28804a30","change_kind":"initial","revision_date":"2005-10-20"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"第一條    屏東縣政府（以下簡稱本府）為管理特定行業，特制定本自治\n條例。\n特定行業之管理及處罰，除中央法令另有規定外，依本自治條\n例規定辦理。\n第二條   本自治條例所稱特定行業，包括視聽歌唱、美容美髮服務業、\n三溫暖、舞廳、舞場、酒家、酒吧、特種咖啡茶室、資訊休閒、夜\n店及電子遊戲場等業，其定義如下：\n一、視聽歌唱業：指提供伴唱視聽設備，供人歌唱之營利事業。\n二、美容美髮服務業：指包含理髮、理容業務，將營業所加以區隔\n或包廂式經營為人理容之觀光理髮或視聽理容之營利事業。\n三、三溫暖業：指提供冷、熱水池、蒸烤設備，供人沐浴之營利事\n業。\n四、舞廳業：指提供場所，備有舞伴，供不特定人跳舞之營利事業。\n五、舞場業：指提供場所，不備舞伴，供不特定人跳舞之營利事業。\n六、酒家業：指提供場所，備有服務生陪侍，供應酒、菜或其他飲\n料之營利事業。\n七、酒吧業：指提供場所，備有服務生陪侍，供應酒類或其他飲料\n之營利事業。\n八、特種咖啡茶室業：指提供場所，備有服務生陪侍，供應飲料之\n營利事業。\n九、資訊休閒業：指提供場所及電腦資訊設備，以連線方式擷取網\n路資訊或以非連線方式結合資料儲存裝置，供不特定人從事遊\n戲娛樂之營利事業。\n十、夜店業：指從事提供酒精類飲料與音樂，及提供演奏或表演等\n服務，並備有聲光、座位及舞池等功能設施之營業場所，且主\n要營業時間為夜間至次日凌晨之營利事業。\n十一、電子遊戲場業：指電子遊戲場業管理條例第三條規定之營利\n事業。\n第三條    特定行業之營業場所應符合下列規定：\n一、營業場所位於都市計畫地區者，應符合都市計畫法及都市土地\n使用分區管制之規定；位於非都市計畫地區者，應符合區域計\n畫法及非都市土地使用管制之規定。\n二、營業場所之建築、消防、衛生及環保設施應符合其相關法令規\n定。\n前項規定於事業申請增加特定行業之變更登記時，亦適用之。\n第四條    本府應定期或不定期檢查特定行業之建築、消防、衛生、環保\n等設施。\n本府應召集警政、建管、消防、衛生、環保、稅捐、都市計畫\n、地政及商業等相關單位組成聯合稽查小組，執行前項工作。\n第五條    舞廳、舞場、酒家、酒吧、特種咖啡茶室、限制級電子遊戲場\n業、三溫暖、夜店及其他涉及賭博、色情、暴力等經主管機關認定\n足以危害其身心健康之場所等業應於營業場所出入口明顯，張貼未\n滿十八歲者禁止進入之標示，且不得僱用未滿十八歲之青少年。\n第五條之一    有下列情形之一者，不得充任特定行業之代表人、負責人\n或營業場所管理人：\n一、無行為能力人、限制行為能力人或受輔助宣告之人。\n二、曾犯刑法第十六章妨害性自主罪、第十六章之一妨害風化\n罪、第二百四十條至第二百四十三條之罪，或兒童及少年\n性剝削防制條例之罪，經判決確定執行完畢或赦免後未滿\n五年，或受緩刑宣告尚未期滿。\n三、曾犯組織犯罪防制條例或槍砲彈藥刀械管制條例規定之罪\n，經判決確定執行完畢或赦免後未滿十年，或受緩刑宣告\n尚未期滿。\n四、經依檢肅流氓條例裁處感訓處分確定執行完畢後未滿十年。\n五、曾犯肅清煙毒條例、麻醉藥品管理條例或管制藥品管理條\n例之罪，經判決確定執行完畢或赦免後未滿五年，或受緩\n刑宣告尚未期滿。\n六、曾犯毒品危害防制條例之罪，經觀察、勒戒、強制戒治、\n判決確定執行完畢或赦免後未滿五年，或受緩刑宣告尚未\n期滿。\n第五條之二    特定行業之營業場所發現顧客有下列情事之一者，應即通\n報警察機關處理：\n一、攜帶違禁物品。\n二、鬥毆或酗酒滋事。\n三、其他影響公共秩序。\n第六條    本府得隨時派員檢查特定行業之營業狀況。\n特定行業負責人及從業人員不得規避、拒絕或妨礙前項檢查。\n第七條    特定行業應投保公共意外責任險。\n保險期間屆滿時，應予以續保，並將前項公共意外責任險保單送本\n府備查，其投保最低保險金額如下：\n一、每一個人身體傷亡：新臺幣三百萬元。\n二、每一事故身體傷亡：新臺幣二千萬元。\n三、每一事故財產損失：新臺幣三百萬元。\n四、保險期間總保險金額：新臺幣四千八百萬元。\n第八條    （刪除）\n第八條之一 違反第五條規定者，令負責人限期改善；屆期仍未改善者\n，處其新臺幣一萬元以上五萬元以下罰鍰，並得按次處罰。\n第九條    違反第六條第二項規定者，處負責人新臺幣一萬元以上五萬元\n以下罰鍰，並得按次處罰。\n第十條    特定行業未依第七條規定投保公共意外責任險、保險期間屆滿\n未予續保或投保後無故退保者，處負責人新臺幣三萬元以上十萬元\n以下之罰鍰，並令其限期投保或續保；屆期仍未投保或續保者，得\n按次處罰。\n第十一條    特定行業違反第三條、第五條、第六條及第七條，經處罰後\n仍拒不改善，情節重大者，本府得命其停止營業。\n特定行業申請營業登記後，如發生違反第五條之一情形者，\n令負責人限期改善，屆期仍未改善者，本府得命其停止營業。\n第十二條    本自治條例自公布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:FL041017","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"修正日期":"民國 108 年 07 月 09 日","公發布日":"民國 91 年 11 月 18 日","法規名稱":"屏東縣特定行業管理自治條例","法規體系":"城鄉發展處","發文字號":"屏府行法字第10825049901號 令"},"promulgation_date":"2002-11-18","revision_date":"2019-07-09","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=FL041017","status":"unknown","title":"屏東縣特定行業管理自治條例","last_checked_at":"2026-10-06T17:31:48+08:00","last_success_at":"2026-10-06T17:31:48+08:00","verification_status":"fetched","content_hash":"1c829a5ee1ef1f90efe37bd5888fff4430517ab756d08b310136204a9e319313","history":[{"observed_at":"2026-10-06T17:31:48+08:00","content_hash":"1c829a5ee1ef1f90efe37bd5888fff4430517ab756d08b310136204a9e319313","change_kind":"initial","revision_date":"2019-07-09"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"一、屏東縣政府（以下簡稱本府）為評議本縣現有巷道有關爭議，依據\n屏東縣建築管理自治條例第八條規定，特設屏東縣現有巷道認定評\n議小組（以下簡稱本小組），並訂定本要點。\n二、本小組任務如下：\n（一）現有巷道認定疑義及爭議之審議事項。\n（二）現有巷道改道及廢道異議處理之審議事項。\n（三）其他與現有巷道有關之交議、研究及建議事項。\n三、本小組置委員十三人，其中一人為召集人，由本府秘書長兼任；一\n人為副召集人，由本府城鄉發展處處長兼任；其餘委員由本府就下\n列人員聘（派）兼之:\n（一）本府城鄉發展處建築管理科科長。\n（二）本府城鄉發展處都市計畫科科長。\n（三）本府消防局代表一人。\n（四）本府工務處代表一人。\n（五）本府水利處代表一人。\n（六）本府交通旅遊處代表一人。\n（七）本府地政處代表一人。\n（八）本府行政處法制科代表一人。\n（九）屏東縣建築師公會代表二人\n（十）具有建築或法律專門學識之專家學者一人。\n前款任一性別委員人數不得低於委員人數三分之一。\n四、本小組委員任期二年，期滿得續聘（派）兼之。任期內出缺時，得\n補聘（派）兼至原任期屆滿之日止。但單位(機關)代表職務異動時\n，各單位(機關)應依程序改派，其任期至原任期屆滿之日止。\n五、本小組視業務需要，不定期召開。\n會議由召集人召集，並擔任主席；召集人因故不能出席時，由副召\n集人代理；召集人及副召集人均因故不能出席者，由出席委員互推\n一人代理主席。\n本小組召開會議得邀請有關機關（構）派員列席。\n六、本小組會議應有過半數委員出席，出席委員過半數之同意始得作成\n決議；正反意見同數時，由主席裁決之。\n七、本府聘任之委員應親自出席本小組會議及參與表決，不得代理。但\n本府(派)兼任之委員未能親自出席時，得指派代表代理之。\n八、本小組委員對於個別議案有利害關係者，應予迴避，不得參與開會\n及表決；應迴避而未迴避者，當事人得申請其迴避或由召集人令其\n迴避。迴避之委員，不計入出席或表決委員之人數。\n九、本小組置執行秘書一人，由本府城鄉發展處建築管理科科長兼任，\n承召集人之命綜理小組事務；幹事一人，由本府城鄉發展處建築管\n理科人員兼任。\n十、本小組會議決議及交付執行事項，以本府名義行之，函請有關機關\n辦理。\n十一、本小組派兼任人員均為無給職；但非本府人員出席會議時，得依\n規定支給出席費及交通費。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000758","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 111 年 07 月 19 日","法規名稱":"屏東縣現有巷道認定評議小組設置要點","法規體系":"城鄉發展處","發文字號":"屏府城管字第11128682200號函"},"promulgation_date":"2022-07-19","revision_date":"2022-07-19","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000758","status":"unknown","title":"屏東縣現有巷道認定評議小組設置要點","last_checked_at":"2026-10-06T17:32:00+08:00","last_success_at":"2026-10-06T17:32:00+08:00","verification_status":"fetched","content_hash":"16af97928e36eff147666e2edefa746bc08d37cc7a4d0cb19bc5d836d25fe3ad","history":[{"observed_at":"2026-10-06T17:32:00+08:00","content_hash":"16af97928e36eff147666e2edefa746bc08d37cc7a4d0cb19bc5d836d25fe3ad","change_kind":"initial","revision_date":"2022-07-19"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"附表.pdf","url":"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=11844&id=GL000913&type=LAW"}],"authority":"屏東縣政府","category":"建築管理相關","content":"一、\n屏東縣政府為辦理屏東縣產業園區之組織、任務、運作及其他相關事宜，依據\n產業創新條例第五十條第二項規定，設屏東縣產業園區聯合服務中心（以下簡\n稱本中心），並訂定本要點。\n二、本中心任務為統籌辦理屏東縣產業園區發展之需要及健全園區之經營、維護及\n管理。\n三、本中心置主任一人，綜理中心業務。\n四、本中心設下列各組，分別掌理各有關事項：\n(一)服務組：置組長一人，組員二人，掌理園區公共工程、環境清理與景觀維護\n作業、公共設施管理維護等相關事項。\n(二)環保組：置組長一人，組員二人，掌理事業或污水下水道系統廢(污)水檢測\n申報、用水量申報、事業污染總量核配管理、污水處理廠等相關事項。\n五、本中心人員編制如附表。\n前項人員之遴選及管理方式如下:\n(一)\n主任之僱用由熟稔及具相關領域專長之人員擔任。\n(二)組長及其他人員得以專案人員方式進用。\n(三)專案人員之待遇與管理規定，依屏東縣政府及所屬機關學校約聘人員進用要\n點規定辦理。\n六、本中心所需經費，於委託開發階段由各產業園區開發成本支應；營運\n階段由本\n府城鄉發展處編列預算支應。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000913","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"修正日期":"民國 115 年 06 月 18 日","公發布日":"民國 115 年 04 月 24 日","圖表附件":"附表.pdf","法規名稱":"屏東縣產業園區聯合服務中心設置要點","法規體系":"城鄉發展處","發文字號":"屏府城工字第1150169091號函"},"promulgation_date":"2026-04-24","revision_date":"2026-06-18","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000913","status":"unknown","title":"屏東縣產業園區聯合服務中心設置要點","last_checked_at":"2026-10-06T17:32:04+08:00","last_success_at":"2026-10-06T17:32:04+08:00","verification_status":"fetched","content_hash":"b8eb71b9b87649e672796eb9429036f9033e08d65753366b7ac747ab3e1ca6d7","history":[{"observed_at":"2026-10-06T17:32:04+08:00","content_hash":"b8eb71b9b87649e672796eb9429036f9033e08d65753366b7ac747ab3e1ca6d7","change_kind":"initial","revision_date":"2026-06-18"}],"version_count":1,"attachment_hashes":{"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=11844&id=GL000913&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"第一條\n屏東縣為因應產業園區發展之需要，健全產業園區之管理，特依產業創新\n條例（以下簡稱本條例）第四十九條第一項規定，設置屏東縣產業園區開\n發管理基金（以下簡稱本基金），並依預算法第九十六條第二項準用第二\n十一條規定，訂定本辦法。\n第二條\n本基金之收入、保管及運用，除法令另有規定外，依本辦法之規定辦理。\n第三條\n本基金為預算法第四條第一項第二款所定之特種基金，以屏東縣政府（以下簡稱本府）為主管機關，本府城鄉發展處為管理單位。\n第四條\n本基金之來源如下：\n一、\n依本條例第四十八條規定繳交之款項。\n二、\n依本條例第四十七條第一項規定收取之超過成本收入。\n三、\n產業園區維護費、使用費、管理費、服務費\n及權利金。\n四、\n產業園區開發完成後之結餘款。\n五、\n投資產業園區相關事業之收益。\n六、\n融貸資金之利息。\n七、\n基金孳息。\n八、\n由政府循預算程序之撥款。\n九、\n依本條例收取之回饋金。\n十、\n其他有關之收入。\n第五條\n本基金之用途如下：\n一、\n產業園區開發之融貸資金。\n二、\n產業園區內土地或建築物，長期未能租售，致租售價格超過附近使用\n性質相同之土地或建築物者，其所增加開發成本利息之補貼。\n三、\n產業園區或其周邊相關公共設施之興建、維護或改善。\n四、\n產業園區管理機構之營運。\n五、\n產業園區或其周邊受影響區域環境保護之改善。\n六、\n產業園區之相關研究、規劃或宣導。\n七、\n產業園區相關事業之投資。\n八、\n產業園區內重大公共意外事故之後續救助、補償之定額支出。\n九、\n其他有關之支出。\n第六條\n本基金應在金融機構設立專戶存儲。\n第七條\n本基金設屏東縣產業園區開發管理基金委員會（以下簡稱本會），監督本\n基金之管理及運用；其任務如下：\n一、\n本基金收支、保管及運用之審議事項。\n二、\n本基金年度預算、決算之審議事項。\n三、\n本基金貸放之審議事項。\n四、\n本基金運用執行情形之考核事項。\n五、\n其他有關本基金事項。\n第八條\n本會置委員九至十一人，其中一人為召集人，由縣長兼任；副召集人一人\n，由本府城鄉發展處處長兼任。其餘委員，由縣長遴聘有關機關代表及專\n家學者擔任。\n一、本府有關機關代表三至四人\n。\n二、學者專家四至五人。\n前項委員任期二年，期滿得續聘一次。但代表機關出任者，應隨其本職進\n退。\n聘期內委員出缺時，得補行遴聘，其聘期至原聘期屆滿之日止。\n第九條\n本會會議每年開會一次，必要時得召開臨時會，由召集人召集之，召集人\n因故不能出席時，由副召集人代理；召集人、副召集人因故不能出席時，\n由召集人指定委員一人代理。\n委員應親自出席會議。但代表機關之委員得由該機關派員代理出席。\n本會之決議，應經過半數委員之出席及出席委員過半數之同意；其決議事\n項，應報本府核定後辦理之。\n第十條\n本會委員均為無給職。但外聘委員得依規定支領出席費。\n第十一條\n本基金預算之編製、執行、會計事務之處理程序及決算之編造，應依預算\n法、會計法、決算法、審計法及相關法令規定辦理。\n第十二條\n本基金結束時，應予結算，其餘存權益應循預算程序辦理解繳縣庫。\n第十三條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000078","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 100 年 09 月 21 日","法規名稱":"屏東縣產業園區開發管理基金收支保管及運用辦法","法規體系":"城鄉發展處","發文字號":"屏府行法字第1000248297號 令"},"promulgation_date":"2011-09-21","revision_date":"2011-09-21","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000078","status":"unknown","title":"屏東縣產業園區開發管理基金收支保管及運用辦法","last_checked_at":"2026-10-06T17:31:49+08:00","last_success_at":"2026-10-06T17:31:49+08:00","verification_status":"fetched","content_hash":"fcde20c082b4c39e15aad3acd132c0380719e1662be516f88634c57483b2a0f7","history":[{"observed_at":"2026-10-06T17:31:49+08:00","content_hash":"fcde20c082b4c39e15aad3acd132c0380719e1662be516f88634c57483b2a0f7","change_kind":"initial","revision_date":"2011-09-21"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"第1條\n本規則依建築法(以下簡稱本法) 第四十六條規定訂定之。\n第2條\n畸零地及其相鄰土地之使用管理，依本規則之規定。\n前項所稱畸零地係指本法第三條規定地區內面積狹小或地界曲折之基地。\n第3條\n本規則所稱面積狹小基地，係指建築基地深度與寬度未達下列規定者：\n一  一般建築用地：\n┌───┬───┬───┬───┬──────────────┐\n│二  正│公  正│公  正│公  正│＼                          │\n│十  面│尺  面│尺  面│尺  面│  ＼                        │\n│五  路│至  路│至  路│以  路│    ＼  使用分區或使用地別  │\n│公  寬│二  寬│十  寬│下  寬│      ＼                    │\n│尺  超│十  超│五  超│    七│        ＼                  │\n│    過│五  過│公  過│      │          ＼                │\n│      │公  十│尺  七│      │            ＼              │\n│      │尺  五│      │      │              ＼            │\n├─┬─┼─┬─┼─┬─┼─┬─┤                ＼          │\n│最│最│最│最│最│最│最│最│基地情形（公尺）  ＼        │\n│小│小│小│小│小│小│小│小│                    ＼      │\n│深│寬│深│寬│深│寬│深│寬│                      ＼    │\n│度│度│度│度│度│度│度│度│                        ＼  │\n├─┼─┼─┼─┼─┼─┼─┼─┼──────────────┤\n│一│  │一│  │一│  │一│  │甲、乙種建築用地及住宅區    │\n│六│四│六│四│四│三│二│三│                            │\n│．│．│．│．│．│．│．│．│                            │\n│０│０│０│０│０│五│０│０│                            │\n│０│０│０│０│０│０│０│０│                            │\n├─┼─┼─┼─┼─┼─┼─┼─┼──────────────┤\n│一│  │一│  │一│  │一│  │商業區                      │\n│八│四│五│四│三│四│一│三│                            │\n│．│．│．│．│．│．│．│．│                            │\n│０│五│０│五│０│０│０│五│                            │\n│０│０│０│０│０│０│０│０│                            │\n├─┼─┼─┼─┼─┼─┼─┼─┼──────────────┤\n│二│  │二│  │二│  │二│  │丙種建築用地及風景區        │\n│０│六│０│六│０│六│０│六│                            │\n│．│．│．│．│．│．│．│．│                            │\n│０│０│０│０│０│０│０│０│                            │\n│０│０│０│０│０│０│０│０│                            │\n├─┼─┼─┼─┼─┼─┼─┼─┼──────────────┤\n│一│  │一│  │一│  │一│  │丁種建築用地及工業區        │\n│六│七│六│七│六│七│六│七│                            │\n│．│．│．│．│．│．│．│．│                            │\n│０│０│０│０│０│０│０│０│                            │\n│０│０│０│０│０│０│０│０│                            │\n├─┼─┼─┼─┼─┼─┼─┼─┼──────────────┤\n│一│  │一│  │一│  │一│  │其他使用分區                │\n│八│四│七│四│六│四│二│三│                            │\n│．│．│．│．│．│．│．│．│                            │\n│０│五│０│五│０│０│０│五│                            │\n│０│０│０│０│０│０│０│０│                            │\n└─┴─┴─┴─┴─┴─┴─┴─┴──────────────┘\n二  側面應留設騎樓之建築基地：\n┌───┬───┬───┬───┬──────────────┐\n│二  正│公  正│公  正│公  正│＼                          │\n│十  面│尺  面│尺  面│尺  面│  ＼                        │\n│五  路│至  路│至  路│以  路│    ＼  使用分區            │\n│公  寬│二  寬│十  寬│下  寬│      ＼                    │\n│尺  超│十  超│五  超│    七│        ＼                  │\n│    過│五  過│公  過│      │          ＼                │\n│      │公  十│尺  七│      │            ＼              │\n│      │尺  五│      │      │              ＼            │\n├─┬─┼─┬─┼─┬─┼─┬─┤                ＼          │\n│最│最│最│最│最│最│最│最│基地情形（公尺）  ＼        │\n│小│小│小│小│小│小│小│小│                    ＼      │\n│深│寬│深│寬│深│寬│深│寬│                      ＼    │\n│度│度│度│度│度│度│度│度│                        ＼  │\n├─┼─┼─┼─┼─┼─┼─┼─┼──────────────┤\n│一│  │一│  │一│  │一│  │住宅區                      │\n│六│七│六│七│四│七│二│六│                            │\n│．│．│．│．│．│．│．│．│                            │\n│０│六│０│六│０│一│０│六│                            │\n│０│０│０│０│０│０│０│０│                            │\n├─┼─┼─┼─┼─┼─┼─┼─┼──────────────┤\n│一│  │一│  │一│  │一│  │商業區                      │\n│八│七│五│七│五│七│一│六│                            │\n│．│．│．│．│．│．│．│．│                            │\n│０│六│０│六│０│一│０│六│                            │\n│０│０│０│０│０│０│０│０│                            │\n├─┼─┼─┼─┼─┼─┼─┼─┼──────────────┤\n│一│  │一│  │一│  │一│  │工業區                      │\n│六│八│六│八│六│八│六│八│                            │\n│．│．│．│．│．│．│．│．│                            │\n│０│０│０│０│０│０│０│０│                            │\n│０│０│０│０│０│０│０│０│                            │\n├─┼─┼─┼─┼─┼─┼─┼─┼──────────────┤\n│一│  │一│  │一│  │一│  │其他使用分區                │\n│八│七│七│七│六│七│二│六│                            │\n│．│．│．│．│．│．│．│．│                            │\n│０│六│０│六│０│一│０│六│                            │\n│０│０│０│０│０│０│０│０│                            │\n└─┴─┴─┴─┴─┴─┴─┴─┴──────────────┘\n前項其他使用分區不包括農業區、保存區、保護區、公共設施用地及表列\n以外非都市土地。但依獎勵投資條例或促進產業升級條例開發之工業住宅\n社區，按前項第一款之甲、乙種建築用地及住宅區之規定辦理。\n除興辦事業計畫同意免臨接建築線之特定目的事業用地外，特定目的事業\n用地準用第一項其他使用分區規定。\n應留設側院地區，基地寬度減側院寬度之差，不得小於第一項各表最小寬\n度。\n第4條\n本規則所稱正面路寬、最小寬度及最小深度之定義如下：\n一、正面路寬係指基地面前道路之寬度。如以符合建築技術規則第二條規\n定之私設通路連接建築線者，得以私設通路寬度視為面前道路寬度。\n二、最小寬度係指最小深度範圍內基地二側境界線間與道路境界線平行距\n離之最小值。但道路境界線為曲線者，以該曲線與基地兩側境界線交\n點之連線視為道路境界線。\n三、最小深度係指臨接之道路境界線至該基地後側境界線垂直距離之最小\n值。\n建築基地如屬角地應截角時，其寬度及深度係指截角前之寬度及深度。\n第5條\n建築基地臨接二條以上道路，起造人得選擇任一道路為面前道路。\n建築基地位於道路末端，其寬度、深度及方位由起造人選定之。\n前二項情形分別以任一道路為面前道路或以任一方位量距，其寬度及深度\n達到本規則所定最小寬度及深度之標準以上者，即不必與相鄰土地合併使\n用。\n道路境界線以外另定建築線之建築基地，其寬度與深度應自建築線起算。\n第6條\n依第三條規定之基地寬度，每增加十公分，其深度得減少二十公分，減少\n後之深度不得小於八公尺。\n依前項規定調整最小寬度、深度，須留設前院、後院、法定騎樓、臨接綠\n帶退縮及都市計畫規定退縮建築者，減少後之深度不得小於六公尺。\n第7條\n本規則所稱地界曲折基地，係指下列情形之一：\n一、基地界線曲折不齊成為畸形，而該曲折部分無法配置建築物者。\n二、基地界線與建築線斜交之角度不滿六十度或超過一百二十度者。\n前項如可配置符合第三條或第六條規定最小寬度及最小深度之六十度至一\n百二十度平行四邊形者，非屬畸零地。\n第8條\n面積狹小之基地非經補足所缺寬度、深度，地界曲折之基地非經整理，均\n不得建築。但符合下列情形之一者，不在此限：\n一、臨接地為道路、水溝、軍事設施或公共設施用地。\n二、寬度符合第三條最小寬度且深度部分臨接土地業已建築完成者，其基\n地最小深度扣除騎樓地或退縮地後，未小於六公尺。\n三、深度符合第三條最小深度且寬度部分臨接土地業已建築完成者，其基\n地最小寬度扣除騎樓地或退縮地後，未小於二公尺。\n四、臨接土地業已領得建造執照並已完成地上一樓頂版勘驗或為合法房屋。\n五、因地形上之障礙無法合併使用。\n第9條\n實施區域計畫地區非都市土地在編定使用前或實施都市計畫地區在中華民\n國六十二年七月十二日前業經地政機關辦理分割完竣，或因都市計畫公共\n設施用地之劃定逕為分割完竣，面積狹小之基地符合下列規定之最小寬度\n、深度及面積者，准予建築。┌─────┬─────┬─────┬─────┬──────┐\n│  二  正  │  公  正  │  公  正  │  公  正  │            │\n│  十  面  │  尺  面  │  尺  面  │  尺  面  │            │\n│  五  路  │  至  路  │  至  路  │  以  路  │    使用分區│\n│  公  寬  │  二  寬  │  十  寬  │  下  寬  │            │\n│  尺  超  │  十  超  │  五  超  │      七  │            │\n│      過  │  五  過  │  公  過  │          │            │\n│          │  公  十  │  尺  七  │          │＼          │\n│          │  尺  五  │          │          │  ＼        │\n├─┬─┬─┼─┬─┬─┼─┬─┬─┼─┬─┬─┤    ＼      │\n│最│最│最│最│最│最│最│最│最│最│最│最│      ＼    │\n│小│小│小│小│小│小│小│小│小│小│小│小│        ＼  │\n│深│深│寬│深│深│寬│深│深│寬│深│深│寬│基地情形  ＼│\n│度│度│度│度│度│度│度│度│度│度│度│度│（公尺）    │\n│︵│︵│︵│︵│︵│︵│︵│︵│︵│︵│︵│︵│            │\n│平│公│公│平│公│公│平│公│公│平│公│公│            │\n│方│尺│尺│方│尺│尺│方│尺│尺│方│尺│尺│            │\n│公│︶│︶│公│︶│︶│公│︶│︶│公│︶│︶│            │\n│尺│  │  │尺│  │  │尺│  │  │尺│  │  │            │\n│︶│  │  │︶│  │  │︶│  │  │︶│  │  │            │\n├─┼─┼─┼─┼─┼─┼─┼─┼─┼─┼─┼─┼──────┤\n│四│  │  │三│  │  │三│  │  │二│  │  │甲、乙種建築│\n│０│七│四│五│六│三│０│六│三│０│五│三│用地、住宅區│\n│．│．│．│．│．│．│．│．│．│．│．│．│、商業區    │\n│０│０│０│０│０│五│０│０│五│０│０│０│            │\n│０│０│０│０│０│０│０│０│０│０│０│０│            │\n└─┴─┴─┴─┴─┴─┴─┴─┴─┴─┴─┴─┴──────┘\n前項建築基地騎樓部分應計入最小深度。但不列入最小寬度及最小面積。\n應留設側院地區，其基地寬度減側院寬度之差，不得小於三公尺。\n臨接綠帶應退縮建築之基地，其退縮部分不計入最小面積，基地深度減退\n縮地深度之差，不得小於五公尺。\n第10條\n實施區域計劃地區非都市土地編定為丁種建築用地及實施都市計畫地區劃\n定為工業區之土地，在中華民國七十五年十一月二日前，業經地政機關辦\n理分割完竣之建築基地，符合下列規定之最小寬度、深度者，准予建築，\n不受第三條規定之限制。\n┌───┬───┬───┬───┬──────────────┐\n│二  正│公  正│公  正│公  正│＼                          │\n│十  面│尺  面│尺  面│尺  面│  ＼                        │\n│五  路│至  路│至  路│以  路│    ＼  使用分區            │\n│公  寬│二  寬│十  寬│下  寬│      ＼                    │\n│尺  超│十  超│五  超│    七│        ＼                  │\n│    過│五  過│公  過│      │          ＼                │\n│      │公  十│尺  七│      │            ＼              │\n│      │尺  五│      │      │              ＼            │\n├─┬─┼─┬─┼─┬─┼─┬─┤                ＼          │\n│最│最│最│最│最│最│最│最│基地情形（公尺）  ＼        │\n│小│小│小│小│小│小│小│小│                    ＼      │\n│深│寬│深│寬│深│寬│深│寬│                      ＼    │\n│度│度│度│度│度│度│度│度│                        ＼  │\n│︵│︵│︵│︵│︵│︵│︵│︵│                            │\n│公│公│公│公│公│公│公│公│                            │\n│尺│尺│尺│尺│尺│尺│尺│尺│                            │\n│︶│︶│︶│︶│︶│︶│︶│︶│                            │\n├─┼─┼─┼─┼─┼─┼─┼─┼──────────────┤\n│一│  │一│  │一│  │一│  │　　                        │\n│八│四│七│四│六│四│二│三│丁種建築用地、工業區        │\n│．│．│．│．│．│．│．│．│                            │\n│０│五│０│五│０│０│０│五│                            │\n│０│０│０│０│０│０│０│０│                            │\n└─┴─┴─┴─┴─┴─┴─┴─┴──────────────┘\n第11條\n畸零地所有權人與鄰地所有權人無法達成協議時，欲申請調處時，應填具\n申請書並檢附下列書件正本一份，副本十份向本府申請調處：\n一、合併使用土地之土地登記簿謄本、地籍圖謄本。\n二、相關土地地盤圖，註明需合併使用土地最小面積之寬度及深度。\n三、相關土地所有權人、承租人及他項權利人之姓名、住址。\n四、公告現值。\n五、建築線指示（定）成果圖。\n六、調解委員會二次調解不成立證明文件。\n第12條\n本府受理調處畸零地合併時，應於收到申請書之日起一個月內，通知有關\n土地所有權人、承租人及他項權利人進行調處，調處之程序如下：\n一、審查合併土地之位置、形狀及申請人所規劃合併土地最小面積、寬度\n及深度，必要時並酌予調整。\n二、查估合併土地附近之買賣市價，徵詢參與調處人之意見，並由各土地\n所有權人協商合併建築或公開議價，互為買賣或合併建築。\n三、調處時，雙方意見不一致或一方缺席經再次通知不到者，視為調處一\n次不成立。\n經調處二次不成立者，一年內不再受理調處。\n第13條\n畸零地調處二次不成立時，基地所有權人及臨接土地所有權人得依本法第\n四十五條之規定預繳承買價款，申請徵收。\n第14條\n本府調處委員會，以下列人員為委員，由本府城鄉發展處處長為召集人：\n一、城鄉發展處處長。\n二、本府地政、財政、法制單位代表各一人。\n三、本府建築管理科及都市計畫科科長。\n四、社團法人屏東縣建築師公會、中華民國不動產估價師協會、屏東縣不\n動產開發商業同業公會代表各一人。\n第15條\n公有畸零地合併使用證明書之核發基準由本府另定之。\n第 16 條\n本規則自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:FL026596","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"修正日期":"民國 103 年 12 月 30 日","公發布日":"民國 91 年 02 月 15 日","法規名稱":"屏東縣畸零地使用規則","法規體系":"城鄉發展處","發文字號":"屏府行法字第10379877701號 令"},"promulgation_date":"2002-02-15","revision_date":"2014-12-30","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=FL026596","status":"unknown","title":"屏東縣畸零地使用規則","last_checked_at":"2026-10-06T17:31:50+08:00","last_success_at":"2026-10-06T17:31:50+08:00","verification_status":"fetched","content_hash":"9c42b4ce08452820899682c4aa79ca2385e7b4b4fa922056e96ceb69df54460e","history":[{"observed_at":"2026-10-06T17:31:50+08:00","content_hash":"9c42b4ce08452820899682c4aa79ca2385e7b4b4fa922056e96ceb69df54460e","change_kind":"initial","revision_date":"2014-12-30"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"一、屏東縣政府(以下簡稱本府)為促進本縣科學園區(以下簡稱科學園區\n)之發展，特設立屏東縣科學園區諮詢委員會 (以下簡稱本會)，並\n訂定本要點。\n二、 本會任務如下：\n（一）科學園區產業、發展及策略之研擬分析。\n（二）科學園區周邊發展及配套措施之策略研擬。\n（三）其他有關科學園區相關事項之建議。\n三、本會置委員十五人至十九人，其中主任委員一人由縣長兼任，副主任\n委員一人由縣長就本府人員指定一人兼任，其餘委員由本府相關單位\n或聘請產業發展相關專家學者擔任。\n本會委員任期為二年，任期屆滿得續聘(派)或改聘(派)之；任期內出\n缺時，得補行遴聘(派)至原任期屆滿之日為止。\n本會開會時，視議題需要得邀請本府相關局處派員列席或其他相關機\n關(構)、專家、學者列席。\n四、本會會議視業務推動情形，不定期召開。\n會議由主任委員召集，並擔任主席，主任委員不克出席會議時，由副\n主任委員代理，副主任委員亦不克出席者，由出席委員互推一人代理\n主席。\n五、本會之決議，交由本府辦理或相關單位協辦者，本府應定期追蹤進度。\n六、本會委員均為無給職。但非本府人員出席會議時，得依規定支給出席\n費及交通費。\n七、本會辦理所需經費，由本府相關預算支應。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000739","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 111 年 03 月 04 日","法規名稱":"屏東縣科學園區諮詢委員會設置要點","法規體系":"城鄉發展處","發文字號":"屏府城都字11107948900號函"},"promulgation_date":"2022-03-04","revision_date":"2022-03-04","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000739","status":"unknown","title":"屏東縣科學園區諮詢委員會設置要點","last_checked_at":"2026-10-06T17:31:59+08:00","last_success_at":"2026-10-06T17:31:59+08:00","verification_status":"fetched","content_hash":"642dce2e2ddd80e00883ea3dde2defa926c63baa842f355a0c71c2267615e7e3","history":[{"observed_at":"2026-10-06T17:31:59+08:00","content_hash":"642dce2e2ddd80e00883ea3dde2defa926c63baa842f355a0c71c2267615e7e3","change_kind":"initial","revision_date":"2022-03-04"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"第1條\n屏東縣（以下簡稱本縣）為有效管理都市計畫區內空地及空屋，以改善環\n境衛生、維護公共安全、美化觀瞻，並促進土地及房屋充分利用，特制定\n本自治條例。\n第2條\n本自治條例之主管機關為屏東縣政府（以下簡稱本府）。為辦理空地空屋\n查處作業，應設置空地空屋縣查處小組及空地空屋鄉（鎮、市）查處小組\n；其設置及執行規定另定之。\n第3條\n本自治條例所稱空地及空屋定義如下：\n一、空地：指全部或部分閒置、荒廢之土地或建築物四周全部或部分未利\n用之土地。\n二、空屋：指荒廢或無人使用之建築物，或已被徵收拆除後棄置之建築物。\n第4條\n空地或空屋所有權人、管理人或使用人應負下列維護管理責任：\n一、刈除逾五十公分之雜草。\n二、清除有污染環境之虞的廢棄土及廢棄物。\n三、不得堆置有礙觀瞻、環境衛生之物品。\n四、防止孶生病媒源或有發生傳染病之虞。\n五、本府認定非屬古蹟或歷史建築物之危險房屋者，房屋所有權人應自行\n拆除或妥為維護。\n工程中止或因故停工或無人使用之建築物，除應維護建築物之結構安全及\n工地環境衛生外，並不得阻礙騎樓地及人行道之暢通，其建築物外觀及必\n要之假設工程，不得影響觀瞻。必要時，得命起造人、承造人、管理人、\n使用人或所有權人對建築物外觀加以美化或自行拆除。空地供作營利性臨\n時使用者，應依前項各款規定，負維護管理責任。\n第5條\n本府為查核本縣空地及空屋之維護管理情形，得派員攜帶證明文件，必要\n時會同警員或里長進入空地或空屋從事勘查，所有權人、管理人、使用人\n、起造人或承造人不得規避、妨礙或拒絕。\n第6條\n違反第四條第一項第一款至第三款規定，經本府通知限期改善而屆期未改\n善者，處新臺幣一千二百元以上六千元以下罰鍰，並按次處罰。\n第7條\n違反第四條第一項第四款規定，經本府通知限期清理改善屆期仍不符規定\n者，依傳染病防治法規定處罰。\n第8條\n違反第四條第一項第五款規定，經本府通知限期改善屆期仍不符規定者，\n依建築法規定處罰。\n第9條\n違反第四條第二項規定，經本府通知限期改善而屆期未改善者，處新臺幣\n一萬二千元以上六萬元以下罰鍰，並按次處罰。但建築法另有規定，依其\n規定處罰。\n第10條\n違反第五條規定拒絕本府派員進入空地或空屋勘查者，處新臺幣一千二百\n元以上二萬元以下罰鍰，並按次處罰。\n第11條\n本府得委託各鄉（鎮、市）公所負責轄區內空地或空屋查報，並造冊列管\n。經發現有違反第四條之規定者，應將其違反事實通知本府處理。\n第12條\n本府及各鄉（鎮、市）公所執行本自治條例所需之土地、建築物、戶籍及\n稅籍等資料，各地政事務所、戶政事務所及稅務機關應免費提供。\n第13條\n本自治條例自公布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000121","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 101 年 08 月 13 日","法規名稱":"屏東縣空地空屋管理自治條例","法規體系":"城鄉發展處","發文字號":"屏府行法字第10125905700號 令"},"promulgation_date":"2012-08-13","revision_date":"2012-08-13","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000121","status":"unknown","title":"屏東縣空地空屋管理自治條例","last_checked_at":"2026-10-06T17:31:46+08:00","last_success_at":"2026-10-06T17:31:46+08:00","verification_status":"fetched","content_hash":"f08c53688d1cd5c7a52c5217913a4b8d38a3f28584d23384859edaed35b7b399","history":[{"observed_at":"2026-10-06T17:31:46+08:00","content_hash":"f08c53688d1cd5c7a52c5217913a4b8d38a3f28584d23384859edaed35b7b399","change_kind":"initial","revision_date":"2012-08-13"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"第 1 條\n本辦法依建築法第九十九條之一規定訂定之。\n第 2 條\n本辦法實施範圍為琉球鄉、滿洲鄉、枋山鄉、三地門鄉、霧台鄉、瑪家鄉\n、泰武鄉、來義鄉、春日鄉、獅子鄉、牡丹\n鄉。但屬山坡地者，應依山坡地開發建築管理辦法及其有關規定辦理。\n第 3 條\n本辦法實施範圍內建造鄉村住宅，其工程造價在新臺幣七十萬元以下者，\n得免由建築師設計或監造或營造業承造，其申請建造執照應備具之工程圖\n樣如下：\n一  基地位置圖。\n二  地盤圖。\n三  配置圖，其比例尺不得小於一千二百分之一。\n四  平面、立面、剖面圖，其比例尺不得小於百分之一。但選用屏東縣政\n府 (以下簡稱本府) 指定之標準建築圖樣者，得免附平面、立面圖。\n第 4 條\n本辦法實施範圍內供公眾使用建築物認定標準如下：\n一  戲院、電影院、演藝場。\n二  舞廳、歌廳、夜總會、俱樂部。\n三  酒家、酒吧、酒店、酒館。\n四  保齡球館、遊藝場、室內兒童樂園、室內溜冰場、室內游泳池、體育\n館。\n五  總樓地板面積在三百平方公尺以上之旅館類。\n六  總樓地板面積在五百平方公尺以上之市場、百貨商場。\n七  博物館、美術館、圖書館、資料館、陳列館。\n八  寺院、廟宇、教會、集會堂。\n九  總樓地板面積在三百平方公尺以上之車站、航空站、加油站。\n一○  幼稚園、小學、中學、大專院校、總樓地板面積在四百平方公尺以\n上之補習班及訓練班。\n一一  使用電力 (包括電熱) 在七十五千瓦以上，作業樓地板面積合計在\n五百平方公尺以上之工廠。\n一二  四層以上總樓地板面積一千平方公尺以上之集合住宅 (公寓) 。\n一三  其他經本府指定者。\n第 5 條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:FL026942","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"修正日期":"民國 91 年 01 月 24 日","公發布日":"民國 90 年 12 月 17 日","法規名稱":"屏東縣簡化偏遠地區建築管理辦法","法規體系":"城鄉發展處","發文字號":"屏府工建字第0910013802號"},"promulgation_date":"2001-12-17","revision_date":"2002-01-24","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=FL026942","status":"unknown","title":"屏東縣簡化偏遠地區建築管理辦法","last_checked_at":"2026-10-06T17:31:48+08:00","last_success_at":"2026-10-06T17:31:48+08:00","verification_status":"fetched","content_hash":"ade1b639f172358e6eb548813a24b90ced6939f1d435498515280589e10f12da","history":[{"observed_at":"2026-10-06T17:31:48+08:00","content_hash":"ade1b639f172358e6eb548813a24b90ced6939f1d435498515280589e10f12da","change_kind":"initial","revision_date":"2002-01-24"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"第一條　  屏東縣（以下簡稱本縣）為推動永續城鄉，營造綠建築環境\n，創造健康生活品質，促進綠色產業，並達到節能減碳及減災目\n標，特制定本自治條例。\n第二條　　本自治條例之主管機關為屏東縣政府（以下簡稱本府）。\n第三條　　本自治條例所稱聰明基地，指基地與建築物利用透水基盤、\n綠能屋頂、立體綠化、通用設計、深遮陽及創造有效通風開口等\n方式，呼應在地氣候，達到節能、健康及舒適之生活環境。\n第四條　　適用本自治條例之各類建築物（以下簡稱各類建築物），其\n分類如下：\n一、第一類建築物：指公有新建建築物。但本自治條例公布施行\n前預算已審議通過或工程造價未達新臺幣三千萬元者，不在\n此限。\n二、第二類建築物：指依都市計畫公共設施用地多目標使用辦法\n、建築技術規則建築設計施工編第十五章實施都市計畫區建\n築基地綜合設計規定申請之新建建築物及樓高十六層以上之\n新建建築物。\n三、第三類建築物：指依建築技術規則建築設計施工編第十四章\n規定申請之工廠類新建建築物。但該宗基地建築面積在一千\n平方公尺以下者，不在此限。\n四、第四類建築物：前三類建築物以外供公眾使用之新建建築物\n且基地建築面積在二百平方公尺以上者。\n五、第五類建築物：領有使用執照之建築物。\n第五條　　第一類建築物之綠建築設計，應符合下列規定：\n一、建築物屋頂應設置隔熱層及太陽光電發電設施或屋頂綠化設\n施。\n二、基地範圍內應設置垃圾處理設施及垃圾存放空間。\n三、建築物應全面採用省水便器。\n四、應設置自行車停車空間。\n五、依建築技術規則規定應設置昇降機者，每幢建築物應設置可\n同時搭載人員及自行車之昇降機一部。但自行車停車空間設\n置於地面層者，其昇降機可不具搭載自行車之功能。\n六、應於建築基地內預為留設電動汽（機）車電力線路及動線。\n第六條　　第二類建築物之綠建築設計，應依下列規定為之：\n一、建築物屋頂應設置隔熱層及太陽光電發電設施或屋頂綠化設\n施。\n二、十六層以上之建築物應設置垃圾處理設施及垃圾存放空間。\n三、建築物之室內裝修材料、樓地板面材料及窗，其綠建材使用\n率應達總面積百分之四十五以上。但窗未使用綠建材者，得\n不計入總面積檢討。\n四、應設置具管理功能之自行車停車空間，並應設置乾濕分離之\n淋浴設施。但供集合住宅使用者得免設置淋浴設施。\n五、建築物應全面採用省水便器。\n六、依建築技術規則規定應設置昇降機者，每幢建築物應設置可\n同時搭載人員及自行車之昇降機一部。但自行車停車空間設\n置於地面層者，其昇降機可不具搭載自行車之功能。\n第七條　　 第三類建築物之綠建築設計，應依下列規定為之：\n一、建築物屋頂應設置太陽光電發電設施或屋頂綠化設施。\n二、建築物應全面採用省水便器。\n第八條　  第四類建築物之綠建築設計，應依下列規定為之：\n一、建築物屋頂應設置隔熱層及太陽光電發電設施或屋頂綠化設\n施。\n二、建築物應全面採用省水便器。\n三、應設置自行車停車空間。\n四、人工基盤設置硬舖面者，應搭配使用透水性鋪面。\n第九條　 第五類建築物申請建築物室內裝修時，申請範圍內之新設\n及既有燈具不得使用高耗能燈具。\n第十條    太陽光電發電設施之設置規定如下：\n一、第一類、第二類及第四類建築物，每幢建築物裝置容量\n應達二峰瓩以上。\n二、第三類建築物，太陽光電發電設施設置面積應達新建最\n大建築面積二分之一以上。但屋頂不可設置區域得扣除\n之。\n前項太陽光電發電設施得設置於空地上、建築物立面、\n露台或同基地既有他幢建築物之屋頂。\n第一項第二款所稱太陽光電發電設施設置面積，指太陽\n光電發電設施之投影面積；所稱屋頂不可設置區域，指屋頂\n突出物、屋頂雜項工作物、屋頂綠化設施及屋頂透空框架投\n影、經審核遮陰部分及宗教類建築物其斜屋頂設置太陽光電\n發電設施確有困難者等面積後所占之面積。\n太陽光電發電設施應裝置容量超過四百九十九峰瓩者，\n起造人得裝置四百九十九峰瓩。\n第十一條    屋頂綠化設施之設置規定如下：\n一、屋頂綠化設施面積應達新建最大建築面積二分之一以\n上。但屋頂不可設置區域得扣除之。\n二、屋頂綠化應附設給水設備，以供植栽澆灌使用，並應\n考量植栽位置及排水、防水設計。\n前項屋頂綠化設施得設置於露台或同基地既有他幢建\n築物之屋頂、牆面。\n第一項第一款所稱屋頂綠化設施面積，指屋頂綠化設\n施之投影面積；所稱屋頂不可設置區域，指屋頂突出物、\n屋頂雜項工作物、太陽光電發電設施及屋頂透空框架投影\n、經審核宗教類建築物其斜屋頂設置太陽光電發電設施確\n有困難者其所占之面積。\n屋頂綠化設施之設計，應符合建築基地綠化設計技術\n規範之規定。\n第十二條    建築物屋頂設置隔熱層者，其屋頂平均熱傳透率應低\n於零點八瓦/(平方公尺‧度)。\n前項屋頂平均熱傳透率之計算方式，應依建築物節約\n能源設計技術規範之規定。\n第十三條　　建築物垃圾處理設施及垃圾存放空間之設置規定如下：\n一、應設置垃圾暫存設施、廚餘收集處理再利用設施及資\n源垃圾分類回收設施。\n二、垃圾存放空間之設置規模，應以建築物容積總樓地板\n面積每二十平方公尺為一人核算建築物使用人口數，\n再按每人每日一點二公斤或零點零零六零五立方公尺\n之垃圾生產量標準，核算之。\n三、樓高十六層以上建築物之垃圾存放空間應設置於室內。\n第十四條    建築物設置之省水便器，應取得經濟部水利署省水標\n章證書之認證。\n建築物供公眾使用之洗手設備，應設有踩踏式或感應\n式沖水洗手設備。\n第十五條　　綠建材使用率，其計算方法應符合綠建材設計技術規\n範之規定。\n第十六條    自行車停車空間之設置規定如下：\n一、平面自行車停車格寬度不得小於六十公分、長度不得\n小於一百八十五公分。\n二、公有建築物者，其停車數量不得少於該建築物法定停\n車位數量二分之一。\n第十七條    依規定設置可同時搭載人員及自行車之昇降機者，其\n承載人數不得少於十二人。\n第十八條　　設計本縣公有建築物領得黃金級以上綠建築標章之建\n築師，應予獎勵；其獎勵辦法由主管機關定之。\n第十九條　　建築物設置聰明基地應予獎勵；其獎勵辦法由主管機\n關定之。\n第二十條    本自治條例申請各類建築物建造執照及雜項執照規費\n，按建築物造價或雜項工作物造價一千五百分之一計算，\n如有變更設計時，則按變更部分一千五百分之一計算。\n第二十一條    建築物有下列情形之一者，得由起造人將綠建築設\n備及設施經費匯入屏東縣永續綠建築經營基金（以下簡\n稱本基金）內統合辦理後核發建照：\n一、綠建築設施及設備費用低於新臺幣一百萬元。\n二、經主管機關核定建築物設置綠建築設備及設施確有\n困難。\n三、起造人不擬自辦。\n四、第三類建築物如有無法符合第六條規定之部分。\n五、其他經主管機關認定事項。\n第一項起造人應繳納之經費，得按綠建築設備設施\n經費計算表計算後依下列規定比例折減之：\n一、民國一零五年一月一日至民國一零五年十二月三十\n一日申請案件：折減百分之九十。\n二、民國一零六年一月一日至民國一零六年十二月三十\n一日申請案件：折減百分之七十。\n三、民國一零七年一月一日至民國一零七年十二月三十\n一日申請案件：折減百分之五十。\n起造人於建築物領得使用執照後三年內，依本自治\n條例設置綠建築設備及設施，並檢附建築師簽證之綠建\n築設施竣工之文件經主管機關審核通過者，主管機關得\n無息退還起造人依第一項繳交之經費。\n本基金之收支管理、運用及綠建築設備設施經費計\n算表，由主管機關定之。\n第二十二條    起造人申請各類建築物建造執照時，應同時檢附建\n築師及相關設備技師簽證之各項綠建築項目設計圖說。\n各類建築物竣工時，應同時檢附建築師簽證之綠建築設\n施竣工文件併同相關設備標章影本及出廠證明文件，申\n請使用執照。\n第二十三條　　各類建築物申請建造執照時，應檢附各綠建築項目\n設計圖說之書圖文件如下：\n一、太陽光電發電系統之模組裝設方位角、傾斜角、平\n面配置圖及太陽光電發電系統單線圖。\n二、屋頂綠化之綠化配置及相關立面圖、綠化面積計算\n表(載明屋頂植栽投影面積及屋頂面積)、相關設備\n圖說及剖面圖(含覆土高程)。\n三、屋頂隔熱層剖面大樣圖及屋頂平均熱傳透率計算檢\n討說明。\n四、建築物垃圾處理設施圖說及垃圾存放空間配置圖。\n五、省水便器之衛生設備配置圖及設備規格表。\n六、綠建材使用率計算表及綠建材配置圖。\n七、自行車停車空間平面圖；設置停車設備者，其設\n備圖說。\n第二十四條    為鼓勵綠建築設計，推動本縣公有及民間建築物\n進行綠建築工程或設置太陽光電等綠能設施，本府得\n編列預算予以改善或獎勵補助。\n本縣新建或既有綠建築獎勵補助之優先項目如下：\n一、老舊建築物立面節能修繕工程。\n二、建築基地景觀綠美化。\n三、屋頂隔熱及綠美化。\n四、設置太陽光電設施等綠能設施。\n五、其他因配合整體整建或維護工程之完整性，經審\n查同意之必要工程項目。\n本縣新建或既有綠建築獎勵補助辦法，由主管機關定\n之。\n第二十五條    建築物屋頂設置一定規模以下之太陽光電發電系\n統等綠能設施，或於建築物設計綠建築設備設施，得\n免申請雜項執照。\n前項有關免申請雜項執照之設備容量、高度及面\n積標準，由主管機關定之。\n第二十六條    本自治條例第五條至第九條規定之綠建築設計項\n目，經檢具申請書、建築物綠建築性能設計計畫書及\n評定書向主管機關申請認可者，得不適用本自治條例\n一部或全部之規定。\n前項之建築物綠建築性能設計評定書，應由主管\n機關指定之機關（構）、學校或團體辦理評定。\n第一項之申請書、建築物綠建築性能設計計畫書\n及評定書格式、應記載事項、得免適用之條文、認可\n程序及其他應遵循事項，由主管機關定之。\n第二項之機關（構）、學校或團體，應具備之條\n件、指定程序及其應遵循事項，由主管機關定之。\n第二十七條　　本自治條例第五條至第九條規定之綠建築設施設\n備，除中華民國國家標準另有規定者外，應依本自治\n條例規定。但因特殊情形，難以應用符合本自治條例\n與中華民國國家標準材料及設備，經主管機關同意修\n改設計規定者，不在此限。\n引用新穎之建築技術、新工法或建築設備，適用\n本自治條例確有困難者，或本自治條例及中華民國國\n家標準未明定適用之特殊或國外進口材料及設備者，\n應檢具申請書、試驗報告書及性能規格評定書，向主\n管機關申請認可後，始得運用於建築物。\n前項之試驗報告書及性能規格評定書，應由主管\n機關指定之機關（構）、學校或團體辦理評定。\n第二項申請認可之申請書、試驗報告書及性能規\n格評定書之格式、認可程序及其他應遵行事項，由主\n管機關定之。\n第三項之機關（構）、學校或團體，應具備之條\n件、指定程序及其應遵行事項，由主管機關定之。\n第二十八條    主管機關得設綠建築技術審議會，以從事綠建築\n設計、施工、構造、材料與設備等技術之審議、研究\n、爭議事件、建議及改進事項等；其組織及運作由主\n管機關定之。\n綠建築設計如有節能、減碳或防災之效益，且對\n於都市發展、建築藝術、施工技術、公益有重大貢獻\n或狀況特殊、執行有困難者等，並經綠建築技術審議\n會審議認可者，得不適用本自治條例一部或全部之規\n定。\n申請前二項提送綠建築技術審議會審議者；其收\n費標準，由主管機關定之，該費用匯入本基金。\n第二十九條　　本自治條例自中華民國一零五年一月一日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000391","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 104 年 12 月 28 日","法規名稱":"屏東縣綠建築自治條例","法規體系":"城鄉發展處","發文字號":"屏府行法字第10481959501號 令"},"promulgation_date":"2015-12-28","revision_date":"2015-12-28","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000391","status":"unknown","title":"屏東縣綠建築自治條例","last_checked_at":"2026-10-06T17:31:47+08:00","last_success_at":"2026-10-06T17:31:47+08:00","verification_status":"fetched","content_hash":"a9840e453b806502b25c5d60283f5e65fe38387c4cd2c111c0185c41238bc5a1","history":[{"observed_at":"2026-10-06T17:31:47+08:00","content_hash":"a9840e453b806502b25c5d60283f5e65fe38387c4cd2c111c0185c41238bc5a1","change_kind":"initial","revision_date":"2015-12-28"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":true,"attachments":[{"name":"屏東縣綠建築設備設施經費計算表.pdf","url":"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=863&id=GL000416&type=LAW"}],"authority":"屏東縣政府","category":"建築管理相關","content":"如附件所示。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000416","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 105 年 06 月 24 日","圖表附件":"屏東縣綠建築設備設施經費計算表.pdf","法規名稱":"屏東縣綠建築設備設施經費計算表","法規體系":"城鄉發展處","發文字號":"屏府行法字第10520903001號 令"},"promulgation_date":"2016-06-24","revision_date":"2016-06-24","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000416","status":"unknown","title":"屏東縣綠建築設備設施經費計算表","last_checked_at":"2026-10-06T17:31:51+08:00","last_success_at":"2026-10-06T17:31:51+08:00","verification_status":"attachment_pending","content_hash":"b40e950e7a5b060be219348dcfc9cb215e3af9ed65b5e2a756f333dc41f10cf6","history":[{"observed_at":"2026-10-06T17:31:51+08:00","content_hash":"b40e950e7a5b060be219348dcfc9cb215e3af9ed65b5e2a756f333dc41f10cf6","change_kind":"initial","revision_date":"2016-06-24"}],"version_count":1,"attachment_hashes":{"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=863&id=GL000416&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"一、屏東縣政府（以下簡稱本府）為實施本縣臨時性建築物之管理，以維\n護公共安全，特訂定本管理要點。\n二、本要點所稱臨時性建築物，指下列符合建築法第四條規定，且訂有使\n用期限，供臨時性使用之構造物或雜項工作物：\n(一)經目的事業主管機關核准使用或本府核准供短期使用之建築物。\n(二)供競選活動辦事處或集會使用者。\n(三)樣品屋：指專為銷售本縣轄建造執照所興建房屋為目的之臨時建\n築物，作為接待、展示、行政及其相關附屬設施。\n三、申請搭建臨時性建築物者，應由申請人於施工前檢附下列書圖文件向\n本府申請許可，經許可後始得搭建：\n(一)申請書\n(二)目的事業主管機關核准文件。(無目的事業主管機關者，免附)\n(三)建築師委託書。\n(四)土地使用權利證明文件（三個月有效期限內之土地登記簿謄本、\n地籍圖謄本及土地使用權同意書；公有土地應由管理機關出具土\n地使用權利同意書）。\n(五)現況圖、位置圖、平面圖、立面圖。\n(六)結構安全證明書（經建築師或專業技師簽證）。\n(七)屆期自行拆除切結書。\n(八)其他必要之設備圖說及現況照片。\n(九)申請樣品屋者，應檢附原建築工程建築物建造執照影本。\n前項建築物涉及消防設備者，其消防設備圖說應於取得臨時性建築許\n可後，另向本府消防局申請核准。\n四、申請使用期間在七日以內之短期展演場所，經目的事業主管機關同意\n後即可搭建。但高度在二公尺以上之臨時舞臺或高度在四公尺以上之\n臨時攤棚，應檢附申請書、目的事業主管機關核准文件、相關圖說(\n現況圖、位置圖、平面圖、立面圖)、結構安全證明書等，報請本府\n備查，免再依前點辦理申請核准程序。\n五、樣品屋申請應符合下列規定：\n（一)應於取得建照執照後方可申請。\n（二)樣品屋使用期限為一年，期限屆滿得向本府申請展期一次，合計\n不得超過二年。\n（三)絕對高度不得超過申請設置地區建築物相關管制高度線，且不得\n超過十二公尺。\n（四)不得有妨礙土地使用管制、都市計畫、區域計畫、公共安全、公\n共交通、公共衛生等事項。\n六、臨時性建築物之設置期限由本府核定之，除樣品屋外，並以六個月為\n限。但經目的事業主管機關簽報本府核定或其他法規另有規定者，得\n延長使用期限。\n前項臨時性建築物之使用期限屆滿時，應無條件自行拆除。\n七、臨時性建築物應於使用期限屆滿翌日起七日內自行拆除完畢。逾期未\n拆除者，視同違章建築，並依「屏東縣違章建築拆除優先次序表」規\n定處理，所需費用由申請人負擔。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000741","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"修正日期":"民國 111 年 04 月 26 日","公發布日":"民國 94 年 10 月 12 日","法規名稱":"屏東縣臨時性建築物管理要點","法規體系":"城鄉發展處","發文字號":"屏府城管字第11116821100號函"},"promulgation_date":"2005-10-12","revision_date":"2022-04-26","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000741","status":"unknown","title":"屏東縣臨時性建築物管理要點","last_checked_at":"2026-10-06T17:31:59+08:00","last_success_at":"2026-10-06T17:31:59+08:00","verification_status":"fetched","content_hash":"7820b297a09e7684c1642d18849b06c492dd94cf4fb3c765672f0bbef9b1f19b","history":[{"observed_at":"2026-10-06T17:31:59+08:00","content_hash":"7820b297a09e7684c1642d18849b06c492dd94cf4fb3c765672f0bbef9b1f19b","change_kind":"initial","revision_date":"2022-04-26"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"第1條\n屏東縣（以下簡稱本縣）為加強管理轄內行道樹之美化綠化，特訂定本辦\n法。\n第2條\n本辦法相關名詞定義如下：\n一、行道樹：指本縣轄內道路及綠帶上栽植之樹木（含喬木、灌木、草花\n、草皮等植栽）。\n二、毀損：指行道樹因人為因素受損或枯死。\n三、管理維護：指栽種、移植、修剪防颱、除蔓、除草、補植、澆水、施\n肥、病蟲害防治等作業。\n第3條\n本辦法主管機關為屏東縣政府（以下簡稱本府）；管理機關如下：\n一、縣道及鄉道為本府。\n二、重劃區道路及農路、市區道路、村里聯絡道路、現有巷道及都市計畫\n區內道路為各鄉（鎮、市）公所。\n前項第二款都市計畫區內道路與縣道、鄉道重疊者，以鄉（鎮、市）公所\n為管理機關。\n第4條\n新闢或拓寬寬度達二十四公尺以上之道路設置中央分隔島者，留設空間栽\n植行道樹，寬度應為一公尺以上，植穴底部並應保持透水性。但栽植確有\n困難，經報主管機關同意者，不在此限。\n第5條\n已開闢之道路，如須栽植行道樹者，由各管理機關調查後訂定栽植計畫，\n編列預算辦理。\n第6條\n行道樹宜選擇生長旺盛、枝幹堅強、樹型優美、可遮蔭、抗風、抗污染、\n耐病蟲害及傳染病，適合本縣環境氣候生長之原生種。\n第7條\n行道樹有下列情形之ㄧ者，管理機關應迅速扶正或補植：\n一、遭颱風暴雨侵襲折斷、倒伏。\n二、成活不佳、自然枯死或受病蟲侵襲。\n三、毀損或盜挖。\n四、其他自然災害。\n前項第三款規定情事，管理機關應予追償或追訴。\n第8條\n行道樹除經管理機關同意外，不得任意修剪、移植或砍伐。\n第9條\n遷移行道樹，應先擬定遷移計畫書向管理機關申請核准後始得施工；未經\n核准或未按核准之施工圖樣、方法施工致毀損行道樹者，依第十二條規定\n標準賠償。\n第10條\n行道樹及其植穴上，不得有下列行為：\n一、棄置果皮、紙屑、砂石或其他廢棄物者。\n二、未經核准，擅自張貼廣告或懸掛、樹立招牌、燈柱、電動燈光、旗幟\n等設施物者。\n三、曝曬衣物者。\n四、攀折樹木、損壞護欄或支柱等設施者。\n五、封閉栽植穴或栽植槽者。\n六、其他影響行道樹生機者。\n違反前項規定致毀損行道樹者，依第十二條規定標準賠償。\n第11條\n行道樹因老化、嚴重病蟲害或樹種混雜不齊須更新時，由管理機關擬定更\n新計畫報主管機關核准後辦理。\n第12條\n毀損行道樹應照價賠償，如無法計算時，依下列標準：\n一、樹冠弄亂、枝葉斷落或樹皮擦損之輕微毀損：賠償金額依該規格樹木\n基本單價計算。\n二、大枝折損或根群喪失達四分之一以上、二分之一以下之嚴重毀損：賠\n償金額依該規格樹木之基本單價加二倍計算。\n三、只賸主幹及少許枝葉或根群喪失二分之一以上之極嚴重毀損：賠償金\n額依該規格樹木之基本單價加三倍計算。\n四、主幹折斷、環剝樹皮、全株枯死或遭挖除之全株毀損：賠償金額依該\n規格樹木之基本單價加六倍計算，並另加補植費。\n行道樹毀損程度，由管理機關會同當地轄區警員及村（里）幹事認定。\n行道樹之基本單價及補植費依屏東縣辦理公共工程用地農作改良物及水產\n養殖物、畜禽補償遷移費查估基準計算。\n第13條\n本辦法規定之賠償金額，由管理機關負責追償，所得款項悉數解繳公庫。\n第14條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000119","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 101 年 08 月 13 日","法規名稱":"屏東縣行道樹管理辦法","法規體系":"工務處","發文字號":"屏府行法字第10125581000號 令"},"promulgation_date":"2012-08-13","revision_date":"2012-08-13","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000119","status":"unknown","title":"屏東縣行道樹管理辦法","last_checked_at":"2026-10-06T17:32:09+08:00","last_success_at":"2026-10-06T17:32:09+08:00","verification_status":"fetched","content_hash":"aaea792aa72f837a1c6fb3c396768719c9558ff9a02ac1ae080e133a3cd13a52","history":[{"observed_at":"2026-10-06T17:32:09+08:00","content_hash":"aaea792aa72f837a1c6fb3c396768719c9558ff9a02ac1ae080e133a3cd13a52","change_kind":"initial","revision_date":"2012-08-13"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"第一條    本標準依規費法第十條第一項規定訂定之。\n第二條    道路挖掘經審核通過者，應繳納許可費。但有下列各款情形之\n一者，得免繳納之：\n一、屏東縣政府（以下簡稱本府）及所屬機關（構）之申請案。\n二、配合本府公共工程所進行之造街、雨水或污水管線遷改、無自\n來水地區延管案用戶端接管、孔蓋下地或提昇、寬頻管道進駐\n及架空纜線下地等工程。\n第三條    道路挖掘許可收費依下列計算標準計徵：\n一、申請面積在二十平方公尺以下者，每件收取新臺幣一千二百元。\n二、申請面積逾二十平方公尺且在一百平方公尺以下者，每件以申\n挖面積每平方公尺新臺幣五十元計算，且不低於新臺幣一千二\n百元收取。\n三、申請面積逾一百平方公尺且在五百平方公尺以下者，每件以申\n挖面積每平方公尺新臺幣三十元計算，且不低於新臺幣五千元\n收取。\n四、申請面積逾五百平方公尺者，每件以申挖面積每平方公尺新臺\n幣二十元計算，且以不低於新臺幣一萬五千元，不高於新臺幣\n五萬元收取。\n前項各款申請展延案件，以每件新臺幣一千二百元計收。\n第四條    本標準自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000592","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"修正日期":"民國 108 年 07 月 25 日","公發布日":"民國 105 年 02 月 03 日","法規名稱":"屏東縣道路挖掘許可收費標準","法規體系":"工務處","發文字號":"屏府行法字第10827632901號 令"},"promulgation_date":"2016-02-03","revision_date":"2019-07-25","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000592","status":"unknown","title":"屏東縣道路挖掘許可收費標準","last_checked_at":"2026-10-06T17:32:10+08:00","last_success_at":"2026-10-06T17:32:10+08:00","verification_status":"fetched","content_hash":"1cf6aaa18f2703457e7b96d5fa0f0630432a332029b9bb70b6a40511790d2987","history":[{"observed_at":"2026-10-06T17:32:10+08:00","content_hash":"1cf6aaa18f2703457e7b96d5fa0f0630432a332029b9bb70b6a40511790d2987","change_kind":"initial","revision_date":"2019-07-25"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"第一章 總則\n第一條    為有效管理道路施工、提升道路服務品質及維護公共安全，特\n制定本自治條例。\n本自治條例未規定者，依其他法令辦理。\n第二條    本自治條例之主管機關為屏東縣政府(以下簡稱本府)。本自治\n條例之權限分配和委辦事項，規定如下：\n一、縣道、鄉道：管理機關為本府。\n二、農路、市區道路、原住民部落聯絡道路、村里聯絡道路、現有\n巷道、既成道路：管理機關為鄉 (鎮、市) 公所。\n前項第二款道路與縣道、鄉道有使用同一路線時，其共同使用\n部分，以本府為管理機關。但其道路附屬設施之管理不在此限。\n第一項各款道路已委託代管者，以受委託之機關為管理機關。\n第三條    主管機關及管理機關(含委辦機關)之權責劃分如下：\n一、主管機關：本縣道路施工規章、收費標準及相關規定之制定。\n二、管理機關：\n（一）受理道路施工申請及許可。\n（二）道路施工、竣工及保固維護之監督管理及規費徵收。\n（三）依本自治條例罰則規定執行違規裁罰。\n第四條    本自治條例用詞，定義如下：\n一、事業機構：指電力、電信（含軍警專用電信）、自來水、排水\n、污水、輸油、輸氣、社區共同天線廣播電視設備、有線電視\n、寬頻管道等需要利用管道或管線之事業機構或機關。\n二、道路施工：指於本縣轄內之道路，從事管(纜）線、豎桿、人\n（手）孔、閥箱與其他道路附屬設施等之新設、拆遷、換修、\n擴充、附掛或其他相類之工程行為。\n三、道路附屬設施：指市區道路條例第三條之附屬工程、公路委託\n管理辦法第二條第二項之必要設施、管頻管道及道路綠帶。\n第二章    道路施工申請許可\n第五條    事業機構進行道路施工，應向管理機關申請許可，並取得許可\n證後，始得施工。\n有下列情形之一者，管理機關得駁回其申請：\n一、事業機構於曾違反本自治條例規定，經命限期改善仍未改善。\n二、事業機構未依本自治條例繳納各項費用及罰鍰。\n三、事業機構未依本自治條例規定負擔賠償責任。\n四、事業機構未依本自治條例規定提出審查所需文件，或經命其限\n期補正屆期仍未補正所需文件。\n五、事業機構於管理機關公告禁止範圍內之道路申請施工。\n第六條    配合公共工程辦理管線（含人、手孔及電桿）遷移或埋設者，\n工程主辦機關應通知各有關事業機構配合辦理管線遷移或埋設之先\n期作業，必要時並得召開管線協調會，事業機構應於工程主辦機關\n所定期限內配合該工程為前條之申請。\n事業機構未於規定之期限內完成管線遷移或埋設，進而妨礙公\n共工程施工時，管理機關得就工程額外增加與延宕期程之費用，以\n書面行政處分命其繳納。\n第七條    事業機構因管線（道）損壞、故障或因重大災害及其他緊急事\n件，須緊急搶修時，應先以電話、傳真或網際網路向管理機關報備\n，並於三日內檢附相關申請資料及搶修施工相片補行申請許可。\n第八條    多種管線工程需挖掘同一道路時，管理機關得命各相關事業機\n構同時辦理。\n道路施工之管線屬幹線系統時，應同時配合埋設與其聯結且有\n施工必要之支線。\n第九條    管線需要通過隧道者，應自其地下通過。但經管理機關許可得\n附設於隧道壁面。\n第十條    事業機構申請道路施工應採電子網路方式辦理。但有正當理由\n無法採電子網路作業時，得暫採紙本辦理。\n第十一條    申請道路施工經審核通過者，應繳納許可費。但有下列各款\n情形之ㄧ者，得免繳納之：\nㄧ、本府及所屬機關之申請案。\n二、配合本府公共工程所進行之造街、雨水或污水管線遷改、無\n自來水地區延管案用戶端接管、孔蓋下地或提昇、寬頻管道\n進駐及架空纜線下地等工程。\n前項許可費收費之辦法，由主管機關定之。\n第十二條    新開闢、拓寬未滿三年或修建未滿二年之道路，不得申請道\n路施工。但有下列情形之ㄧ者，不在此限：\nㄧ、與國家重要建設有關之管線工程。\n二、既有管線之緊急搶修工程。\n三、軍用管線工程。\n四、用戶申請聯接自來水、污水、電力、電信或瓦斯之管線工程。\n五、道路交通控制設施之管線工程。\n六、足以影響公共安全之號誌或路燈用電等管線工程。\n七、經本府核准之管線工程。\n道路施工屬前項第四款情況之申請，須由用戶填具聯合施工\n申請書，並依第十條規定辦理。\n第十三條    有下列情形之ㄧ者，管理機關得公告禁止或限制道路施工：\nㄧ、重大慶典、重大國際性會議或活動期間。\n二、依選舉委員會公告之選舉期間及農曆年期間。\n三、預定或已實施同時埋設多種管線之道路。\n四、基於公共安全或其他交通上認為有必要者。\n第十四條    申請道路施工全線應一次申請，得採分段施工。\n前項分段施工之長度，市區以三百公尺為限，郊區以五百公\n尺為限，必要時得再縮短之。同一路段之兩側，不得同時挖掘；\n應先將已挖掘之道路回填並舖設原材質面層至原路面高程平齊後\n，始得挖掘次一路段。\n第十五條    事業機構應於許可期限內竣工及修復路面；期限屆滿未竣工\n者，其許可屆期失其效力，事業機構應立即停工並修復路面。但\n有正當理由者，事業機構得於期限屆滿日前七日向管理機關申請\n展期。\n前項展期以一次為限，其天數不得超過原申挖許可天數之百\n分之二十。但特殊情形經管理機關核准者，不在此限。\n第三章 道路施工管理\n第十六條    事業機構應於申請道路施工前勘查地上、地下設施之設置情\n形及蒐集相關資料，必要時應報請管理機關召開管線協調會。\n第十七條    事業機構應採電子網路方式向管理機關申報開工，並應通知\n道路施工地點所在之村（里）辦公處。\n第十八條    道路施工前，事業機構應依許可內容先測定施工地點及標定\n管溝寬度之定線，並使用切割機按標定線平直全厚度切割路面後\n，再行挖掘路基及路床，並不得挖損標定線範圍外之路面；如遇\n有障礙物而有辦理變更之必要者，應報請管理機關同意後始得變\n更之。\n第十九條    道路施工期間，事業機構應依核准計畫及相關法令辦理，並\n向管理機關提供每日施工動態資料，管理機關並得派員現場督導\n查核，經發現缺失者，管理機關得命事業機構限期改善。\n第二十條    道路施工期間，事業機構應妥為放置施工材料，施工現場應\n設置告示牌，標明工程名稱、主辦單位、承包廠商、工程概要、\n服務及申訴電話、開工及預定完工日期等內容，且工程告示牌上\n應張貼護貝完妥之道路施工許可證影本，並應遵守道路交通、職\n業安全衛生等相關法令規定。\n第二十一條    道路施工之土石方及廢棄物，事業機構應隨挖隨即運離，\n並依有關規定處理，不得堆放於管溝邊及道路上。\n第二十二條    事業機構於道路設置人（手）孔、閥箱及中心樁（含基座\n）等構造物延伸至路面之蓋板，應遵守下列規定：\n一、其強度最低為能負荷公路橋梁設計規範載重車輛(HS20)之\n通行標準。\n二、其頂面應與路面平齊、密合保持平順。\n事業機構應定期巡視前項蓋板與銜接路面之高低差，於超\n過零點六公分時，應立即改善。\n第二十三條    事業機構因道路施工而損壞或滅失公共設施時，應立即通\n知該公共設施之管理機關，並即時修復或負擔修復費用。\n前項所稱公共設施，包括路樹、標誌、標線、號誌、交通\n控制、消防栓、都市計畫道路中心樁及其他設施。\n事業機構有損壞管線情事應即通知管理機關、原管線機構\n及相關單位會同處理，不得逕行施工。\n第二十四條    事業機構應辦理道路挖掘施工(含修復)相關查驗。\n路面回填品質試驗查驗應委請具有財團法人全國認證基金\n會認證標記之實驗室辦理。\n管理機關得隨時抽驗施工品質，其抽驗相關費用由事業機\n構全額負擔。\n第二十五條    道路施工之路面修復方式，除配合國家重大工程經主管機\n關同意外，管理機關得採取下列方式之一辦理：\nㄧ、向事業機構收取道路挖補費辦理修復。\n二、協調或要求事業機構自行統一施工，並監督其施工及命其\n限期完成修復道路。\n前項道路挖補費收費辦法，由本府定之。\n第二十六條    事業機構於道路施工時涉及土地所有權爭議時，應停止施\n工，並負責協調解決後再行施工，不得以管理機關已核准為由\n繼續施工。\n第四章 道路管線與圖資維護\n第二十七條    事業機構應於竣工日起三十日內將竣工文件及圖資等採電\n子網路方式報請管理機關備查。\n前項竣工圖資申報更新之事項，其相關辦法由本府定之。\n第二十八條    事業機構申報竣工後，應負保固二年之責任；於保固期限\n內，路面因挖掘或地基回填不實，致發生路面塌陷、龜裂、鬆\n脫、高低不平或下陷變形等情形，管理機關得命事業機構限期\n修復，屆期未修復者，管理機關得代為修復，其修復費用應由\n事業機構負擔。\n第二十九條    事業機構應於每年十月三十一日前擬訂次年度管線檢測維\n護計畫報請管理機關核定。\n前項執行成果應定期彙報管理機關備查。\n第三十條    事業機構於道路範圍內辦理開啟或封閉人(手)孔作業時應通\n知管理機關，並設置必要之交通安全維護措施。\n第五章 罰則\n第三十一條    事業機構違反前條規定，或因道路施工或維護管理有欠缺\n，致侵害他人權利或發生國家賠償責任者，應依相關法律負其\n責任。\n第三十二條    事業機構有下列情形之一者，處新臺幣二萬元以上十萬元\n以下罰鍰，並得命限期改善；屆期仍未改善或補辦手續者，得\n按次處罰。必要時，並得命其限期回復原狀、廢止原許可或暫\n停其申請道路施工許可證一個月至六個月：\nㄧ、違反第五條第一項及第七條規定，未申請許可。\n二、違反第八條第一項規定，未與其他管線同時挖掘埋設。\n三、違反第十五條規定，未立即停工並修復路面。\n四、違反第十九條規定，未依核准計畫辦理道路施工。\n五、違反第二十三條第三項規定，未通知原管線機構及相關單\n位會同處理，私自裝接或為施工之行為。\n第三十三條    事業機構有下列情形之一者，經管理機關通知限期改善，\n屆期仍未改善者，處新臺幣一萬元以上五萬元以下罰鍰，並得\n按次處罰。必要時，得暫停其申請道路挖掘許可證三個月：\nㄧ、未依第十四條規定分段施工。\n二、未依第十七條或第二十七條規定申報開工或提報竣工圖資。\n三、未依第十八條規定辦理道路施工。\n四、未依第二十條規定施工材料妥為置放或設置施工告示牌。\n五、未依第二十一條規定，道路施工之土石方及廢棄物隨挖隨\n即運離，堆置於管溝邊及道路上。\n六、未依第二十二條規定設置蓋板。\n七、未依第二十三條第一項規定修復施工損壞或滅失之公共設\n施。\n八、未依第二十四條規定辦理路面回填品質試驗。\n九、未依第二十六條規定停止施工。\n十、有第二十八條所定因挖掘或地基回填不實，致發生路面塌\n陷、龜裂、鬆脫、高低不平、下陷變形等情形。\n十一、未依第二十九條規定，年度檢測維護管理計畫報請管理\n機關核定及執行者。\n十二、違反第三十條規定，未通知管理機關。\n第六章 附則\n第三十四條    本自治條例所需書表格式，由本府定之。\n第三十五條    本自治條例自公布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000709","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 110 年 05 月 19 日","法規名稱":"屏東縣道路施工管理自治條例","法規體系":"工務處","發文字號":"屏府行法字第11019879501號令"},"promulgation_date":"2021-05-19","revision_date":"2021-05-19","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000709","status":"unknown","title":"屏東縣道路施工管理自治條例","last_checked_at":"2026-10-06T17:32:09+08:00","last_success_at":"2026-10-06T17:32:09+08:00","verification_status":"fetched","content_hash":"a7c0cbc1254a1bfc1f061187097ba7edc46883483b958d4a566b6ff0513c24d9","history":[{"observed_at":"2026-10-06T17:32:09+08:00","content_hash":"a7c0cbc1254a1bfc1f061187097ba7edc46883483b958d4a566b6ff0513c24d9","change_kind":"initial","revision_date":"2021-05-19"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"第 一 章 總則\n第 1 條\n為有效管理屏東縣道路，特制定本自治條例。\n第 2 條\n本自治條例所稱之道路，指縣轄內之縣道、鄉道、市區道路、農路、重劃\n區道路、廣場及村里聯絡道路。但委託代養之縣道不在此限。\n第 3 條\n本自治條例用詞之定義如下：\n一、村（里）聯絡道路：都市計畫區外供公眾通行之道路。\n二、路基：指承受路面、路肩之土壤部分，其幅度包括路基穩定所形成填\n挖土之邊坡。\n三、路面：指路基上供車輛及行人通行，以各種材料舖築之承受層。\n四、路肩：指路基淨寬減除路面寬度，所餘之路基。\n五、道路附屬設施：包含路燈、行道樹與植栽、道路綠帶、側溝、寬頻管\n道、天橋、人行道及經主管機關核定之其他附屬工程。\n六、道路挖掘：指在本縣轄內之道路、人行道、道路綠帶，因管（纜）線\n、豎桿、人（手）孔、閥箱等之新設、拆遷、換修、擴充或其他用途\n而挖掘道路。\n第 二 章 道路管理權責\n第 4 條\n本自治條例所稱主管機關為屏東縣政府（以下簡稱本府），管理機關（單\n位）如下：\n一、縣道、鄉道為本府工務處。\n二、重劃區道路及農路、市區道路、村里聯絡道路、現有巷道及其道路附\n屬設施為各鄉、鎮、市公所。\n前項第一款道路之路燈由各鄉（鎮、市）公所負責養護。\n道路之管理與養護，必要時得委託公私立機構、團體辦理。\n第 5 條\n主管機關與管理機關（單位）之權責劃分如下：\n一、主管機關：\n（一）有關縣轄道路縣規章之擬定事項。\n（二）有關中央補助及縣預算辦理縣轄道路之修築、改善、養護計畫之審\n議及其他事項。\n（三）有關縣轄道路管理之監督及輔導。\n二、管理機關（單位）：\n（一）有關轄區內道路管理規定之擬訂事項。\n（二）有關轄區內道路之修築、改善及養護計畫之擬訂及執行事項。\n（三）有關轄區內道路之管理事項。\n第 6 條\n管理機關（單位）應於年度開始前，依實際需要擬定道路及附屬設施之修\n築、改善及養護計畫，報請本府備查。\n第 三 章 道路修築維護\n第 7 條\n修築、改善或養護路幅狹窄或交通量頻繁之道路，應儘量利用夜間分段施\n工，施工地段並應依道路交通標誌標線號誌設置規則，設置各項安全措施\n。改善或翻修路基、路肩或路面時，仍需維持行車者，應明顯標示維持行\n車之車道，並設置警告標誌。\n第 8 條\n人民或團體自行修築道路，應先出具土地無償使用同意書向管理機關（單\n位）申請核准，完工後應移交管理機關（單位）管轄。\n第 9 條\n管理機關（單位）對轄區道路應經常養護，並維持各項設施之完整，遇有\n災害應迅 速修復，以維道路暢通。\n第 10 條\n道路整修時，應注意路拱及側溝排水，並通知管線機構配合改善人（手）\n孔、閥門等設施，使其頂面與路面平齊，未平齊部分應限期改善。\n第 11 條\n道路兩旁溝渠除經許可外，不得加以侵占、利用、堆置雜物或設置其他有\n礙水流之物體。管理機關（單位）應會同有關單位定期或經常派員全面檢\n視，如發現違規情事，應即依法排除。\n第 12 條\n新建橋樑、涵洞、隧道或地下道時，應先協調有關管線機構，提出預留之\n設施位置或加設必要之結構計畫，所增加之費用，由該管線機構負擔。\n第 13 條\n道路管理機關（單位）對於橋樑、涵洞、隧道或地下道各部結構及附屬之\n照明、通風或排水設備，應作定期安全檢查，並經常作必要之補強維護。\n第 14 條\n各鄉（鎮、市）公所應經常維護檢查路燈設備，並清潔照明設施之玻璃罩\n，不得妨礙人車安全，如有損壞應隨時換修。但遭人為毀損者，由肇事者\n負擔損害賠償及相關法律責任。\n第 四 章 道路管理\n第 15 條\n申請挖掘道路時，應先向管理機關（單位）申請，並經許可後始可挖掘。\n前項申請人之資格限以公共設施或公用事業之公共設施埋設物設置機關（\n構），個（私）人申請不受理，但經本府核可者，得准予申請。\n第 16 條\n申請人申請道路挖掘應具備下列文件：\n一、申請書（含預定開、竣工日期）。\n二、施工範圍位置圖。\n三、管線埋設平面圖及標準斷面圖。\n四、人（手）孔及閥箱位置圖。\n五、工程進度表。\n六、交通維持計畫。\n七、其他管理機關（單位）要求檢附之相關資料。\n道路挖掘工期三十日以上者，於申請挖掘許可時必須檢附屏東縣道路交通\n安全聯席會報之核准文件。\n第 17 條\n道路新築、拓寬完成三年內或翻修改善完成後一年內或本府公告道路禁挖\n期間，不得挖掘。但有下列各款情形之一者，不在此限：\n一、與國家重要建設有關之管線工程。\n二、既有管線之修理工程。\n三、重大軍事管線工程。\n四、道路交通號誌之有關管線工程。\n五、其他特殊情形，經管理機關（單位）核准者。\n第 18 條\n管理機關（單位）受理道路挖掘申請後應於十五日內完成審查；經審查不\n合格者，應敘明理由通知申請人於期限內補正；逾期未補正或補正後複審\n仍不合格者，管理機關（單位）應將申請案件駁回。\n經審查合格者，核發道路挖掘許可證，並由管理機關（單位）核定應繳納\n之路面修復費用，並通知申請人繳納。\n依本自治條例規定核發之許可，僅為道路挖掘之許可，申請人如有侵害他\n人或生命、身體或財產，應負其法律責任。\n第 19 條\n申請道路挖掘作業程序及代辦路面修復費收費基準由本府另定之。\n第 20 條\n管線需要通過隧道者，應自其地下通過。但經管理機關（單位）認為不影\n響隧道之安全、通風、照明、淨空及觀瞻者，得附設於隧道壁面。\n第 21 條\n管線機構埋設於人行道之地下管線，其人（手）孔或閥箱等附屬設備之頂\n面，未與人行道齊平者，應限期令其改善，逾期未改善者，管理機關（單\n位）得代為執行，費用由管線機構負擔。\n第 22 條\n多種管線計畫型挖掘工程必須在同一道路進行計畫型挖掘埋設時，管理機\n關（單位）應協調各相關管線機構同時申請。\n第 23 條\n申請人因工程施工需變更、增加挖掘面積者，應敘明理由及檢具相關證明\n文件向管理機關（單位）申請變更許可。\n申請人無法於期限內完工者，應於期限屆滿前，敘明理由及檢具相關證明\n文件向管理機關（單位）申請延期許可。\n第 24 條\n申請人未在許可期限內竣工，除已依第二十三條第二項規定申請延期外，\n該許可即失效。\n第 25 條\n申請人因管線（溝）損壞、故障或因重大災害及其他緊急事件，須緊急搶\n修時，應通知管理機關（單位）及轄區警察機關後施工，並於下列時間向\n管理機關（單位）補辦申請許可：\n一、在上班時間內搶修者，應於當日內申請。\n二、在上班時間外搶修者，應於翌日上午十時前申請，但遇星期日或例假\n日得順延至上班第一天上午十時前申請。\n第 26 條\n道路挖掘施工前，申請人應通知管理機關（單位）與轄區警察機關，並預\n先蒐集有關資料，必要時須查看地下埋設物位置及深度。\n第 27 條\n道路挖掘管溝寬度不得少於夯壓機具最大寬度加十公分。\n道路挖掘施工時，應使用切割機按原標定線平直、全厚度切割、並不得損\n毀其他管線及管溝範圍外之路面。\n挖掘道路施工時，各種施工材料應妥為放置，並設置下列各項設施：\n一、施工起迄點設置告示牌，內容依公共工程委員會規定，並張貼挖路許\n可證影本。\n二、設立交通安全措施，在挖掘位置前方及後方設置拒馬、標誌及夜間加\n設紅色警示燈。\n三、沿管溝兩側及人（手）孔週圍設立交通錐或圍籬，夜間並加設紅色警\n示燈。\n四、挖掘管溝深度大於一點五公尺或管溝壁有塌方之虞者，應設立臨時擋\n土措施。\n第 28 條\n道路施工中，管理機關（單位）發現下列違規事項者，應依本自治條例處\n罰，並通知申請人限期改善：\n一、未於規定期限及時段內施工。\n二、未依規定覆蓋止滑鐵板（含覆土板）或未舖設臨時瀝青混凝土面層有\n礙交通。\n三、收工時未將殘方、施工設備、機具、剩餘材料等運離現場並打掃乾淨\n。\n四、挖掘部分未依規定回填、夯實，或未依規定埋設。\n五、人（手）孔蓋高程未能配合道路調整或施工品質不良。\n六、施工導致周邊路面有下陷變形等情形。\n七、每次施工之道路回填、夯實不確實或舖設瀝青混凝土面層未與原路面\n高程齊平。\n八、未落實執行交通維持計畫書。\n第 29 條\n道路挖掘施工時，於施工期間及驗收合格後一年內，路面如有龜裂、下陷\n變形等情形，管理機關（單位）得會同申請人辦理檢測，經查明可歸責於\n申請人之事由，得限期由申請人修復。\n第 30 條\n道路挖掘如損壞路燈、號誌、消防栓、制水閥等公共設施以及其他管線者\n，應即通知相關單位會同處理，並即予修復；如損壞標線、標誌等交通安\n全設施者，申請人應予以修復。\n第 31 條\n道路挖掘施工區域未完全隔離者，在未施工時段，應將已挖掘未回填部分\n，加蓋止滑蓋板及採取必要之安全警示措施，開放通行；加蓋之止滑板應\n避免滑動且與路面保持平順。\n第 32 條\n申請人於道路設置人（手）孔、閥箱及中心樁（含基座）等構造物延伸至\n路面之蓋板時，其強度最低為能負荷公路橋樑設計規範載重車輛（HS20）\n通行標準；其頂面應與路面平齊。\n第 33 條\n道路挖掘竣工後，申請人應完成路基回填、路面修復及標字標線修復。\n違反前項規定者，管理機關（單位）應命其限期改善。\n第 34 條\n有下列情形之一者，管理機關（單位）得指定路線或區域，管制道路挖掘\n：\n一、國家慶典節日。\n二、重大國際性會議、選舉期間。\n三、預定或已實施多種管線同時埋設之道路。\n四、基於公共安全或其他交通上認為有必要。\n前項管制挖掘事項，不含緊急搶修、檢修及用戶聯接管線工程。\n第 35 條\n道路挖掘施工時，如涉及私有土地產權問題，應停止挖掘，由申請人負責\n協調解決後再行施工，不得以管理機關（單位）已核准為由而繼續施工。\n第 五 章 罰則\n第 36 條\n申請人如有下列情形之一者，處新臺幣三萬元以上十萬元以下罰鍰：\n一、未經許可擅自挖掘。\n二、變更道路挖掘面積，未申請許可或未申請完工延期，違反本自治條例\n第二十三條者。\n經通知限期改善，而逾期未改善或改善仍不符規定者，得按次處罰。\n第 37 條\n申請人如有下列情形之一者，處新臺幣三千元以上一萬五千元以下罰鍰：\n一、違反本自治條例第二十一條規定，限期未改善者。\n二、因管線（溝）損壞、故障或因重大災害等緊急事件，違反本自治條例\n第二十五條，未補辦申請許可者。\n三、違反本自治條例第二十七條，挖掘道路施工時，未設置第三項各款規\n定設施者。\n四、違反本自治條例第二十八條各款違規行為者。\n五、違反本自治條例第二十九條，可歸責申請人事由，限期修復未修復者\n。\n六、違反本自治條例第三十條，損壞標線、標誌等交通安全設施未予以修\n復者。\n七、違反本自治條例第三十一條，未加蓋止滑蓋板者。\n八、違反本自治條例第三十三條，限期改善未改善者。\n違反前項規定，經通知限期改善而逾期未改善者，得按次處罰或廢止其許\n可證。\n第 38 條\n本自治條例規定之罰鍰，由道路主管機關處罰之。\n第 39 條\n本自治條例自公布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:FL052458","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 97 年 08 月 22 日","法規名稱":"屏東縣道路管理自治條例","法規體系":"工務處","發文字號":"屏府行法字第0970171555號"},"promulgation_date":"2008-08-22","revision_date":"2008-08-22","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=FL052458","status":"unknown","title":"屏東縣道路管理自治條例","last_checked_at":"2026-10-06T17:32:08+08:00","last_success_at":"2026-10-06T17:32:08+08:00","verification_status":"fetched","content_hash":"36bf9068c0d9e6b9e457bbe6d76f77bfa91a260ddc11c7a975d010900aa84546","history":[{"observed_at":"2026-10-06T17:32:08+08:00","content_hash":"36bf9068c0d9e6b9e457bbe6d76f77bfa91a260ddc11c7a975d010900aa84546","change_kind":"initial","revision_date":"2008-08-22"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"第一條    本標準依都市危險及老舊建築物加速重建條例（以下簡稱本條\n例）第七條規定訂定之。\n第二條    依本條例申請住宅區基地重建之案件，得放寬建蔽率。但不得\n超過都市計畫法臺灣省施行細則所訂住宅區建蔽率百分之六十。\n依本標準放寬建蔽率案件，仍應符合建築法令及都市計畫法令\n之退縮建築規定。\n第三條    本標準施行日期，自發布日至中華民國一百十六年五月三十一\n日止。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000609","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 108 年 07 月 05 日","法規名稱":"屏東縣都市危險及老舊建築物加速重建建蔽率放寬標準","法規體系":"城鄉發展處","發文字號":"屏府行法字第10825049101號 令"},"promulgation_date":"2019-07-05","revision_date":"2019-07-05","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000609","status":"unknown","title":"屏東縣都市危險及老舊建築物加速重建建蔽率放寬標準","last_checked_at":"2026-10-06T17:31:52+08:00","last_success_at":"2026-10-06T17:31:52+08:00","verification_status":"fetched","content_hash":"b821d875ef2271bcde87892ad9ec7d23001b6215e1717074f7a542fe28052738","history":[{"observed_at":"2026-10-06T17:31:52+08:00","content_hash":"b821d875ef2271bcde87892ad9ec7d23001b6215e1717074f7a542fe28052738","change_kind":"initial","revision_date":"2019-07-05"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"第一條    本辦法依都市危險及老舊建築物加速重建條例（以下簡稱本條例）第四條\n第一項規定訂定之。\n第二條    本辦法之主管機關為屏東縣政府（以下簡稱本府）。\n第三條    本辦法之申請資格如下。但中央主管機關另有規定者，從其規定：\n一、受評估建築物應坐落於本縣發布之都市計畫範圍內。\n二、申請人應為建築物所有權人；如建築物為共有者，應有建築物所有權人逾\n半數之同意，並推派一人為代表人。\n第四條    本府補助結構安全性能評估費用，其額度規定及總樓地板面積認定方式，\n依中央主管機關補助結構安全性能評估費用辦法（以下簡稱評估費用辦法）第\n三條規定辦理。\n評估機構及審查機構之收費標準如高於本府補助額度時，超出部分應由申\n請人負擔。\n第五條    申請結構安全性能評估費用補助應檢附下列文件：\n一、申請書。\n二、建築物權利證明文件；如建築物為共有者，檢附建築物所有權人逾半數之\n同意書及其建築物權利證明文件。\n三、建築物使用執照影本或經本府認定之合法建築物證明文件。\n四、其他經本府指定之文件。\n五、申請耐震能力詳細評估費用補助者，除前四款文件外，並須檢附耐震能力\n初步評估結果報告書影本。\n第六條    申請案件有評估費用辦法第六條各款規定情事者，不予補助。\n第七條    申請人請撥結構安全性能評估費用補助應檢附下列文件：\n一、申請函。\n二、補助核准函。\n三、補助評估費用之請撥領據。\n四、評估機構開立予申請人之統一發票影本。\n五、申請案評估報告書（一式三份及電子檔光碟片）。\n六、評估報告書審查符合規定之證明文件。\n七、耐震能力詳細評估案件須檢附與評估機構簽訂之契約書。\n八、其他經本府指定之文件。\n辦理耐震能力初步評估查核之評估機構及辦理耐震能力詳細評估審查機構\n，得檢具下列文件請撥審查費用：\n一、申請函。\n二、審查案件之補助核准函。\n三、補助審查費用之請撥領據。\n四、審查機構開立予申請人之統一發票影本。\n五、評估報告書審查符合規定之證明文件。\n六、耐震能力詳細評估案件須檢附審查案件之評估費用證明文件。\n七、其他經本府指定之文件。\n第八條    申請文件不符合規定者，申請人應於本府通知限期補正；逾期未完成補正\n者，駁回其申請。\n第九條    有下列情事之一者，本府得撤銷或廢止原核准補助案，並得追繳已撥付之\n全部或部分補助款：\n一、申請文件有隱匿、虛偽不實或造假之情事。\n二、除案情特殊，經本府個案核准外，申請人未於執行評估期間配合評估，致\n逾期未完成評估。\n三、申請人放棄申請之情事。\n四、經評估機構判定申請案具不可抗力因素造成評估有困難。\n五、其他違背法令之情事。\n第十條    其他結構安全性能評估補助之相關事宜由本府公告之。\n第十一條    本辦法所需書表格式，由本府定之。\n第十二條    本辦法自發布日施行，適用期間依本條例規定。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000551","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 107 年 08 月 28 日","法規名稱":"屏東縣都市危險及老舊建築物結構安全性能評估費用補助辦法","法規體系":"城鄉發展處","發文字號":"屏府行法字第10771260401號 令"},"promulgation_date":"2018-08-28","revision_date":"2018-08-28","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000551","status":"unknown","title":"屏東縣都市危險及老舊建築物結構安全性能評估費用補助辦法","last_checked_at":"2026-10-06T17:31:52+08:00","last_success_at":"2026-10-06T17:31:52+08:00","verification_status":"fetched","content_hash":"72ce3a82b17ef6d26691960d52870bdd6db9df98f965f9cc0608196d499210e7","history":[{"observed_at":"2026-10-06T17:31:52+08:00","content_hash":"72ce3a82b17ef6d26691960d52870bdd6db9df98f965f9cc0608196d499210e7","change_kind":"initial","revision_date":"2018-08-28"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"附表.pdf","url":"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=11729&id=GL000883&type=LAW"}],"authority":"屏東縣政府","category":"建築管理相關","content":"一、屏東縣政府（以下簡稱本府）為辦理都市更新需要及執行都市更\n新條例(以下簡稱本條例)第二十二條及第二十三條之規定事項，\n特訂定本基準。\n二、依本基準自行劃定之更新單元，不得位於農業區、保護區等非都\n市發展用地。\n三、土地及合法建築物所有權人於都市更新地區內自行劃定都市更新\n單元者，應以一完整之計畫街廓為原則。但因計畫街廓過大或其\n他特殊因素確難一次辦理者，得依下列基準劃定：\n(一)市鎮計畫地區：\n1.臨接八公尺以上之計畫道路或本府認定之現有巷道，且基地\n面積在一千平方公尺以上。\n2.臨接二條計畫道路或本府認定之現有巷道，且基地面積在七\n百平方公尺以上。\n(二)鄉街計畫與特定區計畫地區：\n1.臨接計畫道路或本府認定之現有巷道，且基地面積在七百平\n方公尺以上。\n2.街廓內相鄰土地業已建築完成，無法合併更新，且無礙建築\n設計及市容觀瞻並為一次更新完成，其面積在七百平方公尺\n以上。\n(三)跨街廓更新單元劃設，其中應至少有一街廓符合第一款至第二\n款規定之一，並採整體開發，且不影響各街廓內相鄰土地之開\n發者。\n前項所稱街廓，係以基地四週面臨計畫道路為原則。如因基地鄰\n接永久性空地、公園、廣場、堤防或河川等，其鄰接部分邊界得\n視為街廓邊界。\n四、未經本府劃定應實施更新之地區，土地及合法建築物所有權人自\n行劃定更新單元申請實施都市更新事業者，除應符合前點規定外\n，並應符合下列各款規定：\n(一)未經劃定都市更新地區自行劃定更新單元之建築物及地區環\n境評估指標(附表)之其中二項；如屬跨街廓劃定更新單元，\n應合併檢討符合指標之其中二項。\n(二)更新單元內既有建築面積占單元總土地面積之比率，不得小\n於法定建蔽率二分之一。\n五、更新單元以重建方式實施者，符合下列情形之一且經本府核准者\n，得不受第三點及第四點規定限制：\n(一)合法建築物因地震、風災、水災、火災、爆炸或其他不可抗\n力遭受損害，亟需重建。\n(二)高氯離子混凝土建築物或輻射污染建築物，經本府認定有危\n險之虞，應予拆除或補強者。\n(三)符合都市更新耐震能力不足建築物而有明顯危害公共安全認\n定辦法第三條規定。\n(四)經建築主管機關依建築法規、災害防救法規通知限期拆除、\n逕予強制拆除，或評估有危險之虞應限期補強或拆除者。\n前項各款建築基地周邊鄰接土地得合併辦理更新，但其土地面積合\n計不得超過前項各款建築基地面積加總。\n六、更新單元內之合法建築物全部以整建或維護方式實施者，得不受\n第三點及第四點規定限制。但位於未經本府劃定應實施更新之地\n區，土地及合法建築物所有權人自行劃定整建或維護之都市更新\n單元，除都市計畫或都市更新計畫另有規定外，至少應為屋齡二\n十年以上之一幢合法建築物，且符合下列規定之一者：\n(一)連棟透天式或雙併式接續達三棟以上。\n(二)整幢五層樓以上。\n(三)單棟建物，經本府同意得不受前二款規定限制。\n七、土地及合法建築物所有權人自行劃定更新單元致同一街廓內其他\n土地無法劃定者，依本條例第二十二條及第三十二條規定舉辦公\n聽會時，應一併通知其他土地及合法建築物所有權人參加，徵詢\n其參與更新之意願並協調。\n八、本基準所列事項，應於都市更新事業概要中載明；其依本條例第\n二十二條第二項逕行擬訂都市更新事業計畫辦理者，應於都市更\n新事業計畫中載明。\n依都市更新會設立管理及解散辦法第三條第四款規定，已達本條\n例第二十二條第二項前段規定之同意比率，申請核准籌組都市更\n新會時，即應依本基準所列事項載明。\n更新單元範圍不得重疊，但符合本條例第三十七條規定並依本條\n例第三十二條規定申請事業計畫報核者，不受已核准籌組都市更\n新會或事業概要之範圍限制。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000883","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"修正日期":"民國 114 年 06 月 16 日","公發布日":"民國 106 年 09 月 26 日","圖表附件":"附表.pdf","法規名稱":"屏東縣都市更新單元劃定基準","法規體系":"城鄉發展處","發文字號":"屏府城都字第11401483871號 令"},"promulgation_date":"2017-09-26","revision_date":"2025-06-16","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000883","status":"unknown","title":"屏東縣都市更新單元劃定基準","last_checked_at":"2026-10-06T17:32:07+08:00","last_success_at":"2026-10-06T17:32:07+08:00","verification_status":"fetched","content_hash":"adc2b0089e300e8f40aaac0af5235b6682fb085da92ca1098d1a44264dcc4a9d","history":[{"observed_at":"2026-10-06T17:32:07+08:00","content_hash":"adc2b0089e300e8f40aaac0af5235b6682fb085da92ca1098d1a44264dcc4a9d","change_kind":"initial","revision_date":"2025-06-16"}],"version_count":1,"attachment_hashes":{"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=11729&id=GL000883&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"屏東縣都市計畫保護區農業區土地使用審查要項表及申請書.pdf","url":"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=11628&id=GL000824&type=LAW"}],"authority":"屏東縣政府","category":"建築管理相關","content":"一、屏東縣政府為審查本縣都市計畫保護區農業區內核准使用之各項設施\n案件，特訂定本要點。\n二、都市計畫保護區、農業區依都市計畫法臺灣省施行細則第二十七條、\n二十九條第一項但書規定設置之各項設施(該細則第三十條所規定者\n不在此限)，除都市計畫說明書或其他法令另有規定者，從其規定外，\n應先經各該目的事業主管機關同意設置後（加油站依加油站設置管理\n規則申請者除外），再依本要點規定申請土地核准使用。\n三、申請基地面臨之道路應為已由政府或私人開闢完竣可通行車輛之都市\n計畫道路或現有巷道為限。\n前項申請基地未直接面臨可通行道路者，應依下列規定辦理，並自行\n開闢完成可通行之通路後，始得據以申請使用：\n(一)面臨未全部開闢之計畫道路，應取得該未開闢道路用地之土地使\n用權利證明文件。\n(二)受現有溝渠區隔者，應取得該目的事業主管機關同意使用或架設\n橋涵之權利證明文件。\n四、第二點之各項設施不得在下列地區設置：\n(一)農地重劃區。但經本府農業單位同意者，不在此限。\n(二)保安林地。但經林業主管機關同意者，不在此限。\n(三)軍事禁建區、都市計畫禁建區及其他依法公告之禁建區。\n(四)自然地景、野生動物保護區或野生動物重要棲息環境。\n(五)水源水質水量保護區。但經轄區環保主管機關、水利主管機關及\n自來水主管機關同意者，不在此限。\n(六)斷層帶或環境地質上有崩塌滑動危險之虞之地區。\n(七)其他法令規定禁止或經本府認定不適宜使用之地區。\n五、申請基地範圍原始地形平均坡度不得超過百分之三十；位於山坡地地\n區者，依照建築技術規則建築設計施工編第十三章第一節山坡地基地\n不得開發建築認定基準之規定辦理。\n前項平均坡度應依建築技術規則建築設計篇第十三章之平均坡度定義\n計算。\n六、申請基地面積不得超過三千平方公尺。但同一申請者於同一地號或毗\n鄰土地申請數家相關設施，如經確認不影響附近農業生產環境及交通\n順暢，且不違背設施置之相關規定者，得同意申請設置，惟其申請基\n地之面積合計仍不得超過一公頃。\n前項申請基地面積本要點其他另有規定者，不在此限。七、向本府申\n請時應檢具下列文件：\n(一)申請書：載明申請人之姓名或機關名稱及負責人、住址、電話、\n申請地號、基地面積、申請事由，並由申請人簽名及蓋章。(如附\n表)\n(二)基地周圍都市計畫圖：由申請人提供正確標示基地境界線鄰近範\n圍內現有相關地物或設施之都市計畫圖，其比例尺以該都市計畫\n圖為準。\n(三)最近三個月內核發之地籍圖謄本、土地登記簿謄本、土地使用分\n區證明及土地同意使用之證明文件(申請人為土地所有權人時免附\n)。\n(四)地形圖：申請基地位於山坡地者，應標示地形、地物等高線(等高\n線間隔五十公分)，其比例尺不得小於六百分之一。\n(五)計畫書（載明計畫內容概要）、平面配置圖（其比例尺不得小於\n六百分之一）。\n(六)其他相關文件。\n八、申請基地於農業區或保護區土地屬農業發展條例第三條所稱之耕地，經\n核准作非農業使用者，得依該條例相關規定申請變更地目或分割及農業\n區或保護區土地屬農業用地者，經核准作非農業使用，應依農業發展條\n例第十二條及其相關法令規定，繳交農業用地變更回饋金。\n九、各項設施申請核准使用時，應依下列規定辦理：\n(一)露營設施：依露營場管理要點辦理。\n(二)前款以外各項設施：依本要點及「都市計畫保護區、農業區土地使用審查要項表」辦理","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000824","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"修正日期":"民國 112 年 12 月 22 日","公發布日":"民國 91 年 02 月 05 日","圖表附件":"屏東縣都市計畫保護區農業區土地使用審查要項表及申請書.pdf","法規名稱":"屏東縣都市計畫保護區農業區土地使用審查要點","法規體系":"城鄉發展處","發文字號":"屏府城都字第11273687200號函"},"promulgation_date":"2002-02-05","revision_date":"2023-12-22","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000824","status":"unknown","title":"屏東縣都市計畫保護區農業區土地使用審查要點","last_checked_at":"2026-10-06T17:32:01+08:00","last_success_at":"2026-10-06T17:32:01+08:00","verification_status":"fetched","content_hash":"91f4b681e1c8dab31c967a7fffd9a8f27a6e5c38aaa2ed05ab8c932e90b1277e","history":[{"observed_at":"2026-10-06T17:32:01+08:00","content_hash":"91f4b681e1c8dab31c967a7fffd9a8f27a6e5c38aaa2ed05ab8c932e90b1277e","change_kind":"initial","revision_date":"2023-12-22"}],"version_count":1,"attachment_hashes":{"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=11628&id=GL000824&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"第一條    本標準依據屏東縣建築管理自治條例第二十一條規定訂定之。\n都市計畫書土地使用分區管制要點（計畫）訂有退縮規定者，從其\n規定，不適用本標準。\n第二條    騎樓之構造型式及各部尺寸如下：\n一、凡新建、增建、改建、修建之建築物，其基地在商業區、文教區、\n學校用地、面臨寬度七公尺以上計畫道路，在住宅區面臨寬度十\n公尺以上之計畫道路，應設置騎樓或庇廊。但讓出其寬度作為無\n遮簷人行道退後建築，經屏東縣政府（以下簡稱本府）認可者，\n不在此限。本府主管建築機關基於整體景觀之規劃，得另為必要\n之規定。\n二、騎樓之寬度自建築線算起一律為三‧九公尺，但如因情形特殊，\n確無妨礙市容觀瞻及交通者，其騎樓寬度得由主管建築機關逕\n行認定。\n三、騎樓柱正面，應位於距建築線（所臨道路之溝邊石外緣）三十\n公分之位置。\n四、騎樓地面應以石、磚、混凝土、磁磚或瀝青等材料舖實。\n五、騎樓地面應與人行道齊平，無人行道者應高於道路邊界處十五\n公分，表面應依前款舖裝平實，不得裝置任何台階或阻礙物，\n並應向道路境界線作成四十分之一瀉水坡度，並依市區道路條\n例第九條規定辦理。無遮簷人行道之構造仍應依照本款及前款\n規定辦理。\n六、基地正面及側面應設置騎樓者，其騎樓之寬度應依第一款規定\n設置，其截角長度應依屏東縣建築管理自治條例第二十二條規\n定設置。\n第三條    本標準自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:FL052537","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"修正日期":"民國 105 年 02 月 22 日","公發布日":"民國 71 年 04 月 30 日","法規名稱":"屏東縣都市計畫區法定騎樓設置標準","法規體系":"城鄉發展處","發文字號":"屏府行法字第10505497801號 令"},"promulgation_date":"1982-04-30","revision_date":"2016-02-22","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=FL052537","status":"unknown","title":"屏東縣都市計畫區法定騎樓設置標準","last_checked_at":"2026-10-06T17:31:50+08:00","last_success_at":"2026-10-06T17:31:50+08:00","verification_status":"fetched","content_hash":"6470ddb79ef26003156773c19c1e9dfc15810191d0ebf947ec83dd69a4097c45","history":[{"observed_at":"2026-10-06T17:31:50+08:00","content_hash":"6470ddb79ef26003156773c19c1e9dfc15810191d0ebf947ec83dd69a4097c45","change_kind":"initial","revision_date":"2016-02-22"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"一、屏東縣政府（以下簡稱本府）為改善都市景觀，辦理屏東縣（以下簡\n稱本縣）都市設計審議與研究工作，強化地區特色，提昇都市生活環\n境品質，特設屏東縣都市設計審議委員會（以下簡稱本會），並訂定\n本要點。\n二、本會之任務為審議與研究本縣都市設計有關之建築物設計、開放空間\n設計、交通系統設計、廣告招牌及街道家具設計、植栽及都市景觀設\n計、公共工程規劃設計及其他都市設計相關事項。\n三、本會之審議範圍如下：\n（一）本縣都市計畫說明書中載明須經本會審查之地區。\n（二）本縣都市計畫委員會規定必須經本會審查之地區。\n（三）本縣重大公共工程、公共建築依規定須經本會審議者。\n（四）依其他法令規定須經本會審議者。\n前項審議範圍內之審議作業規定如附件。\n四、本會置委員十九人，其中一人為主任委員，由縣長兼任；一人為副主\n任委員，由秘書長兼任；其餘委員由本府就下列人員聘（派）兼之：\n（一）主管業務機關首長或單位主管。\n（二）有關業務機關首長或單位主管或代表。\n（三）具有專門學術經驗之學者或專家。\n（四）本縣各相關業務之公會代表、熱心公益人士。\n依前項第一款及第二款聘（派）之委員，人數合計不得超過委員總額二\n分之一。\n第一項第四款所聘之委員應有二人以上。\n第一項委員任一性別比例不得少於委員總數三分之一。\n五、本會委員任期一年，期滿得續聘（派）之。但依第四點第一項第三款或\n第四款所聘委員，續聘以三次為限。\n本會委員於任期內職務異動或出缺時，應補聘（派），補聘（派）委員\n任期至原任期屆滿之日為止。\n依第四點第一項第三款及第四款所聘之委員，每次改聘不得超過該等委\n員人數總額二分之一。\n六、本會置執行秘書一人，由都市計畫科科長兼任，承主任委員之命，處理\n日常會務。\n置幹事六至十人，由主任委員就有關人員，核派兼之。\n本會對外行文，以本府名義行之。\n七、本會開會時間視業務需要不定期召開，開會時，由主任委員召集並為主\n席，主任委員因故不能出席時，由副主任委員代行主席職務。主任委員\n與副主任委員因故皆無法出席時，由出席委員互推一人代行主席職務。\n八、本會開會，各委員應親自出席。但依第四點第一項第一款及第二款聘(派)\n之委員未能親自出席者，得指派同一機關人員代表出席；並列入出席委\n員人數，參與會議發言及表決。\n九、本會得視實際案情需要或本府業務需要，由部分委員組成專案小組先行\n審議後，報本會決議。\n十、本會及專案小組應有二分之一以上委員出席始得開會；出席委員過半數\n之同意始得決議；可否同數時，由主席裁決。\n十一、本會審議個案或規範時，與各該案件有利害關係之委員應自行迴避。\n十二、本會兼職人員均為無給職。但依第四點第一項第三款及第四款所聘委\n員得依相關規定支給出席費。\n十三、本會所需經費依照預算程序及相關法令規定辦理。\n十四、為審議都市設計案，得酌收審查費，為透列預算辦理。\n前項審議費用之標準由本府另訂之。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000725","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"修正日期":"民國 115 年 03 月 09 日","公發布日":"民國 94 年 07 月 08 日","法規名稱":"屏東縣都市設計審議委員會設置要點","法規體系":"城鄉發展處","發文字號":"屏府城都字第1150063322號函"},"promulgation_date":"2005-07-08","revision_date":"2026-03-09","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000725","status":"unknown","title":"屏東縣都市設計審議委員會設置要點","last_checked_at":"2026-10-06T17:32:04+08:00","last_success_at":"2026-10-06T17:32:04+08:00","verification_status":"fetched","content_hash":"1eb11db349baeb5a0d429bde7862a0c0f0f1e0222c186a44b727824de23e4150","history":[{"observed_at":"2026-10-06T17:32:04+08:00","content_hash":"1eb11db349baeb5a0d429bde7862a0c0f0f1e0222c186a44b727824de23e4150","change_kind":"initial","revision_date":"2026-03-09"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"屏東縣都市設計審議許可案件變更設計作業要點（附件1、2）.pdf","url":"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=1271&id=GL000596&type=LAW"}],"authority":"屏東縣政府","category":"建築管理相關","content":"一、屏東縣政府為辦理都市設計審議許可案件變更設計審議並簡化其流程\n，特訂定本要點。\n二、經本縣都市設計審議通過之案件，如有變更設計內容時，應再提送審\n議會依原申請程序辦理。但符合下列情形者，不在此限：\n（一）建築量體：\n1.建築基地面積、總樓地板面積增減小於百分之十者。\n2.樓層數未增加，高度增減小於百分之五者。\n（二）停車空間：\n1.停車數量增減小於百分之十者。\n（三）綠化設施與植栽：\n1.綠覆率增減小於百分之十者。\n2.綠化設施之植栽種類變動小於百分之十者。\n3.綠化設施之植栽數量增減小於百分之十者。\n（四）建築立面：\n1.建築色彩、造型或材質變更面積小於原核准面積百分之十者\n，並應以各向建築立面正面投影面積計算分別檢討之。\n（五）建築物內部空間：\n1.建築物用途同組內互換。\n2.建築物用途變更，變更樓地板面積未超過總樓地板面積百分\n之十者。\n三、變更設計內容符合前點但書情形，如違反原委員會議重大決議事項、\n與本縣都市設計審議規範相關規定不符、或與各計畫區都市設計準則\n相關規定不符者，仍應再提送審議會依原申請程序辦理。\n四、變更設計案件需檢附變更設計報告書、本要點查核表(附件一)及該次\n變更有無違反原審議會決議之對照表(附件二)，逐條檢討，並由建築\n師簽證送本府同意備查。\n五、因本要點執行，所生爭議或疑義時，本府得提請本縣都市設計審議委\n員會研議。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000596","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 108 年 04 月 19 日","圖表附件":"屏東縣都市設計審議許可案件變更設計作業要點（附件1、2）.pdf","法規名稱":"屏東縣都市設計審議許可案件變更設計作業要點","法規體系":"城鄉發展處","發文字號":"屏府城都字第10811037800號 函"},"promulgation_date":"2019-04-19","revision_date":"2019-04-19","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000596","status":"unknown","title":"屏東縣都市設計審議許可案件變更設計作業要點","last_checked_at":"2026-10-06T17:31:57+08:00","last_success_at":"2026-10-06T17:31:57+08:00","verification_status":"fetched","content_hash":"963bcf87ff25b4350479eb5df178030f5a4fbb2f5f9422e5c668e83373817eaa","history":[{"observed_at":"2026-10-06T17:31:57+08:00","content_hash":"963bcf87ff25b4350479eb5df178030f5a4fbb2f5f9422e5c668e83373817eaa","change_kind":"initial","revision_date":"2019-04-19"}],"version_count":1,"attachment_hashes":{"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=1271&id=GL000596&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"一、為執行本縣領有使用執照建築基地（以下簡稱建築基地）範圍內部分土地單獨或\n合併鄰地申請建築，特定本原則。\n二、建築基地法定空地應依建築基地法定空地分割辦法（以下簡稱本辦法）完成地籍\n分割後，始可單獨或合併鄰地申請建築。但因都市計畫公共設施用地辦理逕為分\n割或於中華民國七十五年二月三日以前已完成地籍分割、整界，且賸餘建築基地\n符合本辦法第三條第三款及第四款規定者，不在此限。\n建築基地經市地重劃或區段徵收後，僅就建築物所坐落之重劃土地或原位置保留\n戶之土地進行建築管理，原使用執照範圍之其餘土地不予管制。\n三、符合前點免辦理法定空地分割證明書之建築基地，單獨或合併鄰地申請建築時，\n在原使用執照範圍內，其建築物各層至天際垂直區劃為同一權利主體，使用互不\n影響，且與地籍分割線一致者，其部分地號土地建築物拆除新建、增建、改建、\n修建時，得免經原建築基地其他地號土地及建築物所有權人同意。\n前項如涉及合併鄰地並以私設通路或基地內通路連接建築線者，仍應取得該通路\n使用同意書。\n四、建築基地部分地號土地單獨或合併鄰地申請建築時，主管建築機關應於該建築物\n拆除新建前，套繪地籍圖列管使用範圍，並應於新核發建造執照載明原領使用執\n照號碼及地號範圍。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000776","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 108 年 11 月 28 日","法規名稱":"屏東縣領有使用執照建築基地範圍內部分土地申請建築處理原則","法規體系":"城鄉發展處","發文字號":"屏府城管字第10884659900號函"},"promulgation_date":"2019-11-28","revision_date":"2019-11-28","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000776","status":"unknown","title":"屏東縣領有使用執照建築基地範圍內部分土地申請建築處理原則","last_checked_at":"2026-10-06T17:31:57+08:00","last_success_at":"2026-10-06T17:31:57+08:00","verification_status":"fetched","content_hash":"4dd76929ada7f1ae84af084bb35385a0f2c23db230c9772225ec202a5befc7da","history":[{"observed_at":"2026-10-06T17:31:57+08:00","content_hash":"4dd76929ada7f1ae84af084bb35385a0f2c23db230c9772225ec202a5befc7da","change_kind":"initial","revision_date":"2019-11-28"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"第 1 條\n屏東縣政府（以下簡稱本府）為處理高氯離子混凝土建築物，以維公共安\n全，特訂定本辦法。\n第 2 條\n本辦法所稱高氯離子混凝土建築物，係指建築物之混凝土，經本府認可之\n專業鑑定機關（構）、學校或團體辦理鑑定，氯離子含量超過設計環境條\n件下之國家標準值，認定必須補強、防蝕處理或拆除重建者。\n第 3 條\n本辦法適用之建築物，以中華民國八十四年六月三十日前，已依建築法規\n定申報施工勘驗之私有合法建築物為限。\n第 4 條\n建築物所有權人，在發現建築物有白華、析晶、鋼筋腐蝕或混凝土剝落等\n現象時，應自行委託本府認可之專業鑑定機關（構）、學校或團體鑑定。\n經鑑定屬高氯離子混凝土建築物者，應在三十日內備文檢附鑑定報告文件\n，向本府報備處理。\n第 5 條\n專業鑑定機關（構）、學校或團體受理鑑定業務，應就建築物結構安全及\n建築物之氯離子含量提出明確鑑定報告，並建議具體處理措施。\n第 6 條\n高氯離子混凝土建築物經鑑定須補強或防蝕處理者，本府應責成建築物所\n有權人，在六個月內，依鑑定報告處理措施，完成補強或防蝕工程。\n第 7 條\n經鑑定須拆除之建築物，本府應依照建築法規定通知所有權人停止使用，\n並限期拆除，必要時並得強制拆除，代拆除費用由所有權人負責。\n第 8 條\n經鑑定為高氯離子混凝土建築物，原相關監造人或承造人應負之責任，本\n府應依法移送相關懲戒委員會審議；其涉及刑事責任者，並移送司法機關\n偵辦。\n第 9 條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:FL052538","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 97 年 11 月 27 日","法規名稱":"屏東縣高氯離子混凝土建築物善後處理辦法","法規體系":"城鄉發展處","發文字號":"屏府行法字第0970244286號"},"promulgation_date":"2008-11-27","revision_date":"2008-11-27","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=FL052538","status":"unknown","title":"屏東縣高氯離子混凝土建築物善後處理辦法","last_checked_at":"2026-10-06T17:31:49+08:00","last_success_at":"2026-10-06T17:31:49+08:00","verification_status":"fetched","content_hash":"10a7cbeb4eb41fad8f0b0ccb3d3af8167cb22776bb22dd09ea93d566836bacae","history":[{"observed_at":"2026-10-06T17:31:49+08:00","content_hash":"10a7cbeb4eb41fad8f0b0ccb3d3af8167cb22776bb22dd09ea93d566836bacae","change_kind":"initial","revision_date":"2008-11-27"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"第 1 條\n本辦法依國民住宅條例第十八條之一第二項規定訂定之。\n第 2 條\n本辦法適用對象為屏東縣轄內由政府直接興建之國民住宅社區（以下簡稱\n國宅社區）\n第 3 條\n管理維護基金提撥金額為：該國宅社區國民住宅售價百分之二．五提撥款\n及其存款孳息。扣除該國宅社區已實際支出，提出申請年度結束之結餘款\n。\n第 4 條\n國宅社區在構造上或使用上可區分為數部分之建築物及基地，並已分別成\n立管理委員會者，依其戶數比例分帳提撥。\n第 5 條\n國宅社區申請提撥國民住宅管理維護基金應具備下列要件：\n一、依公寓大廈管理條例規定成立管理委員會，並向主管機關報備取得證\n明文件。\n二、以管理委員會名義會同主任委員、財務委員及監察委員完成開設金融\n機構帳戶。\n三、以管理委員會或管理負責人名義，出具概括承受前國宅社區管理委員\n會權利義務之證明文件。\n第 6 條\n國宅社區完成前條所規定要件後，應檢附申請書、報備證明、專戶存摺影\n本、概括承受同意書等相關文件，向本府申請核撥該國宅社區管理維護基\n金。\n第 7 條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:FL052536","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 95 年 07 月 13 日","廢止日期":"民國 104 年 12 月 15 日","法規名稱":"廢 屏東縣國民住宅管理維護基金提撥社區公共基金辦法","法規體系":"城鄉發展處","發文字號":"屏府行法字第10479842901號 令"},"promulgation_date":"2006-07-13","revision_date":"2006-07-13","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=FL052536","status":"repealed","title":"廢 屏東縣國民住宅管理維護基金提撥社區公共基金辦法","last_checked_at":"2026-10-06T17:32:08+08:00","last_success_at":"2026-10-06T17:32:08+08:00","verification_status":"fetched","content_hash":"09b5aead5538b0a589d77389972477c41a3c3dc87ccea97c989b5584af2bc3e1","history":[{"observed_at":"2026-10-06T17:32:08+08:00","content_hash":"09b5aead5538b0a589d77389972477c41a3c3dc87ccea97c989b5584af2bc3e1","change_kind":"initial","revision_date":"2006-07-13"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"第 1 條\n屏東縣政府（以下簡稱本府）為加速工業區開發，健全工業區管理，特設\n工業區開發管理基金（以下簡稱本基金）並依據促進產業升級條例（以下\n簡稱本條例）第五十五條規定訂定本辦法。\n第 2 條\n本基金之收入、保管及運用，除法令另有規定外，依本辦法之規定辦理。\n第 3 條\n本基金以本府為主管機關。\n第 4 條\n本基金之來源如下：\n一、出售工業區土地或建築物時，依本條例第五十五條第一項規定由承購\n人繳付之款項。\n二、出售工業區土地或建築物，超過成本之收入。\n三、工業區內各使用人繳納之權利金、管理費、使用費、維護費或其他服\n務費。\n四、依本條例第五十二條所繳付之管理費。\n五、工業主管機關辦理工業區土地及公共或建築物強制收買或委託公民營\n事業代辦強制收買後，另行出售時，超過成本之收入。\n六、工業區開發完成後之結餘款。\n七、工業區開發之投資或參加投資於工業區相關服務性事業之投資收益。\n八、工業區內使用人繳納之租金。\n九、工業區開發貸款利息收入。\n十、本基金之孳息收入。\n十一、依本條例第三十一條、第三十二條及第五十三條所繳付之回饋金。\n十二、其他有關之收入。\n第 5 條\n本基金之用途如下：\n一、參加工業區開發之投資或融貸資金供工業區之開發。\n二、參加投資於工業區相關服務性之事業。\n三、配合政策需要，投資開發工業區之公民營事業。\n四、工業區內供公共使用之土地及公共建築物與設施之管理維護費。\n五、本條例第四十三條第二項規定之補償費及辦理本條例第六十一條第一\n項第一款事宜所需之資金。\n六、工業區管理機構營運經費。\n七、工業區相關研究規劃、宣導經費。\n八、工業區土地或建築物，長期未能售出，致售價超過附近使用性質相同\n者，其所增加開發成本利息之補貼。\n九、有關工業發展或工業區設置之建設經費。\n十、改善工業區內及受影響鄰近土地環境保護之經費。\n十一、改善工業區連外公共設施之經費。\n十二、其他直接使用於工業區之支出。\n第 6 條\n本基金在金融機構設立專戶存儲，其主辦單位為本府建設局。\n第 7 條\n本基金預算之編製及執行，會計事務之處理程序及決算之編報，依預算法\n、會計法、決算法、審計法及相關法令辦理。\n第 8 條\n本基金結束時，應予結算，其餘存權益應循預算程序解繳縣庫。\n第 9 條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:FL041019","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 89 年 08 月 31 日","廢止日期":"民國 100 年 09 月 21 日","法規名稱":"廢 屏東縣工業區開發管理基金收支保管及運用辦法","法規體系":"城鄉發展處","發文字號":"屏府行法字第1000248296號"},"promulgation_date":"2000-08-31","revision_date":"2000-08-31","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=FL041019","status":"repealed","title":"廢 屏東縣工業區開發管理基金收支保管及運用辦法","last_checked_at":"2026-10-06T17:32:07+08:00","last_success_at":"2026-10-06T17:32:07+08:00","verification_status":"fetched","content_hash":"9ea2969c1f060d746fafdc7de8d8f5b7e4e9bf93c012fee19519277d59014711","history":[{"observed_at":"2026-10-06T17:32:07+08:00","content_hash":"9ea2969c1f060d746fafdc7de8d8f5b7e4e9bf93c012fee19519277d59014711","change_kind":"initial","revision_date":"2000-08-31"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"第 1 條\n本細則依廣告物管理辦法第二十三條之規定訂定之。\n第 2 條\n本辦法第三條第二項所稱工程建築係指左列情形而言。\n一、廣告物本身利用鋨架支著，超越架設廣告之建築物高寬逾一公尺或於\n廣告上裝置電氣及其他涉及安全，須由技術人員勘定者。\n二、申請設置之廣告，因地點或廣告本身依承辦業務人員直覺觀察，認有\n安全顧慮，以先由技術人員勘查為宜者。\n第 3 條\n申請設置前條廣告時，應先將設置地點報請警察局勘定，必要時得通知鐵\n公路主管機關會同辦理，廣告物為雜項工作物者，經申領廣告許可證後，\n應依規定向主管建築機關申領雜項執照方可施工。\n前項廣告圖案文字應於核發廣告許可證後繪製之。\n第 4 條\n本縣左列地區處所不准樹立或張貼廣告。\n一、國立墾丁公園、縣立中山、中正公園內部及四重溪、鵝鑾鼻、佳樂水\n、小琉球、三地門等風景區附近不宜設置廣告之處所。\n二、鄉鎮市區內之人行道及橋樑、高岡、省縣公路兩側五公尺以內地區或\n其他妨礙交通之處所。\n三、機關、學校四週十公尺以內及古蹟寺廟之內部或其他妨礙市客觀瞻之\n處所。\n四、鋨路及國、省、縣公路沿線路權以內地區或路權以外妨礙駕駛人視線\n與路上所設標誌地區高速公路（含交流道、引道及至機場之速絡道）\n兩旁視線所及地區。\n五、鐵路沿線鋨路局經營之範圍內，未附鐵路局行車安全證明或鐵路沿線\n範圍外公私有士地或建築物上有廣告物管理辦法第七條第二款、第三\n款之處所。\n第 5 條\n本縣廣告設置依左列規定:\n一、樹立廣告與招牌廣告，設置在鄉鎮市沿街建築上，高度不得超過街道\n寬度一倍半（包括建築物），廣告物本身高自廣告物與招牌柱基不得\n超過四公尺，寬度以建築物寬度為限。\n二、遊動廣告，如使用車輛、大型車，廣告物本身高度離地不得超過四公\n尺，小型車或三輪汽車、離地不得超過二．五公尺，車尾外端不得懸\n掛商業性廣告牌。\n三、招牌廣告，側懸突出建築物寬逾五十公分以上者，應經申請許可後樹\n立或宣傳，正面型招牌廣告，其兩端或一端供作其他廠商宣傳者，應\n視同樹立廣告辦理。\n四、張貼廣告，比照前二款及第九條、第十條規定辦理。\n前項廣告物違反規定或電桿上書寫廣告妨礙市容者得按廣告標語行為或貼\n塗劃刻為，依有關法令處罰，並責令恢復原狀。\n第 6 條\n樹立廣告，應於核發許可證後三個月內樹立，逾期另行申請，申請人並應\n於樹立前持向當地警察分駐（派出）所登記，並在廣告物內加註許可證之\n日期、字號。\n第 7 條\n張貼廣告，面積以一平方公尺為限，並應於廣告欄或核准之自設廣告招貼\n欄內為之。\n第 8 條\n電影戲院門前或其他地點樹立之電影戲劇廣告，其內容以查驗核准之電影\n戲劇海報為限。\n第 9 條\n各機關、團體、學校得視事實需要，在本機關或所屬建築物附近十公尺以\n內地區設置專用廣告標語欄。但不得妨礙交通及市容觀瞻。\n第 10 條\n各鄉鎮市公所應於轄賽適當地點設置公共廣告貼欄，每村里以二處為原則\n，市鎮地區得酌情增加。\n第 11 條\n各鄉鎮市公所對轄內利用公地樹立之廣告，得按其使用價值酌情收取租金\n，其金額由該鄰鎮市公所訂定。\n第 12 條\n申請宣傳廣告應繳送（閱）左列文件及費用。\n一、樹立廣告:\n（一）廣告宣傳申請書。\n（一）廣告內容說明書（說明廣告之面積質料及文字圖畫）。\n（二）樹立廣告位置。\n（三）土地（建築物）所有權人同意書。\n（四）保證書（負安全保養及保持整潔責任）。\n（五）許可證費新臺幣一千元、印花費新臺幣十二元。\n（六）其他有關證明文件。\n二、遊動廣告:\n（一）宣傳廣告申請書。\n（二）許可證費新臺幣五百元、印花費新臺幣十二元。\n（三）其他有關證明文件。\n三、側懸突出建築物寬逾五十公分招牌廣告。\n（一）宣傳廣告申請書。\n（二）廣告內容說明書。\n（三）保證書（負安全保養及保持整潔責任）。\n（四）許可證費新臺幣一千元、印花費新臺幣十二元。\n（五）其他有關證明文件。\n上項許可證費補發證者折半收費。\n第 13 條\n有關廣告之許可證費收入，悉數解繳縣庫，所需管理費用須編列預算依法\n開支。\n第 14 條\n商戶懸掛招牌廣告應遵守左列規定：\n一、屏東、潮州、東港、恒春、內埔等市鎮鄉（偏遠村落除外）懸掛招牌\n廣告之下端應離地面四公尺以上，其他鄉村離地面二公尺以上。\n二、招牌廣告，因建築物之限制，懸掛高度未達前款標準時一律採正面型\n，其突出建築物厚度以二十公分為限。\n前項招牌廣告縱長超過一公尺，橫寬超過三公尺者應申請許可，並須於招\n牌廣告上加註許可證之日期、字號。\n第 15 條\n主辦單位得統一規定某一地區或街道招牌型式規格及懸掛方式，對市招裝\n置必須顧慮公共安全，裝釘接頭焊牢，支架足以負荷繪面載重，並不得使\n用容易著火之油類紙板或含有傑質塑膠軟布等建材，以減少災害及傷亡。\n第 16 條\n主辦單位每三個月舉行廣告業務導及普查一次，其工作動點為檢查各種廣\n告之內容，懸掛方式及取締未經許可之宣傳廣告。\n第 17 條\n各級警察機關，對於轄內各廣告有調查指導之責，除對已經核准樹立之廣\n告指導當事人照核准內容、地點繪製外，發現未經許可或內容違反第二條\n規定者，即依法取締或層報吊銷許可證。\n第 18 條\n廣告承製商於承包廣告時，對於未經許可之廣告，應勸導廣告當事人辦理\n許可，在未經許可前，不得代為樹立。\n第 19 條\n已經核准樹立之廣告，因環境變遷或有其他必須拆除之原因，主辦單位得\n飭當事人於限期內拆除或遷移。\n第 20 條\n主辦單位因拆除縣內未經許可或內容不合規定之廣告，得洽本縣違章建築\n拆除隊協助，其有關必須之經費在廣告業務管理費項下支。\n第 21 條\n違反本細則規定者，除得吊銷許可證外，依道路交通管理處罰條例或行政\n執行法處罰，必要時，並將樹立之廣告物依行政執行法處分之。\n第 22 條\n本細則自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:FL052535","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 61 年 04 月 06 日","廢止日期":"民國 104 年 09 月 02 日","法規名稱":"廢 屏東縣廣告物管理細則","法規體系":"城鄉發展處","發文字號":"屏府行法字第10427845100號 令"},"promulgation_date":"1972-04-06","revision_date":"1972-04-06","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=FL052535","status":"repealed","title":"廢 屏東縣廣告物管理細則","last_checked_at":"2026-10-06T17:32:08+08:00","last_success_at":"2026-10-06T17:32:08+08:00","verification_status":"fetched","content_hash":"e49b4552a168d3bf91e64f9139360fd950bb62d73d5140ffb7fdadfc1cbd8bf8","history":[{"observed_at":"2026-10-06T17:32:08+08:00","content_hash":"e49b4552a168d3bf91e64f9139360fd950bb62d73d5140ffb7fdadfc1cbd8bf8","change_kind":"initial","revision_date":"1972-04-06"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"第 1 條\n屏東縣政府（以下簡稱本府）為辦理本府所屬各工程主辦單位之施工材料\n物理、化學有關性能試驗、分析、鑑定等事項收費有所依據，特制定本自\n治條例。\n第 2 條\n本府各工程主辦單位除工程契約書另有規定外，應由監工人員負責取樣送\n驗，如因本府試驗設備限制無法試（檢）驗者，得另行委託學術單位或經\n中華民國實驗室認證體系（CNLA）認證合格之民間試驗業者檢驗。\n第 3 條\n本府辦理各項試（檢）驗項目及收費如下：\n一、混凝土材料\n（一）混凝土抗壓每個新臺幣二百十元。\n（二）壓力鎚試驗新臺幣六百元。\n（三）試體切割抗壓新臺幣三百元。\n（四）水泥塊抗壓新臺幣一百二十元。\n（五）PC  鑽心（含切割蓋平）新臺幣一千四百元。\n二、級配材料\n（一）比重、吸水率新臺幣一千五百元。\n（二）篩分析新臺幣一千元。\n（四）單位重新臺幣一千元。\n三、瀝青材料\n（一）瀝青混合料夯壓新臺幣一千元。\n（二）壓實度每組三個新臺幣二千四百元。\n（三）鑽心新臺幣五百元。\n（四）試體測厚度新臺幣三百元。\n（五）試體測密度新臺幣五百元。\n（六）AC  路面平坦儀測試新臺幣三千元。\n（七）瀝青含油量一新臺幣千五元。\n（八）瀝青篩分析新臺幣二千元。\n（九）單位重每組三個新臺幣二千四百元。\n（十）馬歇爾穩定值、流定值新臺幣三千元。\n四、土壤材料\n（一）工地密度每組三個新臺幣二千四百元。\n（二）夯實試驗新臺幣三千元。\n（三）級配篩分析新臺幣一千元。\n五、氯離子含量檢測\n（一）水溶液新臺幣七百元。\n（二）新拌混凝土新臺幣一千五百元。\n第 4 條\n本自治條例自公布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:FL041208","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 90 年 08 月 27 日","廢止日期":"民國 102 年 06 月 26 日","法規名稱":"廢 屏東縣材料試驗收費自治條例","法規體系":"工務處","發文字號":"屏府行法字第10219188700號 令"},"promulgation_date":"2001-08-27","revision_date":"2001-08-27","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=FL041208","status":"repealed","title":"廢 屏東縣材料試驗收費自治條例","last_checked_at":"2026-10-06T17:32:12+08:00","last_success_at":"2026-10-06T17:32:12+08:00","verification_status":"fetched","content_hash":"502ad2d53bb8d3e50992934199e29976841326633c86c54d898e847d2fa71367","history":[{"observed_at":"2026-10-06T17:32:12+08:00","content_hash":"502ad2d53bb8d3e50992934199e29976841326633c86c54d898e847d2fa71367","change_kind":"initial","revision_date":"2001-08-27"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"屏東縣政府","category":"建築管理相關","content":"一、屏東縣政府（以下簡稱本府）為執行營造業法(以下簡稱本法)第十七\n條及第三十四條第一項規定，實施營造業抽查及查核其專任工程人員\n受聘情形，特訂定本要點。\n二、本要點之執行範圍為於本縣辦理營造業登記或承攬本縣土木、建築工\n程之營造業。\n三、本府得於抽查時要求營造業檢具所承攬興建中工程之施工計畫書、開\n工或竣工報告、工程查驗文件或申報勘驗文件以供查核，並得請專任\n工程人員到場協助說明。\n四、營造業公司名稱、營業地址、組織性質、資本額、負責人姓名或專任\n工程人員姓名等登記事項有變更時，應自事實發生之日起二個月內檢\n附相關證明文件向本府申請變更登記，並換領營造業登記證書。\n前項所稱相關證明文件，於辦理變更專任工程人員事項時應檢附專任\n工程人員勞健保投保資料、綜合所得稅結算申報書、前一工作之離職\n證明書及公會會員證以供核對。\n本府得於抽查時要求營造業出具相關文件以供查核是否符合前二項規\n定；違反者，依本法第五十七條規定辦理。\n五、本府執行抽查時，營造業應檢具公司負責人及其專任工程人員（含逐\n案簽章之建築師或技師）之身分證影本、承攬工程手冊、營造業登記\n證書、專任工程人員資格證明書及受聘同意書、最近之公司登記或商\n業登記證明文件、營利事業所得結算申報書、最近一期營業稅銷售額\n及稅額申報書、勞健保投保資料及薪資所得資料，以供抽查人員核對。\n六、抽查作業由本府派員不定期至營造業營業登記地址或所承攬工程現場\n查核，營造業有下列情形之一者，列為優先抽查：\n（一）經各機關、團體及人民移送、函告、檢舉等有違法情事。\n（二）前次未配合抽查及未依規定提供專任工程人員（含逐案簽章之建築\n師或技師）相關文件。\n（三）至本府辦理營造業各項變更登記業務，有違反本法規定。\n七、營造業拒絕、妨礙或規避本府抽查者，依本法第五十五條第一項第三\n款規定辦理。\n八、營造業經抽查後，如不合規定時，由本府列舉事由通知限期補正，營\n造業應於接獲通知之次日起二個月內，依通知補正事項辦理補正。逾\n期未補正者，依本法第五十六條第一項規定辦理。\n九、營造業及其專任工程人員未依第五點規定辦理者，本府得函請財政部\n、勞工保險局、中央健保局提供薪資所得稅籍資料、勞保及健保投保\n登記資料。\n營造業專任工程人員有違反本法第三十四條規定者，依本法第六十一\n條規定辦理。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000317","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 104 年 01 月 23 日","法規名稱":"營造業抽查作業要點","法規體系":"工務處","發文字號":"屏府工營字第10402284900號 函"},"promulgation_date":"2015-01-23","revision_date":"2015-01-23","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000317","status":"unknown","title":"營造業抽查作業要點","last_checked_at":"2026-10-06T17:32:11+08:00","last_success_at":"2026-10-06T17:32:11+08:00","verification_status":"fetched","content_hash":"64761a8e5ce5e31a89a8f7adc45d3fd40ea6ad00937c97321252588b30f8b54c","history":[{"observed_at":"2026-10-06T17:32:11+08:00","content_hash":"64761a8e5ce5e31a89a8f7adc45d3fd40ea6ad00937c97321252588b30f8b54c","change_kind":"initial","revision_date":"2015-01-23"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"1101109_琉球風景特定區計畫遊憩分區整體開發計畫審查作業要點_附表1至4.pdf","url":"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=1452&id=GL000726&type=LAW"}],"authority":"屏東縣政府","category":"建築管理相關","content":"一、屏東縣政府（以下簡稱本府）為辦理琉球風景特定區計畫土地使用分\n區管制要點（以下簡稱本計畫土管要點）第七點規定之遊憩分區整體\n開發計畫審查，特訂定本作業要點。\n二、本要點之執行單位為本府城鄉發展處。\n三、為簡化審議流程及縮短作業時程，有關整體開發計畫審查與其所涉都\n市設計審議併同進行。\n前項申請基地如有分期分區開發者，應至少提出第一期開發內容之都\n市設計送審。\n四、申請整體開發計畫審查（以下簡稱申請案件）之申請人應填具申請書\n（詳附表一），並檢附下列文件向主辦機關提出：\n(一)申請人基本資料：\n1.以個人名義申請者：身分證明文件正反面影本。\n2.以法人團體名義申請者：法人團體登記證明文件影本及其負責\n人（或法定代表人）身分證明文件正反面影本。\n(二)土地登記謄本（應以最近一個月內核發者為憑）。\n(三)地籍圖謄本（應以最近一個月內核發者為憑，並著色標明申請開\n發範圍，其比例尺以能明確顯示申請開發範圍內所有土地之地號\n為原則）。\n(四)土地使用權利或同意之相關證明文件（申請開發土地屬申請人所\n有部分得免附）。\n(五)基地周圍現況實測地形圖：\n1.標示申請開發範圍基地境界線鄰近8公尺範圍內現有相關地形\n、標高、地物及設施，並套繪地籍線及都市計畫圖。\n2.標示間隔為五十公分之等高線。\n3.比例尺不得小於千分之一。\n4.其他依國土測繪法及其相關規定應標示事項，並由專業技師簽\n證(檢附合格執業證明)。\n(六)第一、二級環境敏感地區查詢結果。\n(七)整體開發計畫暨都市設計審議圖說（以下簡稱計畫圖說）：依審\n議書件查核表（詳附表二）表列事項載明相關計畫內容。\n(八)基地建築線指示(定)圖。\n(九)其他主辦機關指定之文件。\n五、申請案件有下列情形者，申請人應於檢送申請資料時，併同檢附之：\n(一)申請基地內既有但無合法建照之建築及設施物，應檢附相關技師\n簽證結構安全無虞證明書。但該等建築及設施物於整體開發計畫\n中將予拆除者，得免附。\n(二)依本計畫土管要點規定須捐贈土地登記為鄉有或繳納代金者，應\n取得屏東縣琉球鄉公所之同意受贈文件。\n(三)申請案件屬依法應辦理環境影響評估、實施水土保持之處理與維\n護、或其他需先經目的事業主管機關審查者，應檢附各該管主管\n機關審查通過之文件；如無須辦理者，應檢附各該管主管機關之\n認定文件。\n六、主辦機關受理申請案件後，由屏東縣都市設計審議委員會（以下簡稱\n委員會）組成專案小組審議，再提請委員會審定。\n申請案件符合下列情形之一者，得由專案小組逕予審定，再行提委員\n會備查：\n(一)經各管主管機關認可得免依法辦理環境影響評估、實施水土保持\n之處理與維護、或實施出流管制。\n(二)申請開發基地條件及開發內容無爭議性、或可能產生重大之環境\n衝擊。\n七、申請案件經委員會審定通過後，申請人應依審查結論修正計畫圖說，\n報請本府同意核定及副知有關機關。\n經核定之案件涉及須捐贈土地登記為鄉有或繳納代金者，應完成捐贈\n登記或繳納後，始得核發建造執照。\n八、經核定之計畫圖說於興建前、興建中或興建完成營運中，需辦理計畫\n內容變更者，申請人應依原申請程序，重新檢送申請資料提請委員會\n決議。\n申請變更案件之變更事項符合下列情形之一者，申請人得檢附變更內\n容查核表（詳附表三-1）及歷次委員會審決檢討表（詳附表三-2），\n由本府逕為同意備查：\n(一)變更計畫案名，但未影響原核定之整體開發計畫性質、實質內容。\n(二)變更設施名稱，但未涉及原核定之整體開發計畫性質、設施內容\n、配置位置、及開發強度等異動。\n(三)變更設計內容符合「屏東縣都市設計審議許可案件變更設計作業\n要點」第二點但書規定。\n(四)調整開發進度及次序，但不涉及原核准開發項目及內容之異動。\n九、依本要點規定執行所生之爭議或疑義，視其性質得提請委員會或本縣\n都市計畫委員會研議。\n十、本要點因都市計畫變更有調整修訂時，主辦機關應配合修正本要點相\n關事項。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000726","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 110 年 11 月 09 日","圖表附件":"1101109_琉球風景特定區計畫遊憩分區整體開發計畫審查作業要點_附表1至4.pdf","法規名稱":"琉球風景特定區計畫遊憩分區整體開發計畫審查作業要點","法規體系":"城鄉發展處","發文字號":"屏府城都字第11052264600號函"},"promulgation_date":"2021-11-09","revision_date":"2021-11-09","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000726","status":"unknown","title":"琉球風景特定區計畫遊憩分區整體開發計畫審查作業要點","last_checked_at":"2026-10-06T17:31:58+08:00","last_success_at":"2026-10-06T17:31:58+08:00","verification_status":"fetched","content_hash":"44cad655a5c6f789254c518734af169834f0e6578b685b3a9d8d923f67368e50","history":[{"observed_at":"2026-10-06T17:31:58+08:00","content_hash":"44cad655a5c6f789254c518734af169834f0e6578b685b3a9d8d923f67368e50","change_kind":"initial","revision_date":"2021-11-09"}],"version_count":1,"attachment_hashes":{"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=1452&id=GL000726&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"20180705屏東縣建築物附建防空避難設備或停車空間繳納代金及管理使用辦法造價係數.pdf","url":"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=1150&id=GL000549&type=LAW"}],"authority":"屏東縣政府","category":"建築管理相關","content":"一、本縣防空避難設備造價係數為0.5。\n二、本縣停車空間，商業區、遊憩區造價係數為1.2，其他為1。\n三、本辦法造價係數得視實際情形另行檢討調整。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"pingtung:GL000549","jurisdiction":"屏東縣","metadata_only":false,"official_fields":{"公發布日":"民國 107 年 07 月 05 日","圖表附件":"20180705屏東縣建築物附建防空避難設備或停車空間繳納代金及管理使用辦法造價係數.pdf","法規名稱":"訂定「屏東縣建築物附建防空避難設備或停車空間繳納代金及管理使用辦法」第5條第2項之造價係數。","法規體系":"城鄉發展處","發文字號":"屏府城使字第10723167600號"},"promulgation_date":"2018-07-05","revision_date":"2018-07-05","source_id":"pingtung","source_updated_at":null,"source_url":"https://ptlaw.pthg.gov.tw/LawContent.aspx?id=GL000549","status":"unknown","title":"訂定「屏東縣建築物附建防空避難設備或停車空間繳納代金及管理使用辦法」第5條第2項之造價係數。","last_checked_at":"2026-10-06T17:32:07+08:00","last_success_at":"2026-10-06T17:32:07+08:00","verification_status":"fetched","content_hash":"852c747325504a80933866efdb6ed20fe14fda9ba3ede54325fa8603622fa500","history":[{"observed_at":"2026-10-06T17:32:07+08:00","content_hash":"852c747325504a80933866efdb6ed20fe14fda9ba3ede54325fa8603622fa500","change_kind":"initial","revision_date":"2018-07-05"}],"version_count":1,"attachment_hashes":{"https://ptlaw.pthg.gov.tw/Download.ashx?FileID=1150&id=GL000549&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"彰化縣政府","category":"建築管理相關","content":"","coverage_note":"官方已標示廢止且未提供正文；保留法規目錄與來源證據。","effective_date":null,"effective_note":"","id":"changhua:GL000115","jurisdiction":"彰化縣","metadata_only":true,"official_fields":{"公發布日":"民國 90 年 05 月 28 日","廢止日期":"民國 93 年 03 月 11 日","法規名稱":"廢 彰化縣畸零地使用規則","法規體系":"建設類","發文字號":"府法制字第0930046243號"},"promulgation_date":"2001-05-28","revision_date":"2001-05-28","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=GL000115","status":"repealed","title":"廢 彰化縣畸零地使用規則","last_checked_at":"2026-10-06T17:26:44+08:00","last_success_at":"2026-10-06T17:26:44+08:00","verification_status":"reference_only","content_hash":"09f35d787fbbf58374163bb9064da7fb1e93c9c4ae75d038294ae5045c5e6fb9","history":[{"observed_at":"2026-10-06T17:26:44+08:00","content_hash":"09f35d787fbbf58374163bb9064da7fb1e93c9c4ae75d038294ae5045c5e6fb9","change_kind":"initial","revision_date":"2001-05-28"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"廢止彰化縣都市更新單元劃定標準總說明.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=3278&id=FL041418&type=LAW"},{"name":"彰化縣都市更新單元劃定標準.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=2853&id=FL041418&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"第 1 條\n彰化縣政府（以下簡稱本府）為辦理彰化縣（以下簡稱本縣）都市更新事\n業，依都市更新條例第十條及第十一條之規定，訂定本標準。\n第 2 條\n都市更新單元劃定標準，應符合下列規定之一：\n一、完整之計畫街廓者。\n二、街廓內面積在一千平方公尺以上者。\n三、街廓內臨接二條以上之計畫道路，且面積在五百平方公尺以上者。\n四、街廓內部分土地業已建築完成，確無法合併更新且無礙建築設計及市\n容觀瞻，其面積在五百平方公尺以上，並為一次更新完成者。\n都市更新單元面積雖不符合前項第二款至第四款規定，其情形特殊有實施\n都市更新必要者，得經本縣都市更新審議委員會同意另行劃定。\n第一項所稱街廓，係以基地四周面臨計畫道路為原則，如因基地鄰\n接永久性空地、公園、廣場、河川等，其鄰接部分邊界得視為街廓邊界。\n第 3 條\n經本府劃定為應實施都市更新之地區，土地及合法建築物所有權人自行劃\n定更新單元者，應以一完整之計畫街廓為原則。但因計畫街廓過大或其他\n特殊因素確難一次辦理者，得依前條第一項第二款至第四款及第二項之規\n定自行劃定更新單元，依都市更新條例第十條規定申請實施都市更新事業\n。\n第 4 條\n未經本府劃定為應實施都市更新之地區，土地及合法建築物所有權人得參\n照第二條所定標準，申請自行劃定更新單元實施都市更新事業。\n前項更新單元內建築物及地區環境狀況應符合下列各款條件之一，並於更\n新事業概要內載明。\n一、更新單元內屬非防火構造建築物之棟數比例達二分之一以上。\n二、更新單元內現有巷道彎曲狹小，寬度小於四公尺者之長度佔現有巷道\n總長度比例達二分之一以上。\n三、更新單元內各種構造建築物使用已逾下列年期之面積比例達二分之一\n以上：土磚造及木造十年，金屬建造（無披覆處理）十五年，金屬建\n造（有披覆處理）二十年，磚造二十五年，加強磚造三十年，鋼筋（\n骨）混凝土造及預鑄混凝土造三十五年。\n四、更新單元內建築物有基礎下陷、主要樑柱及牆壁等腐朽破損或變形，\n有危險之虞者之棟數比例達二分之一以上。\n五、更新單元內合法建築物地面層土地使用現況不符現行都市計畫分區使\n用之樓地板面積比例達二分之一以上。\n六、申請更新單元範圍距離現有火車站一百公尺以內毗鄰之完整街廓者。\n七、更新單元內建築物無污水處理設施之棟數比例達二分之一以上。\n八、更新單元內建築物耐震設計標準，不符建築技術規則耐震設計規定者\n之棟數比例達二分之一以上。\n九、更新單元內計畫道路未開闢者之面積比例達二分之一以上。\n十、更新單元範圍現有建蔽率大於法定建蔽率且現有容積未達法定容積之\n二分之一。有關建蔽率及容積率之計算，以合法建築物為限。\n十一、更新單元內平均居住樓地板面積低於當地居住樓地板面積平均水準\n之二分之一以下者。\n十二、位屬或鄰接內政部及本縣核定之古蹟、都市計畫劃定之保存區、本\n府指定之歷史建築物及推動保存之歷史街區。\n十三、其他經本縣都市更新審議委員會同意確有實施都市更新必要者。\n前項第一款、第四款及第八款建築物狀況，應檢附建築師、相關專業技師\n或機構之鑑定證明。\n第 5 條\n本標準自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL041418","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"全文檔案":"彰化縣都市更新單元劃定標準.pdf","公發布日":"民國 95 年 09 月 25 日","廢止日期":"民國 113 年 07 月 30 日","法規名稱":"廢 彰化縣都市更新單元劃定標準","法規體系":"建設類","發文字號":"府行法字第1130285733號","立法理由":"廢止彰化縣都市更新單元劃定標準總說明.pdf"},"promulgation_date":"2006-09-25","revision_date":"2006-09-25","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL041418","status":"repealed","title":"廢 彰化縣都市更新單元劃定標準","last_checked_at":"2026-10-06T17:26:44+08:00","last_success_at":"2026-10-06T17:26:44+08:00","verification_status":"fetched","content_hash":"b00d780f3d66a55d602e559628d1c26d30dec1923996c54baaae092b1f3ceb65","history":[{"observed_at":"2026-10-06T17:26:44+08:00","content_hash":"b00d780f3d66a55d602e559628d1c26d30dec1923996c54baaae092b1f3ceb65","change_kind":"initial","revision_date":"2006-09-25"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=3278&id=FL041418&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=2853&id=FL041418&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"彰化縣政府","category":"建築管理相關","content":"一、彰化縣政府（以下簡稱本府）為辦理既成道路認定及現有巷道廢止或\n改道審議工作，依彰化縣建築管理自治條例第六條及司法院大法官釋\n字第四百號解釋函意旨，特設彰化縣既成道路認定及現有巷道廢止或\n改道審議委員會（以下簡稱本會），並訂定本要點。\n二、本會置委員八至十人，其中一人為召集人，由本府工務處（以下簡稱\n本處）處長兼任，副召集人一人為當然委員，由本處副處長兼任，其\n餘委員由本府就下列有關人員聘（派）兼之：\n（一）建設處副處長。\n（二）地政處副處長。\n（三）法制處副處長。\n（四）彰化縣建築師公會代表一人。\n（五）具有都市計畫、建築設計、法律或交通等專門學識經驗之專家學者\n代表二人以上。\n前項委員任期二年，任期屆滿得續聘（派）之。本府以外委員期滿得\n續聘（派）一任；外聘委員任一性別以不低於外聘委員全數四分之一\n為原則；任期內出缺時，得補行遴聘（派）至原任期屆滿之日止。\n三、本會任務為彰化縣既成道路認定及現有巷道廢止或改道案件之審議。\n四、本會視實際需要召開會議，由召集人召集並擔任主席，召集人因故不\n能主持時，由副召集人代理之；召集人及副召集人均因故不能主持時\n，由出席委員互推一人代理之。\n本會會議應有過半數以上委員出席始得開會；經出席委員過半數同意\n，始得作成決議。\n本會委員應親自出席會議。但本府機關代表兼任之委員未能親自出席\n者，得指派代表出席，並列入出席人數，參與會議發言及表決。\n本會召開會議時，應請本府相關單位出席，並邀當地里長列席，必要\n時並得邀請申請人或公有土地管理機關及陳情人列席說明，但應於表\n決前退席。\n五、本會委員於審議中，有下列情形之一者，應自行迴避：\n（一）本人或其配偶、前配偶、四親等內之血親或三親等內之姻親或曾有\n此關係者為審議案件之當事人時。\n（二）本人或其配偶、前配偶，就該審議案件與當事人有共同權利人或共\n同義務人之關係者。\n（三）現為或曾為該審議案件當事人之代理人、輔佐人者。\n（四）於該審議案件，曾為證人、鑑定人者。\n本會委員於審議中，有下列情形之一者，當事人得申請迴避，並適用\n行政程序法第三十三條有關迴避規定：\n（一）有前項所定之情形而不自行迴避者。\n（二）有具體事實，足認其執行職務有偏頗之虞者。\n六、本會行政業務由本處辦理。\n七、本會委員及兼任人員均為無給職。但外聘委員得支給出席費及交通費\n。\n八、本會所需經費，由本處編列年度預算支應。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL088164","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"公發布日":"民國 104 年 05 月 05 日","廢止/停止適用日期":"民國 112 年 12 月 05 日","法規名稱":"廢/停 彰化縣既成道路認定及現有巷道廢止或改道審議委員會設置要點","法規體系":"工務類","發文字號":"府工管字第1120478988號"},"promulgation_date":"2015-05-05","revision_date":"2015-05-05","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL088164","status":"repealed","title":"廢/停 彰化縣既成道路認定及現有巷道廢止或改道審議委員會設置要點","last_checked_at":"2026-10-06T17:26:53+08:00","last_success_at":"2026-10-06T17:26:53+08:00","verification_status":"fetched","content_hash":"8f12742c15955eebf3a7f72a0a29c782994fcdcbd6bff4b81655cc58683f5eb5","history":[{"observed_at":"2026-10-06T17:26:53+08:00","content_hash":"8f12742c15955eebf3a7f72a0a29c782994fcdcbd6bff4b81655cc58683f5eb5","change_kind":"initial","revision_date":"2015-05-05"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"彰化縣政府","category":"建築管理相關","content":"一、彰化縣政府為有效執行道路交通管理處罰條例第九十條之三第一項機\n慢車之停車秩序，特訂定本要點。\n二、機慢車種類及名稱如下：\n（一）機車：\n1.普通重型機車：\n（1）汽缸總排氣量在逾五十立方公分且在二百五十立方公分以下之\n二輪或三輪機車。\n（2）電動機車之馬達及控制器最大輸出馬力逾五馬力且在四十馬力\n（HP）以下之二輪或三輪機車。\n2.普通輕型機車：\n（1）汽缸總排氣量在五十立方公分以下之二輪或三輪機車。\n（2）電動機車之馬達及控制器最大輸出馬力在五馬力（HP）以下、\n一．三四馬力（電動機功率一千瓦）以上或最大輸出馬力小於\n一．三四馬力（電動機功率小於一千瓦），且最大行駛速率逾\n每小時四十五公里之二輪或三輪機車。\n3.小型輕型機車：電動機車之馬達及控制器最大輸出馬力小於一．\n三四馬力（電動機功率小於一千瓦），且最大行駛速率在每小時\n四十五公里以下之二輪或三輪機車。\n4.前三目三輪機車以車輪為前一後二或前二後一對稱型式排列之機\n車為限。\n（二）慢車：\n1.腳踏自行車。\n2.電動輔助自行車：指經型式審驗合格，以人力為主，電力為輔，\n最大行駛速率在每小時二十五公里以下，且車重在四十公斤以下\n之二輪車輛。\n3.電動自行車：指經型式審驗合格，以電力為主，最大行駛速率在\n每小時二十五公里以下，且車重（不含電池）在四十公斤以下之\n二輪車輛。\n4.人力行駛車輛：指三輪客、貨車、手拉（推）貨車等。\n三、寬度三點五公尺以上之人行道得繪設機慢車停車格，機慢車應停放於\n停車格內，並以一列為限，車輪前緣應與人行道緣石標齊。寬度三公\n尺以上者得以斜向繪設機器腳踏車停車格並維持人行道淨寬一點五公\n尺以上無障礙通行空間。\n人行道管理機關應視實際停車情形，依前項規定劃設停車格或設立停\n放標誌。\n四、禁止劃設機慢車停放區之處所：\n（一）橋樑、隧道之人行道。\n（二）寬度未滿三公尺之人行道。\n（三）消防栓（含大樓消防出水口）前後五公尺範圍。\n（四）公車停靠區範圍。\n（五）行人穿越道前後五公尺範圍。\n（六）貨車裝卸貨格位範圍。\n（七）學校家長接送區範圍。\n（八）公共場所出入口及設有斜坡道之處所。\n（九）市區腳踏車道（人車共道路段應至少保留二公尺淨寬）。\n（十）計程車招呼站牌前計程車停靠範圍。\n五、連續劃設之機慢車停放區，每隔適當距離應留設一處行人通道，通道\n寬度至少二公尺。\n六、身心障礙格位應臨近斜坡道設置，數量得依實際需求調整之。\n七、機慢車停放時，應以停車格格線為準，不得超越，相鄰車輛應注意整\n齊有序。\n八、機慢車進入人行道後，不得乘騎行駛。\n九、機慢車於人行道，應保持整潔，並不得裝載污穢零亂物品、妨礙觀瞻\n與衛生。\n十、於未設置自行車停車設施之人行道，自行車得比照機慢車停放。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL088171","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"修正日期":"民國 104 年 02 月 11 日","公發布日":"民國 102 年 08 月 13 日","法規名稱":"彰化縣人行道機慢車停放及停車格劃設要點","法規體系":"工務類","發文字號":"府工管字第1040045281號"},"promulgation_date":"2013-08-13","revision_date":"2015-02-11","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL088171","status":"unknown","title":"彰化縣人行道機慢車停放及停車格劃設要點","last_checked_at":"2026-10-06T17:26:47+08:00","last_success_at":"2026-10-06T17:26:47+08:00","verification_status":"fetched","content_hash":"f3e0b2a8af5ac3604976026efb08b678d249327a0a492dc515c5af4d3ece423c","history":[{"observed_at":"2026-10-06T17:26:47+08:00","content_hash":"f3e0b2a8af5ac3604976026efb08b678d249327a0a492dc515c5af4d3ece423c","change_kind":"initial","revision_date":"2015-02-11"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"附件一.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=1121&id=GL000216&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"一、\n彰化縣政府(下稱本府)為使本府及本縣各鄉（鎮、市）公所執行彰化縣人行道設置公共設施申請事宜，避免人行動線阻斷，建構完善人行無障礙環境，特訂定本要點。\n二、\n本要點申請設置公共設施，應視道路之權屬向下列管理機關申請：\n(一)縣道、鄉道：本府。\n(二)市區道路、公路與市區道路共線路段、產業道路及村里道路：所在地之鄉（鎮、市）公所。\n三、\n本要點僅就於人行道申請設置公共設施者規定審查事項，如涉及道路挖掘行為，應依彰化縣道路挖掘管理自治條例相關規定辦理。\n四、\n本要點規定之公共設施係指提供為交通、消防、管線設施及經管理機關認定之相關設施。\n五、\n申請設置公共設施應符合下列規定：\n(一)公共設施突出物不得設置為銳角面，最突出之外緣與路肩外緣或路面邊線之淨距應大於零點二公尺。\n(二)公共設施設置後行人通行淨寬一般狀況應大於一點五公尺，人行道總寬度小於一點五公尺或因民生、公益所需之必要附屬設施造成人行道淨寬小於一點五公尺情況則應大於零點九公尺。\n(三)公共設施懸挑至車道部分，淨高應大於四點六公尺，懸挑至人行道部分，淨高不得小於二點一公尺，且於人行道側邊高度零點六至二點一公尺間不得有零點一公尺之突出物。\n(四)公共設施以設置於公共設施帶為原則，如無公共設施帶，以不影響行人及無障礙環境通暢、一般道路或交叉路口之安全視距為原則。\n六、\n申請設置公共設施者，應填具申請書如附件一並檢附簡要計畫書向管理機關申請，簡要計畫書內容應包含：\n(一)公共設施設置類型、尺寸、設置簡圖與用途說明。\n(二)設置地點現況調查表及現況照片。\n(三)申請人或其代表人之身分證件、公司或商業登記證明文件。但政府機關、公營事業機構或公立學校免附。\n(四)其他經管理機關要求之相關證明文件。\n七、\n申請設置公共設施經核准者，申請人應依管理機關核准之圖說自行負擔費用施工完成，完工後檢附施工前中後照片送管理機關備查。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:GL000216","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"公發布日":"民國 109 年 12 月 16 日","圖表附件":"附件一.pdf","法規名稱":"彰化縣人行道申請設置公共設施管理審查要點","法規體系":"工務類","發文字號":"府工管字第1090454192號函"},"promulgation_date":"2020-12-16","revision_date":"2020-12-16","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=GL000216","status":"unknown","title":"彰化縣人行道申請設置公共設施管理審查要點","last_checked_at":"2026-10-06T17:26:46+08:00","last_success_at":"2026-10-06T17:26:46+08:00","verification_status":"fetched","content_hash":"659ce8be96e407adc7579a6a9287747ab36c7b341628d8ebd4e25ce5dbda7610","history":[{"observed_at":"2026-10-06T17:26:46+08:00","content_hash":"659ce8be96e407adc7579a6a9287747ab36c7b341628d8ebd4e25ce5dbda7610","change_kind":"initial","revision_date":"2020-12-16"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=1121&id=GL000216&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"彰化縣政府","category":"建築管理相關","content":"一、彰化縣政府（以下簡稱本府）為執行彰化縣人行道設置斜坡道申請辦\n法（以下簡稱本辦法），俾有一致審查認定標準，特訂定本基準。\n二、本基準之執行及管理機關為本縣各鄉（鎮、市）公所。\n三、申請人應檢附申請書、申請設置地點現況調查表、現況照片及相關證\n明文件，向管理機關提出申請。\n申設條件與本辦法第五條至第八條規定不符者，函覆退件。\n四、管理機關受理申請案後，應就下列事項進行書面審查：\n（一）相關證明文件是否為有效及互為相符。\n（二）申設地點與相關證明文件註記是否相符。\n（三）申設依據與相關證明文件註記是否相符。\n（四）申設事項與現況照片是否相符。\n（五）申設地點違反本辦法第十二條規定者，原申請人於人行道修復後二\n年內，不得於同一地點重新申請設置斜坡道。\n書面審查相關文件不齊全者，應通知申請人於接獲通知次日起七日內\n補正；逾期未補正或補正後仍不合規定者，函覆退件。\n五、管理機關於書面審查後，應洽申請人於現場提供相關文件正本核對，\n並就下列事項進行現場勘查：\n（一）現場與申請書所載地點是否相符。\n（二）申請人現場提供相關文件正本與影本是否相符。\n（三）現場與申請書所附現況照片是否相符。\n（四）現場與相關圖面證明文件所註記內容是否相符。\n（五）營業場所內是否確有停車空間。\n（六）現場與申請書所附現況調查表是否相符。\n（七）營業場所遷址者，原營業地點斜坡道是否已依周邊人行道標準修復\n。\n（八）申請地點有行動不便使用輪椅人士居住，是否距最近斜坡道十五公\n尺以上，或至鄰近斜坡道之間人行道最小淨寬度未達九十公分，並\n無平順騎樓可供替代通行。\n（九）銜接建築物所屬行動不便者通行動線設施是否已完備。\n現場勘查不合規定者，函覆退件。\n六、管理機關於會同申請人進行現場勘查後，如有下列情形之一，應邀集\n申請人及相關單位進行現場會勘：\n（一）申請設置斜坡道範圍有路樹或路燈等公共設施時，以不遷移為原則\n，但現場情形特殊時，邀集公所、本府農業處、本府工務處現場會\n勘處理。\n（二）申請設置斜坡道範圍有號誌或標誌等公共設施時，以不遷移為原則\n，但現場情形特殊時，邀集本府工務處、公所與彰化縣警察局交通\n隊現場會勘處理。\n（三）申請設置斜坡道寬度超過五點五公尺或車道出入口設置二處以上或\n位於道路交叉點或截角線五公尺以上十公尺以下範圍內時，邀集本\n府工務處、公所與各工務段現場會勘處理。\n（四）申請設置斜坡道範圍有公車站牌時，應經公車站牌之權管單位交通\n部公路總局台中區監理站同意重新調整位置，始得設置；申請設置\n斜坡道範圍有其他公共設施時，應經該主管機關同意。\n七、符合下列情形之一者，得依本辦法第八條規定提出申請：\n（一）依其它法令規定或經本府核准設置斜坡道並出具證明者。\n（二）因本府主辦工程致申請人原有汽車通道無法繼續使用者。\n（三）經領有主管建築機關核發「合法房屋證明」之老舊合法房屋者。\n（四）實際從事汽車里程計費表裝修行業，並提出相關文件證明者。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL088156","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"公發布日":"民國 102 年 10 月 28 日","法規名稱":"彰化縣人行道設置斜坡道審查基準","法規體系":"工務類","發文字號":"府工管字第1020333076號"},"promulgation_date":"2013-10-28","revision_date":"2013-10-28","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL088156","status":"unknown","title":"彰化縣人行道設置斜坡道審查基準","last_checked_at":"2026-10-06T17:26:48+08:00","last_success_at":"2026-10-06T17:26:48+08:00","verification_status":"fetched","content_hash":"a41ac677179f0757fc155160ca8346d6c3dd4aa79fa6292615e239058c2065df","history":[{"observed_at":"2026-10-06T17:26:48+08:00","content_hash":"a41ac677179f0757fc155160ca8346d6c3dd4aa79fa6292615e239058c2065df","change_kind":"initial","revision_date":"2013-10-28"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"彰化縣政府","category":"建築管理相關","content":"第 1 條\n彰化縣政府（以下簡稱本府）為辦理人行道設置斜坡道申請事宜，特訂定\n本辦法。\n第 2 條\n本辦法主管機關為本府，管理機關為本縣各鄉（鎮、市）公所。\n第 3 條\n本辦法所稱斜坡道，係指為調整人行道與道路間原有高低差所興建之內嵌\n式平緩斜坡。\n第 4 條\n斜坡道之高低差與斜坡度應符合市區道路及附屬工程設計規範之規定，並\n分為下列三類：\n一、汽車斜坡道：供汽車進出，其寬度最小為二點七五公尺，最大八公尺\n。\n二、機車斜坡道：供機車、腳踏車進出，其寬度最小為零點九公尺，最大\n一點五公尺。\n三、無障礙路緣斜坡道：供輪椅進出，其淨寬不包括側坡之寬度宜大於一\n點二公尺；坡度宜小於百分之八點三三（一：十二）。\n第 5 條\n有下列情形之一者，得申請設置汽車斜坡道：\n一、作為車庫、停車位或停車場通道之使用且確有停車之必要。\n二、經營汽車買賣業、汽車保養業、汽車修理業、汽車裝潢業、汽車美容\n業、汽車清洗業、車輪定位業、輪胎更換業、小客車租賃業或計程車\n營業站、加油站或倉儲物流業，且營業場所內確有停車空間及停車之\n必要。\n第 6 條\n有下列情形之一者，得申請設置機車斜坡道：\n一、經營機車買賣業、機車保養業或機車修理業，且營業場所內有停車空\n間。\n二、住家有機車出入需要，並符合下列情形之一：\n（一）設置地點距離最近斜坡道十五公尺以上者。\n（二）設置地點至鄰近斜坡道間最小淨寬度未達九十公分者。\n（三）設置地點至鄰近斜坡道間無平順路面可通行者。\n第 7 條\n有下列情形之一者，得申請設置無障礙斜坡道：\n一、設置地點有行動不便使用輪椅人士居住。\n二、車站、郵局、銀行、村（里）活動中心、政府機關、學校、醫院、診\n所或其他依建築技術規則建築設計施工編第一百七十條列舉公共建築\n物之場所，為銜接其建築物所屬行動不便者設施通行動線。\n第 8 條\n申請設置斜坡道者，應填具申請書並檢附下列文件向管理機關提出：\n一、設置地點現況調查表及現況照片。\n二、地籍圖謄本，並標示申請地點、斜坡道位置及相關道路名稱。\n三、申請日前一個月內之土地登記簿謄本（標示部、他項權利部）。\n四、申請人為自然人，其身分證（正、反面）影本。申請人為法人或行號\n者，公司登記證明文件或商業登記證明文件及其代表人之身分證正、\n反面影本。但政府機關、公營事業機構或公立學校免附。\n五、依第五條規定申請者，並應加附下列文件：\n（一）對外營業之車庫、停車位或停車場，其停車場登記證影本。\n（二）設置於建築物內或已建築土地之車庫、停車位或停車場，其建築物\n使用執照及核准平面圖影本。\n（三）設置於私有未建築土地之停車位或停車場，其土地所有權證明或使\n用同意書。\n六、依第七條第一款規定申請者，並應加附下列文件：\n（一）行動不便人士需使用輪椅相關證明（如身心障礙手冊或證明影本、\n醫院診斷書或村（里）辦公處出具之證明書等）。\n（二）申請人或其親屬所有之房屋所有權證明或行動不便者設籍證明文件\n。\n七、依前條第二款規定申請之私人機構，並應加附開業證明影本。\n第 9 條\n申請設置斜坡道經核准者，由申請人應於核准日起三個月內，依管理機關\n核發之圖說自行負擔費用施工完成，並檢附完工後之照片送管理機關備查\n。逾期未施工完成者，管理機關得廢止其核准。\n斜坡道配合人行道更新或改善工程設置者，得由工程主辦機關併人行道工\n程一併施工，其施工期限及費用負擔不適用前項規定。\n第 10 條\n申請人施工時，應依下列規定辦理：\n一、原有人行道應採先切割後打除方式辦理。\n二、圖面內含有之溝蓋、緣石等附屬設施應一併設置。\n三、立體停車場及地下停車場之汽車斜坡道出入口應加設車輛駛出感應裝\n置及警示燈。\n第 11 條\n斜坡道、附屬設施及車輛經過之區域，應由申請人負責維護管理，並不得\n妨礙人行道上行人之通行。\n第 12 條\n斜坡道違反原設置目的使用或第十一條規定者，管理機關應通知申請人限\n期改善，屆期未改善或一年內累計達三次者，管理機關得廢止其核准。經\n管理機關廢止核准之斜坡道，應由申請人於廢止後一個月內，依周邊人行\n道標準恢復原狀，並將恢復原狀後之照片送管理機關備查。\n第 13 條\n斜坡道申請核准之原因消滅後，申請人應向管理機關申請廢止斜坡道，並\n於本府同意廢止後一個月內，依周邊人行道標準回復原狀，並將回復原狀\n後之照片送管理機關備查。\n第 14 條\n未依前二條規定恢復原狀者，申請人二年內不得再申請設置斜坡道，管理\n機關並得代為恢復原狀，其費用由申請人負擔。\n第 15 條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL071752","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"修正日期":"民國 103 年 04 月 02 日","公發布日":"民國 102 年 10 月 04 日","法規名稱":"彰化縣人行道設置斜坡道申請辦法","法規體系":"工務類","發文字號":"府法制字第1030099597號"},"promulgation_date":"2013-10-04","revision_date":"2014-04-02","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL071752","status":"unknown","title":"彰化縣人行道設置斜坡道申請辦法","last_checked_at":"2026-10-06T17:26:51+08:00","last_success_at":"2026-10-06T17:26:51+08:00","verification_status":"fetched","content_hash":"6ebc37f7e3d1e1f3daf3b584523fe533f967bdd650d1faa47ad5d6316acd91c1","history":[{"observed_at":"2026-10-06T17:26:51+08:00","content_hash":"6ebc37f7e3d1e1f3daf3b584523fe533f967bdd650d1faa47ad5d6316acd91c1","change_kind":"initial","revision_date":"2014-04-02"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"彰化縣免辦理變更使用執照之規模認定標準總說明.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=2863&id=FL027887&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"第 1 條\n本標準依建築法第七十三條第三項規定訂定之。\n第 2 條\n建築物之使用及變更使用，應符合都市計畫土地使用分區管制或非都市土\n地使用管制之容許使用項目規定。\n第 3 條\n建築物除原供農舍、停車空間或防空避難室使用外，其變更使用在不改變\n主要構造、防火區劃、消防設備、防火避難設施行為且合於下列建築物使\n用類組及規模者，免辦理變更使用執照：\n一  屬同類同組使用項目更動者。\n二  建築物第一層變更為Ｂ類第３組、Ｄ類第５組、Ｅ類、Ｆ類第２組、\nＦ類第３組、Ｇ類第２組、Ｇ類第３組、Ｈ類第１組、Ｈ類第２組使\n用，其變更使用面積在三百平方公尺以下或非供公眾使用範圍者。\n三  建築物避難層直上層變更為Ｄ類第５組、Ｆ類第２組、Ｆ類第３組、\nＧ類第２組、Ｇ類第３組、Ｈ類第１組、Ｈ類第２組使用，其變更使\n用面積在二百平方公尺以下者。\n四  建築物各樓層變更為Ｇ類第２組、Ｇ類第３組使用且為非供公眾使用\n範圍者。\n五  建築物第一層、第二層及地下一層變更為資訊休閒服務業使用，其使\n用面積合計在一百五十平方公尺以下者。\n六  建築物各樓層變更為工廠使用，其使用之作業廠房樓地板面積，在實\n施都市計畫地區未達二百平方公尺或在非實施都市計畫地區未達五百\n平方公尺者。\n前項所稱建築物使用類組，為建築法第七十三條執行要點所訂之使用分類\n。\n第 4 條\n合於前條免辦理變更使用執照者，其建築物所有權人及使用人應於申請營\n利事業登記或立案登記時，檢附申請範圍未有妨礙防火避難設施或構造設\n備，營業範圍絕不佔用建築物附設之停車空間、防空避難設備、自用貯藏\n室及其他公共設施，並願依法維護防火避難設施合法使用及構造設備安全\n之切結證明。\n合於前條免辦理變更使用執照之建築物，主管建築機關得隨時派員檢查其\n有關公共安全與公共衛生之構造與設備。\n如有規避、妨礙或拒絕前項之檢查或檢查不合規定者，應依建築法有關規\n定處分。\n第 5 條\n有關消防安全設備部分，仍應依消防法規定，逕向消防機關辦理。\n有關建築物室內裝修部分，仍應依建築物室內裝修管理辦法規定辦理。\n第 6 條\n本標準自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL027887","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"公發布日":"民國 92 年 11 月 18 日","法規名稱":"彰化縣免辦理變更使用執照之規模認定標準","法規體系":"建設類","發文字號":"府法制字第0920218530號","立法理由":"彰化縣免辦理變更使用執照之規模認定標準總說明.pdf"},"promulgation_date":"2003-11-18","revision_date":"2003-11-18","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL027887","status":"unknown","title":"彰化縣免辦理變更使用執照之規模認定標準","last_checked_at":"2026-10-06T17:26:43+08:00","last_success_at":"2026-10-06T17:26:43+08:00","verification_status":"fetched","content_hash":"ead2255335af8b881ec11d68fb8b8f524089559cdf69f9015ea008dd9c405519","history":[{"observed_at":"2026-10-06T17:26:43+08:00","content_hash":"ead2255335af8b881ec11d68fb8b8f524089559cdf69f9015ea008dd9c405519","change_kind":"initial","revision_date":"2003-11-18"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=2863&id=FL027887&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"附表一彰化縣公共場所道路指示標誌申請設置申請書.PDF","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=449&id=FL088174&type=LAW"},{"name":"附表二彰化縣公共場所道路指示標誌牌背面註記事項.PDF","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=450&id=FL088174&type=LAW"},{"name":"附圖彰化縣公共場所指示標誌申請設置作業流程圖.PDF","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=451&id=FL088174&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"一、為執行道路交通標誌標線號誌設置規則（以下簡稱設置規則）第八十\n七條之一至第一百二十七條之規定，特訂定本要點。\n二、本要點之主管機關為彰化縣政府，管理機關為該申設地點之權責機關\n。\n三、本要點所稱公共場所如下，但不包含中央機關所轄公共場所在內：\n（一）「觀光遊樂地區申請設置道路交通指示標誌審核要點」第三點規定\n之觀光遊樂地區。\n（二）設置規則第八十七條之二定義之遊憩地點，並符合下列情形之ㄧ者\n：\n1.經目的事業主管機認定之體育場（館）、球場、運動場。\n2.面積達五公頃以上之公園。\n3.露營場。\n4.動物園。\n5.經各該中央及地方主管機關公告之文化資產。\n6.其他經目的事業主管機關認定為博物館、展覽場所等場所。\n（三）設置規則第一百十八條之四所列舉之運輸場站。\n（四）設置規則第一百十八條之五所定義之政府機關（構）。\n（五）加油站。\n（六）渡口。\n（七）學校：\n1.大專院校以上。\n2.地址座落於巷、弄之高中（職）以下學校。\n（八）醫院：經核可設立之醫院。\n四、公共場所指示標誌，得由申設單位向管理機關申請許可後自行設置。\n五、申請設置公共場所指示標誌時，應備具下列文件，向管理機關提出之\n：\n（一）申請書（如附表一）。\n（二）公共場所位置平面圖（A3，比例尺 1/1500）。\n（三）施工設計圖（標誌設置地點、方式、內容、規格及數量等）。\n（四）現況照片。\n圖表附件：\n附表一彰化縣公共場所道路指示標誌申請設置申請書.PDF\n六、管理機關受理申請後，應依第三點之規定為公共場所之認定。但申請\n類別屬第三點第二款第五目及第六目者，由管理機關送交各該目的事\n業主管機關認定之。\n七、公共場所指示標誌之設計，應依下列規定：\n（一）標誌設計應符合設置規則規定，其中字型應使用國字方體。\n（二）申請數量以不超過五面為原則。但管理機關得視情況酌予增減。\n（三）設置規則未規定牌面規格者，除指示標誌有整合需要外，以長一四\n○公分、寬八○公分為原則。\n（四）標誌內容須採中、英雙語化，並以漢語拼音為原則。\n八、公共場所指示標誌設置之許可，應符合下列規定：\n（一）申設單位應於核准設置後二個月內，檢送設置完工前後照片至管理\n機關辦理完工查驗；如有不符原核准事項，或未辦理完工查驗，經\n通知限期改善，屆期仍未改善者，撤銷或廢止原許可，並依法強制\n拆除設置物。\n（二）核准設置之標誌牌背面應註明設置時間、核准文號、申設單位及聯\n絡電話等基本資料（如附表二）。\n（三）標誌設置完工後，得因事實需要以書面通知申設單位後，整合、拆\n除或遷移之。\n（四）標誌如有損毀、老舊、褪色等情形者，申設單位應主動修復或汰換\n；如未修復或汰換，經通知限期改善，屆期仍未改善者，廢止原許\n可，並依法強制拆除設置物。\n（五）標誌之設置如不法侵害他人之身體、財產等相關情事，由申設單位\n負責賠償及承擔一切法律責任；如有急迫危險之情事，得逕予拆除\n，所需費用由申設單位負擔。\n圖表附件：\n附表二彰化縣公共場所道路指示標誌牌背面註記事項.PDF\n九、公共場所指示標誌設置得與號誌桿、燈桿或標誌桿共桿，並應符合下\n列規定：\n（一）不得妨礙、遮蔽、破壞現有之標誌、號誌、照明、監控、安全設施\n、燈桿結構及外觀，並應兼顧行車安全。\n（二）牌面在人行道上須維持二一○公分以上淨高，在車道上方須維持四\n六○公分以上淨高，設置於人行道之牌面以距離緣石邊緣三○公分\n為原則。\n十、公共場所指示標誌基座如須挖掘道路，申設單位應向道路管理機關申\n請挖掘道路許可，經核准後方可施工。\n十一、申設單位如須變更標誌位置或牌面內容者，應依申請設置程序檢附\n相關文件，申請變更核准後始得為之。\n十二、因交通管制或其他必要因素，須拆除或遷移指示標誌者，應由管理\n機關以書面通知申請人。\n十三、彰化縣公共場所指示標誌申請設置作業流程如附圖。\n圖表附件：\n附圖彰化縣公共場所指示標誌申請設置作業流程圖.PDF","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL088174","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"公發布日":"民國 103 年 08 月 14 日","法規名稱":"彰化縣公共場所指示標誌設置基準及審核要點","法規體系":"工務類","發文字號":"府工管字第1030257437號"},"promulgation_date":"2014-08-14","revision_date":"2014-08-14","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL088174","status":"unknown","title":"彰化縣公共場所指示標誌設置基準及審核要點","last_checked_at":"2026-10-06T17:26:48+08:00","last_success_at":"2026-10-06T17:26:48+08:00","verification_status":"fetched","content_hash":"3ab616fe87554bd4d9d4e65a106992d7e469529837f22296747e639518f1eb55","history":[{"observed_at":"2026-10-06T17:26:48+08:00","content_hash":"3ab616fe87554bd4d9d4e65a106992d7e469529837f22296747e639518f1eb55","change_kind":"initial","revision_date":"2014-08-14"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=449&id=FL088174&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=450&id=FL088174&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=451&id=FL088174&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"彰化縣政府","category":"建築管理相關","content":"第 一 章 總　則\n第一條\n本府為劃一轄內興辦各項公共設施拆除建築改良物（以下簡稱建築物）查\n估補償標準並簡化作業程序特訂定本辦法。\n第二條\n本辦法所稱之建築物係指下列各款：\n一、都市計劃及內政部指定建築法適用地區發布前之建築物。\n二、日據時期已實施都市計劃地區，光復後依法重行發布實施都市計劃以\n    前建造之建築物。\n三、依建築法領有使用執照之建築物。\n四、依建築法領有建造執照或建築許可及都市計劃公共設施保留地臨時建\n    築使用辦法施行前領有臨時建造執照之建築物，但以主要構造及位置\n    ，均係按照核准之工程圖樣施工者為限。\n第三條\n合法房屋概以重置價格之「面積評點法」查估補償，不予折舊，亦不考慮\n因地段所異之減半。\n第四條\n本府及所屬各用地機關應依照實地調查資料估算拆遷補償費，並於拆除前\n通知所有權人，對於估價有異議時，應於協議時提出。建築物所有權人於\n協議時提出異議者，用地機關應派員複查並估算複查後之補償額通知領款\n。並由鄉鎮市公所負責查估報由本府複估為原則。\n第五條\n道路兩旁依規定須留設騎樓者拆除建築物時一併打通為原則。\n第 二 章 建築物之拆遷補償\n第六條\n建築物之認定，由查估單位會同權責單位及所有權人或管理人查證。\n第七條\n房屋價格概以評點計值得每年定期調整單價一次，以七十年七月份總指數\n為基數，每一評點以新臺幣肆元伍角計值，今後每年七月一日按臺灣省物\n價統計月報表發布，最近月份臺灣省勞造工程工料價格指數自行調整評點\n單價。（八十二年元月起調整每評點為柒元計值）\n第八條\n房屋價格評點數標準按建築物構造體及粉裝造作訂定評點數（如附表）。\n第九條\n自動拆遷將勵金發給標準如左：\n一、凡於限期內自行拆除者，給予重建價格百分之五十計列發給，逾越限\n    期拆除者不予發給充為本府代為執行拆除費用，凡由本府代為執行拆\n    除時其留置現場之所有建築材料及物品，本府不負保管責任，並視同\n    廢棄物處理，辦理省屬以上機關或其他機關用地拆遷其自動拆遷獎勵\n    金比照該機關發給標準辦理。\n二、凡於期限內搬遷者依戶政事務所所訂門牌，每戶發給搬遷費二千點數\n    外，另按每口再發給八百點，最高以五口計算。\n第十條\n建築物部份拆除後其賸餘部份無法繼續使用（賸餘部份之底層面積小於十\n五平方公尺者）或有礙結構安全時及位於公共設施保留地上者得一併拆除\n補償之。\n第十一條\n建築物依法留設之騎樓地，於領取使用執照後擅自阻塞者應予拆除概不補\n償。\n第 三 章 工廠生產設備及營業設備拆遷補助\n第十二條\n電力外線工程費補助建築物全部拆除者或部份拆除確無法繼續生產及須移\n設線路者或營業者，依查估前一個月之電費百分之十補償，其限額最高為\n六百評點最低為二百評點。\n第十三條\n自來水外線工程費補助，建築物全部拆除者或部份拆除確無法繼續生產或\n營業者及須移設管理者，按自來水公司所訂用水設備，外線價格表之標準\n檢據補償。\n第十四條\n瓦斯外線工程費補助之依瓦斯公司計算標準比照第十三條規定辦理。\n第十五條\n固定及附屬設備之補償。\n一、機械臺基礎，依構造體之區別計算其數量折算重置價格補償。\n二、工業及營業用水槽，以容量計算依其構造體之區別補償。\n三、工業及營業用灶單座--六百評點，雙連座--一千評點。\n四、水井補償部分（如后），廢井不予補償。\n（一）二．五公分（一吋）每三十公分五百元。\n（二）五公分（二吋）每三十公分五百九十元。\n（三）七．六公分（三吋）每三十公分七百二十元。\n（四）一○公分（四吋）每三十公分七百七十元。\n（五）一二．七公分（五吋）每三十公分八百三十元。\n（六）一五．二公分（六吋）每三十公分八百九十元。\n（七）二○．三公分（八吋）每三十公分一千一百九十元。\n（八）二五．四公分（十吋）每三十公分一千二百九十元。\n（九）三○．四公分（十二吋）每三十公分一千三百九十元。\n（十）三五．五公分（十四吋）每三十公分一千七百八十元。\n（十一）四○．六公分（十六吋）每三十公分一千九百八十元。\n（十二）四十五公分每三十公分二千一百八十元。\n（十三）六十公分每三十公分二千三百八十元。\n（十四）九十公分每三十公分二千五百七十元。\n（十五）一百十公分每三十公分二千七百七十元。\n（十六）一百二十公分每三十公分二千九百七十元。\n（十七）一百三十公分每三十公分三千一百七十元。\n（十八）一百五十公分每三十公分三千五百六十元。\n    以上所列井徑以內徑為標準：而（一）－（十一）項之單價係以塑膠\n    管為準，若遇鐵管以上材質之水井，其單價應再加一成二計算。\n五、前項查定標準係參照台中縣辦理公共工程建築改良物拆遷補償辦法及\n    台灣區鑿井工程工業同業公會提供造價訂定。\n六、持有水權狀（含臨時用水執照）或依法符合免申請條件者，依查定金\n    額補償；所持水權狀（含臨時用水執照）已逾越期限者依查定金額百\n    分之八十發給；提不出水權狀（含臨時用水執照）者依查定金額百分\n    之四十發給救濟金。\n七、水井深度現場無法丈量時，由水井持有人切結辦理。\n第十六條\n固定附屬設備未列明補償標準者得按構造物核實查估予以補償。\n第十七條\n機械拆卸運搬及安裝工資按所需工數查估補償。\n第 四 章 附屬建築及附屬設備之補償\n第十八條\n室外附屬雜項建造物依構造體估算其重建價格。\n第十九條\n電話遷機費之補償，參照電信局所訂標準全額補助。\n第二十條\n中央系統之空調冷凍設備，昇降機及高壓受電一次側之電壓 11.4KW 以上\n之自設變電設備等得按構造並參照帳簿所記附屬設備費及憑證核實查估予\n以補償。\n第 五 章 附　則\n第二十一條\n補償費應於拆除期限內發放拆遷獎勵金及補助費應於房屋拆除後二星期內\n發放。\n第二十二條\n前條所定補償費，未於通知限期內具領者發放機關得再限期通知一次，仍\n不具領者或拒領者提存法院，但獎勵金及補助費等逾期未領者以棄權論。\n第二十三條\n辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:GL000118","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"修正日期":"民國 88 年 02 月 26 日","公發布日":"民國 71 年 09 月 00 日","法規名稱":"彰化縣公共設施拆遷建築改良物補償辦法","法規體系":"工務類","發文字號":"彰化縣政府八八彰府秘法字第 037535 號令"},"promulgation_date":null,"revision_date":"1999-02-26","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=GL000118","status":"unknown","title":"彰化縣公共設施拆遷建築改良物補償辦法","last_checked_at":"2026-10-06T17:26:53+08:00","last_success_at":"2026-10-06T17:26:53+08:00","verification_status":"fetched","content_hash":"fee7898eaf5ae29ad95e9486272d7c64a5e7dbbb7486259c86498d788e30b35f","history":[{"observed_at":"2026-10-06T17:26:53+08:00","content_hash":"fee7898eaf5ae29ad95e9486272d7c64a5e7dbbb7486259c86498d788e30b35f","change_kind":"initial","revision_date":"1999-02-26"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"彰化縣政府","category":"建築管理相關","content":"一、公共設施用地已完成徵收者，原則不變更為其他土地使用分區或公共\n設施用地。\n二、除學校以外之公共設施用地，服務半徑 500  公尺內無相同公共設施\n者，原則不變更為其他土地使用分區或公共設施用地。\n三、各項公共設施用地面積如已超出「都市計畫定期通盤檢討實施辦法」\n之標準，符合下列各款，經實際檢討後已不具原設置之功能者，得變\n更為其他適合土地使用分區，並依「彰化縣都市計畫區土地變更回饋\n審議原則」辦理：\n前項公共設施如有不足，但該計畫區內有公有土地可供劃設補充，經\n補充後超出各該項公設用地檢討標準部分，仍得依本點規定辦理。\n（一）公共設施劃設逾 20 年以上，需地機關未辦理徵收，經需地機關表\n示無使用計畫者，得優先檢討變更。\n（二）公共設施用地範圍內，合法建物密集，其所佔面積逾 50％ 以上，\n經範圍內私有土地所有權人二分之一以上，及其所有土地總面積超\n過土地總面積二分之一以上之同意者，得優先檢討調整。\n四、符合前述第一至三點檢討原則之公共設施用地，應以公平、效率、安\n全、便利為原則，考量區位條件、服務半徑及預期發展等因素，依據\n都市計畫法第二十六條規定辦理通盤檢討或公共設施專案通盤檢討。\n五、本原則之適用範圍，不含計畫道路用地。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL088002","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"公發布日":"民國 95 年 10 月 05 日","法規名稱":"彰化縣公共設施用地變更為可建築土地優先檢討原則","法規體系":"建設類","發文字號":"字第號"},"promulgation_date":"2006-10-05","revision_date":"2006-10-05","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL088002","status":"unknown","title":"彰化縣公共設施用地變更為可建築土地優先檢討原則","last_checked_at":"2026-10-06T17:26:32+08:00","last_success_at":"2026-10-06T17:26:32+08:00","verification_status":"fetched","content_hash":"b03eced8538ec1e28f4f81313302b8e0ffe5afc279a7112b0796dd6741b4c762","history":[{"observed_at":"2026-10-06T17:26:32+08:00","content_hash":"b03eced8538ec1e28f4f81313302b8e0ffe5afc279a7112b0796dd6741b4c762","change_kind":"initial","revision_date":"2006-10-05"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"彰化縣公寓大廈共用部分及約定共用部分維護修繕費用補助辦法(令).pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=2851&id=FL064442&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"第 1 條\n本辦法依公寓大廈管理條例第十條第三項規定訂定之。\n第 2 條\n本辦法之主管機關為彰化縣政府（以下簡稱本府），主辦單位為本府建設\n處。\n第 3 條\n本辦法補助對象為彰化縣（以下簡稱本縣）轄內領有建築物使用執照滿十\n年且已依公寓大廈管理條例成立管理委員會或推選管理負責人，並向各該\n鄉（鎮、市）公所報備有案之公寓大廈。\n第 4 條\n本辦法補助範圍以該公寓大廈之共用部分及約定共用部分設施者為限，其\n補助項目如下：\n一、涉及公共環境清潔衛生之維持。\n二、公共消防滅火器材之維護。\n三、公共通道溝渠及相關設施之修繕。\n第 5 條\n申請本辦法之補助者，應由公寓大廈管理委員會或管理負責人填具申請書\n，並檢附下列文件向本府建設處提出：\n一、公寓大廈管理組織報備證明文件影本。\n二、區分所有權人會議或管理委員會會議紀錄影本。\n三、建築物使用執照影本。\n四、公寓大廈之共用部分、約定共用部分維護修繕成果：施工前照片、完\n工照片、施工位置平面圖及管理委員會或管理負責人支付費用發票或\n收據之正本。\n五、管理委員會或管理負責人金融機構存摺封面（戶名及帳號）影本。\n六、其他相關證明文件。\n前項申請應於申請補助項目完成後一年內提出。\n第 6 條\n本辦法之補助金額，除下列項目為維護修繕費之二分之一以外，其餘項目\n以五分之一為限：\n一、設置或改善供行動不便者使用設施、設備。\n二、騎樓順平之改善。\n三、招牌廣告或樹立廣告之改善。\n四、建築物外牆之整修、粉刷或清潔。\n本辦法之補助金額，並不得超過下列額度：\n一、總戶數一百戶以下者，新臺幣六萬元。\n二、總戶數一百零一戶至二百戶者，新臺幣八萬元。\n三、總戶數二百零一戶以上者，新臺幣十萬元。\n同一公寓大廈每四年以補助一次為限。\n第 7 條\n本府為審查本辦法之補助得設審查小組，其設置要點由本府另定之。\n第 8 條\n本辦法之補助作業相關規定，由本府公告之。\n第 9 條\n本辦法所需經費由本府視財源編列預算辦理，當年度編列之經費如已用罄\n，當年度不再受理申請。\n第 10 條\n本辦法所需之書表格式，由本府另定之。\n第 11 條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL064442","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"全文檔案":"彰化縣公寓大廈共用部分及約定共用部分維護修繕費用補助辦法(令).pdf","公發布日":"民國 101 年 02 月 07 日","法規名稱":"彰化縣公寓大廈共用部分及約定共用部分維護修繕費用補助辦法","法規體系":"建設類","發文字號":"府法制字第1010029339號"},"promulgation_date":"2012-02-07","revision_date":"2012-02-07","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL064442","status":"unknown","title":"彰化縣公寓大廈共用部分及約定共用部分維護修繕費用補助辦法","last_checked_at":"2026-10-06T17:26:40+08:00","last_success_at":"2026-10-06T17:26:40+08:00","verification_status":"fetched","content_hash":"0c0ff1ca937a4930c9478f5875858b759b20441859cd52c0419f90ceba0d5b25","history":[{"observed_at":"2026-10-06T17:26:40+08:00","content_hash":"0c0ff1ca937a4930c9478f5875858b759b20441859cd52c0419f90ceba0d5b25","change_kind":"initial","revision_date":"2012-02-07"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=2851&id=FL064442&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"彰化縣政府","category":"建築管理相關","content":"第 1 條\n本辦法依彰化縣公寓大廈輔導管理自治條例第八條規定訂定之。\n第 2 條\n本辦法之主管機關為彰化縣政府（以下簡稱本府），執行單位為本府建設\n處。\n第 3 條\n本辦法補助對象為領有建築物使用執照且已依公寓大廈管理條例成立管理\n委員會或推選管理負責人，並向公寓大廈所在之公所報備有案之公寓大廈\n，其居住事實之住戶符合社會救助法之低收入戶及中低收入戶或其他經主\n管機關認定者達全部住戶二分之一以上者。\n第 4 條\n本辦法補助範圍以前條公寓大廈之共用部分及約定共用部分之防火避難設\n施為限。\n第 5 條\n申請本辦法之補助者，應由公寓大廈管理委員會或管理負責人填具申請書\n，並檢具下列文件向本府建設處提出：\n一  公寓大廈管理組織報備證明文件影本。\n二  區分所有權人會議或管理委員會會議紀錄影本。\n三  建築物使用執照影本。\n四  公寓大廈之共用部分、約定共用部分防火避難設施維\n護修繕成果：施\n工前照片、完工照片及管理委員會或\n管理負責人支付費用發票或收據\n之正本。\n五  管理委員會或管理負責人金融機構存摺封面（戶名及\n帳號）影本。\n六  有居住事實住戶之低收入戶及中低收入戶證明文\n件正本（需為設施維\n護修繕當年度）。\n七  其他相關證明文件。\n前項申請應於申請補助項目完成後一年內提出。申請人提\n送之申請文件有\n欠缺，經主管機關通知限期補正，屆期未完成\n補正者，駁回其申請。\n第 6 條\n每一公寓大廈維護修繕費用最高補助金額為維護修繕費之二分之一，且不\n得超過下列額度：\n一  總戶數五十戶以下者，新臺幣十六萬元。\n二  總戶數五十一戶至一百戶者，新臺幣二十萬元。\n三  總戶數一百零一戶至二百戶者，新臺幣二十四萬元。\n四  總戶數二百零一戶以上者，新臺幣二十八萬元。\n同一公寓大廈每四年以補助一次為限。\n第 7 條\n本府為審查本辦法之補助得設審查小組，其設置要點由本府另定之。\n第 8 條\n本辦法之補助作業相關規定，由本府另定之。\n第 9 條\n本辦法所需經費由本府視財源編列預算辦理，當年度編列之經費如已用罄\n，當年度不再受理申請。\n第 10 條\n有下列情事之一者，主管機關不予核發補助；已核發補助者，得撤銷一部\n分或全部，並以書面行政處分追繳已受領之補助費：\n一  申領資料不實。\n二  違背其他法令之情事。\n主管機關作成核發補助處分時，應於處分書中載明前項事項。\n第 11 條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:GL000365","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"公發布日":"民國 112 年 11 月 16 日","法規名稱":"彰化縣公寓大廈共用部分及約定共用部分防火避難設施費用補助辦法","法規體系":"建設類","發文字號":"府行法字第1120454271號令"},"promulgation_date":"2023-11-16","revision_date":"2023-11-16","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=GL000365","status":"unknown","title":"彰化縣公寓大廈共用部分及約定共用部分防火避難設施費用補助辦法","last_checked_at":"2026-10-06T17:26:38+08:00","last_success_at":"2026-10-06T17:26:38+08:00","verification_status":"fetched","content_hash":"ca2096989296e2fb19e94fc9b221718ca404fe8e7ac0a6493ca0360b2e1a348f","history":[{"observed_at":"2026-10-06T17:26:38+08:00","content_hash":"ca2096989296e2fb19e94fc9b221718ca404fe8e7ac0a6493ca0360b2e1a348f","change_kind":"initial","revision_date":"2023-11-16"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"彰化縣公寓大廈輔導管理自治條例(令).pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=2906&id=GL000343&type=LAW"},{"name":"彰化縣公寓大廈輔導管理自治條例總說明.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=2907&id=GL000343&type=LAW"},{"name":"彰化縣公寓大廈輔導管理自治條例逐條說明.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=2908&id=GL000343&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"第 1 條\n為加強彰化縣(以下簡稱本縣)公寓大廈之輔導及管理，提升住戶居住品質及\n安全，特制定本自治條例。\n第 2 條\n本自治條例之主管機關為彰化縣政府(以下簡稱本府)。\n本自治條例所定事項，涉及本府各目的事業主管者，其相關權責劃分如下：\n一、本府建設處：非屬目的事業主管機關權責範圍之事項。\n二\n、\n本縣消防局：建築物之消防安全管理等事項。\n第 3 條\n本自治條例之用詞定義如下：\n一\n、\n公寓大廈：指構造上或使用上或在建築執照設計圖樣標有明確界線，得\n區分為數部分之建築物及其基地。\n二\n、\n既有公寓大廈：指公寓大廈管理條例施行前已取得建造執照，且未依公\n寓大廈管理條例成立管理委員會或推選管理負責人之公寓大廈。\n三\n、\n管理委員會：指為執行區分所有權人會議決議事項及公寓大廈管理維護\n工作，由區分所有權人選任住戶若干人為管理委員所設立之組織。\n四\n、\n管理負責人：指未成立管理委員會，由區分所有權人推選住戶一人或依\n公寓大廈管理條例第二十九條第六項規定為負責管理公寓大廈事務者。\n五\n、\n住戶：指公寓大廈之區分所有權人、承租人或其他經區分所有權人同意\n而為專有部分之使用者或業經取得停車空間建築物所有權者。\n六\n、\n區分所有權人會議：指區分所有權人為共同事務及涉及權利義務之有關\n事項，召集全體區分所有權人所舉行之會議。\n第 4 條\n本府對六層以上既有公寓大廈，得分類分期分區公告輔導暨補助計畫，並輔\n導召開區分所有權人會議成立管理委員會或推選管理負責人。\n前項公告計畫範圍內之公寓大廈區分所有權人，應於公告日起一年內，互推\n一人為召集人，召開第一次區分所有權人會議，成立管理委員會或推選管理\n負責人，並向其所在轄區之鄉(鎮、市)公所報備。\n召集人無法依前項規定互推產生時，本府得指定區分所有權人一人為臨時召\n集人。\n第 5 條\n第四條第二項公告計畫範圍內之六層以上既有公寓大廈應於成立管理委員會\n或推選管理負責人之日起一個月內，檢附下列文件向其所在轄區之鄉(鎮、\n市)公所報備：\n一\n、\n申請報備書及申請報備檢查表。\n二\n、\n成立管理委員會或推選管理負責人時之全體區分所有權人名冊。\n三\n、\n成立管理委員會或推選管理負責人時之區分所有權人會議紀錄、出席人\n員簽到簿、推舉管理負責人公告及規約。\n四\n、\n公寓大廈之建築物使用執照影本。\n第 6 條\n鄉(鎮、市)公所審查前條應備文件齊全後，應發給報備證明，並報請本府備\n查，同時函文通知本府建設處、本縣警察局及本縣消防局。\n前條應備文件不齊者，鄉(鎮、市)公所應通知管理委員會或管理負責人於一\n定期間補正。屆期未補正者，不予受理。\n第 7 條\n本縣消防局依申請或職權不定期舉辦建築物搶救演練。\n公寓大廈管理委員會或管理負責人得向本縣消防局申請開設有關防火宣導及\n避難逃生相關課程。\n第 8 條\n已成立管理委員會或推選管理負責人之公寓大廈，其有居住事實之住戶符合\n社會救助法之低收入戶及中低收入戶或其他經主管機關認定者達全部住戶二\n分之一以上者，得向本府建設處申請補助防火避難設施或向本縣消防局申請\n補助相關消防安全設備，其補助辦法由各目的事業主管機關另定之。\n第 9 條\n未依第四條第二項成立管理委員會或推選管理負責人者，本府應通知限期改\n善，屆期未改善者，處各專有部分區分所有權人新臺幣一萬元以上五萬元以\n下罰鍰，並限期改善；屆期仍未改善者，得連續處罰。\n第 10 條\n本自治條例未規定之事項，適用其他相關法令。\n第 11 條\n本自治條例自公布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:GL000343","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"修正日期":"民國 114 年 01 月 20 日","全文檔案":"彰化縣公寓大廈輔導管理自治條例總說明.pdf","公發布日":"民國 112 年 05 月 05 日","圖表附件":"彰化縣公寓大廈輔導管理自治條例逐條說明.pdf","法規名稱":"彰化縣公寓大廈輔導管理自治條例","法規體系":"建設類","發文字號":"府行法字第1140019812號","立法理由":"彰化縣公寓大廈輔導管理自治條例(令).pdf"},"promulgation_date":"2023-05-05","revision_date":"2025-01-20","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=GL000343","status":"unknown","title":"彰化縣公寓大廈輔導管理自治條例","last_checked_at":"2026-10-06T17:26:35+08:00","last_success_at":"2026-10-06T17:26:35+08:00","verification_status":"fetched","content_hash":"36a081e540f18284655ac5c3f6f09e2962f15068fe94ea3fcbdc5905b2a878a2","history":[{"observed_at":"2026-10-06T17:26:35+08:00","content_hash":"36a081e540f18284655ac5c3f6f09e2962f15068fe94ea3fcbdc5905b2a878a2","change_kind":"initial","revision_date":"2025-01-20"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=2906&id=GL000343&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=2907&id=GL000343&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=2908&id=GL000343&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"格式 合併使用證明申請書.ODT","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=123&id=FL026529&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"一、本基準依彰化縣畸零地使用自治條例（以下簡稱本自治條例）第十六\n條規定訂定之。\n二、私有土地合於下列各款情形之一者，其土地所有權人得申請核發公有\n畸零地合併使用證明書（以下簡稱本證明書）\n（一）相鄰之私有土地與公有土地均屬畸零地，非合併無法建築使用者。\n（二）公有土地屬畸零地，非與其相鄰之私有土地合併無法建築使用者。\n（三）私有土地屬畸零地，非與其相鄰之公有土地合併無法建築使用者。\n三、私有土地如與申請之公有土地合併使用後，仍無法單獨建築使用者不\n得發給本證明書。\n四、申請合併之公有畸零地如已建築完成者，不發給本證明書。但有下列\n情形者不在此限。\n（一）本自治條例第九條第二項所定情事者。\n（二）已建築完成之建築物為申請人所有者。\n（三）已建築完成之建築物非為申請人所有，應取得房屋所有權人同意書\n。\n申請核發公有畸零地合併使用證明書，僅供建築基地合併使用或調整\n地形之參考，如涉及私權糾紛由申請人及公有財產主管機關（單位）\n另循其他法規及程序處理。\n五、私有土地非與相鄰公有畸零地之一部分合併無法建築使用者，得核發\n該部分之合併使用證明書。\n六、兩筆以上權屬不同之私有土地與相鄰公有畸零地合併後始得建築使用\n者，申請核發本證明書應檢具各該私有土地所有權人同意合併使用協\n議文件。\n七、公有畸零地與其兩側任一私有非畸零地合併均可單獨建築使用時，任\n一側私有土地所權有人均得申請核發本證明書。\n八、公有畸零地兩側之私有地均非屬畸零地，而私有裡地申請將該公有畸\n零地作為私設通路，如該道路符合建築技術規則建築設計施工篇第二\n條之規定時，得發給本證明書。\n九、面臨現有巷道申請建築，因指定建築線退讓之基地，於巷道邊緣與建\n築線間夾有公有畸零地者，得申請核發本證明書。\n十、公有土地之界線與建築線斜交角度不滿六十度或超過一百二十度者，\n其鄰接之私有土地得就規定最小深度範圍內，將該公有地界夾角調整\n為六十度至九十度或一百二十度至九十度間，申請與該角度調整後所\n夾公有土地合併使用。\n十一、私有畸零地與公有土地合併使用達規定最小深度，所餘公有土地非\n合併使用無法建築，得發給本證明書。但公有裡地與相鄰私有土地\n合併始能建築使用者，得一併提出申請，惟應在證明書中註明合併\n理由，並於附圖中另以不同圖例表示。\n十二、本證明書應附圖註明下列事項：\n（一）基地及其鄰近之土地現況標示。\n（二）土地使用分區或使用地別。\n（三）道路寬度及其境界線。\n（四）規定最小寬度、最小深度。\n（五）合併使用範圍。\n（六）騎樓地或應留設之前、後側院或其他必要事項。\n十三、申請核發本證明書，應檢具下列書件：\n（一）申請書一份、證明書二份。\n（二）合併使用範圍土地之土地登記謄本、地籍圖謄本各一份。\n（三）建築線指示成果一份。\n（四）申請合併使用範圍圖說。\n（五）其它經主管建築機關（單位）認為必要證明文件。\n十四、受理申請核發本證明書時，應於收到申請書之日起十日內審查完竣\n，其符合規定者發給證明，不合規定者列舉理由通知申請人。\n需會同有關機關（單位）現地勘查者，前項審查期限延長十日。\n十五、本證明書之有效期間為八個月。\n在前項有效期間內核發本證明書之相關法令變更，致本證明書之內\n容與其抵觸時，本證明書失效。\n十六、合併使用證明書（申請書）格式如下。\n圖表附件：\n格式 合併使用證明申請書.ODT","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL026529","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"修正日期":"民國 93 年 05 月 13 日","公發布日":"民國 90 年 08 月 09 日","法規名稱":"彰化縣公有畸零地合併使用證明書核發基準","法規體系":"建設類","發文字號":"府建管字第0930091863號"},"promulgation_date":"2001-08-09","revision_date":"2004-05-13","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL026529","status":"unknown","title":"彰化縣公有畸零地合併使用證明書核發基準","last_checked_at":"2026-10-06T17:26:32+08:00","last_success_at":"2026-10-06T17:26:32+08:00","verification_status":"fetched","content_hash":"8cf6c80f63ffb206e1d9a00067ae498b8ffda469844f1d8c26df7a375098cea3","history":[{"observed_at":"2026-10-06T17:26:32+08:00","content_hash":"8cf6c80f63ffb206e1d9a00067ae498b8ffda469844f1d8c26df7a375098cea3","change_kind":"initial","revision_date":"2004-05-13"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=123&id=FL026529&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"彰化縣政府","category":"建築管理相關","content":"第一條\n本辦法依停車場法第二十九條規定訂定之\n第二條\n本辦法所稱公有路外停車場指彰化縣政府（以下簡稱本府）在道路路面外，\n以平面式、立體式、機械式或塔台式等所設供停放車輛之場所。\n第三條\n公有路外停車場委託民間經營，應以公開招標方式為之，由得標者與本府訂\n定租賃契約後，取得經營權。\n第四條\n參與投標經營公有路外收費停車場者，凡中華民國國民年滿二十歲以上自然\n人及營業項目具有停車場經營業務之公司均可參加投標。但自然人得標後應\n依商業登記法規定以獨資方式辦理登記。\n第五條\n租賃期間公有路外停車場應繳納之地價稅及房屋稅由本府負擔，其餘有關停\n車場經營應繳納之稅捐及費用，由承租人負擔。承租人如需增添、更換設備，\n應徵得本府同意後始得為之，費用由承租人負擔，並不得要求任何補償。\n第六條\n承租人應將公有路外停車場開放供公眾停車使用，除法令另有規定外，不得\n指定專用專位供特定對象使用。\n承租人不得於公有路外停車場經營停車場業務以外之商業行為。\n第七條\n承租人得依區域、流量、時段之不同，訂定差別費率。其停車費以計時收取\n為原則，並得採月票方式收費；其位於市中心區或商業區者，得採計時累進\n方式收費。\n委託民間經營之公有路外停車場，其費率不得超過該公有路外停車場收費費\n率標準之規定，並應報請本府核備後實施。\n第八條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:GL000089","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"修正日期":"民國 89 年 01 月 03 日","公發布日":"民國 88 年 02 月 04 日","法規名稱":"彰化縣公有路外停車場委託民間經營辦法","法規體系":"建設類","發文字號":"彰府秘法字第000698號"},"promulgation_date":"1999-02-04","revision_date":"2000-01-03","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=GL000089","status":"unknown","title":"彰化縣公有路外停車場委託民間經營辦法","last_checked_at":"2026-10-06T17:26:44+08:00","last_success_at":"2026-10-06T17:26:44+08:00","verification_status":"fetched","content_hash":"a1c96a3ebca640c3f40bf0b30275dff0351442df43b6a38d232b1b8a6db1c3b4","history":[{"observed_at":"2026-10-06T17:26:44+08:00","content_hash":"a1c96a3ebca640c3f40bf0b30275dff0351442df43b6a38d232b1b8a6db1c3b4","change_kind":"initial","revision_date":"2000-01-03"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"彰化縣政府","category":"建築管理相關","content":"一、\n彰化縣政府（以下簡稱本府）為使共同管道管理及維護經費專戶（以下簡稱本專戶）之運用得以有所遵循，特訂定本要點。\n二、\n本專戶之資金來源如下：\n(一)政府或事業機構提供之專款收入。\n(二)共同管道管理維護經費及使用費收入。\n(三)寬頻管道租金收入及攤還本府代墊配合款。\n(四)個人或團體之捐助款收入。\n(五)本專戶孳息收入。\n(六)其他收入。\n三、\n本專戶得支用項目如下：\n(一)辦理共同管道建設、改善及其他與建設有關之費用。\n(二)共同管道及相關附屬設備之管理維護費用支出。\n(三)共同管道之水電費支出。\n(四)辦理共同管道管理及維護相關教育訓練、資訊管理及研究發展等相關業務費用。\n(五)共同管道維護之人事費支出（含薪資、保險、離職儲金等其他相關費用）。\n(六)影響共同管道正常營運之相關改善工程費用支出。\n(七)辦理共同管道委外管理及維護所需相關費用。\n(八)其他與本專戶業務有關費用。\n四、\n本專戶會計事務之處理，依相關會計作業規定辦理。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:GL000419","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"公發布日":"民國 113 年 09 月 04 日","法規名稱":"彰化縣共同管道管理及維護經費專戶收支管理運用要點","法規體系":"工務類","發文字號":"府工管字第1130339167號函"},"promulgation_date":"2024-09-04","revision_date":"2024-09-04","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=GL000419","status":"unknown","title":"彰化縣共同管道管理及維護經費專戶收支管理運用要點","last_checked_at":"2026-10-06T17:26:44+08:00","last_success_at":"2026-10-06T17:26:44+08:00","verification_status":"fetched","content_hash":"0bbf8a8f94dae5fba6668b301e6a4dbbf1f5479f6250a58ebe7407adf692fb1f","history":[{"observed_at":"2026-10-06T17:26:44+08:00","content_hash":"0bbf8a8f94dae5fba6668b301e6a4dbbf1f5479f6250a58ebe7407adf692fb1f","change_kind":"initial","revision_date":"2024-09-04"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"彰化縣政府","category":"建築管理相關","content":"第 1 條\n依共同管道法第十七條規定訂定本辦法。\n第 2 條\n本辦法之主管機關為彰化縣政府（以下簡稱本府）；管理單位為本府工務\n處。\n第 3 條\n本府得委託專業機構辦理共同管道主體及其附屬設施之管理維護，其內容\n包括下列事項：\n一  申請進入或使用共同管道之許可證件、完竣報告書及作業工作之查核\n。\n二  共同管道門禁管制。\n三  共同管道監控中心各項設備監控、操作及維護。\n四  共同管道主體及其附屬設施定期巡視檢查、保養及清潔維護。\n五  共同管道禁挖道路範圍之巡查、通報。\n六  共同管道緊急事故應變處理及防災演習。\n七  管理文件建檔及保管。\n八  管理單位指示其他有關共同管道維護應辦事項。\n第 4 條\n本辦法之管線事業機關（構）權責如下：\n一  共同管道內各該公共設施管線及其附屬設施定期巡視檢查、保養及維\n護。\n二  共同管道緊急事故應變處理。\n三  配合辦理共同管道防災演習。\n四  共同管道管線管理資料之建檔保管。\n前項第一款之附屬設施由二個以上管線事業機關（構）共同使用時，應協\n商共同管道管理維護，並明定協議事項之執行；無法達成協議時，由管理\n單位協調決定之。\n第 5 條\n參與共同管道建設之管線事業機關（構）於共同管道竣工，經結清應負擔\n之建設經費，並依共同管道建設及管理經費分攤辦法規定提撥共同管道管\n理及維護經費後，管理機關得核發使用許可，如有先行使用需求，得核發\n臨時使用許可。\n第 6 條\n未負擔共同管道工程建設經費之管線事業機關（構）於共同管道佈設新增\n管線，應先檢具申請書及相關文件向管理單位申請許可，於繳納許可年限\n之使用費及保證金後，發給許可。但許可年限不得逾五年。\n申請書應載明下列事項：\n一  管線事業機關（構）名稱。\n二  使用共同管道之範圍。\n三  佈設管線種類及其附屬設施。\n四  使用期間。\n五  其他相關事項。\n申請文件如有欠缺，經限期補正而未補正，或經通知期限繳納使用費及保\n證金而未依限繳納者，應駁回其申請。\n第 7 條\n前條第一項之使用費，依管線事業機關（構）使用共同管道之長度及期間\n計算，使用期間以年為計收單位，不滿一年者，以一年計收。\n共同管道之年使用費計算方式如下：年使用費（元／年‧公尺）＝年總營\n運成本（元）÷ 總長度（公尺）× 使用空間（使用截面積比率）。\n前項年總營運成本為下列各款費用之總和：\n一  建造費：以五十年為耐用年限，並以平均折舊法計算當年建造費。\n二  管理維護費：指維持共同管道營運管理費用，以申請當年之前三年所\n需費用之平均值計算，如管道新建完成無前三年費用資料時，由管理\n單位依實際情形概估所需費用。\n三  業務費：指辦理共同管道業務費用，其計算方式同前款。\n第 8 條\n第六條第一項之保證金金額，按年使用費之百分之十五計算，並以現金或\n設定質權之銀行定期存單繳納。\n前項保證金於管線事業機關（構）結束使用並拆除所使用之管（纜）線完\n畢，且無應扣抵保證金與待解決事項後，無息退還。\n第 9 條\n管線事業機關（構）應依其管線之特性，於進入共同管道使用前，訂定管\n線專業設置維護規範，提送管理單位核准後始得使用。\n管線專業設置維護規範，應包括下列事項：\n一  管線名稱、設置位置及管徑、規格、數量等說明標示圖表。\n二  管線安全標準。\n三  管線佈設、維修注意事項。\n四  現場防護及緊急事故處理程序。\n五  天然災害或特殊事件發生時之巡視檢查及通報事項。\n六  其他相關事項。\n管線事業機關（構）未依前項規定辦理時，管理單位得不予核發進入使用\n許可。\n第 10 條\n管線事業機關（構）應於管線佈設竣工後六十日內及次年起每年一月三十\n一日前，擬定年度定期安全巡檢計畫，送管理單位備查，並確實依計畫執\n行；計畫變更時，亦同。\n前項定期安全巡檢計畫應載明下列事項，未記載者，管理單位應通知管線\n事業機關（構）限期補正：\n一  管線名稱、設置位置及管徑、規格、數量等說明標示圖表。\n二  巡視檢查人員、職稱及聯絡電話。\n三  巡視檢查管道名稱。\n四  巡視檢查管道區段及檢查時程、頻率。\n五  檢查表報，內容包括檢查項目、標準及方法。\n六  缺失改善及期限或預防矯正措施。\n七  管線資料查核。\n八  異常情形處理方式。\n九  緊急救災機制及全日聯絡方式。\n第 11 條\n幹管內管線每半年至少檢查一次，支管及電纜溝每年至少檢查一次。如有\n水災、風災、震災等天然災害或特殊事件發生，應加強巡視檢查工作，巡\n視檢查結果應報管理單位備查，如有缺失於改善完成後，亦同。\n第 12 條\n管線事業機關（構）應於每次巡檢完成後三十日內，將檢核表及異常情形\n處理結果報請管理單位備查。\n管理單位得定期檢查管線事業機關（構）定期安全巡檢計畫執行情形，必\n要時並得檢閱相關文件。\n第 13 條\n管線事業機關（構）之安全巡檢有下列情形之一者，管理單位得限期命其\n改善，屆期未改善者，得廢止其共同管道之使用許可：\n一  未依規定提送定期安全巡檢計畫備查。\n二  未依定期安全巡檢計畫執行。\n三  定期安全巡檢計畫有缺失。\n第 14 條\n管理單位應管理維護共同管道主體設施；管線事業機關（構）應管理、維\n護其所設置之管線。\n因設置、管理、維護缺失或施工維護作業致生損害第三人者，應依法負賠\n償責任。\n第 15 條\n管線事業機關（構）申請進入或使用共同管道，應於申請進入或使用日期\n前五日，填具申請書或通報單，經管理單位許可後始得進入。但相關技術\n人員或依法執行公務者，因緊急事故進入或使用，不在此限。\n申請進入共同管道施工，應檢附下列文件一式三份：\n一  位置平面圖、斷面圖。\n二  工程進度網狀圖。\n三  施工計畫書（含安全維護及緊急應變計畫）：事業主管機關（構）審\n查核可簽署。\n申請進入共同管道巡檢，應檢附下列文件一式三份：\n一  巡視檢查位置平面圖。\n二  巡視檢查作業人員組織及名冊。\n所送申請書件不齊全，經通知限期補正屆期未補正，應駁回其申請。\n第 16 條\n管線事業機關（構）申請進入共同管道，有下列各款之一者，管理單位得\n不予許可：\n一  無進入共同管道之必要。\n二  進入共同管道有危害共同管道安全之虞。\n三  最近一年內曾有違規紀錄且情節重大。\n四  未繳納管理維護費用。\n第 17 條\n進入共同管道應持管理單位核發之進入許可文件，向監控中心登記，換取\n臨時工作證，並由監控中心人員偵測確認共同管道安全無虞後，會同開啟\n出入口，使用完畢後會同關閉。進出共同管道應確實填寫使用紀錄簿。\n進入共同管道應有三人以上編組，其中至少包括一名組長負責聯繫及一名\n守望員守護出入口。進入共同管道人員，應攜帶無線對講機或專用電話等\n通信設備、穿戴安全服具及配戴臨時工作證，並遵守勞工安全衛生作業規\n定及其他相關規定。\n第 18 條\n進入共同管道內之作業人員，不得有下列行為：\n一  擅入未經許可進入之共同管道區段。\n二  損壞共同管道結構或其附屬設施。\n三  損壞其他管（纜）線或其附屬設施。\n四  吸菸、飲酒或其他危害安全之行為。\n五  妨礙其他管線事業機關（構）之使用。\n六  任意堆放材料、工具、易燃物品或其他妨害共同管道安全或整潔之行\n為。\n第 19 條\n進入共同管道作業完竣後，應清理現場回復原狀、關閉電源及出入口、確\n認共同管道及其內管線安全無虞，並清點人數，經監控中心確認並換回證\n件後，始得離開；作業未完成者，翌日再向監控中心請求開啟出入口進入\n。\n第 20 條\n管線事業機關（構）進入共同管道作業全部完成後，十日內應填報完竣報\n告書，經管線事業機關（構）監工人員、監控中心人員簽章後，連同進入\n使用登錄簽名冊送管理單位備查。\n完竣報告書之內容應包括下列事項：\n一  管線佈設位置平面圖及實際佈設圖說。\n二  施工前、中、後相片。\n三  進入作業前之自動檢查表。\n四  定期巡檢表。\n五  完竣後之安全檢查表。\n六  其他相關附件。\n第 21 條\n共同管道內發生緊急事故，經相關單位通報後，管線事業機關（構）應向\n監控中心登錄，並以電話或傳真向管理單位報備後，立即進入搶修。\n管線事業機關（構）於搶修完畢後，應於七日內提出緊急事故處理書面報\n告送管理單位備查。\n第 22 條\n共同纜溝、共同供給管道之申請使用及管理，準用共同管道之規定。\n第 23 條\n共同管道建設完成後，禁止挖掘共同管道經過之道路。但情形特殊經共同\n管道管理單位及道路管理機關核准同意挖掘時，除應依核准書圖施工外，\n施工完竣後應會同勘查，如有損壞共同管道或相關公共設施時，應負責復\n原。\n第 24 條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL085821","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"公發布日":"民國 106 年 07 月 06 日","法規名稱":"彰化縣共同管道管理辦法","法規體系":"工務類","發文字號":"府法制字第1060222643號"},"promulgation_date":"2017-07-06","revision_date":"2017-07-06","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL085821","status":"unknown","title":"彰化縣共同管道管理辦法","last_checked_at":"2026-10-06T17:26:50+08:00","last_success_at":"2026-10-06T17:26:50+08:00","verification_status":"fetched","content_hash":"4169fa3007c40a9c697b0bace89345089c80c5e5059ec5e36888653aeb4c0f51","history":[{"observed_at":"2026-10-06T17:26:50+08:00","content_hash":"4169fa3007c40a9c697b0bace89345089c80c5e5059ec5e36888653aeb4c0f51","change_kind":"initial","revision_date":"2017-07-06"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"彰化縣政府","category":"建築管理相關","content":"第 1 條\n彰化縣政府（以下簡稱本府）為加強政府直接興建國民住宅社區（以上簡\n稱國宅社區）之管理組織，辦理國宅社區管理維護事項，依國民住宅社區\n管理維護辦法第十一條，訂定本縣國宅社區管理維護辦法（以下簡稱本辦\n法）。\n第 2 條\n本辦法所稱國民住宅社區，係指政府集中興建之國民住宅社區，包括政府\n直接興建之國民住宅及其社區內之公共設施，商業與服務設施暨其他建築\n物。\n第 3 條\n國宅社區住戶交屋進住達總戶數三分之一以上時，本府輔導住戶成立社區\n管理委員會（以下簡稱管委會），未達總戶數三分之一時，本府得輔導住\n戶成立籌備委員會（以下簡稱籌委會），當社區成立管委會時，籌委會同\n時解散。\n管委會有怠忽職權、妨害公益、違反法令情事，本府得令其改選之。\n管委會應於任期屆滿前二個月辦理改選，因故無法於任期屆滿前完成改選\n時，得由原管委會繼續執行會務，並於六個月內積極輔導完成改選。\n第 4 條\n同一社區得分區成立管委會，惟同一使用執照之建築基地，僅能成立一管\n委會。每一分區管委會戶數需二百戶以上，且需位於同一建築基地或二基\n地以上而具有相鄰關係者。\n在原管委會下需另行成立分區管委會時，需先經各該分區三分之二以上所\n有權人連署同意後，函本府查核所有權人之意願，再交原管委會與發起人\n協商，將公共設施（備）維護、水電費分攤比例、維修補助款、管理維護\n費、公共設施（備）收益等如何收取、分配之有關權責確定後，公告社區\n住戶周知（公告期限為七日），無住戶二分之一以上連署異議時，函本府\n核備後，再依規定辦理選舉成立分區管委會。\n原管委會如拒絕與發起人協商，經本府通知雙方協商二次，仍然拒絕協商\n或協商不成立，本府得逕行核准分區管委會之成立，並令原管委會改選之\n；改選完成後，管委會應再協商前項之分配事宜，如仍無法達成協商，則\n由本府依權責加以分配，惟協商已有共識可望成立時，不在此限。\n第 5 條\n管委會委員之推選人及候選人資格：\n管委會置委員五十至二十人，委員任期二年，連選得連任。\n一、須在該社區設有戶籍且有居住事實之國宅承購人，或同一戶籍內之配\n偶、年滿二十歲之直系親屬，每戶以一人為限。\n二、有下列情事之一，不得為管委會委員：\n（一）未設戶籍及未居住本社區國宅承購戶。\n（二）喪失中華民國國籍者。\n（三）褫奪公權尚未復權者。\n（四）受禁治產之宣告尚未撤銷者。\n（五）受破產之宣告尚未回復者。\n（六）限制行為能力或無行為能力人。\n（七）積欠社區管理維護費之住戶。\n（八）不熱衷參與管委會會務，經紀錄有案達六次以上者。\n管委會委員，若發生前項情事之一者，亦當然解任。\n第 6 條\n第一屆管委會由本府輔導住戶選舉產生外，嗣後改選由各管委會自行辦理\n應函本府核備，並應自訂組織章程於本府核備後生效。\n委員出缺時由該選區推選遞補，並函本府核備。\n第 7 條\n管委會應於委員選出函本府核備後十日內公告當選名單，並定期召開委員\n會，由委員以無記名投票方式互選主任委員，主任委員因故出缺改選時亦\n同。\n前項主任委員之選舉及改選，有全體委員過半數之出席，及出席委員過半\n數之同意為當選。選舉結果無人當選時，應即舉行第二次投票，以得票數\n最多者為主任委員當選人，票數相同時以抽籤決定。\n主任委員就任滿六個月後，得經三分之一以上委員連署同意罷免，並將連\n署書函本府召開臨時委員會議，經全體委員三分之二之出席，出席委員三\n分之二以上同意罷免之。\n第 8 條\n管委會置委員，一人為主任委員、一至三人為副主任委員，一人為財務委\n員，並得分組處理會務：\n一、主任委員，綜合會務，召開管委會並擔任主席，遴選副主任委員、財\n務委員提管委會同意。\n二、副主任委員，協助主委策劃會務及年度計劃方案、經費動支監核事宜\n。\n三、財務委員，辦理財務收支，各項經費登記、保管及其收支計畫之擬定\n。\n四、委員為無給職，提議、監督管委會各項工作。\n五、得設總幹事、行政助理等職務襄助會務，由主任委員遴選，經提管委\n會同意後聘任。\n六、主任委員、副主任委員、財務委員及委員改選任時應予公告，解任時\n，亦同。\n第 9 條\n管委會會議之召開事宜：\n一、委員會議每個月召開一次，由主任委員召集主持，必要時並得召集臨\n時會議，主任委員因故不能召集或出席時，得由副主任委員代理之。\n二、委員會之決議，除另有規定外，全體委員應有過半數之出席始得開會\n，出席委員過半數之同意始得議決，如表決人數相同時，取決於主席\n。\n三、委員會議召開時得邀請主管機關派員列席指導，並得邀請社區內村里\n長、轄區派出所主管及社區發展組織之理事主席列席。\n四、委員會議紀錄，於會後一週內函本府備查。\n第 10 條\n管委會經授權應辦理下列事務：\n一、國宅社區公用部分及公共設施（備）之檢修、維護事項。\n前項包括住宅之外牆、屋頂、水塔、蓄水池、自來水塔、廢污水管、\n污水處理操作、瓦斯管、化糞池、電力系統、照明設備、垃圾管道及\n電梯、抽水馬達、發電機、消防設備、公用電視天線及其他公共設施\n之檢修維護及清潔。\n二、國宅社區公共空間及四周環境之美化、清潔、維護事項。\n前項包括住宅之屋頂、樓（電）梯間、走廊、地下室、停車場之清潔\n維護及社區亭園花草、樹木之定期檢修及日常澆水、施肥、除草等工\n作。\n三、國宅社區地下室、停車場及專用污水處理場之營運事項。\n四、管理維護費用之訂定、收取、保管及運用事項。\n五、管委會改選、主任委員、副主任委員、委員補選之選舉事項。\n六、有關國宅社區公共安全與秩序之宣導事項。\n七、推動守望相助、敦親睦鄰及辦理社區文康休閒等公益事項。\n八、其他經主管機關臨時委辦事項。\n第 11 條\n國宅社區住戶積欠管理維護費或公共基金逾三個月未繳納者，管委會應催\n告住戶限期繳納，經管委會催告仍不給付者，管委會得訴請法院命其給付\n應繳之金額及遲延利息。\n第 12 條\n管委會為維護社區公共安全及秩序，得派員經常巡視社區內之環境，對下\n列行為勸導改善或向各業務主管機關依法舉發：\n一、國宅社區內違章建築、違規使用或占用公共設施（備）、場所之行為\n。\n二、國宅社區內任意停放車輛之行為。\n三、非法流動攤販進入之營業行為。\n四、任意懸掛、張貼廣告物。\n五、任意放流污水、廢氣或棄置垃圾之行為。\n六、其他違反社區共同約定事項。\n第 13 條\n管委會之經費來源：\n一、社區住戶繳納管理維護費收入。\n二、公共設施及服務設施收益款及其存款孳息收入。\n三、國民住宅主管機關補助款。\n四、其他收入。\n第 14 條\n管委會經費用途：\n一、國宅社區環境清潔維護費用及清潔人員之薪資。\n二、國宅社區安全設備及管理維護設備之維護修理費用。\n三、國宅社區公共使用之水、電等費用。\n四、其他專供國宅社區使用之費用。\n第 15 條\n管委會之決議、年度計畫、用人計畫及經費收支計畫等之擬定：\n一、每年十月十五日前應將次一會計年度之工作計畫、用人計畫及經費收\n支計畫，函請本府備查後向社區住戶公告。\n二、僱用人員應依用人計畫辦理。\n三、執行社區年度計畫、用人計畫及收支計畫使用管理維護工作所需經費\n，由住戶繳交之管理維護費、及社區公共及服務設施收益，經委員會\n開會決議通過後動支。\n四、各項經費收支需經管委會決議後始得動支，應將動支之經費按月結算\n，向住戶公告周知，並函本府備查。\n五、管委會所做之決議如影響社區住戶權益時，需於決議執行前先予公告\n，自公告日起七日內，如無住戶總戶數三分之一以上連署異議時，方\n可依決議執行。\n管委會委員違反前項規定，致管委會受有損害時，參與決議之委員，負損\n害賠償之責；但經表示反對之委員，有紀錄或書面聲明可證者，免其責任\n。\n第 16 條\n主任委員應將管委會組織章程、委員會會議紀錄及管委會保管之文卷、財\n產清冊等簿冊，備置於管委會辦公場所。\n前項相關簿冊、於各屆管委會依法改選後，併同應移交之財產移交予新當\n選之主任委員。\n第 17 條\n管委會應接受有關單位檢查財務狀況，查核簿冊文件，並得提出報告，不\n得以任何理由推諉拒絕，如財務運用涉有不法情事者，應移送法辦。\n第 18 條\n為執行國宅社區管理維護事項，得以各社區管理維護基金購置社區管理服\n務站（以下簡稱管理站），管理站視業務實際需要設置助理管理人員、維\n護人員或清潔人員。\n當國宅社區成立管理組織、管理、維修及清潔人員之僱用，則由該管委會\n自行聘僱支薪。\n第 19 條\n社區管理服務站應辦理下列業務：\n一、國民住宅社區管理及維護業務之規劃。\n二、國民住宅社區管理組織之輔導及管理。\n三、國民住宅建築物及住戶資料之建立、保管、彙轉。\n四、違規攤販廣告物或違章或占用公共設施之查報處理。\n五、國民住宅住戶進住查訪情形。\n六、協助國民住宅社區管理組織，辦理國宅社區公用部分及公共設施（備\n）之檢修、維護事項。\n七、其他經主管機關臨時交辦事項。\n第 20 條\n管委會圖記之規格，由本府統一參照印信條例有關規定製作發給。\n第 21 條\n本辦法如有未盡事宜，得修正或補充並依其他相關法令辦理。\n第 22 條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL048809","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"公發布日":"民國 88 年 09 月 09 日","法規名稱":"彰化縣國民住宅社區管理維護辦法","法規體系":"工務類","發文字號":"（88）彰府秘法字第170883號"},"promulgation_date":"1999-09-09","revision_date":"1999-09-09","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL048809","status":"unknown","title":"彰化縣國民住宅社區管理維護辦法","last_checked_at":"2026-10-06T17:26:53+08:00","last_success_at":"2026-10-06T17:26:53+08:00","verification_status":"fetched","content_hash":"985b53d50b9416f4ab2421f6cd850802b88245fc6d3f1f936bc9ba8ee7d24381","history":[{"observed_at":"2026-10-06T17:26:53+08:00","content_hash":"985b53d50b9416f4ab2421f6cd850802b88245fc6d3f1f936bc9ba8ee7d24381","change_kind":"initial","revision_date":"1999-09-09"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"彰化縣政府","category":"建築管理相關","content":"第 1 條\n本辦法依國民住宅條例第十八條之一第二項規定訂定之。\n第 2 條\n本辦法之主管機關為彰化縣政府（以下簡稱本府）。\n第 3 條\n彰化縣國民住宅管理維護基金（以下簡稱管理維護基金）提撥作為縣內政\n府直接興建國民住宅社區（以下簡稱社區）公共基金之金額，以已撥入基\n金專戶之內政部營建署核撥該社區之國民住宅售價百分之二．五提撥款餘\n額，扣除已提撥款價購房舍後之結餘款及其存款孳息計列。\n第 4 條\n各社區依公寓大廈管理條例成立管理委員會或推選管理負責人，經向公寓\n大廈主管機關報備，並完成下列事項後，應由管理委員會或管理負責人檢\n附報備證明、領據、專戶存摺影本、概括承受同意書、住戶規約等相關文\n件，向本府以書面申請核撥其社區之管理維護基金：\n一、社區係成立管理委員會者，應以管理委員會名義會同主任委員、財務\n委員或監察委員完成開設銀行或郵局專戶。\n二、以管理委員會或管理負責人名義出具概括承受前社區管理委員會權利\n義務之證明文件。\n第 5 條\n各社區有下列各款情形之一者，應於處理完成後，始得申請核撥管理維護\n基金：\n一、社區內屬本縣市所有之管理站由管理委員會使用者，管理委員會應與\n本府協商訂定租賃契約或騰空交還之。\n二、住商混合之社區，區分所有權人會議應於其住戶規約訂定其社區內辦\n公、商場未依法令單獨成立管理委員會前，應依辦公、商場面積占全\n社區比例，保障辦公、商場選任管理委員會之委員名額。\n第 6 條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL041174","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"公發布日":"民國 95 年 09 月 08 日","法規名稱":"彰化縣國民住宅管理維護基金作為公寓大廈公共基金提撥辦法","法規體系":"工務類","發文字號":"府法制字第0950176263號"},"promulgation_date":"2006-09-08","revision_date":"2006-09-08","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL041174","status":"unknown","title":"彰化縣國民住宅管理維護基金作為公寓大廈公共基金提撥辦法","last_checked_at":"2026-10-06T17:26:52+08:00","last_success_at":"2026-10-06T17:26:52+08:00","verification_status":"fetched","content_hash":"0529f0e0797917e437ba2505ce90f878408f078ccf4b313019d0662eca42f584","history":[{"observed_at":"2026-10-06T17:26:52+08:00","content_hash":"0529f0e0797917e437ba2505ce90f878408f078ccf4b313019d0662eca42f584","change_kind":"initial","revision_date":"2006-09-08"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"(精簡)彰化縣城鄉發展建設基金收支保管及運用辦法.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=2867&id=FL041363&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"第 1 條\n為推動彰化縣（以下簡稱本縣）各城鄉地區之建設與發展及建築物無障礙\n設備與設施改善計畫，特設置彰化縣城鄉發展建設基金（以下簡稱本基金\n），並依預算法第九十六條第二項準用同法第二十一條規定訂定本辦法。\n第 2 條\n本基金之收支保管及運用，除法令另有規定外，依本辦法之規定辦理。\n第 3 條\n本基金供執行城鄉發展建設計畫及建築物無障礙設備與設施改善計畫之用\n，分別於本縣代理公庫機構設立專戶存管，並專款專用。\n第 3 條之 1\n本基金關於建築物無障礙設備與設施改善計畫之管理及運用方式，依建築\n物無障礙設備與設施改善基金收支保管及運用辦法第七條至第十一條規定\n。\n第 4 條\n本基金為預算法第四條第一項第二款第五目規定之特別收入基金，編製附\n屬單位預算，以彰化縣政府（以下簡稱本府）為主管機關，本府建設處為\n管理單位。\n第 5 條\n城鄉發展建設計畫之基金來源如下：\n一  依區域計畫法第十五條之三規定所收取之開發影響費或可建築土地及\n樓地板面積之出售收入。\n二  依都市計畫法第二十七條之一規定，由土地權利關係人所捐贈之回饋\n金或可建築土地及樓地板面積之出售收入。\n三  依都市計畫書規定所收取之開發許可回饋金或可建築土地及樓地板面\n積之出售收入。\n四  辦理區域及都市計畫容積獎勵所受之回饋金、回饋土地及回饋樓地板\n面積出售所得之收入。\n五  辦理都市更新地區重建、整建完成後讓售、標售或出租房地之收入。\n六  由政府循預算程序之撥款。\n七  金融機構或其他特種基金融資收入。\n八  本條計畫運用及孳息收入。\n九  其他有關收入。\n第 6 條\n城鄉發展建設計畫之基金用途如下：\n一  支應本縣各區域及都市計畫範圍內公共設施之建設及維護。\n二  辦理區域及都市計畫、都市設計、都市更新地區重建整建維護及都市\n工程等相關之調查測量、研究規劃、設計及其他作業等必要之費用。\n三  辦理都市發展相關之研究及活動費用。\n四  支應融資還本及付息。\n五  支應其他與本條計畫業務有關之費用。\n第 7 條\n建築物無障礙設備與設施改善計畫之基金來源如下：\n一  依身心障礙者權益保障法第八十八條第一項所處之罰鍰收入。\n二  本條計畫運用及孳息收入。\n三  其他有關收入。\n第 8 條\n建築物無障礙設備與設施改善計畫之基金用途如下：\n一  辦理建築物無障礙設備與設施改善，並優先使用於私有建築物改善。\n二  推廣建築物無障礙設備與設施之教育宣導及相關獎勵。\n三  推動建築物無障礙設備與設施之研究發展。\n四  辦理建築物無障礙設備與設施之管理。\n五  支應其他建築物無障礙設備與設施之相關費用。\n第 9 條\n本基金對本府各單位及所屬機關、鄉（鎮、市）公所補助，應由本府各單\n位及所屬機關、鄉（鎮、市）公所提出補助計畫書送交本府審核後，視財\n源狀況酌予補助。\n審核作業要點由本府另定之。\n第 10 條\n本基金關於城鄉發展建設計畫，應設彰化縣城鄉發展建設基金管理委員會\n(以下簡稱城鄉基金管委會)，置委員七人至十一人，其中一人為主任委員\n，由縣長兼任；一人為副主任委員，由主任委員指定委員兼任；其餘委員\n，由本府相關機關(單位)主管兼任。\n第 11 條\n城鄉基金管委會視執行情形必要時由主任委員召集會議；主任委員因故不能出席時，由副主任委員或委員互推一人代理之。本會之會議應有全體委員過半數之出席始得開會，應有出席委員過半數之同意始得決議。委員應親自出席會議。但由機關代表兼任之委員，除主任委員及副主任委員外，如因故不能親自出席時，得指派相當層級之代表出席。\n第 12 條\n城鄉基金管委會之任務如下：\n一  城鄉發展建設計畫基金收支、保管及運用之審議。\n二  城鄉發展建設計畫基金年度預算及決算之審議。\n三  城鄉發展建設計畫基金運用執行情形之考核。\n四  其他有關事項。\n第 13 條\n城鄉基金管委會委員及派兼人員均為無給職。\n第 14 條\n本基金之保管及運用應注重收益性及安全性，其存儲應依彰化縣縣庫事務\n處理自治條例及相關法令規定辦理。\n第 15 條\n本基金有關預算編製與執行及決算編造，應依預算法、會計法、決算法、\n審計法及相關法令規定辦理。\n第 16 條\n本基金結束時，應予結算，其餘存權益應解繳縣庫。\n第 17 條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL041363","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"修正日期":"民國 111 年 09 月 08 日","全文檔案":"(精簡)彰化縣城鄉發展建設基金收支保管及運用辦法.pdf","公發布日":"民國 94 年 03 月 22 日","法規名稱":"彰化縣城鄉發展建設基金收支保管及運用辦法","法規體系":"建設類","發文字號":"府法制字第1110345232號"},"promulgation_date":"2005-03-22","revision_date":"2022-09-08","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL041363","status":"unknown","title":"彰化縣城鄉發展建設基金收支保管及運用辦法","last_checked_at":"2026-10-06T17:26:38+08:00","last_success_at":"2026-10-06T17:26:38+08:00","verification_status":"fetched","content_hash":"c0c8e29c420e6ab2176c6a1e6b01594ac677dd01f3cc8309aca34a14aa1d4ee8","history":[{"observed_at":"2026-10-06T17:26:38+08:00","content_hash":"c0c8e29c420e6ab2176c6a1e6b01594ac677dd01f3cc8309aca34a14aa1d4ee8","change_kind":"initial","revision_date":"2022-09-08"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=2867&id=FL041363&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"九十八年十二月二日彰化縣政府府法制字第0980291316號令訂定發布全文7條.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=3561&id=FL051465&type=LAW"},{"name":"一百十四年五月八日彰化縣政府府行法字第1140175979號令修正發布第2條、第4條至第6條.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=3562&id=FL051465&type=LAW"},{"name":"附表-彰化縣執行違反都市計畫土地使用分區管制案件裁處基準表.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=3563&id=FL051465&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"第 1 條\n為落實都市計畫土地使用分區管制，維護居住生活品質及公共安全，依都\n市計畫法第七十九條規定訂定本辦法。\n第 2 條\n本辦法所稱違反都市計畫土地使用分區管制之行為(以下簡稱違反案件)，\n係指於都市計畫範圍內土地或建築物之使用，或從事建造、採取土石、變\n更地形，違反都市計畫法或內政部、彰化縣政府依都市計畫法所發布之命\n令者。\n第 3 條\n裁處機關為違反案件所在地之都市計畫擬定機關。\n第 4 條\n經民眾檢舉或相關單位舉發疑似違反案件，經裁處機關查證屬實者，依本\n辦法第五條規定裁處。\n裁處機關於裁處前，應給予裁處相對人十四日陳述意見之機會。\n第 5 條\n違反案件裁處基準如附表。\n第 6 條\n違反案件裁處後，如經相關目的事業主管機關認可得輔導其合法化使用，\n或改善期間受天候及不可抗力之天然災害影響者，得於裁處書所定改善期\n限屆滿前申請展延，展延以一次為限，期限最長為三個月。\n前項如涉及都市計畫變更者，應於改善期間申請辦理變更都市計畫，該變\n更都市計畫案審議期間，其展延期限依第三項規定辦理。\n前項變更都市計畫案審議未通過者，應自都市計畫委員會會議紀錄發文日\n起一個月內拆除、改建、停止使用或恢復原狀，未依期限拆除、改建、停\n止使用或恢復原狀者，依本辦法第五條規定辦理。\n第 7 條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL051465","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"修正日期":"民國 114 年 05 月 08 日","公發布日":"民國 98 年 12 月 02 日","圖表附件":"附表-彰化縣執行違反都市計畫土地使用分區管制案件裁處基準表.pdf","法規名稱":"彰化縣執行違反都市計畫土地使用分區管制裁處辦法","法規體系":"建設類","發文字號":"府行法字第1140175979號","立法理由":"九十八年十二月二日彰化縣政府府法制字第0980291316號令訂定發布全文7條.pdf 一百十四年五月八日彰化縣政府府行法字第1140175979號令修正發布第2條、第4條至第6條.pdf"},"promulgation_date":"2009-12-02","revision_date":"2025-05-08","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL051465","status":"unknown","title":"彰化縣執行違反都市計畫土地使用分區管制裁處辦法","last_checked_at":"2026-10-06T17:26:37+08:00","last_success_at":"2026-10-06T17:26:37+08:00","verification_status":"fetched","content_hash":"0f04f2e86206da2a971e82b0a88f35dede86eaa44df0dce9b817a9e4efc70c7e","history":[{"observed_at":"2026-10-06T17:26:37+08:00","content_hash":"0f04f2e86206da2a971e82b0a88f35dede86eaa44df0dce9b817a9e4efc70c7e","change_kind":"initial","revision_date":"2025-05-08"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=3561&id=FL051465&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=3562&id=FL051465&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=3563&id=FL051465&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"彰化縣政府","category":"建築管理相關","content":"一、為加速公共設施保留地取得，並維護都市景觀及開發之合理公平性，特成立彰化縣容積移轉繳納代金專戶（以下簡稱本專戶），訂定本作業要點。\n二、本基金之收支保管及運用，除法令另有規定外，依本辦法之規定辦理。\n三、本專戶之來源如下：\n(一)依彰化縣都市計畫容積移轉審查許可及作業要點第七點規定，以折繳代金方式辦理容積移轉之收入。\n(二)由政府循預算程序之撥款。\n(三)金融機構或其他特種基金融資收入。\n(四)本專戶運用及孳息收入。\n(五)其他有關收入。\n四、本專戶之用途如下：\n(一)都市計畫範圍內公共設施保留地之建設、徵收、支出及維護費用。\n(二)融資還本及付息支出。\n(三)其他與本基金業務有關之費用。\n五、彰化縣政府（以下簡稱本府）各用地機關動用本專戶，應向本府提出申請。\n六、本專戶預算之編製、執行、決算之編造及會計事務之處理程序，依預算法、會計法、決算法、審計法、公庫法及相關法令規定辦理。\n七、本專戶應於本縣代理公庫機構設立專戶存管，並應專款專用，以代收代付方式辦理。\n八、本專戶之保管及運用應注重收益性及安全性，其存儲應依彰化縣縣庫事務處理自治條例及相關法令規定辦理。\n九、本專戶結束時，應予結算，餘存權益應解繳縣庫。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:GL000430","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"公發布日":"民國 105 年 12 月 14 日","法規名稱":"彰化縣容積移轉繳納代金及管理使用作業要點","法規體系":"建設類","發文字號":"府建管字第1050434356號函"},"promulgation_date":"2016-12-14","revision_date":"2016-12-14","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=GL000430","status":"unknown","title":"彰化縣容積移轉繳納代金及管理使用作業要點","last_checked_at":"2026-10-06T17:26:33+08:00","last_success_at":"2026-10-06T17:26:33+08:00","verification_status":"fetched","content_hash":"45a34b31bff4cb386c5f398b8767cd2214909d01c383ddceefc8d6deceab47ca","history":[{"observed_at":"2026-10-06T17:26:33+08:00","content_hash":"45a34b31bff4cb386c5f398b8767cd2214909d01c383ddceefc8d6deceab47ca","change_kind":"initial","revision_date":"2016-12-14"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"彰化縣政府","category":"建築管理相關","content":"第 1 條\n本辦法依彰化縣寬頻管道維護管理自治條例（以下簡稱本自治條例）第十\n八條訂定之。\n第 2 條\n依本自治條例所收取租金（以下簡稱租金），應分配百分之三十予彰化縣\n政府（以下簡稱本府），百分之七十予租用管道所在地之鄉（鎮、市）公\n所（以下簡稱公所）。\n第 3 條\n公所攤還本府代公所墊支配合款前，應將前條公所應分配比例之百分之五\n十優先攤還本府已支出之配合款。\n第 4 條\n公所於租賃契約報本府備查時，應將分配本府之租金及應攤還款項一併繳\n至本府。\n第 5 條\n依本自治條例收取之租金，扣除公所攤還配合款後，至少應有百分之五十\n使用於寬頻管道之維護管理或新建工程，其餘款項繳交公庫或使用於市區\n道路之維護、新建及管理。\n依本辦法攤還本府及本府收取之租金不在此限。\n第 6 條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL062056","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"公發布日":"民國 100 年 07 月 08 日","法規名稱":"彰化縣寬頻管道租金管理及運用辦法","法規體系":"工務類","發文字號":"府法制字第1000230068號"},"promulgation_date":"2011-07-08","revision_date":"2011-07-08","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL062056","status":"unknown","title":"彰化縣寬頻管道租金管理及運用辦法","last_checked_at":"2026-10-06T17:26:52+08:00","last_success_at":"2026-10-06T17:26:52+08:00","verification_status":"fetched","content_hash":"a569eb2326c808a6b85f20a5b121b2ba2898b9055e2c9656e37a0b8cfce151d1","history":[{"observed_at":"2026-10-06T17:26:52+08:00","content_hash":"a569eb2326c808a6b85f20a5b121b2ba2898b9055e2c9656e37a0b8cfce151d1","change_kind":"initial","revision_date":"2011-07-08"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"彰化縣政府","category":"建築管理相關","content":"第 1 條\n彰化縣政府（以下簡稱本府）為加速彰化縣（以下簡稱本縣）寬頻管道建\n設、提升通訊品質及國際競爭力、統合市區道路公共設施管線配置、加強\n道路管理、維護交通安全及市容觀瞻，有效維護管理寬頻管道，特制定本\n自治條例。\n第 2 條\n本自治條例用詞定義如下：\n一、寬頻管道：指用於容納固定通信（含綜合網路、室內網路、長途網路\n、國際網路、國際海纜電路出租）、行動通信（含數位式低功率無線\n電話、行動電話、第三代行動通信、無線寬頻接取）、有線廣播電視\n系統（含有線播送系統）、路燈、號誌或其他經政府核准之纜線及其\n接續設施之構造物。\n二、纜線業者（以下簡稱業者）：指使用道路埋設公用纜線之固定通信、\n行動通信、有線廣播電視系統及其他經政府專案核定者。\n第 3 條\n本自治條例所稱寬頻管道主管機關（以下簡稱主管機關）為本府，所稱寬\n頻管道管理機關（以下簡稱管理機關）為本縣各鄉（鎮、市）公所。\n第 4 條\n主管機關辦理下列事項：\n一、寬頻管道發展政策、方案之訂定。\n二、鄉（鎮、市）寬頻管道計畫之核定。\n三、鄉（鎮、市）寬頻管道建設、管理與維護之督導。\n四、跨越鄉（鎮、市）寬頻管道規劃、建設、管理及維護之協調。\n五、其他經主管機關核定之事項。\n第 5 條\n管理機關辦理下列事項：\n一、鄉（鎮、市）寬頻管道計畫之規劃。\n二、鄉（鎮、市）寬頻管道之建設、管理與維護。\n三、其他有關鄉（鎮、市）寬頻管道事宜。\n第 6 條\n寬頻管道建設完成後，除原已施設管道之纜線業者因緊急搶修或其他特殊\n情形經管理機關核准外，禁止業者在寬頻管道經過之道路為新增管道進行\n道路挖掘、埋設管線或採雨水下水道、電力、電信、路燈、交通號誌等電\n桿架空附掛纜線，但纜線需連接使用由寬頻管道引上或需跨越道路等有附\n掛需要者不在此限，違者由管理機關依第十五條規定予以剪除。\n第 7 條\n申請案件由管理機關審查合格後，送主管機關報備，始由管理機關核准。\n業者申請租用寬頻管道案件，經管理機關於報備後應通知業者限期簽訂租\n賃契約、繳納使用租金及保證金，未依期限簽訂租賃契約者，視同棄權。\n管理機關完成前項租賃契約訂定後，應將租賃契約副本壹份送主管機關備\n查。\n第 8 條\n業者申請租用寬頻管道，應填具下列文件向管理機關提出申請：\n一、申請書。\n二、國家通訊傳播委員會（NCC） 核發之固定通信、行動通信、有線廣播\n電視系統等業務之籌設同意或網路（系統）建設許可或營運許可證之\n影本壹份（影本應加蓋公司大小章及與正本相符樣章）。\n三、佈設路線圖及使用寬頻管道位置圖，並應標註佈設長度及租用管數。\n四、平面圖、斷面圖、接戶引上管（引進管）及設施物設置詳圖等相關之\n施工圖說。\n五、巡檢及維護計畫。\n六、管理機關指定之其他文件。\n警政署、國防部或本府及所屬機關需租用寬頻管道者，免檢附前項第二款\n文件。\n第 9 條\n寬頻管道租賃應依下列規定：\n一、租用寬頻管道時以子管一管為單位，每一業者以租用四管子管為限。\n但租用管道大於四管子管者，應另案提出申請，並經管理機關審查核\n准。\n二、申請租用經審查合格後，未經管理機關同意，不得將租賃契約之權利\n轉讓、分租或轉租於他人。\n三、經同意舖設之纜線，應清楚標示業者名稱及證照字號。\n四、申請佈纜業者，應於訂約後一個月內開工，於核准施設期限內完工。\n第 10 條\n使用寬頻管道舖設纜線不得影響其他業者之纜線，必要時管理機關得通知\n業者立即改善。\n第 11 條\n除警政署、國防部或本府及所屬機關及情形特殊經管理機關核准者外，租\n用寬頻管道佈設相關纜線應於簽約或續租時，繳納下列費用：\n一、租金：寬頻管道每子管每公尺每一個月租金為新臺幣二元，不足一個\n月以一個月計算。\n二、保證金：依租賃契約租金總價百分之十計算。\n租金得分年繳納，並於契約簽訂時需繳清至第一年年底租金及全額保證金\n。\n業者得於契約生效日之次年起，每年申請無息退還其已使用年期之保證金\n，於契約屆滿後三十日內，申請無息退還餘款。\n主管機關得視物價或管道營運情形、管道維護狀況或其他因素調整租金費\n率。\n第 12 條\n寬頻管道租賃契約以簽約日起至當年之年底為第一期。第二年起，以一年\n為一期，每次租用至少一期以上。\n業者續租時，應於租約期滿前二個月內檢具第八條之文件向管理機關提出\n申請。\n申請續約，未獲核准者，管理機關應通知業者限期拆除。\n第 13 條\n租用期間若因管理機關需要，得於一個月前通知業者配合辦理纜線拆遷作\n業。但遇突發事故需緊急處理者，得隨時通知業者立即配合拆遷。未能配\n合遷移，管理機關得派員逕予剪除，所有損失由業者自行負責，業者不得\n異議或要求補償。\n纜線依前項規定拆遷，管理機關如無法再提供舖設或業\n者不欲繼續租用時，應按比例無息退還未到期之租金及保證金。\n第 14 條\n進入（開啟人、手孔）或使用寬頻管道，應填具申請書表及檢附相關文件\n，送管理機關核准後始得進入。如遇緊急事故，得以書面或口頭通知管理\n機關後先行進入（開啟人、手孔），惟應於進入（開啟人、手孔）後三日\n內檢附佐證及完工資料報請管理機關備查。\n第 15 條\n有下列情形之一者，視為違規使用：\n一、未經管理機關書面同意而擅自進入（開啟人、手孔）或使用寬頻管道\n者。\n二、於寬頻管道舖設纜線及相關器材以外之任何物品者。但經管理機關專\n案同意者不在此限。\n三、未完成簽訂租賃契約或租賃契約已失其效力者。\n四、舖設纜線有損管道結構或市容觀瞻者。\n五、違反第六條規定者。\n六、違反第九條規定者。\n前項違規者，管理機關得通知業者限期改善，逾期未改善者，管理機關得\n逕行僱工剪除，所支出費用由違規業者負擔，並得由未退還之未到期租金\n及保證金中扣抵。核准舖設期間，未經申請而自行拆除舖設者，其已繳租\n金及保證金不予發還。\n第 16 條\n為維護管理寬頻管道、附屬設施物及檢視管道內使用情形，業者應定期實\n施檢視維護（天然災害等特殊事件發生時應加強巡檢工作），並於次月內\n將已實施之檢視維護紀錄及下次檢視維護時程表報請管理機關核備。\n管理機關得隨時派員抽查或會同有關單位與業者抽驗查證。\n業者對所佈設纜線及設施應負維護管理之責任。如有損壞，不得向管理機\n關或主管機關求償。\n管理機關每年應全面巡視查檢管道、手孔及附屬設施壹次以上。\n第 17 條\n業者於使用寬頻管道時因纜線施工或維護不良，致發生破壞或災害事故，\n業者應負擔全部賠償責任。\n第 18 條\n依本自治條例所收取之租金之管理及運用辦法，由本府另定之。\n第 19 條\n本自治條例所需申請之書表格式，由本府另定之。\n第 20 條\n本自治條例未規定事項依其他相關法令之規定辦理。\n第 21 條\n本自治條例自公布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL048808","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"修正日期":"民國 114 年 01 月 20 日","公發布日":"民國 97 年 09 月 19 日","法規名稱":"彰化縣寬頻管道維護管理自治條例","法規體系":"工務類","發文字號":"府行法字第1140019620號"},"promulgation_date":"2008-09-19","revision_date":"2025-01-20","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL048808","status":"unknown","title":"彰化縣寬頻管道維護管理自治條例","last_checked_at":"2026-10-06T17:26:49+08:00","last_success_at":"2026-10-06T17:26:49+08:00","verification_status":"fetched","content_hash":"f398a5e835a4aca0a9ea6be4578d3446248a9bc47694c6a1d3e1ef3f4a6e1cd9","history":[{"observed_at":"2026-10-06T17:26:49+08:00","content_hash":"f398a5e835a4aca0a9ea6be4578d3446248a9bc47694c6a1d3e1ef3f4a6e1cd9","change_kind":"initial","revision_date":"2025-01-20"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"附圖一.PDF","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=155&id=FL087950&type=LAW"},{"name":"附圖二.PDF","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=156&id=FL087950&type=LAW"},{"name":"附圖三.PDF","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=157&id=FL087950&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"一、本原則依建築技術規則設計施工編第 263  條第 2  項規定訂定之。\n二、山坡地建築基地與指定建築線之道路成上、下邊坡時，得免退縮一點\n五公尺人行步道。（附圖一）\n圖表附件：\n附圖一.PDF\n三、山坡地建築基地深度扣除一點五公尺後未符合彰化縣畸零地使用自治\n條例所規定之建築基地最小深度時，得免退縮一點五公尺人行步道。\n（附圖二）\n圖表附件：\n附圖二.PDF\n四、山坡地建築基地經彰化縣政府加強山坡地雜項執照審查及施工查驗審\n查小組審查認定免退縮人行步道者，得免退縮一點五公尺人行步道。\n五、山坡地建築基地鄰接二條以上道路時，得選擇一面免退縮一點五公尺\n人行步道，其餘應依規定留設人行步道。（附圖三）\n圖表附件：\n附圖三.PDF\n六、原有合法建築物之增建、修建，無涉及整地者，得免退縮一點五公尺\n人行步道。\n七、山坡地建築基地已依其他規定設置人行步道且大於一點五公尺者，得\n免再退縮留設。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL087950","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"公發布日":"民國 104 年 10 月 29 日","法規名稱":"彰化縣山坡地建築基地免予退縮人行步道認定原則","法規體系":"建設類","發文字號":"府建管字第1040365969A號"},"promulgation_date":"2015-10-29","revision_date":"2015-10-29","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL087950","status":"unknown","title":"彰化縣山坡地建築基地免予退縮人行步道認定原則","last_checked_at":"2026-10-06T17:26:30+08:00","last_success_at":"2026-10-06T17:26:30+08:00","verification_status":"fetched","content_hash":"4267015f33de29b4588324242025ad4defdc970581507856a7c08d032f79d5d1","history":[{"observed_at":"2026-10-06T17:26:30+08:00","content_hash":"4267015f33de29b4588324242025ad4defdc970581507856a7c08d032f79d5d1","change_kind":"initial","revision_date":"2015-10-29"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=155&id=FL087950&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=156&id=FL087950&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=157&id=FL087950&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"彰化縣市區道路人行道認養契約書（範本）.PDF","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=187&id=FL084844&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"第 1 條\n彰化縣政府（以下簡稱本府）為結合民間力量，運用社會資源，鼓勵人民\n、法人或團體（以下簡稱認養人）認養彰化縣（以下簡稱本縣）轄內市區\n道路人行道，無償維護管理或施築工作，特訂定本辦法。\n第 2 條\n本辦法之主管機關為本府，管理機關為各鄉（鎮、市）公所。\n本辦法所稱之人行道，為市區道路範圍內所規劃供行人行走之地面道路（\n不包括騎樓與走廊）。\n第 3 條\n認養人申請無償認養人行道者，應以書面向管理機關提出，並經管理機關\n會同相關單位審查核准後，訂定認養契約，其契約內容應載明本辦法所規\n定之重要權利義務事項。\n前項認養契約（範本）由主管機關另訂之。\n圖表附件：\n彰化縣市區道路人行道認養契約書（範本）.PDF\n第 4 條\n認養人申請自費變更人行道路型、鋪面材質及既有附屬設施者，應檢附下\n列相關圖說資料，送請管理機關審查同意後，始得為之。\n一  認養範圍及現況圖：\n（一）現有人行道鋪面、植栽、燈具及其他附屬設施位置。\n（二）認養人行道範圍四周相關現況建物空間或設施。\n二  認養範圍規劃設計圖說：\n（一）人行道路型設計。\n（二）喬木、灌木、花槽植栽之位置、種類及樹徑。\n（三）燈具型式、數量、設置位置及供電維護計畫。\n（四）人行道鋪面材質、拼貼方式、鋪面大樣圖。\n（五）座椅、候車亭等街道家具設置位置、設計圖說。\n（六）無障礙設施及動線規劃。\n自費變更人行道鋪面材質應以澀面防滑材料為之，並應預留必要之備料以\n供日後維修。植栽、燈具、街道家具及附屬設施應依核准計畫圖說施作，\n並於完工後報請管理機關核備。\n認養之人行道及自費變更之設施，於認養契約期滿或終止認養時，應保持\n現狀，無條件點交返還管理機關，不得要求任何補償。\n第 5 條\n認養人應善盡維護管理責任，並應遵守下列事項：\n一  人行道之清潔。\n二  人行道鋪面有鬆動、破損者，認養人應先行設置安全警示設施，並即\n通知管理機關派員處理；其係認養人行為所致者，應由認養人處理。\n三  人行道上，發現有影響市容觀瞻之設施或破壞之行為者，應即通知管\n理機關協調相關權責單位處理。\n四  經核准由認養人施作之街道家具及附屬設施等，應保持清潔、堪用；\n其有損壞者，應即修繕。\n五  行道樹之維護管理，認養人應依彰化縣樹木保育自治條例為之，其他\n經核准設置之花木植栽等，認養人應負責修剪、施肥、灑水及清潔工\n作。\n六  認養契約指定之其他事項。\n第 6 條\n認養人應置專人辦理認養契約所定之各項工作，並將管理人員之姓名、地\n址及連絡電話等資料報請管理機關備查。管理人員變更時，應立即通知管\n理機關。\n第 7 條\n認養人得設置認養標誌牌一處，標誌牌之規格以四十五公分乘七十五公分\n為限，牌內得標示認養人（含共同認養人及標章）、認養位置及範圍、管\n理人連絡電話，如有其他內容須經管理機關同意後，始可設置。\n認養標誌牌之設置方式及顏色應與週邊景觀協調，並應設置於不妨礙行人\n通行及公共安全之位置，不得遮蔽或附掛於交通標誌或號誌上。\n前項認養標誌牌應於認養期滿或終止認養契約之日起十日內拆除並回復原\n狀；逾期未拆除者，管理機關得逕行拆除，並視為廢棄物處理。\n第 8 條\n認養期間以三年為一期，認養人得於認養期滿前一個月向管理機關申請繼\n續認養，並依第三條規定辦理。\n第 9 條\n認養人於認養期間違反本辦法相關規定、認養契約或其他相關規定者，管\n理機關得終止認養契約，如涉及相關設施損壞，應予復原，且一年內不得\n再申請認養。\n第 10 條\n認養人於認養期間善盡維護管理責任者，管理機關得依認養面積、範圍或\n認養年數，訂定各類獎項，簽報本府頒予獎狀、感謝狀或獎牌。\n認養人繼續認養六年以上，或其認養範圍達一個街廓者，管理機關得於網\n站上公布或刊於專刊，並得於網站以超連結至該認養人網站。\n第 11 條\n認養人不得將認養契約權利義務之全部或一部讓與他人。\n第 12 條\n認養人非經管理機關核准，不得於認養路段舉辦活動、張貼或樹立廣告物\n、設置攤位、障礙物或作其他妨礙公眾通行之使用；違反者，除依相關規\n定處理外，管理機關並得終止認養契約，且一年內不得再申請認養。\n第 13 條\n管理機關於道路認養期間，依法仍有維護管理道路之權責。如管理機關認\n有必要時，得無條件終止認養契約。終止後，認養人不得請求任何補（賠\n）償或主張任何權利。\n管理機關於認養路段辦理人行道鋪面改善、更新或設置街道家具、燈具、\n植栽更新及相關附屬設施需要時，認養人應予配合。\n第 14 條\n管理機關得視需要就轄區內覓妥適合認養人行道地點並公告徵求人民、法\n人或團體認養。\n第 15 條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL084844","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"公發布日":"民國 105 年 06 月 16 日","法規名稱":"彰化縣市區道路人行道認養辦法","法規體系":"工務類","發文字號":"府法制字第1050198924號"},"promulgation_date":"2016-06-16","revision_date":"2016-06-16","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL084844","status":"unknown","title":"彰化縣市區道路人行道認養辦法","last_checked_at":"2026-10-06T17:26:51+08:00","last_success_at":"2026-10-06T17:26:51+08:00","verification_status":"fetched","content_hash":"11ee3f2789ad9dfa697bba5063a9d4490a2c8d1f78566ae22f42b9f0e96e3d2f","history":[{"observed_at":"2026-10-06T17:26:51+08:00","content_hash":"11ee3f2789ad9dfa697bba5063a9d4490a2c8d1f78566ae22f42b9f0e96e3d2f","change_kind":"initial","revision_date":"2016-06-16"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=187&id=FL084844&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"彰化縣政府","category":"建築管理相關","content":"第 1 條\n本辦法依市區道路條例第二十七條第六項規定訂定之。\n第 2 條\n彰化縣市區道路基金（以下稱本基金）為預算法第四條第一項第二款所規\n定之特種基金，以彰化縣政府（以下簡稱本府）為主管機關，各鄉（鎮、\n市）公所為管理機關。\n第 3 條\n本基金之來源如下：\n一、各管線單位、自然人、法人、團體繳交代辦各類管線（路）埋設及挖\n補工程、瀝青混凝土路面修補、人（手）孔蓋調整（降）等改善工程\n費用。\n二、政府補助及協助收入。\n三、本基金孳息收入。\n四、個人或團體之捐贈收入。\n五、市區道路條例規定收入。\n六、其他有關收入。\n第 4 條\n本基金應由各鄉（鎮、市）公所於公庫代理機構設立彰化縣各鄉（鎮、市\n）道路基金專戶存儲。\n第 5 條\n本基金之用途如下：\n一、代辦各類管線（路）埋設及挖補工程。\n二、代辦各類管線工程柏油路面補修。\n三、道路刨除、翻修、封層工程。\n四、道路路容整修改善及綠美化。\n五、道路人（手）孔蓋升降、標線繪製等交通改善工程。\n六、各項代辦工程之管理費。\n七、辦理道路挖補修復所需設備費、業務費及人事費。\n八、道路及橋樑之調查及檢測補強改善工程。\n九、其他有關道路管理工作或獎勵金。\n第 6 條\n本基金結束時，應予結算並將其餘存權益解繳鄉（鎮、市）庫。\n第 7 條\n本基金預算之編製、執行、決算之編造及會計事務之處理程序，依預算法\n、會計法、決算法、審計法、公庫法及相關法令規定辦理。\n第 8 條\n本基金收支保管及運用，除法令另有規定外，悉依本辦法之規定辦理。\n第 9 條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL073500","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"公發布日":"民國 103 年 04 月 02 日","法規名稱":"彰化縣市區道路基金收支保管及運用辦法","法規體系":"工務類","發文字號":"府法制字第1030099278號"},"promulgation_date":"2014-04-02","revision_date":"2014-04-02","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL073500","status":"unknown","title":"彰化縣市區道路基金收支保管及運用辦法","last_checked_at":"2026-10-06T17:26:51+08:00","last_success_at":"2026-10-06T17:26:51+08:00","verification_status":"fetched","content_hash":"ebb3d165cb7e0030c80304138f88f86a54a607278e952ebb8bc56c75954d0daa","history":[{"observed_at":"2026-10-06T17:26:51+08:00","content_hash":"ebb3d165cb7e0030c80304138f88f86a54a607278e952ebb8bc56c75954d0daa","change_kind":"initial","revision_date":"2014-04-02"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"彰化縣政府","category":"建築管理相關","content":"第 一 章 總則\n第 1 條\n本規則依市區道路條例第三十二條規定訂定之。\n第 2 條\n本規則用詞之定義如下：\n一　市區道路：係指本縣各都市計畫區域（含各種特定區）內所有道路。\n二　路基：係指承受路面之土壤部份，其幅度包括路基有效寬度及為使路\n基穩定所形成挖填土之邊坡。\n三　路面：係指承受車輛、行人行駛（走）部分在路基上以各種材料舖築\n之承受層。\n四　路肩：係指路基有效寬度減除路面寬度，所剩兩側之路基面。\n五　路拱：係指道路橫向坡度曲線。\n六　人行道：係指劃設供行人專用之地面、道路與人行陸橋及人行地下道\n。\n七　分隔島：係設於道路路幅內，高出路面之構造物，用以區分各向、各\n型車輛及行人適當使用道路之安全設施。\n八　專用道路：係指各公私事業機構所興建，專供所營事業本身運輸之道\n路。\n九　平交道：係指市區道路與鐵路平面交叉之地方。\n十　共同管道：指設置於道路內之道路附屬工程，用於容納二種以上公用\n設施管線之構造物及其附屬設備。\n第 二 章 道路管理權責及幹支線區分\n第 一 節 權責之劃分\n第 3 條\n本規則所稱市區道路主管機關（以下簡稱主管機關）為彰化縣政府，市區\n道路管理機關（以下簡稱管理機關）為各所轄鄉（鎮、市）公所。\n第 4 條\n主管機關與管理機關之權責劃分如下：\n一、主管機關：\n（一）有關本縣市區道路法規之擬定事項。\n（二）有關本縣市區道路長期性修築、改善及養護發展計畫之審議與協助\n重要路線之修築及改善事項。\n（三）有關本縣市區道路之監督及輔導事項。\n二、管理機關：\n（一）有關市區道路鄉（鎮、市）自治規約之擬定事項。\n（二）有關鄉（鎮、市）市區道路基本資料及交通流量資料之蒐集、統計\n及建立事項。\n（三）有關鄉（鎮、市）市區道路修築、改善、養護及管理之擬定與執行\n事項。\n（四）有關鄉（鎮、市）市區道路之管理維護使用費徵收事項。\n（五）有關鄉（鎮、市）市區道路人行環境無障礙設施清查、改善之擬定\n與執行事項。\n第 5 條\n管理機關應於年度開始前，視實際需要擬定道路及附屬設施之修築、改善\n及養護計畫，報主管機關核定或備查，於年度終了時，予以考核。\n第 6 條\n市區道路及其附屬工程、路面、路肩上下公共設施之有關資料，應由管理\n機關設簿登記。\n第 二 節 道路幹支線之區分\n第 7 條\n道路幹支線之區分如下：\n一　幹線道路：供車輛直接通過之快速道路、主要道路及林園道路。\n二　支線道路：供兩旁人車直接出人之次要道路及巷道。\n前項區分規劃完成後，管理機關應公告之， 變更時亦同。\n第 三 章 道路及其附屬設施之管理\n第 一 節 道路\n第 8 條\n管理機關應定期實施重要市區道路使用現況調查。\n前項現況調查應包括道路幾何設計、路面狀況、行車速率及交通流量。\n第 9 條\n市區道路修築、改善或養護期間，應儘量維持通車，必須管制交通或禁止\n通行者，管理機關應會同警察機關將管制或禁止範圍、繞道路線及期限，\n予以公告，並設置必要之警告標誌。\n第 10 條\n修築、改善或養護路幅狹窄或交通量頻繁之市區道路，應儘量利用夜間分\n段施工，施工地段並應依道路交通標誌、標線號誌設置規則，設置各項安\n全設施。\n第 11 條\n人民或團體自行修築市區道路，應先向管理機關申請核准。\n第 12 條\n管理機關應經常養護道路維持各項設施完整，遇有毀損或災害應迅速修復\n，保持暢通。\n第 二 節 路基、路肩、路面\n第 13 條\n改善或翻修路基、路肩或路面時，仍須維持行車者，應明顯標示維持行車\n之車道，並設置警告標誌。\n第 14 條\n市區道路加舖新路面時，管理機關應注意路拱及側溝排水，並通知在道路\n下埋設管線單位，配合改善人孔、水閥盒等設施，使其頂面與路面平齊。\n設有共同管道之道路，應將原有管線納入共同管道。但經主管機關核定不\n宜納入者，不在此限。\n第 三 節 排水溝渠\n第 15 條\n市區道路兩旁溝渠不得加以侵占、利用、堆置雜物或設置其他有礙水流之\n物體。但經本府特別核准者，不在此限。管理機關並應會同有關單位定期\n或經常派員全面檢視，如發現違規情事，應即依法排除。\n第 16 條\n市區道路之現有溝渠，於修築或改善道路時，應儘量納入道路排水系統；\n道路兩側局部低達地區，土地業主得自行將基地填高至道路邊溝項或與人\n行道齊平。道路兩旁建築物之騎樓及無遮簷人行道地平面，應依照市區道\n路及附屬工程設計標準及配合道路高程建造，不得與鄰接地平面高低不平\n。\n第 四 節 橋樑、涵洞、隧道及地下道\n第 17 條\n管理機關於新建橋樑、涵洞、隧道或地下道時，應先協調有關公共設施管\n理單位，提出預留之設施位置或加設必要之結構計畫，增加之費用，由該\n公共設施管理單位負擔。\n第 18 條\n管理機關對於橋樑、涵洞、隧道或地下道各部結構及附屬之照明、通風或\n排水設備，每年應作定期安全檢查，並經常作必要之維護。\n第 19 條\n現有橋樑上下不得附加任何管線。但因事實需要，經管理機關認為無礙安\n全者，不在此限。\n第 20 條\n公共設施需要通過隧道者，應自地下通過。但經管理機關認為不影響隧道\n之安全者、通風、照明、淨空及觀瞻，得附設於隧道壁面。\n第 21 條\n在橋樑上下游各五百公尺及沿公路護岸八十公尺以內河川用地禁止採掘砂\n石，管理機關於必要時得請河川主管機關就特定橋樑擴大其禁限範圍。\n第 五 節 人行道\n第 22 條\n公共設施管理單位埋設於人行道之地下管線，其人孔或水閥盒等附屬設備\n之頂面，未與人行道齊平者，應限期令其改善，逾期不履行者，管理機關\n得代為履行。\n第 23 條\n人行道應維持平整暢通，並禁止不當使用。並依無障礙環境規定設置必要\n設施，管理機關應予維持正常使用。如有圍堵，管理機關應予打通整平。\n第 六 節 附屬物\n第 24 條\n管理機關應經常派員檢視市區道路之擋土牆，妥加維護。\n前項擋土牆為私有者，應由業主維護。\n第 25 條\n管理機關應經常檢查市區道路護欄及分隔島前端之防護設備，做必要之整\n修及油漆。\n第 26 條\n管理機關開闢或拓寬道路時，應視大眾運輸發展需要，協調交通事業主管\n機關及警察機關預留車站停車彎位置。\n第 27 條\n交通事業在現有道路旁新設或增設車站、招呼站或候車亭時，應將計畫設\n置地點及位置平面圖樣，送經交通事業主管機關會同警察機關及管理機關\n等核定後，始得設置。\n前項車站、招呼站或候車亭，交通事業單位經常維持清潔及完整，不得妨\n礙市容觀瞻。\n第 28 條\n市區道路之綠地、路肩及人行道內，管理機關得栽植樹木、花卉或草皮，\n並得設置護欄。\n第 29 條\n管理機關對路樹及綠地應經常維護或剪修， 並不得妨礙人車安全。\n第 七 節 路燈\n第 30 條\n管理機關應視實際需要清洗照明設施之玻璃罩，工廠集中或易遭污染地區\n者，應依實際需要增加清洗次數。\n第 31 條\n管理機關應經常維護檢查燈具、燈柱、支架、管制機具及零件，不得妨礙\n人車安全，如有損壞應隨時換修。\n第 八 節 天然災害及交通事故\n第 32 條\n管理機關應於天然災害發生前後全面巡視轄區道路，如發現有危害人車安\n全之虞者，應立即採取有效安全措施，並設置警告標誌。\n第 33 條\n管理機關應就當地警察機關提供之逐年交通事故調查資料，分析肇事地點\n道路之設計、施工及交通管制設施之缺點，予以改善。\n第 34 條\n市區道路之標誌、標線及號誌由管理機關會同警察機關，依道路交通標誌\n標線號誌設置規則設置，標誌、標線由管理機關管理維護；號誌由警察機\n關管理維護。\n道路之標誌、標線及號誌，得視實際需要委由警察機關設置或管理。\n警察機關得依道路易壅塞及易肇事路段或路口，會同管理機關，依道路交\n通標誌標線號誌設置規則規定，增設交通標誌、標線或號誌。\n第 35 條\n市區道路同一地點設置二種以上交通標誌、號誌或路名牌時，儘量設置於\n同一桿柱，並得利用路燈或電力、電信桿柱設置。\n第 36 條\n市區道路內之標誌、標線及號誌，管理機關及警察機關應經常維護管理，\n維持功能。\n第 37 條\n市區道路之交通安全設施，警察機關得會同管理機關設置，並由管理機關\n維護及管理。\n第 38 條\n行人護欄應設於下列地點：\n一　行人跨越易生危險之路口。\n二　沒有人行地下道或陸橋之處。\n三　限制行人穿越道路之路段。\n四　其他易使行人發生危險之處所。\n第 四 章 道路之使用與限制\n第 一 節 道路挖掘\n第 39 條\n公共設施管理單位因新設、拆遷、換修管線或其他使用，需挖掘路面時，\n應先向管理機關申請許可。\n主管機關須挖掘路面時，得行文通知管理機關後逕為辦理。\n第一項公共設施新設、拆遷及換修時，應將該路段原有管線儘量埋設地下\n。\n第 40 條\n申請挖掘道路者，應就該挖掘路面負修復責任，並得由管理機關代為修復\n。經核准修復者，應於完工後即行辦理，並負責保固二年。\n前項路面修復標準，由本府另定之。\n第 41 條\n市區道路在下列期間內，除有特殊情事經核准外，不得申請挖掘使用：\n一、新建或拓寬完成日起三年內。\n二、翻修或改善完成日起二年內。\n三、重要慶典期間。\n第 42 條\n市區道路兩旁房屋地下室與人行地下道連接著，起造人或承造人得向管理\n機關申請許可設置出入孔道，所需費用由申請人負擔。\n第 二 節 建築使用\n第 43 條\n建築物承造人在施工中須使用道路者，應依彰化縣建築管理自治條例之規\n定，先行申請許可。\n前項使用範圍須利用人行道者，應在人行道上空加設安全人行走廊，以維\n行人安全。\n第 44 條\n建築工程必須損壞道路、溝渠或其他設施時，承造人非先經申請管理機關\n核准，不得施工。\n前項損壞應由承造人負責修復，並得預繳費用，由管理機關代為修復。\n第 45 條\n建築工程施工時，承造人應維護工地附近路面、溝渠、人行道及其他公共\n設施之完整，如有毀損應負責修復。\n第 三 節 公共設施使用道路\n第 46 條\n公私團體機構之各種設施物，非經申請許可，不得佔用道路。\n第 47 條\n在市區道路範圍內設置下列設施時，應經管理機關許可：\n一　電力桿、電信桿、電力塔、變壓箱、郵筒、公共電話亭、停車收費設\n施、自來水救火栓、加壓設備及其他類似之公共設施。\n二　輕便軌道及其附屬設施。\n三　高架道路下之辦公室、店舖、倉庫、停車場、廣場及其他類似之設施\n。\n前項設施係建築法所規定建築物者，應申請建築執照。\n第 48 條\n申請設置前條設施者，應填具申請書，載明下列事項：\n一　使用道路之地點、範圍及計畫圖說。\n二　使用道路之目的。\n三　使用道路之期限。\n四　設施之構造。\n五　工程施工方法。\n六　施工期限。\n七　修復道路之方法。\n前項申請涉及道路交通安全者，應會同警察機關辦理，變更時亦同。\n第 49 條\n使用市區道路之設施，在路面或其上空者，應依下列規定辦理：\n一　儘量靠路邊或人行道。但對交通或景觀無顯著妨礙者，得設置於安全\n島、圓環及其他類似地點。\n二　不得設於道路交岔口、接續點或轉彎處之地面。\n三　懸空設施最下端與路面拱頂之淨空，不得少於四．六公尺。但人行道\n上空或商店之廣告牌，得減至二．五公尺。\n四　依道路寬度、交通流量及停車需要規劃路邊收費停車場。\n第 49-1 條\n使用市區道路之設施，應依據內政部所訂「市區道路使用費收費標準」繳\n交使用費。\n主管機關（含所屬機關）使用市區道路之設施，得免繳交使用費。\n第 50 條\n自來水管、雨水管、污水管、煤氣管、電力管、電信管、油管及電視電纜\n管等地下管線（以下簡稱地下管線），應埋設在人行道或靠近慢車道下，\n其頂面距離路面之深度規定如下：\n一　人行道不得少於五十公分。\n二　巷道不得少於七十公分。\n三　快慢車道不得少於一百公分。\n前項地下管線斷面積較大，其結構計算事先經管理機關同意者，不受埋設\n位置及深度之限制。\n第 51 條\n地下管線之埋設位置及深度，在已開闢之都市計畫道路，應由管理機關與\n公共設施管理單位協商決定。在未開闢之都市計畫道路或都市計畫開闢前\n已有既成道路，應由公共設施管理單位事先與道路管理機關協商決定。\n第 52 條\n管理機關辦理市區道路新建、拓寬或改善工程時，應經協商將擬之工程概\n要及實施要點，送請公共設施管理單位配合辦理地下管線埋設工程，並請\n其將地下管線工程概要復知管理機關。\n第 53 條\n設置地下管線、共同管道、人行地下道、地下商場、地下室及地下停車場\n等設施者，應於施工前三十日向管理機關申請許可，但災害搶修及其他緊\n急工程，得於通知當地警察機關及管理機關後施工，並於施工後三日內補\n辦申請許可。管理機關收到前項申請書件翌日起，應於十日內審查完竣，\n將審查結果通知申請人，准予施工者並應發給許可證，副知當地警察機關\n。但施工期間須管制交通者，應會同警察機關審查，並應公告。\n申請人應於施工時設置警告標誌，竣工後應將路面修復請管理機關驗收。\n管理機關應於接獲報驗日起五日內驗收，並將結果通知申請人，驗收合格\n者始得拆除警告標誌。\n第 54 條\n管理機關得依事實需要或公共設施管理單位申請，擬定共同管道設置計畫\n，報經上級管理機關核准後公告之。\n市區道路設置共同管道者，除特殊情事外，原有管線應納入共同管道，並\n禁止在路面下新設或增設管線。\n第 55 條\n快速道路通過省轄市行政區域或都市計劃範圍內者，管理機關應與當地都\n市計劃主管機關協商決定其位置、式樣及構造。\n第 56 條\n電力管、電信管、油管、煤氣管及自來水管等管線附設於快速道路者，不\n得影響人車之安全。\n第 57 條\n人行陸橋得與相鄰之建築物接通，但應符合建築法之有關規定。\n第 四 節 道路障礙清理\n第 58 條\n人行道與慢車道間之Ｌ型側溝，不得破壞、更改或設置三角形物。\n第 59 條\n營業性汽車修理場所，不得在寬度六公尺以下之巷道內，開闢汽車出入口\n。\n第 60 條\n下列行為應予禁止：\n一　在道路堆置或棄置有礙交通之物品。\n二　利用道路作為工作場所。\n三　非經許可利用道路擺設攤位。\n四　其他不當使用道路之行為。\n第 五 章 附則\n第 61 條\n鄉（鎮、市）之市區道路管理業務，經考核著有績效者，本府得予以獎勵\n，績效不佳者，得予以懲處。\n第 62 條\n違反本規則規定者，依市區道路條例、道路交通管理處罰條例、建築法或\n其他有關法規處罰。\n第 63 條\n本規則規定之書、表、簿等格式由本府訂定之。\n第 64 條\n本規則自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL044918","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"修正日期":"民國 109 年 10 月 13 日","公發布日":"民國 91 年 10 月 28 日","法規名稱":"彰化縣市區道路管理規則","法規體系":"工務類","發文字號":"府法制字第1090359742號"},"promulgation_date":"2002-10-28","revision_date":"2020-10-13","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL044918","status":"unknown","title":"彰化縣市區道路管理規則","last_checked_at":"2026-10-06T17:26:49+08:00","last_success_at":"2026-10-06T17:26:49+08:00","verification_status":"fetched","content_hash":"477c6fbd9657111a5dec3f13d24eb3ba80cd09faa64f03317b76b54cc2f00eae","history":[{"observed_at":"2026-10-06T17:26:49+08:00","content_hash":"477c6fbd9657111a5dec3f13d24eb3ba80cd09faa64f03317b76b54cc2f00eae","change_kind":"initial","revision_date":"2020-10-13"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"彰化縣政府","category":"建築管理相關","content":"第 1 條\n彰化縣政府（以下簡稱本府）為落實使用者付費之財政負擔公平原則，依\n規費法第十條第一項規定訂定本收費標準。\n第 2 條\n申請建築圖說之使用，應填具申請文件，經本府核准後，通知申請人辦理\n繳費及領取資料事宜。\n第 3 條\n申請建築圖說之使用，應依本收費標準規定繳納建築圖說使用費。\n前項所稱建築圖說使用費，包括建築圖說影印及建築圖說電子檔案列印輸\n出之費用。\n第 4 條\n申請各種規格建築圖說之收費標準如下：\n一、黑白影印、列印輸出：A1  及 A2 每張收取新臺幣五十元，A3  及\nB4  每張收取新臺幣五元，A4  及 B5 每張收取新臺幣二元。\n二、彩色影印、列印輸出：A3、B4、A4  及 B5 每張收取新臺幣三十元。\n前項申請依相關法令規定本府應予提供者，得免收費用。\n依本收費標準收取之費用，依法解入彰化縣縣庫。\n第 5 條\n本收費標準自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL060854","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"公發布日":"民國 100 年 04 月 28 日","法規名稱":"彰化縣建築圖說使用收費標準","法規體系":"建設類","發文字號":"府法制字第1000108720號"},"promulgation_date":"2011-04-28","revision_date":"2011-04-28","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL060854","status":"unknown","title":"彰化縣建築圖說使用收費標準","last_checked_at":"2026-10-06T17:26:40+08:00","last_success_at":"2026-10-06T17:26:40+08:00","verification_status":"fetched","content_hash":"37ab293b7aaa682cbbcace340d8b2a856ec508039055190eb7bb7fde53e305e6","history":[{"observed_at":"2026-10-06T17:26:40+08:00","content_hash":"37ab293b7aaa682cbbcace340d8b2a856ec508039055190eb7bb7fde53e305e6","change_kind":"initial","revision_date":"2011-04-28"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"彰化縣政府","category":"建築管理相關","content":"一、彰化縣政府（以下簡稱本府）為加強本縣建築工程申報勘驗事項之管\n理，依彰化縣建築管理自治條例（以下簡稱本自治條例）第二十七條\n第六項規定訂定本要點。\n二、建築工程必須於施工前申報之階段勘驗如下：\n（一）供公眾使用建築物：基礎、各樓層（不含屋頂突出物）。\n（二）非供公眾使用建築物：基礎。\n三、建築工程申報勘驗，應檢附下列證明文件向本府申報（文件格式依內政部規定辦理）：\n（一）建築工程勘驗申報書(B14-1)。\n（二）建造執照正本。\n（三）建築工程必須勘驗部分申報表(B14-2)\n（四）建築物施工中營造業專任工程人員督察紀錄表(B14-5)。\n（五）勘驗建築物外觀及申報樓層之相片。\n（六）承造人之專任工程人員或委託其他同等級營造業之專任工程人員現場查驗之相片。\n（七）監造人或委託具監造資格之其他建築師現場查驗之相片。\n（八）鋼筋無輻射污染及混凝土品質氯離子含量檢測等相關證明文件。\n（九）六層以上或開挖地下室建築物須檢附「必須鑑定範圍」或「免鑑定」報告書。\n（十）處理建築工程剩餘土及混合物相關證明文件。\n（十一）建築物結構用混凝土細粒料混摻電弧爐煉鋼爐碴（石）檢測報告書。\n（十二）施工日誌(B14-4)。\n（十三）其它依法令必要之文件或本府指定應檢附之書件。\n無第八款至第十一款事項者得免檢附該項證明文件。 ​​​​​​\n四、應申報勘驗未申報而先行動工者，承造人應於該樓層申報勘驗時，檢\n附專業公會出具之安全鑑定報告書及結構強度證明文件後，始得繼續\n施工。\n前項出具之安全鑑定報告書並應含無輻射鋼筋及氯離子符合規定之證\n明事項。\n五、供公眾使用建築物及非供公眾使用建築物合計達十戶以上者，於下列施工階段應由本府派員或委託專業機構現場勘驗:\n（一）有地下室建築物之基礎勘驗。\n（二）鋼構一層樓建築物之基礎勘驗。\n（三）地上二層樓板勘驗。\n（四）地上二層樓板以上每增加五層樓板勘驗。\n（五）其他經主管建築機關認定有必要之項目。\n建築物除前項以外必須勘驗部分，本府以書面審查為原則，必要時並得派員勘驗之。\n本府受理申報後三日內（不含例假日及國定假日）派員至現場勘查及填寫勘驗紀錄表（附表一）經同意後始得繼續施工。但有本自治條例第二十七條第三項之情事者，不在此限。\n六、本要點自發布日實施。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL077977","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"修正日期":"民國 115 年 04 月 08 日","公發布日":"民國 0 年 00 月 00 日","法規名稱":"彰化縣建築工程申報及現場勘驗作業要點","法規體系":"建設類","發文字號":"府建管字第1150122489號令"},"promulgation_date":null,"revision_date":"2026-04-08","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL077977","status":"unknown","title":"彰化縣建築工程申報及現場勘驗作業要點","last_checked_at":"2026-10-06T17:26:27+08:00","last_success_at":"2026-10-06T17:26:27+08:00","verification_status":"fetched","content_hash":"1e091e930db186c9d7c51c649f31c22c9e2a7c4e73c4f9fcddf5e75d5cc8bd1b","history":[{"observed_at":"2026-10-06T17:26:27+08:00","content_hash":"1e091e930db186c9d7c51c649f31c22c9e2a7c4e73c4f9fcddf5e75d5cc8bd1b","change_kind":"initial","revision_date":"2026-04-08"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"彰化縣政府","category":"建築管理相關","content":"一、彰化縣政府（以下簡稱本府）為強化彰化縣建築管理自治條例第二十六條有關施工計畫書內容，以加強彰化縣（以下簡稱本縣）建築施工管理，提升建築物施工品質、安全及衛生，特訂定本原則。\n二、建築物施工（拆除）計畫書，分為以下二類：\n（一）特殊性案件：\n1.適用彰化縣政府建造執照申請有關特殊結構委託審查原則案件。\n2.山坡地基地面積達三千平方公尺涉及開挖整地之建築或雜項工工程。\n3.拆除執照工程其拆屋規模達地上十層以上之建築物。\n4.基地範圍境界線起算水平距離六公尺內同時有地下層施工。\n5.其他經主管建築機關認定情況特殊並有安全顧慮。\n（二）一般性案件：前項以外之建築物或雜項工作物。\n三、前點第二款所定一般性案件之施工（拆除）計畫書，載明下列事項：\n（一）工程概要：\n1.工程名稱。\n2.工程地址。\n3.建築執照字號。\n4.工程規模。\n5.工程造價。\n6.工程承攬金額。\n（二）工程相關人員組織基本資料：\n1.起造人。\n2.監造人。\n3.承造人。\n4.專任工程人員。\n5.職業安全衛生人員。\n6.工地主任（營造業承攬一定金額或一定規模以上之工程，包含工程金額及規模、工地主任姓名、工地主任證號、派駐工地期間）。\n7.工地負責人。\n8.營造業技術士資訊（包含專業工程項目、特定施工項目、特定施工項目金額規模、技術士種類、技術士證號、派駐施工期間）。\n（三）施工方法及施工程序。\n（四）預定進度及作業時間。\n（五）勘驗預定申報流程及範圍。\n（六）自主品質管制措施。\n（七）建築基地周邊調查（含公共設施）。\n（八）施工場所配置及圖說：\n1.各項安全衛生維護設施。\n2.預防火災之適當設備。\n3.工務所設置位置。\n4.機具材料堆置位置。\n5.加工場位置。\n6.施工圍籬美化之相關設計圖說及設置位置標示。\n（九）工地環境維護：\n1.噪音及振動防制措施。\n2.相關營建污染及灰塵散播防制措施。\n3.公共設施維護措施。\n4.營建廢棄物處理措施。\n（十）營建剩餘土石方處理：\n1.開挖土石方計算及處理方式。\n2.營建工程剩餘土石方處理計畫申報表。\n3.剩餘土石方清除清除機具內容及應裝置即時追蹤系統等說明。\n（十一）塔式起重機具設備使用計畫：\n1.使用塔式起重機具設備者，應檢附施工計畫、勞工安全衛生及交通維持之主管機關同意核備文件。\n2.無需使用塔式起重機具者，應檢附切結書。\n（十二）交通安全維護計畫（含大型工程車車輛進出工地及營建材料吊掛作業管制措施）。\n（十三）地下室施工作業：\n1.地下層開挖擋土措施。\n2.挖土工程施工及流程安排。\n3.地下層開挖之止水及排水措施分析評估。\n4.安全觀測系統（儀器、數量、安裝位置圖、觀測頻率及管理值表）。\n（十四）鄰房安全維護措施：\n1.現況鄰房調查及距離。\n2.開挖深度及影響評估。\n3.擋土設施及支撐安全維護設施。\n4.事故發生之處理及緊急應變措施。\n（十五）施工風險評估報告。\n（十六）防災及緊急應變措施：\n1.鷹架系統施工及安全維護措施。\n2.模板支撐系統施工及安全維護措施。\n3.墜落物防護及安全維護措施。\n4.開口安全防護措施。\n5.地下室通風及毒氣安全維護監測措施。\n6.火災預防措施。\n7.天然災害（颱風、豪雨、地震）防救措施及檢查（核）表：\n（1）彰化縣建築工程防颱作業工地自主檢查表。\n（2）彰化縣建築工程地震災害後工程設施檢核表。\n（3）人為災害（火災、坍塌、墜落）防救措施。\n（十七）施工災害緊急應變及通報計畫。\n（十八）建築工地紅火蟻防治工作計畫：\n1.紅火蟻清查及防治措施。\n2.建築基地入侵紅火蟻現場清查紀錄表。\n（十九）建築工地登革熱防治工作計畫。\n（二十）建築工程落實污染防制（治）輔導紀錄單、公共工程建築工程環境維護輔導紀錄單。\n四、第二點第一款所定特殊性案件之施工（拆除）計畫書，除載明前點所定事項外，並須載明下列事項：\n（一）工程概要：結構與施工法概要、地下室擋土工法概要（擋土措施之種類、規格、開挖剖面圖）。\n（二）基地環境概況：基地現況與四周基地地下管線及構造物現況調查、基地土層分布特性、地下水位。\n（三）地下室施工作業：地下層開挖擋土支撐系統之應力分析及檢討（各階段開挖壁體變形量、水平支撐設定壓力及地面沉陷分析）、開挖面之上舉、隆起及砂湧、管湧及整體穩定分析、地質改良工法之施工方式及藥液成分管制及地下水污染防治（改良範圍）。\n（四）鄰房安全維護措施：開挖可能導致鄰近一定範圍地盤沉陷分析評估、開挖深度一定範圍鄰房及公共設施現況調查（含鄰房樓層數、構造、基礎型式初判及周邊道路探測（如透地雷達等方式）、鄰房保護措施。\n（五）工法說明：如施工程序及管制要點說明、逆打柱承載重核算、高空作業人員安全防護措施、地下室照明、通訊設備、鋼骨樓層、樓板進度配合、地下室緊急逃生措施、地下室各層樓板混凝土養護、地下室運土計畫、垂直墜落物防範措施、地錨設計、施工拉拔力檢測。\n（六）其他視案件規模或類型，應檢附文件：\n1.土壤鑽探試驗結果報告。\n2.抽水及停止抽水計畫計算。\n3.構台應力分析及設計。\n4.緊急搶修及救災應變方式。\n5.特殊模板應力分析及設計。\n6.地下連續壁或反循環基樁等施工方法之污染防治措施。\n7.其他經主管建築機關認有必要載明之事項。\n五、施工計畫書應於開工報請備查作業：\n（一）特殊性案件：起造人或承造人委託建築師公會、土木技師公會、結構技師公會、大地技師公會、其他經本府同意之專業機關或團體辦理計畫書技術性諮詢作業且無修正意見後，將諮詢結果文件送本府備查。\n（二）一般性案件：由主管建築機關自行辦理備查。\n申請建造執照或雜項執照時如未檢附地政機關核發之土地複丈成果圖，應於申報開工前申請土地鑑界，以確認土地界址。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:GL000481","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"修正日期":"民國 115 年 06 月 02 日","公發布日":"民國 115 年 06 月 15 日","法規名稱":"彰化縣建築工程辦理施工計畫書備查作業原則","法規體系":"建設類","發文字號":"府建管字第1150212465號"},"promulgation_date":"2026-06-15","revision_date":"2026-06-02","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=GL000481","status":"unknown","title":"彰化縣建築工程辦理施工計畫書備查作業原則","last_checked_at":"2026-10-06T17:26:27+08:00","last_success_at":"2026-10-06T17:26:27+08:00","verification_status":"fetched","content_hash":"23d6f2a96aa22ffde9229b8c38cff5102f71c8319dc2fa0ee01b62b38f01a468","history":[{"observed_at":"2026-10-06T17:26:27+08:00","content_hash":"23d6f2a96aa22ffde9229b8c38cff5102f71c8319dc2fa0ee01b62b38f01a468","change_kind":"initial","revision_date":"2026-06-02"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"彰化縣政府","category":"建築管理相關","content":"一、彰化縣政府（以下簡稱本府）為加強複查建築物公共安全檢查申報案\n件，以確保建築物合法使用與其構造設備安全，依建築法第七十七條\n第四項規定訂定本要點。\n二、本要點以已完成建築物公共安全檢查申報，並由本府建設局同意備查\n之案件為執行範圍。\n三、本要點所稱「專業檢查人」，為建築師、專業技師或專業機構檢查人\n。\n四、從核發申報結果通知書之日起至複查完竣期間不得逾越二個月。\n五、建築物公共安全檢查申報案件核發申報結果通知書後，原則於每週一\n分配抽查案件，每週五彙整抽查結果。\n六、建築物公共安全檢查申報複查率應達百分之三十五以上。\n七、複查案件應於現場複查，本府建設局應於三日前通知申報人及專業檢\n查人員會同到場檢查，無故缺席者，視為拒絕檢查。\n八、經複查結果為不合格者，應於會勘紀錄述明違規事項及責任歸屬，由\n申報人及專業檢查人員簽名確認並依「彰化縣政府辦理建築物公共安\n全檢查違法案件統一裁罰基準」規定辦理。該營業場所由該專業檢查\n人重新檢查，並於一個月內將檢查結果向本府建設局申報。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL087949","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"公發布日":"民國 92 年 12 月 24 日","法規名稱":"彰化縣建築物公共安全檢查申報案件複查執行要點","法規體系":"建設類","發文字號":"府建使字第0920244655號"},"promulgation_date":"2003-12-24","revision_date":"2003-12-24","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL087949","status":"unknown","title":"彰化縣建築物公共安全檢查申報案件複查執行要點","last_checked_at":"2026-10-06T17:26:34+08:00","last_success_at":"2026-10-06T17:26:34+08:00","verification_status":"fetched","content_hash":"9db4f3d12501843ca86e8e5be7ae584cd2c9db4897a524445bc8034c67b832c9","history":[{"observed_at":"2026-10-06T17:26:34+08:00","content_hash":"9db4f3d12501843ca86e8e5be7ae584cd2c9db4897a524445bc8034c67b832c9","change_kind":"initial","revision_date":"2003-12-24"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"彰化縣政府","category":"建築管理相關","content":"一、彰化縣政府 (以下簡稱本府) 為提高本縣建築物公共安全檢查簽證及\n申報書審查作業效率，特訂定本要點。\n二、本要點審查人員由本府建設局使用管理課輪值人員任之，必要時得邀\n請本縣建築物公共安全檢查機構或人員二至三人協助。\n三、本府審查人員於受理申報人委託專業檢查機構或人員辦理檢查之申報\n書時，應依下列規定辦理：\n(一) 經審查結果不符案件，應一次通知簽證檢查人或申報人補正，於補\n正後資料再行併同申報書等文件，檢送至本府辦理複審。\n(二) 經審查結果符合規定者，應檢附申報書原卷 (三份) ，辦理掛號手\n續。\n前項簽證檢查人或受託送審辦理申報人員經審查確定後，未辦理掛號\n手續者，視為無效之申報書。審理期間如有爭議時，得現場向審查人\n員反映，必要時得由簽證檢查人員到場說明。\n四、申報書若有下列情形之一者，得不予審理：\n(一) 未檢附申報書原卷 (三份) 。\n(二) 檢查報告書內資料不全，或填寫不全，且未附註具體說明者。\n(三) 未提出符合建築法令及其規定之改善計畫。\n(四) 修改處專業檢查機構或人員未核章。\n(五) 其他事項者 (如重複提改善計畫而未確實改善完竣者) 。\n五、專業檢查機構、人員或受託送審人員，於審理申報書前，應出具申報\n人領取檢查報告書之委託書(如附件)，若未出具委託書或委託書填寫\n不確實者，審查人員得不予受理。\n六、本要點自發布日實施。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL028120","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"公發布日":"民國 92 年 03 月 11 日","法規名稱":"彰化縣建築物公共安全檢查簽證及申報業務審查作業要點","法規體系":"建設類","發文字號":"字第號"},"promulgation_date":"2003-03-11","revision_date":"2003-03-11","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL028120","status":"unknown","title":"彰化縣建築物公共安全檢查簽證及申報業務審查作業要點","last_checked_at":"2026-10-06T17:26:35+08:00","last_success_at":"2026-10-06T17:26:35+08:00","verification_status":"fetched","content_hash":"a6476058fbebf34c6e512dbb70c7dab0af969e41a2e02dfe69b0494844d517be","history":[{"observed_at":"2026-10-06T17:26:35+08:00","content_hash":"a6476058fbebf34c6e512dbb70c7dab0af969e41a2e02dfe69b0494844d517be","change_kind":"initial","revision_date":"2003-03-11"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"附圖.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=4031&id=GL000488&type=LAW"},{"name":"附表.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=4032&id=GL000488&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"一、彰化縣政府(以下簡稱本府)為落實建築物室內裝修管理，實施室內裝修案件審核、查驗及抽查機制，依據建築物室內裝修管理辦法(以下簡稱本辦法)第七條第二項規定，訂定本規範。\n二、本規範之主管機關為本府，執行單位為本府建設處。\n三、本規範所稱申請人為建築物起造人、所有權人或使用人。\n四、本規範用詞定義如下：\n(一) 審查機構：係指經內政部指定置有審查人員執行室內裝修審核及查驗業務之建築師公會或專業技術團體，並向本府核備而得於本縣執行業務者。\n(二) 簡易室內裝修：係指符合本辦法第三十三條規定條件之室內裝修。\n五、審查機構辦理室內裝修之圖說審核及竣工查驗應依本辦法第七條第一項及本規範規定，擬訂作業事項並載明工作內容與應負之責任及義務，報請本府核備。\n六、申請簡易室內裝修之建築物，應依下列規定辦理，相關流程如附圖：\n(一) 裝修圖說由依法登記開業之建築師或室內裝修業專業設計技術人員簽章負責，如涉及分間牆變更者，應依本辦法第二十五條規定辦理。\n(二) 消防安全設備於申報施工及工程完竣審查時，由消防設備師或消防安全設備設計監造暫行人員簽證負責，免送彰化縣消防局審查。\n(三) 施工完竣後由營造業專任工程人員或室內裝修專業施工技術人員查驗簽章。\n七、審查機構辦理室內裝修圖說審核及竣工查驗，應指派具有本辦法第八條規定審查人員資格者為之，並應將審查人員造冊送本府備查。\n八、審查機構圖說審核，應依下列辦理：\n(一) 申請書圖文件應齊全。\n(二) 應註明室內裝修使用之材料種類、防火時效及耐燃級數。\n(三)防火避難設施、消防設備、防火區劃及主要構造應符合規定，不得有破壞或妨害情形。\n九、審查機構竣工查驗，應依下列辦理：\n(一)現場查核與圖說相符。\n(二)使用之防火材料應附具檢測合格之證明文件及出廠證明。\n符合本規範第六點規定者，經審核其申請文件齊全後，發給室內裝修合格證明，得免現場查核，必要時應依前項規定辦理。\n十、室內裝修施工期限自本府核發同意施工文件之日起兩年為限，符合本規範第六點規定者為六個月；申請人因故未能於期限內完工時，得於期限屆滿前申請展期六個月，並以一次為限；未依規定申請展期或已逾展期期限仍未完工者，本府同意施工文件自期限屆滿之日起，失其效力。但因特殊情形經本府核可者，不在此限。\n十一、審查機構應設審查小組，就所受理室內裝修及簡易室內裝修申請案（圖說審核及竣工查驗）實施抽查，每半年一次，其抽查件數不得少於當期申請案件之十分之一，抽查結果應報本府備查，或得由本府逕為抽查之。\n十二、室內裝修相關書表，依內政部訂頒之格式辦理；簡易室內裝修申請書表文件如附表；必要時審查機構得報請本府補充之。\n十三、本規範未盡事宜，悉依本辦法規定辦理，並得由審查機構依本辦法第七條訂定作業事項中補充之。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:GL000488","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"公發布日":"民國 115 年 09 月 30 日","圖表附件":"附圖.pdf 附表.pdf","法規名稱":"彰化縣建築物室內裝修審查作業事項規範","法規體系":"建設類","發文字號":"115年9月30日府建使字第1150396692號函"},"promulgation_date":"2026-09-30","revision_date":"2026-09-30","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=GL000488","status":"unknown","title":"彰化縣建築物室內裝修審查作業事項規範","last_checked_at":"2026-10-06T17:26:26+08:00","last_success_at":"2026-10-06T17:26:26+08:00","verification_status":"fetched","content_hash":"d1c1f7dd5dbddf3dcdcf5cedf37f063b963ad22290db1ea49a39eeb30e3894a8","history":[{"observed_at":"2026-10-06T17:26:26+08:00","content_hash":"d1c1f7dd5dbddf3dcdcf5cedf37f063b963ad22290db1ea49a39eeb30e3894a8","change_kind":"initial","revision_date":"2026-09-30"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=4031&id=GL000488&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=4032&id=GL000488&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"彰化縣建築物工程造價標準第二條修正條文對照表.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=3282&id=FL049411&type=LAW"},{"name":"彰化縣建築物工程造價標準第二條修正總說明.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=3281&id=FL049411&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"第 1 條\n彰化縣建築物工程造價標準（以下簡稱本標準）依彰化縣建築管理自治條\n例第十七條規定訂定之。\n第 2 條\n彰化縣（以下簡稱本縣）各種構造建築物工程造價如下：\n┌────────────────┬────┬────────┐\n│構  造  類  別                  │單　  位│      單  價    │\n│                                │        │    （新臺幣）  │\n├────────────────┼────┼────────┤\n│鋼骨或鋼筋混凝土造　五層以下    │平方公尺│    五千九百元  │\n├────────────────┼────┼────────┤\n│鋼骨或鋼筋混凝土造　六至十層    │平方公尺│    七千一百元  │\n├────────────────┼────┼────────┤\n│鋼骨或鋼筋混凝土造  十一至十五層│平方公尺│  一萬零八百元  │\n├────────────────┼────┼────────┤\n│鋼骨或鋼筋混凝土造  十六至二十層│平方公尺│  一萬一千六百元│\n├────────────────┼────┼────────┤\n│鋼骨或鋼筋混凝土造  二十一層以上│平方公尺│  一萬三千元    │\n├────────────────┼────┼────────┤\n│鋼筋混凝土加強磚造              │平方公尺│    五千九百元  │\n├────────────────┼────┼────────┤\n│磚造                            │平方公尺│    三千元      │\n├────────────────┼────┼────────┤\n│木造                            │平方公尺│    三千元      │\n├────────────────┼────┼────────┤\n│磚木造                          │平方公尺│    三千元      │\n├────────────────┼────┼────────┤\n│磚石造                          │平方公尺│    三千元      │\n├────────────────┼────┼────────┤\n│鋼鐵造有牆者                    │平方公尺│    三千八百元  │\n├────────────────┼────┼────────┤\n│鋼鐵造無牆者                    │平方公尺│    二千六百元  │\n└────────────────┴────┴────────┘\n第 3 條\n本縣收取建築執照規費及罰鍰之核算應依據前條工程造價標準，本標準內\n容不包括水電及建築設備。\n第 4 條\n本標準未列之工程項目，依建築師或各專業技師以實際工作所需之工程費\n用覈實估算，由本府核定。\n第 5 條\n本標準自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL049411","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"修正日期":"民國 113 年 10 月 22 日","公發布日":"民國 96 年 07 月 09 日","法規名稱":"彰化縣建築物工程造價標準","法規體系":"建設類","發文字號":"府行法字第1130404682號","立法理由":"彰化縣建築物工程造價標準第二條修正條文對照表.pdf 彰化縣建築物工程造價標準第二條修正總說明.pdf"},"promulgation_date":"2007-07-09","revision_date":"2024-10-22","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL049411","status":"unknown","title":"彰化縣建築物工程造價標準","last_checked_at":"2026-10-06T17:26:38+08:00","last_success_at":"2026-10-06T17:26:38+08:00","verification_status":"fetched","content_hash":"c74addd536d147f93f2ca4c38563d5264912f9f058cc7348d7a83015603afc92","history":[{"observed_at":"2026-10-06T17:26:38+08:00","content_hash":"c74addd536d147f93f2ca4c38563d5264912f9f058cc7348d7a83015603afc92","change_kind":"initial","revision_date":"2024-10-22"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=3282&id=FL049411&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=3281&id=FL049411&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"01申請建築物恢復使用及供水供電申請書應備書件.DOC","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=163&id=FL049930&type=LAW"},{"name":"02彰化縣建築物恢復使用及供水供電申請書.DOC","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=164&id=FL049930&type=LAW"},{"name":"03申請人身份證明文件.DOC","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=165&id=FL049930&type=LAW"},{"name":"04所有權人行政罰鍰繳納證明.DOC","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=166&id=FL049930&type=LAW"},{"name":"05建築物現場改善照片.DOC","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=167&id=FL049930&type=LAW"},{"name":"06民事委任書.DOC","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=168&id=FL049930&type=LAW"},{"name":"07切結書.DOC","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=169&id=FL049930&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"一、彰化縣政府（以下簡稱本府）為辦理建築法第九十四條、第九十四條\n之一及工廠管理輔導法第三十一條第二項規定，關於許可建築物恢復\n使用及供水供電事宜，訂定本要點。\n二、本要點規定申請恢復使用及供水供電對象，係指違反建築法第七十三\n條、第七十七條規定並依同法第九十一條規定處以限期停止使用或停\n止供水供電之建築物，及違反工廠管理輔導法第二十三條、二十五條\n、第二十六條規定，並依同法第三十一條規定處以限期停止使用或停\n止供水供電之建築物。\n三、建築物申請恢復使用及供水供電之審查權責劃分如下：\n（一）建築物防火避難設施及設備安全：本府建設處。\n（二）目的事業主管機關（單位）原列管項目：本府相關局、處。\n（三）消防安全設備：本縣消防局。\n四、建築物申請恢復使用及供水供電審查原則如下：\n（一）建築物符合原核准用途使用。\n（二）建築室內裝修拆空或恢復原核准使用。\n（三）符合消防法規相關規定。\n（四）違規生財器具已搬遷。\n（五）繳清違規罰鍰。\n（六）違章部分依據「彰化縣辦理變更使用執照及室內裝修申請案違建部\n分處理辦法」辦理。\n五、建築物申請恢復使用及供水供電，申請人應檢具下列證明文件及圖說\n向本府提出申請：\n（一）申請書。\n（二）建築物使用執照或變更使用執照及竣工圖影本（舊有合法房屋免附\n）。\n（三）建築物權利證明文件（建築改良物登記簿謄本或權狀影本）。\n（四）建築物所有權人身分證明文件。\n（五）該建築物違反建築法或工廠管理輔導法之行政罰鍰處分書及繳納證\n明文件影本（無罰鍰者免附）。\n（六）該建築物違反建築法或工廠管理輔導法改善後照片（建物正面含門\n牌、改善後之樓層內部裝修）。\n（七）切結書。\n（八）委任書（委任他人辦理時應檢附）。\n前項所稱申請人，為建築物所有權人。\n六、本府自收件掛號日起，應於三日內完成書面審查，申請書件不齊備者\n應詳為列舉，一次通知補正。申請人應於接到補正通知書之日起二十\n日內補正，逾期未補正或未依通知補正事項補正者，得予以退件。\n前項審查如有下列情形之一者，應排定日程通知申請人及相關權責機\n關（單位）現場會勘：\n（一）申請日期前一年內擅自變更供作八大行業或電子遊藝場使用者。\n（二）建築物改善後照片無法充分顯示改善情形，經通知補正仍未符規定\n者。\n七、前點現場勘查之內容如下：\n（一）建築物防火避難設施及設備安全：依建築法相關規定及核准建築物\n平面圖說辦理。\n（二）目的事業主管機關（單位）原列管項目：依各目的事業相關法規辦\n理。\n（三）消防安全設備：依消防法相關規定辦理。\n現場會勘應由各權責機關（單位）分別填寫會勘紀錄。如現場會勘結\n果符合原核准用途使用，前項建築物防火避難設施及設備安全得由建\n築物公共安全檢查人員或專業檢查機構簽證負責。\n八、經權責機關（單位）勘查符合規定者，應於審查完竣或會勘之日起十\n日內彙整通知申請人，經審查不合格者，應將其不合格之處，詳為列\n舉，一次通知改善。申請人應於接獲通知改善之日起二個月內，依通\n知事項改善完竣送請複審；逾期未送或複審仍不合規定者，得予以退\n件。\n九、對於申請人所檢附之圖說、照片、證件資料，本府必要時得會請相關\n機關（單位）協助查證，若有虛偽不實，得移送檢調機關（單位）依\n刑法第二百十四條使公務員登載不實罪究辦，申請案件應予退件。\n十、建築物申請恢復使用及供水供電相關書表格式，由本府定之。\n圖表附件：\n01申請建築物恢復使用及供水供電申請書應備書件.DOC\n02彰化縣建築物恢復使用及供水供電申請書.DOC\n03申請人身份證明文件.DOC\n04所有權人行政罰鍰繳納證明.DOC\n05建築物現場改善照片.DOC\n06民事委任書.DOC\n07切結書.DOC\n十一、本要點自發布日實施。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL049930","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"修正日期":"民國 98 年 06 月 25 日","公發布日":"民國 93 年 04 月 21 日","法規名稱":"彰化縣建築物恢復使用及供水供電審查作業要點","法規體系":"建設類","發文字號":"府建使字第0980149540號"},"promulgation_date":"2004-04-21","revision_date":"2009-06-25","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL049930","status":"unknown","title":"彰化縣建築物恢復使用及供水供電審查作業要點","last_checked_at":"2026-10-06T17:26:34+08:00","last_success_at":"2026-10-06T17:26:34+08:00","verification_status":"fetched","content_hash":"54b530c8e7c785627464eb04b8aca21ebb759c722d977b28f9c360c026a53933","history":[{"observed_at":"2026-10-06T17:26:34+08:00","content_hash":"54b530c8e7c785627464eb04b8aca21ebb759c722d977b28f9c360c026a53933","change_kind":"initial","revision_date":"2009-06-25"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=163&id=FL049930&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=164&id=FL049930&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=165&id=FL049930&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=166&id=FL049930&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=167&id=FL049930&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=168&id=FL049930&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=169&id=FL049930&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"附表一.odt","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=887&id=GL000116&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"第一條\n彰化縣政府 (以下簡稱本府) 為加強施工中維護公共安全及處理建築爭議\n事件，特訂定本規則。\n第二條\n建築物設計人對於施工涉及公共安全之防範措施預先應有周全之考慮。施\n工中，起造人、承造人、監造人對於公共安全應有周全之防護措施，如有\n發生侵害他人財產或肇致危險或傷害他人等情事，建築物起造人、設計人\n、監造人、承造人 (含負責人及專任工程人員) 應依建築法第二十六條及\n營造業法第三十七條、第三十八條及第三十九條規定分別負其責任。\n第三條\n六層以上或開挖地下室之建築物施工為界定將來損鄰之責任，起造人及承\n造人應於放樣前會同監造人勘查基地現況，向鑑定單位申請鄰房現況調查\n鑑定 (至少以基礎開挖深度二倍以上距離內所有鄰房之各層範圍) ，作成\n報告於申報放樣勘驗時一併檢附備查；但經監造人及專任工程人員認定免\n鑑定或必須鑑定範圍，且事先報經本府或公所核備者不在此限。\n其他施工規模得比照前項規定辦理。\n第四條\n建築物施工中發生公共安全事件者，承造人除應立即停工，並應報請備查\n外，專任工程人員及工地負責人應確實檢查，並請監造人鑑定，鑑定之情\n況依下列規定辦理。\n一  經鑑定不危及公共安全者，經報請本府或公所核備後，准予繼續施工\n。\n二  經鑑定有危及公共安全者，監造人應即通知承造人及起造人改善加強\n防護或協調修護賠償；惟經監造人、承造人及專任工程人員勘查認為\n停工會使損鄰擴大且有緊急搶救必要者，得由起、監、承造人即刻採\n取維護補救措施，直至無影響公共安全之虞為止；並報經本府或公所\n核備後，准予繼續施工，如承造人及起造人不依指示辦理，監造人應\n即報請本府或公所依建築法第五十八條之規定處理。\n第五條\n監造人對於發生損鄰事件時，應於本府或公所通知十日內依前條規定出具\n安全鑑定書。\n第六條\n起、承造人應就損鄰事件主動與受損戶協調修復賠償事宜，就賠償事宜未\n能達成協議或和解者，雙方當事人得委託鑑定單位鑑定，本府或公所以該\n鑑定單位出具之鑑定報告作為後續協調及辦理提存之依據。\n鑑定單位應合於下列規定：\n一  相關公會：\n組織章程應經其相關事業主管機關核准備查，業務項目核准內容應包\n括受理委託辦理各種建築、土木工程鑑定估價。主持鑑定人員應具備\n建築師或專業技師資格，並以公會名義出具鑑定報告。\n二  學術研究機構：\n(一) 法人組織之建築、土木學術研究機構：組織章程應包括相關營建研\n究項目及經其事業主管機關核准備查有案。主持鑑定人員應具建築\n師或專業技師資格，並以機構名義出具鑑定報告。\n(二) 其他學術研究機構：教育部立案設有建築、土木相關科系研究所或\n附設之學術單位並以學校名義出具鑑定報告。\n第七條\n起、承造人委託鑑定單位辦理鑑定時，如受損戶經鑑定單位通知三次仍無\n法配合完成鑑定者，則由受委託之鑑定單位出具報告書，送請本府或公所\n備查並副知受損戶，本府或公所得撤銷列管，並通知雙方當事人逕循司法\n途徑解決。\n第八條\n損壞責任如經鑑定非屬施工造成損壞，或鄰房房屋邊緣線與工程開挖境界\n線間之水平距離大於開挖深度四倍以上並經專任工程人員及監造人認定非\n屬本工程造成者，本府或公所得以撤銷列管；如由異議人自覓鑑定單位鑑\n定並出具損壞鑑定報告，再據以處理。\n第九條\n建築物施工逾屋頂版或屋架申報勘驗 (建築物結構體完成) 一個月始提出\n損鄰事件陳情者，由本府或公所發函監、承造人及專任工程人員勘查，經\n監造人及專任工程人員認定無危及公共安全者，不適用本規則，由爭議雙\n方逕循司法途徑解決。\n第十條\n建築物發生損鄰事件，雙方自行協調或委託當地鄉鎮市公所調解委員會調\n解，協調達成協議，雙方應作成和解書或調解書，函請本府或公所備查銷\n案，或併案申請使用執照。\n前項和解書或調解書向本府或公所備查銷案時應檢附相關建物謄本。如該\n建築物無產權登記亦無使用執照，即以陳情人為和解人；惟陳情人須附合\n法房屋證明文件或切結書切結建築物為其所有。\n第十一條\n經各鄉鎮市公所調解委員會代為協調不成，雙方當事人得檢具協調不成立\n證明文件及損害鑑定報告，向本縣建築爭議事件評審委員會申請協調或評\n審，陳情人或受損戶經本府通知而不出席達二次者，由雙方循司法途徑解\n決，撤銷列管。\n第十二條\n經各鄉鎮市公所調解委員會受理申請代為協調不成，且經監造人鑑定無危\n及公共安全者，雙方仍未達成協議，本縣建築爭議事件評審委員會得決議\n由起、承造人之一，依鑑定單位鑑估受損房屋修復賠償費用提存法院，以\n受損戶名義提存法院後，得檢據相關文件依法請領使用執照；損壞鄰房修\n復賠償費用提存法院數額表 (如附表一) 分段累計確定數額，受損戶如有\n異議應循司法途徑解決。\n如雙方各自申請之鑑定報告其修復賠償金額不一致時，由建築爭議事件評\n審委員會決議之。\n圖表附件：\n附表一.odt\n第十三條\n建築爭議事件評審委員會認有必要時，得要求鑑定單位派員列席說明。\n第十四條\n本規則自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:GL000116","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"公發布日":"民國 92 年 06 月 17 日","法規名稱":"彰化縣建築物施工中發生公共安全及建築爭議事件協調處理規則","法規體系":"建設類","發文字號":"府法制字第0920111738號"},"promulgation_date":"2003-06-17","revision_date":"2003-06-17","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=GL000116","status":"unknown","title":"彰化縣建築物施工中發生公共安全及建築爭議事件協調處理規則","last_checked_at":"2026-10-06T17:26:43+08:00","last_success_at":"2026-10-06T17:26:43+08:00","verification_status":"fetched","content_hash":"8b45f8bca17893e0e0000c6c05c7bbbec9ee678f2f9ec7fff5c9f5072a75fde1","history":[{"observed_at":"2026-10-06T17:26:43+08:00","content_hash":"8b45f8bca17893e0e0000c6c05c7bbbec9ee678f2f9ec7fff5c9f5072a75fde1","change_kind":"initial","revision_date":"2003-06-17"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=887&id=GL000116&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"彰化縣政府建築工程地震後檢查及回報作業流程.ODT","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=137&id=FL087989&type=LAW"},{"name":"彰化縣政府建築工程颱風警報發布期間防護措施檢查及回報作業流程.ODT","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=138&id=FL087989&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"一、彰化縣政府（以下簡稱本府）為維護建築物施工場所之公共安全、公\n共交通，促進市容觀瞻，參照建築法第五十八條、第六十一條、第六\n十三條至第六十九條、第八十九條及建築技術規則建築設計施工編第\n八章之規定訂定本要點。\n二、（工地措施）凡從事建築物之新建、增建、改建、修建或拆除等行為\n時，施工場所應有維護安全、防護危險及預防災害之設備措施。其圖\n說應依建築法第五十四條及彰化縣建築管理自治條例第二十六條之規\n定申請建築執照核發單位備查，拆除時亦同。\n前項安全防護措施應於各階段工程施工前按圖說施作完妥，由承造人\n會同監造人查核符合規定後併同申報勘驗文件簽章檢同現場照片送達\n建築執照核發單位次日方得繼續施工。建築執照核發單位得隨時勘驗\n作成紀錄。\n三、（安全圍籬之設備內容）\n（一）材料：建築物施工場所基地四週應以鋼鐵或金屬板（一．二○公厘\n厚以上），木板（一．五○公分厚以上），夾板（○．九○公分厚\n以上）等材料設置高度在一．八○公尺以上定著基地上之密閉式或\n漏空部分未超過六公分之安全圍籬，臨接道路長度未達六公尺者得\n將圍籬改為活動式。\n道路轉角或轉彎處兩側 10 公尺內之圍籬自地面 80 公分以上位置\n應為網狀圍籬，另屬環保法令第 1  級之工程，其高度不得低於 2\n.4  公尺。\n（二）設置範圍：應於施工場所四周設置。但四周空曠未開闢且無鄰房居\n住地區或以既有之構造物替代，無礙於公共安全經建築執照核發單\n位核准者不在此限。\n（三）底座：安全圍籬底部和地表間空隙，須設金屬板或混凝土防溢座，\n使基地用水不致溢流到基地外。\n（四）施工門：車輛出入設置鐵捲門或軌道式活動密閉門，除車輛出入外\n應隨時封閉，並不得任意遷移。\n（五）警示標誌：於圍籬突出轉角處張貼警示標誌圖樣。\n（六）警示燈：於圍籬突出處、轉角、施工大門處設立警示燈，並於適當\n間隔設置照明設備，以利夜間人車通行安全。\n（七）顏色：為加強市容美化，密閉式圍籬之板面得參考本府提供之圍籬\n美化圖片（如附圖一）並視工地狀況設計靈活運用。但自行設計圖\n案經建築執照核發單位核准者不在此限。\n（八）其他：結構體完成，鷹架圍籬拆除後，整理環境時，於借用道路範\n圍內，應採取完善之維護措施，並隨時清掃整理，以維持工地整潔\n。\n四、（機具材料置放）建築物施工時，其建築材料、施工機具及廢棄物之\n堆放應在其安全圍籬內，其所使用具粉塵逸散性之工程材料、砂石、\n土方或廢棄物，應採行覆蓋防塵布、防塵網及配合定期噴灑化學穩定\n劑。如地下室全部開挖者，應考慮分段施工或於擋土支撐上方架設棧\n橋（供施工機具運轉）、構臺（供材料置放）以利工程施工。但開挖\n面積在五百平方公尺以下或基地情形特殊且無其他替代方法可以施工\n時，其運轉機具或擋土構材得報經核准限時借用道路。\n五、（鷹架、護網、帆布、斜籬）：二層以上建物施工或拆除時，其施工\n鷹架外緣距離建築線或地界線不足二．五○公尺或五層以上建築物施\n工時，應設置防止物料向外飛散或墮落之措施。\n（一）鷹架設置：六層以上建築物施工時應使用鋼管鷹架或鋼框鷹架，其\n鷹架柱腳底，應襯厚木條或採取其他防沈措施。但其施工場地情況\n特殊或其未臨接道路部分，無礙於公共安全經核准者不在此限。\n（二）護網：鷹架外部應置二十號以上鍍鋅鐵絲網或一．三公厘徑尼龍塑\n膠網（網格不得大於十五公厘，搭接長度不得小於二○公分）。\n（三）帆布護籬：鷹架外部於四樓版以下應另加厚○．二二公厘帆布圍護\n。\n（四）斜籬：鷹架斜籬應使用框架式以○．九公分厚夾板或一．二公厘鋼\n板設置於二樓板處並每五層設置一處，突出鷹架寬度約二公尺。\n六、（安全走廊範圍）：凡建築基地臨接經建築執照核發單位指定之重要\n道路、地區或面前道路寬度在十二公尺以上，其臨接道路長度在十公\n尺以上者，應於安全圍籬外設置有頂蓋之行人安全走廊，以銜接基地\n相鄰之騎樓或人行道。\n七、（安全走廊規格）：行人安全走廊之設置應依左列規定辦理：\n（一）安全走廊之淨寬至少一．三○公尺，淨高至少二．四○公尺，其使\n用材料為鋼鐵料、木料、金屬料，應堅固安全美觀，其頂面應設置\n鋼板（厚度一．五○公厘以上）頂側線應設置二十公分寬以上之封\n板，以防止物料墜落。\n（二）道路旁設有人行道寬度大於一．三○公尺者，其安全走廊之寬度應\n與人行道寬度相同。但路旁行道樹得扣除占用範圍。\n（三）安全走廊上方，得加設臨時工房或供材料置放之貨櫃（須檢討結構\n安全），其造型應整齊美觀，層高不得超過四公尺，安全走廊內不\n得設置任何阻礙物，並應舖設適當材料使地面齊平，以利通行。\n（四）安全走廊內應設置照明設備。\n（五）安全走廊除供施工場所之車輛進出口處（地坪加○．九公分厚鐵板\n）外，應力求貫通不得中斷，且不得任意遷移拆除。\n（六）行人安全走廊應於該建築物全部完工後拆除。\n八、（吊高設備）建築物施工場所使用起重或吊高設備作業時，應考慮其\n安全性，並派員身著鉻黃色衣服，手持指揮旗疏導交通，禁止任意占\n用道路，妨礙通行。\n九、（保持道路清潔）建築工程地區有污損周圍路段者，應即以混凝土或\n瀝青混凝土等材料暫時加以舖平並清除廢棄物等，以維施工環境清潔\n。工地須設置沖洗設備；車輛之輪胎應刷洗乾淨後始得駛離工地，沿\n途不得滴漏污水遺落污物。\n十、（騎樓打通）建築物應設置法定騎樓之施工場所，除騎樓地面經核准\n者外，應保持與鄰側騎樓地及前側人行道面順平；並應於二樓板混凝\n土灌注一個月內打通騎樓及在騎樓內側加做圍籬，以供公眾通行。但\n鄰接地騎樓未打通前或案情特殊經建築執照核發單位核准延長者不在\n此限。\n十一、（衛生設備）建築物施工場所，如於基地內設置工寮及臨時廁所時\n，應隨時保持清潔，其臨時廁所應有簡易化糞池設備，以維公共衛\n生。\n十二、（施工場所出入口）建築物施工場所四周明顯處及車輛出入口處應\n設置安全警示燈、警示標誌，以提醒行人車輛注意，車輛進出之際\n，應派身著鉻黃色衣服，手持旗號之引導者，在場整理交通，車輛\n進出口位置應距離道路交叉口、轉角、人行斑馬線、消防栓在五公\n尺以上，火警警報器三公尺以上。但情況特殊，經建築執照核發單\n位核准者不在此限。\n十三、（垃圾清除）建築物施工場所除利用電梯孔、管道間清運垃圾外，\n應設置垃圾清除滑落孔道或加設防護裝置之垃圾滑槽，以防止垃圾\n自上落下時四處飛散。\n十四、（安全護欄）建築物施工場所可能發生跌落事故之處所，如昇降機\n坑孔道、吊孔各樓層之開口、樓梯等應加揭示危險標誌並設置一．\n一○公尺以上之安全護欄。\n十五、（排水護蓋材料）建築物施工場所應規劃基地排水設施，基地四周\n原有排水溝應隨時疏濬保持暢通，其車輛出入口處用鐵板護蓋蓋於\n水溝上，其餘得以適當材料護蓋。\n十六、（污泥處理）建築物施工場所，如有反循環基椿、連續壁、預壘排\n椿、磨石子等工程產生之污泥者，應設置足夠容量之污泥沈澱處理\n槽或機械處理設備，且應待污泥凝結沉澱後，其上方之廢水始得排\n入現有排水溝，凝結沈澱之污泥並應設法運離工地。\n十七、（噪音、震動作業）建築工程進行時，應依噪音管制法令有關規定\n管制噪音。對違反噪音管制情形嚴重者，建築執照核發單位即知會\n環保單位加強巡查取締。\n十八、（公共設施防護）建築物施工場所之周圍道路、現有巷道、鄰近房\n屋、排水溝渠、下水道與人孔、給水管與止水栓、瓦斯管、消防栓\n、電力電纜、電話線、軍用通訊電纜、交通號誌、公車站牌、電桿\n、行道樹、人行地下道、陸橋、公共護欄、路燈等公共設施均予詳\n加調查，隨時與有關主管單位協調養護、防護、迂迴施工、臨時移\n設等對策，以防止導致鄰近地區發生缺電、瓦斯電氣、斷話、火警\n等情況。\n十九、（地下室支撐作業）為避免因建築工程挖掘地基或任意取土導致鄰\n屋及地下埋設物之傾斜破損等營建公害，承造人於地下室開挖時其\n擋土支撐作業應依營造安全衛生設施標準規定辦理並應注意下列事\n項：\n（一）靠近鄰房挖土，其擋土工法應校核現地質狀況及地下水情形與原\n設計是否相符，並於施工時派專人隨時檢查並改善擋土設備，以\n避免附近道路與鄰房發生崩塌沈陷。於必要時應先設法改善鄰房\n基礎使成穩定後，再行開挖地下室。\n（二）地下室開挖如採用自然坡度施工者，依下列各項辦理：\n1.鄰房保留足夠安全間距。\n2.採取其他適當措施者外，開挖面之放置時間限三星期內，開挖\n面與坡肩須有適當保護措施，坡間保護寬度應與開挖深度相同\n，且其地表面不可加載荷重。\n3.地表面部分發生龜裂時，應即以塑膠布覆蓋龜裂部分或採取其\n他適當措施，並繼續觀察，倘繼續擴大時，應迅即回填，另行\n採用其他擋土工法。\n（三）隨時注意開挖中有無發生異常出水現象並設置排水溝以防止附近\n雨、污水流入開挖區內，且應設置坑池或點井，以利排水。\n（四）搬運擋土材料或結構鋼材等長尺度之構材時，應注意其上下及周\n圍之行人及車輛安全，並派專人身著鉻黃色衣服，手持指揮旗在\n場整理交通。\n（五）設在擋土支撐上之棧橋，構臺應有足夠的強度與支持力，並應隨\n時加以補強。\n二十、（顏色與標示板）安全圍籬、安全走廊、帆布護籬等設施之顏色以\n整齊劃一為原則，且須定期維護。其油漆部分最少半年油漆一次，\n帆布、護網有破損時隨時修護整理，並於車輛進出口處設置標示板\n（七十五公分＊一五○公分）標示工程名稱、建造執照號碼、設計\n人、監造人、承造人（含主任技師）、載明營建工程空氣污染防制\n費徵收管制編號、工地負責人姓名、電話及當地環保機關公害檢舉\n電話號碼等有關工程內容摘要外，不得設置與工程無關之任何廣告\n。\n二十一、建築工程施工期間如遭遇颱風或地震等重大天然災害，其事前通\n報及事後檢查機制，依災害種類如下：\n颱風：颱風海上警報發布後，各建築工程承、監造人應通知施工\n中建築工地進行防颱整備及鷹架、模板支撐與高空架作車等臨時\n措施檢查，如有不足應立即加強；颱風警報解除後，各建築工程\n之承、監造人應進行工地巡查，就其安全圍籬、鷹架、帆布及材\n料基地四周排水是否通暢等逐一檢視，如有破壞應立即修復並副\n知本府。\n地震：地震發生後，各建築工程之承、監造人應即進行鷹架、模\n板支撐及高空架作車等臨時措施檢查；地震震度 4  級以上地區\n，地震發生前 7  日內有澆置混凝土行為者，應依據內政部「結\n構混凝土施工規範」規定進行檢查或補強，經勘估有公共安全之\n虞者進行補強時，應於該階段勘驗申報時一併檢附補強報告，並\n報本府備查。\n前項各款作業流程及自主檢查表由本府另定之。\n二十二、（罰則）違反以上各點規定者，依建築法第八十九條之規定處理\n。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL087989","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"修正日期":"民國 105 年 12 月 15 日","公發布日":"民國 93 年 01 月 15 日","圖表附件":"彰化縣政府建築工程地震後檢查及回報作業流程.ODT 彰化縣政府建築工程颱風警報發布期間防護措施檢查及回報作業流程.ODT","法規名稱":"彰化縣建築物施工中管制要點","法規體系":"建設類","發文字號":"府建管字第1050426418號"},"promulgation_date":"2004-01-15","revision_date":"2016-12-15","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL087989","status":"unknown","title":"彰化縣建築物施工中管制要點","last_checked_at":"2026-10-06T17:26:29+08:00","last_success_at":"2026-10-06T17:26:29+08:00","verification_status":"fetched","content_hash":"3ac7227a47792dc6fa7a0271174c38d0ea81812e34c10a824cbdebd2bb6f63c9","history":[{"observed_at":"2026-10-06T17:26:29+08:00","content_hash":"3ac7227a47792dc6fa7a0271174c38d0ea81812e34c10a824cbdebd2bb6f63c9","change_kind":"initial","revision_date":"2016-12-15"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=137&id=FL087989&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=138&id=FL087989&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"附表一：損壞鄰房修復賠償費用提存法院數額表.DOC","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=136&id=FL049410&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"第 1 條\n彰化縣政府（以下簡稱本府）為處理建築物施工損壞鄰房事件，特制定本\n自治條例。\n第 2 條\n建築物設計人對於施工涉及公共安全之防範措施，應預先為周全之考慮。\n建築物施工中，起造人、承造人、監造人對於公共安全應有周全之防護措\n施，如有發生侵害他人財產或肇致危險或傷害他人等情事，建築物起造人\n、設計人、監造人、承造人（含負責人及專任工程人員）應依建築法及營\n造業法規定分別負其責任。\n第 3 條\n本自治條例所稱鑑定單位，應合於下列規定之一：\n一、相關專業公會：組織章程應經其相關事業主管機關登記許可，業務項\n目核准內容應包括受理委託辦理各種建築、土木工程鑑定估價。主持\n鑑定人員應具備建築師或專業技師資格，並以公會名義出具鑑定報告\n。\n二、學術研究機構：\n（一）、法人組織之建築、土木學術研究機構：組織章程應包括相關營建\n研究項目及經其事業主管機關登記許可有案。主持鑑定人員應具\n建築師或專業技師資格，並以機構名義出具鑑定報告。\n（二）、其他學術研究機構：教育部立案設有建築、土木相關科系研究所\n或附設之學術單位並以學校名義出具鑑定報告。\n第 4 條\n施工建築物達六層以上或有開挖地下室者，為界定將來損鄰責任，起造人\n及承造人應於放樣前會同監造人勘查基地現況，向鑑定單位申請鄰房現況\n調查（至少以基礎開挖深度二倍以上距離內所有鄰房之各層範圍），作成\n報告於申報放樣勘驗時一併檢附備查。但經監造人及專任工程人員認定免\n鑑定或自訂鑑定範圍，且事先報經本府或鄉（鎮、市）公所核備者，不在\n此限。\n鄰房所有權人拒絕會同辦理鄰房現況調查，嗣後提出損鄰事件陳情者，本\n縣建築爭議事件評審委員會得逕依損壞鑑定報告書評審。\n其他建築物施工，得比照前二項規定辦理。\n第 5 條\n建築物施工中發生公共安全事件者，承造人除應立即停工，並應報請備查\n外，專任工程人員及工地負責人應確實檢查，並請監造人鑑定。\n前項之鑑定，應視鑑定之情況依下列規定辦理：\n一、經鑑定無危及公共安全者，於報請本府或鄉（鎮、市）公所核備後，\n准予繼續施工。\n二、經鑑定有危及公共安全者，監造人應即通知承造人及起造人改善加強\n防護並協調修護賠償。但經監造人、承造人及專任工程人員勘查認為\n停工會使損鄰擴大且有緊急搶救必要者，得由起、監、承造人即刻採\n取維護補救措施，直至無影響公共安全之虞為止，並報經本府或鄉（\n鎮、市）公所核備後，准予繼續施工。如承造人及起造人不依指示辦\n理，監造人應即報請本府或鄉（鎮、市）公所依建築法第五十八條規\n定辦理。\n第 6 條\n發生損鄰事件時，本府或鄉（鎮、市）公所得通知監造人限期十日內依前\n條規定出具安全鑑定書。\n第 7 條\n起、承造人應就損鄰事件主動與受損戶協調修復賠償事宜。\n前項就賠償事宜未能達成協議或和解者，雙方當事人得委託鑑定單位鑑定\n，本府或鄉（鎮、市）公所以該鑑定單位出具之鑑定報告作為後續協調及\n辦理提存之依據。\n第 8 條\n起、承造人委託鑑定單位辦理鑑定時，如受損戶經鑑定單位通知三次仍無\n法配合完成鑑定者，由受委託之鑑定單位出具報告書，送請本府或鄉（鎮\n、市）公所備查並副知受損戶，本府或鄉（鎮、市）公所得逕為撤銷列管\n，並通知雙方當事人循司法途徑解決，或提交本縣建築爭議事件評審委員\n會評審決議通過後，由起造人繼續施工並依法請領使用執照。\n第 9 條\n鄰房損壞責任如經鑑定非屬施工所造成，或鄰房房屋邊緣線與工程開挖境\n界線間之水平距離大於開挖深度四倍以上並經專任工程人員及監造人認定\n非屬本工程造成者，本府或鄉（鎮、市）公所得撤銷列管。\n前項情形，如陳情人提出異議，得自覓鑑定單位鑑定並出具損壞鑑定報告\n，認定已危及公共安全且係由該建築工程所造成者，應由異議人申請本縣\n建築爭議事件評審委員會評審。\n第 10 條\n有下列情形之一者，由本府或鄉（鎮、市）公所發函監、承造人及專任工\n程人員勘查，經監造人及專任工程人員認定無危及公共安全者，逕行撤銷\n列管，由爭議雙方逕循司法途徑解決：\n一、鄰房受損部分不屬於合法建築物。\n二、建築物施工逾屋頂版或屋架申報勘驗（建築物結構體完成）一個月始\n提出損鄰事件陳情。\n第 11 條\n建築物發生損鄰事件，雙方當事人應自行協調或聲請當地鄉（鎮、市）公\n所調解委員會調解。調解如達成協議，雙方應作成和解書或調解書，送交\n本府或鄉（鎮、市）公所備查銷案，並依法申請使用執照。\n前項和解書或調解書向本府或鄉（鎮、市）公所備查銷案時，應檢附相關\n建物謄本。如該建築物無產權登記亦無使用執照，即以陳情人為和解人。\n前項陳情人應檢附合法房屋證明文件，並以切結書切結建築物為其所有。\n第 12 條\n損鄰事件經自行協調不成或經各鄉（鎮、市）公所調解委員會調解不成立\n，雙方當事人得檢具協調或調解不成立證明文件及損害鑑定報告，向本縣\n建築爭議事件評審委員會申請協調。\n前項協調，陳情人或受損戶經本府通知而不出席達二次以上或協調不成立\n者，由雙方當事人循司法途徑解決。\n第 13 條\n前條協調程序，經監造人鑑定無危及公共安全者，本縣建築爭議事件評審\n委員會得決議由起、承造人之一，依鑑定單位鑑估受損房屋修復賠償費用\n提存法院，以受損戶名義提存法院後，檢據相關文件依法請領使用執照。\n但雙方當事人各自申請之鑑定報告其修復賠償費用不一致時，由建築爭議\n事件評審委員會決議之。\n損壞鄰房修復賠償費用提存法院數額表如附表一，並應分段累計確定數額\n，受損戶如有異議應循司法途徑解決。\n圖表附件：\n附表一：損壞鄰房修復賠償費用提存法院數額表.DOC\n第 14 條\n建築爭議事件評審委員會認有必要時，得要求鑑定單位或相關單位派員列\n席說明。\n第 15 條\n本自治條例自公布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL049410","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"修正日期":"民國 114 年 01 月 20 日","公發布日":"民國 96 年 07 月 19 日","法規名稱":"彰化縣建築物施工損壞鄰房事件處理自治條例","法規體系":"建設類","發文字號":"府行法字第1140019802號"},"promulgation_date":"2007-07-19","revision_date":"2025-01-20","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL049410","status":"unknown","title":"彰化縣建築物施工損壞鄰房事件處理自治條例","last_checked_at":"2026-10-06T17:26:36+08:00","last_success_at":"2026-10-06T17:26:36+08:00","verification_status":"fetched","content_hash":"ddc1cd90c7cfd969d8cd08cae056c94bb79018c5c6cd32b7440e7afd25b7714a","history":[{"observed_at":"2026-10-06T17:26:36+08:00","content_hash":"ddc1cd90c7cfd969d8cd08cae056c94bb79018c5c6cd32b7440e7afd25b7714a","change_kind":"initial","revision_date":"2025-01-20"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=136&id=FL049410&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"彰化縣政府","category":"建築管理相關","content":"第 1 條\n為充分利用彰化縣日照，有效管理太陽光電發電設備，爰依建築技術規則\n總則編第三條之二第一項規定訂定本辦法。\n第 2 條\n本辦法所稱太陽光電發電設備，指太陽能光電板、支架（含欄杆）、維修\n設施及轉換太陽光能為電能之必要設施。\n第 3 條\n設置太陽光電發電設備，除依設置再生能源設施免請領雜項執照標準規定\n免申請雜項執照者外，應依建築法規定申請雜項執照，並報中央主管機關\n同意備查。\n第 4 條\n建築物屋頂、屋頂突出物設置太陽光電發電設備，符合下列各款情形者，\n得免計入屋頂突出物面積及建築物高度：\n一  太陽光電發電設備從屋頂面起算高度在四點五公尺以下，水平投影面\n積之和在建築面積百分之五十以內。但其水平投影面積之和未逾三十\n平方公尺者，不在此限。\n二  太陽光電板水平投影面積占太陽光電發電設備水平投影面積百分之七\n十以上。\n三  太陽光電發電設備設置於屋頂突出物時，其與屋頂突出物高度合計不\n得超過九公尺。\n第 5 條\n依本辦法設置之太陽光電發電設備，其消防安全部分應依消防法相關法令\n規定辦理。\n第 6 條\n建築物屋頂設置太陽光電發電設備，不得妨害四周建築物已申請設置太陽\n光電發電設備之功能。\n第 7 條\n依本辦法設置之太陽光電發電設備，其下方空間不得作為居室使用。\n違反前項規定者，依建築法規定處理。\n第 8 條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL086209","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"公發布日":"民國 106 年 07 月 19 日","法規名稱":"彰化縣建築物設置太陽光電發電設備管理辦法","法規體系":"建設類","發文字號":"府法制字第1060241789號"},"promulgation_date":"2017-07-19","revision_date":"2017-07-19","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL086209","status":"unknown","title":"彰化縣建築物設置太陽光電發電設備管理辦法","last_checked_at":"2026-10-06T17:26:40+08:00","last_success_at":"2026-10-06T17:26:40+08:00","verification_status":"fetched","content_hash":"fa3c9c8c57f378cb737650125ec27b3a00b93510dc95b4f41fe19041e02e7658","history":[{"observed_at":"2026-10-06T17:26:40+08:00","content_hash":"fa3c9c8c57f378cb737650125ec27b3a00b93510dc95b4f41fe19041e02e7658","change_kind":"initial","revision_date":"2017-07-19"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"彰化縣政府","category":"建築管理相關","content":"第1條\n依規費法第十條第一項規定，訂定本標準。\n第2條\n新建或增建公共建築物申請無障礙設施勘檢，起造人應依下列規定繳納勘\n檢費：\n一  樓地板面積未達五百平方公尺者：新臺幣(下同)一萬元。\n二  樓地板面積五百平方公尺以上者：二萬元。\n依前項繳納勘檢費後，如經勘檢未符規定，得免費申請複檢一\n次。\n第3條\n既有公共建築物申請無障礙設施替代改善計畫審查，建築物所\n有權人或使\n用人應依下列規定繳納審查費：\n一  替代改善一項者，一萬五千元。\n二  替代改善二項以上者，三萬元。\n依前項規定繳納審查費後，如經審查未符規定，申請複審得免\n計費且次數\n不限。\n第4條\n非公共建築物申請勘檢或申請替代改善計畫之審查者，準用前二條之收\n費標準。\n第5條\n公有建築物申請無障礙設施勘檢及既有公有建築物申請無障礙\n設施替代\n改善計畫審查者，免繳勘檢費及審查費。\n第6條\n依本標準繳納之勘檢費或審查費，於主管機關實施勘檢或審查\n前撤回申請者，得申請無息退還。\n第7條\n依本標準收取之勘檢費及審查費，應納入彰化縣建築物無障礙\n設備與設施改善基金專戶。\n第8條\n本標準自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:GL000189","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"公發布日":"民國 109 年 04 月 30 日","法規名稱":"彰化縣建築物設置無障礙設施勘檢費及替代改善計畫審查費收費標準","法規體系":"建設類","發文字號":"府法制字第109142826號令"},"promulgation_date":"2020-04-30","revision_date":"2020-04-30","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=GL000189","status":"unknown","title":"彰化縣建築物設置無障礙設施勘檢費及替代改善計畫審查費收費標準","last_checked_at":"2026-10-06T17:26:39+08:00","last_success_at":"2026-10-06T17:26:39+08:00","verification_status":"fetched","content_hash":"8616b56102aaee77e6063694a0e7d9fd8617864cd9d84d3e56aab4766014147e","history":[{"observed_at":"2026-10-06T17:26:39+08:00","content_hash":"8616b56102aaee77e6063694a0e7d9fd8617864cd9d84d3e56aab4766014147e","change_kind":"initial","revision_date":"2020-04-30"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"彰化縣政府","category":"建築管理相關","content":"第 1 條\n本辦法依建築法第一百零二條之一第二項規定訂定之。\n第 2 條\n建築物依規定應附設停車空間。但新建或增建之建築物，其建築基地面積\n未達三百五十平方公尺，且建築基地位於都市計畫停車場公共設施用地或\n政府興建停車場周圍一千公尺半徑範圍內，並有下列各款情形之一者，得\n由起造人申請以繳納代金方式代之，免予附設：\n一、經扣除騎樓或退縮地部分之深度或寬度任一邊未達十公尺者。\n二、依都市計畫法令或建築技術規則規定，應附設之停車空間在五輛以下\n者。\n三、建築基地因都市計畫限制車輛無法通行進入者。\n四、建築基地臨接之道路坡度超過一比六者。\n第 3 條\n建築物變更使用有下列各款情形之一者，得由所有權人申請以繳納代金替\n代應增設之停車空間：\n一、建築物因辦理變更使用執照所需檢討附設停車空間者。\n二、已領得使用執照建築物，設置於地下層停車空間因結構補強或增設必\n要機電設備，致法定停車空間不足者。\n第 4 條\n應繳納之代金計算標準，依下列計算公式核算：應繳納代金之總額＝【２\nｘ建築物各構造類別法定工程造價（元╱平方公尺）＋建築基地當期公告\n現值（元╱平方公尺）ｘ建築基地面積（平方公尺）╱建築物總樓地板面\n積（平方公尺）】ｘ２５（平方公尺）ｘ申請免附設之車位數ｘ使用分區\n係數。\n前項使用分區係數於都市計畫商業區者為一‧二，位於其他使用分區者為\n一。\n第 5 條\n建築物附設停車空間繳納代金之申請，應檢具同意書併同建造執照（含變\n更設計）或變更使用執照申請書，向彰化縣政府（以下簡稱本府）提出。\n前項代金，應於領取使用執照或變更使用執照前繳交。\n第一項之同意書應載明以代金所興建之停車空間，應登記為彰化縣所有。\n第 6 條\n申請人繳交之代金，應納入本府停車場作業基金，並由目的事業主管機關\n統籌應用於集中興建及管理維護停車空間等相關用途。\n第 7 條\n依本辦法繳納代金興建之停車空間，由本府管理維護，必要時得委託其他\n機關、民間團體或個人經營管理之。\n第 8 條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL042572","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"公發布日":"民國 95 年 03 月 24 日","法規名稱":"彰化縣建築物附設停車空間繳納代金及管理使用辦法","法規體系":"建設類","發文字號":"府法制字第0950057370號"},"promulgation_date":"2006-03-24","revision_date":"2006-03-24","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL042572","status":"unknown","title":"彰化縣建築物附設停車空間繳納代金及管理使用辦法","last_checked_at":"2026-10-06T17:26:42+08:00","last_success_at":"2026-10-06T17:26:42+08:00","verification_status":"fetched","content_hash":"36113e28e56046ad56f954fac5e3288f5521930fe8fb8361503d5be8c0dee480","history":[{"observed_at":"2026-10-06T17:26:42+08:00","content_hash":"36113e28e56046ad56f954fac5e3288f5521930fe8fb8361503d5be8c0dee480","change_kind":"initial","revision_date":"2006-03-24"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"附件.DOC","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=135&id=FL026531&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"第 1 條\n本自治條例依建築法（以下簡稱本法）第一百零一條規定制定之。\n第 2 條\n建築基地面臨計畫道路、廣場、市區道路、公路或合於本自治條例規定之\n現有巷道者，得申請指定建築線。但都市計畫農業區及區域計畫各種分區\n之農牧用地、甲種建築用地，未臨接道路基地其總樓地板面積六百六十平\n方公尺以下者，得申請建築，於本自治條例施行後分割者，應合併計算。\n申請指定建築線者，應繳納規費及建築線指定手續費，其數額由彰化縣政\n府（以下簡稱本府）定之。\n本府指定建築線應自收件次日起八日內辦理完竣，並將指定圖發給申請人\n。但面臨公路須會同道路主管機關辦理者為十五日。\n道路或廣場開闢完成，其境界線經本府確定為建築線者，應於一個月內公\n告得免申請指定建築線，其有變更時應即公告修正。\n第 3 條\n申請指定建築線應填具申請書，並檢附下列文件：\n一、地籍套繪圖應描繪以一個街廓為原則，並應標明建築基地之地段、地\n號、方位、基地範圍及鄰近之各種公共設施、道路之寬度。\n二、基地位置圖應簡明標出基地位置、附近道路、機關學校或其他明顯建\n築物之相關位置。\n三、現況圖應標明地形、鄰近現有建築物、道路及溝渠，其比例尺不得小\n於地籍圖。\n第 4 條\n建築基地面臨現有巷道，應申請建築線指示。\n前項所稱現有巷道，指下列情形之一：\n一、供公眾通行，具有公用地役關係且供二戶以上通行之巷道。\n二、有公益上或實質必要應予維持供公眾通行之巷道，得經村里長證明確\n應繼續保留，經本府或公所認定無礙公共交通者。\n三、已開闢之私設通路出具經公證之土地所有權人同意書無條件同意該私\n設通路供公眾通行使用。\n四、土地所有權人捐獻土地作為道路使用，經依法完成土地移轉登記為公\n有者。\n前項第一款所稱供公眾通行之巷道，由本府就其通行情形及公益上需要認\n定之。\n申請指示建築線基地之鄰近現有巷道寬度、地形地貌由申請人或設計人依\n第二項規定於申請建築線指示成果圖上簽章負責。\n第 5 條\n面臨現有巷道之基地，其建築線之指定，應依下列規定辦理：\n一、巷道為單向出口長度在四十公尺以下，雙向出口長度在八十公尺以下\n，寬度不足四公尺者，以該巷道中心線為準，兩旁均等退讓，以合計\n達到四公尺寬度之邊界線作為建築線；巷道長度超過上開規定者，兩\n旁亦應均等退讓，以合計達到六公尺寬度之邊界線作為建築線。但面\n臨工業區內現有巷道之基地，應以合計達八公尺寬度之邊界線作為建\n築線，現有巷道臨接排水溝寬達一‧五公尺以上者，其退讓由排水溝\n內緣單邊退讓。\n二、未達二公尺及地形特殊不能通行車輛者，前款巷道之寬度得分別減為\n三公尺及四公尺。\n三、建築基地正面臨接道路，側面或背面臨接現有巷道者，於申請指定建\n築線時，應一併指定該巷道之建築線，其側面或背面在現有道路部分\n及退讓之土地，得以空地計算。\n四、現有巷道之寬度大於四公尺或六公尺者，仍應保持原有之寬度。\n五、建築基地與都市計畫道路間夾有具公用地役關係之現有巷道，得以現\n有巷道之邊界線作為建築線，並納入都市計畫道路。\n現有巷道寬度計算方法如下：\n一、二旁或一旁有排水溝或斷崖，未加蓋之水溝以內緣或斷崖邊緣為準，\n計算寬度。\n二、無排水溝者，以該巷道兩旁建築物（或圍牆）間之最小淨距離為準，\n計算寬度。\n第一項第一款退讓土地，不得以空地計算。\n第一項第一款所稱單向出口係指巷道僅一端接通計畫道路者。\n都市計畫區內巷道之長度應自與計畫道路連接之出口起算。\n第 6 條\n現有巷道之改道或廢止，應向本府申請之，本府應將廢止或改道之路段公\n告一個月，徵求異議。\n依前項申請改道者，除應檢附新設巷道與現有巷道位置圖外；並應檢附新\n設巷道土地所有權人出具供公眾通行及變更地目為道之同意書，或捐獻土\n地為道路使用之同意書。\n現有巷道改道後之新巷道寬度應合於前條規定。\n新巷道自開闢完成供公眾通行之日起，其土地所有權人不得為違反供公眾\n通行之使用，原巷道土地所有權人於新巷道開闢通行並辦理變更地目為道\n，或將新巷道土地完成捐獻等移轉登記手續之日起，得申請廢止原巷道。\n第 7 條\n建築基地面臨現有巷道申請建築，免附該巷道之土地權利證明文件。\n建築基地以私設通路連接建築線者，應檢附該私設通路之土地權利證明文\n件。但已依法申請建築所留設之私設通路，其原面臨該通路建造之建築物\n申請增建、改建、修建或重建者，不在此限。\n第 8 條\n建築基地與建築線接連部分之最小寬度，規定如下：\n一、建築基地不得小於彰化縣畸零地使用規則所定基地最小寬度之規定。\n二、畸零地寬度不足，依規定不必補足者，不得小於二公尺。\n三、以私設通路連接建築線者，不得小於建築技術規則所定私設通路之最\n小寬度。\n第 9 條\n本府應於測定建築線後，在指定建築線之文件上註明下列事項：\n一、椿位。\n二、基地所屬之使用分區用地。\n三、主要計畫及細部計畫發布實施日期文號。\n四、騎樓寬度。\n五、道路寬度、標高及牆面線。\n六、建蔽率及容積率。\n七、其他與設計有關之各項資料。\n第 10 條\n建築基地之排水溝渠與排水方向應配合該地區之排水系統設計，必要時得\n由本府規定溝渠構造規格與型式。\n第 11 條\n申請建造執照除依本法規定外，並應檢附下列文件：\n一、土地權利證明文件：\n（一）、土地登記謄本。\n（二）、地籍圖謄本。\n（三）、土地使用同意書（限土地非自有者）。\n二、工程圖樣：\n（一）、基地位置圖：載明基地位置、方位、都市計畫土地使用分區或區域\n計畫土地使用編定及比例尺。\n（二）、地盤圖：載明基地之方位、地號及境界線、建築線、臨接道路之名\n稱及寬度、建築物之配置。\n（三）、配置圖：載明基地之方位、地形、四週道路、附近建築物情況（含\n層數及構造）、申請建築物之位置、騎樓、防火間隔、空地、基地\n標高、排水系統及排水方向。\n（四）、各層平面圖及屋頂平面圖：註明各部分之用途及尺寸，並標示新舊\n溝渠位置及流水方向。\n（五）、建築物立面圖：各向立面圖應以座向標示之。\n（六）、剖面圖：註明建築物各部尺寸及所用材料。\n（七）、各層結構平面圖。\n（八）、結構詳圖：載明各部斷面大小及所用材料。但所附結構計算書業載\n明斷面大小及材料者，其結構詳圖得於開工前送主管建築機關備查\n。\n（九）、設備圖：依各設備主管機關規定辦理。但相關設計圖說得於開工前\n補送主管建築機關備查。\n三、結構計算書：\n（一）、屋架跨度超過十二公尺者，應檢附屋架應力計算書。\n（二）、二層以下建築物，樑跨度超過六公尺者，應檢附該部分應力計算書\n。\n（三）、三層建築物，樑跨度超過五公尺者，應檢附結構計算書。\n（四）、四樓以上建築物一律檢附結構計算書。\n（五）、經主管建築機關認有必要者。\n四、地基調查報告：建築技術規則建築構造編第六十四條規定之建築物或\n經主管建築機關認有必要者，應檢附地質鑽探報告書。\n五、建築線指定圖。\n六、其他有關文件：\n（一）、使用共同壁者，應檢附協定書。\n（二）、起造人委託建築師辦理申請建築執照者，應檢附委託書。\n（三）、申請興建自用農舍者，應檢附農業法規規定之文件。\n（四）、增建者應檢附合法房屋證明文件。\n（五）、使用耕地訂有三七五租約者，應檢附承租人同意書。\n（六）、辦理空地套繪所需之地籍套繪圖。\n（七）、依有關法令之規定應檢附者。\n七、本府統一規定格式之數位化資料。\n前項第一款第一、二目之文件，能以電子處理達成查詢者，得免提出。\n第 12 條\n申請雜項執照，除依本法規定外，並應檢附下列文件：\n一、土地權利證明文件：\n（一）、土地登記謄本。\n（二）、地籍圖謄本。\n（三）、土地使用同意書（限土地非自有者）。\n二、工程圖樣：位置圖、地盤圖、平面圖、立面圖與剖面詳細圖。\n三、建築線指定圖。\n四、其他有關文件：\n（一）、使用共同壁者應檢附協定書。\n（二）、起造人委託建築師設計及請領建築執照者，應檢附委託書。\n（三）、使用耕地訂有三七五租約者，應檢附承租人同意書。\n五、本府統一規定格式之數位化資料。\n前項第一款第一、二目之文件，能以電子處理達成查詢者，得免提出。\n開發山坡地範圍內之土地申請雜項執照者，除應依前規定辦理外，並應依\n山坡地建築管理辦法之規定辦理。\n第 13 條\n申請使用執照除依本法規定外，並應檢附下列文件：\n一、建築物竣工照片（各向立面、屋頂、法定空地、防火間隔、天井、停\n車空間等）。\n二、建築物申請新建者，應檢附門牌證明。\n三、建築物之主要構造、室內隔間及主要設備，經承造之專任工程人員，\n監造人檢查與設計圖樣相符後向本府申請使用執照。\n四、本府統一規定格式之數位化資料。\n第 14 條\n申請拆除執照除依本法規定外，並應檢附下列文件：\n一、建築物之位置圖、平面圖。\n二、建築物權利證明文件或其他合法證明。\n第 15 條\n供公眾使用建築物應於建築執照申請書及建築執照上註明之。\n第 16 條\n本法第十六條規定得免由建築師設計、監造或營造業承造非供公眾使用之\n建築物或雜項工作物如下：\n一、工程造價在一定金額以下者，得免由建築師設計、監造及營造業承造\n。\n二、建築物之建築面積在四十五平方公尺以下，簷高在三‧五公尺以下者\n，或農業區內依都市計畫法臺灣省施行細則之規定准予興建之自用農\n舍，得免由建築師設計、監造及營造業承造。\n三、鳥舍、涼棚、容量二公噸以下之水塔、本身高度在六公尺以下之瞭望\n臺、廣告牌、廣播塔是煙囪、或高度在二公尺以下之圍牆、建築所需\n駁崁或挖填土石方者，得免由建築師設計、監造及營造業承造。\n四、經農業主管機關核准非供居住使用之農業相關設施。其總樓地板面積\n在二萬平方公尺以下，建築物高度在二層（七公尺）以下，樑跨度在\n六公尺以下，肱（懸）臂樑跨度在二公尺以下或屋架跨度在十二公尺\n以下者，得免由建築師設計、監造及營造業承造。\n五、竹木造或加強磚造三樓以下無附建地下室者。其高度在十公尺以下，\n樑跨度在六公尺以下，肱（懸）臂樑跨度在二公尺以下或屋架跨度在\n十二公尺以下，其總樓地板面積，竹木造未逾一千平方公尺，加強磚\n造未逾三百平方公尺者。得免由建築師監造。\n六、雜項工作物之承載物頂端高度在九公尺以下，其載重量未逾二公噸者\n，得免由建築師監造。\n前項第一款工程造價之一定金額由本府定之。\n第一項各款之建築物分次申請建築時，其金額、面積、高度、容量等數額\n應累計計算。\n第 17 條\n前條建築物之造價估算標準，由本府定之。但雜項工作物之造價，應由建\n築師覈實估算，由本府核定。\n第 18 條\n建築工程使用道路者，應依下列規定辦理：\n一、使用道路寬度：\n（一）、道路寬度在四公尺以下者，不得使用。\n（二）、道路寬度超過四公尺未達六公尺者，使用寬度不得超過一公尺。\n（三）、道路寬度六公尺以上未達十二公尺者，使用寬度不得超過一公尺半\n。\n（四）、道路寬度十二公尺以上者，使用寬度不得超過二公尺。\n二、申請使用道路，應填具申請書，檢附使用範圍圖，由本府核定。\n三、使用道路應依核准使用之範圍設置安全圍籬。使用人行道者，應在安\n全圍籬外設置有頂蓋之行人安全走廊。\n四、經核准使用道路之範圍，仍應依本法第六十四條規定辦理。\n第 19 條\n都市騎樓、無遮簷人行道設置及退縮建築等之規定如下：\n一、實施都市計畫地區建築基地，都市計畫或其他法令已有退縮建築規定\n者，從其規定，免再設置騎樓或無遮簷人行道；其它無退縮建築規定\n者，應依下列各目規定設置騎樓或無遮簷人行道。\n（一）、商業區、住宅區面臨七公尺以上計畫道路，應設置騎樓或無遮簷人\n行道。\n（二）、其他分區（農業區及保護區除外）或公共設施用地面臨七公尺以上\n計畫道路應設置無遮簷人行道退縮建築。但工業區依法容許作一般\n商業設施且面臨十公尺以上道路者，得設置騎樓。\n二、騎樓或無遮簷人行道自建築線起至建築物外牆三．七五公尺。\n三、騎樓淨高度不得少於三公尺。\n四、構造規定如下：\n（一）、人行道騎樓地面應高於已完成道路邊界十公分至二十公分，表面平\n整作成四十分之一瀉水坡度，並配合道路邊緣人行步道齊平設置，\n不得裝置任何台階或阻礙物。\n（二）、騎樓柱正面應自道路境界線退縮二十五公分以上，騎樓縱深淨寬不\n得少於二．五○公尺。\n（三）、依規定留設之無遮簷人行道，表面舖設應平整，不得設有阻礙物。\n五、依規定留設之法定騎樓，其法定騎樓所占面積不計入基地面積及建築\n面積。\n第 20 條\n本府為改善環境增進市容觀瞻，調整路段內建築物之位置，得指定牆面線\n。\n第 21 條\n建造執照、雜項執照、拆除執照等核准之工程圖樣及說明書應置於施工地\n點，並應影印一份張掛或張貼於施工地點之明顯處所。\n本府對於前項規定應隨時派員查驗。\n第 22 條\n已領有建築執照尚未開工或正在施工中之建築物，因都市計畫之變更而有\n妨礙變更後之都市計畫者，本府應通知起造人於六個月內，辦理變更設計\n。但依下列規定完成之樓層，得按其核准範圍申領使用執照。\n一、已完成基礎工程者，准其完成至一層樓為止。\n二、超出一層樓並已建成外牆一公尺以上或建柱高達二公尺半以上者，准\n其完成至各該樓層為止。但僅豎立鋼筋不得視為建柱。\n第 23 條\n本府依本法第五十三條核定建築期限時，以六個月為基數，另依下列規定\n標準增加日數：\n一、地下室每層四個月。\n二、地面各樓層每層三個月。\n三、雜項工程三個月。\n前項建築期限，因構造特殊、施工困難、工程鉅大或情形特殊顯有增加日\n數之必要者，得視實際需要，酌予增加。\n第一項建築期限以開工之日起算。\n第 24 條\n依本法第五十三條、第五十四條作廢之建造執照或雜項執照，本府應於執\n照作廢後三十日內，派員實地勘查，其擅自建築者，應依本法第八十六條\n規定處理。\n第 25 條\n本法第五十四條所稱之開工，係指起造人會同承造人、監造人依本法規定\n向本府申報開工，並在現地實施拆除原有房屋、整地、挖地、打椿、從事\n安全措施等工程之一者，但搭建工寮或設圍籬而無實際工作者不得視為已\n開工。\n第 26 條\n建築物施工計畫書之內容應包括下列各項：\n一、承造人之專任工程人員、工地負責人、勞工安全衛生管理人員之姓名\n、地址、連絡電話。\n二、工程概要。\n三、施工程序及預定進度。\n四、施工方法及作業時間。\n五、施工場所佈置各項安全措施、工寮、材料堆置及加工場之圖說及配置\n。\n六、施工安全衛生措施、施工安全衛生設備、工地環境之維護、建築廢棄\n物處理及剩餘土石方處理之計畫。\n前項施工計畫書於實施都市計畫以外地區或偏遠地區內，非供公眾使用及\n四樓以下之建築物，本府得依據當地情形簡化其內容。\n第 27 條\n建築工程必須勘驗部分，依下列施工階段辦理：\n一、放樣勘驗：建築物放樣後，挖掘基礎土方前。\n二、基礎勘驗：基礎土方挖掘後、澆置混凝土前，其為鋼筋混凝土構造者\n，配筋完畢，如有基椿者，基椿施工完成。\n三、配筋勘驗：鋼筋混凝土構造及加強磚造各層樓板或屋頂配筋完畢，澆\n置混凝土前。\n四、鋼筋勘驗：鋼骨鋼筋混凝土構造各層鋼骨組立完成裝置模板前或鋼骨\n構造、鋼骨結構組立完成作防火覆蓋之前。\n五、屋架勘驗：屋架豎立後蓋屋面之前。\n前項勘驗應包括建築物位置相關事項、防空避難設備、配筋、騎樓及其標\n高、公共交通、衛生及安全措施。\n申報勘驗之文件應經承造人會同監造人查核簽章並送達本府後，方得繼續\n施工。但有緊急施工之必要者，監造人或承造人得監督先行施工，並於三\n日內報備。\n依本自治條例第十六條規定免由營造業承造及建築師監造之建築物或雜項\n工作物由起造人自行依核定圖樣施工，免予施工勘驗。\n放樣及基礎之勘驗，有關建築物之位置，臨接建築線部分，以主管建築機\n關所定建築線為準，土地界址由土地所有權人申請主管地政機關鑑定之，\n地界未經鑑定致越界建築者由起造人負責。\n主管建築機關得指定必須現場勘驗部份，應經主管建築機關派員勘驗合格\n後，方得繼續施工。其勘驗方式及勘驗項目由本府另訂之。\n勘驗紀錄應與建築執照申請書件及工程圖說一併保存至該建物拆除或損毀\n為止。\n第 28 條\n工程進行中變更設計者，應依本法第三十九條前段規定提出申請。但地下\n層部分因防範緊急危險，得於施工後七日內補辦手續。\n第 29 條\n建築物之竣工尺寸，高度誤差在百分之一以下，未逾三十公分；各樓層高\n度、各跨度誤差在百分之三以下，未逾十五公分；各層樓地板面積誤差在\n百分之三以下，未逾五平方公尺；其他各部分尺寸誤差在百分之二以下，\n未逾十公分者，視為符合核定計畫。但臨接騎樓線或指定牆面線部分，其\n誤差不得超過五公分。\n第 30 條\n建築物竣工時，起造人或承造人應將損壞之道路、溝渠、路燈、都市計畫\n椿等公共設施或公有建築物修復，並將損毀之行道樹補植，私設通路路面\n舖設完竣；搭蓋之圍籬、遮板、鷹架、工棚、樣品屋及須拆除之舊有建築\n物拆除完竣、清理一切廢棄物及疏通水溝後，始得申請核發使用執照。\n前項公共設施及公有建築物之修復，起造人或承造人得以繳納代金方式由\n有關主管機關於繳納代金代為修復。\n第 30-1 條\n依本法第七十七條第三項規定，受委託辦理建築物公共安全檢查之專業機\n構或人員，於本縣執行建築物公共安全檢查申報業務，及建築物室內裝修\n管理辦法第十三條所稱之專業技術人員，於本縣執行建築物室內裝修業務\n，應每年向本府辦理執行業務登記。\n第 31 條\n本法第七十條所稱建築物主要設備，係指下列各項：\n一、消防設備。\n二、避雷設備。\n三、污物、污水或其他廢棄物處理設備。\n四、昇降設備。\n五、防空避難設備。\n六、附設之停車空間。\n第 32 條\n對於面臨河湖、廣場等地帶申請建築，有退讓必要者，得會同有關機關劃\n定退讓之界線，公告之。\n沿道路交叉口建築者，應依附表規定退讓。（備註欄中）\n一、單位：公尺\n二、路寬為非整數者，按四捨五入計算。\n三、本表所稱之道路係指依有關法令公布之道路、經指定建築線之現有巷\n道。\n四、本表截角改為圓弧時，其截角長度即為該弧之切線長。\n五、切角所成之三角形應為等腰三角形。\n六、交叉角度超過一百二十度者無須截角。\n七、已開闢私設通路經認定為現有巷道者免截角。\n圖表附件：\n附件.DOC\n第 33 條\n本法第九十九條第一項規定之建築物，起造人應依下列規定辦理後，敘明\n不適用本法全部規定或一部規定之條款及其理由申請本府核定。\n一、紀念性之建築物為古蹟者，應照原有形貌保存，有修護必要者，其修\n護之工程計畫，應先報經古蹟主管機關許可。\n二、地面下之建築物，在市區道路範圍內建造者，其工程計畫應先申請市\n區道路管理機關許可。\n三、海港、碼頭、鐵路車站、航空站等範圍內雜項工作物之建造，其工程\n計畫應先經各該主管機關許可。\n四、依本法第九十九條第一項第三款所指臨時性之建築依下列規定辦理。\n（一）、應檢附申請書、土地使用權利證明文件、建築師出具之結構安全證\n明書、使用期限具結書、基地位置圖、現況圖、配置圖、平面圖、\n立面圖向本府申請核准。\n（二）、臨時性之建築物於竣工查驗合格後發給臨時使用執照，使用期滿由\n起造人自行拆除，逾期不拆者，強制拆除之，所需拆除費用由起造\n人負擔。\n（三）、使用期限以本府核准者為限，必要時得延長六個月，並以一次為限\n。\n（四）、臨時性建築物之設計、監造、構造安全，應由申請人委由建築師負\n責。\n興辦公共設施，在拆除合法建築物基地內改建或增建建築之管理辦法，由\n本府另定之。\n第一項第一款、第二款、第三款建築物，經核定不適用本法全部之規定者\n，仍應將工程圖樣說明書及建築期限申報本府備查，第四款臨時性之建築\n物須先經目的事業及用地主管機關同意後方得申請。\n第 34 條\n風景區之建築物應依下列規定：\n一、具有觀瞻及保存價值之古樹、林木及地貌應予保存。\n二、建築物之高度、色彩及造型應配合周圍自然環境與景觀，其建築計畫\n應經本縣風景區主管單位核可。\n三、原有建築物之修繕（包括外牆粉刷、屋面修改、搭蓋涼棚等）應經本\n縣風景區主管單位核可。\n第 35 條\n建築物在適用本法前或實施都市計畫以外地區建築物管理辦法施行前，已\n建築完成，申請補發使用執照者，應檢附下列文件，並免由建築師及營造\n業簽章：\n一、使用執照申請書。\n二、建築線指定證明。\n三、土地及房屋權利證明文件。\n四、基地位置圖、地盤圖、建築物之平面圖、立面圖。\n五、建築師安全鑑定書。\n六、房屋完成日期證明文件。\n七、其他有關文件。\n第 36 條\n於中華民國六十年十二月二十二日本法修正公布前已領有建造執照之建築\n物，申請補發使用執照者，應檢附下列文件，並免由建築師及營造業簽章\n：\n一、使用執照申請書。\n二、原領建造執照及核准之設計圖說。\n三、施工中有辦理中間勘驗紀錄，檢附勘驗紀錄，未辦理者，檢附建築師\n安全鑑定書。\n四、同時變更起造人名義者，應附土地及房屋權利證明文件。\n五、房屋完成日期證明文件。\n六、其他有關文件。\n前項第三款無勘驗紀錄者，應依本法第八十七條規定予以處罰。\n第 37 條\n供公眾使用之建築物，依前二條規定申請補發使用執照者，其出入口、走\n廊、防火間隔、樓梯及消防設備應符合建築技術規則及消防法規之規定。\n但樓梯及走廊如利用原有部分修改構造，得不限制其寬度。增設之安全梯\n免計入建築面積。\n第 38 條\n依本自治條例第三十六條，第三十七條規定申請補發使用執照之建築物，\n其建蔽率、高度應符合都市計畫法及有關法令之規定。但建築物在適用本\n法前或實施都市計畫以外地區建築物管理辦法施行前已建築完成或符合原\n核准建造執照者，不在此限。\n前項建築物之用途，應符合都市計畫法及有關法令之規定。但在都市計畫\n發布前已取得營利事業許可者，不在此限。\n第 39 條\n依據本法第五十一條在市區道路範圍內建造者，其工程計畫應經鄉、鎮、\n縣轄市市區道路管理機關許可，其土地產權仍屬私人所有者，應取得土地\n使用權同意書。\n第 39-1 條\n建築物未依本法第二十五條規定申請許可擅自建造者，限期補辦建築執照\n；必要時得強制拆除其建築物。\n補辦建築執照之規定，得由本府另定之。\n違章建築之拆除，由本府執行之。違章建築之查報及勒令停工，由各鄉（\n鎮、市）公所辦理。\n第 39-2 條\n本法第七十三條第一項但書規定，未領得使用執照之既有建築物申請接用\n水、電之條件及程序等事項之辦法，由本府另定之。\n前項接用水、電同意函之核發，由各鄉（鎮、市）公所辦理。\n第 40 條\n本自治條例執行發生疑義時，得由本府建設局局長召集本縣建築管理法規\n小組審議之。\n前項法規小組置委員十三人，以本府建設局局長為委員兼召集人，其餘委\n員就下列人員聘（派）兼之。\n一、臺灣省建築師公會彰化縣辦事處代表二人。\n二、臺灣區綜合營造工程工業同業公會彰化縣辦事處代表一人。\n三、彰化縣建築開發商業同業公會代表一人。\n四、彰化縣土木包工業商業同業工會代表一人。\n五、本府法制室代表一人。\n六、本府工務局土木課課長。\n七、本府建設局城鄉計畫課課長。\n八、本府建設局使用管理課課長。\n九、本府建設局建築管理課課長。\n十、專家學者二名。\n前項委員任期二年，均為無給職。但得依規定支給出席費。\n第 40-1 條\n下列事項得向本府委託之專業公會或團體申請辦理：\n一、建築許可之審查。\n二、施工勘驗。\n三、變更使用執照之審查。\n四、變更使用執照竣工查驗。\n五、建築物公共安全檢查申報之審查。\n六、公寓大廈管理條例第五十七條第一項規定之見證移交事項。\n前項費用由申請人負擔。\n第一項之委託審查、勘驗、查驗、見證移交及費用標準，由本府另定之。\n第 40-2 條\n非本府所在地鄉、鎮之實施區域計畫地區建築管理業務，除公有建築物與\n供公眾使用建築物由本府辦理外，得委由各鄉（鎮、市）公所辦理。\n前項建築管理業務包含建築許可之申請、違反本法或基於本法所發布之命\n令等相關規定之裁罰權限。\n第 41 條\n本自治條例自公布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL026531","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"修正日期":"民國 114 年 01 月 20 日","公發布日":"民國 91 年 02 月 18 日","法規名稱":"彰化縣建築管理自治條例","法規體系":"建設類","發文字號":"府行法字第1140019782號"},"promulgation_date":"2002-02-18","revision_date":"2025-01-20","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL026531","status":"unknown","title":"彰化縣建築管理自治條例","last_checked_at":"2026-10-06T17:26:36+08:00","last_success_at":"2026-10-06T17:26:36+08:00","verification_status":"fetched","content_hash":"6184d48635cff7cc32f8d9325202329e5f628fa67107163192d4620c2d6e8201","history":[{"observed_at":"2026-10-06T17:26:36+08:00","content_hash":"6184d48635cff7cc32f8d9325202329e5f628fa67107163192d4620c2d6e8201","change_kind":"initial","revision_date":"2025-01-20"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=135&id=FL026531&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"彰化縣政府","category":"建築管理相關","content":"第 1 條\n為加強彰化縣（以下簡稱本縣）建築開發業之管理，建立不動產開發秩序\n，保護消費者權益，協助建築管理業務之推行，特制定本自治條例。\n第 2 條\n凡於本縣轄區從事建築開發業，應加入本縣建築開發商業同業公會。\n第 3 條\n建築開發業領得建造（雜項）執照申報開工時應向本縣建築開發商業同業\n公會報備登記，並檢具該公會年度會員證書影印本。\n第 4 條\n本縣建築開發商業同業公會應對業者入會、退會、規範事項及本縣轄區建\n築開發之區位、總樓地面積、工程造價、開工時間、完工期限等，每半年\n彙報彰化縣政府建設處備查。\n第 5 條\n本縣建築開發商業同業公會對於建築開發業涉有海砂屋、輻射屋之紀錄者\n，應主動通知承造人、監造人加強監工及監造責任。\n第 6 條\n本縣建築開發商業公會應協助辦理本縣轄區建築開發所發生之糾紛、紓困\n及獎懲等事項，辦理成果應報彰化縣政府建設處備查。\n第 7 條\n本自治條例未規定者適用其他有關法令之規定。\n第 8 條\n本自治條例自公布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL028115","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"修正日期":"民國 97 年 04 月 24 日","公發布日":"民國 92 年 06 月 19 日","法規名稱":"彰化縣建築開發業管理自治條例","法規體系":"建設類","發文字號":"府法制字第0970084797號"},"promulgation_date":"2003-06-19","revision_date":"2008-04-24","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL028115","status":"unknown","title":"彰化縣建築開發業管理自治條例","last_checked_at":"2026-10-06T17:26:36+08:00","last_success_at":"2026-10-06T17:26:36+08:00","verification_status":"fetched","content_hash":"0a2b6c274ba4bd071328aafa0018691c4fb83831506f269e5883ce7265dbdaf7","history":[{"observed_at":"2026-10-06T17:26:36+08:00","content_hash":"0a2b6c274ba4bd071328aafa0018691c4fb83831506f269e5883ce7265dbdaf7","change_kind":"initial","revision_date":"2008-04-24"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"彰化縣政府","category":"建築管理相關","content":"一、為提升行政服務效率及有效管制建築設計簽證品質，以落實行政與技\n術分立之目標，特訂定本原則。\n二、本處理原則所稱簽證項目係指「建造執照及雜項執照建築師簽證表」\n所定，經建築師簽證之項目。\n三、本縣執照抽查小組由彰化縣政府建設處（以下簡稱本處）及社團法人\n彰化縣建築師公會（以下簡稱公會）會員組成。\n四、建造執照、雜項執照、變更設計簽證項目每月就前月已發照案件抽查\n，按下列比例抽查，並得就實際需要適時調整之：\n（一）五層以下非供公眾使用之建築物每十件抽查一件以上。\n（二）五層以下供公眾使用之建築物每十件抽查二件以上。\n（三）六層以上至十四層之建築物每十件抽查二件以上。\n（四）十一層以上至十四層之建築物每十件抽查四件以上。\n（五）十五層以上建築物每十件抽查五件以上。\n前項案件屬下列情形之一者，應列為必須抽查案件：\n（一）山坡地範圍內之供公眾使用建築物。\n（二）建築基地全部或一部位於地質敏感區內。\n五、審查結果若有不符規定者，應通知起造人及設計建築師限期改正或辦\n理變更設計，必要時得依法勒令停工；經通知改正，如無正當理由逾\n期未辦理變更設計者，本府得註銷該執照並依相關規定辦理。\n六、抽查項目：\n建造執照簽證項目由本府執照抽查小組依下開抽查項目逐項審查，查\n有不符規定情形者，逐項累積次數：\n（一）建蔽率、容積率。\n（二）建築物高度、樓層高度、高度比、陰影、日照。\n（三）碰撞距離、結構計算書。\n（四）停車空間、裝卸位。\n（五）騎樓、無遮簷人行道。\n（六）綠化設施、開放空間。\n（七）出入口、走廊、通道（路）或坡道。\n（八）樓梯、安全梯、梯廳、步行距離。\n（九）防火區劃、防火構造、防火避難。\n（十）昇降機、緊急用昇降機、緊急進口。\n（十一）通風、採光。\n（十二）防空避難、屋頂避難平台、避雷設備及防災中心。\n（十三）無障礙設施及無障礙設施勘檢合格資料。\n（十四）其他退縮距離及建築物緩衝空間。\n（十五）臨接道路限制。\n（十六）依地質法進行進行基地地質調查及地質安全評估。\n（十七）綠建築。\n（十八）其他本處會議決議或認定有必要者。\n其他未經列出之項目，經審查人員認定不合格者，仍應依前項規定辦\n理。\n七、起造人、設計建築師收到本府抽查結果通知後，如有異議應於通知改\n正期限內申請複核。本府應於十日內將複核結果通知起造人，必要時\n應召開複核會議。起造人對核復結果仍有異議時，應由本府於七日內\n報請上級主管建築機關處理。\n八、複核會議小組置成員十五人，以本府建設處處長為召集人，本府建設\n處副處長為副召集人，其餘組員就下列人員聘（派）兼之。\n（一）公會代表七人。\n（二）本府建設處城鄉計畫科代表二人。\n（三）本府建設處使用管理科代表二人。\n（四）本府建設處建築管理科代表二人。\n九、簽證案件經抽查後，相關文件、圖說缺漏，或建築設計有不符第六點\n規定之相關規定情形者，由本處逐項對設計建築師予以記點一次，每\n案件記點次數以五點為上限。但漏未檢討建築相關法規，補檢討後仍\n符合者，不在此限。\n十、簽證案件於施工中或領得使用執照後，經本處發現簽證項目有不符規\n定者，依本原則規定記點。\n十一、其他不符規定項目記點方式，由本處準用第九點相關類似項目之認\n定。\n十二、本原則記點以一年（每年一月一日至十二月三十一日止）為累計期\n間，並依下列方式分別處理：\n（一）依第六點規定，一年內累計記點達十五點以上，或記二點以上之\n案件數達五件者，該設計建築師之當年度設計案件，需親自至本\n處說明後始准核照，本處並得指定抽查該設計建築師下一年之設\n計案件。\n（二）依第六點規定，一年內累計記點達三十點以上，或記二點以上之\n案件數達十件者，將該設計建築師依建築師法規定移送本縣建築\n師懲戒委員會辦理懲戒。\n（三）每年累計記點結果，由本處函知公會，並公布本處網站。\n重大過失案件經本處認有必要者，除予累計記點數外，得以個案逕\n行移送懲戒。\n十三、本原則自修正發布日實施。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL078186","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"修正日期":"民國 104 年 06 月 26 日","公發布日":"民國 94 年 10 月 04 日","法規名稱":"彰化縣建造執照及雜項執照（含變更設計）簽證案件抽查處理原則","法規體系":"建設類","發文字號":"府建管字第1040207608號"},"promulgation_date":"2005-10-04","revision_date":"2015-06-26","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL078186","status":"unknown","title":"彰化縣建造執照及雜項執照（含變更設計）簽證案件抽查處理原則","last_checked_at":"2026-10-06T17:26:30+08:00","last_success_at":"2026-10-06T17:26:30+08:00","verification_status":"fetched","content_hash":"236db16934c17a44fa7a7c8fdb260ae87ea66a2df40b38440e8f2ba81f905c9d","history":[{"observed_at":"2026-10-06T17:26:30+08:00","content_hash":"236db16934c17a44fa7a7c8fdb260ae87ea66a2df40b38440e8f2ba81f905c9d","change_kind":"initial","revision_date":"2015-06-26"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"彰化縣政府","category":"建築管理相關","content":"第 1 條\n彰化縣政府 (以下簡稱本府) 為整頓市容、處理拆除合法建築物剩餘部分\n之整建，特依彰化縣建築管理自治條例第三十三條第二項規定訂定本辦法\n。\n第 2 條\n因興辦公共設施拆除合法建築物剩餘部分之就地整建，除依建築法及其他\n法律規定外，依本辦法辦理之。\n第 3 條\n就地整建應依下列規定辦理：\n一  寬度：臨接建築線長度應為二公尺以上。\n二  深度：自建築線起扣除騎樓之深度後最小為一．五公尺，最大為十六\n公尺。\n三  高度：就地整建建築物沿路面之簷高以不超過拆除面之高度為準。但\n拆除面與建築物成斜面，而高度不同者，以其平均高度為準；拆除面\n之高度低於原建築簷高者，得維持原建築物簷高；拆除面高度低於十\n三公尺者，得以十三公尺為準。屋頂如係木架或鐵架之房屋，屋頂最\n高高度得自簷高加屋架跨度四分之一高度。如拆除後之剩餘基地屬公\n共設施保留地者，其整建高度應符合都市計畫公共設施保留地臨時建\n築使用辦法有關規定。\n四  總樓地板面積：原有空地得合併就地整建。但其總樓地板面積扣除騎\n樓面積後，不得超過拆除前原有建築物總樓地板面積。\n五  建蔽率、容積率：就地整建範圍得不受建蔽率及容積率規定之限制。\n前項第四款拆除前原有建築物總樓地板面積未達二百六十平方公尺者，就\n地整建時得以二百六十平方公尺為準。\n就地整建建築物與毗連建築物如最高簷高相差三十公分以內者，得由整建\n人聯合申請統一高度及統一正面裝修。\n就地整建應依建築技術規則設計施工編規定留設防火間隔。但就地整建之\n基地，其深度在十公尺範圍內部分，不在此限。\n第 4 條\n供公眾使用建築物及前條第一項第三款建築物之簷高超過十三公尺者，不\n適用本辦法之規定。\n第 5 條\n修復門面得免申請就地整建，由所有權人自行沿拆除面，按拆除剩餘之建\n築物高度修復之，其依法須設置騎樓者，並應將拆除剩餘之建築物依彰化\n縣建築管理自治條例規定設置騎樓。\n第 6 條\n就地整建之基地內如有公共設施保留地，得依下列規定辦理：\n一  剩餘建築物所有權人得向主辦公共工程機關申請補償，一併拆除之。\n二  剩餘建築物如有部分位置在公共設施保留地上者，得檢附公共設施開\n闢時無償自行拆除切結書申請同時整建，整建之建築物以原高度為限\n；該公共設施開闢時應由當地政府通知限期自行無條件拆除，逾期未\n拆除者，由當地政府強制拆除之。\n前項就地整建之建築物，其構造材料應不超過都市計畫公共設施保留地臨\n時建築使用辦法之規定。\n第 7 條\n剩餘建築物有下列各款情形之一者，其所有權人得向主辦公共工程機關申\n請補償一併拆除：\n一  不符合本辦法規定無法申請就地整建者。\n二  具有危險性而不申請就地整建者。\n三  使用價值偏低，不申請就地整建者。\n第 8 條\n主辦公共工程機關應於工程開工時將預定完工期限通知拆除戶。\n就地整建應於公共工程完工後二年內向本府建設處或轄區鄉、鎮、市公所\n提出申請。\n前項公共工程完工以驗收合格日為準。\n受理機關應自收到申請書日起十日內予以准駁；申請文件不全者，應即通\n知申請人限期補正，逾期未補正或補正仍不齊全者，駁回其申請。\n第 9 條\n剩餘建築物逾期未申請就地整建而有傾頹或朽壞情事致有危害公共安全者\n，依建築法有關規定處理。\n第 10 條\n申請就地整建者應檢附下列文件：\n一  申請書。\n二  經轄區鄉 (鎮、市) 公所核發之樓地板面積證明文件。\n三  土地權利證明文件：土地登記簿謄本、地籍圖謄本及土地使用權利\n證明書。但就地整建之建地屬自有者免附土地使用權利證明書。\n四  使用共同壁協定書。\n五  地盤圖。\n六  建築線指定圖 (含現有巷道) 。\n七  比例尺百分之一原建築平面圖及各向立面圖。\n八  比例尺百分之一整建平面圖，各向立面圖、基礎、各層樓地板、屋架\n構造平面圖及主要剖面圖。\n九  整建之高度超過七公尺 (二樓) 者，應檢附建築師或專業技師安全証\n明並依下列情況檢附結構計算書備查。\n(一) 二層以下跨距超過六公尺之鋼筋混凝土樑，應檢附該部分應力計算\n書。\n(二) 跨距超過十二公尺之鋼構造，應檢附鋼架應力計算書。\n(三) 三層以上之鋼筋混凝土構造建築物，樑跨距超過五公尺者及四層建\n築物應檢附結構計算書。\n第 11 條\n就地整建應於核定完成整建期限內依核准圖樣整建完成，無法如期完成者\n得申請展期。\n整建完成後應檢附竣工平面圖及各向立面四吋照片二份向受理機關申請核\n發完工證明書。\n受理機關於收到申請書日起十日內應派員實地查驗，合格後發給完工證明\n書。\n第 12 條\n未經核准擅自整建或未依照核准圖樣施工者，依建築法第八十六條第一款\n規定或其他有關法令規定辦理。\n第 13 條\n本府建設處得依建築法第二十七條規定委由鄉（鎮、市）公所依規定受理\n就地整建及核發完工證明書等業務。\n第 14 條\n依本辦法申請就地整建者，得免由建築師設計、監造及營造業承造。\n第 15 條\n本辦法規定之書表格式，由本府建設處另定之，並由受理機關依式印製免\n費供應。\n第 16 條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL028117","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"修正日期":"民國 97 年 06 月 02 日","公發布日":"民國 92 年 03 月 11 日","法規名稱":"彰化縣拆除合法建築物剩餘部分就地整建辦法","法規體系":"建設類","發文字號":"府法制字第0970112436號"},"promulgation_date":"2003-03-11","revision_date":"2008-06-02","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL028117","status":"unknown","title":"彰化縣拆除合法建築物剩餘部分就地整建辦法","last_checked_at":"2026-10-06T17:26:42+08:00","last_success_at":"2026-10-06T17:26:42+08:00","verification_status":"fetched","content_hash":"ea56831f1d25389bd7b1376e3a77acd19f8f6a639e853ae40207bb9903bb53f8","history":[{"observed_at":"2026-10-06T17:26:42+08:00","content_hash":"ea56831f1d25389bd7b1376e3a77acd19f8f6a639e853ae40207bb9903bb53f8","change_kind":"initial","revision_date":"2008-06-02"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"彰化縣政府及所屬機關橋梁維護管理作業要點.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=1220&id=GL000238&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"第一條\n彰化縣政府(以下簡稱本府)為加強轄內橋梁維護管理工作，確實掌握橋梁使用現況及損傷情形，特訂定本橋梁維護管理作業要點。\n第二條\n本要點適用於彰化縣轄內縣道、鄉道、市區道路、農路、防汛道路、村里道路之車行橋梁。\n第三條\n本要點用詞定義如下：\n(一)定期檢測：指利用徒步、攀登方式或機械車輛儘可能接近橋梁構造物，定期對橋梁構件實施檢測，評估橋梁構造物之安全情形，藉以早期發現構件之劣化程度，並評估劣化原因及橋梁功能損傷情形。\n(二)\n特別檢測：指災害(如颱風、豪雨或地震等)、重大事故或發現橋梁有特殊異狀情形後，可能造成橋梁功能損傷所進行之不定期檢測。\n​​​​​​​​​​​​​​  (三)\n定期維修：指針對橋梁定期檢測結果採用DERU方式評定之對檢測結果評估為D及R≧3或U≧3之橋梁構件進行維修。\n第四條\n橋梁檢測頻率如下：\n(一)\n定期檢測：新建橋梁應於完工使用後二年內進行第一次定期檢測，爾後定期檢測之間隔以二年為原則。重要橋梁與特殊形式橋梁(如吊橋、斜張橋、脊背橋等) 則每年進行一次檢測。\n(二)\n特別檢測：顯著異狀於災害(如颱風、豪雨或地震等)及重大事故發生後或本府轄管各級橋梁之主管單位認定有必要辦理時。\n第五條\n定期維修頻率應視檢測結果及時辦理。\n第六條\n定期檢測及維修成果資料，應上傳交通部「臺灣地區橋梁管理資訊系統」資料庫。\n第七條\n依交通部辦理之「縣市政府橋梁維護管理作業評鑑」結果，視檢測作業及維修作業評等優劣情形，分別予以獎勵或議處：\n(一)\n檢測作業評等結果，本府相關執行及督導人員依下列原則獎勵或議處：\n1.優良：嘉獎二次。\n2.佳：嘉獎一次。\n3.尚可：不予敘獎。\n4.待改善：口頭告誡；如因年度未編列預算，致無法辦理橋梁檢測，則可免予議處。\n5.亟待改善：申誡一次；如因年度未編列預算，致無法辦理橋梁檢測，則可免予議處。\n​​​​​​​  (二)\n維修作業評等結果，除各鄉(鎮、市)公所之獎懲部分，由本府函請該管公所納為相關人員績效考核參考外，本府相關執行及督導人員依下列原則獎勵或議處：\n1.優良：嘉獎二次。\n2.佳：嘉獎一次。\n3.尚可：不予敘獎。\n4.待\n改善：口頭告誡；如橋梁管理單位已於年度預算編列、辦理追加預算及動支本府預備金時，均提出橋梁維修經費需求，礙於各因素，無法適時編列預算辦理橋梁維修時，則可免予議處。\n5.亟待改善：申誡一次；如橋梁管理單位已於年度預算編列、辦理追加預算及動支本府預備金時，均提出橋梁維修經費需求，礙於各因素，無法適時編列預算辦理橋梁維修時，則可免予議處。.\n​​​​​​","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:GL000238","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"全文檔案":"彰化縣政府及所屬機關橋梁維護管理作業要點.pdf","公發布日":"民國 109 年 10 月 22 日","法規名稱":"彰化縣政府及所屬機關橋梁維護管理作業要點","法規體系":"工務類","發文字號":"府工管字第1090383848號函"},"promulgation_date":"2020-10-22","revision_date":"2020-10-22","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=GL000238","status":"unknown","title":"彰化縣政府及所屬機關橋梁維護管理作業要點","last_checked_at":"2026-10-06T17:26:46+08:00","last_success_at":"2026-10-06T17:26:46+08:00","verification_status":"fetched","content_hash":"6d8aa54380f428ecd67ff4f998ae6d592dc54f71b385e9e88e5beea148908f3c","history":[{"observed_at":"2026-10-06T17:26:46+08:00","content_hash":"6d8aa54380f428ecd67ff4f998ae6d592dc54f71b385e9e88e5beea148908f3c","change_kind":"initial","revision_date":"2020-10-22"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=1220&id=GL000238&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"逐點說明.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=1797&id=GL000367&type=LAW"},{"name":"總說明.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=1796&id=GL000367&type=LAW"},{"name":"法規全文.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=1798&id=GL000367&type=LAW"},{"name":"附件一.odt","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=1795&id=GL000367&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"一、彰化縣政府（以下簡稱本府）為受理土地及合法建築物所有權人提議劃定彰化縣（以下簡稱本縣）更新地區，依都市更新條例（以下簡稱本條例）第十條第三項規定，訂定本作業原則。\n二、農業區、保護區、河川區、行水區、風景區或其他非屬開發建築用地，不得提議劃定為更新地區。\n三、具本條例第六條規定之情形，且符合下列情形之一者，其土地及合法建築物所有權人得向本府提議優先劃定更新地區：\n(\n一\n)\n提議範圍內之建築物，經專業機構、建築師或專業技師鑑定，屬於非防火構造或鄰棟間隔不足建築物，其棟數占總建築物棟數比率達二分之一以上。\n(\n二\n)\n提議範圍內之建築物，屋齡達三十年以上，且經結構安全性能初步評估之結果為乙級或未達最低等級，其棟數占總建築物棟數比率達二分之一以上。\n(\n三\n)\n提議範圍內，屬於無昇降設備之四層樓以上之合法建築物，其投影面積占全部建築物總投影面積比率二分之一以上。\n(\n四\n)\n提議範圍位於本條例施行細則第二條規定之重大建設或大眾運輸場站四百公尺範圍內。\n(\n五\n)\n提議範圍位於中央或本府已指定或登錄之文化資產或都市計畫保存區，或其毗鄰建築物未能配合保存或維護。\n(\n六\n)\n提議劃定範圍內之建築物，無設置化糞池或該建築物沖洗式廁所排水、生活雜排水未經處理而直接排放，其棟數占總建築物棟數比率達二分之一以上。\n(\n七\n)\n提議劃定範圍內之建築物，經行政院原子能委員會偵檢確定遭受放射性污染，其棟數占總建築物棟數比率達二分之一以上。\n(\n八\n)\n提議劃定範圍內之建築物，涉及特種工業設施有妨害公共安全之虞。\n前項提議劃定範圍，應為完整街廓或面積達五千平方公尺以上。\n第一項規定之專業機構，指內政部依都市危險及老舊建築物加速重建條例及都市危險及老舊建築物結構安全性能評估辦法審查合格評定之共同供應契約機構。\n四、具本條例第七條規定之情形，且符合下列情形之一者，土地及合法建築物所有權人得向本府提議迅行劃定更新地區：\n(\n一\n)\n提議範圍內之建築物，因戰爭、地震、火災、水災、風災或其他重大事變遭受損壞，\n經相關主管機關認定為危險或有安全之虞\n，\n有立即實施重建、整建或維護措施之必要。\n(\n二\n)\n提議範圍內之建築物，符合都市危險及老舊建築物加速重建條例第三條第一項第一款規定者。\n五、提議人依第三點及第四點規定，向本府提議劃定更新地區者，\n應經範圍內私有土地及私有合法建築物所有權人均逾二分之一，且其所有土地總面積及合法建築物總樓地板面積均逾二分之一之提議意願，並\n檢附下列文件：\n(\n一\n)\n申請書（如附件一）。\n(\n二\n)\n提議人之身分證明文件及其位於提議範圍內之土地登記謄本、建物登記謄本、地籍圖謄本及土地使用分區證明；上述謄本得以電子謄本代之。\n(\n三\n)\n提議人委託他人代為辦理者，應檢附受託人之身分證明文件及委託書。\n(\n四\n)\n更新地區範圍圖，以都市計畫圖或地形圖為底圖，比例尺不得小於一千二百分之一。\n(\n五\n)\n都市更新計畫草案。但依第四點規定提出者，得不檢附訂定都市更新計畫草案。\n(\n六\n)\n提議劃定更新地區範圍意願調查統計相關文件。\n前項文件有缺漏或不符規定者而能補正者，本府應以書面通知限期補正；屆時未完成補正者，不予受理。\n圖表附件：\n附件一.odt","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:GL000367","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"全文檔案":"法規全文.pdf","公發布日":"民國 112 年 11 月 22 日","法規名稱":"彰化縣政府受理提議劃定更新地區作業原則","法規體系":"建設類","發文字號":"府建新字第1120467151號函","立法理由":"逐點說明.pdf 總說明.pdf"},"promulgation_date":"2023-11-22","revision_date":"2023-11-22","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=GL000367","status":"unknown","title":"彰化縣政府受理提議劃定更新地區作業原則","last_checked_at":"2026-10-06T17:26:28+08:00","last_success_at":"2026-10-06T17:26:28+08:00","verification_status":"fetched","content_hash":"8a92aa9be1760eed60da5ba16e76cadf6f28d1cabb66b604aee56479ea90a777","history":[{"observed_at":"2026-10-06T17:26:28+08:00","content_hash":"8a92aa9be1760eed60da5ba16e76cadf6f28d1cabb66b604aee56479ea90a777","change_kind":"initial","revision_date":"2023-11-22"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=1797&id=GL000367&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=1796&id=GL000367&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=1798&id=GL000367&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=1795&id=GL000367&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"彰化縣政府受理申請使用縣鄉道舉辦活動計畫審核注意事項.PDF","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=212&id=FL088184&type=LAW"},{"name":"附件一彰化縣政府受理使用縣鄉道舉辦活動申請書.PDF","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=213&id=FL088184&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"一、彰化縣政府（以下簡稱本府）為因應配合各機關團體申請於本府轄管\n縣、鄉道舉辦活動，維護交通安全，特依據「公路用地使用規則」第\n四條第一項及第五條第一項規定，訂定本要點。\n二、活動性質與申請原則：\n（一）本要點所稱之活動，指舉辦具有學術、藝文、旅遊、公益、體育等\n性質而須實施道路交通管制之行為，活動舉辦原則應向該活動主管\n機關申請許可後，再向本府申請路權。\n（二）民間婚、喪、喜慶、迎神賽會、擺設筵席等行為，依「道路交通安\n全規則」或「集會遊行法」規定向警察機關申請核准活動，免向本\n府申請路權。但活動需封閉全部道路（雙向）者，仍應先向本府申\n請許可。\n三、申請路段：本府轄管縣道及鄉道。\n四、受理單位：本府工務處。\n五、申請方式及應備文件：\n（一）於活動舉辦三十日前，以書面向本府提出申請。（申請書如附件一\n）\n（二）若有特殊情況未能於前款規定期限前提出申請，活動主辦單位詳述\n理由，並經本府同意者，不受前款規定之限制。\n（三）活動主辦單位於提出申請時，應一併提送詳細之活動計畫書，其內\n容至少應包含以下項目：\n1.活動名稱、目的、方式、預定參加人數。\n2.活動主、協辦單位簡介及舉辦同類性質活動經驗說明。\n3.活動主、協辦單位及各單位負責人，各單位之活動主要承辦人員\n，各單位聯絡窗口（含聯絡人）及方式（地址、電話、傳真、網\n站及電子郵件等）。\n4.活動場地規劃及示意圖，包括活動期間臨時進入或設置於道路上\n之車輛、設施名稱、數量及舉辦活動必要搭設之司令台、舞台等\n設施。\n5.交通維持計畫（含交通動線示意圖、交通維持設施佈設、宣導及\n執法計畫等）。\n6.事後道路清理等復原計畫。\n7.其他有關道路管理及交通秩序與安全相關事項。\n（四）活動計畫書之內容若有補充資料時，須於活動舉辦七日前補送，逾\n時不予收件。\n圖表附件：\n附件一彰化縣政府受理使用縣鄉道舉辦活動申請書.PDF\n六、若有超過一個以上單位對同一時間、路段提出申請時，申請使用道路\n之優先序位，以本府收件日期及當日收件掛號順序為準。\n七、申請人於活動期間，應對活動行為及安全負責，不得使用製造噪音及\n環境污染致妨害他人生活安寧與生活品質之相關設備，如有下列情形\n之一者，本府得立即停止其使用，並廢止原使用許可。如違反其他法\n令者，依其他相關法令規定處理：\n（一）違反原核准使用計畫。\n（二）未能維持現場人員、車輛等秩序，足以影響公共安全、環境衛生及\n破壞公物。\n（三）因天災、事變或其他不可抗力事件，宜停止其使用之必要者。\n申請人有前項第一款及第二款情形，一年累計次數達二次者，本府一\n年內不受理其申請道路使用。\n八、其他：\n（一）活動主辦單位應負責現場清潔維護，參與活動人員之安全、秩序維\n護工作，及辦理公共意外保險。\n（二）不得有毀損道路相關設施之行為。\n（三）如有毀損道路設施之情形時，活動主辦單位應負賠償之責。\n（四）活動結束後，活動主辦單位需將現場清理完成及恢復原狀。\n（五）活動主辦單位倘需本府、各縣市政府警察局及其他單位配合或代辦\n事項，包含工務及警力支援、交通維持、安全秩序維護等，應自行\n接洽研商。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL088184","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"修正日期":"民國 105 年 01 月 21 日","公發布日":"民國 0 年 00 月 00 日","圖表附件":"彰化縣政府受理申請使用縣鄉道舉辦活動計畫審核注意事項.PDF","法規名稱":"彰化縣政府受理申請使用縣鄉道舉辦活動管理要點","法規體系":"工務類","發文字號":"府工管字第1050024628號"},"promulgation_date":null,"revision_date":"2016-01-21","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL088184","status":"unknown","title":"彰化縣政府受理申請使用縣鄉道舉辦活動管理要點","last_checked_at":"2026-10-06T17:26:47+08:00","last_success_at":"2026-10-06T17:26:47+08:00","verification_status":"fetched","content_hash":"c53301914d16dede515226e7ba40426d822c4a812c7de8cccbeef2291d80e676","history":[{"observed_at":"2026-10-06T17:26:47+08:00","content_hash":"c53301914d16dede515226e7ba40426d822c4a812c7de8cccbeef2291d80e676","change_kind":"initial","revision_date":"2016-01-21"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=212&id=FL088184&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=213&id=FL088184&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"附件:空白檢舉書.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=3483&id=GL000439&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"彰化縣政府(以下簡稱本府)為考量違章建築管理人力及端正社會風氣，避免以大量檢舉違章建築謀其私人之利益，特訂定本要點。\n本府受理違章建築檢舉方式應以書面為之，書面以本府民意信箱或書面郵寄或至本府建設處填具檢舉書，格式如附件。非以書面並依本要點第三、四點規定辦理，且符合行政程序法第一百七十三條各款情形之一者得不予受理。\n檢舉書內容應符合下列規定：\n檢舉案件應一次一案（一案指同一地址、一宗基地或一棟建築物…等）。\n填具真實姓名、聯絡地址及電話，以不實姓名或僅留郵政信箱或電子郵件信箱不予受理。\n載明違章地段及地號或地址。\n​​​​​​​\n檢舉書應檢附下列文件：\n​​​​​​​\n違章地點地籍圖、地籍謄本。\n現場照片三張（應顯示明確清楚的違章建築物及拍攝日期）。\n本府受理檢舉案件後依彰化縣建築管理自治條例第三十九條之一辦理，函請各鄉（鎮、市）公所查報，並依違章辦法辦理；檢舉人未提供本要點第四點規定資料者，本府不另提供查詢及查證服務。\n本府對於檢舉人及被檢舉人資訊應依個人資料保護法等相關之規定予以保密。並基於衡平原則，就檢舉事由，對檢舉人與被檢舉人有相同查察之權利。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:GL000439","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"修正日期":"民國 112 年 09 月 28 日","公發布日":"民國 107 年 05 月 09 日","圖表附件":"附件:空白檢舉書.pdf","法規名稱":"彰化縣政府受理違章建築檢舉要點","法規體系":"建設類","發文字號":"府建使字第1120380115號"},"promulgation_date":"2018-05-09","revision_date":"2023-09-28","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=GL000439","status":"unknown","title":"彰化縣政府受理違章建築檢舉要點","last_checked_at":"2026-10-06T17:26:33+08:00","last_success_at":"2026-10-06T17:26:33+08:00","verification_status":"fetched","content_hash":"c5446b0c9cfde2956e38a632f84b6ce17716efe95f609146bdf9b4638c86f1b8","history":[{"observed_at":"2026-10-06T17:26:33+08:00","content_hash":"c5446b0c9cfde2956e38a632f84b6ce17716efe95f609146bdf9b4638c86f1b8","change_kind":"initial","revision_date":"2023-09-28"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=3483&id=GL000439&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"彰化縣政府","category":"建築管理相關","content":"一、法令依據：都市計畫容積移轉實施辦法第九條之一。\n二、查估內容：\n（一）都市計畫容積移轉實施辦法第九條之一規定之容積代金。\n（二）彰化縣都市計畫容積移轉審查許可及作業要點第七點所定之接受基\n地市價。\n三、本府委託專業估價者以登記開業於下列公會之一者為限：\n（一）中華民國不動產估價師公會全國聯合會。\n（二）台北市不動產估價師公會\n（三）新北市不動產估價師公會。\n（四）桃園市不動產估價師公會。\n（五）台中市不動產估價師公會。\n（六）台南市不動產估價師公會。\n（七）高雄市不動產估價師公會。\n（八）其他經本府同意之專業機關或團體。\n四、申請方式：\n申請人應向三家以上之本府委託專業估價者辦理估價，估價費用由申\n請人自行負擔，查估報告書應加蓋專業估價者圖章並由專業估價者簽\n證。\n五、查估作業：\n（一）專業估價者辦理容積代金勘估業務，應遵守誠實信用之原則，不得\n有不正當行為及違反或廢弛其業務上應盡之義務，並應參考同區段\n實價登錄案例，評估鑑定價值是否明顯偏離市場價值。\n（二）本府委託之專業估價者應參與本府召開之容積代金審議工作小組會\n議，並列席簡報說明。\n（三）申請人不得為該案件之專業估價者。\n（四）專業估價者不得以估價報告書業經工作小組檢視，而主張減免其錯\n誤、疏漏之責任。\n六、查估時限：\n申請人應於申請容積移轉掛件時，檢附前二個月內之查估報告書。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL078203","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"修正日期":"民國 104 年 09 月 21 日","公發布日":"民國 0 年 00 月 00 日","法規名稱":"彰化縣政府容積移轉委託專業估價原則","法規體系":"建設類","發文字號":"府建管字第1040314913A號"},"promulgation_date":null,"revision_date":"2015-09-21","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL078203","status":"unknown","title":"彰化縣政府容積移轉委託專業估價原則","last_checked_at":"2026-10-06T17:26:30+08:00","last_success_at":"2026-10-06T17:26:30+08:00","verification_status":"fetched","content_hash":"94cb3415ae783782109ce143514828c763a303e10d5df545dc323589b5b63a1f","history":[{"observed_at":"2026-10-06T17:26:30+08:00","content_hash":"94cb3415ae783782109ce143514828c763a303e10d5df545dc323589b5b63a1f","change_kind":"initial","revision_date":"2015-09-21"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"彰化縣政府市區道路養護及管理績效考評要點 立法理由.txt","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=206&id=FL088182&type=LAW"},{"name":"附件一「彰化縣政府市區道路養護及管理績效考評」評分表.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=1806&id=FL088182&type=LAW"},{"name":"附件二.PDF","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=208&id=FL088182&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"一、彰化縣政府（以下簡稱本府）為加強市區道路維護管理，以提昇道路\n服務品質，特訂定本要點。\n二、本要點之主管機關為本府工務處，管理機關為各鄉（鎮、市）公所（\n以下簡稱各公所）。\n三、本府排定每年四月至五月辦理實地考評各公所前年度平時道路養護執\n行狀況，並得視業務需要提前或延後辦理。\n四、本要點考核範圍、方式及內容如下：\n（一）考評範圍原則為各公所轄管之寬度八公尺以上市區道路；無寬度八\n公尺以上道路者，以其轄內主要道路為考評範圍。\n（二）考評方式為各公所於考評日之前一周提報三條市區道路（含一條人\n行道），提報長度至少需為二百公尺以上。\n（三）考評內容分為「政策作為」及「實際作為」，其考評項目及權重分\n配內容，詳附件一及附件二。\n圖表附件：\n附件一「彰化縣政府市區道路養護及管理績效考評」評分表.pdf\n附件二.PDF\n五、本要點考評小組由本府工務處處長擔任召集人及當然委員，本府工務\n處副處長及技正擔任副召集人及當然委員，其餘考評委員得遴聘府外\n道路交通專家或社福團體人士擔任，並由彰化縣環境保護局、彰化縣\n警察局、本府交通處、本府農業處及本府工務處道路管理科各派一人擔任。\n前項考評小組由召集人召集及領隊；召集人因故不能出席時，由召集\n人指派副召集人代為出席；副召集人因故不能出席時，由副召集人指\n定委員一人代理之。\n六、本要點考評成績併入本府對各公所財政收支考核成績計算之。\n七、依「彰化縣政府市區道路養護及管理績效考評要點」評等結果，予以\n獎勵：\n（一）第一名：為總成績分數最高者，業務主管及主辦人員記功一次。\n（二）第二名：為總成績分數次高者，業務主管及主辦人員嘉獎二次。\n（三）第三名：為總成績分數第三高者，業務主管及主辦人員嘉獎一次。\n八、歷次考評內容應做成紀錄，並彙整保存，便於長期追蹤改善。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL088182","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"修正日期":"民國 112 年 09 月 21 日","公發布日":"民國 0 年 00 月 00 日","法規名稱":"彰化縣政府市區道路養護及管理績效考評要點","法規體系":"工務類","發文字號":"府工管字第1120372574號","立法理由":"彰化縣政府市區道路養護及管理績效考評要點 立法理由.txt"},"promulgation_date":null,"revision_date":"2023-09-21","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL088182","status":"unknown","title":"彰化縣政府市區道路養護及管理績效考評要點","last_checked_at":"2026-10-06T17:26:45+08:00","last_success_at":"2026-10-06T17:26:45+08:00","verification_status":"fetched","content_hash":"cbf1cd0ffa721b59eecdea71068c18839598bb06ac2e6e613a60091873825be3","history":[{"observed_at":"2026-10-06T17:26:45+08:00","content_hash":"cbf1cd0ffa721b59eecdea71068c18839598bb06ac2e6e613a60091873825be3","change_kind":"initial","revision_date":"2023-09-21"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=206&id=FL088182&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=1806&id=FL088182&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=208&id=FL088182&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"修正對照表.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=2142&id=FL026533&type=LAW"},{"name":"修正總說明.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=2141&id=FL026533&type=LAW"},{"name":"彰化縣政府建造執照申請有關特殊結構委託審查原則.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=2143&id=FL026533&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"一、審查範圍：\n（一）建築物高度超過五十公尺者。\n（二）鋼筋混凝土構造且設計跨度在十八公尺以上（屋頂層除外）之建築\n物。\n（三）地下層開挖之總深度（含基礎）在十二公尺以上，或地下層開挖超\n過三層之建築物。但開挖邊界與基地境界線之最小距離大於開挖深\n度者，不在此限。\n（四）建築基地位於都市計畫圖所劃設之活動斷層地區或經中央地質主管\n機關公告之山崩與地滑地質敏感區，其地下層開挖之總深度（含基\n礎）在七公尺以上之建築物。\n（五）其他經彰化縣政府（以下簡稱本府）認為有必要者。\n二、審查機關：\n（一）台灣大學地震工程研究中心。\n（二）台灣省建築師公會。\n（三）台灣省土木技師公會。\n（四）台灣省結構技師公會。\n（五）台灣省大地工程技師公會。\n（六）其他經本府同意之專業機關或團體。\n各審查機關、團體之審查人員以參加前各機關、學會之一為限。\n三、委託方式：\n起造人於領得本府核發之建造執照後，應自行擇定第二點所列審查機\n關、團體之一，並檢送審查所需書圖文件至本府，由本府函請該機關\n、團體審查，建造執照變更設計申請案仍由原審查機關、團體辦理。\n但建築物之結構係由擔任審查人員設計者，不得委託該審查人員所屬\n之機關、團體辦理審查。\n四、審查方式：\n（一）每一案件之審查人員應在五人以上，除較單純之局部變更設計案件\n外，應以公開形式審查，並容許自由旁聽，對審查通過之結構計算\n書及施工圖說，須加蓋審查人員圖章及審查機關印鑑並具審查意見\n書。\n（二）本府認有必要得於審查機關審查完成送回本府時，邀請審查機關簡\n報說明。\n（三）委託審查之案件係由審查人員所設計者，該審查人員不得參與該案\n件之審查。\n五、審查作業：\n（一）審查費用由起造人支付，並由起造人逕向審查機關繳納。\n（二）建造執照審核，除依照內政部訂頒之「改進建築管理方案實施要點\n」改進措施之作業要點二，應審核之主要項目審查合格發照外，有\n關由建築師簽證負責之結構部分，均列入必須抽查管理，由本府依\n第三點之委託方式於發照後一個月內辦理委託審查，且應依建築法\n第五十四條規定申報開工期限以前，經審查合格將審查結果通知本\n府，始得申報開工，逾期執照依法作廢。\n六、審查時限：\n委託審查案件須於文到後二個月審查完成，並將審查結果函知本府。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL026533","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"修正日期":"民國 113 年 01 月 05 日","全文檔案":"彰化縣政府建造執照申請有關特殊結構委託審查原則.pdf","公發布日":"民國 90 年 07 月 13 日","法規名稱":"彰化縣政府建造執照申請有關特殊結構委託審查原則","法規體系":"建設類","發文字號":"府建管字第1130005907號","立法理由":"修正對照表.pdf 修正總說明.pdf"},"promulgation_date":"2001-07-13","revision_date":"2024-01-05","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL026533","status":"unknown","title":"彰化縣政府建造執照申請有關特殊結構委託審查原則","last_checked_at":"2026-10-06T17:26:32+08:00","last_success_at":"2026-10-06T17:26:32+08:00","verification_status":"fetched","content_hash":"51a7451b813ecbd23a869421a247705532b5b3e1c22fc2ab2bdfb51169e19e3a","history":[{"observed_at":"2026-10-06T17:26:32+08:00","content_hash":"51a7451b813ecbd23a869421a247705532b5b3e1c22fc2ab2bdfb51169e19e3a","change_kind":"initial","revision_date":"2024-01-05"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=2142&id=FL026533&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=2141&id=FL026533&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=2143&id=FL026533&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"彰化縣政府","category":"建築管理相關","content":"一、彰化縣政府（以下簡稱本府）為確保彰化縣（以下簡稱本縣）各級道\n路維護及管理工作之管線資料品質，並使申請單位辦理管線施作及圖\n資更新維護作業有所依循，特訂定本要點。\n二、本要點用詞定義如下：\n（一）公共設施管線：係指電信、電力、自來水、下水道、瓦斯、水利設\n施、輸油輸氣、綜合（寬頻管道）等八大類管線。\n（二）路權單位：係指辦理本縣轄內之縣道、鄉道、市區道路、村里道路\n或產業道路等各級（類）道路之挖掘管理相關業務之權責機關或單\n位。\n（三）申請單位：指施設各類公共設施管線進行營運、維護等業務之事業\n單位。\n（四）圖資：係指以測量方式建立公共設施管線資料位相關係，並以紙本\n或數值化檔案方式呈現者。\n三、本要點之主管機關為本府，管理機關為各路權單位。\n四、申請單位申請於道路上進行管線設施之新設、變更、遷移、報廢、更\n新及維護工作時，應辦理公共設施管線及其固定設施物調查及測量，\n申請單位可採用全測站（Total Station） 法，或衛星定位測量（\nGPS/GNSS）法，以提供「公共設施管線資料庫」之相關應用，其施作\n規定如下：\n（一）全測站（Total Station） 法\n1.各類孔蓋及管線位置資料（包括位置坐標、管線及孔蓋種類代碼\n等資料）直接記錄於記錄器內，並引用本府佈設之地形圖測繪控\n制點、內政部之三等衛星控制點（含）以上或經本府核定公告之\n控制點作為量測引用之依據。如有採用導線測量進行補點時，須\n將位置明確標示（包括轉點計算所有之方位角及距離資料），並\n製作點之記號。\n2.導線測量之平面坐標系統應採用 TWD97  或 TWD97（2010）二度\n分帶坐標系統；高程坐標以採用 TWVD2001 高程控制系統為宜。\n3.全測站法之導線測量每測站正倒鏡二測回以上，觀測值之誤差不\n得超過十秒。\n4.全測站法之導線測量部份整體水平角閉合差不得大於 10”√N（\nN 為導線總點數），位置閉合差需小於一萬分之一方可使用。\n5.管線量測之範圍須涵蓋全部人手孔蓋及管線路徑（含管線起末端\n、轉折點及分支點）。\n6.相關測量點位均需測量平面坐標及高程。\n7.孔蓋中心坐標施測成果之容許誤差為正負二十公分。管線直線之\n線形坐標施測成果之容許誤差正負三十公分。管線轉折部份之特\n殊線形坐標施測成果之容許誤差為正負五十公分。\n8.孔蓋蓋頂高程與管線轉折點（及分支點）之高程測量，得利用由\n已知控制點所佈設之導線點，採間接高程之施測，其高程施測成\n果容許誤差為正負二十公分。\n9.孔蓋、管線及固定設施物之測量及現場記錄項目須包含坐標、間\n接高程、類別、所屬單位等。\n（二）衛星定位測量法\n1.採衛星定位測量法作業者，應按「基本測量實施規則」等相關作\n業規定進行施測。\n2.管線量測之範圍須涵蓋全部人手孔蓋及管線路徑（含管線起末端\n、轉折點及分支點）。\n3.相關測量點位均需測量平面坐標及高程。\n4.孔蓋中心坐標施測成果之容許誤差為正負二十公分。管線直線之\n線形坐標施測成果之容許誤差正負三十公分。管線轉折部份之特\n殊線形坐標施測成果之容許誤差為正負五十公分。\n5.孔蓋蓋頂高程與管線轉折點（及分支點）之高程測量，得利用由\n已知控制點所佈設之導線點，採間接高程之施測，其高程施測成\n果容許誤差為正負二十公分。\n6.孔蓋、管線及固定設施物之測量及現場記錄項目須包含坐標、間\n接高程、類別、所屬單位等。\n7.上述之測量定位作業得以符合內政部規定之衛星定位測量方式（\n需採用測量等級之儀器，包括天線、接收器及記錄器等）進行。\n衛星定位測量之點位坐標得採套合方式轉換至 TWD97  或 TWD97\n（2010）二度分帶坐標系統上，惟轉換後之成果仍應符合前述之\n各項測量精度要求。\n五、現場測量完成之資料，需保留原始資料並制作相關表單（如記錄器資\n料、控制點及導線測量成果、孔蓋及管線測量成果等），並由申請單\n位或測量技師簽證保障資料品質。\n六、申請單位於施工作業過程中，須拍攝施工現場數位相片，並以 .jpg\n檔儲存，每張相片檔案不得超過五○○  KB，且拍攝文字及測量數字\n部分需清晰顯示內容，不得模糊難辨），數位相片以能清楚清楚展示\n施工之範圍、管線佈設完成、回填前、測量標記及工程情況為主。拍\n攝需分為開工前（現況）、施工中（含交通維持、道路切割面、挖掘\n機具、挖掘深度測量、管線佈設）及完工後（含回填復原、劣實機具\n、取樣會簽）等三大類。\n七、依本府管線資料庫之屬性資料規定格式，由各申請單位至少針對屬性\n資料之必要項目需求進行現地調查及度量，以供製作圖資之屬性資料\n。\n八、施作完成之成果資料應進行圖資更新維護作業，其規定如下：\n（一）將外業測量之成果於內業進行轉換並數化，並以本府所指定之公布\n基本地形底圖進行套疊檢核，以確認施測成果與地形圖一致。\n（二）依本府管線資料庫屬性規定格式，進行各申請單位屬性資料格式設\n定及資料內容之建置工作，並與外業測量值轉換之數位化成果建置\n聯結。外業施工之規模若屬非必要測量之作業（如抽換、檢修、用\n戶接管在十平方公尺以下等），則由申請單位於完工時申請時提供\n說明，並由路權單位核判圖資更新作業之必要性。\n（三）圖形檔之每一屬性註記均需能對應在屬性資料庫中之每一屬性資料\n；而屬性資料庫中之每一筆資料也只對應圖形檔中之一個屬性註記\n。\n（四）屬性資料的檢核動作必須確實，可使用程式偵測可能之人為誤差，\n並修正檢核之。\n（五）經檢核完成之圖形及屬性檔，依本府規定之管線圖資標準交換格式\n（GML） 製作標準交換檔，並於工程完工時由系統提供之圖資更新\n功能界面上傳。\n九、申請單位於完工時除相關竣工書面資料外，並應製作下列檔案內容，\n上傳至本縣道路挖掘業務管理系統，於辦理申報完工及結案程序，併\n同竣工資料送路權單位備查。\n（一）測量成果檔案：例如記錄器資料，控制點及導線測量成果、孔蓋及\n管線測量成果相關證明資料，相關資料直接壓縮成 .rar 或 .zip\n之壓縮檔案，於系統上申報完工時直接透過系統上傳。\n（二）施工數位相片檔案（製作 .jpg 格式），除依各路權單位規定繳交\n外，並挑選具代表性數位照片，於系統上申報完工時直接透過系統\n上傳，並註記基本說明。\n（三）依本府規定之管線圖資標準交換格式（GML 格式）製作標準交換檔\n，並須與系統上傳檔案一致。\n（四）其他竣工規定之相關資料檔。\n十、申請單位須保障圖資品質，主管機關得隨時予以抽查，如發現資料未\n上傳或有缺漏、錯誤、不符測量精度要求者，並得通知申請單位自行\n補測或補正相關圖資。\n十一、公共設施管線資料庫係為各申請單位提供圖資並數值化後建立，使\n用人引用時，仍應查證，必要時亦須辦理試挖作業確認。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL088162","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"公發布日":"民國 102 年 10 月 03 日","法規名稱":"彰化縣政府管線施工作業及圖資更新維護作業要點","法規體系":"工務類","發文字號":"府工管字第1020307016號"},"promulgation_date":"2013-10-03","revision_date":"2013-10-03","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL088162","status":"unknown","title":"彰化縣政府管線施工作業及圖資更新維護作業要點","last_checked_at":"2026-10-06T17:26:48+08:00","last_success_at":"2026-10-06T17:26:48+08:00","verification_status":"fetched","content_hash":"ba2ec0c53390e918f1d29bb9c4d61c1fef005e9c5db5bf591d2f9ff866bdfed8","history":[{"observed_at":"2026-10-06T17:26:48+08:00","content_hash":"ba2ec0c53390e918f1d29bb9c4d61c1fef005e9c5db5bf591d2f9ff866bdfed8","change_kind":"initial","revision_date":"2013-10-03"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"彰化縣政府處理違反公寓大廈管理條例事件統一裁罰基準附表.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=4013&id=GL000485&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"情節重大或特殊案件，經依行政罰法第十八條規定審酌後得於法定罰鍰額度內加重或減輕處罰，並應敘明理由。\n違反公寓大廈管理條例事件之裁罰基準如附表規定。\n圖表附件：\n彰化縣政府處理違反公寓大廈管理條例事件統一裁罰基準附表.pdf\n彰化縣政府為加強執行違反公寓大廈管理條例規定事件，並符合依法行政、裁罰之明確性、適當性與公平性及符合比例原則，以減少行政裁處爭議及明確裁罰金額，特訂定本基準。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:GL000485","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"公發布日":"民國 115 年 09 月 08 日","法規名稱":"彰化縣政府處理違反公寓大廈管理條例事件統一裁罰基準","法規體系":"建設類","發文字號":"府建使字第1150366568號令"},"promulgation_date":"2026-09-08","revision_date":"2026-09-08","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=GL000485","status":"unknown","title":"彰化縣政府處理違反公寓大廈管理條例事件統一裁罰基準","last_checked_at":"2026-10-06T17:26:37+08:00","last_success_at":"2026-10-06T17:26:37+08:00","verification_status":"fetched","content_hash":"0f4508e3301d794d4a5dbae52da2a5a1b17e65f28a76bbcaa75e7810170adc90","history":[{"observed_at":"2026-10-06T17:26:37+08:00","content_hash":"0f4508e3301d794d4a5dbae52da2a5a1b17e65f28a76bbcaa75e7810170adc90","change_kind":"initial","revision_date":"2026-09-08"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=4013&id=GL000485&type=LAW":null}},{"articles":[],"attachment_required":true,"attachments":[{"name":"彰化縣政府轄管橋梁災害應變封橋標準作業程序.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=1005&id=GL000184&type=LAW"},{"name":"彰化縣政府轄管橋梁災害應變封橋標準作業程序修正草案總說明及對照表.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=1006&id=GL000184&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"","coverage_note":"官方網頁僅提供附件；正文需另行讀取附件。","effective_date":null,"effective_note":"","id":"changhua:GL000184","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"公發布日":"民國 109 年 03 月 18 日","圖表附件":"彰化縣政府轄管橋梁災害應變封橋標準作業程序.pdf 彰化縣政府轄管橋梁災害應變封橋標準作業程序修正草案總說明及對照表.pdf","法規名稱":"彰化縣政府轄管橋梁災害應變封橋標準作業程序","法規體系":"工務類","發文字號":"府工管字第1090076304號 函"},"promulgation_date":"2020-03-18","revision_date":"2020-03-18","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=GL000184","status":"unknown","title":"彰化縣政府轄管橋梁災害應變封橋標準作業程序","last_checked_at":"2026-10-06T17:26:46+08:00","last_success_at":"2026-10-06T17:26:46+08:00","verification_status":"attachment_pending","content_hash":"fbdb6526340187b9943e2b2654786eb25ff7c41ad336c5009e3cb04ed1931e07","history":[{"observed_at":"2026-10-06T17:26:46+08:00","content_hash":"fbdb6526340187b9943e2b2654786eb25ff7c41ad336c5009e3cb04ed1931e07","change_kind":"initial","revision_date":"2020-03-18"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=1005&id=GL000184&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=1006&id=GL000184&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"彰化縣政府","category":"建築管理相關","content":"第1條\n彰化縣政府（以下簡稱本府）為順利推動彰化縣各項交通、水利工程之興\n建，提升用地取得之效率，特訂定本辦法。\n第2條\n本辦法適用範圍以興辦事業計畫奉核定之各項交通、水利工程，並符合下\n列要件者為限：\n一  具有使用公有土地未與所有權（管理）人訂定使用（租賃）契約之具\n體事實；或具有位於未登錄地上之標的物之具體事實，而有發放之必\n要者。\n二  前款之事實，以在交通、水利工程事業興辦計畫核定前存在者為限。\n第3條\n本辦法之發放標準如下：\n一  建築物（含雜項工作物）：在本府限定期限內提供本府拆除者，比照\n彰化縣公共設施拆遷建築改良物補償辦法之合法房屋補償價格發給百\n分之五十拆遷救濟金。\n二  農林作物、水產養殖物、畜禽；其救濟金依彰化縣當年度辦理徵收土\n地農林作物、水產養殖物、畜禽補償遷移費查估基準發給百分之五十\n救濟金。不另發給自動拆遷獎勵金。\n三  墳墓：墳墓墓主於限期內自行遷葬者，按查定遷葬金額百分之三十發\n給自動遷葬救濟金。\n四  生產設備搬遷及營業設備搬遷：不發給搬遷救濟金。\n第4條\n本辦法救濟金之經費由中央核定補助款或本府編列年度預算支應。\n第5條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:GL000022","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"公發布日":"民國 92 年 07 月 29 日","法規名稱":"彰化縣政府辦理交通水利工程使用公地救濟金發放辦法","法規體系":"工務類","發文字號":"彰化縣政府府法制字第 0920141703 號"},"promulgation_date":"2003-07-29","revision_date":"2003-07-29","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=GL000022","status":"unknown","title":"彰化縣政府辦理交通水利工程使用公地救濟金發放辦法","last_checked_at":"2026-10-06T17:26:52+08:00","last_success_at":"2026-10-06T17:26:52+08:00","verification_status":"fetched","content_hash":"056c34d4aad1779b4afa2d7d0bb85bb64acddd111d5cfb24f3d90674e4066ba3","history":[{"observed_at":"2026-10-06T17:26:52+08:00","content_hash":"056c34d4aad1779b4afa2d7d0bb85bb64acddd111d5cfb24f3d90674e4066ba3","change_kind":"initial","revision_date":"2003-07-29"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"附表彰化縣政府辦理建築物公共安全檢查違法案件統一裁罰基準表.PDF","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=177&id=FL028118&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"一、彰化縣政府（以下簡稱本府）為辦理建築法第九十一條、第九十一條\n之一、第九十一條之二、第九十五條之一規定之罰鍰案件，依循行政\n自我拘束原則暨裁量正當性原則予以適當及有效裁處，建立執法之公\n平性，減少民眾爭議，並提升公信力，特訂定本基準。\n二、本基準係考量行為人之違規次數及性質等因素而訂定，其詳細規定如\n附表。\n附表所稱第一、第二順序場所係依行政院訂頒「維護公共安全方案—\n營建管理部分」規定，第一順序場所為：Ａ1 類組、Ｂ1  類組、Ｂ2\n類組、Ｂ3 類組、Ｂ4 類組，第二順序場所為：Ｄ1 類組、Ｄ5 類組\n、Ｆ2 類組、Ｆ3 類組、Ｈ1 類組；所稱違規次數係指本基準發布實\n施後之查獲違規次數。\n圖表附件：\n附表彰化縣政府辦理建築物公共安全檢查違法案件統一裁罰基準表.PDF\n三、裁處時應以違反事實認定之，注意程序合法、完整，並依附表所訂基\n準表量罰。\n四、對於違規案情較為特殊者，得依照裁罰基準酌予加重或減輕處罰。但\n應敘明加重或減輕之理由。\n五、本基準經核定後發布實施。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL028118","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"修正日期":"民國 93 年 12 月 17 日","公發布日":"民國 92 年 11 月 10 日","法規名稱":"彰化縣政府辦理建築物公共安全檢查違法案件統一裁罰基準","法規體系":"建設類","發文字號":"府建使字第0930240346號"},"promulgation_date":"2003-11-10","revision_date":"2004-12-17","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL028118","status":"unknown","title":"彰化縣政府辦理建築物公共安全檢查違法案件統一裁罰基準","last_checked_at":"2026-10-06T17:26:34+08:00","last_success_at":"2026-10-06T17:26:34+08:00","verification_status":"fetched","content_hash":"c663b160602345f5bc6f03be0eb8286a0606b9154fe0f998e5c0aac7698e6ff5","history":[{"observed_at":"2026-10-06T17:26:34+08:00","content_hash":"c663b160602345f5bc6f03be0eb8286a0606b9154fe0f998e5c0aac7698e6ff5","change_kind":"initial","revision_date":"2004-12-17"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=177&id=FL028118&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"彰化縣政府辦理既成道路認定執行要點 立法理由.txt","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=209&id=FL088186&type=LAW"},{"name":"彰化縣政府辦理既成道路認定執行要點.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=1805&id=FL088186&type=LAW"},{"name":"申請書(附件一).odt","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=1803&id=FL088186&type=LAW"},{"name":"委託書(附件二).odt","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=1804&id=FL088186&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"一、彰化縣政府（以下稱本府）為辦理既成道路認定，特訂定本要點。\n二、申請者應檢附下列文件，向本府提出申請：\n（一）申請書（附件一）\n（二）土地登記簿謄本及地籍圖謄本各乙份（請逕向地政事務所申請）\n（三）道路現況照片\n（四）實測現況套繪地籍圖（應描述一個街廓以上，並標明地段、地號、\n方位、申請土地範圍及各種公共設施、道路之寬度，其比例不得小\n於地籍圖，\n應由測量技師本人簽署並加蓋技師執業圖\n記。）\n（五）非法定空地使用證明文件（非屬建築用地類別者免）\n（六）毗鄰申請地之建物建築執照及使用執照資料（無者免附）\n（七）街路巷道門牌編釘證明、戶政設籍資料（請逕向戶政事務所申請）\n（八）\n申請認定道路範圍之臺灣地區相片基本圖第一版(或七十一年附近年度空照相片)及第三版\n(或八十三年附近年度空照相片)（請逕向行政院農委會林務局農林航空測量所洽購）\n（九）委託書（附件二）\n前項申請文件不合規定，其可補正者，限期補正；不能補正或逾期未\n補正，或雖補正仍不符合規定者，得退回其申請。\n(十)\n土地所有權人同意申請證明文件(如申請人為土地所有權人免附)\n圖表附件：\n申請書(附件一).odt\n委託書(附件二).odt\n三、既成道路依司法院大法官釋字第四百號解釋理由書，基於巷道之寬\n度、使用性質、使用期間、通行情形及公益上需要等情形，依下列原\n則認定：\n（一）須為不特定之公眾通行所必要，而非僅為通行之便利或省時。\n（二）於公眾通行之初，土地所有權人並無阻止之情事。\n（三）須經歷之年代久遠而未曾中斷，所謂年代久遠雖不必限定其期間，\n但仍應以時日長久，一般人無復記憶其確實之起始，僅能知其梗概\n（例如始於日據時期、八七水災等）為必要。\n（四）依建築法規及民法等之規定，提供土地作為公眾通行之道路，與因\n時效而形成之既成道路不同，非大法官解釋所指之公用地役關係。\n前項所稱供公眾通行，具公用地役關係而為既成道路，應徵詢管理機\n關（單位）意見，管理機關（單位）應就其寬度、使用性質、使用期\n間、養護該路段歷史紀錄、通行情形公益上需要明確表示意見，以及\n有無取得土地所有權人供公眾通行同意書等相關資料。\n四、申請文件符合規定者，依下列程序辦理：\n（一）現場勘查：視需要會同有關機關（地政單位、戶政單位、水利單位\n、建管單位、當地公所、村里長等）及土地關係人，並通知申請人\n到場指引說明作成會勘紀錄。\n（二）現勘查明不合規定，其可補正者，限期補正；不能補正或逾期未補\n正，或雖補正仍不符合規定者，退回其申請。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL088186","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"修正日期":"民國 112 年 12 月 05 日","全文檔案":"彰化縣政府辦理既成道路認定執行要點.pdf","公發布日":"民國 105 年 04 月 12 日","法規名稱":"彰化縣政府辦理既成道路認定執行要點","法規體系":"工務類","發文字號":"府工管字第1120478988號","立法理由":"彰化縣政府辦理既成道路認定執行要點 立法理由.txt"},"promulgation_date":"2016-04-12","revision_date":"2023-12-05","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL088186","status":"unknown","title":"彰化縣政府辦理既成道路認定執行要點","last_checked_at":"2026-10-06T17:26:45+08:00","last_success_at":"2026-10-06T17:26:45+08:00","verification_status":"fetched","content_hash":"f69ac3d7eab5886b95881b8288eaf575291074a9552521f00b0b1f8a477c8bce","history":[{"observed_at":"2026-10-06T17:26:45+08:00","content_hash":"f69ac3d7eab5886b95881b8288eaf575291074a9552521f00b0b1f8a477c8bce","change_kind":"initial","revision_date":"2023-12-05"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=209&id=FL088186&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=1805&id=FL088186&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=1803&id=FL088186&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=1804&id=FL088186&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"第五點、第六點修正總說明及對照表.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=1800&id=GL000109&type=LAW"},{"name":"112年11月27日修正要點全文.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=1801&id=GL000109&type=LAW"},{"name":"附件一(流程圖).pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=882&id=GL000109&type=LAW"},{"name":"附件二(彰化縣政府辦理都市計畫農業區已建築供居住使用之合法建築物基地認定申請書).odt","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=883&id=GL000109&type=LAW"},{"name":"附件三(申請基地範圍圖).odt","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=884&id=GL000109&type=LAW"},{"name":"附件四(彰化縣政府辦理都市計畫農業區已建築供居住使用之合法建築物基地認定現地勘查表).odt","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=885&id=GL000109&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"一\n彰化縣政府(以下簡稱本府)為處理都市計畫法臺灣省施行細則第三十條規定之都市計畫農業區已建築供居住使用之合法建築物基地認定作業，特訂定本要點。\n二\n本要點所稱「都市計畫農業區已建築供居住使用之合法建築物基地」，係指坐落都市計畫農業區土地，在都市計畫發布前已存在且供居住使用之建築物所坐落之建築基地。\n三\n本要點所稱「建築基地」，係依據建築法第十一條規定，為供建築物本身所占之地面及其所應留設之法定空地。\n四\n合法建築物基地之認定範圍應包含空地面積，空地位置留設原則應於建築物四周，與建築物所占地面應相連接，連接部分寬度不得小於二公尺；倘申請之基地整筆土地面積經認定皆屬合法建築物之範圍，則合法建築物基地依該筆土地全部認定，不另計算其所留設之空地面積。\n五\n為辦理第二點規定之認定作業，本府設置彰化縣都市計畫農業區合法建築基地審認委員會(以下簡稱審認委員會)及現地勘查小組(以下簡稱現勘小組)。由現勘小組實地勘查，並彙整申請人提供之資料及實地勘查結果，提請審認委員會召開會議審認，並由申請人簡報說明之。\n六\n審認委員會置委員十三人，由秘書長兼任召集人，副召集人由建設處處長兼任，委員會委員由以下機關(單位)指派所屬人員擔任之：\n(一)本縣建築師公會專家一人。\n(二)本縣律師公會專家一人。\n(三)本府地政處、農業處代表各一人；建設處四人(建築管理科、使用管理科、城鄉計畫科、更新發展科代表各一人)。\n(四)專家學者三人。\n前項審認委員會外聘專家任期兩年，期滿得續聘(派)之，外聘專家於任期內出缺時，應補行聘派，其任期至原任期屆滿之日止。召集人、副召集人應隨其本職進退，召集人無法出席會議時，由副召集人或召集人指派人員主持會議。\n審認委員會議得邀請申請案件所在地之地政事務所、地方稅務局、鄉（鎮、市）公所、戶政事務所列席協助審認。\n七\n現勘小組由以下機關(單位)指派所屬人員擔任之：\n(一)建設處四人(建築管理科、使用管理科、城鄉計畫科、更新發展科代表各一人)。\n(二)農業處代表一人。\n(三)地政事務所、地方稅務局、鄉（鎮、市）公所代表各一人。(申請案件所在地之轄管單位)\n前項現勘小組得視案件實際需要，邀請有關機關(單位)協助書面審核或現場勘查。\n八\n申請認定都市計畫發布前已存在且供居住使用之建築物，應由申請人檢附下列證明文件之一(正本或影本，影本應標明與正本相符並蓋章)：\n(一)建築執照。\n(二)建物登記證明。\n(三)未實施建築管理地區建築物完工證明書。\n(四)載有該建築物資料之土地使用現況調查清冊或卡片之謄本。\n(五)繳納房屋稅憑證或稅籍證明。\n(六)繳納自來水費或電費證明。\n(七)地形圖。\n(八)都市計畫圖。\n(九)航照圖。\n(十)其它經政府機關或政府機關委託製作之圖像資料。\n前項申請人檢附之文件倘經審認委員會或現勘小組審查經認定有必要者，應另行補充檢附。\n第一項文件內已記載面積者，依其所載面積由現勘小組實地勘查作成紀錄以為合法建築物面積及所坐落建築基地之認定。未記載面積者，由現勘小組參考航照圖及實際供居住情形等相關資料實地勘查審認範圍，再請申請人自行委託測繪單位依審認範圍量測並繪製範圍圖或提出該建物測量成果圖交予現勘小組，以為合法建築物面積及所坐落建築基地之認定。\n九\n申請基地經現勘小組實地會勘認定後，其認定結果倘係以部分土地作為建築基地者，申請人得依認定之基地面積範圍向地政機關辦理土地分割作業。\n十\n設有抵押權之土地提出申請時，無須徵得抵押權人同意。但本府應將辦理結果通知抵押權人。\n十一\n本要點辦理作業程序如流程圖(附件一)所示。\n十二\n申請合法建築物基地認定作業，申請人應檢具下列書件向本府建設處提出申請：\n(一)申請書一份。(附件二)\n(二)本要點第八點之證明文件。\n(三)申請基地三個月內之土地登記謄本(第一類)及地籍圖謄本各一份。\n(四)使用分區證明。\n(五)原地目證明文件。\n(六)申請基地範圍圖說。(部分土地作為建築基地者應檢附，附件三)\n(七)申請人應為土地所有權人，共有土地提出申請時，應由全體共有人共同提出申請，並檢具身分證明文件，委託他人代理申請時應檢附委託書。\n(八)其他經機關(單位)認為必要之證明文件。\n申請基地如屬「田」地目者，應檢附鄉（鎮、市）公所簽註有無訂定三七五租約之證明文件；如屬「水」或「道」地目者，應檢附主管機關(單位)之無妨礙水利或交通之證明文件。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:GL000109","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"修正日期":"民國 112 年 11 月 27 日","全文檔案":"112年11月27日修正要點全文.pdf","公發布日":"民國 108 年 07 月 15 日","圖表附件":"附件一(流程圖).pdf 附件二(彰化縣政府辦理都市計畫農業區已建築供居住使用之合法建築物基地認定申請書).odt 附件三(申請基地範圍圖).odt 附件四(彰化縣政府辦理都市計畫農業區已建築供居住使用之合法建築物基地認定現地勘查表).odt","法規名稱":"彰化縣政府辦理都市計畫農業區已建築供居住使用之合法建築物基地認定作業要點","法規體系":"建設類","發文字號":"府建新字第1120453269號函","立法理由":"第五點、第六點修正總說明及對照表.pdf"},"promulgation_date":"2019-07-15","revision_date":"2023-11-27","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=GL000109","status":"unknown","title":"彰化縣政府辦理都市計畫農業區已建築供居住使用之合法建築物基地認定作業要點","last_checked_at":"2026-10-06T17:26:28+08:00","last_success_at":"2026-10-06T17:26:28+08:00","verification_status":"fetched","content_hash":"f986e09d176cb038b887959edb24da0543cf36e35117176948beb83eede687de","history":[{"observed_at":"2026-10-06T17:26:28+08:00","content_hash":"f986e09d176cb038b887959edb24da0543cf36e35117176948beb83eede687de","change_kind":"initial","revision_date":"2023-11-27"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=1800&id=GL000109&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=1801&id=GL000109&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=882&id=GL000109&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=883&id=GL000109&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=884&id=GL000109&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=885&id=GL000109&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"彰化縣政府","category":"建築管理相關","content":"一、彰化縣政府（以下簡稱本府）為執行「臺中港收容非公共工程土石方作業規定」（以下簡稱臺中港作業規定），協助申請人運送彰化縣非公共工程營建剩餘土石方（以下簡稱營建剩餘土石方）至臺中港收受事項，特訂定本要點。\n二、本要點之適用對象及管理機關如下：\n（一）依彰化縣營建剩餘土石方管理自治條例核准營運之土石方資源堆置處理場（以下簡稱土資場）產出之營建剩餘土石方，由本府水利資源處管理。\n（二）其他經本府各目的事業主管機關推薦具公益性或符合本府政策之民間建築工程所產出之營建剩餘土石方，由該推薦之目的事業主管機關管理。\n三、推薦機關應就其推薦之案件訂有回饋機制，倘以回饋金方式辦理，得參考本府公告之基準。\n四、申請人申請運送民間建築工程營建剩餘土石方至臺中港，應依彰化縣營建剩餘土石方管理自治條例相關規定辦理，並向營建剩餘土石方資訊服務中心申報剩餘土石方之總類、數量及去處，載運完成時亦同。\n土資場申請運送營建剩餘土石方至臺中港，應依營建剩餘土石方處理方案向管理機關申報剩餘土石方運送地點、名稱、收容期間、土質及數量，並向營建剩餘土石方資訊服務中心申報營建剩餘土石方出場總量，載運完成時亦同。\n五、申請人應就每一申請案辦理檢驗，其檢驗方式、結果及品質應按臺中港作業規定，並自主管理品質。\n土資場每批之體積數量原則應介於六百立方公尺至九千六百立方公尺，並經管理機關確認合格後始得載運進場。\n六、土資場申請運送至臺中港之營建剩餘土石方應單獨堆置，且有明顯區隔，不可與場內其他餘土或混合物混雜。送檢驗樣品應由管理機關隨機指定，土資場不得拒絕。\n七、每一申請案均應依臺灣港務股份有限公司臺中港務分公司（以下簡稱臺中港務分公司）開立之繳款單繳交保證金，並將繳交完成收據影本送管理機關備查後始得出土。全部營建剩餘土石方運送完畢且無違反臺中港作業規定時，由臺中港務分公司依所持收據正本無息退還保證金。\n八、臺中港務分公司為支應收土作業之管理成本等訂有營建剩餘土石方管理費，於每月辦理進場營建剩餘土石方管理費結算並通知管理機關，申請人於接獲管理機關轉交繳費單時，應於臺中港務分公司規定期限內將營建剩餘土石方管理費匯入指定銀行帳戶。\n九、申請人獲通知同意營建剩餘土石方載運進場後，應提送人員、車輛名冊資料予管理機關，以協助申請人員及車輛港區通行證。\n前項提送之營建剩餘土石方載運車輛應依臺中港作業規定裝置具逐車追蹤流向功能設備。\n十、申請人於出土期間應配合管理機關派員至收土端進行自主檢查，包含辨識營建剩餘土石方運送憑證之真偽、車載營建剩餘土石方之土質與出土相符及數量符合運送憑證上所載，檢查方式悉依臺中港作業規定辦理。\n十一、本要點未盡事宜，依臺中港作業規定辦理。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:GL000482","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"公發布日":"民國 115 年 07 月 20 日","法規名稱":"彰化縣政府辦理非公共工程運送營建剩餘土石方至臺中港作業要點","法規體系":"建設類","發文字號":"府建管字第1150271902A號令"},"promulgation_date":"2026-07-20","revision_date":"2026-07-20","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=GL000482","status":"unknown","title":"彰化縣政府辦理非公共工程運送營建剩餘土石方至臺中港作業要點","last_checked_at":"2026-10-06T17:26:26+08:00","last_success_at":"2026-10-06T17:26:26+08:00","verification_status":"fetched","content_hash":"26d42111d07ddf7e9890ed902f0a4393f1e33a6179e2d487c32b4beff14a64ce","history":[{"observed_at":"2026-10-06T17:26:26+08:00","content_hash":"26d42111d07ddf7e9890ed902f0a4393f1e33a6179e2d487c32b4beff14a64ce","change_kind":"initial","revision_date":"2026-07-20"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"彰化縣政府","category":"建築管理相關","content":"一、彰化縣政府（以下簡稱本府）為評議都市計畫容積移轉代金或土地變\n更回饋金，設立容積代金及回饋金估價工作小組（以下簡稱工作小組）\n，特訂定本作業要點。\n二、工作小組置委員九人，由本府代表一人兼任召集人，委員分別就下列\n人員聘（派）之：\n（一）本府財政處、地政處、建設處、主計處、工務處代表各一人。\n（二）具有都市計畫、不動產估價、建築、景觀、社會、法律、交通、財\n經、土地開發或地政等專門學識經驗之專家學者共三人。\n（三）中華民國不動產估價師公會全國聯合會一人。\n工作小組之召開，應有二分之一以上成員出席，且前項第二款及第三\n款成員人數合計應佔出席成員三分之一以上。\n本府派兼委員倘因故無法出席，應指定代理人出席會議。\n三、工作小組任務如下：\n（一）檢視容積代金或土地變更回饋金估價報告書（以下簡稱估價報告書）\n內容有無錯誤、疏漏。\n（二）檢視勘估標的有無參考同區段實價登錄案例，評估鑑定價值是否明\n顯偏離市場價值。\n（三）檢視估價報告書土地變更前後價值差異估價是否合理。\n（四）提供建議並評議容積代金或回饋金合理性。\n四、工作小組成員任期一年，期滿得續聘（任）之。成員因故出缺時，繼\n任成員之任期至原任期屆滿之日止。但代表機關出任者，應隨其本職\n進退。\n五、工作小組成員，應依相關規定迴避與個人有利害關係之案件，並對會\n議內容有保守秘密之義務。\n六、召開工作小組會議時得邀請不動產估價師及有關機關列席，估價報告\n書之簽證不動產估價師應就估價報告書說明。\n容積代金或回饋金申請人出席工作小組會議人數以三人為限，並得於\n會議中陳述意見。\n七、估價報告書經工作小組檢視後評議容積代金或回饋金。\n不動產估價師不得以估價報告書業經工作小組檢視，而主張減免其錯\n誤、疏漏之責任。\n八、工作小組成員均為無給職。但得依規定支給出席費、交通費或審查費\n。\n九、工作小組所需經費由本府容積代金專戶年度預算支應。\n專戶成立前，暫由本處業務費用支應。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL082622","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"修正日期":"民國 110 年 08 月 23 日","公發布日":"民國 104 年 09 月 01 日","法規名稱":"彰化縣政府都市計畫容積移轉代金及土地變更回饋金估價工作小組作業要點","法規體系":"建設類","發文字號":"府建新字第1100295978號"},"promulgation_date":"2015-09-01","revision_date":"2021-08-23","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL082622","status":"unknown","title":"彰化縣政府都市計畫容積移轉代金及土地變更回饋金估價工作小組作業要點","last_checked_at":"2026-10-06T17:26:29+08:00","last_success_at":"2026-10-06T17:26:29+08:00","verification_status":"fetched","content_hash":"a4cd9697488c03fb4ab9f6e5200462520bcff5c23be2cd56b782256f39aff114","history":[{"observed_at":"2026-10-06T17:26:29+08:00","content_hash":"a4cd9697488c03fb4ab9f6e5200462520bcff5c23be2cd56b782256f39aff114","change_kind":"initial","revision_date":"2021-08-23"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"中華民國九十二年十二月三十一日彰府九十二府法制字第 09250830 號令訂定.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=3318&id=FL049413&type=LAW"},{"name":"中華民國九十七年六月二十五日彰化縣政府府法制字第 0970130407 號 令修正發布第 1、2、5 條條文.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=3319&id=FL049413&type=LAW"},{"name":"中華民國一百十三年十二月二日彰化縣政府府行法字第 1130459898 號 令修正發布第 4 條條文.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=3320&id=FL049413&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"第 1 條\n本辦法依建築法第七十三條第一項但書及彰化縣建築管理自治條例第三十\n九條之二第一項規定訂定之。\n第 2 條\n本辦法所稱既有建築物，係於民國九十二年六月七日前存在之建築物。\n前項期日，以房屋稅單或房屋稅籍證明所載起課日期或房屋所有人設籍證\n明所載設籍日期認定之。\n第 3 條\n非供公眾使用之既有建築物，非為無權佔用公有土地、公共設施或排水設\n施用地且符合下列情形者之一者，得由房屋所有權人申請接水接電：\n一、因興辦公共設施所需而拆遷具整建需要且無礙都市計畫發展之建築物\n。\n二、天然災害損壞需安置及修復之建築物。\n三、其他有迫切民生需要之建築物。\n前項第三款所稱其他有迫切民生需要之建築物，得由當地鄉鎮市公所組成\n專案小組認定之。\n依第一項第一款、第二款申請接用水電應檢附用地或目的事業主管機關出\n具之證明文件。\n第一項所稱房屋所有權人，以房屋稅單所載納稅義務人或建造執照起造人\n認定之。\n第 4 條\n依本辦法申請既有建築物接用水接電，應檢附下列文件：\n一、申請書（如附件）。\n二、地籍圖謄本。\n三、依本辦法第二條、第三條規定提出之文件。\n四、建物位置圖、平面圖、立面簡圖（應標明各樓層尺寸及隔間）。\n五、建物各方向照片。\n第 5 條\n依本辦法第四條提出之申請案，經審查合格者，得發給接用水電同意函，\n並副知自來水公司及電力相關單位。\n第 6 條\n本府得委由各鄉鎮市公所核發接水、接電同意函。\n第 7 條\n依本辦法申請接用水電之既有建築物仍不視為合法建築物；如違反建築法\n或其他法令遭停止供水、電者，不得再適用之。申請人有侵害他人財產或\n肇致危險或傷害他人時，應自負法律責任。\n第 8 條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL049413","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"修正日期":"民國 113 年 12 月 02 日","公發布日":"民國 92 年 12 月 31 日","法規名稱":"彰化縣未領得使用執照之既有建築物申請接用水電辦法","法規體系":"建設類","發文字號":"府行法字第1130459898號","立法理由":"中華民國九十二年十二月三十一日彰府九十二府法制字第 09250830 號令訂定.pdf 中華民國九十七年六月二十五日彰化縣政府府法制字第 0970130407 號 令修正發布第 1、2、5 條條文.pdf 中華民國一百十三年十二月二日彰化縣政府府行法字第 1130459898 號 令修正發布第 4 條條文.pdf"},"promulgation_date":"2003-12-31","revision_date":"2024-12-02","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL049413","status":"unknown","title":"彰化縣未領得使用執照之既有建築物申請接用水電辦法","last_checked_at":"2026-10-06T17:26:38+08:00","last_success_at":"2026-10-06T17:26:38+08:00","verification_status":"fetched","content_hash":"92a4d6bb024d596494660781bd4fdd82d58bee8bc07e96b42b95abb58469f188","history":[{"observed_at":"2026-10-06T17:26:38+08:00","content_hash":"92a4d6bb024d596494660781bd4fdd82d58bee8bc07e96b42b95abb58469f188","change_kind":"initial","revision_date":"2024-12-02"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=3318&id=FL049413&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=3319&id=FL049413&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=3320&id=FL049413&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"彰化縣政府","category":"建築管理相關","content":"一、彰化縣政府為辦理民眾申請營利事業登記，其建築物用途之審查，除\n依「彰化縣營利事業登記建築物用途審查辦法」有關規定外，另依本\n補充規定辦理。\n二、以舊有合法房屋申請營利事業登記，其面積不明者，應委請建築師繪\n製並標示營業範圍及面積。但經申請人繪製營業範圍平面圖標明尺寸\n面積且與切結營業面積相符者，不在此限。\n三、非屬舊有合法房屋申請營利事業登記時，應以整層範圍為之。但申請\n範圍以具有一小時防火時效之防火牆、防火門窗區劃分開且不妨害或\n破壞其他範圍之防火避難設施，並符合下列各款情形者，得以局部範\n圍申請作為營業使用：\n(一) 依使用執照記載該申請樓層僅供一種用途使用。\n(二) 檢具該樓層平面圖說，標明該樓層之防火避難設施、防火區劃材料\n及營業範圍尺寸面積。\n四、下列建築物未涉及主要構造、防火區劃、防火避難設施變更者，由目\n的事業主管機關逕行辦理營利事業登記或立案登記。\n(一) 建築物第一層供作為Ｇ類第二組或Ｇ類第三組，其使用面積在二百\n五十平方公尺以下。\n(二) 建築物第二層供作為Ｇ類第二組使用、第一層供作為Ｇ類第三組使\n用，其使用面積合計在一百五十平方公尺以下。\n五、本補充規定自中華民國九十一年十月三十日實施。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL028107","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"公發布日":"民國 91 年 12 月 12 日","法規名稱":"彰化縣營利事業登記建築物用途審查補充規定","法規體系":"建設類","發文字號":"府建使字第09102343340號"},"promulgation_date":"2002-12-12","revision_date":"2002-12-12","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL028107","status":"unknown","title":"彰化縣營利事業登記建築物用途審查補充規定","last_checked_at":"2026-10-06T17:26:35+08:00","last_success_at":"2026-10-06T17:26:35+08:00","verification_status":"fetched","content_hash":"9d352d25b4dcf40950797a62790022715c1c7a4a289f394be87bd507e938f73c","history":[{"observed_at":"2026-10-06T17:26:35+08:00","content_hash":"9d352d25b4dcf40950797a62790022715c1c7a4a289f394be87bd507e938f73c","change_kind":"initial","revision_date":"2002-12-12"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"彰化縣政府","category":"建築管理相關","content":"第 1 條\n彰化縣政府為便利民眾申請營利事業登記時，辦理建築物營業用途及項目\n核對工作，特訂定本辦法。\n第 2 條\n本辦法所稱營業用途，係指申請營利事業登記之營業項目，依經濟部訂定\n之「公司行號營業項目代碼表」，於適用建築物所屬使用類組及用途。\n第 3 條\n建築物原非供公眾使用建築物，申請作為供公眾使用時，不適用本辦法，\n仍應依建築法規定辦理建築物用途變更後始得辦理營利事業登記或立案登\n記。\n第 4 條\n申請營利事業登記建築物用途審查，應由申請人或代理人檢附下列正本、\n影本 (應標明與正本相符並蓋章) 或謄本之證明文件及圖說：\n一  建築物使用證明文件\n(一) 舊有合法房屋：建築物完工日期合於下列規定者，應檢附繳納自來\n水費收據、電費收據、房屋稅籍證明、戶口遷入證明或建築物登記\n證明等任一種文件據以認定：\n1 都市計畫內：於當地都市計畫公布實施前建築完成者。\n2 都市計畫外：\nA 坐落於非屬田地目土地之建物：於民國六十九年六月一日前建\n築完成者。\nB 坐落於田地目土地一至十二等則之建物：於民國六十二年十二\n月二十四日前建築完成者。\nC 坐落於田地目土地十三至二十六等則之建物：於民國六十五年\n一月一日前建築完成者。\n(二) 非屬舊有合法房屋：應檢附建築物使用執照。\n二  土地使用分區證明書：都市計畫內者應檢附。\n三  土地登記簿謄本：都市計畫外之舊有合法房屋應檢附 (以認定是否為\n田地目) 。\n四  建築物平面圖說：下列情形應檢附：\n(一) 同一樓層供兩種以上用途 (含停車空間) 。\n(二) 舊有合法房屋面積不明者，應委請建築師繪製並標示營業範圍及面\n積。\n五  門牌整編證明：有經整編者應檢附。\n第 5 條\n（刪除）\n第 6 條\n使用舊有合法房屋第二層 (含) 以上，辦理營利事業登記或立案登記時應\n檢附建築師或結構技師或相關技師出具之結構安全證明書，簽證結構安全\n無虞，始得設立。上述證明書應為正本並敘明營業所在地、地號、面積、\n開立證明書之技師姓名、開業字號、地址並簽章。\n第 7 條\n建築物所有權人及使用人應於申請設立時，檢附申請範圍未有妨礙防火避\n難設施或構造設備之切結證明，並依法維護防火避難設施合法使用及構造\n設備安全。\n第 8 條\n營業範圍不得佔用建築物附設之停車空間、防空避難設備、自用貯藏室及\n其他公共設施。\n第 9 條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL028239","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"修正日期":"民國 91 年 12 月 13 日","公發布日":"民國 91 年 07 月 08 日","法規名稱":"彰化縣營利事業登記建築物用途審查辦法","法規體系":"建設類","發文字號":"府法制字第09102348140號"},"promulgation_date":"2002-07-08","revision_date":"2002-12-13","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL028239","status":"unknown","title":"彰化縣營利事業登記建築物用途審查辦法","last_checked_at":"2026-10-06T17:26:43+08:00","last_success_at":"2026-10-06T17:26:43+08:00","verification_status":"fetched","content_hash":"9d9add308dbc3c93a561c2453f570c87399c5455ecb24fe48040ab9c76989380","history":[{"observed_at":"2026-10-06T17:26:43+08:00","content_hash":"9d9add308dbc3c93a561c2453f570c87399c5455ecb24fe48040ab9c76989380","change_kind":"initial","revision_date":"2002-12-13"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"附表一：（機關全銜）道路挖掘申請書.PDF","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=146&id=FL067963&type=LAW"},{"name":"附表二：（機關全銜）道路挖掘許可證.PDF","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=147&id=FL067963&type=LAW"},{"name":"附表三：（機關全銜）道路挖掘開工報告書.PDF","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=148&id=FL067963&type=LAW"},{"name":"附表四：（機關全銜）道路挖掘完工報告書.PDF","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=149&id=FL067963&type=LAW"},{"name":"附件一：道路修復費用項目單價.PDF","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=150&id=FL067963&type=LAW"},{"name":"附件一：道路修復費用項目單價.PDF","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=151&id=FL067963&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"第 1 條\n本辦法依彰化縣道路挖掘管理自治條例（以下稱本自治條例）第十條及第\n二十七條規定訂定之。\n第 2 條\n申請道路挖掘者（以下稱申請人）應依本自治條例規定檢具申請書（附表\n一）及相關書件向管理機關（單位）申請核發道路挖掘許可證（附表二）\n。\n申請人於開工前應向管理機關（單位）提出開工報告書（附表三）申報開\n工。\n圖表附件：\n附表一：（機關全銜）道路挖掘申請書.PDF\n附表二：（機關全銜）道路挖掘許可證.PDF\n附表三：（機關全銜）道路挖掘開工報告書.PDF\n附表四：（機關全銜）道路挖掘完工報告書.PDF\n第 3 條\n申請人於道路挖掘竣工後應依本自治條例規定檢具完工報告書（附表四）\n及相關文件向管理機關（單位）申報完工。\n第 4 條\n申請道路挖掘，應依下列標準繳交許可費：\n一、申請面積在五十平方公尺以下者，每件新臺幣一千元。\n二、申請面積逾五十平方公尺且在一百平方公尺以下者，每件新臺幣一千\n五百元。\n三、申請面積逾一百平方公尺且在二百平方公尺以下者，每件新臺幣三千\n元。\n四、申請面積逾二百平方公尺者，每件除收取新臺幣三千元之基本費外，\n其逾二百平方公尺部分，每增加二百平方公尺加徵新臺幣三千元，其\n餘數不足 二百平方公尺者，不予加徵。\n前項第一款之申請案件屬因設置郵筒、家庭用戶新申裝管線設施或緊急搶\n修所提出者。依下列標準繳交許可費：\n一、申請面積在十平方公尺以下者，每件新臺幣一百元。\n二、申請面積逾十平方公尺，未達五十平方公尺者，每件新臺幣五百元。\n第 5 條\n道路修復費用，以項目單價乘以第六條之收費面積計算之。\n前項項目單價如附件一。\n圖表附件：\n附件一：道路修復費用項目單價.PDF\n第 6 條\n道路修復費用之面積計算方式如下：\n一、挖掘路段道路改善（或路面加封）未滿七年者，按挖掘長度乘以全路\n幅寬度所得面積，核算修復費用（有分向島者，以分向島單側之路幅\n寬度計算修復面積）。\n二、挖掘路段道路改善（或路面加封）已滿七年者，按挖掘長度乘以二分\n之一路幅寬度所得面積，核算修復費用（有分向島者，以分向島單側\n之路幅寬度計算修復面積；四車道以上者，以道路中心分向線單側之\n路幅寬度計算修復面積）。\n三、配合年度路面整修工程者，按挖掘長度乘以管道佔用車道寬度所得面\n積，核算修復費用。\n四、橫越管道及零星挖掘路段，按管道佔用瀝青混凝土車道寬度乘以四公\n尺長度涵蓋面積計算。\n零星挖掘定義如下：\n（一）挖掘機（慢）車道、自行車道或路肩，且連續路段挖掘總面積不超\n過一百平方公尺者。\n（二）挖掘快車道或混合車道，且連續長度不超過四公尺者。\n（三）屬一般用戶申請接管性質，面積不超過一百平方公尺者。\n五、不同申請人同時於相同道路範圍申挖者，依挖掘長度所佔比例分攤核\n算收費。\n六、符合經濟部水利署無自來水地區供水改善計畫自來水延管工程申請及\n管考作業要點規定，經管理機關專案核准者，得減收或免收修復費。\n挖掘破壞之道路設施，未屬附件一內所列性質者，其修繕所需費用，由申\n請人與管理機關（單位）以協議方式辦理。\n圖表附件：\n附件一：道路修復費用項目單價.PDF\n第 7 條\n本辦法第五條規定項目以外之道路挖掘，由申請人與道路管理機關（單位\n）參考市價並評估所需費用，以協議方式辦理。\n第 8 條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL067963","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"修正日期":"民國 104 年 08 月 28 日","公發布日":"民國 101 年 08 月 03 日","法規名稱":"彰化縣申請道路挖掘及修復收費辦法","法規體系":"工務類","發文字號":"府法制字第1040292213號"},"promulgation_date":"2012-08-03","revision_date":"2015-08-28","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL067963","status":"unknown","title":"彰化縣申請道路挖掘及修復收費辦法","last_checked_at":"2026-10-06T17:26:51+08:00","last_success_at":"2026-10-06T17:26:51+08:00","verification_status":"fetched","content_hash":"944d72ab021a2ed568b1a6845e9a4557489082c15d98031b8de4caea1992320a","history":[{"observed_at":"2026-10-06T17:26:51+08:00","content_hash":"944d72ab021a2ed568b1a6845e9a4557489082c15d98031b8de4caea1992320a","change_kind":"initial","revision_date":"2015-08-28"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=146&id=FL067963&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=147&id=FL067963&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=148&id=FL067963&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=149&id=FL067963&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=150&id=FL067963&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=151&id=FL067963&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"彰化縣政府","category":"建築管理相關","content":"第 1 條\n本自治條例依建築法（以下簡稱本法）第四十六條規定制定之。\n第 2 條\n畸零地及其相鄰土地之使用管理，依本自治條例之規定。\n前項所稱畸零地，係指本法第三條規定地區內面積狹小之基地。\n第 3 條\n本自治條例所稱面積狹小基地，指建築基地深度及寬度任一項未達下列規\n定者︰\n一、一般建築用地\n┌──────────┬───┬───┬───┬───┬───┐\n│            使用分區│甲、乙│商業區│丙種建│丁種建│其他使│\n│            或使用地│種建築│      │築用地│築用地│用分區│\n│            別      │用地、│      │及風景│及工業│      │\n│基地情形            │住宅區│      │區    │區    │      │\n│（公尺）            │      │      │      │      │      │\n├─────┬────┼───┼───┼───┼───┼───┤\n│正面路寬七│最小寬度│   3.0│   3.5│   6.0│   7.0│   3.5│\n│公尺以下  │最小深度│  12.0│  11.0│  20.0│  16.0│  12.0│\n├─────┼────┼───┼───┼───┼───┼───┤\n│正面路寬超│最小寬度│   3.5│   4.0│   6.0│   7.0│   4.0│\n│過七公尺至│最小深度│  14.0│  15.0│  20.0│  16.0│  16.0│\n│十五公尺  │        │      │      │      │      │      │\n├─────┼────┼───┼───┼───┼───┼───┤\n│正面路寬超│最小寬度│   4.0│   4.5│   6.0│   7.0│   4.5│\n│過十五公尺│最小深度│  16.0│  15.0│  20.0│  16.0│  17.0│\n│至二十五公│        │      │      │      │      │      │\n│尺        │        │      │      │      │      │      │\n├─────┼────┼───┼───┼───┼───┼───┤\n│正面路寬超│最小寬度│   4.0│   4.5│   6.0│   7.0│   4.5│\n│過二十五公│最小深度│  16.0│  18.0│  20.0│  16.0│  18.0│\n│尺        │        │      │      │      │      │      │\n└─────┴────┴───┴───┴───┴───┴───┘\n二、側面應留設騎樓之建築基地\n┌──────────────┬───┬───┬───┬───┐\n│                    使用分區│住宅區│商業區│工業區│其他使│\n│                            │      │      │      │用分區│\n│基地情形（公尺）            │      │      │      │      │\n├─────────┬────┼───┼───┼───┼───┤\n│正面路寬七公尺以下│最小寬度│   6.6│   6.6│   8.0│   6.6│\n│                  │最小深度│  12.0│  11.0│  16.0│  12.0│\n├─────────┼────┼───┼───┼───┼───┤\n│正面路寬超過七公尺│最小寬度│   7.1│   7.1│   8.0│   7.1│\n│至十五公尺        │最小深度│  14.0│  15.0│  16.0│  16.0│\n├─────────┼────┼───┼───┼───┼───┤\n│正面路寬超過十五公│最小寬度│   7.6│   7.6│   8.0│   7.6│\n│尺至二十五公尺    │最小深度│  16.0│  15.0│  16.0│  17.0│\n├─────────┼────┼───┼───┼───┼───┤\n│正面路寬超過二十五│最小寬度│   7.6│   7.6│   8.0│   7.6│\n│公尺              │最小深度│  16.0│  18.0│  16.0│  18.0│\n└─────────┴────┴───┴───┴───┴───┘\n前項其他使用分區不包括農業區暨保護區。但依獎勵投資條例及促進產業\n升級條例開發之工業住宅社區按前項第一款之甲、乙種建築用地及住宅區\n之規定辦理。\n第 4 條\n本自治條例所稱正面路寬、最小寬度及最小深度，其定義如下：\n一、正面路寬係指基地面前道路之寬度。\n二、最小寬度係指最小深度範圍內基地二側境界線間與道路境界線平行距\n離之最小值。但道路境界線為曲線者，以該曲線與基地兩側境界線交\n點之連線視為道路境界線。\n三、最小深度係指臨接之道路境界線至該基地後側境界線垂直距離之最小\n值。\n建築基地如屬角地應截角時，其寬度及深度係指截角前之寬度及深度。\n第 5 條\n建築基地臨接二條以上道路，起造人得選擇任一道路為面前道路。\n建築基地位於道路末端，其寬度及深度及方位由起造人選定之。\n前二項情形分別以任一道路為面前道路或以任一方位量距，其寬度及深度\n達到本自治條例所定最小寬度及深度之標準以上者，即不必與相鄰土地合\n併使用。\n道路境界線以外另定建築線之建築基地，其寬度及深度應自建築線起算。\n臨接退縮線之基地，其寬度應自退縮線起算，深度應自境界線起算。\n第 6 條\n依第三條規定之基地寬度，每增加十公分，其深度得減少二十公分，減少\n後之深度不得小於八公尺。\n應留設前後院地區，其基地深度減前後院深度之差不得小於六公尺。\n應留設側院地區，其基地寬度減側院寬度之差不得小於四公尺。\n應留設騎樓地區及臨接應退縮建築之土地，其基地深度減騎樓或退縮地深\n度之差不得小於八公尺。\n第 7 條\n面積狹小之基地非經補足所缺寬度、深度，不得建築。該基地周圍情形確\n實無法補足或整理，可供建築使用，並合於下列情形之一者，不在此限：\n一、鄰接地為道路、水溝、軍事設施或公共設施用地者。\n二、鄰接土地業己建築完成無法合併建築使用者。\n三、因地形上之障礙無法合併使用者。\n前項第二款所稱業已建築完成不包括車棚、花棚、圍牆及其他類似構造之\n簡易工作物。\n第 8 條\n實施區域計畫地區非都市土地在編定使用前，或實施都市計畫地區在中華\n民國六十二年七月十二日臺灣省畸零地使用規則發布施行前業經地政機關\n辦理分割完竣，或因都市計畫公共設施用地之劃定逕為分割完竣，面積狹\n小之基地符合於下列規定之最小寬度、深度及面積者，准予建築：\n┌───────────────────┬───────┐\n│                    使用分區或使用地別│甲、乙種建築用│\n│                                      │地、住宅區、商│\n│基地情形                              │業區          │\n├────────┬──────────┼───────┤\n│正面路寬七公尺以│最小寬度（公尺）    │      3.0     │\n│下              ├──────────┼───────┤\n│                │最小深度（公尺）    │      5.0     │\n│                ├──────────┼───────┤\n│                │最小面積（平方公尺）│     20.0     │\n├────────┼──────────┼───────┤\n│正面路寬超過七公│最小寬度（公尺）    │      3.5     │\n│尺至十五公尺    ├──────────┼───────┤\n│                │最小深度（公尺）    │      6.0     │\n│                ├──────────┼───────┤\n│                │最小面積（平方公尺）│     30.0     │\n├────────┼──────────┼───────┤\n│正面路寬超過十五│最小寬度（公尺）    │      3.5     │\n│公尺至二十五公尺├──────────┼───────┤\n│                │最小深度（公尺）    │      6.0     │\n│                ├──────────┼───────┤\n│                │最小面積（平方公尺）│     35.0     │\n├────────┼──────────┼───────┤\n│正面路寬超過二十│最小寬度（公尺）    │      4.0     │\n│五公尺          ├──────────┼───────┤\n│                │最小深度（公尺）    │      7.0     │\n│                ├──────────┼───────┤\n│                │最小面積（平方公尺）│     40.0     │\n└────────┴──────────┴───────┘\n前項建築基地騎樓部分應計入最小深度。但不列入最小寬度及最小面積。\n應留設側院地區，其基地寬度減側院寬度之差，不得小於三公尺。\n臨接綠帶應退縮建築之基地，其退縮部分不計入最小面積，基地深度減退\n縮地深度之差，不得小於五公尺。\n第 9 條\n實施區域計畫地區非都市土地編定為丁種建築用地及實施都市計畫地區劃\n定為工業區之土地，在中華民國七十五年十一月二日前，業經地政機關辦\n理分割完竣之建築基地，符合下列規定之最小寬度、深度者，准予建築，\n不受第三條規定之限制：\n┌─────────────────┬────────┐\n│                          使用分區│丁種建築用地及工│\n│                                  │業區            │\n│基地情形（公尺）                  │                │\n├────────────┬────┼────────┤\n│正面路寬七公尺以下      │最小寬度│       3.5      │\n│                        │最小深度│      12.0      │\n├────────────┼────┼────────┤\n│正面路寬超過七公尺至十五│最小寬度│       4.0      │\n│公尺                    │最小深度│      16.0      │\n├────────────┼────┼────────┤\n│正面路寬超過十五公尺至二│最小寬度│       4.5      │\n│十五公尺                │最小深度│      17.0      │\n├────────────┼────┼────────┤\n│正面路寬超過二十五公尺  │最小寬度│       4.5      │\n│                        │最小深度│      18.0      │\n└────────────┴────┴────────┘\n第 10 條\n畸零地所有權人與鄰地所有權人無法達成協議者，欲申請調處時，應填具\n申請書並檢附下列書件正本一份、副本十份向本府申請調處：\n一、合併使用土地之土地登記謄本、地籍圖謄本。\n二、相關土地地盤圖，註明需合併使用土地最小面積之寬度及深度。\n三、相關土地所有權人、承租人及他項權利人之姓名、住址。\n四、公告現值及市價概估。\n五、其它經主管建築機關認為有必要文件。\n第 11 條\n本府受理調處畸零地合併時，應於收到申請書之日起一個月內，通知有關\n土地所有權人、承租人及他項權利人進行調處，調處之程序如下：\n一、審查合併土地之位置、形狀及申請人所規劃合併土地最小寬度及深度\n，必要時並酌予調整。\n二、查估合併土地附近之買賣市價，徵詢參與調處人之意見，並由各土地\n所有權人協商合併建築或公開議價，互為買賣或合併建築。\n三、調處時，雙方意見不一致或一方缺席經再次通知不到者，視為調處一\n次不成立。\n前項調處不成立者，得於六個月後重新申請調處。\n第 12 條\n本府設畸零地調處委員會處理畸零地調處業務，置委員九人，其中一人為\n主任委員，由建設處處長兼任；其餘委員由下列人員組成：\n一、地政、財政及法制單位代表各一人。\n二、建築管理及使用管理、城鄉計畫科科長。\n三、當地建築師公會代表二人。\n第 13 條\n申請承購公有畸零地應檢附本府或委託鄉（鎮、市）公所核發之公有畸零\n地合併使用證明書。\n前項證明書之核發基準由本府另定之。\n第 14 條\n本自治條例自公布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL031576","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"修正日期":"民國 114 年 01 月 20 日","公發布日":"民國 92 年 12 月 18 日","法規名稱":"彰化縣畸零地使用自治條例","法規體系":"建設類","發文字號":"府行法字第1140019793號"},"promulgation_date":"2003-12-18","revision_date":"2025-01-20","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL031576","status":"unknown","title":"彰化縣畸零地使用自治條例","last_checked_at":"2026-10-06T17:26:36+08:00","last_success_at":"2026-10-06T17:26:36+08:00","verification_status":"fetched","content_hash":"85dc77f4903c27689bef1d317700327f2794e6f267ab7da1298b8c7a12add7b1","history":[{"observed_at":"2026-10-06T17:26:36+08:00","content_hash":"85dc77f4903c27689bef1d317700327f2794e6f267ab7da1298b8c7a12add7b1","change_kind":"initial","revision_date":"2025-01-20"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"彰化縣政府","category":"建築管理相關","content":"一、彰化縣政府（以下簡稱本府）為明定本縣臨時展演場所搭建臨時建築\n物管理程序，以維護公共安全，特依建築法第九十九條、彰化縣建築\n管理自治條例第三十三條規定訂定本作業程序。本作業程序未規定者\n，依其他相關法令規定辦理。\n二、本作業程序所稱臨時展演設施，係指下列供臨時性使用之建築物或其\n必要相關設施：\n（一）提供商品展售、藝文展演或民俗活動所搭建之設施。\n（二）競選活動辦事處及其他設施。\n（三）房屋銷售展示中心或樣品屋。\n（四）其他經本府認定之設施。\n三、申請人應於展演十四日以前委託建築師及相關技師，檢附下列書圖文\n件向本府提出申請，核准後始得搭建臨時性建築物。\n（一）申請書（包括活動期限說明）。\n（二）目的事業主管機關核准文件（含期間）。\n（三）建築師委託書。\n（四）土地使用權利證明文件：三個月有效期限內土地登記簿謄本、地籍\n圖謄本及土地使用權利同意書；公有土地應由管理機關出具土地使\n用權利同意書；於道路用地申請臨時展演場所者應先取得道路管理\n機關（單位）許可證明文件。\n（五）現況圖、位置圖、平面圖、立面圖、剖面圖、細部構造材料圖（依\n建築法第三十二條規定繪製）。\n（六）結構計算書圖。\n（七）自行拆除切結書。\n（八）其他必要之設備圖說。\n四、申請使用期限在三日以內之短期展演得檢具第三點所須書圖文件經目\n的事業主管機關同意後即行搭建臨時展演場所，不受第三點應辦理核\n准程序規定。\n五、高度在一．五公尺以下無頂蓋之臨時舞台或高度在四公尺以下無壁體\n及基礎結構之臨時攤棚，得檢具相關圖說逕向目的事業主管機關申請\n，並經目的事業主管機關及道路主管機關同意後搭建，免依第三點規\n定辦理申請核准程序，其臨時使用期限以一個月為限。\n六、申請人應於施工前將消防設備圖說及消防防護計畫送本縣消防局審查\n，申請活動使用基地面積超過五千平方公尺者，並應製作交通維持計\n畫書送本縣警察局審核，經核可後始得施工。但第四點及第五點案件\n，不受此限制。\n竣工後應申請竣工勘驗，經本府建設局會同消防局勘驗合格後，核發\n臨時使用許可，以憑接臨時水、電。\n七、臨時展演活動期滿後應於三日內自行拆除完畢；如有正當理由，得報\n經原核准機關延長拆除期限；逾期未拆除者，應以違章建築論處。\n八、臨時建築物使用期限以三個月為限，如有正當理由得於原核准使用期\n限內，檢附第三點規定書圖文件及建築師簽證現場勘驗原核准臨時建\n築結構安全證明文件向本府建設局申請延長使用期限。但以一次為限\n，且不得超過六個月。\n九、本作業程序經核定後發布實施。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL028121","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"修正日期":"民國 94 年 08 月 15 日","公發布日":"民國 91 年 09 月 06 日","法規名稱":"彰化縣臨時性展演設施許可及管理作業程序","法規體系":"建設類","發文字號":"府建管字第0940160142A號"},"promulgation_date":"2002-09-06","revision_date":"2005-08-15","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL028121","status":"unknown","title":"彰化縣臨時性展演設施許可及管理作業程序","last_checked_at":"2026-10-06T17:26:34+08:00","last_success_at":"2026-10-06T17:26:34+08:00","verification_status":"fetched","content_hash":"ab0b0e4e60af5db9f6e812999eac3281681f1ca341ba7f5f33a59478981afbd2","history":[{"observed_at":"2026-10-06T17:26:34+08:00","content_hash":"ab0b0e4e60af5db9f6e812999eac3281681f1ca341ba7f5f33a59478981afbd2","change_kind":"initial","revision_date":"2005-08-15"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"彰化縣政府","category":"建築管理相關","content":"一、本處理規定係依「舊有建築物防火避難設施及消防設備改善辦法」第\n八條規定訂定。\n二、本處理規定所稱舊有建築物係指七十三年十一月七日建築法修正公布\n施行前興建完成之建築物。\n三、舊有建築物防火避難設施及消防設備之改善，所必預增設於地面以下\n防空避難設施部分之固定設備，其所佔面積准免補足，並不得超過附\n建防空避難設備面積四分之一。\n四、舊有建築物防火避難設施及消防設備改善致該停車空間及防空避難設\n備面積減少或不符現行設置規定時，應依下列規定處理：\n(一) 停車空間及防空避難設備面積減少或不符現行設置規定，其停車空\n間未達十五平方公尺及防空避難設備未達十平方公尺，准予免再補\n行設置。\n(二) 停車空間及防空避難設備超過免補設標準部分，應於同一基地內補\n足之。\n(三) 應補設停車空間及防空避難設備，同一基地內無法設置者，其附近\n三百公尺內已闢建完成之停車場及防空避難設備之場所，得由本府\n訂定檢討補足規定據以審核辦理。\n五、舊有建築物應改善防火避難設施及消防設備同時需補設其停車空間及\n防空避難設備者，需一併申請改善與補設，並應於改善完竣經檢查合\n格後始得繼續使用，並應於使用執照內註記或函知申請人，同時副知\n警察及消防單位。\n六、古蹟建築物應補足停車空間及防空避難設備者，應報經該古蹟主管機\n關許可後始得辦理。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL028122","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"公發布日":"民國 90 年 09 月 24 日","法規名稱":"彰化縣舊有建築物防火避難設施及消防設備改善其停車空間及防空避難設備配合處理規定","法規體系":"建設類","發文字號":"（90）彰府工使字第167520號"},"promulgation_date":"2001-09-24","revision_date":"2001-09-24","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL028122","status":"unknown","title":"彰化縣舊有建築物防火避難設施及消防設備改善其停車空間及防空避難設備配合處理規定","last_checked_at":"2026-10-06T17:26:32+08:00","last_success_at":"2026-10-06T17:26:32+08:00","verification_status":"fetched","content_hash":"cc107db453a18756090921e6fe037224b4af785443ed65e3461eb1e1861019a4","history":[{"observed_at":"2026-10-06T17:26:32+08:00","content_hash":"cc107db453a18756090921e6fe037224b4af785443ed65e3461eb1e1861019a4","change_kind":"initial","revision_date":"2001-09-24"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"彰化縣政府","category":"建築管理相關","content":"第1條\n彰化縣政府（以下簡稱本府）為加強路燈之設置管理以維護公共安全，提\n升居住環境品質，特訂定本辨法。\n第2條\n本辦法所稱管理機關為公有路燈設置機關或各鄉（鎮、市）公所。\n第3條\n本辦法所稱路燈係指由路燈管理機關設置或其他機關設置而委由各鄉（鎮\n、市）公所管理之公共照明設備。\n本辦法所稱路燈管理，係指路燈之裝設、換裝、遷移、維修及廢除等管理\n工作。\n第4條\n路燈管理所需經費(含電費)，由設置或管理機關依法編列預算執行或申請\n相關機關經費補助辦理，並得善用社會資源，建立路燈認養制度。\n第5條\n各機關、學校、團體及一般民眾為路燈之裝設、換裝、遷移或廢除，應向\n各管理機關提出申請，經管理機關會勘及審核通過後執行，並應辦理財產\n管理業務。\n第6條\n路燈之裝設原則如下：\n一  都市計畫道路用地於道路開闢時，得同時配合裝設路燈。\n二  現有巷道得配合現況需求裝設路燈。\n三  裝設路燈地點屬供公眾通行之道路或依建築技術規則留設之私設通道\n，得申請裝設路燈，其裝設原則以有適當地點可供立桿及台灣電力股\n份有限公司可供給電源之地點且經土地管理機關或土地所有權人同意。\n四  新成立社區道路其屬合法編為路、街、巷、弄之道路並供公眾通行者，\n得依申請裝設路燈。\n五  其他經管理機關認定有裝設、換裝及維修之必要者。\n路燈之裝設及維修應以節能減碳為原則，燈具型式由管理機關依道路現況及\n安全需求綜判選用，且不得採用已公告禁用之燈具。\n第7條\n路燈以裝設於公有路燈燈桿為原則，必要時得附掛於台灣電力公司電桿或\n附掛於民宅或其他私有設施。\n前項附掛於民宅或其他私有設施之路燈之裝設，應取得該設施所有權人無\n償使用同意書始得辦理，且不得影響公共安全。\n路燈裝設或遷移，管理機關應同時設置接地；路燈換裝或維修，如發現未\n設置接地或接地損毀，管理機關應予補設置。\n第8條\n為避免資源浪費，路燈設置不得過於密集或供特定民眾使用。\n路燈裝設之標準依下列各款規定辦理：\n一  經濟部頒布之路燈設計規定。\n二  交通部頒布之交通工程規範第七章公路照明。\n三  內政部營建署頒布之市區道路及附屬工程設計規範第十九章道路照明\n。\n路燈裝設、換裝、遷移、維修或廢除，管理機關應同時向台灣電力股份有\n限公司申請辦理用電新設、用電變更或用電廢止。\n第9條\n管理機關所管理之既設路燈，應清點盤查，造冊建檔，建立統一編號張貼\n號碼牌（或認養牌），以利管理及清點，並於每年十二月三十一日前通盤\n核對校正一次。\n第10條\n民眾因新建或改建房舍或其他事由，造成既設路燈有妨礙交通、營業動線\n或公共安全者，得向各管理機關申請路燈遷移。\n前項申請路燈遷移之地點，若非屬公用土地者，申請人應取得土地所有權\n人之使用土地同意書，始得辦理。\n第11條\n已設置之路燈，有下列各款情形之一者，管理機關得主動拆遷或廢除：\n一  違反本辦法第八條第一項規定。\n二  經政府公告廢道之既設路燈。\n三  設置於公有道路及場所之路燈照明，有妨礙交通、公共安全或破壞街\n道景觀者。\n各鄉（鎮、市）公所發現轄內有非屬政府機關所設置或管理之路燈，且有\n前項各款情形之一者，應即通知台灣電力股份有限公司查處。\n第12條\n設置或管理機關發現或受理民眾通報發現路燈有漏電、電桿腐蝕或有傾倒\n之虞者，應作緊急維修處置。\n前項情形，如有不屬於管理機關維護範圍者，應立即通知相關機關處理。\n第13條\n本辦法所需之各類申請書表，由管理機關另訂之。\n本辦法未規定之事項，依電業法、屋內線路裝置規則、台灣電力公司營業\n規則、行政院公共工程委員會頒布施工綱要規範及其他相關規定辦理。\n本府每二年考核各鄉（鎮、市）公所之路燈管理作業，於預定考核日前一\n個月通知受考核公所，考核完成後一個月內通知考核結果。受考核公所應\n就考核結果予以落實改善。\n第14條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:GL000021","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"修正日期":"民國 108 年 01 月 04 日","公發布日":"民國 100 年 10 月 06 日","法規名稱":"彰化縣路燈設置管理辦法","法規體系":"工務類","發文字號":"府法制字第1070461847號令 令"},"promulgation_date":"2011-10-06","revision_date":"2019-01-04","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=GL000021","status":"unknown","title":"彰化縣路燈設置管理辦法","last_checked_at":"2026-10-06T17:26:50+08:00","last_success_at":"2026-10-06T17:26:50+08:00","verification_status":"fetched","content_hash":"078c572a2b13d343c837f468480773a43f3ceed07f3dca235d1fde3a34017f5f","history":[{"observed_at":"2026-10-06T17:26:50+08:00","content_hash":"078c572a2b13d343c837f468480773a43f3ceed07f3dca235d1fde3a34017f5f","change_kind":"initial","revision_date":"2019-01-04"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"附件一、任務編組表.ODT","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=204&id=FL088180&type=LAW"},{"name":"附件二、封閉作業流程圖（SOP）.ODT","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=205&id=FL088180&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"一、依據：\n災害防救法及災害防救法施行細則、公路法及公路修建養護管理規則\n、行政院災害緊急通報作業規定、交通部災害緊急通報作業要點等規\n定辦理。\n二、目的：\n彰化縣轄內車行地下道於發生災害或有發生災害危險之虞時，循本程\n序即時封閉車行地下道，保障用路人生命財產安全，並使車行地下道\n運輸功能所遭受損害減至最低程度。\n三、適用範圍：\n（一）彰化縣政府（以下簡稱本府）轄管車行地下道，於發生災害或有發\n生災害危險之虞時，依照本程序辦理車行地下道封閉作業。\n（二）彰化縣各鄉（鎮、市）公所管理維護之車行地下道，未另訂有車行\n地下道封閉標準作業程序者，得比照辦理。\n四、警戒時機：\n（一）交通部中央氣象局發布颱風陸上警報或豪雨特報或相關機關（單位\n）發布列為警戒區域者，或為本府維護管理單位或當地公所判定該\n車行地下道屬豪雨期間易致淹水影響安全者。\n（二）經分析雨量或氣象等資料，由本府維護管理單位或當地公所勘查、\n認定需要者。\n（三）接獲用路人、當地居民、警政機關（單位）反映，經本府維護管理\n單位或當地公所勘查、認定車行地下道內積淹水水位達五至十公分\n（警戒值）者。\n五、封閉時機：\n（一）車行地下道之封閉時機：當車行地下道最低處累積水位達十五公分\n（行動值）或依現地狀況檢討分析後訂定之封閉值，致影響交通車\n輛通行。\n（二）經本府車行地下道設備建置及維護單位或巡檢單位判定有下列情事\n，雖未達封閉行動值，仍得提前辦理封閉：\n1.車行地下道結構現況或排水設施、設備測試後運轉功能不佳。\n2.夜間無法辨識出車行地下道狀況時。\n3.發生事故導致部分車道受阻或交通阻斷。\n4.發生強烈地震、海嘯及火災且產生災情阻斷交通。\n5.維護單位或巡檢單位發現異常。\n6.經評估有危害用路人安全之虞。\n7.其它天然災害或人為事故等事件。\n六、封閉執行單位：\n各鄉（鎮、市）公所管理維護之車行地下道：由該鄉（鎮、市）公所\n負責執行封閉作業。\n七、任務分工：\n（一）請詳車行地下道封閉任務編組表。（附件一）\n（二）車行地下道巡檢單位：\n1.封閉作業：本縣各公所、彰化縣政府工務處。\n2.協助單位：警察、消防、醫院等單位。\n圖表附件：\n附件一、任務編組表.ODT\n八、封閉作業程序：詳如封閉作業流程圖。（附件二）\n（一）交通部中央氣象局發布海上颱風警報後、陸上颱風警報前或豪雨特\n報後，公所應予判斷，依需要通知管制組待命。\n（二）管制組巡檢人員巡視車行地下道有無積水情形，如淹水達警戒值（\n五至十公分）或車行地下道有異樣，恐有影響交通通行之虞時，則\n進入警戒時機，管制組應即時回報各鄉（鎮、市）級應變中心指揮\n官，視需要通知警察機關（單位）進場協助維持交通。\n（三）當淹水達行動值（十五公分）有淹水之虞，管制組經判斷有封閉必\n要，應立即通報現場指揮官或其指定代理人，由現場指揮官或其指\n定代理人下達封閉指令，並由各鄉（鎮、市）級應變中心要求警察\n機關（單位）協助管制交通並派員布設第一階段簡易封閉設施（原\n則車行地下道兩端同時布設，簡易封閉設施如警示帶、交通錐、蜂\n鳴器（視狀況佈設）、警示燈等），防止用路人誤闖。並由通報組\n通報工務處災害應變小組及縣級應變中心。\n（四）完成簡易封閉設施後，由各公所派員辦理第二階段完整封閉設施（\n如充水式或RC護欄、拒馬、交通錐、警示燈等）完成封閉作業，並\n由公所於車行地下道兩端適當地點架設替代路線告示牌及指示標誌\n，必要時報告現場指揮官或其指定代理人要求後勤支援。\n（五）由工務處應變小組於接獲鄉（鎮、市）級應變中心回報後，辦理行\n政通報（依序發送簡訊、災情傳真、登錄網站及通知縣級災害應變\n中心發布新聞），通知警廣、媒體發布封閉及繞道替代路線訊息。\n圖表附件：\n附件二、封閉作業流程圖（SOP）.ODT\n九、封閉開放作業程序：\n（一）車行地下道封閉原因消失，車行地下道經檢查後確認安全無虞時，\n由各級災害應變中心指揮官或其指定代理人下達開放通車指令。檢\n查項目應至少包括淹水情形降至警戒水位五公分以下、車行地下道\n結構情形等構件無持續變化或受損情形。\n（二）撤除交通阻絕管制設施開放通車。\n（三）依規定辦理恢復通車。\n（四）現場指揮官或其指定代理人視需要得指示人員持續現場觀察車行地\n下道狀況、積水水位變化等狀況保持警戒。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL088180","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"公發布日":"民國 105 年 05 月 24 日","法規名稱":"彰化縣車行地下道封閉標準作業程序","法規體系":"工務類","發文字號":"府工管字第1050173359號"},"promulgation_date":"2016-05-24","revision_date":"2016-05-24","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL088180","status":"unknown","title":"彰化縣車行地下道封閉標準作業程序","last_checked_at":"2026-10-06T17:26:47+08:00","last_success_at":"2026-10-06T17:26:47+08:00","verification_status":"fetched","content_hash":"a94606aa4d5557d217f89bd799ab8a8838f6c90726478976d898c93a235351a3","history":[{"observed_at":"2026-10-06T17:26:47+08:00","content_hash":"a94606aa4d5557d217f89bd799ab8a8838f6c90726478976d898c93a235351a3","change_kind":"initial","revision_date":"2016-05-24"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=204&id=FL088180&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=205&id=FL088180&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"彰化縣辦理公共工程拆遷建築改良物補償自治條例及附表.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=1564&id=FL060374&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"第 1 條\n彰化縣政府（以下簡稱本府）為辦理公共工程拆遷建築改良物之補償及獎\n勵事宜，特制定本自治條例。\n第 2 條\n本自治條例所稱之建築改良物（以下簡稱建物）係指依法興建或實施建築\n管理前興建完成之建物。\n第 3 條\n建物之勘查，應由需地機關會同有關機關查明下列事項，以作為查估補償\n之依據：\n一、建物門牌號碼。\n二、建物所有人之姓名及住址。\n三、建物構造、面積及用途。\n四、建築年月或其他相關佐證資料。\n五、附屬設施。\n六、建築基地地號、所有權人及土地使用權利。\n七、建物他項權利登記情形。\n第 4 條\n建物以重建價格補償，其計算方式如下：\n一、建物補償價格依「建築物補償查估評點標準」（如附表一）按每平方\n公尺評點之方法查估之。\n二、都市計畫外，建物拆除面積之計算，以建物各層外牆或外柱面以內面\n積計算，工程用地範圍線起算五十公分為拆除線之範圍面積計算，並\n應以拆除後賸餘建物結構安全為原則。\n三、都市計畫內，建物部分拆除界線認定，應以工程用地範圍線為原則。\n依規定須留設騎樓者，以一樓騎樓內（線）為準；二樓以上部分，以\n工程用地範圍線為準；按工程計畫施工者，以工程用地範圍線為準。\n但因施工需要者，按指定拆除線為準。\n四、未能依第一款規定查估核算之建物，得依現況核實查估，辦理補償。\n拆除建物應注意賸餘建物之無法繼續使用或結構有礙安全，其賸餘建物經\n專業技師鑑定其結構有礙安全且無法補強者，得申請全部拆除補償之。\n第 5 條\n補償費應依實地調查資料核算，對於補償費估價有異議時，依土地徵收條\n例第二十二條之規定辦理。\n第 6 條\n建物補償價格以評點計值，其單價以每一評點新臺幣」（下同）九點五元\n計值，本府得依行政院主計總處公布之營造工程物價指數總指數變動情形\n調整之。\n第 7 條\n非供人居住之附屬雜項建造物依「附屬雜項建造物補償單價表」（如附表\n二）估算，並免雜項建造物之證明文件。。\n第 8 條\n依第四條查估之建物，其自動拆遷獎勵金發給標準如下：\n一、凡於需地機關規定期限內自行拆除完竣者，給予重建價格百分之五十\n計列之。逾期未拆除者，由需地機關逕行拆除，不發給獎勵金。代為\n執行拆除時留置現場之所有建築材料及物品，需地機關不負保管責任\n，並得依廢棄物清理法處理之。\n二、應全部拆除或部分拆除之建物，依該門牌所設籍總人口數計算。同一\n門牌有多戶設籍，且各有獨立出入口、廚房及廁所等設施，具實際獨\n立生活者，按實際戶籍人數認定，其補助標準如附表三 。\n前項第二款之規定，同意協議價購者以第一次召開用地取得協議價購會前\n六個月，在現址設立戶籍，並有居住事實者為限；未能達成協議價購者以\n徵收（含區段徵收）計畫書公告六個月前，在現址設立戶籍，並有居住事\n實者為限。但因結婚、出生而設籍者，不受六個月期限限制。\n第 9 條\n建物局部拆除者，除依第四條計算補償費外，並加發原有門面修復費，其\n標準如下：\n一、鋼筋（鋼骨）混凝土造每平方公尺三千四百元。\n二、鋼筋混凝土加強磚造每平方公尺二千七百元。\n三、木、竹、磚、土石、鋼架造每平方公尺一千五百元。\n門面修復面積，以賸餘建物臨接拆除線門面面積為準。\n第 10 條\n合法營業之工廠或取得設立許可證之廠商，其電力外線設備補助費，依下\n列規定發給：\n一、建物全部拆除者，以徵收(含區段徵收)計畫書公告六個月前之電費收\n據所載契約容量，並依外線補助費標準表（如附表五）發給。\n二、建物部分拆除，其生產設備可繼續生產者，不予補助。但為維持原契\n約容量須另繳線路補助費者，得依前款規定發給。\n三、建物部分拆除，其生產設備無法繼續生產者，得依第一款規定計算發\n給。\n合法營業之工廠或取得設立許可證之廠商，其電力內線設備補助費，依「\n內線補助費標準表」（如附表六），下列規定發給：\n一、建物全部拆除者，以電氣總工程費加上設計簽證費，計算其補助數額\n。\n二、建物部分拆除，其生產設備可繼續生產者，依停工日數計算停工期間\n之基本電費及內線修繕費。\n三、建物部分拆除，其生產設備無法繼續生產者，得依第一款規定計算發\n給。\n依第一項計算電力外線設備補助費者，應提供電力公司用電戶基本資料（\n含燈、力、熱等設備容量）。\n第 11 條\n合法營業之工廠或取得設立許可證之廠商，其自來水外線工程費之補助，\n建物全部拆除者或部分拆除確無法繼續生產或使用而須移設管線者，依自\n來水公司所訂用水設備外線價格表之標準檢據補償之。\n第 12 條\n合法營業之工廠或取得設立許可證之廠商，其瓦斯外線工程費之補助，依\n瓦斯公司計算標準比照第十一條規定辦理。\n第 13 條\n合法營業之工廠或取得設立許可證之廠商，其建物固定附屬設備或機械設\n備之土木基礎，依各該種類及構造之土木基礎費單價表（如附表七）核實\n計算重置費用。\n第 14 條\n合法營業之工廠或取得設立許可證之廠商，其建物內之固定設備因拆除或\n部分拆除致無法繼續生產或使用者，補償其拆裝工資費用。\n第 15 條\n工廠機械設備及原物料之拖運費用依附表九之補償標準計算，但體積或重\n量過大之機器，依實際情況核算拖運費用。\n第 16 條\n工廠吊車或堆高機租金費用，依其車型實際租用天數計算補償金額（如附\n表十）。\n第 17 條\n有工廠登記證之工廠，其營業項目與現場相符者，依查定金額發給，營業\n項目與現場不符（產業別不同）者，依查定金額百分之八十發給。\n第 18 條\n工廠未經完成登記者，不得依第十三條至第十六條申請補償。但有未達工\n廠登記要件之證明文件者，依查定金額百分之八十發給。\n第 19 條\n電話遷機費每戶補償一千元。\n第 20 條\n因建物全部或部分拆除，而遷移祖先牌位或神位（像）者，發給遷移費；\n其標準如下：\n一、宗祠、祠堂（含祭祀公業）發給一萬元。\n二、大宅院、四合院內公廳發給六千元。\n三、住宅供奉神像或祖先牌位者發給二千元。\n如拆遷戶同時供奉一種以上祖先牌位、神位（像）時，依單項最高金額補\n償，不得重複補償。\n第 21 條\n建物查估作業，由本府或鄉（鎮、市）公所辦理，必要時得委託具公信力\n之專業機構辦理。\n第 22 條\n本自治條例自公布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL060374","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"修正日期":"民國 114 年 01 月 20 日","公發布日":"民國 100 年 03 月 11 日","圖表附件":"彰化縣辦理公共工程拆遷建築改良物補償自治條例及附表.pdf","法規名稱":"彰化縣辦理公共工程拆遷建築改良物補償自治條例","法規體系":"工務類","發文字號":"府行法字第1140019648號"},"promulgation_date":"2011-03-11","revision_date":"2025-01-20","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL060374","status":"unknown","title":"彰化縣辦理公共工程拆遷建築改良物補償自治條例","last_checked_at":"2026-10-06T17:26:49+08:00","last_success_at":"2026-10-06T17:26:49+08:00","verification_status":"fetched","content_hash":"83200dba342d768c3bf53bc437b4659424152f11cb13141d18cbdddf22b23804","history":[{"observed_at":"2026-10-06T17:26:49+08:00","content_hash":"83200dba342d768c3bf53bc437b4659424152f11cb13141d18cbdddf22b23804","change_kind":"initial","revision_date":"2025-01-20"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=1564&id=FL060374&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"彰化縣辦理變更使用執照及室內裝修申請案違建部分處理辦法修正第一條至第三條總說明及條文對照表.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=2862&id=FL048257&type=LAW"},{"name":"彰化縣辦理變更使用執照及室內裝修申請案違建部分處理辦法總說明及逐條說明.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=2861&id=FL048257&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"第 1 條\n彰化縣政府為辦理建築物變更使用執照及室內裝修申請案內之違章建築，\n以維護公共安全及建築物逃生避難之暢通，特訂定本辦法。\n第 2 條\n申請變更使用執照及室內裝修案件，有下列情形之一者，應於申請竣工勘\n驗前，由申請人或協調該所有權人自行拆除：\n一、地面層出入口有阻礙或封閉，違反建築技術規則建築設計施工編（以\n下簡稱本編）第九十條出入口寬度規定之違建者。但遮雨棚架等無礙\n逃生之設施列管拆除。\n二、屋頂平臺有違反本編第九十九條避難面積之違建者，應拆除部分違建\n使其避難面積達建築面積二分之一。如以走道連接避難平臺者，走道\n有效寬度須大於樓梯寬度。但申請範圍位於地面層、地下層、或三樓\n以下與地面層同一戶可經由該戶室內梯自地面層直接避難逃生者，免\n檢討此項。\n三、直通樓梯範圍內有阻礙，違反本編法定樓梯寬度之違建者。但得不經\n由直通樓梯而直接避難逃生者，免檢討此項。\n四、應歸責於申請變更使用執照之防火間隔（防火巷）增建物。\n五、阻塞緊急進口之違建者。\n六、騎樓之違建者。\n七、陽台違建屬建築物使用類組及變更使用辦法（使用項目舉例表）之Ｂ\n類、Ｉ類各組及醫院、療養院、長期照護機構、養謢機構、安養機構\n、老人服務機構、護理之家機構、產後護理機構、育嬰中心、幼稚園\n、托兒所，將陽台內牆拆除及陽台外緣加蓋遮雨棚等及妨礙緩降機、\n救助帶等操作之一切障礙物。另陽台外緣加裝鐵窗等（各類用途），\n須留設緊急進口。\n八、廣告招牌、建築物內外牆裝飾物封閉緊急進口，影響民眾避難逃生及\n消防救災者。\n九、建築物超出建築線、道路境界線者。\n前項圖說應將違建之判定及位置、尺寸標示、面積計算等於圖上明確標示\n並敘明。\n第 3 條\n申請變更使用執照及室內裝修案件，有下列情形之一者，應於申請竣工勘\n驗前，由申請人或協調該所有權人自行拆除或以Ｒ．Ｃ牆、磚牆封閉切結\n不使用，並檢附施工前後相片、圖說憑辦及列入竣工檢查項目：\n一、天井違建。但採光罩等無礙逃生之設施列管拆除。\n二、夾層違建。\n前項圖說應將違建之判定及位置、尺寸標示、面積計算等於圖上明確標示\n並敘明，並由建築師提出建築物結構安全證明。\n第 4 條\n變更使用範圍與違建部分之區隔規定如下：\n一、變更使用範圍內，將陽台原有建築物外牆拆除（非承重牆為限，並由\n建築師簽證），以陽台加窗為建築物外牆之違建部分符合緊急進口相\n關規定者，於申請變更使用時已拆除之外牆得免復原。應於平面圖註\n明「陽台已拆除之建築物外牆非承重牆」。\n二、變更使用範圍內，將合法房屋原有外牆拆除於法定空地或室內空間違\n建者，其已拆除之外牆應以原材料或混凝土（十二公分厚以上）、磚\n牆（二十四公分厚以上）或經中央主管機關審核認可之具一小時以上\n防火時效材料復原，復原後並應符合緊急進口相關規定。\n第 5 條\n非前三條範圍之違章建築，應由建築師提出建築物結構安全證明，並於申\n請案核准變更時，將違建位置圖說及相片，隨同執照副本逕依違章建築處\n理辦法規定辦理。\n第 6 條\n有關第二條第一項第一款至第三款之認定，以申請案所在單棟為其認定範\n圍；第四款至第九款之認定，以申請案該戶為之。\n第 7 條\n變更使用執照及室內裝修申請案違章建築部分，如經公寓大廈管理組織檢\n舉者，列為優先強制拆除。\n第 8 條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL048257","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"修正日期":"民國 98 年 06 月 17 日","公發布日":"民國 98 年 01 月 08 日","法規名稱":"彰化縣辦理變更使用執照及室內裝修申請案違建部分處理辦法","法規體系":"建設類","發文字號":"府法制字第0980142446號","立法理由":"彰化縣辦理變更使用執照及室內裝修申請案違建部分處理辦法修正第一條至第三條總說明及條文對照表.pdf 彰化縣辦理變更使用執照及室內裝修申請案違建部分處理辦法總說明及逐條說明.pdf"},"promulgation_date":"2009-01-08","revision_date":"2009-06-17","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL048257","status":"unknown","title":"彰化縣辦理變更使用執照及室內裝修申請案違建部分處理辦法","last_checked_at":"2026-10-06T17:26:41+08:00","last_success_at":"2026-10-06T17:26:41+08:00","verification_status":"fetched","content_hash":"22337c1ebaae3f2575fa6daf4b289ec49a8319c0a6b962ab59747f573c71a974","history":[{"observed_at":"2026-10-06T17:26:41+08:00","content_hash":"22337c1ebaae3f2575fa6daf4b289ec49a8319c0a6b962ab59747f573c71a974","change_kind":"initial","revision_date":"2009-06-17"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=2862&id=FL048257&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=2861&id=FL048257&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"第 7 點完整條文.PDF","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=214&id=FL088189&type=LAW"},{"name":"第 10 點完整條文.PDF","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=215&id=FL088189&type=LAW"},{"name":"第 11 點完整條文.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=1007&id=FL088189&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"一、依據：\n災害防救法及災害防救法施行細則、公路法及公路修建養護管理規則\n、行政院災害緊急通報作業規定、交通部災害緊急通報作業要點。\n二、目的：\n彰化縣轄內公路於發生災害或有發生災害危險之虞時，循本作業程序\n即時封閉公路，保障用路人生命財產安全，並使公路運輸功能所遭受\n損害減至最低程度。\n三、適用範圍：\n（一）彰化縣政府（以下簡稱本府）轄管公路（縣、鄉道），於發生災害\n或有發生災害危險之虞時，依照本作業程序辦理道路封閉作業。\n（二）彰化縣各鄉（鎮、市）公所管理維護之道路，未另訂有道路封閉標\n準作業程序者，得參照本程序另訂準用之。\n四、警戒時機：\n（一）接獲用路人、當地居民、警政單位或各級道路管理機關通報，經養\n護單位認定需要者。\n（二）列為重點監控之公路，先前災害尚未修復之路基缺口、具坍方潛勢\n尚未辦理坡面防護之上邊坡及位於河流攻擊岸之路段，經氣象局發\n布陸上颱風警報或上游集水區發布豪雨特報，經養護單位認定需\n要者。\n五、封路時機：\n封路之時機，經巡查或通報有下列狀況者執行：\n（一）公路因災害或無預警發生路基缺口或路基下陷且有擴大之虞時。\n（二）公路邊坡發生落石坍方且有擴大之虞時。\n（三）發生強烈地震且產生災情阻斷交通時。\n（四）中央氣象局發布海嘯警報，為維護警報區域路段行車安全時。\n（五）其他經公路養護單位評估有危害用路人安全之虞時。\n六、封路執行單位\n（一）施工中之路段：各工程執行單位。\n（二）本府轄管公路（縣、鄉道）：為利封路執行時效，由各鄉（鎮、市\n）公所先行執行第一階段簡易封路，本府工務處派員執行第二階段\n道路封閉及相關交維設施之設置。\n（三）各鄉（鎮、市）公所管理維護之道路：由該鄉（鎮、市）公所負責\n執行封路作業。\n七、任務編組\n圖表附件：\n第 7 點完整條文.PDF\n八、封路作業程序\n（一）公路如因災害阻斷交通或經公路養護單位評估有危害用路人安全之\n虞（達封路標準）時，應立即報告現場指揮官（由本府工務處處長\n或各鄉（鎮、市）公所首長擔任）或其指定代理人，下達封路指令\n，並即通報相關單位依程序辦理道路封閉及後續道路搶通搶修作業\n。\n（二）阻絕設施設置程序分工如下：\n1. 警察單位配合協助交通管制。\n2. 第一階段簡易封路（受阻路段兩端同時佈設，警示帶、交通錐、\n警示燈）由各鄉（鎮、市）公所執行。\n3. 第二階段完全阻絕設施（灌水式或 RC 護欄、交通錐、警示燈）\n、設置封路告示牌、替代路線告示牌，由本府工務處執行。\n（三）本府工務處依序發布新聞、登錄網站、請警廣協助轉知相關訊息並\n於現場張貼公告。（循「彰化縣重要道路公共安全通知事項標準作\n業程序」辦理）\n九、封路開放作業程序\n（一）路基缺口修復、坍方清除並完成相關交通安全設施經公路養護單位\n勘查無虞後，由現場指揮官或其指定代理人下達開放通車指令。\n（二）現場指揮官或其指定代理人視需要得指示人員持續現場觀察邊坡狀\n況保持警戒。\n十、各單位緊急聯絡窗口名冊\n（一）為利本項作業程序之執行，請各鄉（鎮、市）公所於每年三月三十\n一日前提送聯絡窗口之聯絡資訊予本府彙整（需包含姓名、職稱、\n手機、辦公室電話、傳真、電子信箱等）。\n（二）聯絡資訊表格如下：\n圖表附件：\n第 10 點完整條文.PDF\n十一、道路封閉作業流程圖（SOP）\n圖表附件：\n第 11 點完整條文.pdf","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL088189","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"修正日期":"民國 109 年 03 月 18 日","公發布日":"民國 103 年 06 月 04 日","法規名稱":"彰化縣道路封閉標準作業程序","法規體系":"工務類","發文字號":"府工管字第1090076354號 函"},"promulgation_date":"2014-06-04","revision_date":"2020-03-18","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL088189","status":"unknown","title":"彰化縣道路封閉標準作業程序","last_checked_at":"2026-10-06T17:26:46+08:00","last_success_at":"2026-10-06T17:26:46+08:00","verification_status":"fetched","content_hash":"11f5765853cb9eb766ef78d40f12ed49cccae3416a5f3783336f178a8ac8f0dc","history":[{"observed_at":"2026-10-06T17:26:46+08:00","content_hash":"11f5765853cb9eb766ef78d40f12ed49cccae3416a5f3783336f178a8ac8f0dc","change_kind":"initial","revision_date":"2020-03-18"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=214&id=FL088189&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=215&id=FL088189&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=1007&id=FL088189&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"工程用水電申挖切結書.PDF","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=217&id=FL088190&type=LAW"},{"name":"管線申挖切結書.PDF","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=218&id=FL088190&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"一\n、\n彰化縣政府（以下簡稱本府）為加強管理彰化縣道路挖掘管理自治條\n例第五條第一項、第十七條第二款之挖掘申請及第十九條、第二十條\n、第二十二條道路挖掘行為，以維護道路品質，特訂定本要點。\n二、新建房屋（以下簡稱建案）申請用戶分支管線接管（含電力、電信、\n自來水、排水、污水及瓦斯等管線）時，該建案起造人應向各管線機\n構同時提出申請，並彙整各管線機構挖掘期程，及填具管線申挖切結\n書逕向道路管理機關（以下簡稱管理機關）提出申請，由管理機關核\n發該建案道路挖掘許可證後，如無法在核定挖掘期間完成，自「核定\n挖掘期間完成」起至「領得使用執照起算一年內」，該建案不得提出\n任一管線之申請設置。\n圖表附件：\n工程用水電申挖切結書.PDF\n管線申挖切結書.PDF\n三、申請道路挖掘者（以下簡稱申請人）於道路挖掘後之路面修復採方形\n切割方式辦理，應符合下列規定：\n（一）按原路面相同之材質、品質及厚度修復。\n（二）瀝青混凝土道路應按挖掘範圍內之車道寬度採方形切割並刨（挖）\n除五公分厚度後，再依前款規定辦理；其與原有路面（含人孔、手\n孔相關設施設備等）銜接處，除於鋪築時予以壓實外，並應妥為處\n理平順。\n（三）混凝土之道路應先切割一車道寬度之路面後，再依原路面材質修築\n平順，並為與原路面相同之修飾。\n（四）各管線單位所屬之人孔、手孔蓋（含制水閥等）應與周圍原路面銜\n接平順或辦理下地減量。\n（五）瀝青混凝土鋪面鑽心厚度，不得少於五公分。\n（六）管溝回填材料以高性能低強度材料（CLSM）回填壓實，於二十八天\n後抗壓強度每平方公分應達二十公斤至八十公斤；管溝回填材料以\n碎石級配料回填時，每層不得超過三十公分，並壓實至最大乾密度\n百分之九十五以上。\n（七）瀝青混合料除工程合約條款另有規定外均為（密級配），其瀝青含\n量為百分之五點五、容許誤差百分之零點三亦即瀝青含量達百分之\n五點二以上者為合格。\n四、道路挖掘時，施工材料應妥為放置，施工現場應設置告示牌（道路挖\n掘許可證張貼在左上方），並標明工程名稱、管線機構、施工廠商、\n工程概要、全民督工及檢舉電話、開工及預定完工日期等內容。\n管溝開挖如遇較鬆軟土層，或開挖深度達一點五公尺以上，有崩塌之\n虞者，應依設計管溝開挖寬度以適當擋土設施維持土壁穩定，於施工\n前提送擋土設施計畫經工程主辦機關核定後始得動工，並注意下列事\n項，以確保管線工作人員施工安全：\n(一)打設擋土設施時，應先核對其他管線之套繪資料，並先挖導溝確\n認有無既設管線及其實際分布位置狀況後，方可打設施工。\n(二)拔除擋土設施須垂直拔起，不可斜拔損及管線。\n五、管理機關得命申請人提供道路挖掘施工期間之每日施工動態資料，並\n得派員現場勘察施工品質、安全措施及交通安全管制設施。\n六、前點情形，經發現缺失者，管理機關應限期命申請人改善，並予以記\n點，其記點標準如下：\n（一）有下列缺失之一者，記點一點：\n1.未完善設置交通安全設施。\n2.未設置施工告示牌。\n3.未張貼道路挖掘許可證。\n4.施工道路兩端未指派專人指揮。\n5.鐵板覆蓋路面未採用防滑性材料。\n6.假修復後未恢復路面標線及標誌。\n（二）有下列缺失之一者，記點二點：\n1.挖掘土方未運離工地。\n2.道路切割線未平直。\n3.回填材料未確實滾壓。\n4.鋪設於管道之臨時簡易 AC 之粒料鋪設不良，致粒料分離。\n5.未於竣工後三日內完成路面修復。\n6.施工面積未與道路許可證內容相符。\n7.封閉道路未施設交通改道導（指）引標誌及號誌。\n8.施工機（用）具不得占用道路、未施工時尋覓適當地點放置不得\n放置工區。\n9.未依據「管線單位緊急搶修案件電話傳真報備單」核准內容施作。\n（三）有下列缺失之一者，記點四點：\n1.底層級配壓實度或篩分析不合格。\n2.AC  面層壓實度、厚度或篩分析不合格。\n七、申請人依前點規定缺失記點點數每月累計達四點者，管理機關得停\n發申請道路挖掘許可證一個月；每月累計達八點者，得停發申請\n道路挖掘許可證二個月。\n八、 前點停發申請道路挖掘許可證事項，不含緊急搶修、檢修及用戶聯接\n管線工程。\n九、從事道路挖掘作業，應依營造安全衛生設施標準第九條、第六十三條\n、第六十六條、第六十九條及第七十一條等相關規定辦理。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL088190","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"修正日期":"民國 113 年 03 月 21 日","公發布日":"民國 103 年 05 月 01 日","法規名稱":"彰化縣道路挖掘管理實施要點","法規體系":"工務類","發文字號":"府工管字第1130102485號函"},"promulgation_date":"2014-05-01","revision_date":"2024-03-21","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL088190","status":"unknown","title":"彰化縣道路挖掘管理實施要點","last_checked_at":"2026-10-06T17:26:45+08:00","last_success_at":"2026-10-06T17:26:45+08:00","verification_status":"fetched","content_hash":"8fe4f2c6a225822295b0d2c2fe2dcb632ecee459546bcd4303400f1202ef6bae","history":[{"observed_at":"2026-10-06T17:26:45+08:00","content_hash":"8fe4f2c6a225822295b0d2c2fe2dcb632ecee459546bcd4303400f1202ef6bae","change_kind":"initial","revision_date":"2024-03-21"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=217&id=FL088190&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=218&id=FL088190&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"彰化縣政府","category":"建築管理相關","content":"第 1 條\n為維護彰化縣（以下簡稱本縣）轄區內道路服務品質、交通安全及市容觀\n瞻，有效管理道路挖掘事宜，特制定本自治條例。\n第 2 條\n本自治條例用詞定義如下：\n一、道路：指本縣轄內自養縣道、鄉道、市區道路、產業道路及村里道路\n；不含中央機關管理之道路。\n二、道路挖掘：指因施作管（纜）線（道）、人（手）孔、閥箱等之新設\n、拆遷、換修、擴充或其他工程，有挖掘道路或附掛橋梁、隧道、地\n下道等設施者。\n三、公共管線：係指電力、電信（含軍、警專用電信）、自來水、天然氣\n、輸油、輸氣、路燈、交通號誌、社區共同天線電視設備、有線電視\n、下水道、共同管道、環保、廢棄物、水利設施及氣象偵測或其他經\n認定供公共使用之管線或管道。\n四、共同管道：係指設於地面上、下，用於容納二種以上公共管線之構造\n物及其排水、通風、照明、通訊、電力或有關安全監視（測）系統等\n之各種設施。\n五、管線機構：係指公共管線之設置或管理機構（單位）。\n六、緊急性挖掘：係指公共管線臨時重大損壞或故障緊急搶修必須挖掘道\n路者。\n七、計畫性挖掘：係指彰化縣政府（以下簡稱本府）及各公私事業機構、\n機關於年度計畫籌辦之專案工程，且須於年度內配合相關公共管線同\n時挖掘道路者。\n第 3 條\n申請道路挖掘者（以下簡稱申請人），應視道路之權屬\n向下列管理機關申\n請：\n一、自養縣道、鄉道：本府或本府指定之各鄉（鎮、市）公所。\n二、市區道路、產業道路及村里道路：所在地之鄉（鎮、市）公所。\n三、新闢道路：尚未移交第一款及第二款管理機關之新闢道路，由該道路\n工程主辦機關受理申請。\n第 3-1 條\n依本自治條例罰則規定之違規裁罰，由管理機關執行之。\n第 4 條\n管線機構須於每年三月底前，向管理機關申報該年度之計畫性挖掘案件，\n逾期未申報者，該年度不得再行申請。\n計畫性挖掘案件，限於該年四月至九月間施工修復完成，其他時間禁止道\n路挖掘。但經本府核准者，不在此限。\n管理機關受理第一項申報之計畫性挖掘案件後，應邀集管線機構或相關機\n關協商辦理方式及各階段作業配合時程，凡挖掘同一道路者，應協調配合\n接續或同時施工。\n前項配合計畫性挖掘案件之申請人應依協調結果辦理，並依第七條規定提\n出申請。\n第 5 條\n新建房屋起造人申請用戶分支管線接管（含電力、電信、自來水、排水、\n污水、瓦斯等管線）時，應於建築申報開工前以書面向管理機關預先登記\n。\n前項起造人應向各管線機構同時提出申請並以書面通知管理機關，由管理\n機關協調各管線機構後，定於同一時段施工，管線機構無正當理由者不得\n拒絕。\n公共管線之幹線系統埋設時，應儘可能將用戶聯接支線埋設，以備日後隨\n時聯接。\n第 6 條\n道路新闢、拓寬時，公共管線應同時配合道路工程施工。工程主辦機關辦\n理道路工程時，經認與管線工程有關者，除特殊情形外，應於年度預算開\n始六個月前，將擬辦之各該工程實施地點、工程概要等分送各管線機構，\n管線機構認該項道路工程與管線有關者，應即復知管理機關並編列其年度\n預算。道路工程年度預算成立後一個月內，管理機關應即通知管線機構，\n計畫變更時亦同。\n道路工程規劃或設計時，得編列先期探管費用，並請管線機構提供相關資\n料，會同參與，將其管線之配置一併規劃，並適時與相關管理工程機構協\n調聯繫；道路工程施工時，相關管線工程須同時配合辦理。\n第 7 條\n申請人申請道路挖掘許可，應檢具下列書件一式三份向管理機關申請：\n一、申請書。\n二、施工計畫書。\n三、施工範圍位置圖。\n四、工程進度表。\n五、交通維持計畫書。\n六、管線埋設平面圖。\n七、管線標準橫斷面圖。\n八、其他相關書圖。\n申請道路挖掘案件之規模及期程，依彰化縣道路施工交通維持計畫審查作\n業程序規定須報請本縣道路交通安全聯席會報核准者，應檢附其核准通過\n之交通維持計畫書及相關書件。\n第 8 條\n管理機關受理前條之申請案件後，應於十日內完成審查；經審查合格者，\n管理機關應通知申請人繳交道路挖掘許可費（以下簡稱許可費）、預繳代\n辦道路挖掘修復費（以下簡稱修復費）後，始核發道路挖掘許可證並核定\n施工期限。\n管理機關核發道路挖掘許可證時，應副知所在地鄉（鎮、市）公所、本縣\n道路交通安全聯席會報、警察局及環境保護局。\n道路挖掘完工後實挖數量若有減少時，申請人得申請重新核算修復費。\n申請案件經審查不合格者，管理機關應敘明理由駁回；得補正者，應通知\n限期補正，逾期未補正者，駁回之。\n第 8-1 條\n前條第一項之情形，經道路管理機關核准申請人自行修復道路並負責保固\n二年者，得免繳修復費。\n前項保固期間發生塌陷或裂痕等情形，由道路管理機關通知申請人限期修\n復，逾期未修復者，由道路管理機關代為修復，所需費用由申請人負擔。\n第 9 條\n因興辦公共工程而辦理道路挖掘案件或管線機構配合道路新闢、拓寬工程\n施工辦理之道路挖掘案件，免繳第八條第一項之許可費；其由本府或道路\n工程施工機關自行修復路面者，免繳修復費。\n第 10 條\n第八條許可費及修復費收費標準，由本府定之。\n第 11 條\n道路挖掘採用免開挖技術施工者，仍應依規定提出挖掘申請，並繳交許可\n費及修復費。\n第 12 條\n申請道路挖掘，除工程特殊且有連貫性之必要者外，每申請案件以一條道\n路為限。\n申請挖掘同一道路全線應以一次申請為原則。但在市區或交通繁忙路段申\n請挖掘長度超過三百公尺或在郊區申請挖掘長度超過五百公尺者，管理機\n關得分段核定施工期限，且先挖掘路段應完成回填及路面假修復作業並經\n管理機關勘查認可後，始得進行次一路段之挖掘。\n第 13 條\n道路挖掘埋設公共管線，其設施頂面距路面之深度，在車道下不得少於一\n點二公尺，在人行道下不得少於零點五公尺。\n前項埋設深度，因情形特殊，且結構計算事先經管理機關核准者，得不受\n限制。\n第 14 條\n於現有橋梁、隧道、地下道附掛公共管線前，應向該管管理機關申請許可\n。\n第 15 條\n因搶修公共管線辦理緊急性道路挖掘施工時，申請人應先以電子郵件、傳\n真或電話等向管理機關報備後始得施工，並應於七日內檢附相關資料及搶\n修過程前、中、後照片，向管理機關補辦申請道路挖掘許可，並依規定補\n繳許可費及修復費。\n未完成報備或未依限補辦申請許可者，視為擅自挖掘。\n第 16 條\n有下列情形之一者，道路禁止挖掘：\n一、道路新闢或拓寬工程竣工驗收完成未滿三年。\n二、道路新舖路面封層竣工驗收完成未滿二年。\n三、其他經本府公告禁止道路挖掘期間。\n第 17 條\n有下列情事需限期完成道路挖掘者，得不受前條之限制：\n一、經檢附相關證明文件之配合政策性之國家重要建設工程。\n二、搶修公共管線辦理緊急性工程。\n三、配合或解決區域性之專案公共工程。\n四、新建房屋申請用戶分支管線接管工程。\n五、採用免開挖技術施工工程。\n六、其他經管理機關核准，並報本府備查之情況。\n第 18 條\n申請人應於施工前檢具開工報告書向管理機關申報開工，並依據道路挖掘\n許可證內容施工，除經管理機關核准者外，不得擅自變更。\n申請人因故未能於核定期限內完工時，應於期限屆滿前以書面向管理機關\n申請展延，申請展延以一次為限。\n第 19 條\n道路挖掘應使用切割機按標定線平直，全厚度切割路面面層，並不得毀損\n管溝兩旁之路面及其他公共管線或公共設施。如因施工導致損壞，或因安\n全設施不當導致交通、意外事故，申請人應即通知有關單位處理，並應負\n全部責任。\n道路挖掘施工範圍應豎立日夜間明顯警告標誌及安全措施，以維交通安全\n。\n第 20 條\n道路挖掘施工，當日收工前應完成回填、假修復、環境維護及廢料清除等\n作業。如不能立即完成回填或假修復者，應於挖掘管溝上覆蓋相當強度之\n止滑鋼板，且於板底鋪墊柔性材料避免滑動，並與路面保持平順；管溝路\n面假修復作業，最遲應於回填作業辦理次日完成。\n管溝施工回填，其以碎石級配回填者，應確實分層夯實。\n管溝路面假修復舖設之瀝青混凝土，其厚度比照原有瀝青混凝土厚度，修\n復後路面應與原路面平順，並應作平坦度試驗。\n路面刨除加封修復完成一年內，如有因道路挖掘工程施工因素產生異常下\n陷損害者，申請人應負責修復並負擔復原及施作費用。\n第 21 條\n挖掘道路施工，涉及私有土地產權問題時，應即停止挖掘，由申請人負責\n協調解決後再行施工。\n第 22 條\n申請人於道路挖掘修復竣工後三十日內，應檢具下列資料，向管理機關申\n報完工：\n一、平面位置圖（圖檔含 TWD97  坐標系統坐標）。\n二、縱橫斷面圖。\n三、附屬工程竣工圖。\n四、相關試驗報告。\n五、道路挖掘管理系統所必須填列之管線數值資訊。\n六、施工前中後照片。\n前項第五款數值資訊規範，由本府另定之。\n第一項第六款施工照片應配合拍攝位置以附近建物或地標為背景，並具指\n定座標系統之座標。其內容包括：\n一、施工告示牌。\n二、道路切割情形。\n三、管線埋深檢測。\n四、回填深度檢測。\n五、級配深度檢測。\n六、ＡＣ修復厚度檢測。\n七、路面修復平整檢測。\n八、現場機具施工情形。\n管理機關應派員現場會勘，經會勘認可後，交由管理機關予以刨除加封修\n復路面；會勘查有缺失者，應通知申請人限期改善完成後，再行函報複核\n。\n管溝挖掘長度超過五十公尺以上者，應抽查瀝青混凝土舖面鑽心厚度，及\n檢核申請人確已委請認證合格之實驗室完成下列試驗：\n一、管溝回填材料壓實度試驗報告：路面修復面積小於五百平方公尺或累\n計達五百平方公尺者，試驗一處，每超過五百平方公尺者，應增加一\n處。\n二、瀝青含油量試驗報告：路面修復面積小於一千平方公尺或累計達一千\n平方公尺者，試驗一處，每超過一千平方公尺者，應增加一處。\n路面鑽心取樣後，遺留之孔內應以相同材質材料回填並壓實之。\n第 23 條\n未依第八條第一項規定取得管理機關許可擅自挖掘道路，或違反第十八條\n規定，未依許可證內容施工及未依限申請展延者，處新臺幣三萬元以上九\n萬元以下罰鍰，並責令其限期回復原狀或賠償修復費用。\n第 23-1 條\n新建房屋起造人未依第五條第一項規定於開工前向管理機關預先登記，或\n管線機構未依第五條第二項規定於同一時段施工者，處新臺幣三萬元以上\n九萬元以下罰鍰。\n第 24 條\n如有第十五條第二項擅自挖掘之情形或冒用緊急搶修事由者，處新臺幣三\n萬元以上九萬元以下罰鍰，並責令其限期回復原狀或賠償修復費用。\n第 25 條\n違反第十九條或第二十條第一項至第三項規定者，處新臺幣三萬元以上九\n萬元以下罰鍰，並責令加強相關安全防護措施。\n第 26 條\n申請人未依第二十二條第一項、第五項或第六項規定辦理者，處新臺幣三\n萬元以上九萬元以下罰鍰。\n第 27 條\n本自治條例規定所需各種表冊及書類格式除已有規定者外，由本府另定之\n。\n第 28 條\n本自治條例自公布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL067962","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"修正日期":"民國 114 年 01 月 20 日","公發布日":"民國 101 年 08 月 03 日","法規名稱":"彰化縣道路挖掘管理自治條例","法規體系":"工務類","發文字號":"府行法字第1140019676號"},"promulgation_date":"2012-08-03","revision_date":"2025-01-20","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL067962","status":"unknown","title":"彰化縣道路挖掘管理自治條例","last_checked_at":"2026-10-06T17:26:48+08:00","last_success_at":"2026-10-06T17:26:48+08:00","verification_status":"fetched","content_hash":"6dd2658a8501078262cdb0fcec280c49660c4d45270ef2c4cc42e340ce032b6b","history":[{"observed_at":"2026-10-06T17:26:48+08:00","content_hash":"6dd2658a8501078262cdb0fcec280c49660c4d45270ef2c4cc42e340ce032b6b","change_kind":"initial","revision_date":"2025-01-20"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"彰化縣政府","category":"建築管理相關","content":"第一條\n彰化縣政府（以下簡稱本府）為推動道路挖補及修復業務，集中管理運用\n代辦路面挖掘之修復費用，加強財務收支管理與監督，依據預算法第九十\n六條第二項準用同法第二十一條規定，訂定本辦法。\n第二條\n本基金之收支保管及運用，除其他法令另有規定外，悉依本辦法規定辦理\n。\n第三條\n本基金為預算法第四條第一項第二款所規定之特種基金，編製附屬單位預\n算，以本府為主管機關，本府工務處為管理單位。\n第四條\n本基金之來源如下：\n一  各級管線單位、私人、公民營公司、團體繳交代辦各類管線（路）埋\n設及挖補工程、瀝青混凝土路面修補、人（手）孔蓋調整（降）等改\n善工程費用。\n二  政府補助及協助收入。\n三  本基金孳息收入。\n四  個人或團體之捐贈收入。\n五  其他有關收入。\n第五條\n本基金之用途如下：\n一  代辦各類管線（路）埋設及挖補工程。\n二  代辦各類管線工程柏油路面補修。\n三  辦理道路挖補修復所需設備費、業務費及人事費。\n四  本縣管線挖掘資訊便民服務系統所需之管理維護費。\n第六條\n本基金之收支、保管及運用，應設立專戶存管循環運用，並專款專用。\n第七條\n本基金之存儲應依彰化縣縣庫事務處理自治條例及相關法令規定辦理。\n第八條\n本基金預算之編製、執行、決算之編造及會計事務之處理程序，依預算法\n、會計法、決算法、審計法、公庫法及相關法令規定辦理。\n第九條\n本基金結束時，應予結算並將其餘存權益解繳縣庫。\n第十條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:GL000117","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"公發布日":"民國 108 年 08 月 13 日","法規名稱":"彰化縣道路挖掘路修費基金收支保管及運用辦法","法規體系":"工務類","發文字號":"府法制字第1080275324號令"},"promulgation_date":"2019-08-13","revision_date":"2019-08-13","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=GL000117","status":"unknown","title":"彰化縣道路挖掘路修費基金收支保管及運用辦法","last_checked_at":"2026-10-06T17:26:50+08:00","last_success_at":"2026-10-06T17:26:50+08:00","verification_status":"fetched","content_hash":"3db143f0178141c4ab933f2646fa640f792afcdd985e7d6cfa7c89ddadbf49f9","history":[{"observed_at":"2026-10-06T17:26:50+08:00","content_hash":"3db143f0178141c4ab933f2646fa640f792afcdd985e7d6cfa7c89ddadbf49f9","change_kind":"initial","revision_date":"2019-08-13"}],"version_count":1,"attachment_hashes":{}},{"articles":[],"attachment_required":false,"attachments":[{"name":"彰化縣都市危險及老舊建築物重建作業辦法_removed.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=2852&id=GL000007&type=LAW"},{"name":"申請重建流程及審查流程.odt","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=558&id=GL000007&type=LAW"},{"name":"彰化縣重建計畫書檢核表.odt","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=559&id=GL000007&type=LAW"},{"name":"都市危險及老舊建築物重建流程及相關書表文件.odt","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=560&id=GL000007&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"第 1 條\n本辦法依都市危險及老舊建築物加速重建條例（以下簡稱本條例）第四條\n規定訂定之。\n第 2 條\n本辦法之主管機關為彰化縣政府（以下簡稱本府）。\n第 3 條\n為審議依本辦法申請重建之案件，得委請相關專業單位協助審查。\n第 4 條\n依本條例第三條第一項第二款、第三款規定之案件，得補助結構安全性能\n評估費用。\n前項補助之申請要件及額度，依中央主管機關補助結構安全性能評估費用\n辦法規定辦理。\n第 5 條\n依本條例申請重建時應檢附之文件、重建計畫應載明之事項及審核時程，\n依本條例施行細則規定辦理。\n彰化縣都市危險及老舊建築物重建流程、重建計畫書檢核表、都市危險及\n老舊建築物重建流程及相關書表文件（範本）等詳如附件。\n圖表附件：\n申請重建流程及審查流程.odt\n彰化縣重建計畫書檢核表.odt\n都市危險及老舊建築物重建流程及相關書表文件.odt\n第 6 條\n重建計畫範圍內之建築基地，得視實際需要，給予適度之建築容積獎勵，\n其獎勵之項目、計算方式、額度、申請條件及其他應遵行事項，依都市危\n險及老舊建築物建築容積獎勵辦法辦理。\n本條例施行後三年內申請之重建計畫，得再給予各該建築基地基準容積百\n分之十之獎勵，不受本條例獎勵後之建築容積規定上限之限制。\n第 7 條\n依本條例申請重建之案件，其建蔽率以住宅區之基地為限，且不得超過原\n建蔽率。\n第 8 條\n依本條例施行後五年內申請之重建計畫，其重建計畫範圍內之土地及建築\n物，得依本條例第八條第一項第一款至第三款規定減免稅捐。\n依本辦法適用租稅減免者，不得同時併用其他法律規定之同稅目租稅減免\n。但其他法律之規定較本條例更有利者，適用最有利之規定。\n第 9 條\n本辦法未規定事項，依本條例及其他相關法令規定辦理。\n第 10 條\n本辦法自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:GL000007","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"全文檔案":"彰化縣都市危險及老舊建築物重建作業辦法_removed.pdf","公發布日":"民國 107 年 07 月 27 日","法規名稱":"彰化縣都市危險及老舊建築物重建作業辦法","法規體系":"建設類","發文字號":"府法制字第1070256694號"},"promulgation_date":"2018-07-27","revision_date":"2018-07-27","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=GL000007","status":"unknown","title":"彰化縣都市危險及老舊建築物重建作業辦法","last_checked_at":"2026-10-06T17:26:40+08:00","last_success_at":"2026-10-06T17:26:40+08:00","verification_status":"fetched","content_hash":"db879717c8f575e1b9bbce83784b01d1c4cf9f14b593a618cd9423ecac9d03f7","history":[{"observed_at":"2026-10-06T17:26:40+08:00","content_hash":"db879717c8f575e1b9bbce83784b01d1c4cf9f14b593a618cd9423ecac9d03f7","change_kind":"initial","revision_date":"2018-07-27"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=2852&id=GL000007&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=558&id=GL000007&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=559&id=GL000007&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=560&id=GL000007&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"附表一.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=2914&id=GL000379&type=LAW"},{"name":"附表二.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=2915&id=GL000379&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"第一點\n彰化縣政府（以下簡稱本府）為執行都市更新條例(以下簡稱本條例)第二十二條及第二十三條規定，使都市更新單元(以下簡稱更新單元)之劃定有所依循，特訂定本基準。\n第二點\n更新單元劃定相關事項依本基準辦理。但都市計畫或都市更新計畫另有規定者，從其規定。\n第三點\n本基準用詞定義如下：\n(一)街廓：指四週被都市計畫道路或其他分區界線圍成之土地。\n(二)非都市發展用地：指農業區、保護區、河川區、行水區或其他非屬開發建築用地。\n(三)毗鄰土地已開發完成：指鄰接基地上之合法建築物，其樓層數為六樓以上、或屋齡未達三十年且五樓以下之防火構造物。\n前項第一款之基地鄰接河川、永久性空地或其他非屬開發建築用地者視為街廓邊界。\n第四點\n更新單元不得位於非都市發展用地，且不得涉及都市計畫主要計畫之擬定或變更。但有下列情形者，不在此限：\n(一)符合本條例施行細則第二十一條所定情形。\n(二)僅涉及細部計畫之擬定、變更者。\n第五點\n劃定更新單元時，不得造成毗鄰土地為畸零地。但該毗鄰土地或合法建築物所有權人確實不願參與更新，且經彰化縣(以下簡稱本縣)都市更新及爭議處理審議會同意者，不在此限。\n第六點\n更新單元應臨接計畫道路或已指定建築線之現有巷道，其所臨接之計畫道路或現有巷道之寬度應達八公尺以上，或與基地退縮留設深度合計達八公尺以上，並符合下列規定之一者：\n(一)為完整之計畫街廓。\n(二)街廓內面積在一千五百平方公尺以上者。\n(三)街廓內臨接二條以上之計畫道路，且面積在一千平方公尺以上者。\n(四)街廓內毗鄰土地已開發完成，確無法合併更新且無礙建築設計及市容觀瞻，其面積在一千平方公尺以上，並為一次更新完成者。\n都市更新單元面積雖不符合前項第二款至第四款規定，其情形特殊有實施都市更新必要者，得經本縣都市更新及爭議處理審議會同意另行劃定。\n第七點\n未經本府劃定為應實施都市更新之地區，土地及合法建築物所有權人得依第六點所定標準，申請自行劃定更新單元實施都市更新事業。\n前項更新單元內重建區段建築物及地區環境評估應符合附表一所列評估指標（至少一項），並應檢附建築師、相關專業技師或機構之鑑定證明。\n圖表附件：\n附表一.pdf\n第八點\n更新單元內之合法建築物全部以整建或維護方式處理者，得不受第五點至第七點規定之限制。但位於未經劃定應實施更新之地區，更新單元內整建或維護區段建築物及地區環境狀況應符合附表二所列評估指標（至少一項），並應檢附建築師、相關專業技師或機構之鑑定證明。\n圖表附件：\n附表二.pdf\n第九點\n更新單元符合下列情形之一且經本府核准者，得不受第五點至第八點規定之限制：\n(一)合法建築物因戰爭、地震、火災、水災、風災或其他重大事變遭受損壞。\n(二)合法建築物經本府認定屬高氯離子鋼筋混凝土或耐震能力不足而有明顯危害公共安全。\n前項各款建築基地之周邊鄰接土地得合併辦理更新。但其土地之面積合計不得超過前項各款建築基地之面積。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:GL000379","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"公發布日":"民國 113 年 04 月 08 日","法規名稱":"彰化縣都市更新單元劃定基準","法規體系":"建設類","發文字號":"府建新字第1130120101號函"},"promulgation_date":"2024-04-08","revision_date":"2024-04-08","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=GL000379","status":"unknown","title":"彰化縣都市更新單元劃定基準","last_checked_at":"2026-10-06T17:26:28+08:00","last_success_at":"2026-10-06T17:26:28+08:00","verification_status":"fetched","content_hash":"ef502cedd242fd805e82ba0521572eb542be23dd854c7b202727453633b85d9d","history":[{"observed_at":"2026-10-06T17:26:28+08:00","content_hash":"ef502cedd242fd805e82ba0521572eb542be23dd854c7b202727453633b85d9d","change_kind":"initial","revision_date":"2024-04-08"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=2914&id=GL000379&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=2915&id=GL000379&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"彰化縣都更地區建築容積獎勵核計標準.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=2857&id=FL041414&type=LAW"},{"name":"附表更新單元規劃設計之獎勵容積（△F5）評定基準表.DOC","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=139&id=FL041414&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"第 1 條\n彰化縣政府（以下簡稱本府）為辦理彰化縣（以下簡稱本縣）都市更新建\n築容積獎勵之核計，特訂定本標準。\n第 2 條\n本縣都市更新事業建築容積獎勵項目及評定基準，除都市計畫及相關法令\n另有規定外，依下列規定辦理：\n一、建築容積獎勵額度依下列公式核計：F ＝F0＋△F1＋△F2＋△F3＋△\nF4＋△F5＋△F6\nF ：獎勵後總容積，其上限依都市更新建築容積獎勵辦法第四條規定辦\n理。\nF0：法定容積。\n△F1：都市更新條例第四十四條第一項第一款規定之獎勵容積。\n△F2：都市更新條例第四十四條第一項第二款規定之獎勵容積。\n△F3：都市更新條例第四十四條第一項第四款規定之獎勵容積。\n△F4：都市更新建築容積獎勵辦法第八條規定考量地區環境狀況之獎勵容\n積。\n△F5：都市更新建築容積獎勵辦法第八條規定更新單元規劃設計之獎勵容\n積。\n△F6：都市更新建築容積獎勵辦法第八條規定為處理占有他人土地舊違章\n建築戶之需要之獎勵容積。\n二、前款獎勵建築容積項目之評定基準依下列規定辦理：\n△F1：以原建築容積減法定容積之差核算；原建築容積，係指建築物建造\n時，主管機關核發使用執照所核准之建築容積。其屬合法建築物而\n無使用執照者，以建築主管機關所認定為準。\n使用執照所核准之建築容積，以原使用執照樓地板面積扣除原申請之\n獎勵樓地板面積（包括停車獎勵、綜合設計獎勵等）及建築免計樓地\n板面積部分（包括騎樓、屋頂突出物等）認定之。\n△F2：以更新後分配建築物樓地板面積低於當地居住樓地板面積平均水準\n之戶數（P） ，乘以本縣居住樓地板面積平均水準（A） 與更新後\n分配建築物樓地板面積平均值（A1）之差額核算。\n計算公式  △F2＝P*（A－A1）\nP 值應超過更新後應分配建築物及其應有部分之原土地及建築物所\n有權人人數之二分之一。\nA 值以最近一次行政院主計處公布之臺閩地區戶口及住宅普查或臺\n閩地區人口及居住調查報告中，本縣平均每戶居住樓地板面積為準\n。\nA1  值為更新後分配建築物樓地板面積低於 A  值之平均值。\n△F3：自本府公告都市更新地區日起，二年內提出申請實施更新者，給予\n法定容積之百分之五之獎勵容積；四年內提出申請實施更新者，給\n予法定容積之百分之四之獎勵容積；六年內提出申請實施更新者，\n給予法定容積之百分之三之獎勵容積。\n△F4：以下各項措施所需成本經費，除以獎勵樓層單位面積不含建築成本\n及管銷費用之銷售淨利核算。但以其建築容積獎勵已有研提相關財\n務計畫內容及詳實佐證數據予以核計者為限。\n（一）配合本縣或所轄鄉（鎮、市）公所需求捐贈公益設施者，其建築成\n本。\n（二）協助開闢都市計畫公共設施所需工程、拆遷安置經費及捐贈道路用\n地成本經費。但依建築法相關規定，為基地出入通路部分應自行開\n闢者，其工程及拆遷安置經費不得核計獎勵容積。\n（三）認養公共設施、改善人行空間鋪面及公共藝術等增進都市景觀美化\n所需相關經費。\n△F5：開放空間廣場、人行步道、保存經核定具歷史性、紀念性或藝術價\n值之建築、更新單元規模及無障礙空間等因素，依更新單元規劃設\n計之獎勵容積（△F5）評定基準表規定核計應得之獎勵容積。但已\n依建築技術規則建築設計施工篇實施都市計畫地區建築基地綜合設\n計獎勵者，不適用開放空間廣場及人行步道之容積獎勵。\n△F6：實施者為處理基地內占有他人土地之舊違章建築戶所需樓地板面積\n，及協議以現金補償或異地安置方式核算之樓地板面積（每戶不超\n過本縣樓地板面積平均水準），其額度以法定容積之百分之二十為\n限。本標準所稱舊違章建築戶之認定指民國八十七年十一月十一日\n都市更新條例公布施行前已興建完成之建築物。\n三、獎勵後總容積，若經本縣都市更新審議委員會審議將對周邊公共設施\n及交通造成嚴重衝擊者，得適度酌減。\n圖表附件：\n附表更新單元規劃設計之獎勵容積（△F5）評定基準表.DOC\n第 3 條\n依其他法令規定申請建築容積獎勵時，應將該等相關計畫納入都市更新事\n業計畫中，且其申請獎勵項目之性質不得重複。\n前條核定獎勵後之總容積，為該都市更新事業計畫申請建築執照之最大允\n許建築容積。\n第 4 條\n更新後提供社區使用之公益設施，其樓地板面積免計容積。公益設施項目\n如下：\n一、圖書館、博物館、藝術中心等文化展演設施。\n二、社會福利設施、活動中心及集會場所\n三、其他經本縣都市更新審議委員會審議通過者。\n前項各款樓地板面積應在一百平方公尺以上，且具有獨立之出入口，自行\n管理維護者，並應訂定公益設施管理維護計畫，併同更新事業計畫辦理審\n議。\n公益設施樓地板面積合計不得超過法定容積之百分之十，超過部分應計入\n容積面積。\n第 5 條\n本標準自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL041414","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"全文檔案":"彰化縣都更地區建築容積獎勵核計標準.pdf","公發布日":"民國 95 年 09 月 25 日","法規名稱":"彰化縣都市更新地區建築容積獎勵核計標準","法規體系":"建設類","發文字號":"府法制字第0950187285號"},"promulgation_date":"2006-09-25","revision_date":"2006-09-25","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL041414","status":"unknown","title":"彰化縣都市更新地區建築容積獎勵核計標準","last_checked_at":"2026-10-06T17:26:42+08:00","last_success_at":"2026-10-06T17:26:42+08:00","verification_status":"fetched","content_hash":"cee6605d440e91569abd8ecd120e1c14c962759df7973e3c3dc99ed99f3ef83b","history":[{"observed_at":"2026-10-06T17:26:42+08:00","content_hash":"cee6605d440e91569abd8ecd120e1c14c962759df7973e3c3dc99ed99f3ef83b","change_kind":"initial","revision_date":"2006-09-25"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=2857&id=FL041414&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=139&id=FL041414&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"訂定「彰化縣都市更新權利變換最小分配面積單元標準」令、總說明及逐條說明.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=3828&id=GL000465&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"第 1 條\n本標準依都市更新條例第五十一條第四項規定訂定之。\n第 2 條\n本標準之執行單位為彰化縣政府建設處。\n第 3 條\n本標準所稱都市更新權利變換最小分配面積單元，為權利變換後應分配之\n建築物登記總面積扣除公用部分、雨遮、露台及陽台面積後不得小於四十\n六平方公尺。但有下列各款情形之一者，不在此限：\n一、權利變換後實施者分配之建築物。\n二、社會住宅。\n三、商業使用。\n四、權利變換後分配之建築物登記總面積不小於都市更新事業計畫報核日\n前之合法建築物登記總面積。\n五、有特殊原因，經彰化縣都市更新及爭議處理審議會同意。\n第 4 條\n本標準自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:GL000465","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"公發布日":"民國 115 年 01 月 29 日","法規名稱":"彰化縣都市更新權利變換最小分配面積單元標準","法規體系":"建設類","發文字號":"府行法字第1150039525號","立法理由":"訂定「彰化縣都市更新權利變換最小分配面積單元標準」令、總說明及逐條說明.pdf"},"promulgation_date":"2026-01-29","revision_date":"2026-01-29","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=GL000465","status":"unknown","title":"彰化縣都市更新權利變換最小分配面積單元標準","last_checked_at":"2026-10-06T17:26:37+08:00","last_success_at":"2026-10-06T17:26:37+08:00","verification_status":"fetched","content_hash":"a66a8613e808a2acc5b48399b18ae28147b6d3ef9b3bc42ea139cf56cb6b49b3","history":[{"observed_at":"2026-10-06T17:26:37+08:00","content_hash":"a66a8613e808a2acc5b48399b18ae28147b6d3ef9b3bc42ea139cf56cb6b49b3","change_kind":"initial","revision_date":"2026-01-29"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=3828&id=GL000465&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"附件一_提列總表.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=3694&id=GL000453&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"一、\n彰化縣政府（以下簡稱本府）為審議都市更新權利變換計畫提列之共同負擔項目及費用，以合於實務需求、標準化及公平一致，特訂定本原則。\n二、\n依都市更新條例第五十一條及都市更新權利變換實施辦法第十九條規定，得提列之共同負擔項目及費用如下，其內容詳如提列總表（如附件一）：\n(一) 工程費用。\n(二) 申請各項建築容積獎勵所支付之費用。\n(三) 權利變換費用。\n(四) 貸款利息。\n(五) 稅捐。\n(六) 管理費用。\n(七) 都市計畫變更負擔費用。\n(八) 容積移轉費用。\n圖表附件：\n附件一_提列總表.pdf\n三、\n增列前點提列總表外之其他費用，須敘明支出時機、管理方式、計列貸款利息、稅捐及管理費之情形，並經彰化縣都市更新及爭議處理審議會審議同意。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:GL000453","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"公發布日":"民國 114 年 11 月 21 日","法規名稱":"彰化縣都市更新權利變換計畫提列共同負擔項目及費用審議原則","法規體系":"建設類","發文字號":"府建新字第1140464658號函"},"promulgation_date":"2025-11-21","revision_date":"2025-11-21","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=GL000453","status":"unknown","title":"彰化縣都市更新權利變換計畫提列共同負擔項目及費用審議原則","last_checked_at":"2026-10-06T17:26:27+08:00","last_success_at":"2026-10-06T17:26:27+08:00","verification_status":"fetched","content_hash":"f1030373666e00da45f0ec49bcd48b1e693ead71140435e01282eb7b8d97d8c3","history":[{"observed_at":"2026-10-06T17:26:27+08:00","content_hash":"f1030373666e00da45f0ec49bcd48b1e693ead71140435e01282eb7b8d97d8c3","change_kind":"initial","revision_date":"2025-11-21"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=3694&id=GL000453&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"彰化縣都市計畫保護區農業區土地容許使用審查要點 立法理由.txt","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=180&id=FL050628&type=LAW"},{"name":"附件一：彰化縣都市計畫保護區農業區土地容許使用申請書.PDF","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=1390&id=FL050628&type=LAW"},{"name":"附件二：彰化縣都市計畫保護區農業區土地容許使用審查表.PDF","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=182&id=FL050628&type=LAW"},{"name":"附件三：申請土地容許使用案件審查作業流程.PDF","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=183&id=FL050628&type=LAW"},{"name":"附件四:都市計畫保護區農業區土地容許使用項目及目的事業主管機關（單位）.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=1354&id=FL050628&type=LAW"},{"name":"附件五：彰化縣都市計畫保護區農業區土地容許作○○○設施使用證明書.PDF","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=186&id=FL050628&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"一、彰化縣政府（以下簡稱本府）為審查本縣都市計畫保護區、農業區內\n土地容許使用之各項設施，訂定本要點。本要點未規定事項，適用其\n他相關法令。\n二、依都市計畫法臺灣省施行細則（以下簡稱本細則）第二十七條、第二\n十九條之一、第二十九條之二規定，於都市計畫保護區、農業區設置\n各項設施，除都市計畫書或其他法令另有規定者，從其規定外，應依\n本要點規定申請土地容許使用。\n三、申請土地容許使用，應填具申請書，並檢附下列文件：\n（一）申請書：載明申請人之姓名或機關名稱及負責人、住址、電話、申\n請地號、基地面積、申請事由，並由申請人簽名及蓋章。（格式如\n附件一）\n（二）容許使用計畫書：說明使用範圍及計畫內容概要，內容如下：\n1.計畫緣由：說明計畫緣起及目的。\n2.需求評估及環境分析：申請需求評估、環境現況說明（含現況照\n片），及容許使用後基地周邊環境、衛生、都市景觀及交通之影\n響分析。\n3.都市計畫土地使用分區證明書。\n4.建築線指示（定）成果圖。\n5.申請使用內容、面積及申請設施平、立面概要說明。\n6.其他相關文件。\n（三）籌設許可文件或相關同意備查文件：除申請私設通路使用項目外，\n其他項目須檢附經各目的事業主管機關審核通過之籌設許可文件或\n相關同意備查文件，另容許項目有興辦事業者，應一併檢附興辦事\n業計畫書。\n（四）最近三個月內核發之地籍圖謄本、土地登記簿謄本、土地使用分區\n證明及土地同意使用之證明文件（申請人為土地所有權人時免附）\n。\n（五）申請基地及周邊現況地形圖及都市計畫位置圖：標示基地所在位置\n及鄰近範圍內現有相關地物或設施，另都市計畫位置圖以本府公告\n之都市計畫圖為準。\n（六）如屬農業用地變更使用者，應依「農業主管機關同意農業用地變更\n使用審查作業要點」第三點規定，擬具農業用地變更（容許）使用\n說明書，以供農業主管機關審查。\n（七）其他合法相關文件。\n圖表附件：\n附件一：彰化縣都市計畫保護區農業區土地容許使用申請書.PDF\n四、各項設施土地容許使用審查事項如下：\n（一）申請設施項目應符合本細則保護區（第二十七條）、農業區（第二\n十九條之一、第二十九條之二）及第八點附件四規定使用項目與使\n用強度。\n（二）保護區設置農業產銷必要設施應符合本細則保護區（第二十七條第\n一項第十九款）規定。\n（三）農業區內之土地，其已申請建築者，於增建或辦理變更用途時，應\n符合本細則農業區（第二十九條第二項第三款）規定。\n（四）申請基地在農地重劃區或保安林地者，應經本府農業單位同意。\n（五）不得於自來水水質水量保護區、飲用水水源水質保護區及飲用水取\n水口一定距離範圍內之土地申請設置。但自來水水質水量保護區範\n圍內之土地，經水利單位依自來水法同意者，或飲用水水源水質保\n護區、飲用水取水口一定距離範圍內之土地，經環境保護單位依飲\n用水管理條例同意者，不在此限。\n（六）是否符合都市計畫書之相關規定。\n五、本府（建設處）受理土地容許使用申請案件後，應即查核申請書件是\n否齊全，填具審查表（格式如附件二），核簽具體意見後，核發土地\n容許使用證明書，其審查流程如附件三。\n圖表附件：\n附件二：彰化縣都市計畫保護區農業區土地容許使用審查表.PDF\n附件三：申請土地容許使用案件審查作業流程.PDF\n六、申請基地面積及使用限制如下：\n（一）都市計畫法臺灣省施行細則已有規定者，申請面積應從其規定。但\n同一申請人不得於同一地號或毗鄰土地申請數相關設施。申請基地\n面積合計不得超過三千平方公尺。\n（二）申請基地面積合計超過三千平方公尺者，如其他法規另有規定或取\n得目的事業主管機關籌設許可或相關同意備查文件者，不受前款申\n請基地面積之限制。但申請基地面積合計仍不得超過一公頃。\n（三) 申請同意設置之各項設施，於農業區者不得妨礙鄰近既有農水路設\n施之使用功能及農業生產環境。但提供相同寬度之農路、水路替代\n方案經農業主管機關同意者，不在此限；於保護區者不得影響生態\n資源及水土保持，並應徵得農業主管機關同意。\n（四）除申請私設通路使用者外，申請基地毗鄰農業用地者，應取得農業\n主管機關同意，並依核准之農地變更（容許）使用計畫書內容設置\n隔離綠帶。\n七、農業產銷必要設施、休閒農業設施、自然保育設施、綠能設施及農村\n再生相關公共設施逕依「農業用地容許作農業設施使用審查辦法」、\n「彰化縣政府辦理申請農業用地容許作農業設施使用審查作業要點」\n、「彰化縣申請農業設施興建高度及樓層審查基準」、「休閒農業輔\n導管理辦法」、「再生能源發展條例」、「農村再生條例」等規定申\n請容許使用，免依本要點辦理土地容許使用手續。\n前項農業產銷必要設施許可使用細目中，有關其他部分依「彰化縣申\n請農業設施興建高度及樓層審查基準」辦理。\n農業主管機關於受理前項申請許可案件，其位於都市計畫農業區保護\n區範圍內者，除依前項辦法規定免申請容許使用者外，應加會本府建\n設處查核都市計畫土地使用管制情形。\n八、本要點規定設置各項設施之目的事業主管機關（單位），依附件四規\n定辦理。\n各項設施容許使用細目之適用範圍，以相關法令已有訂定或經各目的\n事業主管機關所認定者為限。\n圖表附件：\n附件四:都市計畫保護區農業區土地容許使用項目及目的事業主管機關（單位）.pdf\n九、農業區土地作非農業使用時，應繳交回饋金之規定與執行如下：\n（一）本府農業處核算變更回饋金並製作回饋金計算表後轉（簽）送本府\n建設處。\n（二）本府建設處於同意變更使用前，應通知申請人依法繳納。\n（三）申請人應於繳納完竣後，檢具繳納回饋金收據向本府建設處辦理核\n發容許使用證明。\n（四）本府建設處於核發容許使用證明時，應副知本府農業處及彰化縣地\n方稅務局並檢附前款收據。\n十、本要點規定各項設施涉及建築行為者，除第七點規定外，申請人應檢\n具土地容許使用證明文件，於八個月內依法向本府建管單位申請建築\n許可。申請人因故未能於期限內申請建築許可時，得向本府建設處申\n請展期八個月，且以原核准有效期最終日之次日起核算展期天數，並\n以一次為限。\n圖表附件：\n附件五：彰化縣都市計畫保護區農業區土地容許作○○○設施使用證明書.PDF\n十一、依本要點核發之土地容許使用證明，如遇都市計畫變更時，應依據\n新計畫公告內容為準。\n核准使用設施，經依法制止使用或廢止時，其使用之土地應回復原\n來之使用。\n十二、各項目設施申請核准使用時，除依本要點規定辦理外，並應符合附\n表相關規定。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL050628","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"修正日期":"民國 111 年 02 月 10 日","公發布日":"民國 92 年 10 月 21 日","法規名稱":"彰化縣都市計畫保護區農業區土地容許使用審查要點","法規體系":"建設類","發文字號":"府建新字第1110048294號函","立法理由":"彰化縣都市計畫保護區農業區土地容許使用審查要點 立法理由.txt"},"promulgation_date":"2003-10-21","revision_date":"2022-02-10","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL050628","status":"unknown","title":"彰化縣都市計畫保護區農業區土地容許使用審查要點","last_checked_at":"2026-10-06T17:26:28+08:00","last_success_at":"2026-10-06T17:26:28+08:00","verification_status":"fetched","content_hash":"ed88c9ee3d5e3bcea576818c53280eacdbf954e973b95a6e366c4b6e32f7bd00","history":[{"observed_at":"2026-10-06T17:26:28+08:00","content_hash":"ed88c9ee3d5e3bcea576818c53280eacdbf954e973b95a6e366c4b6e32f7bd00","change_kind":"initial","revision_date":"2022-02-10"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=180&id=FL050628&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=1390&id=FL050628&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=182&id=FL050628&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=183&id=FL050628&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=1354&id=FL050628&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=186&id=FL050628&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"(精簡)彰化縣都市計畫公共設施保留地臨時建築使用管制規則.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=2866&id=GL000020&type=LAW"},{"name":"附表.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=579&id=GL000020&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"第 1 條\n本規則依都市計畫公共設施保留地臨時建築使用辦法第四條第二項規定訂\n定之。\n第 2 條\n都市計畫公共設施保留地（以下簡稱公共設施保留地）容許臨時建築使用\n細目如附表。\n圖表附件：\n附表.pdf\n第 3 條\n公共設施保留地臨時建築使用之建蔽率不得超過百分之三十。\n第 4 條\n公共設施保留地臨時建築使用之最大建築面積，除下列規定情形外，不予\n限制：\n一、臨時建築權利人之自用住宅、簡易汽車駕駛訓練場最大建築面積為三\n百平方公尺。\n二、其他依都市計畫法第五十一條規定得使用之建築物不得增加建築面積\n。\n第 5 條\n公共設施保留地鄰近之土地使用分區種類有二種以上時，由彰化縣政府（\n以下簡稱本府）城鄉發展局就申請基地區位之實際發展狀況及對環境影響\n程度最小者，認定其所鄰近之土地使用分區類別。\n公共設施保留地鄰近之土地為附表以外之其他使用分區時，由本府城鄉發\n展局就申請基地區位之實際發展狀況及對環境影響程度最小者，比照附表\n之土地使用分區類別認定。\n第 6 條\n申請下列臨時建築使用應附設停車空間，其面積不得少於建築面積二分之\n一：\n一、小型游泳池、運動設施及其他供社區遊憩使用之建築物。\n二、幼稚園、托兒所。\n三、臨時攤販集中場。\n前項建築空間及停車空間以外之申請基地應綠美化。\n第 7 條\n申請下列臨時建築使用得附設飲食、販賣場所，其面積以一百平方公尺為\n限：\n一、菇寮、花棚、養魚池及其他供農業使用之建築物。\n二、小型游泳池、運動設施及其他供社區遊憩使用之建築物。\n第 8 條\n公共設施保留地申請臨時建築使用，基地內土方應維持平衡，開挖之深度\n不得超過一．五公尺，並不得建造地下室。\n第 9 條\n公共設施保留地申請臨時建築使用，應經各使用項目之目的事業主管機關\n核准。\n前項目的事業主管機關於核准前，應會請用地主管機關就公共設施保留地\n開闢計畫及經費預算狀況核表意見後辦理。\n第 10 條\n本規則自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:GL000020","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"全文檔案":"(精簡)彰化縣都市計畫公共設施保留地臨時建築使用管制規則.pdf","公發布日":"民國 94 年 02 月 03 日","法規名稱":"彰化縣都市計畫公共設施保留地臨時建築使用管制規則","法規體系":"建設類","發文字號":"府法制字第0940026404號"},"promulgation_date":"2005-02-03","revision_date":"2005-02-03","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=GL000020","status":"unknown","title":"彰化縣都市計畫公共設施保留地臨時建築使用管制規則","last_checked_at":"2026-10-06T17:26:42+08:00","last_success_at":"2026-10-06T17:26:42+08:00","verification_status":"fetched","content_hash":"2313d0c90ed511bc4dc6bf4a8a02e550f1582a6ac19eaff550e25b494d5afbf9","history":[{"observed_at":"2026-10-06T17:26:42+08:00","content_hash":"2313d0c90ed511bc4dc6bf4a8a02e550f1582a6ac19eaff550e25b494d5afbf9","change_kind":"initial","revision_date":"2005-02-03"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=2866&id=GL000020&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=579&id=GL000020&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"表一：公共設施變更為可建築用地應提供公共設施回饋標準表.PDF","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=193&id=FL088005&type=LAW"},{"name":"表二：土地使用分區間變更應提供公共設施回饋標準表.PDF","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=194&id=FL088005&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"一、彰化縣政府（以下簡稱本府）為因應都市土地利用之需求，促進土地\n有效之利用，在 兼顧社會公平正義之原則下，針對本縣都市計畫區\n內土地使用之變更審議，特訂定本原則。\n二、回饋方式\n公設用地變更為使用分區之公共設施回饋比例標準如表一，土地使用\n分區間之變更其公共設施回饋比例標準如表二。\n都市計畫委員會對變更回饋比例之調整得參酌各都市計畫區之都市機\n能、人口成長、公共設施劃設及開闢情形，依前表之標準做上下 5％\n內之調整。\n公共設施用地或不可建築用地於都市計畫發布實施前已為可建築用地\n者，經本縣都市計畫委員會審議得酌予降低回饋比例。\n圖表附件：\n表一：公共設施變更為可建築用地應提供公共設施回饋標準表.PDF\n表二：土地使用分區間變更應提供公共設施回饋標準表.PDF\n三、免回饋情形\n都市計畫變更符合下列情形之一者，得免回饋：\n（一）都市計畫公告實施之土地使用分區經都市計畫通盤檢討變更為公共\n設施用地，今再恢復變更為原使用分區者。\n（二）都市計畫辦理檢討、重製，原核定都市計畫、樁位成果與地籍分割\n資料不吻合而需調整變更，經本縣都市計畫委員會審議通過者。\n（三）其他特殊之情形經提本縣都委會審議通過者。\n四、回饋對象\n本規定之土地回饋及代金繳納對象為本府，繳收之代金得成立城鄉發\n展建設基金。\n前項基金之收支、保管及運用方式由本府另行訂定之。\n五、回饋時機\n應擬定細部計畫地區，須回饋之公共設施用地，應於該細部計畫公告\n發布實施後，建照核發前完成土地無償移轉登記予彰化縣，管理機關\n依相關法令規定辦理。\n無須擬定細部計畫，但應回饋之公共設施用地，應於該細部計畫公告\n發布實施後，建照核發前完成土地無償移轉登記予彰化縣，管理機關\n依相關法令規定辦理。\n得以採代金抵充應回饋之公共設施用地之地區，應於都市計畫核定前\n完成代金繳納。\n六、本回饋規定經本縣都市計畫委員會審議通過後實施，其他都市計畫法\n令另有規定者按其規定辦理。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL088005","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"修正日期":"民國 104 年 05 月 26 日","公發布日":"民國 99 年 11 月 12 日","法規名稱":"彰化縣都市計畫區土地變更回饋審議原則","法規體系":"建設類","發文字號":"字第號"},"promulgation_date":"2010-11-12","revision_date":"2015-05-26","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL088005","status":"unknown","title":"彰化縣都市計畫區土地變更回饋審議原則","last_checked_at":"2026-10-06T17:26:30+08:00","last_success_at":"2026-10-06T17:26:30+08:00","verification_status":"fetched","content_hash":"8410ae667f27ff7ca58feaa3a2473e700a8bae854636c027260a4650ae3d1708","history":[{"observed_at":"2026-10-06T17:26:30+08:00","content_hash":"8410ae667f27ff7ca58feaa3a2473e700a8bae854636c027260a4650ae3d1708","change_kind":"initial","revision_date":"2015-05-26"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=193&id=FL088005&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=194&id=FL088005&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"(精簡)彰化縣都市計畫區數值地形圖檔使用管理方法.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=2864&id=FL051637&type=LAW"},{"name":"(精簡)彰化縣都市計畫區數值地形圖檔使用管理方法.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=2865&id=FL051637&type=LAW"},{"name":"附件一-彰化縣都市計畫區數值地形圖檔使用申請表.odt","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=869&id=FL051637&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"第 1 條\n彰化縣政府（以下簡稱本府）為因應國土資訊發展，促進資訊交流共享，\n以發揮數值地形圖資料推廣利用效益，訂定本辦法。\n本辦法數值地形圖檔之收費標準依規費法第十條第一項規定訂定之。\n第 2 條\n本辦法之主管單位為本府建設處。\n依本辦法提供之數值地形圖檔，以本府自行產製者為限。\n第 3 條\n申請使用數值地形圖檔，應填具申請表，經本府核准後，通知申請人辦\n理繳費及領取數值地形圖檔資料事宜。申請表格式如附件一。\n機密圖檔之申請或刊載，另依國家機密保護法之規定辦理。\n第 4 條\n依本辦法申請之數值地形圖檔，僅提供申請者依申請書載明用途之使用，\n但經本府書面許可者不在此限。\n第 5 條\n申請數值地形圖檔之收費標準如下：\n一、每幅數值地形圖檔收費新臺幣三千元。\n二、申請者為政府機關、公營事業機構及學術機構，每幅數值地形圖檔收\n費新臺幣一千元。\n前項第二款規定之政府機構、公營事業機構及學術機構依平等互惠原則，\n提供價值相當之圖檔或專案成果予本府無償使用者，本府得無償提供使用\n。\n申請者為本府暨所屬機關、學校及本縣鄉（鎮、市）公所，本府得無償提\n供。\n依本辦法收取之費用，依法解入本縣縣庫。\n第 6 條\n本辦法自公布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL051637","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"全文檔案":"(精簡)彰化縣都市計畫區數值地形圖檔使用管理方法.pdf (精簡)彰化縣都市計畫區數值地形圖檔使用管理方法.pdf","公發布日":"民國 98 年 12 月 21 日","圖表附件":"附件一-彰化縣都市計畫區數值地形圖檔使用申請表.odt","法規名稱":"彰化縣都市計畫區數值地形圖檔使用管理辦法","法規體系":"建設類","發文字號":"府法制字第0980323067號"},"promulgation_date":"2009-12-21","revision_date":"2009-12-21","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL051637","status":"unknown","title":"彰化縣都市計畫區數值地形圖檔使用管理辦法","last_checked_at":"2026-10-06T17:26:41+08:00","last_success_at":"2026-10-06T17:26:41+08:00","verification_status":"fetched","content_hash":"9dbda8d098f970c77a813d88d0dc9c4d69c9f7bb77195025916bde6bd2a01bab","history":[{"observed_at":"2026-10-06T17:26:41+08:00","content_hash":"9dbda8d098f970c77a813d88d0dc9c4d69c9f7bb77195025916bde6bd2a01bab","change_kind":"initial","revision_date":"2009-12-21"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=2864&id=FL051637&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=2865&id=FL051637&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=869&id=FL051637&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"彰化縣都市計畫容積轉移審查許可及作業規則_removed_removed.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=2854&id=GL000019&type=LAW"},{"name":"表一_彰化縣都市計畫容積移轉審查許可申請書.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=748&id=GL000019&type=LAW"},{"name":"表二_送出基地所有權人及權利關係人同意書.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=749&id=GL000019&type=LAW"},{"name":"表三_彰化縣都市計畫容積移轉審查許可計算表.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=750&id=GL000019&type=LAW"},{"name":"表四_接受基地所有權人委託書.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=751&id=GL000019&type=LAW"},{"name":"表五_都市計畫容積移轉審查許可現地勘查表.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=752&id=GL000019&type=LAW"},{"name":"表六_彰化縣都市計畫容積移轉審查許可表.pdf","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=753&id=GL000019&type=LAW"},{"name":"彰化縣都市計畫容積移轉審查許可及作業規則流程圖.PDF","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=578&id=GL000019&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"第 1 條\n依據都市計畫容積移轉實施辦法（以下簡稱本辦法）第四條之規定，特訂\n定本規則。\n第 2 條\n本辦法第六條第一項第一款送出基地之認定基準及程序如下：\n一  都市計畫表明應予保存者，係指劃定為保存區、古蹟保存區、寺廟保\n存區之土地。\n二  經主管機關指定之古蹟，或登錄為歷史建築所定著之土地。\n依古蹟土地容積移轉辦法得申請容積移轉之土地，從其規定辦理，不得同\n時適用本辦法。\n第 3 條\n依本辦法第六條第一項第二款規定辦理之土地，應提經彰化縣（以下簡稱\n本縣）都市設計審議委員會審查認定之。\n第 4 條\n本辦法第六條第一項第三款之第一階段送出基地實施順序如下：\n一  鄰里性公共設施用地，其項目包括：\n（一）道路用地。\n（二）公園用地。\n（三）中小學用地。\n（四）兒童遊樂場用地。\n（五）公園兼兒童遊樂場用地。\n（六）體育場。\n（七）停車場。\n（八）綠地。\n（九）廣場。\n（十）市場用地。\n二  都市計畫書已有規定或配合本府政策經公告指定得為送出基地者。\n第二階段由彰化縣政府（以下簡稱本府）視實際辦理情形另行檢討之。\n第 5 條\n下列各款土地不得為接受基地：\n一  位於農業區、河川區、風景區及保護區等其他非都市發展用地。\n二  位於本規則第二條土地毗鄰之基地。但完整街廓基地情形特殊者，提\n經本縣都市設計審議委員會審查通過後，得酌予調整。\n三  實施容積率管制前已取得建造執照，且實際使用容積已超過現行基準\n容積之土地。\n四  依本縣都市計畫規定禁止容積移轉地區之土地。\n五  位於山坡地範圍之土地。\n六  依其他相關法令規定列為禁限建區域之土地。\n七  基地臨接寬度未達八公尺以上之道路者。\n第 6 條\n接受基地之可移入容積，不得超過該接受基地基準容積之百分之三十。\n位於整體開發地區、實施都市更新地區、面臨永久性空地或其他都市計畫\n指定地區範圍內之接受基地，其可移入容積不受前項之限制。但不得超過\n該接受基地基準容積之百分之四十。\n接受基地依本辦法申請移入容積數量，加計都市更新條例、都市計畫或其\n他法規規定給予之總獎勵容積，不得超過其基準容積百分之一百。\n第 7 條\n接受基地得以折繳代金方式移入容積。\n前項折繳代金由本府委託三家以上專業估價者查估後由本府評定之；必要\n時，查估工作得由本府辦理，其所需費用，由接受基地所有權人負擔或公\n有土地地上權人負擔。\n第一項代金之用途，應專款專用於取得與接受基地同一主要計畫區之本辦\n法第六條第一項第三款土地為限。\n第 8 條\n送出基地之容積移轉與接受基地建造執照應同時提出申請，並應送請本縣\n都市設計審議委員會審查。\n前項辦理移轉之時程，不計入請領建造執照之辦理時限。\n第 9 條\n申請容積移轉案件，應檢齊後附書表及文件一式二份，向本府提出申請：\n一  彰化縣都市計畫容積移轉審查許可申請書（表一）。\n二  送出基地所有權人及權利關係人同意書（表二）。\n三  彰化縣都市計畫容積移轉審查許可計算表（表三）。\n四  受基地所有權人委託書（表四）。\n五  送出基地所有權人及接受基地所有權人身分證明文件影本。\n六  送出基地及接受基地之地籍圖謄本及土地登記謄本。\n七  送出基地土地使用分區證明書。\n八  接受基地之建築線指示（定）圖及都市計畫位置圖。\n九  都市計畫容積移轉審查許可現地勘查表（表五）。\n十  彰化縣都市計畫容積移轉審查許可表（表六）。\n十一  其它證明文件。\n以繳納代金辦理容積移轉得免檢附前項第二款、第五款至第七款及第九款\n文件。\n本府得依實際作業需求，修改或調整前項各書表、文件之格式內容。\n第 10 條\n容積移轉審查許可作業規則流程詳如附圖。\n圖表附件：\n彰化縣都市計畫容積移轉審查許可及作業規則流程圖.PDF\n第 11 條\n本規則自發布日施行。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:GL000019","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"修正日期":"民國 107 年 11 月 06 日","全文檔案":"彰化縣都市計畫容積轉移審查許可及作業規則_removed_removed.pdf","公發布日":"民國 104 年 08 月 14 日","圖表附件":"表一_彰化縣都市計畫容積移轉審查許可申請書.pdf 表二_送出基地所有權人及權利關係人同意書.pdf 表三_彰化縣都市計畫容積移轉審查許可計算表.pdf 表四_接受基地所有權人委託書.pdf 表五_都市計畫容積移轉審查許可現地勘查表.pdf 表六_彰化縣都市計畫容積移轉審查許可表.pdf","法規名稱":"彰化縣都市計畫容積移轉審查許可及作業規則","法規體系":"建設類","發文字號":"府法制字第1070385707號"},"promulgation_date":"2015-08-14","revision_date":"2018-11-06","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=GL000019","status":"unknown","title":"彰化縣都市計畫容積移轉審查許可及作業規則","last_checked_at":"2026-10-06T17:26:39+08:00","last_success_at":"2026-10-06T17:26:39+08:00","verification_status":"fetched","content_hash":"1b962e3776f2ab982bd28971aec1ed4befcf7e00ad6e9dad71f4511d51bf82d4","history":[{"observed_at":"2026-10-06T17:26:39+08:00","content_hash":"1b962e3776f2ab982bd28971aec1ed4befcf7e00ad6e9dad71f4511d51bf82d4","change_kind":"initial","revision_date":"2018-11-06"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=2854&id=GL000019&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=748&id=GL000019&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=749&id=GL000019&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=750&id=GL000019&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=751&id=GL000019&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=752&id=GL000019&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=753&id=GL000019&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=578&id=GL000019&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[{"name":"附表一：都市計畫工業區檢討變更使用申請表.PDF","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=158&id=FL087991&type=LAW"},{"name":"附表二：土地使用變更同意書.PDF","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=159&id=FL087991&type=LAW"},{"name":"附表三：彰化縣申請都市計畫工業區檢討變更使用審核摘要表.PDF","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=160&id=FL087991&type=LAW"},{"name":"附表三：彰化縣申請都市計畫工業區檢討變更使用審核摘要表.PDF","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=161&id=FL087991&type=LAW"},{"name":"附圖一：申請都市計畫工業區檢討變更使用辦理程序示意圖.PDF","url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=162&id=FL087991&type=LAW"}],"authority":"彰化縣政府","category":"建築管理相關","content":"一、彰化縣政府為審核依都市計畫法第二十六條、第二十七條第一項第三\n款、第四款及都市計畫定期通盤檢討實施辦法、都市計畫工業區檢討\n變更審議規範等規定之都市計畫工業區檢討變更使用申請個案，特訂\n定「彰化縣都市計畫工業區檢討變更使用申請個案變更作業程序」。\n二、申請者應檢具變更計畫申請書十份，其內容需包括下列各項：\n（一）都市計畫工業區檢討變更使用申請表。（如附表一）\n（二）都市計畫工業區檢討變更使用土地清冊。\n（三）土地變更範圍之地籍圖及土地登記謄本。（正本一份；且為三個月\n內核發）\n（四）都市計畫土地使用分區證明書。（正本一份；且為八個月內核發）\n（五）土地變更範圍之全部地籍套繪都市計畫圖。\n（六）土地使用變更同意書。（如附表二）\n（七）都市計畫變更內容概要，其內容至少包括：\n1.變更位置及範圍。\n2.土地使用現況。\n3.變更理由。\n4.變更內容。\n5.整體開發計畫及財務計畫內容概要。（如附表三）\n（八）環境現況調查資料（其內容至少需包括環境地質、土壤及地下水污\n染評估調查資料，且需專業技師簽證）。\n（九）工廠登記證明文件。\n（十）工廠清冊。（單一工廠者免附）\n（十一）申請範圍內工廠搬遷意願書。\n已完成遷廠、停止生產或未開發之工業區，無須檢附第九款至十一款\n文件。\n圖表附件：\n附表一：都市計畫工業區檢討變更使用申請表.PDF\n附表二：土地使用變更同意書.PDF\n附表三：彰化縣申請都市計畫工業區檢討變更使用審核摘要表.PDF\n三、其他都市計畫法令另有規定者，按其規定辦理。\n四、申請都市計畫工業區檢討變更使用審核摘要表（如附表三）。\n圖表附件：\n附表三：彰化縣申請都市計畫工業區檢討變更使用審核摘要表.PDF\n五、申請都市計畫工業區檢討變更使用審核流程圖（如附圖一）。\n圖表附件：\n附圖一：申請都市計畫工業區檢討變更使用辦理程序示意圖.PDF","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL087991","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"公發布日":"民國 103 年 03 月 06 日","法規名稱":"彰化縣都市計畫工業區檢討變更使用申請個案變更作業程序","法規體系":"建設類","發文字號":"字第號"},"promulgation_date":"2014-03-06","revision_date":"2014-03-06","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL087991","status":"unknown","title":"彰化縣都市計畫工業區檢討變更使用申請個案變更作業程序","last_checked_at":"2026-10-06T17:26:31+08:00","last_success_at":"2026-10-06T17:26:31+08:00","verification_status":"fetched","content_hash":"2b7fb4fc1d778d69f5ba2e789f32c3151c8a9a715070e82d35fd191afbfa0299","history":[{"observed_at":"2026-10-06T17:26:31+08:00","content_hash":"2b7fb4fc1d778d69f5ba2e789f32c3151c8a9a715070e82d35fd191afbfa0299","change_kind":"initial","revision_date":"2014-03-06"}],"version_count":1,"attachment_hashes":{"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=158&id=FL087991&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=159&id=FL087991&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=160&id=FL087991&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=161&id=FL087991&type=LAW":null,"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/Download.ashx?FileID=162&id=FL087991&type=LAW":null}},{"articles":[],"attachment_required":false,"attachments":[],"authority":"彰化縣政府","category":"建築管理相關","content":"一、為提升都市機能及環境品質，並促進整體發展，變更範圍應不得小於\n一個街廓；若變更範圍非屬完整街廓者，得以整體規劃並經各級都市\n計畫委員會審議通過後，納入計畫書內作為同街廓內後續變更審議之\n參考。\n二、工業區變更案件以捐贈公共設施用地及可建築土地為原則。但捐贈之\n可建築土地，經都市計畫委員會同意後，得改以捐獻代金方式折算繳\n納，其代金須優先回饋當地之公共建設。\n三、捐獻代金之數額，由彰化縣政府委託三家以上專業估價者查估後，依\n下列公式計算之，並得以分期方式繳納；其所需費用，由申請人負擔\n。但其捐獻數額不得低於工業區變更後第一次公告土地現值之一點四\n倍。\n捐獻代金之數額＝三家以上專業估價者查估變更後全部可建築土地之\n價格（取最高價計算）×變更後應捐贈可建築土地面積÷變更後全部\n可建築土地面積。\n四、工業區變更後容積率，應依下列公式計算，且不得大於鄰近使用性質\n相同使用分區之容積率。\n工業區變更後容積率＝變更前工業區容積率×變更前工業區面積／（\n變更前工業區面積－變更後公共設施用地面積）\n五、工業區變更後獎勵容積、移入容積及其他名目容積之合計，不得大於\n基準容積（變更後可建築土地面積乘以前項工業區變更後容積率）之\n零點五倍。但相關法令另有規定者，不在此限。\n六、工業區變更應捐贈公共設施用地及可建築土地之比例，未達「都市計\n畫工業區檢討變更審議規範」第六點第一款第一目規定者，非有特殊\n理由，其基準容積應予降低。\n七、變更範圍內應自行留設之公共設施用地，應優先考量補充該主要計畫\n區內不足之公共設施用地，納入變更主要計畫書內，並依「彰化縣都\n市計畫區土地變更回饋審議原則」辦理。\n八、申請人須訂定具體之開發計畫，並敘明都市計畫發布實施後三年內必\n需予以開發建設，否則依都市計畫法定程序申請展期或回復為工業區\n，且納入變更主要計畫書內規定，以為執行依據。","coverage_note":"已擷取官方正文；附件保存官方連結，未宣稱附件全文已索引。","effective_date":null,"effective_note":"","id":"changhua:FL087990","jurisdiction":"彰化縣","metadata_only":false,"official_fields":{"公發布日":"民國 100 年 10 月 04 日","法規名稱":"彰化縣都市計畫工業區變更審議原則","法規體系":"建設類","發文字號":"字第號"},"promulgation_date":"2011-10-04","revision_date":"2011-10-04","source_id":"changhua","source_updated_at":null,"source_url":"https://lawsearch.chcg.gov.tw/GLRSNEWSOUT/LawContent.aspx?id=FL087990","status":"unknown","title":"彰化縣都市計畫工業區變更審議原則","last_checked_at":"2026-10-06T17:26:31+08:00","last_success_at":"2026-10-06T17:26:31+08:00","verification_status":"fetched","content_hash":"fe36ea5096e27dfb8be9ae354077ebf41665f8275e1dfd9fca63a646498ee2a6","history":[{"observed_at":"2026-10-06T17:26:31+08:00","content_hash":"fe36ea5096e27dfb8be9ae354077ebf41665f8275e1dfd9fca63a646498ee2a6","change_kind":"initial","revision_date":"2011-10-04"}],"version_count":1,"attachment_hashes":{}}]);
